!   ..common blocks
!-----------------------------------------------------------------------
!.documentation
!
!  1. purpose
!
!     B2STBC_PHYS provides linearised expressions for the sources of
!     density, parallel momentum, electron heat, atom heat, and charge,
!     due to the boundary conditions.
!     Here the boundary conditions are expressed by use of the old B2
!     namelist format.
!
!-----------------------------------------------------------------------
!.declarations
!
!   ..local variables
  INTEGER :: icv1, ifc, is, ib, ibc, k
!Solovyev 23.05.14 !srv 29.09.15 }
  INTEGER, SAVE :: bcpot_16_step=50
  INTEGER, SAVE :: bccon_flux_fb_style=0
!srv 19.04.13
  INTEGER, SAVE :: bcene_15_style=1
!srv 19.04.13
  INTEGER, SAVE :: bceni_15_style=0
!srv 19.04.13
  INTEGER, SAVE :: bcpot_12_style=0
  INTEGER, SAVE :: bcenk_17_style=0
  INTEGER, SAVE :: bc_type16_kinetic_energy=0
!srv 16.02.12 12.02.15 29.09.15
  LOGICAL :: once_bccon(0:ns-1), once_bcene, once_bceni, once_bcpot
  REAL(kind=r8) :: naua2sum(0:ns-1), naua2average(0:ns-1), pzaverage, &
& pzsum, volsum, vbc(ncv, 0:ns-1), csbc(ncv, 0:ns-1)
  REAL(kind=r8) :: naua2sumd0(nbdirsmax0, 0:ns-1), naua2averaged0(&
& nbdirsmax0, 0:ns-1), pzaveraged0(nbdirsmax0), pzsumd0(nbdirsmax0), &
& vbcd0(nbdirsmax0, ncv, 0:ns-1), csbcd0(nbdirsmax0, ncv, 0:ns-1)
  REAL(kind=r8) :: naua2sumd(nbdirsmax, 0:ns-1), naua2averaged(nbdirsmax&
& , 0:ns-1), pzaveraged(nbdirsmax), pzsumd(nbdirsmax), vbcd(nbdirsmax, &
& ncv, 0:ns-1), csbcd(nbdirsmax, ncv, 0:ns-1)
  REAL(kind=r8) :: naua2sumdd(nbdirsmax0, nbdirsmax, 0:ns-1), &
& naua2averagedd(nbdirsmax0, nbdirsmax, 0:ns-1), pzaveragedd(nbdirsmax0&
& , nbdirsmax), pzsumdd(nbdirsmax0, nbdirsmax), vbcdd(nbdirsmax0, &
& nbdirsmax, ncv, 0:ns-1), csbcdd(nbdirsmax0, nbdirsmax, ncv, 0:ns-1)
!lk 20.11.07
  REAL(kind=r8) :: bzsum, bzaverage
!sxhz(-1:nx,-1:ny),                                    !srv 24.08.08
  REAL(kind=r8) :: wdia(ncv), wrk0(ncv), wrkf(nfc), pz(ncv), gonedbsq(&
& nfc, 0:1), sna0_no_mdf(ncv, 0:1, 0:ns-1)
  REAL(kind=r8) :: wrkfd(nbdirsmax0, nfc), pzd0(nbdirsmax0, ncv), &
& sna0_no_mdfd0(nbdirsmax0, ncv, 0:1, 0:ns-1)
  REAL(kind=r8) :: pzd(nbdirsmax, ncv), sna0_no_mdfd(nbdirsmax, ncv, 0:1&
& , 0:ns-1)
  REAL(kind=r8) :: pzdd(nbdirsmax0, nbdirsmax, ncv), sna0_no_mdfdd(&
& nbdirsmax0, nbdirsmax, ncv, 0:1, 0:ns-1)
!srv 23.09.08
  REAL(kind=r8), SAVE :: cor9=0.0_R8
  REAL(kind=r8) :: fac_he_anom, fac_he_anom_bc
!srv 11.07.05
  CHARACTER :: chns*3, chk*1
!srv 01.02.09
  REAL(kind=r8) :: rz(ncv)
  REAL(kind=r8) :: rzd0(nbdirsmax0, ncv)
  REAL(kind=r8) :: rzd(nbdirsmax, ncv)
  REAL(kind=r8) :: rzdd(nbdirsmax0, nbdirsmax, ncv)
  CHARACTER(len=26) :: boundary_location(nbcd)
!   ..procedures
  INTRINSIC ABS, SQRT
  EXTERNAL IPGETR, B2XVSG, B2XVPS_NODIFF_NODIFF, INTFACE_S
!srv 24.08.08
  REAL(kind=r8) :: sy, INTFACE_S
  EXTERNAL XERTST, IPGETI, ESEEC0_NODIFF_NODIFF
  INTRINSIC MINVAL
  EXTERNAL XERRAB
  REAL(r8) :: result1
  REAL(r8) :: result2
  INTEGER :: arg1
  REAL(kind=r8) :: arg10
  CHARACTER(len=15) :: arg11
  INTEGER :: nd
  REAL(r8) :: temp
  REAL(r8), DIMENSION(nbdirsmax0) :: tempd
  INTEGER :: nbdirs
  INTRINSIC MAXVAL
  INTEGER :: nd0
  REAL(r8) :: temp0
  INTEGER :: nbdirs0
!   ..initialisation
!-----------------------------------------------------------------------
!.computation
!
! ..preliminaries
!   ..subprogram start-up calls
  CALL SUBINI('b2stbc_phys')
!   ..set internal parameters on first call
  IF (ncall_b2stbc_phys .EQ. 0) THEN
    CALL IPGETI('b2stbc_bccon_flux_fb_style', bccon_flux_fb_style)
    CALL IPGETI('b2stbc_bcene_15_style', bcene_15_style)
    CALL IPGETI('b2stbc_bceni_15_style', bceni_15_style)
    CALL IPGETI('b2stbc_bcpot_12_style', bcpot_12_style)
    CALL IPGETI('b2stbc_bcenk_17_style', bcenk_17_style)
! The following switches are only used in 'WG-TODO' blocks, i.e. not yet converted to wide grid functionality
!       call ipgeti ('b2tfhe_conduction_only', conduction_only)
!       call ipgeti ('b2stbc_iform_corr_dia', iform_corr_dia)        !srv 25.07.05
!       call ipgeti ('b2stbc_coreregno', coreregno)
!       call xertst (cbirso.le.coreregno.and.
!     1   coreregno.le.cbirso+cbnrso-1,
!     2   'faulty internal parameter coreregno')
!       if (nncut.ge.2) then
!         call ipgeti ('b2stbc_coreregn2', coreregn2)
!         call xertst (cbirso.le.coreregn2.and.
!     1     coreregn2.le.cbirso+cbnrso-1,
!     2     'faulty internal parameter coreregn2')
!       endif
!       call ipgeti ('b2tfhe_no_hybr', no_hybr_e)
!       call ipgeti ('b2tfhi_no_hybr', no_hybr_i)
!       call ipgeti ('b2stbc_type16_ref', bc_type16_ref)
!       call ipgeti ('b2stbc_type20_ref', bc_type20_ref)
!       call ipgeti ('b2stbc_type21_ref', bc_type21_ref)
!       call ipgeti ('b2stbc_fix_fch_in_fhe_sheath',
!     1  fix_fch_in_fhe_sheath)
!       call ipgeti ('b2stbc_fix_sx_in_fhe_sheath',
!     1  fix_sx_in_fhe_sheath)                                       !srv 08.05.09
!       call ipgeti ('b2stbc_istyle_fchi', istyle_fchi)              !srv 14.02.05
!       call ipgeti ('b2stbc_bcpot_16_step', bcpot_16_step)          !Solovyev 23.05.14 !srv 29.09.15
!       call ipgeti ('b2stbc_type16_kinetic_energy',
!     1  bc_type16_kinetic_energy)
!       call ipgeti ('b2stbc_average_pr', istyle_average_pr)         !srv 08.08.02
  END IF
!   ..test nCv, nFc, ns
  CALL XERTST(0 .LT. ncv .AND. 0 .LT. nfc, 'faulty argument nCv, nFc')
  CALL XERTST(1 .LE. ns, 'faulty argument ns')
  CALL XERTST(0 .LE. ismain .AND. ismain .LT. ns, &
&       'invalid main plasma species index ismain')
  CALL XERTST(.NOT.is_neutral(ismain), &
&       'invalid main plasma species ismain; must not be neutral')
  CALL XERTST(0 .LE. ismain0 .AND. ismain0 .LT. ns, &
&       'invalid main neutral species index ismain0')
  CALL XERTST(is_neutral(ismain0) .OR. ismain .EQ. ismain0, &
&       'invalid main neutral species ismain0; must be neutral')
!   ..test facdrift (not on first call)                              !xpb
!xpb
  IF (ncall_b2stbc_phys .GT. 0) THEN
    result1 = MINVAL(dv%facdrift)
    result2 = MAXVAL(dv%facdrift)
    CALL XERTST(0.0_R8 .LE. result1 .AND. 1.0_R8 .GE. result2, &
&         'faulty argument facdrift')
  END IF
!   ..extensive tests on first few calls
  IF (ncall_b2stbc_phys .LT. 3) THEN
!    ..test sign of vol
    CALL B2XVSG(ncv, geo%cvvol, 1, 'vol', '.gt.')
    arg1 = nfc*2
    CALL B2XVSG(arg1, geo%fcvol, 1, 'vol', '.gt.')
!    ..test state
    CALL B2XVPS_NODIFF_NODIFF(ncv, nfc, ns, pl, dv)
    DO nd0=1,nbdirs0
!    ..test sign of chce, chci
      wrkfd(nd0, :) = 0.D0
      wrkfd(nd0, :) = 0.D0
      wrkfd(nd0, :) = 0.D0
      wrkfd(nd0, :) = 0.D0
    END DO
    wrkf(:) = co%chce(:, 0)*geo%fcqalf(:, 0)
    CALL B2XVSG(nfc, wrkf, 1, 'chce0', '.ge.')
    wrkf(:) = co%chce(:, 1)*geo%fcqalf(:, 1)
    CALL B2XVSG(nfc, wrkf, 1, 'chce1', '.ge.')
    wrkf(:) = co%chci(:, 0)*geo%fcqalf(:, 0)
    CALL B2XVSG(nfc, wrkf, 1, 'chci0', '.ge.')
    wrkf(:) = co%chci(:, 1)*geo%fcqalf(:, 1)
    CALL B2XVSG(nfc, wrkf, 1, 'chci1', '.ge.')
  END IF
!   ..set cutll, cutlo
  IF (.NOT.b2mod_math_initialised) CALL B2MOD_MATH_INIT()
!
!  -- INITIALISE CERTAIN CONSTANTS --
  epslon = 1.e-10_R8
!  -- SET NE00, UP00, UBIG, VBIG --
  ne00 = 1.0e20_R8
  arg10 = 100*ev/mp
  up00 = SQRT(arg10)
  ubig = up00/epslon
  vbig = 1.0e-2_R8*ubig
  pbig = up00
!
  sna0_no_mdf = 0.0_R8
!
  cor9 = switch%b2stbc_cor9
!
  IF (switch%keps_anom_he_model .EQ. 0) THEN
! Default model. Apply factor 5/2 for anomalous terms in heat equations
! Default model. No correction for imposed heat fluxes at boundaries
    fac_he_anom = 2.5_R8
    fac_he_anom_bc = 1.0_R8
  ELSE IF (switch%keps_anom_he_model .EQ. 1) THEN
! keps model. Apply factor 3/2 for anomalous terms in heat equations
! Assume physical heat flux with factor 3/2.
! No correction for imposed heat fluxes at boundaries.
    fac_he_anom = 1.5_R8
    fac_he_anom_bc = 1.0_R8
  ELSE IF (switch%keps_anom_he_model .EQ. 2) THEN
! keps model. Apply factor 3/2 for anomalous terms in heat equations
! Assume physical heat flux is still with factor 5/2.
! Correct imposed heat fluxes at boundaries.
    fac_he_anom = 1.5_R8
    fac_he_anom_bc = 3.0_R8/5.0_R8
  END IF
!
!srv 18.01.02
  pzd = 0.d0
  pzd0 = 0.D0
  pzdd = 0.D0
  CALL B2XPPZ_DV_DV(ncv, ns, dv%ne, dvd0%ne, dvd%ne, dvdd%ne, pl%na, &
&             pld0%na, pld%na, pldd%na, pl%te, pld0%te, pld%te, pldd%te&
&             , pl%ti, pld0%ti, pld%ti, pldd%ti, pz, pzd0, pzd, pzdd, &
&             st_ext, nbdirs, nbdirs0)
!
!   ..pre-compute some quantities for core BCs with drifts
  CALL GRAD_NODIFF_NODIFF(ncv, nfc, nvx, 1, geo, mpg, geo%cvonedbsq, geo&
&                   %vxonedbsq, gonedbsq)
  pzsum = 0.0_R8
  naua2sum = 0.0_R8
  volsum = 0.0_R8
  bzsum = 0.0_R8
  pzsumd = 0.d0
  naua2sumd = 0.d0
  pzsumd0 = 0.D0
  pzsumdd = 0.D0
  naua2sumd0 = 0.D0
  naua2sumdd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
  DO ib=1,nbc
    icv1 = mpg%bccv(mpg%bccvp(ib, 1), 1)
    IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
!      ..accumulate the average pressure for inner flux surface
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            pzsumdd(nd0, nd) = pzsumdd(nd0, nd) + geo%fcs(ifc)*pzdd(nd0&
&             , nd, icv1)
          END DO
          pzsumd(nd) = pzsumd(nd) + geo%fcs(ifc)*pzd(nd, icv1)
        END DO
        DO nd0=1,nbdirs0
          pzsumd0(nd0) = pzsumd0(nd0) + geo%fcs(ifc)*pzd0(nd0, icv1)
        END DO
        pzsum = pzsum + geo%fcs(ifc)*pz(icv1)
        volsum = volsum + geo%fcs(ifc)
!      ..accumulate the average na*ua**2, na for inner flux surface
        DO is=0,ns-1
          DO nd0=1,nbdirs0
            tempd(nd0) = pld0%ua(nd0, icv1, is)
          END DO
          temp = pl%ua(icv1, is)
          DO nd=1,nbdirs
            temp0 = 2*pl%na(icv1, is)
            DO nd0=1,nbdirs0
              naua2sumdd(nd0, nd, is) = naua2sumdd(nd0, nd, is) + geo%&
&               fcs(ifc)*(pld%na(nd, icv1, is)*2*temp*tempd(nd0)+temp**2&
&               *pldd%na(nd0, nd, icv1, is)+pld%ua(nd, icv1, is)*(temp*2&
&               *pld0%na(nd0, icv1, is)+temp0*tempd(nd0))+temp0*temp*&
&               pldd%ua(nd0, nd, icv1, is))
            END DO
            naua2sumd(nd, is) = naua2sumd(nd, is) + geo%fcs(ifc)*(temp*&
&             temp*pld%na(nd, icv1, is)+temp0*temp*pld%ua(nd, icv1, is))
          END DO
          DO nd0=1,nbdirs0
            naua2sumd0(nd0, is) = naua2sumd0(nd0, is) + geo%fcs(ifc)*(&
&             temp**2*pld0%na(nd0, icv1, is)+pl%na(icv1, is)*2*temp*&
&             tempd(nd0))
          END DO
          naua2sum(is) = naua2sum(is) + geo%fcs(ifc)*(pl%na(icv1, is)*(&
&           temp*temp))
        END DO
!      ..accumulate the average fcBb(:,2) for inner flux surface
        bzsum = bzsum + geo%fcs(ifc)*geo%fcbb(ifc, 2)
      END DO
    END IF
  END DO
  IF (volsum .GT. 0.0_R8) THEN
    naua2averagedd = 0.D0
    pzaveragedd = 0.D0
    DO nd=1,nbdirs
      DO nd0=nd,nbdirs0
        pzaveragedd(nd0, nd) = pzsumdd(nd0, nd)/volsum
        naua2averagedd(nd0, nd, :) = naua2sumdd(nd0, nd, :)/volsum
      END DO
      pzaveraged(nd) = pzsumd(nd)/volsum
      naua2averaged(nd, :) = naua2sumd(nd, :)/volsum
    END DO
    DO nd0=1,nbdirs0
      pzaveraged0(nd0) = pzsumd0(nd0)/volsum
      naua2averaged0(nd0, :) = naua2sumd0(nd0, :)/volsum
    END DO
    pzaverage = pzsum/volsum
    naua2average = naua2sum/volsum
    bzaverage = bzsum/volsum
  ELSE
    naua2averaged = 0.d0
    pzaveraged = 0.d0
    naua2averagedd = 0.D0
    pzaveragedd = 0.D0
    naua2averaged0 = 0.D0
    pzaveraged0 = 0.D0
  END IF
!
!wdk  ro and pr based on charged particles only!
!wdk  no neutral contribution to sound speed definition
!srv 01.02.09
  rzd = 0.d0
  rzd0 = 0.D0
  rzdd = 0.D0
  CALL B2XPRZ_DV_DV(ncv, ns, mp, am, pl%na, pld0%na, pld%na, pldd%na, rz&
&             , rzd0, rzd, rzdd, st_ext, nbdirs, nbdirs0)
!      call b2xppz (nCv, ns, dv%ne, pl%na, pl%te, pl%ti, pz, st_ext)
  wdia = (dv%ne*pl%te+dv%ni(:, 1)*pl%ti)*geo%cvbb(:, 2)
  DO is=0,st_ext%ns-1
    IF (.NOT.st_ext%is_neutral(is)) wdia = wdia + st_ext%na(:, is)*&
&       st_ext%ta(:, is)*geo%cvbb(:, 2)
  END DO
  IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, *) 'Doing B2-style bc'
!
!srv 16.02.12 {
  once_bccon = .false.
  once_bcene = .false.
!srv 16.02.12 }
  once_bceni = .false.
!Solovyev 13.05.14 !srv 29.09.15
  once_bcpot = .false.
! -- Prepare boundary_location array in advance                       !srv 05.08.22 {
  DO ib=1,nbc
    IF (bcpos(ib) .EQ. -2) THEN
      WRITE(boundary_location(ib), '(a23,i2)') ' on boundary cell list '&
&     , ib
    ELSE
      WRITE(boundary_location(ib), '(a4,i4,a6,i4,a4,i4)') ' at ', bcpos(&
&     ib), ' from ', bcstart(ib), ' to ', bcend(ib)
    END IF
!srv 05.08.22 }

  END DO
  vbcd = 0.d0
  sna0_no_mdfd = 0.d0
  csbcd = 0.d0
  vbcd0 = 0.D0
  sna0_no_mdfdd = 0.D0
  sna0_no_mdfd0 = 0.D0
  csbcd0 = 0.D0
  vbcdd = 0.D0
  csbcdd = 0.D0
!
! -- LOOP OVER ALL BOUNDARIES
  DO ib=1,nbc
!srv 15.02.26 }
!
    SELECT CASE  (bc_for_equations) 
    CASE ('all') 
!srv 15.02.26 {
      CALL B2STBC_PHYS_SPECIES_DV_DV(ib, nbdirs, nbdirs0)
      CALL B2STBC_PHYS_ENE_DV_DV(ib, nbdirs, nbdirs0)
      CALL B2STBC_PHYS_ENI_DV_DV(ib, nbdirs, nbdirs0)
      CALL B2STBC_PHYS_POT_DV_DV(ib, nbdirs, nbdirs0)
      CALL B2STBC_PHYS_ENK_DV_DV(ib, nbdirs, nbdirs0)
      CALL B2STBC_PHYS_ENZ_DV_DV(ib, nbdirs, nbdirs0)
    CASE ('spc') 
      CALL B2STBC_PHYS_SPECIES_DV_DV(ib, nbdirs, nbdirs0)
    CASE ('ene') 
      CALL B2STBC_PHYS_ENE_DV_DV(ib, nbdirs, nbdirs0)
    CASE ('eni') 
      CALL B2STBC_PHYS_ENI_DV_DV(ib, nbdirs, nbdirs0)
    CASE ('pot') 
      CALL B2STBC_PHYS_POT_DV_DV(ib, nbdirs, nbdirs0)
    CASE ('enk') 
      CALL B2STBC_PHYS_ENK_DV_DV(ib, nbdirs, nbdirs0)
    CASE ('enz') 
      CALL B2STBC_PHYS_ENZ_DV_DV(ib, nbdirs, nbdirs0)
    CASE DEFAULT
      CALL XERRAB('B2STBC -- incorrect value of bc_for_equations')
    END SELECT
!

  END DO
!
! -- Moving core tally according to B.C.
! -- Must be done only once!
!
!
  IF (switch%b2npmo_iout .EQ. 1 .OR. switch%iout_b2wdat .EQ. 4) THEN
!srv 11.09.09 {
    DO is=0,ns-1
      WRITE(chns, '(i3.3)') is
      wrk0 = srw%smo0(:, 0, is) + srw%smo0(:, 1, is)*pl%ua(:, is) + srw%&
&       smo0(:, 2, is)*pl%na(:, is)*mp*am(is) + srw%smo0(:, 3, is)*pl%ua&
&       (:, is)*pl%na(:, is)*mp*am(is)
      arg11 = 'b2stbc_phys_smo'//chns
      CALL MY_OUT_US(70, ncv, 0, wrk0, arg11)
    END DO
  END IF
  IF (switch%b2npco_iout .EQ. 1 .OR. switch%iout_b2wdat .EQ. 4) THEN
    DO is=0,ns-1
      WRITE(chns, '(i3.3)') is
      wrk0 = srw%sna0(:, 0, is) + srw%sna0(:, 1, is)*pl%na(:, is)
      arg11 = 'b2stbc_phys_sna'//chns
      CALL MY_OUT_US(70, ncv, 0, wrk0, arg11)
    END DO
  END IF
  IF (switch%b2npht_iout .EQ. 1 .OR. switch%iout_b2wdat .EQ. 4) THEN
    wrk0 = srw%she0(:, 0) + srw%she0(:, 1)*pl%te + srw%she0(:, 2)*dv%ne &
&     + srw%she0(:, 3)*pl%te*dv%ne
    CALL MY_OUT_US(70, ncv, 0, wrk0, 'b2stbc_phys_she')
    wrk0 = srw%shi0(:, 0) + srw%shi0(:, 1)*pl%ti + srw%shi0(:, 2)*dv%ni(&
&     :, 0) + srw%shi0(:, 3)*pl%ti*dv%ni(:, 0)
    CALL MY_OUT_US(70, ncv, 0, wrk0, 'b2stbc_phys_shi')
  END IF
  IF ((switch%b2npp7_iout .EQ. 1 .OR. switch%b2nppo_iout .EQ. 1) .OR. &
&     switch%iout_b2wdat .EQ. 4) THEN
    wrk0 = srw%sch0(:, 0) + srw%sch0(:, 1)*pl%po + srw%sch0(:, 2)*dv%ne &
&     + srw%sch0(:, 3)*pl%po*dv%ne
    CALL MY_OUT_US(70, ncv, 0, wrk0, 'b2stbc_phys_sch')
  END IF
!srv 11.09.09 }
!
  IF (switch%b2stbc_iout .EQ. 1) THEN
    DO is=0,ns-1
      WRITE(chns, '(i3.3)') is
      DO k=0,3
        WRITE(chk, '(i1)') k
        arg11 = 'b2stbc_phys_smo'//chk//chns
        CALL MY_OUT_US(70, ncv, 0, srw%smo0(1, k, is), arg11)
      END DO
      DO k=0,1
        WRITE(chk, '(i1)') k
        arg11 = 'b2stbc_phys_sna'//chk//chns
        CALL MY_OUT_US(70, ncv, 0, srw%sna0(1, k, is), arg11)
      END DO
    END DO
    DO k=0,3
      WRITE(chk, '(i1)') k
      arg11 = 'b2stbc_phys_sch'//chk
      CALL MY_OUT_US(70, ncv, 0, srw%sch0(1, k), arg11)
      arg11 = 'b2stbc_phys_she'//chk
      CALL MY_OUT_US(70, ncv, 0, srw%she0(1, k), arg11)
      arg11 = 'b2stbc_phys_shi'//chk
      CALL MY_OUT_US(70, ncv, 0, srw%shi0(1, k), arg11)
    END DO
  END IF
!
! ..return
  IF (ncall_b2stbc_phys .EQ. 0 .OR. main_call) ncall_b2stbc_phys = &
&     ncall_b2stbc_phys + 1
  CALL SUBEND()
  RETURN
!
!-----------------------------------------------------------------------
!.end b2stbc_phys
!

CONTAINS
!  Differentiation of csbc_is_dv in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: csbc csbcd csd cs
!   with respect to varying inputs: *(rtd.rza) *(rt.rza) *(pld.te)
!                *(pld.ti) *(pl.te) *(pl.ti) pzd rzd rz csbc csbcd
!                pz csd
!   Plus diff mem management of: rtd.rza:in rt.rza:in pld.te:in
!                pld.ti:in pl.te:in pl.ti:in
!  Differentiation of csbc_is in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: csbc cs
!   with respect to varying inputs: *(rt.rza) *(pl.te) *(pl.ti)
!                rz csbc pz
!   Plus diff mem management of: rt.rza:in pl.te:in pl.ti:in
!
!srv 15.02.26 {
  SUBROUTINE CSBC_IS_DV_DV(icv1, ib, is, cs, csd0, csd, csdd, nbdirs, &
&   nbdirs0)
    USE B2MOD_DIFFSIZES
!  Hint: nbdirsmax0 should be the maximum number of differentiation directions
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: icv1, ib, is
    REAL(kind=r8) :: cs
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: csd0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: csdd
    INTRINSIC SQRT
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: arg12d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg12dd
    REAL(r8) :: arg13
    REAL(r8), DIMENSION(nbdirsmax0) :: arg13d0
    REAL(r8), DIMENSION(nbdirsmax) :: arg13d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg13dd
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: tempd
    REAL(r8) :: temp0
    REAL(r8), DIMENSION(nbdirsmax0) :: temp0d
    INTEGER :: nbdirs
    INTEGER :: nd0
    REAL(kind=r8) :: temp1
    REAL(r8) :: temp2
    INTEGER :: nbdirs0
!
    IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
      temp1 = pz(icv1)/rz(icv1)
      DO nd0=1,nbdirs0
        tempd(nd0) = (pzd0(nd0, icv1)-temp1*rzd0(nd0, icv1))/rz(icv1)
      END DO
      temp = temp1
      arg12dd = 0.D0
      DO nd=1,nbdirs
        temp1 = (pzd(nd, icv1)-temp*rzd(nd, icv1))/rz(icv1)
        DO nd0=1,nbdirs0
          arg12dd(nd0, nd) = (pzdd(nd0, nd, icv1)-rzd(nd, icv1)*tempd(&
&           nd0)-temp*rzdd(nd0, nd, icv1)-temp1*rzd0(nd0, icv1))/rz(icv1&
&           )
        END DO
        arg12d(nd) = temp1
      END DO
      arg12 = temp
      temp1 = SQRT(arg12)
      DO nd0=1,nbdirs0
        arg12d0(nd0) = tempd(nd0)
        IF (arg12 .EQ. 0.D0) THEN
          tempd(nd0) = 0.D0
        ELSE
          tempd(nd0) = arg12d0(nd0)/(2.0*temp1)
        END IF
      END DO
      temp = temp1
      DO nd=1,nbdirs
        IF (arg12 .EQ. 0.d0) THEN
          DO nd0=1,nbdirs0
            csdd(nd0, nd) = 0.D0
          END DO
          csd(nd) = 0.d0
        ELSE
          temp1 = arg12d(nd)/(2.0*temp)
          DO nd0=1,nbdirs0
            csdd(nd0, nd) = (arg12dd(nd0, nd)-temp1*2.0*tempd(nd0))/(2.0&
&             *temp)
          END DO
          csd(nd) = temp1
        END IF
        DO nd0=1,nbdirs0
          csbcdd(nd0, nd, icv1, is) = csdd(nd0, nd)
        END DO
        csbcd(nd, icv1, is) = csd(nd)
      END DO
      DO nd0=1,nbdirs0
        csd0(nd0) = tempd(nd0)
        csbcd0(nd0, icv1, is) = csd0(nd0)
      END DO
      cs = temp
      csbc(icv1, is) = cs
    ELSE
      arg13 = (pl%te(icv1)*rt%rza(icv1, is)+pl%ti(icv1))/(am(is)*mp)
      temp2 = SQRT(arg13)
      DO nd0=1,nbdirs0
        arg13d0(nd0) = (rt%rza(icv1, is)*pld0%te(nd0, icv1)+pl%te(icv1)*&
&         rtd0%rza(nd0, icv1, is)+pld0%ti(nd0, icv1))/(am(is)*mp)
        IF (arg13 .EQ. 0.D0) THEN
          temp0d(nd0) = 0.D0
        ELSE
          temp0d(nd0) = arg13d0(nd0)/(2.0*temp2)
        END IF
      END DO
      temp0 = temp2
      arg13dd = 0.D0
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          arg13dd(nd0, nd) = (pld%te(nd, icv1)*rtd0%rza(nd0, icv1, is)+&
&           rt%rza(icv1, is)*pldd%te(nd0, nd, icv1)+rtd%rza(nd, icv1, is&
&           )*pld0%te(nd0, icv1)+pl%te(icv1)*rtdd%rza(nd0, nd, icv1, is)&
&           +pldd%ti(nd0, nd, icv1))/(am(is)*mp)
        END DO
        arg13d(nd) = (rt%rza(icv1, is)*pld%te(nd, icv1)+pl%te(icv1)*rtd%&
&         rza(nd, icv1, is)+pld%ti(nd, icv1))/(am(is)*mp)
        IF (arg13 .EQ. 0.d0) THEN
          DO nd0=1,nbdirs0
            csdd(nd0, nd) = 0.D0
          END DO
          csd(nd) = 0.d0
        ELSE
          temp2 = arg13d(nd)/(2.0*temp0)
          DO nd0=1,nbdirs0
            csdd(nd0, nd) = (arg13dd(nd0, nd)-temp2*2.0*temp0d(nd0))/(&
&             2.0*temp0)
          END DO
          csd(nd) = temp2
        END IF
        DO nd0=1,nbdirs0
          csbcdd(nd0, nd, icv1, is) = csdd(nd0, nd)
        END DO
        csbcd(nd, icv1, is) = csd(nd)
      END DO
      DO nd0=1,nbdirs0
        csd0(nd0) = temp0d(nd0)
        csbcd0(nd0, icv1, is) = csd0(nd0)
      END DO
      cs = temp0
      csbc(icv1, is) = cs
    END IF
    RETURN
  END SUBROUTINE CSBC_IS_DV_DV

!  Differentiation of csbc_is in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: csbc cs
!   with respect to varying inputs: *(rt.rza) *(pl.te) *(pl.ti)
!                rz csbc pz
!   Plus diff mem management of: rt.rza:in pl.te:in pl.ti:in
!
!srv 15.02.26 {
  SUBROUTINE CSBC_IS_DV(icv1, ib, is, cs, csd, nbdirs)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: icv1, ib, is
    REAL(kind=r8) :: cs
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd
    INTRINSIC SQRT
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(r8) :: arg13
    REAL(r8), DIMENSION(nbdirsmax) :: arg13d
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(r8) :: temp0
    INTEGER :: nbdirs
!
    IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
      temp = pz(icv1)/rz(icv1)
      DO nd=1,nbdirs
        arg12d(nd) = (pzd(nd, icv1)-temp*rzd(nd, icv1))/rz(icv1)
      END DO
      arg12 = temp
      temp = SQRT(arg12)
      DO nd=1,nbdirs
        IF (arg12 .EQ. 0.d0) THEN
          csd(nd) = 0.d0
        ELSE
          csd(nd) = arg12d(nd)/(2.0*temp)
        END IF
        csbcd(nd, icv1, is) = csd(nd)
      END DO
      cs = temp
      csbc(icv1, is) = cs
    ELSE
      arg13 = (pl%te(icv1)*rt%rza(icv1, is)+pl%ti(icv1))/(am(is)*mp)
      temp0 = SQRT(arg13)
      DO nd=1,nbdirs
        arg13d(nd) = (rt%rza(icv1, is)*pld%te(nd, icv1)+pl%te(icv1)*rtd%&
&         rza(nd, icv1, is)+pld%ti(nd, icv1))/(am(is)*mp)
        IF (arg13 .EQ. 0.d0) THEN
          csd(nd) = 0.d0
        ELSE
          csd(nd) = arg13d(nd)/(2.0*temp0)
        END IF
        csbcd(nd, icv1, is) = csd(nd)
      END DO
      cs = temp0
      csbc(icv1, is) = cs
    END IF
    RETURN
  END SUBROUTINE CSBC_IS_DV

!
!srv 15.02.26 {
  SUBROUTINE CSBC_IS(icv1, ib, is, cs)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER :: icv1, ib, is
    REAL(kind=r8) :: cs
    INTRINSIC SQRT
    REAL(kind=r8) :: arg12
    REAL(r8) :: arg13
!
    IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
      arg12 = pz(icv1)/rz(icv1)
      cs = SQRT(arg12)
      csbc(icv1, is) = cs
    ELSE
      arg13 = (pl%te(icv1)*rt%rza(icv1, is)+pl%ti(icv1))/(am(is)*mp)
      cs = SQRT(arg13)
      csbc(icv1, is) = cs
    END IF
    RETURN
  END SUBROUTINE CSBC_IS

!  Differentiation of vbc_is_dv in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: vbc vbcd
!   with respect to varying inputs: *(dv.vaecrb) *(dvd.vaecrb)
!                *(pld.ua) *(pl.ua) vbc vbcd csd cs
!   Plus diff mem management of: dv.vaecrb:in dvd.vaecrb:in pld.ua:in
!                pl.ua:in
!  Differentiation of vbc_is in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: vbc
!   with respect to varying inputs: *(dv.vaecrb) *(pl.ua) vbc cs
!   Plus diff mem management of: dv.vaecrb:in pl.ua:in
!srv 15.02.26 }
!
!srv 15.02.26 {
  SUBROUTINE VBC_IS_DV_DV(ib, is, ibc, icv1, icv2, ifc, cs, csd0, csd, &
&   csdd, wrk, nbdirs, nbdirs0)
    USE B2MOD_DIFFSIZES
!  Hint: nbdirsmax0 should be the maximum number of differentiation directions
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: ib, is, ibc, icv1, icv2, ifc
! cs=csbc(iCv1,is)
    REAL(kind=r8) :: cs
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: csd0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: csdd
    REAL(kind=r8) :: wrk, vbnd, t0
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: vbndd0, t0d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: vbndd, t0d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: vbnddd, t0dd
    INTRINSIC ABS
    INTRINSIC MIN
    INTRINSIC SIGN
    REAL(kind=r8) :: y1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: y1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y1dd
    REAL(kind=r8) :: y2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: y2d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y2d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y2dd
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x1dd
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: min1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: min1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: min1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min1dd
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: min2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: min2d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: min2d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min2dd
    REAL(kind=r8) :: max1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max1dd
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(r8) :: temp0
    INTEGER :: nbdirs
    INTEGER :: nd0
    INTEGER :: nbdirs0
!
    wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)*mpg%&
&     bcfcor(mpg%bccvp(ib, 1)+ibc-1)
    temp = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
    vbnddd = 0.D0
    DO nd=1,nbdirs
      DO nd0=nd,nbdirs0
        vbnddd(nd0, nd) = temp*(geo%fcqalf(ifc, 0)*dvdd%vaecrb(nd0, nd, &
&         ifc, 0, is)+geo%fcqalf(ifc, 1)*dvdd%vaecrb(nd0, nd, ifc, 1, is&
&         ))
      END DO
      vbndd(nd) = temp*(geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, ifc, 0, is)+&
&       geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc, 1, is))
    END DO
    DO nd0=1,nbdirs0
      vbndd0(nd0) = temp*(geo%fcqalf(ifc, 0)*dvd0%vaecrb(nd0, ifc, 0, is&
&       )+geo%fcqalf(ifc, 1)*dvd0%vaecrb(nd0, ifc, 1, is))
    END DO
    vbnd = temp*(geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcqalf(ifc&
&     , 1)*dv%vaecrb(ifc, 1, is))
    IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
      IF (wrk .GE. 0.) THEN
        abs0 = wrk
        t0dd = 0.D0
      ELSE
        abs0 = -wrk
        t0dd = 0.D0
      END IF
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          t0dd(nd0, nd) = abs0*2.0_R8*csdd(nd0, nd)
        END DO
        t0d(nd) = abs0*2.0_R8*csd(nd)
      END DO
      DO nd0=1,nbdirs0
        t0d0(nd0) = abs0*2.0_R8*csd0(nd0)
      END DO
      t0 = 2.0_R8*cs*abs0
      IF (vbnd .GE. 0.) THEN
        y1dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y1dd(nd0, nd) = vbnddd(nd0, nd)
          END DO
          y1d(nd) = vbndd(nd)
        END DO
        DO nd0=1,nbdirs0
          y1d0(nd0) = vbndd0(nd0)
        END DO
        y1 = vbnd
      ELSE
        y1dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y1dd(nd0, nd) = -vbnddd(nd0, nd)
          END DO
          y1d(nd) = -vbndd(nd)
        END DO
        DO nd0=1,nbdirs0
          y1d0(nd0) = -vbndd0(nd0)
        END DO
        y1 = -vbnd
      END IF
      IF (t0 .GT. y1) THEN
        min1dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            min1dd(nd0, nd) = y1dd(nd0, nd)
          END DO
          min1d(nd) = y1d(nd)
        END DO
        DO nd0=1,nbdirs0
          min1d0(nd0) = y1d0(nd0)
        END DO
        min1 = y1
      ELSE
        min1dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            min1dd(nd0, nd) = t0dd(nd0, nd)
          END DO
          min1d(nd) = t0d(nd)
        END DO
        DO nd0=1,nbdirs0
          min1d0(nd0) = t0d0(nd0)
        END DO
        min1 = t0
      END IF
      temp0 = SIGN(1.0_R8, vbnd)
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          vbnddd(nd0, nd) = temp0*min1dd(nd0, nd)
        END DO
        vbndd(nd) = temp0*min1d(nd)
      END DO
      DO nd0=1,nbdirs0
        vbndd0(nd0) = temp0*min1d0(nd0)
      END DO
      vbnd = temp0*min1
      temp0 = SIGN(1.0_R8, wrk)
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          vbcdd(nd0, nd, icv1, is) = wrk*csdd(nd0, nd) - temp0*vbnddd(&
&           nd0, nd)
        END DO
        vbcd(nd, icv1, is) = wrk*csd(nd) - temp0*vbndd(nd)
      END DO
      DO nd0=1,nbdirs0
        vbcd0(nd0, icv1, is) = wrk*csd0(nd0) - temp0*vbndd0(nd0)
      END DO
      vbc(icv1, is) = wrk*cs - temp0*vbnd
    ELSE
      IF (wrk .GE. 0.) THEN
        abs1 = wrk
        t0dd = 0.D0
      ELSE
        abs1 = -wrk
        t0dd = 0.D0
      END IF
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          t0dd(nd0, nd) = abs1*2.0_R8*csdd(nd0, nd)
        END DO
        t0d(nd) = abs1*2.0_R8*csd(nd)
      END DO
      DO nd0=1,nbdirs0
        t0d0(nd0) = abs1*2.0_R8*csd0(nd0)
      END DO
      t0 = 2.0_R8*cs*abs1
      IF (vbnd .GE. 0.) THEN
        y2dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y2dd(nd0, nd) = vbnddd(nd0, nd)
          END DO
          y2d(nd) = vbndd(nd)
        END DO
        DO nd0=1,nbdirs0
          y2d0(nd0) = vbndd0(nd0)
        END DO
        y2 = vbnd
      ELSE
        y2dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y2dd(nd0, nd) = -vbnddd(nd0, nd)
          END DO
          y2d(nd) = -vbndd(nd)
        END DO
        DO nd0=1,nbdirs0
          y2d0(nd0) = -vbndd0(nd0)
        END DO
        y2 = -vbnd
      END IF
      IF (t0 .GT. y2) THEN
        min2dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            min2dd(nd0, nd) = y2dd(nd0, nd)
          END DO
          min2d(nd) = y2d(nd)
        END DO
        DO nd0=1,nbdirs0
          min2d0(nd0) = y2d0(nd0)
        END DO
        min2 = y2
      ELSE
        min2dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            min2dd(nd0, nd) = t0dd(nd0, nd)
          END DO
          min2d(nd) = t0d(nd)
        END DO
        DO nd0=1,nbdirs0
          min2d0(nd0) = t0d0(nd0)
        END DO
        min2 = t0
      END IF
      temp0 = SIGN(1.0_R8, vbnd)
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          vbnddd(nd0, nd) = temp0*min2dd(nd0, nd)
        END DO
        vbndd(nd) = temp0*min2d(nd)
      END DO
      DO nd0=1,nbdirs0
        vbndd0(nd0) = temp0*min2d0(nd0)
      END DO
      vbnd = temp0*min2
      temp0 = SIGN(1.0_R8, wrk)
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          vbcdd(nd0, nd, icv1, is) = wrk*csdd(nd0, nd) - temp0*vbnddd(&
&           nd0, nd)
        END DO
        vbcd(nd, icv1, is) = wrk*csd(nd) - temp0*vbndd(nd)
      END DO
      DO nd0=1,nbdirs0
        vbcd0(nd0, icv1, is) = wrk*csd0(nd0) - temp0*vbndd0(nd0)
      END DO
      vbc(icv1, is) = wrk*cs - temp0*vbnd
      temp0 = SIGN(1.0_R8, wrk)
      x1dd = 0.D0
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          x1dd(nd0, nd) = temp0*vbcdd(nd0, nd, icv1, is)
        END DO
        x1d(nd) = temp0*vbcd(nd, icv1, is)
      END DO
      DO nd0=1,nbdirs0
        x1d0(nd0) = temp0*vbcd0(nd0, icv1, is)
      END DO
      x1 = temp0*vbc(icv1, is)
      IF (x1 .LT. wrk*pl%ua(icv2, is)) THEN
        max1dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            max1dd(nd0, nd) = wrk*pldd%ua(nd0, nd, icv2, is)
          END DO
          max1d(nd) = wrk*pld%ua(nd, icv2, is)
        END DO
        DO nd0=1,nbdirs0
          max1d0(nd0) = wrk*pld0%ua(nd0, icv2, is)
        END DO
        max1 = wrk*pl%ua(icv2, is)
      ELSE
        max1dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            max1dd(nd0, nd) = x1dd(nd0, nd)
          END DO
          max1d(nd) = x1d(nd)
        END DO
        DO nd0=1,nbdirs0
          max1d0(nd0) = x1d0(nd0)
        END DO
        max1 = x1
      END IF
      temp0 = SIGN(1.0_R8, wrk)
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          vbcdd(nd0, nd, icv1, is) = temp0*max1dd(nd0, nd)
        END DO
        vbcd(nd, icv1, is) = temp0*max1d(nd)
      END DO
      DO nd0=1,nbdirs0
        vbcd0(nd0, icv1, is) = temp0*max1d0(nd0)
      END DO
      vbc(icv1, is) = temp0*max1
    END IF
    RETURN
  END SUBROUTINE VBC_IS_DV_DV

!  Differentiation of vbc_is in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: vbc
!   with respect to varying inputs: *(dv.vaecrb) *(pl.ua) vbc cs
!   Plus diff mem management of: dv.vaecrb:in pl.ua:in
!srv 15.02.26 }
!
!srv 15.02.26 {
  SUBROUTINE VBC_IS_DV(ib, is, ibc, icv1, icv2, ifc, cs, csd, wrk, &
&   nbdirs)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: ib, is, ibc, icv1, icv2, ifc
! cs=csbc(iCv1,is)
    REAL(kind=r8) :: cs
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd
    REAL(kind=r8) :: wrk, vbnd, t0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: vbndd, t0d
    INTRINSIC ABS
    INTRINSIC MIN
    INTRINSIC SIGN
    REAL(kind=r8) :: y1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y1d
    REAL(kind=r8) :: y2
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y2d
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: min1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: min1d
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: min2
    REAL(kind=r8), DIMENSION(nbdirsmax) :: min2d
    REAL(kind=r8) :: max1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max1d
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(r8) :: temp0
    INTEGER :: nbdirs
!
    wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)*mpg%&
&     bcfcor(mpg%bccvp(ib, 1)+ibc-1)
    temp = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
    DO nd=1,nbdirs
      vbndd(nd) = temp*(geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, ifc, 0, is)+&
&       geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc, 1, is))
    END DO
    vbnd = temp*(geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcqalf(ifc&
&     , 1)*dv%vaecrb(ifc, 1, is))
    IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
      IF (wrk .GE. 0.) THEN
        abs0 = wrk
      ELSE
        abs0 = -wrk
      END IF
      DO nd=1,nbdirs
        t0d(nd) = abs0*2.0_R8*csd(nd)
      END DO
      t0 = 2.0_R8*cs*abs0
      IF (vbnd .GE. 0.) THEN
        DO nd=1,nbdirs
          y1d(nd) = vbndd(nd)
        END DO
        y1 = vbnd
      ELSE
        DO nd=1,nbdirs
          y1d(nd) = -vbndd(nd)
        END DO
        y1 = -vbnd
      END IF
      IF (t0 .GT. y1) THEN
        DO nd=1,nbdirs
          min1d(nd) = y1d(nd)
        END DO
        min1 = y1
      ELSE
        DO nd=1,nbdirs
          min1d(nd) = t0d(nd)
        END DO
        min1 = t0
      END IF
      temp0 = SIGN(1.0_R8, vbnd)
      DO nd=1,nbdirs
        vbndd(nd) = temp0*min1d(nd)
      END DO
      vbnd = temp0*min1
      temp0 = SIGN(1.0_R8, wrk)
      DO nd=1,nbdirs
        vbcd(nd, icv1, is) = wrk*csd(nd) - temp0*vbndd(nd)
      END DO
      vbc(icv1, is) = wrk*cs - temp0*vbnd
    ELSE
      IF (wrk .GE. 0.) THEN
        abs1 = wrk
      ELSE
        abs1 = -wrk
      END IF
      DO nd=1,nbdirs
        t0d(nd) = abs1*2.0_R8*csd(nd)
      END DO
      t0 = 2.0_R8*cs*abs1
      IF (vbnd .GE. 0.) THEN
        DO nd=1,nbdirs
          y2d(nd) = vbndd(nd)
        END DO
        y2 = vbnd
      ELSE
        DO nd=1,nbdirs
          y2d(nd) = -vbndd(nd)
        END DO
        y2 = -vbnd
      END IF
      IF (t0 .GT. y2) THEN
        DO nd=1,nbdirs
          min2d(nd) = y2d(nd)
        END DO
        min2 = y2
      ELSE
        DO nd=1,nbdirs
          min2d(nd) = t0d(nd)
        END DO
        min2 = t0
      END IF
      temp0 = SIGN(1.0_R8, vbnd)
      DO nd=1,nbdirs
        vbndd(nd) = temp0*min2d(nd)
      END DO
      vbnd = temp0*min2
      temp0 = SIGN(1.0_R8, wrk)
      DO nd=1,nbdirs
        vbcd(nd, icv1, is) = wrk*csd(nd) - temp0*vbndd(nd)
      END DO
      vbc(icv1, is) = wrk*cs - temp0*vbnd
      temp0 = SIGN(1.0_R8, wrk)
      DO nd=1,nbdirs
        x1d(nd) = temp0*vbcd(nd, icv1, is)
      END DO
      x1 = temp0*vbc(icv1, is)
      IF (x1 .LT. wrk*pl%ua(icv2, is)) THEN
        DO nd=1,nbdirs
          max1d(nd) = wrk*pld%ua(nd, icv2, is)
        END DO
        max1 = wrk*pl%ua(icv2, is)
      ELSE
        DO nd=1,nbdirs
          max1d(nd) = x1d(nd)
        END DO
        max1 = x1
      END IF
      temp0 = SIGN(1.0_R8, wrk)
      DO nd=1,nbdirs
        vbcd(nd, icv1, is) = temp0*max1d(nd)
      END DO
      vbc(icv1, is) = temp0*max1
    END IF
    RETURN
  END SUBROUTINE VBC_IS_DV

!srv 15.02.26 }
!
!srv 15.02.26 {
  SUBROUTINE VBC_IS(ib, is, ibc, icv1, icv2, ifc, cs, wrk)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER :: ib, is, ibc, icv1, icv2, ifc
! cs=csbc(iCv1,is)
    REAL(kind=r8) :: cs
    REAL(kind=r8) :: wrk, vbnd, t0
    INTRINSIC ABS
    INTRINSIC MIN
    INTRINSIC SIGN
    REAL(kind=r8) :: y1
    REAL(kind=r8) :: y2
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: min1
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: min2
    REAL(kind=r8) :: max1
!
    wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)*mpg%&
&     bcfcor(mpg%bccvp(ib, 1)+ibc-1)
    vbnd = (dv%vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb(ifc, 1, &
&     is)*geo%fcqalf(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
    IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
      IF (wrk .GE. 0.) THEN
        abs0 = wrk
      ELSE
        abs0 = -wrk
      END IF
      t0 = 2.0_R8*cs*abs0
      IF (vbnd .GE. 0.) THEN
        y1 = vbnd
      ELSE
        y1 = -vbnd
      END IF
      IF (t0 .GT. y1) THEN
        min1 = y1
      ELSE
        min1 = t0
      END IF
      vbnd = min1*SIGN(1.0_R8, vbnd)
      vbc(icv1, is) = cs*wrk - vbnd*SIGN(1.0_R8, wrk)
    ELSE
      IF (wrk .GE. 0.) THEN
        abs1 = wrk
      ELSE
        abs1 = -wrk
      END IF
      t0 = 2.0_R8*cs*abs1
      IF (vbnd .GE. 0.) THEN
        y2 = vbnd
      ELSE
        y2 = -vbnd
      END IF
      IF (t0 .GT. y2) THEN
        min2 = y2
      ELSE
        min2 = t0
      END IF
      vbnd = min2*SIGN(1.0_R8, vbnd)
      vbc(icv1, is) = cs*wrk - vbnd*SIGN(1.0_R8, wrk)
      x1 = vbc(icv1, is)*SIGN(1.0_R8, wrk)
      IF (x1 .LT. wrk*pl%ua(icv2, is)) THEN
        max1 = wrk*pl%ua(icv2, is)
      ELSE
        max1 = x1
      END IF
      vbc(icv1, is) = max1*SIGN(1.0_R8, wrk)
    END IF
    RETURN
  END SUBROUTINE VBC_IS

