    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max9dd
    REAL(r8) :: min3
    REAL(r8), DIMENSION(nbdirsmax0) :: min3d0
    REAL(r8), DIMENSION(nbdirsmax) :: min3d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min3dd
    REAL(kind=r8) :: max10
    REAL(kind=r8) :: max11
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max11d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max11d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max11dd
    REAL(kind=r8) :: max12
    REAL(kind=r8) :: max13
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max13d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max13d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max13dd
    REAL(kind=r8) :: max14
    REAL(kind=r8) :: max15
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max15d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max15d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max15dd
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: abs2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: abs2d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs2d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: abs2dd
    REAL(kind=r8) :: max16
    REAL(kind=r8) :: max17
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max17d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max17d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max17dd
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: abs4
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: abs4d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs4d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: abs4dd
    REAL(kind=r8) :: max18
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max18d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max18d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max18dd
    REAL(r8) :: max19
    REAL(r8), DIMENSION(nbdirsmax0) :: max19d0
    REAL(r8), DIMENSION(nbdirsmax) :: max19d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max19dd
    REAL(kind=r8) :: abs5
    REAL(r8) :: max20
    REAL(r8), DIMENSION(nbdirsmax0) :: max20d0
    REAL(r8), DIMENSION(nbdirsmax) :: max20d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max20dd
    REAL(kind=r8) :: abs6
    REAL(kind=r8) :: abs7
    REAL(kind=r8) :: abs8
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: abs8d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs8d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: abs8dd
    REAL(kind=r8) :: abs9
    REAL(kind=r8) :: abs10
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: abs10d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs10d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: abs10dd
    REAL(kind=r8) :: abs11
    REAL(kind=r8) :: abs12
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: abs12d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs12d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: abs12dd
    REAL(kind=r8) :: abs13
    REAL(kind=r8) :: abs14
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: abs14d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs14d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: abs14dd
    REAL(r8) :: arg12
    REAL(r8), DIMENSION(nbdirsmax0) :: arg12d0
    REAL(r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg12dd
    REAL(r8) :: result10
    REAL(r8), DIMENSION(nbdirsmax0) :: result10d0
    REAL(r8), DIMENSION(nbdirsmax) :: result10d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: result10dd
    LOGICAL :: result11
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: tempd
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp1d
    REAL(kind=r8) :: temp2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp2d
    REAL(r8) :: temp3
    REAL(r8), DIMENSION(nbdirsmax0) :: temp3d
    REAL(r8) :: temp4
    REAL(r8), DIMENSION(nbdirsmax0) :: temp4d
    REAL(kind=r8) :: temp5
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp5d
    INTEGER :: nbdirs
    INTEGER :: nd0
    REAL(kind=r8) :: temp6
    REAL(r8) :: temp7
    REAL(r8) :: temp8
    REAL(kind=r8) :: temp9
    REAL(kind=r8) :: temp10
    REAL(kind=r8) :: temp11
    REAL(kind=r8) :: temp12
    INTEGER :: nbdirs0
    t3d = 0.d0
    y1dd = 0.D0
    max9dd = 0.D0
    min2dd = 0.D0
    csdd = 0.D0
    abs8dd = 0.D0
    vbnddd = 0.D0
    add = 0.D0
    result10dd = 0.D0
    max6dd = 0.D0
    y14dd = 0.D0
    abs12dd = 0.D0
    max17dd = 0.D0
    max3dd = 0.D0
    y8dd = 0.D0
    y11dd = 0.D0
    abs2dd = 0.D0
    y5dd = 0.D0
    t2dd = 0.D0
    max11dd = 0.D0
    x11dd = 0.D0
    y2dd = 0.D0
    x4dd = 0.D0
    min3dd = 0.D0
    totpardd = 0.D0
    x1dd = 0.D0
    max7dd = 0.D0
    y15dd = 0.D0
    max18dd = 0.D0
    t3d0 = 0.D0
    max4dd = 0.D0
    abs10dd = 0.D0
    max15dd = 0.D0
    max1dd = 0.D0
    y6dd = 0.D0
    x8dd = 0.D0
    arg12dd = 0.D0
    t3dd = 0.D0
    max20dd = 0.D0
    y3dd = 0.D0
    csbdd = 0.D0
    t0dd = 0.D0
    x2dd = 0.D0
    max8dd = 0.D0
    min1dd = 0.D0
    abs14dd = 0.D0
    max19dd = 0.D0
    max5dd = 0.D0
    y13dd = 0.D0
    abs4dd = 0.D0
    max2dd = 0.D0
    t4dd = 0.D0
    max13dd = 0.D0
    y4dd = 0.D0
    x6dd = 0.D0
    t1dd = 0.D0
    x10dd = 0.D0
!
    DO is=0,ns-1
      IF (is .EQ. ns - 1) THEN
        ishigh = .true.
      ELSE
        ishigh = .NOT.LNEXT(is, is + 1)
      END IF
!
! -- BOUNDARY CONDITIONS FOR CONTINUITY EQUATIONS --
      SELECT CASE  (bccon(is, ib)) 
      CASE (0) 

      CASE (1) 
!
!
! -- BCCON=1 -- PRESCRIBE THE VALUE OF THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                conpardd(nd0, nd, is, ib, 1) = 0.D0
              END DO
              conpard(nd, is, ib, 1) = 0.d0
            END DO
            DO nd0=1,nbdirs0
              conpard0(nd0, is, ib, 1) = 0.D0
            END DO
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  1 : constant density ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 1, CONPAR(,,1) !> 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 2)
          IF (mpg%cvonclosedsurface(icv)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
            IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 1'&
&                            )
          END IF
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp = vbig*geo%fcs(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = temp*conpardd(nd0, nd, &
&               is, ib, 1)
              srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&               icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = temp*conpard(nd, is, ib, 1)
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = temp*conpard0(nd0, is, ib, 1)
            srwd0%sna0(nd0, icv1, 1, is) = 0.D0
            sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&             is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = temp*conpar(is, ib, 1)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (2) 
!
! -- BCCON=2 -- PRESCRIBE THE GRADIENT OF THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  2 : density gradient ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 2'&
&                                                           )
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          t1dd = 0.D0
          CALL INTVERTEX_S_DV_DV(ivx1, ncv, nvx, mpg, geo%vxvol, pl%na(:&
&                          , is), pld0%na(:, :, is), pld%na(:, :, is), &
&                          pldd%na(:, :, :, is), t1, t1d0, t1d, t1dd, &
&                          nbdirs, nbdirs0)
          t2dd = 0.D0
          CALL INTVERTEX_S_DV_DV(ivx2, ncv, nvx, mpg, geo%vxvol, pl%na(:&
&                          , is), pld0%na(:, :, is), pld%na(:, :, is), &
&                          pldd%na(:, :, :, is), t2, t2d0, t2d, t2dd, &
&                          nbdirs, nbdirs0)
          temp = vbig*geo%fcs(ifc)
          temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
          temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc&
&           , 2))
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            temp6 = temp0*geo%fcqgam(ifc, 0)
            DO nd0=1,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = temp*(temp6*conpardd(&
&               nd0, nd, is, ib, 1)-temp1*temp2*(t2dd(nd0, nd)-t1dd(nd0&
&               , nd))/geo%fcht(ifc)+pldd%na(nd0, nd, icv2, is))
              srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&               icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = temp*(temp6*conpard(nd, is, ib&
&             , 1)-temp1*temp2*((t2d(nd)-t1d(nd))/geo%fcht(ifc))+pld%na(&
&             nd, icv2, is))
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          temp6 = temp0*geo%fcqgam(ifc, 0)
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = temp*(temp6*conpard0(nd0, is&
&             , ib, 1)-temp1*temp2*(t2d0(nd0)-t1d0(nd0))/geo%fcht(ifc)+&
&             pld0%na(nd0, icv2, is))
            srwd0%sna0(nd0, icv1, 1, is) = 0.D0
            sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&             is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = temp*(temp6*conpar(is, ib, 1)-temp1*&
&           temp2*((t2-t1)/geo%fcht(ifc))+pl%na(icv2, is))
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (3) 
!
! -- BCCON=3 -- SHEATH CONDITIONS
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&                                   'BCCON =  3 : sheath density bc on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = ubig*geo%fcs(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = temp2*pldd%na(nd0, nd, &
&               icv2, is)
              srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&               icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = temp2*pld%na(nd, icv2, is)
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = temp2*pld0%na(nd0, icv2, is)
            srwd0%sna0(nd0, icv1, 1, is) = 0.D0
            sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&             is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = temp2*pl%na(icv2, is)
          srw%sna0(icv1, 1, is) = -(ubig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (4) 
!
! -- BCCON=4 -- PRESCRIBE THE VALUE OF THE DENSITY, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                conpardd(nd0, nd, is, ib, 1) = 0.D0
              END DO
              conpard(nd, is, ib, 1) = 0.d0
            END DO
            DO nd0=1,nbdirs0
              conpard0(nd0, is, ib, 1) = 0.D0
            END DO
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  4 : weak density ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 4, CONPAR(,,1) !> 0')
          CALL XERTST(conpar(is, ib, 2) .GT. 0.0_R8, &
&               'BCCON = 4, CONPAR(,,2) !> 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 4'&
&                                                           )
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = geo%fcs(ifc)*(conpard(&
&               nd, is, ib, 2)*conpard0(nd0, is, ib, 1)+conpar(is, ib, 1&
&               )*conpardd(nd0, nd, is, ib, 2)+conpard(nd, is, ib, 1)*&
&               conpard0(nd0, is, ib, 2)+conpar(is, ib, 2)*conpardd(nd0&
&               , nd, is, ib, 1))
              srwdd%sna0(nd0, nd, icv1, 1, is) = -(geo%fcs(ifc)*conpardd&
&               (nd0, nd, is, ib, 2))
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&               icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = geo%fcs(ifc)*(conpar(is, ib, 1)&
&             *conpard(nd, is, ib, 2)+conpar(is, ib, 2)*conpard(nd, is, &
&             ib, 1))
            srwd%sna0(nd, icv1, 1, is) = -(geo%fcs(ifc)*conpard(nd, is, &
&             ib, 2))
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = geo%fcs(ifc)*(conpar(is, ib, &
&             1)*conpard0(nd0, is, ib, 2)+conpar(is, ib, 2)*conpard0(nd0&
&             , is, ib, 1))
            srwd0%sna0(nd0, icv1, 1, is) = -(geo%fcs(ifc)*conpard0(nd0, &
&             is, ib, 2))
            sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&             is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = conpar(is, ib, 2)*geo%fcs(ifc)*conpar(&
&           is, ib, 1)
          srw%sna0(icv1, 1, is) = -(conpar(is, ib, 2)*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (5) 
!
! -- BCCON=5 -- PRESCRIBE THE PARTICLE FLUX PER UNIT AREA
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                                 'BCCON =  5 : particle flux per area '&
&                                     , conpar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = geo%fcs(ifc)*conpardd(&
&               nd0, nd, is, ib, 1)
              srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&               icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = geo%fcs(ifc)*conpard(nd, is, ib&
&             , 1)
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = geo%fcs(ifc)*conpard0(nd0, is&
&             , ib, 1)
            srwd0%sna0(nd0, icv1, 1, is) = 0.D0
            sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&             is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = conpar(is, ib, 1)*geo%fcs(ifc)
          srw%sna0(icv1, 1, is) = 0.0_R8
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
          IF (switch%mdf_fnb .NE. 0) THEN
!wdk Added correction to make mdf_fnb options equivalent
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              temp3d(nd0) = pld0%na(nd0, icv1, is) + pld0%na(nd0, icv2, &
&               is)
              tempd(nd0) = temp1*dvd0%vadia(nd0, ifc, 0, is) + temp0*&
&               dvd0%vadia(nd0, ifc, 1, is)
            END DO
            temp3 = pl%na(icv1, is) + pl%na(icv2, is)
            temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1, &
&             is)
            DO nd=1,nbdirs
              temp6 = temp1*dvd%vadia(nd, ifc, 0, is) + temp0*dvd%vadia(&
&               nd, ifc, 1, is)
              temp7 = pld%na(nd, icv1, is) + pld%na(nd, icv2, is)
              DO nd0=1,nbdirs0
                t0dd(nd0, nd) = temp2*(dvdd%fnapsch(nd0, nd, ifc, 0, is)&
&                 +dvdd%fnapsch(nd0, nd, ifc, 1, is)+0.5_R8*(temp6*&
&                 temp3d(nd0)+temp3*(temp1*dvdd%vadia(nd0, nd, ifc, 0, &
&                 is)+temp0*dvdd%vadia(nd0, nd, ifc, 1, is))+temp7*tempd&
&                 (nd0)+temp*(pldd%na(nd0, nd, icv1, is)+pldd%na(nd0, nd&
&                 , icv2, is))))
              END DO
              t0d(nd) = temp2*(dvd%fnapsch(nd, ifc, 0, is)+dvd%fnapsch(&
&               nd, ifc, 1, is)+0.5_R8*(temp3*temp6+temp*temp7))
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = temp2*(dvd0%fnapsch(nd0, ifc, 0, is)+dvd0%&
&               fnapsch(nd0, ifc, 1, is)+0.5_R8*(temp3*tempd(nd0)+temp*&
&               temp3d(nd0)))
            END DO
            t0 = temp2*(dv%fnapsch(ifc, 0, is)+dv%fnapsch(ifc, 1, is)+&
&             0.5_R8*(temp*temp3))
            IF (0.0_R8 .LT. t0) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max1dd(nd0, nd) = t0dd(nd0, nd)
                END DO
                max1d(nd) = t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                max1d0(nd0) = t0d0(nd0)
              END DO
              max1 = t0
            ELSE
              max1 = 0.0_R8
              max1d = 0.d0
              max1d0 = 0.D0
              max1dd = 0.D0
            END IF
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%sna0(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&                 icv1, 0, is) + max1dd(nd0, nd)
              END DO
              srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) + &
&               max1d(nd)
            END DO
            DO nd0=1,nbdirs0
              srwd0%sna0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, is&
&               ) + max1d0(nd0)
            END DO
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max1
            IF (0.0_R8 .GT. t0) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  min1dd(nd0, nd) = t0dd(nd0, nd)
                END DO
                min1d(nd) = t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                min1d0(nd0) = t0d0(nd0)
              END DO
              min1 = t0
            ELSE
              min1 = 0.0_R8
              min1d = 0.d0
              min1dd = 0.D0
              min1d0 = 0.D0
            END IF
            temp7 = min1/pl%na(icv1, is)
            DO nd0=1,nbdirs0
              temp3d(nd0) = (min1d0(nd0)-temp7*pld0%na(nd0, icv1, is))/&
&               pl%na(icv1, is)
            END DO
            temp3 = temp7
            DO nd=1,nbdirs
              temp7 = (min1d(nd)-temp3*pld%na(nd, icv1, is))/pl%na(icv1&
&               , is)
              DO nd0=1,nbdirs0
                srwdd%sna0(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&                 icv1, 1, is) + (min1dd(nd0, nd)-pld%na(nd, icv1, is)*&
&                 temp3d(nd0)-temp3*pldd%na(nd0, nd, icv1, is)-temp7*&
&                 pld0%na(nd0, icv1, is))/pl%na(icv1, is)
              END DO
              srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) + &
&               temp7
            END DO
            DO nd0=1,nbdirs0
              srwd0%sna0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, is&
&               ) + temp3d(nd0)
            END DO
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp3
          END IF
        END DO
      CASE (6) 
!
! -- BCCON=6 -- PRESCRIBE THE TOTAL PARTICLE FLUX FOR A
!                 CONSTANT DENSITY
!
        CALL XERRAB('b2stbc_phys -- BCCON = 6 not adapted for WG')
!
! -- BCCON=7 -- PRESCRIBE THE GIVEN PROFILE OF DENSITY
!
      CASE (7) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
          WRITE(*, '(4a,i3)') 'BCCON = 7 : specified density on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = 0.D0
              srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&               icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = 0.d0
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = 0.D0
            srwd0%sna0(nd0, icv1, 1, is) = 0.D0
            sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&             is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*bv_na(icv1, is)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (8) 
!
! -- BCCON=8 -- PRESCRIBE THE TOTAL PARTICLE FLUX WITH
!                 CONSTANT FLUX DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (is .EQ. ismain .AND. bcchar(ib) .EQ. 'S' .AND. switch%&
&             use_astra .NE. 0) THEN
            CALL XERRAB(&
&                 'Compile with -DASTRA option to couple to ASTRA!')
!
          END IF
          WRITE(*, '(a,1p,g14.7,a4,a1,a,a13,i3)') &
&         'BCCON =  8 : total particle flux ', conpar(is, ib, 1), ' on '&
&         , bcchar(ib), boundary_location(ib), ' for species ', is
        END IF
!wdk      Note: take full area for face, whether "poloidal" or "radial" or mixed
!wdk      Backwards compatibility issue for E/W and 5-pt stencil?
!wdk      Total flux will be fine, possibly distributed somewhat differently...
        us = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          us = us + geo%fcs(ifc)
        END DO
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is) + geo%fcs(ifc)*conpardd(nd0, nd, is, ib, 1)&
&               /us
              srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = sna0_no_mdfdd(nd0, &
&               nd, icv1, 0, is) + srwdd%sna0(nd0, nd, icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = sna0_no_mdfdd(nd0, &
&               nd, icv1, 1, is) + srwdd%sna0(nd0, nd, icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) + &
&             geo%fcs(ifc)*conpard(nd, is, ib, 1)/us
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = sna0_no_mdfd(nd, icv1, 0, is&
&             ) + srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = sna0_no_mdfd(nd, icv1, 1, is&
&             ) + srwd%sna0(nd, icv1, 1, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, is) &
&             + geo%fcs(ifc)*conpard0(nd0, is, ib, 1)/us
            srwd0%sna0(nd0, icv1, 1, is) = 0.D0
            sna0_no_mdfd0(nd0, icv1, 0, is) = sna0_no_mdfd0(nd0, icv1, 0&
&             , is) + srwd0%sna0(nd0, icv1, 0, is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = sna0_no_mdfd0(nd0, icv1, 1&
&             , is) + srwd0%sna0(nd0, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + conpar(is, ib&
&           , 1)/us*geo%fcs(ifc)
          srw%sna0(icv1, 1, is) = 0.0_R8
          sna0_no_mdf(icv1, 0, is) = sna0_no_mdf(icv1, 0, is) + srw%sna0&
&           (icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = sna0_no_mdf(icv1, 1, is) + srw%sna0&
&           (icv1, 1, is)
          IF (switch%mdf_fnb .NE. 0) THEN
!wdk Correction now involves vadia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_fnb = 0 option
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              temp3d(nd0) = pld0%na(nd0, icv1, is) + pld0%na(nd0, icv2, &
&               is)
              tempd(nd0) = temp1*dvd0%vadia(nd0, ifc, 0, is) + temp0*&
&               dvd0%vadia(nd0, ifc, 1, is)
            END DO
            temp3 = pl%na(icv1, is) + pl%na(icv2, is)
            temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1, &
&             is)
            DO nd=1,nbdirs
              temp6 = temp1*dvd%vadia(nd, ifc, 0, is) + temp0*dvd%vadia(&
&               nd, ifc, 1, is)
              temp7 = pld%na(nd, icv1, is) + pld%na(nd, icv2, is)
              DO nd0=1,nbdirs0
                t0dd(nd0, nd) = temp2*(dvdd%fnapsch(nd0, nd, ifc, 0, is)&
&                 +dvdd%fnapsch(nd0, nd, ifc, 1, is)+0.5_R8*(temp6*&
&                 temp3d(nd0)+temp3*(temp1*dvdd%vadia(nd0, nd, ifc, 0, &
&                 is)+temp0*dvdd%vadia(nd0, nd, ifc, 1, is))+temp7*tempd&
&                 (nd0)+temp*(pldd%na(nd0, nd, icv1, is)+pldd%na(nd0, nd&
&                 , icv2, is))))
              END DO
              t0d(nd) = temp2*(dvd%fnapsch(nd, ifc, 0, is)+dvd%fnapsch(&
&               nd, ifc, 1, is)+0.5_R8*(temp3*temp6+temp*temp7))
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = temp2*(dvd0%fnapsch(nd0, ifc, 0, is)+dvd0%&
&               fnapsch(nd0, ifc, 1, is)+0.5_R8*(temp3*tempd(nd0)+temp*&
&               temp3d(nd0)))
            END DO
            t0 = temp2*(dv%fnapsch(ifc, 0, is)+dv%fnapsch(ifc, 1, is)+&
&             0.5_R8*(temp*temp3))
            IF (0.0_R8 .LT. t0) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max2dd(nd0, nd) = t0dd(nd0, nd)
                END DO
                max2d(nd) = t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                max2d0(nd0) = t0d0(nd0)
              END DO
              max2 = t0
            ELSE
              max2 = 0.0_R8
              max2d = 0.d0
              max2d0 = 0.D0
              max2dd = 0.D0
            END IF
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%sna0(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&                 icv1, 0, is) + max2dd(nd0, nd)
              END DO
              srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) + &
&               max2d(nd)
            END DO
            DO nd0=1,nbdirs0
              srwd0%sna0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, is&
&               ) + max2d0(nd0)
            END DO
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max2
            IF (0.0_R8 .GT. t0) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  min2dd(nd0, nd) = t0dd(nd0, nd)
                END DO
                min2d(nd) = t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                min2d0(nd0) = t0d0(nd0)
              END DO
              min2 = t0
            ELSE
              min2 = 0.0_R8
              min2d = 0.d0
              min2dd = 0.D0
              min2d0 = 0.D0
            END IF
            temp7 = min2/pl%na(icv1, is)
            DO nd0=1,nbdirs0
              temp3d(nd0) = (min2d0(nd0)-temp7*pld0%na(nd0, icv1, is))/&
&               pl%na(icv1, is)
            END DO
            temp3 = temp7
            DO nd=1,nbdirs
              temp7 = (min2d(nd)-temp3*pld%na(nd, icv1, is))/pl%na(icv1&
&               , is)
              DO nd0=1,nbdirs0
                srwdd%sna0(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&                 icv1, 1, is) + (min2dd(nd0, nd)-pld%na(nd, icv1, is)*&
&                 temp3d(nd0)-temp3*pldd%na(nd0, nd, icv1, is)-temp7*&
&                 pld0%na(nd0, icv1, is))/pl%na(icv1, is)
              END DO
              srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) + &
&               temp7
            END DO
            DO nd0=1,nbdirs0
              srwd0%sna0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, is&
&               ) + temp3d(nd0)
            END DO
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp3
          END IF
        END DO
      CASE (9) 
!
! -- BCCON=9 -- PRESCRIBE THE DECAY LENGTH FOR THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  9 : density decay length ', conpar(is, ib, 1), &
&         ' on ', bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .NE. 0.0_R8, &
&               'B2STBC -- BCCON=9, CONPAR(,,1) = 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 9'&
&                                                           )
        END IF
!
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          sy = geo%fcs(ifc)
          temp3 = rt%rza(icv1, is)*pl%te(icv1) + pl%ti(icv1)
          temp7 = (co%dna0(icv1, is)+co%dpa0(icv1, is)*temp3)/conpar(is&
&           , ib, 1)
          DO nd0=1,nbdirs0
            temp3d(nd0) = pl%te(icv1)*rtd0%rza(nd0, icv1, is) + rt%rza(&
&             icv1, is)*pld0%te(nd0, icv1) + pld0%ti(nd0, icv1)
            temp4d(nd0) = (cod0%dna0(nd0, icv1, is)+temp3*cod0%dpa0(nd0&
&             , icv1, is)+co%dpa0(icv1, is)*temp3d(nd0)-temp7*conpard0(&
&             nd0, is, ib, 1))/conpar(is, ib, 1)
          END DO
          temp4 = temp7
          DO nd=1,nbdirs
            temp7 = pl%te(icv1)*rtd%rza(nd, icv1, is) + rt%rza(icv1, is)&
&             *pld%te(nd, icv1) + pld%ti(nd, icv1)
            temp8 = (cod%dna0(nd, icv1, is)+temp3*cod%dpa0(nd, icv1, is)&
&             +co%dpa0(icv1, is)*temp7-temp4*conpard(nd, is, ib, 1))/&
&             conpar(is, ib, 1)
            DO nd0=1,nbdirs0
!
              srwdd%sna0(nd0, nd, icv1, 0, is) = 0.D0
              srwdd%sna0(nd0, nd, icv1, 1, is) = -(sy*(codd%dna0(nd0, nd&
&               , icv1, is)+cod%dpa0(nd, icv1, is)*temp3d(nd0)+temp3*&
&               codd%dpa0(nd0, nd, icv1, is)+temp7*cod0%dpa0(nd0, icv1, &
&               is)+co%dpa0(icv1, is)*(rtd%rza(nd, icv1, is)*pld0%te(nd0&
&               , icv1)+pl%te(icv1)*rtdd%rza(nd0, nd, icv1, is)+pld%te(&
&               nd, icv1)*rtd0%rza(nd0, icv1, is)+rt%rza(icv1, is)*pldd%&
&               te(nd0, nd, icv1)+pldd%ti(nd0, nd, icv1))-conpard(nd, is&
&               , ib, 1)*temp4d(nd0)-temp4*conpardd(nd0, nd, is, ib, 1)-&
&               temp8*conpard0(nd0, is, ib, 1))/conpar(is, ib, 1))
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&               icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = 0.d0
            srwd%sna0(nd, icv1, 1, is) = -(sy*temp8)
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = 0.D0
            srwd0%sna0(nd0, icv1, 1, is) = -(sy*temp4d(nd0))
            sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&             is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = 0.0_R8
          srw%sna0(icv1, 1, is) = -(sy*temp4)
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
          IF (switch%mdf_fnb .EQ. 1) THEN
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t0dd(nd0, nd) = temp2*(dvdd%fnapsch(nd0, nd, ifc, 0, is)&
&                 +dvdd%fnapsch(nd0, nd, ifc, 1, is))
              END DO
              t0d(nd) = temp2*(dvd%fnapsch(nd, ifc, 0, is)+dvd%fnapsch(&
&               nd, ifc, 1, is))
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = temp2*(dvd0%fnapsch(nd0, ifc, 0, is)+dvd0%&
&               fnapsch(nd0, ifc, 1, is))
            END DO
            t0 = temp2*(dv%fnapsch(ifc, 0, is)+dv%fnapsch(ifc, 1, is))
            IF (t0 .GE. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  srwdd%sna0(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd&
&                   , icv1, 0, is) + t0dd(nd0, nd)
                END DO
                srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) &
&                 + t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                srwd0%sna0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&                 is) + t0d0(nd0)
              END DO
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
            ELSE
              temp6 = t0/pl%na(icv1, is)
              DO nd0=1,nbdirs0
                temp2d(nd0) = (t0d0(nd0)-temp6*pld0%na(nd0, icv1, is))/&
&                 pl%na(icv1, is)
              END DO
              temp2 = temp6
              DO nd=1,nbdirs
                temp6 = (t0d(nd)-temp2*pld%na(nd, icv1, is))/pl%na(icv1&
&                 , is)
                DO nd0=1,nbdirs0
                  srwdd%sna0(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd&
&                   , icv1, 1, is) + (t0dd(nd0, nd)-pld%na(nd, icv1, is)&
&                   *temp2d(nd0)-temp2*pldd%na(nd0, nd, icv1, is)-temp6*&
&                   pld0%na(nd0, icv1, is))/pl%na(icv1, is)
                END DO
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 + temp6
              END DO
              DO nd0=1,nbdirs0
                srwd0%sna0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&                 is) + temp2d(nd0)
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp2
            END IF
            temp2 = 0.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              temp4d(nd0) = pld0%na(nd0, icv1, is) + pld0%na(nd0, icv2, &
&               is)
              tempd(nd0) = temp1*dvd0%vaecrb(nd0, ifc, 0, is) + temp0*&
&               dvd0%vaecrb(nd0, ifc, 1, is)
            END DO
            temp4 = pl%na(icv1, is) + pl%na(icv2, is)
            temp = temp1*dv%vaecrb(ifc, 0, is) + temp0*dv%vaecrb(ifc, 1&
&             , is)
            DO nd=1,nbdirs
              temp6 = temp1*dvd%vaecrb(nd, ifc, 0, is) + temp0*dvd%&
&               vaecrb(nd, ifc, 1, is)
              temp8 = pld%na(nd, icv1, is) + pld%na(nd, icv2, is)
              DO nd0=1,nbdirs0
                t1dd(nd0, nd) = -(temp2*(temp6*temp4d(nd0)+temp4*(temp1*&
&                 dvdd%vaecrb(nd0, nd, ifc, 0, is)+temp0*dvdd%vaecrb(nd0&
&                 , nd, ifc, 1, is))+temp8*tempd(nd0)+temp*(pldd%na(nd0&
&                 , nd, icv1, is)+pldd%na(nd0, nd, icv2, is))))
              END DO
              t1d(nd) = -(temp2*(temp4*temp6+temp*temp8))
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = -(temp2*(temp4*tempd(nd0)+temp*temp4d(nd0)))
            END DO
            t1 = -(temp2*(temp*temp4))
            IF (t1 .GE. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  srwdd%sna0(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd&
&                   , icv1, 0, is) + t1dd(nd0, nd)
                END DO
                srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) &
&                 + t1d(nd)
              END DO
              DO nd0=1,nbdirs0
                srwd0%sna0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&                 is) + t1d0(nd0)
              END DO
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t1
            ELSE
              temp6 = t1/pl%na(icv1, is)
              DO nd0=1,nbdirs0
                temp2d(nd0) = (t1d0(nd0)-temp6*pld0%na(nd0, icv1, is))/&
&                 pl%na(icv1, is)
              END DO
              temp2 = temp6
              DO nd=1,nbdirs
                temp6 = (t1d(nd)-temp2*pld%na(nd, icv1, is))/pl%na(icv1&
&                 , is)
                DO nd0=1,nbdirs0
                  srwdd%sna0(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd&
&                   , icv1, 1, is) + (t1dd(nd0, nd)-pld%na(nd, icv1, is)&
&                   *temp2d(nd0)-temp2*pldd%na(nd0, nd, icv1, is)-temp6*&
&                   pld0%na(nd0, icv1, is))/pl%na(icv1, is)
                END DO
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 + temp6
              END DO
              DO nd0=1,nbdirs0
                srwd0%sna0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&                 is) + temp2d(nd0)
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp2
            END IF
          END IF
        END DO
      CASE (10) 
!
! -- BCCON=10 -- leakage option for density, recommended for cases with drifts
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') 'BCCON = 10 : leakage ', &
&         conpar(is, ib, 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 10'&
&                                                           )
!lkw 30.06.2022
          CALL XERTST(conpar(is, ib, 2) .GE. 0.0_R8, &
&               'For BCCON = 10, CONPAR(,,2) should not be negative')
        END IF
!wdk      Note: now total face area taken. Need to check backwards
!wdk      compatibility for E/W boundaries
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the plasma cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp)
          temp8 = SQRT(arg12)
          DO nd0=1,nbdirs0
            arg12d0(nd0) = (pl%te(icv1)*rtd0%rza(nd0, icv1, is)+rt%rza(&
&             icv1, is)*pld0%te(nd0, icv1)+pld0%ti(nd0, icv1))/(am(is)*&
&             mp)
            IF (arg12 .EQ. 0.D0) THEN
              temp4d(nd0) = 0.D0
            ELSE
              temp4d(nd0) = arg12d0(nd0)/(2.0*temp8)
            END IF
            result10d0(nd0) = temp4d(nd0)
          END DO
          temp4 = temp8
          result10 = temp4
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = 0.D0
              arg12dd(nd0, nd) = (rtd%rza(nd, icv1, is)*pld0%te(nd0, &
&               icv1)+pl%te(icv1)*rtdd%rza(nd0, nd, icv1, is)+pld%te(nd&
&               , icv1)*rtd0%rza(nd0, icv1, is)+rt%rza(icv1, is)*pldd%te&
&               (nd0, nd, icv1)+pldd%ti(nd0, nd, icv1))/(am(is)*mp)
            END DO
            srwd%sna0(nd, icv1, 0, is) = 0.d0
            arg12d(nd) = (pl%te(icv1)*rtd%rza(nd, icv1, is)+rt%rza(icv1&
&             , is)*pld%te(nd, icv1)+pld%ti(nd, icv1))/(am(is)*mp)
            IF (arg12 .EQ. 0.d0) THEN
              DO nd0=1,nbdirs0
                result10dd(nd0, nd) = 0.D0
              END DO
              result10d(nd) = 0.d0
            ELSE
              temp8 = arg12d(nd)/(2.0*temp4)
              DO nd0=1,nbdirs0
                result10dd(nd0, nd) = (arg12dd(nd0, nd)-temp8*2.0*temp4d&
&                 (nd0))/(2.0*temp4)
              END DO
              result10d(nd) = temp8
            END IF
            DO nd0=1,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 1, is) = geo%fcs(ifc)*(result10d&
&               (nd)*conpard0(nd0, is, ib, 1)+conpar(is, ib, 1)*&
&               result10dd(nd0, nd)+conpard(nd, is, ib, 1)*result10d0(&
&               nd0)+result10*conpardd(nd0, nd, is, ib, 1))
              sna0_no_mdfdd(nd0, nd, icv1, :, is) = sna0_no_mdfdd(nd0, &
&               nd, icv1, :, is) + srwdd%sna0(nd0, nd, icv1, :, is)
            END DO
            srwd%sna0(nd, icv1, 1, is) = geo%fcs(ifc)*(conpar(is, ib, 1)&
&             *result10d(nd)+result10*conpard(nd, is, ib, 1))
            sna0_no_mdfd(nd, icv1, :, is) = sna0_no_mdfd(nd, icv1, :, is&
&             ) + srwd%sna0(nd, icv1, :, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = 0.D0
            srwd0%sna0(nd0, icv1, 1, is) = geo%fcs(ifc)*(conpar(is, ib, &
&             1)*result10d0(nd0)+result10*conpard0(nd0, is, ib, 1))
            sna0_no_mdfd0(nd0, icv1, :, is) = sna0_no_mdfd0(nd0, icv1, :&
&             , is) + srwd0%sna0(nd0, icv1, :, is)
          END DO
          srw%sna0(icv1, 0, is) = 0.0_R8
          srw%sna0(icv1, 1, is) = geo%fcs(ifc)*result10*conpar(is, ib, 1&
&           )
          sna0_no_mdf(icv1, :, is) = sna0_no_mdf(icv1, :, is) + srw%sna0&
&           (icv1, :, is)
          IF (switch%mdf_fnb .EQ. 0) THEN
            temp2 = 0.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp8 = (pl%na(icv1, is)+pl%na(icv2, is))/pl%na(icv1, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              temp4d(nd0) = ((1.0-temp8)*pld0%na(nd0, icv1, is)+pld0%na(&
&               nd0, icv2, is))/pl%na(icv1, is)
              tempd(nd0) = temp1*(dvd0%vadia(nd0, ifc, 0, is)+dvd0%&
&               vaecrb(nd0, ifc, 0, is)) + temp0*(dvd0%vadia(nd0, ifc, 1&
&               , is)+dvd0%vaecrb(nd0, ifc, 1, is))
            END DO
            temp4 = temp8
            temp = temp1*(dv%vadia(ifc, 0, is)+dv%vaecrb(ifc, 0, is)) + &
&             temp0*(dv%vadia(ifc, 1, is)+dv%vaecrb(ifc, 1, is))
            DO nd=1,nbdirs
              temp6 = temp1*(dvd%vadia(nd, ifc, 0, is)+dvd%vaecrb(nd, &
&               ifc, 0, is)) + temp0*(dvd%vadia(nd, ifc, 1, is)+dvd%&
&               vaecrb(nd, ifc, 1, is))
              temp9 = temp/pl%na(icv1, is)
              temp8 = (-temp4+1.0)*pld%na(nd, icv1, is) + pld%na(nd, &
&               icv2, is)
              DO nd0=1,nbdirs0
                y1dd(nd0, nd) = temp2*(temp6*temp4d(nd0)+temp4*(temp1*(&
&                 dvdd%vadia(nd0, nd, ifc, 0, is)+dvdd%vaecrb(nd0, nd, &
&                 ifc, 0, is))+temp0*(dvdd%vadia(nd0, nd, ifc, 1, is)+&
&                 dvdd%vaecrb(nd0, nd, ifc, 1, is)))+temp9*((1.0-temp4)*&
&                 pldd%na(nd0, nd, icv1, is)-pld%na(nd, icv1, is)*temp4d&
&                 (nd0)+pldd%na(nd0, nd, icv2, is))+temp8*(tempd(nd0)-&
&                 temp9*pld0%na(nd0, icv1, is))/pl%na(icv1, is))
              END DO
              y1d(nd) = temp2*(temp4*temp6+temp8*temp9)
            END DO
            DO nd0=1,nbdirs0
              y1d0(nd0) = temp2*(temp4*tempd(nd0)+temp*temp4d(nd0))
            END DO
            y1 = temp2*(temp*temp4)
            IF (0.0_R8 .LT. y1) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max3dd(nd0, nd) = y1dd(nd0, nd)
                END DO
                max3d(nd) = y1d(nd)
              END DO
              DO nd0=1,nbdirs0
                max3d0(nd0) = y1d0(nd0)
              END DO
              max3 = y1
            ELSE
              max3 = 0.0_R8
              max3d = 0.d0
              max3d0 = 0.D0
              max3dd = 0.D0
            END IF
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%sna0(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&                 icv1, 1, is) - max3dd(nd0, nd)
              END DO
              srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) - &
&               max3d(nd)
            END DO
            DO nd0=1,nbdirs0
              srwd0%sna0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, is&
&               ) - max3d0(nd0)
            END DO
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max3
          ELSE
            temp2 = 0.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp8 = (pl%na(icv1, is)+pl%na(icv2, is))/pl%na(icv1, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              temp4d(nd0) = ((1.0-temp8)*pld0%na(nd0, icv1, is)+pld0%na(&
&               nd0, icv2, is))/pl%na(icv1, is)
              tempd(nd0) = temp1*dvd0%vaecrb(nd0, ifc, 0, is) + temp0*&
&               dvd0%vaecrb(nd0, ifc, 1, is)
            END DO
            temp4 = temp8
            temp = temp1*dv%vaecrb(ifc, 0, is) + temp0*dv%vaecrb(ifc, 1&
&             , is)
            DO nd=1,nbdirs
              temp9 = temp1*dvd%vaecrb(nd, ifc, 0, is) + temp0*dvd%&
&               vaecrb(nd, ifc, 1, is)
              temp6 = temp/pl%na(icv1, is)
              temp8 = (-temp4+1.0)*pld%na(nd, icv1, is) + pld%na(nd, &
&               icv2, is)
              DO nd0=1,nbdirs0
                y2dd(nd0, nd) = temp2*(temp9*temp4d(nd0)+temp4*(temp1*&
&                 dvdd%vaecrb(nd0, nd, ifc, 0, is)+temp0*dvdd%vaecrb(nd0&
&                 , nd, ifc, 1, is))+temp6*((1.0-temp4)*pldd%na(nd0, nd&
&                 , icv1, is)-pld%na(nd, icv1, is)*temp4d(nd0)+pldd%na(&
&                 nd0, nd, icv2, is))+temp8*(tempd(nd0)-temp6*pld0%na(&
&                 nd0, icv1, is))/pl%na(icv1, is))
              END DO
              y2d(nd) = temp2*(temp4*temp9+temp8*temp6)
            END DO
            DO nd0=1,nbdirs0
              y2d0(nd0) = temp2*(temp4*tempd(nd0)+temp*temp4d(nd0))
            END DO
            y2 = temp2*(temp*temp4)
            IF (0.0_R8 .LT. y2) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max4dd(nd0, nd) = y2dd(nd0, nd)
                END DO
                max4d(nd) = y2d(nd)
              END DO
              DO nd0=1,nbdirs0
                max4d0(nd0) = y2d0(nd0)
              END DO
              max4 = y2
            ELSE
              max4 = 0.0_R8
              max4d = 0.d0
              max4d0 = 0.D0
              max4dd = 0.D0
            END IF
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%sna0(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&                 icv1, 1, is) - max4dd(nd0, nd)
                t0dd(nd0, nd) = temp2*(dvdd%fnapsch(nd0, nd, ifc, 0, is)&
&                 +dvdd%fnapsch(nd0, nd, ifc, 1, is))
              END DO
              srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) - &
&               max4d(nd)
              t0d(nd) = temp2*(dvd%fnapsch(nd, ifc, 0, is)+dvd%fnapsch(&
&               nd, ifc, 1, is))
            END DO
            DO nd0=1,nbdirs0
              srwd0%sna0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, is&
&               ) - max4d0(nd0)
              t0d0(nd0) = temp2*(dvd0%fnapsch(nd0, ifc, 0, is)+dvd0%&
&               fnapsch(nd0, ifc, 1, is))
            END DO
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max4
            t0 = temp2*(dv%fnapsch(ifc, 0, is)+dv%fnapsch(ifc, 1, is))
            IF (t0 .GE. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  srwdd%sna0(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd&
&                   , icv1, 0, is) + t0dd(nd0, nd)
                END DO
                srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) &
&                 + t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                srwd0%sna0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&                 is) + t0d0(nd0)
              END DO
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
            ELSE
              temp9 = t0/pl%na(icv1, is)
              DO nd0=1,nbdirs0
                temp2d(nd0) = (t0d0(nd0)-temp9*pld0%na(nd0, icv1, is))/&
&                 pl%na(icv1, is)
              END DO
              temp2 = temp9
              DO nd=1,nbdirs
                temp9 = (t0d(nd)-temp2*pld%na(nd, icv1, is))/pl%na(icv1&
&                 , is)
                DO nd0=1,nbdirs0
                  srwdd%sna0(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd&
&                   , icv1, 1, is) + (t0dd(nd0, nd)-pld%na(nd, icv1, is)&
&                   *temp2d(nd0)-temp2*pldd%na(nd0, nd, icv1, is)-temp9*&
&                   pld0%na(nd0, icv1, is))/pl%na(icv1, is)
                END DO
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 + temp9
              END DO
              DO nd0=1,nbdirs0
                srwd0%sna0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&                 is) + temp2d(nd0)
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp2
            END IF
            arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*&
&             mp)
            temp8 = SQRT(arg12)
            temp4 = temp8
            result10 = temp4
            DO nd0=1,nbdirs0
              arg12d0(nd0) = (pl%te(icv1)*rtd0%rza(nd0, icv1, is)+rt%rza&
&               (icv1, is)*pld0%te(nd0, icv1)+pld0%ti(nd0, icv1))/(am(is&
&               )*mp)
              IF (arg12 .EQ. 0.D0) THEN
                temp4d(nd0) = 0.D0
              ELSE
                temp4d(nd0) = arg12d0(nd0)/(2.0*temp8)
              END IF
              result10d0(nd0) = temp4d(nd0)
              t0d0(nd0) = geo%fcs(ifc)*(conpar(is, ib, 2)*result10d0(nd0&
&               )+result10*conpard0(nd0, is, ib, 2))
            END DO
            t0 = geo%fcs(ifc)*result10*conpar(is, ib, 2)
            DO nd=1,nbdirs
!lkw 30.06.2022{
              DO nd0=1,nbdirs0
                arg12dd(nd0, nd) = (rtd%rza(nd, icv1, is)*pld0%te(nd0, &
&                 icv1)+pl%te(icv1)*rtdd%rza(nd0, nd, icv1, is)+pld%te(&
&                 nd, icv1)*rtd0%rza(nd0, icv1, is)+rt%rza(icv1, is)*&
&                 pldd%te(nd0, nd, icv1)+pldd%ti(nd0, nd, icv1))/(am(is)&
&                 *mp)
              END DO
              arg12d(nd) = (pl%te(icv1)*rtd%rza(nd, icv1, is)+rt%rza(&
&               icv1, is)*pld%te(nd, icv1)+pld%ti(nd, icv1))/(am(is)*mp)
              IF (arg12 .EQ. 0.d0) THEN
                DO nd0=1,nbdirs0
                  result10dd(nd0, nd) = 0.D0
                END DO
                result10d(nd) = 0.d0
              ELSE
                temp8 = arg12d(nd)/(2.0*temp4)
                DO nd0=1,nbdirs0
                  result10dd(nd0, nd) = (arg12dd(nd0, nd)-temp8*2.0*&
&                   temp4d(nd0))/(2.0*temp4)
                END DO
                result10d(nd) = temp8
              END IF
              t0d(nd) = geo%fcs(ifc)*(conpar(is, ib, 2)*result10d(nd)+&
&               result10*conpard(nd, is, ib, 2))
              DO nd0=1,nbdirs0
                t0dd(nd0, nd) = geo%fcs(ifc)*(result10d(nd)*conpard0(nd0&
&                 , is, ib, 2)+conpar(is, ib, 2)*result10dd(nd0, nd)+&
&                 conpard(nd, is, ib, 2)*result10d0(nd0)+result10*&
&                 conpardd(nd0, nd, is, ib, 2))
                srwdd%sna0(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&                 icv1, 0, is) + t0d(nd)*pld0%na(nd0, icv1, is) + pl%na(&
&                 icv1, is)*t0dd(nd0, nd) + pld%na(nd, icv1, is)*t0d0(&
&                 nd0) + t0*pldd%na(nd0, nd, icv1, is)
!lkw 30.06.2022}
                srwdd%sna0(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&                 icv1, 1, is) - t0dd(nd0, nd)
              END DO
              srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) + &
&               pl%na(icv1, is)*t0d(nd) + t0*pld%na(nd, icv1, is)
              srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) - &
&               t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              srwd0%sna0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, is&
&               ) + pl%na(icv1, is)*t0d0(nd0) + t0*pld0%na(nd0, icv1, is&
&               )
              srwd0%sna0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, is&
&               ) - t0d0(nd0)
            END DO
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0*pl%na(&
&             icv1, is)
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - t0
          END IF
        END DO
      CASE (11) 
!
! -- BCCON=11 -- particle flux feedback boundary condition
!
        CALL XERRAB('b2stbc_phys -- BCCON = 11 not adapted for WG')
!
! -- BCCON=12 -- particle density feedback boundary condition
!
      CASE (12) 
        CALL XERRAB('b2stbc_phys -- BCCON = 12 not adapted for WG')
!
! -- BCCON=13 -- Feedback constant density for a given particle flux
!
      CASE (13) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,a,a,i3,a,1p,2g14.7)') &
&         'BCCON = 13 : particle density to achieve '//&
&         'specified total flux on ', bcchar(ib), boundary_location(ib)&
&         , ' for species ', is, ' with parameters ', conpar(is, ib, 1)&
&         , conpar(is, ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (switch%ionising_core .GT. 0) WRITE(*, *) &
&               'imposed flux adapted due to ionising_core switch usage'
        END IF
!       ..compute average density on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
        totfluxd = 0.d0
        t1d = 0.d0
        totfluxd0 = 0.D0
        t1d0 = 0.D0
        totfluxdd = 0.D0
        t1dd = 0.D0
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t0 = t0 + geo%fcs(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t1dd(nd0, nd) = t1dd(nd0, nd) + geo%fcs(ifc)*pldd%na(nd0, &
&               nd, icv1, is)
            END DO
            t1d(nd) = t1d(nd) + geo%fcs(ifc)*pld%na(nd, icv1, is)
          END DO
          DO nd0=1,nbdirs0
            t1d0(nd0) = t1d0(nd0) + geo%fcs(ifc)*pld0%na(nd0, icv1, is)
          END DO
          t1 = t1 + geo%fcs(ifc)*pl%na(icv1, is)
          IF (bccon_flux_fb_style .EQ. 0) THEN
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%&
&                 fna(nd0, nd, ifc, 0, is)+dvdd%fna(nd0, nd, ifc, 1, is)&
&                 )
              END DO
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, ifc, 0, &
&               is)+dvd%fna(nd, ifc, 1, is))
            END DO
            DO nd0=1,nbdirs0
              totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fna(nd0, ifc&
&               , 0, is)+dvd0%fna(nd0, ifc, 1, is))
            END DO
            totflux = totflux - temp2*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1&
&             , is))
          ELSE
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%&
&                 fna_eir(nd0, nd, ifc, 0, is)+dvdd%fna_eir(nd0, nd, ifc&
&                 , 1, is))
              END DO
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna_eir(nd, ifc, &
&               0, is)+dvd%fna_eir(nd, ifc, 1, is))
            END DO
            DO nd0=1,nbdirs0
              totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fna_eir(nd0&
&               , ifc, 0, is)+dvd0%fna_eir(nd0, ifc, 1, is))
            END DO
            totflux = totflux - temp2*(dv%fna_eir(ifc, 0, is)+dv%fna_eir&
&             (ifc, 1, is))
          END IF
        END DO
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t1dd(nd0, nd) = t1dd(nd0, nd)/t0
!nh conpar(is,ib,3) contains the contribution from the ionized neutrals
!   (ionising_core option)
            totpardd(nd0, nd) = conpardd(nd0, nd, is, ib, 1) + conpardd(&
&             nd0, nd, is, ib, 3)
          END DO
          t1d(nd) = t1d(nd)/t0
          totpard(nd) = conpard(nd, is, ib, 1) + conpard(nd, is, ib, 3)
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = t1d0(nd0)/t0
          totpard0(nd0) = conpard0(nd0, is, ib, 1) + conpard0(nd0, is, &
&           ib, 3)
        END DO
        t1 = t1/t0
        totpar = conpar(is, ib, 1) + conpar(is, ib, 3)
        IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t3dd(nd0, nd) = conpardd(nd0, nd, is, ib, 2)
            END DO
            t3d(nd) = conpard(nd, is, ib, 2)
          END DO
          DO nd0=1,nbdirs0
            t3d0(nd0) = conpard0(nd0, is, ib, 2)
          END DO
          t3 = conpar(is, ib, 2)
        END IF
        IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref
          t3d = 0.d0
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        IF (totflux .GE. 0.) THEN
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              x1dd(nd0, nd) = totfluxdd(nd0, nd)
            END DO
            x1d(nd) = totfluxd(nd)
          END DO
          DO nd0=1,nbdirs0
            x1d0(nd0) = totfluxd0(nd0)
          END DO
          x1 = totflux
        ELSE
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              x1dd(nd0, nd) = -totfluxdd(nd0, nd)
            END DO
            x1d(nd) = -totfluxd(nd)
          END DO
          DO nd0=1,nbdirs0
            x1d0(nd0) = -totfluxd0(nd0)
          END DO
          x1 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              y3dd(nd0, nd) = totpardd(nd0, nd)
            END DO
            y3d(nd) = totpard(nd)
          END DO
          DO nd0=1,nbdirs0
            y3d0(nd0) = totpard0(nd0)
          END DO
          y3 = totpar
        ELSE
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              y3dd(nd0, nd) = -totpardd(nd0, nd)
            END DO
            y3d(nd) = -totpard(nd)
          END DO
          DO nd0=1,nbdirs0
            y3d0(nd0) = -totpard0(nd0)
          END DO
          y3 = -totpar
        END IF
        IF (x1 .LT. y3) THEN
          IF (y3 .LT. 1.0e10_R8) THEN
            max5 = 1.0e10_R8
            max5d = 0.d0
            max5d0 = 0.D0
            max5dd = 0.D0
          ELSE
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max5dd(nd0, nd) = y3dd(nd0, nd)
              END DO
              max5d(nd) = y3d(nd)
            END DO
            DO nd0=1,nbdirs0
              max5d0(nd0) = y3d0(nd0)
            END DO
            max5 = y3
          END IF
        ELSE IF (x1 .LT. 1.0e10_R8) THEN
          max5 = 1.0e10_R8
          max5d = 0.d0
          max5d0 = 0.D0
          max5dd = 0.D0
        ELSE
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              max5dd(nd0, nd) = x1dd(nd0, nd)
            END DO
            max5d(nd) = x1d(nd)
          END DO
          DO nd0=1,nbdirs0
            max5d0(nd0) = x1d0(nd0)
          END DO
          max5 = x1
        END IF
        temp2 = t3/max5
        DO nd0=1,nbdirs0
          temp2d(nd0) = (t3d0(nd0)-t3*max5d0(nd0)/max5)/max5
          temp4d(nd0) = -(temp2*(totfluxd0(nd0)-totpard0(nd0))+(totflux-&
&           totpar)*temp2d(nd0))
        END DO
        temp4 = -((totflux-totpar)*temp2) + 1.0_R8
        DO nd=1,nbdirs
          temp9 = t3d(nd) - temp2*max5d(nd)
          temp6 = (totflux-totpar)/max5
          temp10 = temp2*(totfluxd(nd)-totpard(nd)) + temp6*temp9
          DO nd0=1,nbdirs0
            t2dd(nd0, nd) = t1d(nd)*temp4d(nd0) + temp4*t1dd(nd0, nd) - &
&             temp10*t1d0(nd0) - t1*((totfluxd(nd)-totpard(nd))*temp2d(&
&             nd0)+temp2*(totfluxdd(nd0, nd)-totpardd(nd0, nd))+temp9*(&
&             totfluxd0(nd0)-totpard0(nd0)-temp6*max5d0(nd0))/max5+temp6&
&             *(t3dd(nd0, nd)-max5d(nd)*temp2d(nd0)-temp2*max5dd(nd0, nd&
&             )))
          END DO
          t2d(nd) = temp4*t1d(nd) - t1*temp10
        END DO
        DO nd0=1,nbdirs0
          t2d0(nd0) = t1*temp4d(nd0) + temp4*t1d0(nd0)
        END DO
        t2 = temp4*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, &
&                                        '(a,i3,1p,4(1x,e15.6))') &
&             'bccon=13: is, curr_flux, desired_flux, old/new density, '&
&                                        , is, totflux, totpar, t1, t2
!       ..impose density
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = geo%fcs(ifc)*vbig*t2dd(&
&               nd0, nd)
              srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&               icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = geo%fcs(ifc)*vbig*t2d(nd)
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = geo%fcs(ifc)*vbig*t2d0(nd0)
            srwd0%sna0(nd0, icv1, 1, is) = 0.D0
            sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&             is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*t2
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (14) 
!
! -- BCCON=14 -- Sound speed flux
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
            WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&           'BCCON = 14 : sound speed flux ', mompar(is, ib, 1), ' on '&
&           , bcchar(ib), boundary_location(ib), ' for species ', is
          ELSE
            WRITE(*, '(a,a,1p,g14.7,a,a,a,a,i3)') &
&           'BCCON = 14 with MOMPAR(:,:,2) > 0.5 : non-marginal ', &
&           'sheath BC, with MOMPAR(:,:,1) = ', mompar(is, ib, 1), &
&           ' on boundary ', bcchar(ib), boundary_location(ib), &
&           ' for species ', is
          END IF
          CALL XERTST(conpar(is, ib, 2) .GE. 0.0_R8, &
&               'BCCON = 14, CONPAR(,,2) < 0 not allowed!')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            s1 = geo%fcpbs(ifc)
          ELSE
            s1 = -geo%fcpbs(ifc)
          END IF
!srv 15.02.26
          CALL CSBC_IS_DV_DV(icv1, ib, is, cs, csd0, csd, csdd, nbdirs, &
&                      nbdirs0)
!srv 15.02.26
          CALL VBC_IS_DV_DV(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is)&
&                     , csbcd0(:, icv1, is), csbcd(:, icv1, is), csbcdd(&
&                     :, :, icv1, is), wrk, nbdirs, nbdirs0)
          IF (wrk .GE. 0.) THEN
            abs0 = wrk
          ELSE
            abs0 = -wrk
          END IF
