                DO nd0=1,nbdirs0
                  srwdd%sna0(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd&
&                   , icv1, 1, is) + (min3dd(nd0, nd)-pld%na(nd, icv1, &
&                   is)*temp4d(nd0)-temp4*pldd%na(nd0, nd, icv1, is)-&
&                   temp8*pld0%na(nd0, icv1, is))/pl%na(icv1, is)
                END DO
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 + temp8
              END DO
              DO nd0=1,nbdirs0
                srwd0%sna0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&                 is) + temp4d(nd0)
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp4
            END IF
          END IF
        END DO
      CASE (15) 
!
! -- BCCON=15 -- prescribe a radial leakage velocity, as a multiplier to the local thermal velocity
!
!srv 25.09.09 16.02.12
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(2a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON = 15 : prescribe the decay length for the density', &
&         ' for drifs switched on ', conpar(is, ib, 1), ' on ', bcchar(&
&         ib), boundary_location(ib), ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 15'&
&                                                           )
        END IF
!wdk      Notes:
!wdk       * need correction for misaligned grids -> t1
!wdk       * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp)
          temp8 = SQRT(arg12)
          t0 = geo%fcqalf(ifc, 1)
          t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&           fcqbet(ifc, 0)
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1
          DO nd0=1,nbdirs0
            arg12d0(nd0) = (pl%te(icv1)*rtd0%rza(nd0, icv1, is)+rt%rza(&
&             icv1, is)*pld0%te(nd0, icv1)+pld0%ti(nd0, icv1))/(am(is)*&
&             mp)
            IF (arg12 .EQ. 0.D0) THEN
              temp4d(nd0) = 0.D0
            ELSE
              temp4d(nd0) = arg12d0(nd0)/(2.0*temp8)
            END IF
            csbd0(nd0) = temp4d(nd0)
            temp1d(nd0) = t0*pld0%na(nd0, icv2, is) - temp2*(pld0%na(nd0&
&             , mpg%fcvx(ifc, 2), is)-pld0%na(nd0, mpg%fcvx(ifc, 1), is)&
&             )
          END DO
          temp4 = temp8
          csb = temp4
          temp1 = t0*pl%na(icv2, is) - temp2*(pl%na(mpg%fcvx(ifc, 2), is&
&           )-pl%na(mpg%fcvx(ifc, 1), is))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              arg12dd(nd0, nd) = (rtd%rza(nd, icv1, is)*pld0%te(nd0, &
&               icv1)+pl%te(icv1)*rtdd%rza(nd0, nd, icv1, is)+pld%te(nd&
&               , icv1)*rtd0%rza(nd0, icv1, is)+rt%rza(icv1, is)*pldd%te&
&               (nd0, nd, icv1)+pldd%ti(nd0, nd, icv1))/(am(is)*mp)
            END DO
            arg12d(nd) = (pl%te(icv1)*rtd%rza(nd, icv1, is)+rt%rza(icv1&
&             , is)*pld%te(nd, icv1)+pld%ti(nd, icv1))/(am(is)*mp)
            IF (arg12 .EQ. 0.d0) THEN
              DO nd0=1,nbdirs0
                csbdd(nd0, nd) = 0.D0
              END DO
              csbd(nd) = 0.d0
            ELSE
              temp8 = arg12d(nd)/(2.0*temp4)
              DO nd0=1,nbdirs0
                csbdd(nd0, nd) = (arg12dd(nd0, nd)-temp8*2.0*temp4d(nd0)&
&                 )/(2.0*temp4)
              END DO
              csbd(nd) = temp8
            END IF
            temp8 = cod%cdna(nd, ifc, 1, is)
            temp10 = t0*pld%na(nd, icv2, is) - temp2*(pld%na(nd, mpg%&
&             fcvx(ifc, 2), is)-pld%na(nd, mpg%fcvx(ifc, 1), is))
            DO nd0=1,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = vbig*(temp8*temp1d(nd0)&
&               +temp1*codd%cdna(nd0, nd, ifc, 1, is)+temp10*cod0%cdna(&
&               nd0, ifc, 1, is)+co%cdna(ifc, 1, is)*(t0*pldd%na(nd0, nd&
&               , icv2, is)-temp2*(pldd%na(nd0, nd, mpg%fcvx(ifc, 2), is&
&               )-pldd%na(nd0, nd, mpg%fcvx(ifc, 1), is))))
              srwdd%sna0(nd0, nd, icv1, 1, is) = -(vbig*(t0*codd%cdna(&
&               nd0, nd, ifc, 1, is)-geo%fcs(ifc)*(conpard(nd, is, ib, 1&
&               )*csbd0(nd0)+csb*conpardd(nd0, nd, is, ib, 1)+csbd(nd)*&
&               conpard0(nd0, is, ib, 1)+conpar(is, ib, 1)*csbdd(nd0, nd&
&               ))))
              sna0_no_mdfdd(nd0, nd, icv1, :, is) = srwdd%sna0(nd0, nd, &
&               icv1, :, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = vbig*(temp1*temp8+co%cdna(ifc, &
&             1, is)*temp10)
            srwd%sna0(nd, icv1, 1, is) = -(vbig*(t0*cod%cdna(nd, ifc, 1&
&             , is)-geo%fcs(ifc)*(csb*conpard(nd, is, ib, 1)+conpar(is, &
&             ib, 1)*csbd(nd))))
            sna0_no_mdfd(nd, icv1, :, is) = srwd%sna0(nd, icv1, :, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = vbig*(temp1*cod0%cdna(nd0, &
&             ifc, 1, is)+co%cdna(ifc, 1, is)*temp1d(nd0))
            srwd0%sna0(nd0, icv1, 1, is) = -(vbig*(t0*cod0%cdna(nd0, ifc&
&             , 1, is)-geo%fcs(ifc)*(csb*conpard0(nd0, is, ib, 1)+conpar&
&             (is, ib, 1)*csbd0(nd0))))
            sna0_no_mdfd0(nd0, icv1, :, is) = srwd0%sna0(nd0, icv1, :, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = vbig*(co%cdna(ifc, 1, is)*temp1)
          srw%sna0(icv1, 1, is) = -(vbig*(co%cdna(ifc, 1, is)*t0-conpar(&
&           is, ib, 1)*geo%fcs(ifc)*csb))
          sna0_no_mdf(icv1, :, is) = srw%sna0(icv1, :, is)
!srv 25.09.09 }
        END DO
      CASE (16) 
!
! -- BCCON=16 -- Feedback boundary condition: given total particle flux with constant density  !srv 16.02.12 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 16 : given total particle flux with constant', &
&         ' density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 16 only applicable to core boundaries !')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 19 .OR. bccon(is, ibw) .EQ. 21)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB(&
&       'BCCON types 16, 19, 21, 22, 23, 25, 26 and 27 cannot be mixed!'&
&                  )
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 16'&
&                          )
        END IF
!srv 16.02.12 }
        IF (.NOT.once_bccon(is)) THEN
          IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  sconpardd(nd0, nd, is) = 0.D0
                END DO
                sconpard(nd, is) = 0.d0
              END DO
              DO nd0=1,nbdirs0
                sconpard0(nd0, is) = 0.D0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      sconpardd(nd0, nd, is) = sconpardd(nd0, nd, is) + &
&                       conpardd(nd0, nd, is, ibw, 1)
                    END DO
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  DO nd0=1,nbdirs0
                    sconpard0(nd0, is) = sconpard0(nd0, is) + conpard0(&
&                     nd0, is, ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=16: Summed value is ', sconpar(is)
            nas = 0.0_R8
            vs = 0.0_R8
            nasd = 0.d0
            nasd0 = 0.D0
            nasdd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      nasdd(nd0, nd) = nasdd(nd0, nd) + geo%cvvol(icv)*&
&                       pldd%na(nd0, nd, icv, is)
                    END DO
                    nasd(nd) = nasd(nd) + geo%cvvol(icv)*pld%na(nd, icv&
&                     , is)
                  END DO
                  DO nd0=1,nbdirs0
                    nasd0(nd0) = nasd0(nd0) + geo%cvvol(icv)*pld0%na(nd0&
&                     , icv, is)
                  END DO
                  nas = nas + pl%na(icv, is)*geo%cvvol(icv)
                  vs = vs + geo%cvvol(icv)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                nasdd(nd0, nd) = nasdd(nd0, nd)/vs
              END DO
              nasd(nd) = nasd(nd)/vs
            END DO
            DO nd0=1,nbdirs0
              nasd0(nd0) = nasd0(nd0)/vs
            END DO
            nas = nas/vs
            totflux = 0.0_R8
            totfluxd = 0.d0
            totfluxd0 = 0.D0
            totfluxdd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                IF (switch%mdf_fnb .NE. 0) THEN
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (dvdd%fna_mdf(nd0, nd, ifc, 0, is)+dvdd%&
&                         fna_mdf(nd0, nd, ifc, 1, is))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna_mdf(&
&                       nd, ifc, 0, is)+dvd%fna_mdf(nd, ifc, 1, is))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%&
&                       fna_mdf(nd0, ifc, 0, is)+dvd0%fna_mdf(nd0, ifc, &
&                       1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna_mdf(ifc, 0, is)+dv&
&                     %fna_mdf(ifc, 1, is))
                  END DO
                ELSE
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (dvdd%fna(nd0, nd, ifc, 0, is)+dvdd%fna(nd0, &
&                         nd, ifc, 1, is))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, &
&                       ifc, 0, is)+dvd%fna(nd, ifc, 1, is))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fna(&
&                       nd0, ifc, 0, is)+dvd0%fna(nd0, ifc, 1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna(ifc, 0, is)+dv%fna&
&                     (ifc, 1, is))
                  END DO
                END IF
              END IF
            END DO
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t3dd(nd0, nd) = conpardd(nd0, nd, is, ib, 2)
                END DO
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              DO nd0=1,nbdirs0
                t3d0(nd0) = conpard0(nd0, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
              t3d0 = 0.D0
              t3dd = 0.D0
            END IF
            IF (totflux .GE. 0.) THEN
              x3 = totflux
            ELSE
              x3 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y7 = sconpar(is)
            ELSE
              y7 = -sconpar(is)
            END IF
            IF (x3 .LT. y7) THEN
              max10 = y7
            ELSE
              max10 = x3
            END IF
            IF (max10 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    x4dd(nd0, nd) = totfluxdd(nd0, nd)
                  END DO
                  x4d(nd) = totfluxd(nd)
                END DO
                DO nd0=1,nbdirs0
                  x4d0(nd0) = totfluxd0(nd0)
                END DO
                x4 = totflux
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    x4dd(nd0, nd) = -totfluxdd(nd0, nd)
                  END DO
                  x4d(nd) = -totfluxd(nd)
                END DO
                DO nd0=1,nbdirs0
                  x4d0(nd0) = -totfluxd0(nd0)
                END DO
                x4 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    y8dd(nd0, nd) = sconpardd(nd0, nd, is)
                  END DO
                  y8d(nd) = sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  y8d0(nd0) = sconpard0(nd0, is)
                END DO
                y8 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    y8dd(nd0, nd) = -sconpardd(nd0, nd, is)
                  END DO
                  y8d(nd) = -sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  y8d0(nd0) = -sconpard0(nd0, is)
                END DO
                y8 = -sconpar(is)
              END IF
              IF (x4 .LT. y8) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max11dd(nd0, nd) = y8dd(nd0, nd)
                  END DO
                  max11d(nd) = y8d(nd)
                END DO
                DO nd0=1,nbdirs0
                  max11d0(nd0) = y8d0(nd0)
                END DO
                max11 = y8
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max11dd(nd0, nd) = x4dd(nd0, nd)
                  END DO
                  max11d(nd) = x4d(nd)
                END DO
                DO nd0=1,nbdirs0
                  max11d0(nd0) = x4d0(nd0)
                END DO
                max11 = x4
              END IF
              temp2 = t3/max11
              DO nd0=1,nbdirs0
                temp2d(nd0) = (t3d0(nd0)-t3*max11d0(nd0)/max11)/max11
                temp4d(nd0) = -(temp2*(totfluxd0(nd0)-sconpard0(nd0, is)&
&                 )+(totflux-sconpar(is))*temp2d(nd0))
              END DO
              temp4 = -((totflux-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                temp10 = t3d(nd) - temp2*max11d(nd)
                temp9 = (totflux-sconpar(is))/max11
                temp6 = totfluxd(nd) - sconpard(nd, is)
                temp11 = temp2*temp6 + temp9*temp10
                DO nd0=1,nbdirs0
                  nasdd(nd0, nd) = nasd(nd)*temp4d(nd0) + temp4*nasdd(&
&                   nd0, nd) - temp11*nasd0(nd0) - nas*(temp6*temp2d(nd0&
&                   )+temp2*(totfluxdd(nd0, nd)-sconpardd(nd0, nd, is))+&
&                   temp10*(totfluxd0(nd0)-sconpard0(nd0, is)-temp9*&
&                   max11d0(nd0))/max11+temp9*(t3dd(nd0, nd)-max11d(nd)*&
&                   temp2d(nd0)-temp2*max11dd(nd0, nd)))
                END DO
                nasd(nd) = temp4*nasd(nd) - nas*temp11
              END DO
              DO nd0=1,nbdirs0
                nasd0(nd0) = temp4*nasd0(nd0) + nas*temp4d(nd0)
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      srwdd%sna0(nd0, nd, icv, 0, is) = geo%fcs(ifc)*&
&                       vbig*nasdd(nd0, nd)
                      srwdd%sna0(nd0, nd, icv, 1, is) = 0.D0
                      sna0_no_mdfdd(nd0, nd, icv, 0, is) = srwdd%sna0(&
&                       nd0, nd, icv, 0, is)
                      sna0_no_mdfdd(nd0, nd, icv, 1, is) = srwdd%sna0(&
&                       nd0, nd, icv, 1, is)
                    END DO
                    srwd%sna0(nd, icv, 0, is) = geo%fcs(ifc)*vbig*nasd(&
&                     nd)
                    srwd%sna0(nd, icv, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv, 0, is) = srwd%sna0(nd, icv, 0&
&                     , is)
                    sna0_no_mdfd(nd, icv, 1, is) = srwd%sna0(nd, icv, 1&
&                     , is)
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%sna0(nd0, icv, 0, is) = geo%fcs(ifc)*vbig*&
&                     nasd0(nd0)
                    srwd0%sna0(nd0, icv, 1, is) = 0.D0
                    sna0_no_mdfd0(nd0, icv, 0, is) = srwd0%sna0(nd0, icv&
&                     , 0, is)
                    sna0_no_mdfd0(nd0, icv, 1, is) = srwd0%sna0(nd0, icv&
&                     , 1, is)
                  END DO
                  srw%sna0(icv, 0, is) = vbig*nas*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          ELSE
!srv 16.02.12 }
            CALL XERRAB('B2STBC -- BCCON=16, NOT AVAILABLE FOR N,W,E')
          END IF
        END IF
      CASE (17) 
!
! -- BCCON=17 -- FILLER
!
        CALL XERRAB('B2STBC -- BCCON=17, NOT YET AVAILABLE')
!
! -- BCCON=18 -- FILLER
!
      CASE (18) 
        CALL XERRAB('B2STBC -- BCCON=18, NOT YET AVAILABLE')
!
! -- BCCON=19 -- Feedback boundary condition: given sum of integrated neutrals and
!                main ion particle fluxes with constant ion density.
!
      CASE (19) 
        IF (switch%spatial_hybrid .NE. 0) CALL XERRAB(&
&                          'BCCON = 19 not compatible with spatial hybr'&
&                                              )
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, *) 'BCCON = 19 : given sum of particle flux '//&
&         'for isonuclear sequence with constant '//&
&         'highest ionisation stage density '
!             write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 19 only applicable to core boundaries !')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 21)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (is .LT. ns - 1) THEN
            result11 = LNEXT(is, is + 1)
            CALL XERTST(.NOT.result11, &
&                 'BCCON = 19 can only be applied to ions in their '//&
&                 'highest ionisation stage')
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 19'&
&                          )
        END IF
!srv 16.02.12 }
        IF (.NOT.once_bccon(is)) THEN
          IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  sconpardd(nd0, nd, is) = 0.D0
                END DO
                sconpard(nd, is) = 0.d0
              END DO
              DO nd0=1,nbdirs0
                sconpard0(nd0, is) = 0.D0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      sconpardd(nd0, nd, is) = sconpardd(nd0, nd, is) + &
&                       conpardd(nd0, nd, is, ibw, 1)
                    END DO
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  DO nd0=1,nbdirs0
                    sconpard0(nd0, is) = sconpard0(nd0, is) + conpard0(&
&                     nd0, is, ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=19: Summed value is ', sconpar(is)
            nas = 0.0_R8
            vs = 0.0_R8
            nasd = 0.d0
            nasd0 = 0.D0
            nasdd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      nasdd(nd0, nd) = nasdd(nd0, nd) + geo%cvvol(icv)*&
&                       pldd%na(nd0, nd, icv, is)
                    END DO
                    nasd(nd) = nasd(nd) + geo%cvvol(icv)*pld%na(nd, icv&
&                     , is)
                  END DO
                  DO nd0=1,nbdirs0
                    nasd0(nd0) = nasd0(nd0) + geo%cvvol(icv)*pld0%na(nd0&
&                     , icv, is)
                  END DO
                  nas = nas + pl%na(icv, is)*geo%cvvol(icv)
                  vs = vs + geo%cvvol(icv)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                nasdd(nd0, nd) = nasdd(nd0, nd)/vs
              END DO
              nasd(nd) = nasd(nd)/vs
            END DO
            DO nd0=1,nbdirs0
              nasd0(nd0) = nasd0(nd0)/vs
            END DO
            nas = nas/vs
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
            totfluxid = 0.d0
            totfluxnd = 0.d0
            totfluxndd = 0.D0
            totfluxidd = 0.D0
            totfluxid0 = 0.D0
            totfluxnd0 = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
! totfluxn here means the sum of fluxes over all ions (including fluid
! neutrals) of this isotope except for the highest ionisation stage.
! For coupled runs, both fna and fna_mdf are rescaled for neutrals
! Note that for neutrals fna = fna_mdf
                  DO isb=0,ns-1
                    IF (b2espcr(is) .EQ. b2espcr(isb) .AND. is .NE. isb&
&                   ) THEN
                      IF ((.NOT.is_neutral(isb)) .OR. switch%use_eirene &
&                         .EQ. 0) THEN
                        IF (switch%mdf_fnb .NE. 0) THEN
                          temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                          DO nd=1,nbdirs
                            DO nd0=nd,nbdirs0
                              totfluxndd(nd0, nd) = totfluxndd(nd0, nd) &
&                               - temp2*(dvdd%fna_mdf(nd0, nd, ifc, 0, &
&                               is)+dvdd%fna_mdf(nd0, nd, ifc, 1, is))
                            END DO
                            totfluxnd(nd) = totfluxnd(nd) - temp2*(dvd%&
&                             fna_mdf(nd, ifc, 0, is)+dvd%fna_mdf(nd, &
&                             ifc, 1, is))
                          END DO
                          DO nd0=1,nbdirs0
                            totfluxnd0(nd0) = totfluxnd0(nd0) - temp2*(&
&                             dvd0%fna_mdf(nd0, ifc, 0, is)+dvd0%fna_mdf&
&                             (nd0, ifc, 1, is))
                          END DO
                          totfluxn = totfluxn - temp2*(dv%fna_mdf(ifc, 0&
&                           , is)+dv%fna_mdf(ifc, 1, is))
                        ELSE
                          temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                          DO nd=1,nbdirs
                            DO nd0=nd,nbdirs0
                              totfluxndd(nd0, nd) = totfluxndd(nd0, nd) &
&                               - temp2*(dvdd%fna(nd0, nd, ifc, 0, is)+&
&                               dvdd%fna(nd0, nd, ifc, 1, is))
                            END DO
                            totfluxnd(nd) = totfluxnd(nd) - temp2*(dvd%&
&                             fna(nd, ifc, 0, is)+dvd%fna(nd, ifc, 1, is&
&                             ))
                          END DO
                          DO nd0=1,nbdirs0
                            totfluxnd0(nd0) = totfluxnd0(nd0) - temp2*(&
&                             dvd0%fna(nd0, ifc, 0, is)+dvd0%fna(nd0, &
&                             ifc, 1, is))
                          END DO
                          totfluxn = totfluxn - temp2*(dv%fna(ifc, 0, is&
&                           )+dv%fna(ifc, 1, is))
                        END IF
                      END IF
                    END IF
                  END DO
! totfluxi here means the flux of the ion in the highest ionisation stage.
                  IF (switch%mdf_fnb .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxidd(nd0, nd) = totfluxidd(nd0, nd) - &
&                         temp2*(dvdd%fna_mdf(nd0, nd, ifc, 0, is)+dvdd%&
&                         fna_mdf(nd0, nd, ifc, 1, is))
                      END DO
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna_mdf&
&                       (nd, ifc, 0, is)+dvd%fna_mdf(nd, ifc, 1, is))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxid0(nd0) = totfluxid0(nd0) - temp2*(dvd0%&
&                       fna_mdf(nd0, ifc, 0, is)+dvd0%fna_mdf(nd0, ifc, &
&                       1, is))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna_mdf(ifc, 0, is)+&
&                     dv%fna_mdf(ifc, 1, is))
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxidd(nd0, nd) = totfluxidd(nd0, nd) - &
&                         temp2*(dvdd%fna(nd0, nd, ifc, 0, is)+dvdd%fna(&
&                         nd0, nd, ifc, 1, is))
                      END DO
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna(nd&
&                       , ifc, 0, is)+dvd%fna(nd, ifc, 1, is))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxid0(nd0) = totfluxid0(nd0) - temp2*(dvd0%&
&                       fna(nd0, ifc, 0, is)+dvd0%fna(nd0, ifc, 1, is))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna(ifc, 0, is)+dv%&
&                     fna(ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t3dd(nd0, nd) = conpardd(nd0, nd, is, ib, 2)
                END DO
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              DO nd0=1,nbdirs0
                t3d0(nd0) = conpard0(nd0, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
              t3d0 = 0.D0
              t3dd = 0.D0
            END IF
            IF (totfluxn + totfluxi .GE. 0.) THEN
              x5 = totfluxn + totfluxi
            ELSE
              x5 = -(totfluxn+totfluxi)
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y9 = sconpar(is)
            ELSE
              y9 = -sconpar(is)
            END IF
            IF (x5 .LT. y9) THEN
              max12 = y9
            ELSE
              max12 = x5
            END IF
            IF (max12 .GT. 0.0_R8) THEN
              IF (totfluxn + totfluxi .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    x6dd(nd0, nd) = totfluxndd(nd0, nd) + totfluxidd(nd0&
&                     , nd)
                  END DO
                  x6d(nd) = totfluxnd(nd) + totfluxid(nd)
                END DO
                DO nd0=1,nbdirs0
                  x6d0(nd0) = totfluxnd0(nd0) + totfluxid0(nd0)
                END DO
                x6 = totfluxn + totfluxi
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    x6dd(nd0, nd) = -totfluxndd(nd0, nd) - totfluxidd(&
&                     nd0, nd)
                  END DO
                  x6d(nd) = -totfluxnd(nd) - totfluxid(nd)
                END DO
                DO nd0=1,nbdirs0
                  x6d0(nd0) = -totfluxnd0(nd0) - totfluxid0(nd0)
                END DO
                x6 = -(totfluxn+totfluxi)
              END IF
              IF (x6 .LT. sconpar(is)) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max13dd(nd0, nd) = sconpardd(nd0, nd, is)
                  END DO
                  max13d(nd) = sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  max13d0(nd0) = sconpard0(nd0, is)
                END DO
                max13 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max13dd(nd0, nd) = x6dd(nd0, nd)
                  END DO
                  max13d(nd) = x6d(nd)
                END DO
                DO nd0=1,nbdirs0
                  max13d0(nd0) = x6d0(nd0)
                END DO
                max13 = x6
              END IF
              temp2 = t3/max13
              DO nd0=1,nbdirs0
                temp2d(nd0) = (t3d0(nd0)-t3*max13d0(nd0)/max13)/max13
                temp4d(nd0) = -(temp2*(totfluxnd0(nd0)+totfluxid0(nd0)-&
&                 sconpard0(nd0, is))+(totfluxn+totfluxi-sconpar(is))*&
&                 temp2d(nd0))
              END DO
              temp4 = -((totfluxn+totfluxi-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                temp11 = t3d(nd) - temp2*max13d(nd)
                temp10 = (totfluxn+totfluxi-sconpar(is))/max13
                temp9 = totfluxnd(nd) + totfluxid(nd) - sconpard(nd, is)
                temp6 = temp2*temp9 + temp10*temp11
                DO nd0=1,nbdirs0
                  nasdd(nd0, nd) = nasd(nd)*temp4d(nd0) + temp4*nasdd(&
&                   nd0, nd) - temp6*nasd0(nd0) - nas*(temp9*temp2d(nd0)&
&                   +temp2*(totfluxndd(nd0, nd)+totfluxidd(nd0, nd)-&
&                   sconpardd(nd0, nd, is))+temp11*(totfluxnd0(nd0)+&
&                   totfluxid0(nd0)-sconpard0(nd0, is)-temp10*max13d0(&
&                   nd0))/max13+temp10*(t3dd(nd0, nd)-max13d(nd)*temp2d(&
&                   nd0)-temp2*max13dd(nd0, nd)))
                END DO
                nasd(nd) = temp4*nasd(nd) - nas*temp6
              END DO
              DO nd0=1,nbdirs0
                nasd0(nd0) = temp4*nasd0(nd0) + nas*temp4d(nd0)
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,es14.7,a,es14.7)') &
&           ' NAS=', nas, ' totfluxn=', totfluxn, ' totfluxi=', totfluxi&
&           , ' SCONPAR=', sconpar(is), ' totfluxn+totfluxi=', totfluxn &
&           + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      srwdd%sna0(nd0, nd, icv, 0, is) = geo%fcs(ifc)*&
&                       vbig*nasdd(nd0, nd)
                      srwdd%sna0(nd0, nd, icv, 1, is) = 0.D0
                      sna0_no_mdfdd(nd0, nd, icv, 0, is) = srwdd%sna0(&
&                       nd0, nd, icv, 0, is)
                      sna0_no_mdfdd(nd0, nd, icv, 1, is) = srwdd%sna0(&
&                       nd0, nd, icv, 1, is)
                    END DO
                    srwd%sna0(nd, icv, 0, is) = geo%fcs(ifc)*vbig*nasd(&
&                     nd)
                    srwd%sna0(nd, icv, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv, 0, is) = srwd%sna0(nd, icv, 0&
&                     , is)
                    sna0_no_mdfd(nd, icv, 1, is) = srwd%sna0(nd, icv, 1&
&                     , is)
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%sna0(nd0, icv, 0, is) = geo%fcs(ifc)*vbig*&
&                     nasd0(nd0)
                    srwd0%sna0(nd0, icv, 1, is) = 0.D0
                    sna0_no_mdfd0(nd0, icv, 0, is) = srwd0%sna0(nd0, icv&
&                     , 0, is)
                    sna0_no_mdfd0(nd0, icv, 1, is) = srwd0%sna0(nd0, icv&
&                     , 1, is)
                  END DO
                  srw%sna0(icv, 0, is) = vbig*nas*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          ELSE
!srv 16.02.12 }
            CALL XERRAB('B2STBC -- BCCON=19, NOT AVAILABLE FOR N,W,E')
          END IF
        END IF
      CASE (20) 
!
! -- BCCON=20 -- constant density feedback condition
!
        CALL XERRAB('b2stbc_phys -- BCCON = 20 not adapted for WG')
!
!    -- BCCON=21 -- PRESCRIBE THE VALUE OF THE DENSITY !lk and IYS 01.03.2013
!                   AND ADD A POLOIDAL DENSITY VARIATION TO GET A SOLUTION
!                   WHICH IS AS CLOSE AS POSSIBLE TO NEOCLASSICAL THEORY
!                   DERIVED FOR PURE H/D/T PLASMA ONLY.
!
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
! CORRESPONDING CONDITION ON ION TEMPERATURE (BCENI=23,24)
!
      CASE (21) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7)') 'BCCON = 21 : constant density', &
&         conpar(is, ib, 1)
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 21 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&                   'BCCON = 21, CONPAR(,,1) !> 0')
! IYS 22.01.2015
              CALL XERTST(conpar(is, ib, 1) .EQ. conpar(is, ibw, 1), &
&                   'BCCON = 21, Average density on all parts '//&
&                   'of the surface should be the same')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.21 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.21 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 21 is applied for main ion only ')
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=21 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=25 instead!'
            WRITE(6, *) &
&           'Use of BCCON=21 only meant for single-fluid runs!'
            WRITE(6, *) 'Use BCCON=25 instead!'
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 21'&
&                          )
        END IF
!lk and IYS 01.03.2013}
        IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') .AND. mpg%&
&           cvonclosedsurface(mpg%bccv(mpg%bccvp(ibw, 1), 2))) THEN
          IF (.NOT.once_bccon(is)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            t1d = 0.d0
            t1d0 = 0.D0
            t1dd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  t0 = t0 + geo%cvvol(icv2)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*(&
&                       pldd%ti(nd0, nd, icv1)+pldd%te(nd0, nd, icv1))
                    END DO
                    t1d(nd) = t1d(nd) + geo%cvvol(icv2)*(pld%ti(nd, icv1&
&                     )+pld%te(nd, icv1))
                  END DO
                  DO nd0=1,nbdirs0
                    t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*(pld0%ti(nd0&
&                     , icv1)+pld0%te(nd0, icv1))
                  END DO
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                END DO
              END IF
            END DO
! Sum of volume-averaged electron and ion temperatures
            IF (t0 .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t1dd(nd0, nd) = t1dd(nd0, nd)/t0
                END DO
                t1d(nd) = t1d(nd)/t0
              END DO
              DO nd0=1,nbdirs0
                t1d0(nd0) = t1d0(nd0)/t0
              END DO
              t1 = t1/t0
            END IF
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  temp2 = vbig*geo%fcs(ifc)
                  temp4 = pl%ti(icv) + pl%te(icv)
                  temp11 = t1/temp4
                  DO nd0=1,nbdirs0
                    temp4d(nd0) = pld0%ti(nd0, icv) + pld0%te(nd0, icv)
                    temp1d(nd0) = temp11*conpard0(nd0, is, ibw, 1) + &
&                     conpar(is, ibw, 1)*(t1d0(nd0)-temp11*temp4d(nd0))/&
&                     temp4
                  END DO
                  temp1 = conpar(is, ibw, 1)*temp11
                  DO nd=1,nbdirs
                    temp8 = pld%ti(nd, icv) + pld%te(nd, icv)
                    temp11 = (t1*conpard(nd, is, ibw, 1)+conpar(is, ibw&
&                     , 1)*t1d(nd)-temp1*temp8)/temp4
                    DO nd0=1,nbdirs0
                      srwdd%sna0(nd0, nd, icv, 0, is) = temp2*(conpard(&
&                       nd, is, ibw, 1)*t1d0(nd0)+t1*conpardd(nd0, nd, &
&                       is, ibw, 1)+t1d(nd)*conpard0(nd0, is, ibw, 1)+&
&                       conpar(is, ibw, 1)*t1dd(nd0, nd)-temp8*temp1d(&
&                       nd0)-temp1*(pldd%ti(nd0, nd, icv)+pldd%te(nd0, &
&                       nd, icv))-temp11*temp4d(nd0))/temp4
                      srwdd%sna0(nd0, nd, icv, 1, is) = 0.D0
                      sna0_no_mdfdd(nd0, nd, icv, 0, is) = srwdd%sna0(&
&                       nd0, nd, icv, 0, is)
                      sna0_no_mdfdd(nd0, nd, icv, 1, is) = srwdd%sna0(&
&                       nd0, nd, icv, 1, is)
                    END DO
                    srwd%sna0(nd, icv, 0, is) = temp2*temp11
                    srwd%sna0(nd, icv, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv, 0, is) = srwd%sna0(nd, icv, 0&
&                     , is)
                    sna0_no_mdfd(nd, icv, 1, is) = srwd%sna0(nd, icv, 1&
&                     , is)
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%sna0(nd0, icv, 0, is) = temp2*temp1d(nd0)
                    srwd0%sna0(nd0, icv, 1, is) = 0.D0
                    sna0_no_mdfd0(nd0, icv, 0, is) = srwd0%sna0(nd0, icv&
&                     , 0, is)
                    sna0_no_mdfd0(nd0, icv, 1, is) = srwd0%sna0(nd0, icv&
&                     , 1, is)
                  END DO
                  srw%sna0(icv, 0, is) = temp2*temp1
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCCON=21, VALID FOR CORE ONLY')
        END IF
      CASE (22) 
!
! -- BCCON=22 -- Feedback boundary condition: given total particle flux with
!    constant average density. The poloidal density variation is added to make
!    the solution as close as possible to the neoclassical value derived for
!    pure H/D/T plasma.
!    It is recommended to use this boundary condition
!    together with corresponding boundary condition on ion temperature
!    (BCENI=23,24) !srv 16.02.12, IYS 01.03.2013 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 22 : given total particle flux with constant', &
&         ' density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 22 only applicable to core boundaries !')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.22 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.22 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 22 is applied for main ion only ')
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=22 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=26 instead!'
            WRITE(6, *) &
&           'Use of BCCON=22 only meant for single-fluid runs!'
            WRITE(6, *) 'Use BCCON=26 instead!'
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 22'&
&                          )
        END IF
!iys 01.03.13 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  sconpardd(nd0, nd, is) = 0.D0
                END DO
                sconpard(nd, is) = 0.d0
              END DO
              DO nd0=1,nbdirs0
                sconpard0(nd0, is) = 0.D0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      sconpardd(nd0, nd, is) = sconpardd(nd0, nd, is) + &
&                       conpardd(nd0, nd, is, ibw, 1)
                    END DO
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  DO nd0=1,nbdirs0
                    sconpard0(nd0, is) = sconpard0(nd0, is) + conpard0(&
&                     nd0, is, ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=22: Summed value is ', sconpar(is)
            totflux = 0.0_R8
! Volume between two surfaces             !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            nas = 0.0_R8
            nasd = 0.d0
            totfluxd = 0.d0
            t1d = 0.d0
            nasd0 = 0.D0
            nasdd = 0.D0
            totfluxd0 = 0.D0
            t1d0 = 0.D0
            totfluxdd = 0.D0
            t1dd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  t0 = t0 + geo%cvvol(icv2)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*(&
&                       pldd%ti(nd0, nd, icv1)+pldd%te(nd0, nd, icv1))
                      nasdd(nd0, nd) = nasdd(nd0, nd) + geo%cvvol(icv2)*&
&                       pldd%na(nd0, nd, icv1, is)
                    END DO
                    t1d(nd) = t1d(nd) + geo%cvvol(icv2)*(pld%ti(nd, icv1&
&                     )+pld%te(nd, icv1))
                    nasd(nd) = nasd(nd) + geo%cvvol(icv2)*pld%na(nd, &
&                     icv1, is)
                  END DO
                  DO nd0=1,nbdirs0
                    t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*(pld0%ti(nd0&
&                     , icv1)+pld0%te(nd0, icv1))
                    nasd0(nd0) = nasd0(nd0) + geo%cvvol(icv2)*pld0%na(&
&                     nd0, icv1, is)
                  END DO
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                  IF (switch%mdf_fnb .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (dvdd%fna_mdf(nd0, nd, ifc, 0, is)+dvdd%&
&                         fna_mdf(nd0, nd, ifc, 1, is))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna_mdf(&
&                       nd, ifc, 0, is)+dvd%fna_mdf(nd, ifc, 1, is))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%&
&                       fna_mdf(nd0, ifc, 0, is)+dvd0%fna_mdf(nd0, ifc, &
&                       1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna_mdf(ifc, 0, is)+dv&
&                     %fna_mdf(ifc, 1, is))
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (dvdd%fna(nd0, nd, ifc, 0, is)+dvdd%fna(nd0, &
&                         nd, ifc, 1, is))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, &
&                       ifc, 0, is)+dvd%fna(nd, ifc, 1, is))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fna(&
&                       nd0, ifc, 0, is)+dvd0%fna(nd0, ifc, 1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna(ifc, 0, is)+dv%fna&
&                     (ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
! Sum of volume-averaged electron and ion temperatures
                t1dd(nd0, nd) = t1dd(nd0, nd)/t0
! Volume-averaged density
                nasdd(nd0, nd) = nasdd(nd0, nd)/t0
              END DO
              t1d(nd) = t1d(nd)/t0
              nasd(nd) = nasd(nd)/t0
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0)/t0
              nasd0(nd0) = nasd0(nd0)/t0
            END DO
            t1 = t1/t0
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t3dd(nd0, nd) = conpardd(nd0, nd, is, ib, 2)
                END DO
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              DO nd0=1,nbdirs0
                t3d0(nd0) = conpard0(nd0, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
              t3d0 = 0.D0
              t3dd = 0.D0
            END IF
            IF (totflux .GE. 0.) THEN
              x7 = totflux
            ELSE
              x7 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y10 = sconpar(is)
            ELSE
              y10 = -sconpar(is)
            END IF
            IF (x7 .LT. y10) THEN
              max14 = y10
            ELSE
              max14 = x7
            END IF
            IF (max14 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    x8dd(nd0, nd) = totfluxdd(nd0, nd)
                  END DO
                  x8d(nd) = totfluxd(nd)
                END DO
                DO nd0=1,nbdirs0
                  x8d0(nd0) = totfluxd0(nd0)
                END DO
                x8 = totflux
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    x8dd(nd0, nd) = -totfluxdd(nd0, nd)
                  END DO
                  x8d(nd) = -totfluxd(nd)
                END DO
                DO nd0=1,nbdirs0
                  x8d0(nd0) = -totfluxd0(nd0)
                END DO
                x8 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    y11dd(nd0, nd) = sconpardd(nd0, nd, is)
                  END DO
                  y11d(nd) = sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  y11d0(nd0) = sconpard0(nd0, is)
                END DO
                y11 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    y11dd(nd0, nd) = -sconpardd(nd0, nd, is)
                  END DO
                  y11d(nd) = -sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  y11d0(nd0) = -sconpard0(nd0, is)
                END DO
                y11 = -sconpar(is)
              END IF
              IF (x8 .LT. y11) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max15dd(nd0, nd) = y11dd(nd0, nd)
                  END DO
                  max15d(nd) = y11d(nd)
                END DO
                DO nd0=1,nbdirs0
                  max15d0(nd0) = y11d0(nd0)
                END DO
                max15 = y11
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max15dd(nd0, nd) = x8dd(nd0, nd)
                  END DO
                  max15d(nd) = x8d(nd)
                END DO
                DO nd0=1,nbdirs0
                  max15d0(nd0) = x8d0(nd0)
                END DO
                max15 = x8
              END IF
              temp2 = t3/max15
              DO nd0=1,nbdirs0
                temp2d(nd0) = (t3d0(nd0)-t3*max15d0(nd0)/max15)/max15
                temp4d(nd0) = -(temp2*(totfluxd0(nd0)-sconpard0(nd0, is)&
&                 )+(totflux-sconpar(is))*temp2d(nd0))
              END DO
              temp4 = -((totflux-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                temp11 = t3d(nd) - temp2*max15d(nd)
                temp10 = (totflux-sconpar(is))/max15
                temp9 = totfluxd(nd) - sconpard(nd, is)
                temp6 = temp2*temp9 + temp10*temp11
                DO nd0=1,nbdirs0
                  nasdd(nd0, nd) = nasd(nd)*temp4d(nd0) + temp4*nasdd(&
&                   nd0, nd) - temp6*nasd0(nd0) - nas*(temp9*temp2d(nd0)&
&                   +temp2*(totfluxdd(nd0, nd)-sconpardd(nd0, nd, is))+&
&                   temp11*(totfluxd0(nd0)-sconpard0(nd0, is)-temp10*&
&                   max15d0(nd0))/max15+temp10*(t3dd(nd0, nd)-max15d(nd)&
&                   *temp2d(nd0)-temp2*max15dd(nd0, nd)))
                END DO
                nasd(nd) = temp4*nasd(nd) - nas*temp6
              END DO
              DO nd0=1,nbdirs0
                nasd0(nd0) = temp4*nasd0(nd0) + nas*temp4d(nd0)
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  temp2 = vbig*geo%fcs(ifc)
                  temp4 = pl%ti(icv) + pl%te(icv)
                  temp11 = nas*t1/temp4
                  DO nd0=1,nbdirs0
                    temp4d(nd0) = pld0%ti(nd0, icv) + pld0%te(nd0, icv)
                    temp1d(nd0) = (t1*nasd0(nd0)+nas*t1d0(nd0)-temp11*&
&                     temp4d(nd0))/temp4
                  END DO
                  temp1 = temp11
                  DO nd=1,nbdirs
                    temp8 = pld%ti(nd, icv) + pld%te(nd, icv)
                    temp11 = (t1*nasd(nd)+nas*t1d(nd)-temp1*temp8)/temp4
                    DO nd0=1,nbdirs0
                      srwdd%sna0(nd0, nd, icv, 0, is) = temp2*(nasd(nd)*&
&                       t1d0(nd0)+t1*nasdd(nd0, nd)+t1d(nd)*nasd0(nd0)+&
&                       nas*t1dd(nd0, nd)-temp8*temp1d(nd0)-temp1*(pldd%&
&                       ti(nd0, nd, icv)+pldd%te(nd0, nd, icv))-temp11*&
&                       temp4d(nd0))/temp4
                      srwdd%sna0(nd0, nd, icv, 1, is) = 0.D0
                      sna0_no_mdfdd(nd0, nd, icv, 0, is) = srwdd%sna0(&
&                       nd0, nd, icv, 0, is)
                      sna0_no_mdfdd(nd0, nd, icv, 1, is) = srwdd%sna0(&
&                       nd0, nd, icv, 1, is)
                    END DO
                    srwd%sna0(nd, icv, 0, is) = temp2*temp11
                    srwd%sna0(nd, icv, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv, 0, is) = srwd%sna0(nd, icv, 0&
&                     , is)
                    sna0_no_mdfd(nd, icv, 1, is) = srwd%sna0(nd, icv, 1&
&                     , is)
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%sna0(nd0, icv, 0, is) = temp2*temp1d(nd0)
                    srwd0%sna0(nd0, icv, 1, is) = 0.D0
                    sna0_no_mdfd0(nd0, icv, 0, is) = srwd0%sna0(nd0, icv&
&                     , 0, is)
                    sna0_no_mdfd0(nd0, icv, 1, is) = srwd0%sna0(nd0, icv&
&                     , 1, is)
                  END DO
                  srw%sna0(icv, 0, is) = temp2*temp1
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=22 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (23) 
!
! -- BCCON=23 -- Feedback boundary condition: given sum of integrated neutrals and
!    main ion particle fluxes with constant average density.
!    The poloidal density variation is added to make the solution
!    as close as possible to the neoclassical value derived for pure H/D/T plasma.
!    It is recommended to use this boundary condition with corresponding
!    boundary condition on ion temperature (BCENI=23,24) !srv 16.02.12, IYS 04.03.2013 {
!    Use this boundary condition for pure H/D/T plasma only,
!    If a minor impurity is present, please use the BCCON=27 instead. ! IYS 21.01.2016
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 23 : given total particle flux with constant', &
&         ' density for main ion is =', ismain
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 23 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GE. 0.0_R8, &
&                   'BCCON = 23, CONPAR(,,1) < 0')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.23 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.23 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=23 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=27 instead!'
            WRITE(6, *) &
&           'Use of BCCON=23 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=27 instead!'
          END IF
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 23 is applied for main ion only ')
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 23'&
&                          )
        END IF
!IYS 04.03.2013 }
!
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  sconpardd(nd0, nd, is) = 0.D0
                END DO
                sconpard(nd, is) = 0.d0
              END DO
              DO nd0=1,nbdirs0
                sconpard0(nd0, is) = 0.D0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      sconpardd(nd0, nd, is) = sconpardd(nd0, nd, is) + &
&                       conpardd(nd0, nd, is, ibw, 1)
                    END DO
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  DO nd0=1,nbdirs0
                    sconpard0(nd0, is) = sconpard0(nd0, is) + conpard0(&
&                     nd0, is, ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=23: Summed value is ', sconpar(is)
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            nas = 0.0_R8
            nasd = 0.d0
            t1d = 0.d0
            totfluxid = 0.d0
            totfluxnd = 0.d0
            nasd0 = 0.D0
            nasdd = 0.D0
            totfluxndd = 0.D0
            t1d0 = 0.D0
            totfluxidd = 0.D0
            totfluxid0 = 0.D0
            totfluxnd0 = 0.D0
            t1dd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  isb = ismain0
                  IF (is_neutral(isb)) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxndd(nd0, nd) = totfluxndd(nd0, nd) - &
&                         temp2*(dvdd%fna(nd0, nd, ifc, 0, isb)+dvdd%fna&
&                         (nd0, nd, ifc, 1, isb))
                      END DO
                      totfluxnd(nd) = totfluxnd(nd) - temp2*(dvd%fna(nd&
&                       , ifc, 0, isb)+dvd%fna(nd, ifc, 1, isb))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxnd0(nd0) = totfluxnd0(nd0) - temp2*(dvd0%&
&                       fna(nd0, ifc, 0, isb)+dvd0%fna(nd0, ifc, 1, isb)&
&                       )
                    END DO
                    totfluxn = totfluxn - temp2*(dv%fna(ifc, 0, isb)+dv%&
&                     fna(ifc, 1, isb))
                  END IF
                  isb = ismain
                  IF (switch%mdf_fnb .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxidd(nd0, nd) = totfluxidd(nd0, nd) - &
&                         temp2*(dvdd%fna_mdf(nd0, nd, ifc, 0, isb)+dvdd&
&                         %fna_mdf(nd0, nd, ifc, 1, isb))
                      END DO
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna_mdf&
&                       (nd, ifc, 0, isb)+dvd%fna_mdf(nd, ifc, 1, isb))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxid0(nd0) = totfluxid0(nd0) - temp2*(dvd0%&
&                       fna_mdf(nd0, ifc, 0, isb)+dvd0%fna_mdf(nd0, ifc&
&                       , 1, isb))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna_mdf(ifc, 0, isb)&
&                     +dv%fna_mdf(ifc, 1, isb))
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxidd(nd0, nd) = totfluxidd(nd0, nd) - &
&                         temp2*(dvdd%fna(nd0, nd, ifc, 0, isb)+dvdd%fna&
&                         (nd0, nd, ifc, 1, isb))
                      END DO
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna(nd&
&                       , ifc, 0, isb)+dvd%fna(nd, ifc, 1, isb))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxid0(nd0) = totfluxid0(nd0) - temp2*(dvd0%&
&                       fna(nd0, ifc, 0, isb)+dvd0%fna(nd0, ifc, 1, isb)&
&                       )
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna(ifc, 0, isb)+dv%&
&                     fna(ifc, 1, isb))
                  END IF
                  t0 = t0 + geo%cvvol(icv2)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*(&
&                       pldd%ti(nd0, nd, icv1)+pldd%te(nd0, nd, icv1))
                      nasdd(nd0, nd) = nasdd(nd0, nd) + geo%cvvol(icv2)*&
&                       pldd%na(nd0, nd, icv1, is)
                    END DO
                    t1d(nd) = t1d(nd) + geo%cvvol(icv2)*(pld%ti(nd, icv1&
&                     )+pld%te(nd, icv1))
                    nasd(nd) = nasd(nd) + geo%cvvol(icv2)*pld%na(nd, &
&                     icv1, is)
                  END DO
                  DO nd0=1,nbdirs0
                    t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*(pld0%ti(nd0&
&                     , icv1)+pld0%te(nd0, icv1))
                    nasd0(nd0) = nasd0(nd0) + geo%cvvol(icv2)*pld0%na(&
&                     nd0, icv1, is)
                  END DO
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
! Sum of volume-averaged electron and ion temperatures
                t1dd(nd0, nd) = t1dd(nd0, nd)/t0
! Volume-averaged density
                nasdd(nd0, nd) = nasdd(nd0, nd)/t0
              END DO
              t1d(nd) = t1d(nd)/t0
              nasd(nd) = nasd(nd)/t0
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0)/t0
              nasd0(nd0) = nasd0(nd0)/t0
            END DO
            t1 = t1/t0
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t3dd(nd0, nd) = conpardd(nd0, nd, is, ib, 2)
                END DO
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              DO nd0=1,nbdirs0
                t3d0(nd0) = conpard0(nd0, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
              t3d0 = 0.D0
              t3dd = 0.D0
            END IF
            IF (totfluxn .GE. 0.) THEN
              abs1 = totfluxn
            ELSE
              abs1 = -totfluxn
            END IF
            IF (totfluxi .GE. 0.) THEN
              abs7 = totfluxi
            ELSE
              abs7 = -totfluxi
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              abs11 = sconpar(is)
            ELSE
              abs11 = -sconpar(is)
            END IF
            IF (abs1 + abs7 + abs11 .GT. 0.0_R8) THEN
              IF (totfluxn .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs2dd(nd0, nd) = totfluxndd(nd0, nd)
                  END DO
                  abs2d(nd) = totfluxnd(nd)
                END DO
                DO nd0=1,nbdirs0
                  abs2d0(nd0) = totfluxnd0(nd0)
                END DO
                abs2 = totfluxn
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs2dd(nd0, nd) = -totfluxndd(nd0, nd)
                  END DO
                  abs2d(nd) = -totfluxnd(nd)
                END DO
                DO nd0=1,nbdirs0
                  abs2d0(nd0) = -totfluxnd0(nd0)
                END DO
                abs2 = -totfluxn
              END IF
              IF (totfluxi .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs8dd(nd0, nd) = totfluxidd(nd0, nd)
                  END DO
                  abs8d(nd) = totfluxid(nd)
                END DO
                DO nd0=1,nbdirs0
                  abs8d0(nd0) = totfluxid0(nd0)
                END DO
                abs8 = totfluxi
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs8dd(nd0, nd) = -totfluxidd(nd0, nd)
                  END DO
                  abs8d(nd) = -totfluxid(nd)
                END DO
                DO nd0=1,nbdirs0
                  abs8d0(nd0) = -totfluxid0(nd0)
                END DO
                abs8 = -totfluxi
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs12dd(nd0, nd) = sconpardd(nd0, nd, is)
                  END DO
                  abs12d(nd) = sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  abs12d0(nd0) = sconpard0(nd0, is)
                END DO
                abs12 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs12dd(nd0, nd) = -sconpardd(nd0, nd, is)
                  END DO
                  abs12d(nd) = -sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  abs12d0(nd0) = -sconpard0(nd0, is)
                END DO
                abs12 = -sconpar(is)
              END IF
              temp11 = t3/(abs2+abs8+abs12)
              temp2 = temp11
              DO nd0=1,nbdirs0
                temp2d(nd0) = (t3d0(nd0)-temp11*(abs2d0(nd0)+abs8d0(nd0)&
&                 +abs12d0(nd0)))/(abs2+abs8+abs12)
                temp4d(nd0) = -(temp2*(totfluxnd0(nd0)+totfluxid0(nd0)-&
&                 sconpard0(nd0, is))+(totfluxn+totfluxi-sconpar(is))*&
&                 temp2d(nd0))
              END DO
              temp4 = -((totfluxn+totfluxi-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                temp11 = abs2d(nd) + abs8d(nd) + abs12d(nd)
                temp10 = t3d(nd) - temp2*temp11
                temp9 = (totfluxn+totfluxi-sconpar(is))/(abs2+abs8+abs12&
&                 )
                temp6 = totfluxnd(nd) + totfluxid(nd) - sconpard(nd, is)
                temp12 = temp2*temp6 + temp9*temp10
                DO nd0=1,nbdirs0
                  nasdd(nd0, nd) = nasd(nd)*temp4d(nd0) + temp4*nasdd(&
&                   nd0, nd) - temp12*nasd0(nd0) - nas*(temp6*temp2d(nd0&
&                   )+temp2*(totfluxndd(nd0, nd)+totfluxidd(nd0, nd)-&
&                   sconpardd(nd0, nd, is))+temp10*(totfluxnd0(nd0)+&
&                   totfluxid0(nd0)-sconpard0(nd0, is)-temp9*(abs2d0(nd0&
&                   )+abs8d0(nd0)+abs12d0(nd0)))/(abs2+abs8+abs12)+temp9&
&                   *(t3dd(nd0, nd)-temp11*temp2d(nd0)-temp2*(abs2dd(nd0&
&                   , nd)+abs8dd(nd0, nd)+abs12dd(nd0, nd))))
                END DO
                nasd(nd) = temp4*nasd(nd) - nas*temp12
              END DO
              DO nd0=1,nbdirs0
                nasd0(nd0) = temp4*nasd0(nd0) + nas*temp4d(nd0)
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(5(a,es14.7))') ' NAS=', nas, ' totfluxn=', &
&           totfluxn, ' totfluxi=', totfluxi, ' SCONPAR=', sconpar(is), &
&           ' totfluxn+totfluxi=', totfluxn + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  temp2 = vbig*geo%fcs(ifc)
                  temp4 = pl%ti(icv) + pl%te(icv)
                  temp12 = nas*t1/temp4
                  DO nd0=1,nbdirs0
                    temp4d(nd0) = pld0%ti(nd0, icv) + pld0%te(nd0, icv)
                    temp1d(nd0) = (t1*nasd0(nd0)+nas*t1d0(nd0)-temp12*&
&                     temp4d(nd0))/temp4
                  END DO
                  temp1 = temp12
                  DO nd=1,nbdirs
                    temp8 = pld%ti(nd, icv) + pld%te(nd, icv)
                    temp12 = (t1*nasd(nd)+nas*t1d(nd)-temp1*temp8)/temp4
                    DO nd0=1,nbdirs0
                      srwdd%sna0(nd0, nd, icv, 0, is) = temp2*(nasd(nd)*&
&                       t1d0(nd0)+t1*nasdd(nd0, nd)+t1d(nd)*nasd0(nd0)+&
&                       nas*t1dd(nd0, nd)-temp8*temp1d(nd0)-temp1*(pldd%&
&                       ti(nd0, nd, icv)+pldd%te(nd0, nd, icv))-temp12*&
&                       temp4d(nd0))/temp4
                      srwdd%sna0(nd0, nd, icv, 1, is) = 0.D0
                      sna0_no_mdfdd(nd0, nd, icv, 0, is) = srwdd%sna0(&
&                       nd0, nd, icv, 0, is)
                      sna0_no_mdfdd(nd0, nd, icv, 1, is) = srwdd%sna0(&
&                       nd0, nd, icv, 1, is)
                    END DO
                    srwd%sna0(nd, icv, 0, is) = temp2*temp12
                    srwd%sna0(nd, icv, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv, 0, is) = srwd%sna0(nd, icv, 0&
&                     , is)
                    sna0_no_mdfd(nd, icv, 1, is) = srwd%sna0(nd, icv, 1&
&                     , is)
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%sna0(nd0, icv, 0, is) = temp2*temp1d(nd0)
                    srwd0%sna0(nd0, icv, 1, is) = 0.D0
                    sna0_no_mdfd0(nd0, icv, 0, is) = srwd0%sna0(nd0, icv&
&                     , 0, is)
                    sna0_no_mdfd0(nd0, icv, 1, is) = srwd0%sna0(nd0, icv&
&                     , 1, is)
                  END DO
                  srw%sna0(icv, 0, is) = temp2*temp1
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=23 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (24) 
!
! -- BCCON=24 -- constant density scaled by density on the ring bc_type21_ref away
!
        CALL XERRAB('b2stbc_phys -- BCCON = 24 not adapted for WG')
!
! -- BCCON=25  Feedback boundary condition: PRESCRIBE THE AVERAGE VALUE OF THE DENSITY  !lk and IYS 01.03.2013{
!              AND ADD A POLOIDAL DENSITY VARIATION FROM NEIGHBOURING RADIAL CELL.
!              THIS BOUNDARY CONDITION IS SUITABLE FOR ANY SPECIES OF
!              MULTI-SPECIES PLASMA (I.E. IN THE CASE WHEN THE CONDITION USED
!              IN BCCON=21 FAILS)
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              CORRESPONDING CONDITION ON ION TEMPERATURE (BCENI=26,27)
!
      CASE (25) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7)') &
&         'BCCON = 25 : constant average density', conpar(is, ib, 1)
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 25 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GT. 0.0_R8, &
&                   'BCCON = 25, CONPAR(,,1) !> 0')
! IYS 22.01.2015
              CALL XERTST(conpar(is, ib, 1) .EQ. conpar(is, ibw, 1), &
&                   'BCCON = 25, Average density on all parts '//&
&                   'of the surface should be the same')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.25 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.25 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 25'&
&                          )
        END IF
!lk and IYS 01.03.2013}
!
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
          IF (.NOT.once_bccon(is)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
! Volume between two surfaces              !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged density
            t1 = 0.0_R8
            t1d = 0.d0
            t1d0 = 0.D0
            t1dd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  t0 = t0 + geo%cvvol(icv)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv)*&
&                       pldd%na(nd0, nd, icv, is)
                    END DO
                    t1d(nd) = t1d(nd) + geo%cvvol(icv)*pld%na(nd, icv, &
&                     is)
                  END DO
                  DO nd0=1,nbdirs0
                    t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv)*pld0%na(nd0, &
&                     icv, is)
                  END DO
                  t1 = t1 + pl%na(icv, is)*geo%cvvol(icv)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t1dd(nd0, nd) = t1dd(nd0, nd)/t0
              END DO
              t1d(nd) = t1d(nd)/t0
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0)/t0
            END DO
            t1 = t1/t0
            DO ibw=ib,nbc
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                temp2 = vbig*geo%fcs(ifc)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    srwdd%sna0(nd0, nd, icv1, 0, is) = temp2*(conpardd(&
&                     nd0, nd, is, ibw, 1)+pldd%na(nd0, nd, icv2, is)-&
&                     t1dd(nd0, nd))
                    srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
                    sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0&
&                     , nd, icv1, 0, is)
                    sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0&
&                     , nd, icv1, 1, is)
                  END DO
                  srwd%sna0(nd, icv1, 0, is) = temp2*(conpard(nd, is, &
&                   ibw, 1)+pld%na(nd, icv2, is)-t1d(nd))
                  srwd%sna0(nd, icv1, 1, is) = 0.d0
                  sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0&
&                   , is)
                  sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1&
&                   , is)
                END DO
                DO nd0=1,nbdirs0
                  srwd0%sna0(nd0, icv1, 0, is) = temp2*(conpard0(nd0, is&
&                   , ibw, 1)+pld0%na(nd0, icv2, is)-t1d0(nd0))
                  srwd0%sna0(nd0, icv1, 1, is) = 0.D0
                  sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1&
&                   , 0, is)
                  sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1&
&                   , 1, is)
                END DO
                srw%sna0(icv1, 0, is) = temp2*(conpar(is, ibw, 1)+pl%na(&
&                 icv2, is)-t1)
                srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
              END DO
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCCON=25, VALID FOR CORE ONLY')
        END IF
      CASE (26) 
!
! -- BCCON=26  Feedback boundary condition: PRESCRIBE THE TOTAL ION FLUX AND
!              FIND THE AVERAGE DENSITY.  !lk and IYS 01.03.2013
!              THE POLOIDAL DENSITY VARIATION FROM THE NEIGHBOURING RADIAL
!              RING IS APPLIED ON TOP OF THE AVERAGE DENSITY.
!              THIS BOUNDARY CONDITION IS SUITABLE FOR ANY SPECIES OF
!              MULTI-SPECIES PLASMA (I.E. IN THE CASE WHEN THE CONDITION USED
!              IN BCCON=22 FAILS)
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              A CORRESPONDING CONDITION ON THE ION TEMPERATURE (BCENI=26,27)
!
! ncall_b2stbc_phys == 0
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!IYS 21.01.2016
!IYS 21.01.2016
!IYS 21.01.2016
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 26 : given total particle flux with ', &
&         'constant average density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 26 only applicable to core boundaries !')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.26 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.26 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               25) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 26'&
&                          )
        END IF
!IYS 01.03.2013 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  sconpardd(nd0, nd, is) = 0.D0
                END DO
                sconpard(nd, is) = 0.d0
              END DO
              DO nd0=1,nbdirs0
                sconpard0(nd0, is) = 0.D0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      sconpardd(nd0, nd, is) = sconpardd(nd0, nd, is) + &
&                       conpardd(nd0, nd, is, ibw, 1)
                    END DO
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  DO nd0=1,nbdirs0
                    sconpard0(nd0, is) = sconpard0(nd0, is) + conpard0(&
&                     nd0, is, ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=26: Summed value is ', sconpar(is)
            totflux = 0.0_R8
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Volume-averaged density on previous surface
            t1 = 0.0_R8
            nas = 0.0_R8
            nasd = 0.d0
            totfluxd = 0.d0
            t1d = 0.d0
            nasd0 = 0.D0
            nasdd = 0.D0
            totfluxd0 = 0.D0
            t1d0 = 0.D0
            totfluxdd = 0.D0
            t1dd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  t0 = t0 + geo%cvvol(icv2)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*&
&                       pldd%na(nd0, nd, icv2, is)
                      nasdd(nd0, nd) = nasdd(nd0, nd) + geo%cvvol(icv2)*&
&                       pldd%na(nd0, nd, icv1, is)
                    END DO
                    t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%na(nd, icv2&
&                     , is)
                    nasd(nd) = nasd(nd) + geo%cvvol(icv2)*pld%na(nd, &
&                     icv1, is)
                  END DO
                  DO nd0=1,nbdirs0
                    t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%na(nd0&
&                     , icv2, is)
                    nasd0(nd0) = nasd0(nd0) + geo%cvvol(icv2)*pld0%na(&
&                     nd0, icv1, is)
                  END DO
                  t1 = t1 + pl%na(icv2, is)*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                  IF (switch%mdf_fnb .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (dvdd%fna_mdf(nd0, nd, ifc, 0, is)+dvdd%&
&                         fna_mdf(nd0, nd, ifc, 1, is))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna_mdf(&
&                       nd, ifc, 0, is)+dvd%fna_mdf(nd, ifc, 1, is))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%&
&                       fna_mdf(nd0, ifc, 0, is)+dvd0%fna_mdf(nd0, ifc, &
&                       1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna_mdf(ifc, 0, is)+dv&
&                     %fna_mdf(ifc, 1, is))
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (dvdd%fna(nd0, nd, ifc, 0, is)+dvdd%fna(nd0, &
&                         nd, ifc, 1, is))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, &
&                       ifc, 0, is)+dvd%fna(nd, ifc, 1, is))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fna(&
&                       nd0, ifc, 0, is)+dvd0%fna(nd0, ifc, 1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna(ifc, 0, is)+dv%fna&
&                     (ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
! Sum of volume-averaged electron and ion temperatures
                t1dd(nd0, nd) = t1dd(nd0, nd)/t0
! Volume-averaged density
                nasdd(nd0, nd) = nasdd(nd0, nd)/t0
              END DO
              t1d(nd) = t1d(nd)/t0
              nasd(nd) = nasd(nd)/t0
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0)/t0
              nasd0(nd0) = nasd0(nd0)/t0
            END DO
            t1 = t1/t0
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t3dd(nd0, nd) = conpardd(nd0, nd, is, ib, 2)
                END DO
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              DO nd0=1,nbdirs0
                t3d0(nd0) = conpard0(nd0, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
              t3d0 = 0.D0
              t3dd = 0.D0
            END IF
            IF (totflux .GE. 0.) THEN
              x9 = totflux
            ELSE
              x9 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y12 = sconpar(is)
            ELSE
              y12 = -sconpar(is)
            END IF
            IF (x9 .LT. y12) THEN
              max16 = y12
            ELSE
              max16 = x9
            END IF
            IF (max16 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    x10dd(nd0, nd) = totfluxdd(nd0, nd)
                  END DO
                  x10d(nd) = totfluxd(nd)
                END DO
                DO nd0=1,nbdirs0
                  x10d0(nd0) = totfluxd0(nd0)
                END DO
                x10 = totflux
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    x10dd(nd0, nd) = -totfluxdd(nd0, nd)
                  END DO
                  x10d(nd) = -totfluxd(nd)
                END DO
                DO nd0=1,nbdirs0
                  x10d0(nd0) = -totfluxd0(nd0)
                END DO
                x10 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    y13dd(nd0, nd) = sconpardd(nd0, nd, is)
                  END DO
                  y13d(nd) = sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  y13d0(nd0) = sconpard0(nd0, is)
                END DO
                y13 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    y13dd(nd0, nd) = -sconpardd(nd0, nd, is)
                  END DO
                  y13d(nd) = -sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  y13d0(nd0) = -sconpard0(nd0, is)
                END DO
                y13 = -sconpar(is)
              END IF
              IF (x10 .LT. y13) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max17dd(nd0, nd) = y13dd(nd0, nd)
                  END DO
                  max17d(nd) = y13d(nd)
                END DO
                DO nd0=1,nbdirs0
                  max17d0(nd0) = y13d0(nd0)
                END DO
                max17 = y13
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max17dd(nd0, nd) = x10dd(nd0, nd)
                  END DO
                  max17d(nd) = x10d(nd)
                END DO
                DO nd0=1,nbdirs0
                  max17d0(nd0) = x10d0(nd0)
                END DO
                max17 = x10
              END IF
              temp2 = t3/max17
              DO nd0=1,nbdirs0
                temp2d(nd0) = (t3d0(nd0)-t3*max17d0(nd0)/max17)/max17
                temp4d(nd0) = -(temp2*(totfluxd0(nd0)-sconpard0(nd0, is)&
&                 )+(totflux-sconpar(is))*temp2d(nd0))
              END DO
              temp4 = -((totflux-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                temp12 = t3d(nd) - temp2*max17d(nd)
                temp11 = (totflux-sconpar(is))/max17
                temp10 = totfluxd(nd) - sconpard(nd, is)
                temp9 = temp2*temp10 + temp11*temp12
                DO nd0=1,nbdirs0
                  nasdd(nd0, nd) = nasd(nd)*temp4d(nd0) + temp4*nasdd(&
&                   nd0, nd) - temp9*nasd0(nd0) - nas*(temp10*temp2d(nd0&
&                   )+temp2*(totfluxdd(nd0, nd)-sconpardd(nd0, nd, is))+&
&                   temp12*(totfluxd0(nd0)-sconpard0(nd0, is)-temp11*&
&                   max17d0(nd0))/max17+temp11*(t3dd(nd0, nd)-max17d(nd)&
&                   *temp2d(nd0)-temp2*max17dd(nd0, nd)))
                END DO
                nasd(nd) = temp4*nasd(nd) - nas*temp9
              END DO
              DO nd0=1,nbdirs0
                nasd0(nd0) = temp4*nasd0(nd0) + nas*temp4d(nd0)
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  temp2 = vbig*geo%fcs(ifc)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      srwdd%sna0(nd0, nd, icv1, 0, is) = temp2*(nasdd(&
&                       nd0, nd)+pldd%na(nd0, nd, icv2, is)-t1dd(nd0, nd&
&                       ))
                      srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
                      sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(&
&                       nd0, nd, icv1, 0, is)
                      sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(&
&                       nd0, nd, icv1, 1, is)
                    END DO
                    srwd%sna0(nd, icv1, 0, is) = temp2*(nasd(nd)+pld%na(&
&                     nd, icv2, is)-t1d(nd))
                    srwd%sna0(nd, icv1, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, &
&                     0, is)
                    sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, &
&                     1, is)
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%sna0(nd0, icv1, 0, is) = temp2*(nasd0(nd0)+&
&                     pld0%na(nd0, icv2, is)-t1d0(nd0))
                    srwd0%sna0(nd0, icv1, 1, is) = 0.D0
                    sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, &
&                     icv1, 0, is)
                    sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, &
&                     icv1, 1, is)
                  END DO
                  srw%sna0(icv1, 0, is) = temp2*(nas+pl%na(icv2, is)-t1)
                  srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                  sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=26 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (27) 
!
! -- BCCON=27  Feedback boundary condition: prescribe the particle flux sum
!              for all neutrals and ions belonging to a given isonuclear sequence
!              and find the average density of the highest ionisation state.
!              THE POLOIDAL DENSITY VARIATION FROM THE NEIGHBOURING RADIAL
!              CELL IS ADDED TO THE AVERAGE DENSITY.
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              A CORRESPONDING CONDITION ON THE ION TEMPERATURE (BCENI=26,27)
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 27 : given total particle flux with constant', &
&         ' density for highest ionisation stage ion is =', is
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 27 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GE. 0.0_R8, &
&                   'BCCON = 27, CONPAR(,,1) < 0')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.27 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.27 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               25) .OR. bccon(is, ibw) .EQ. 26)) THEN
!IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
        END IF
!IYS 04.03.2013 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  sconpardd(nd0, nd, is) = 0.D0
                END DO
                sconpard(nd, is) = 0.d0
              END DO
              DO nd0=1,nbdirs0
                sconpard0(nd0, is) = 0.D0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      sconpardd(nd0, nd, is) = sconpardd(nd0, nd, is) + &
&                       conpardd(nd0, nd, is, ibw, 1)
                    END DO
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  DO nd0=1,nbdirs0
                    sconpard0(nd0, is) = sconpard0(nd0, is) + conpard0(&
&                     nd0, is, ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=27: Summed value is ', sconpar(is)
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
! Volume between two surfaces              !lk 12.12.12 {
            t0 = 0.0_R8
! Volume-averaged on neighbouring surface
            t1 = 0.0_R8
            nas = 0.0_R8
            nasd = 0.d0
            t1d = 0.d0
            totfluxid = 0.d0
            totfluxnd = 0.d0
            nasd0 = 0.D0
            nasdd = 0.D0
            totfluxndd = 0.D0
            t1d0 = 0.D0
            totfluxidd = 0.D0
            totfluxid0 = 0.D0
            totfluxnd0 = 0.D0
            t1dd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
! totfluxn here means the sum of fluxes over all ions (including fluid
! neutrals) of this isotope except for the highest ionisation stage.
! For coupled runs, both fna and fna_mdf are rescaled for neutrals
! Note that for neutrals fna = fna_mdf
                  DO isb=0,ns-1
                    IF (b2espcr(is) .EQ. b2espcr(isb) .AND. is .NE. isb&
&                   ) THEN
                      IF ((.NOT.is_neutral(isb)) .OR. switch%use_eirene &
&                         .EQ. 0) THEN
                        IF (switch%mdf_fnb .NE. 0) THEN
                          temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                          DO nd=1,nbdirs
                            DO nd0=nd,nbdirs0
                              totfluxndd(nd0, nd) = totfluxndd(nd0, nd) &
&                               - temp2*(dvdd%fna_mdf(nd0, nd, ifc, 0, &
&                               isb)+dvdd%fna_mdf(nd0, nd, ifc, 1, isb))
                            END DO
                            totfluxnd(nd) = totfluxnd(nd) - temp2*(dvd%&
&                             fna_mdf(nd, ifc, 0, isb)+dvd%fna_mdf(nd, &
&                             ifc, 1, isb))
                          END DO
                          DO nd0=1,nbdirs0
                            totfluxnd0(nd0) = totfluxnd0(nd0) - temp2*(&
&                             dvd0%fna_mdf(nd0, ifc, 0, isb)+dvd0%&
&                             fna_mdf(nd0, ifc, 1, isb))
                          END DO
                          totfluxn = totfluxn - temp2*(dv%fna_mdf(ifc, 0&
&                           , isb)+dv%fna_mdf(ifc, 1, isb))
                        ELSE
                          temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                          DO nd=1,nbdirs
                            DO nd0=nd,nbdirs0
                              totfluxndd(nd0, nd) = totfluxndd(nd0, nd) &
&                               - temp2*(dvdd%fna(nd0, nd, ifc, 0, isb)+&
&                               dvdd%fna(nd0, nd, ifc, 1, isb))
                            END DO
                            totfluxnd(nd) = totfluxnd(nd) - temp2*(dvd%&
&                             fna(nd, ifc, 0, isb)+dvd%fna(nd, ifc, 1, &
&                             isb))
                          END DO
                          DO nd0=1,nbdirs0
                            totfluxnd0(nd0) = totfluxnd0(nd0) - temp2*(&
&                             dvd0%fna(nd0, ifc, 0, isb)+dvd0%fna(nd0, &
&                             ifc, 1, isb))
                          END DO
                          totfluxn = totfluxn - temp2*(dv%fna(ifc, 0, &
&                           isb)+dv%fna(ifc, 1, isb))
                        END IF
                      END IF
                    END IF
                  END DO
! totfluxi here means the flux of the ion in the highest ionisation stage.
                  IF (switch%mdf_fnb .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxidd(nd0, nd) = totfluxidd(nd0, nd) - &
&                         temp2*(dvdd%fna_mdf(nd0, nd, ifc, 0, is)+dvdd%&
&                         fna_mdf(nd0, nd, ifc, 1, is))
                      END DO
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna_mdf&
&                       (nd, ifc, 0, is)+dvd%fna_mdf(nd, ifc, 1, is))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxid0(nd0) = totfluxid0(nd0) - temp2*(dvd0%&
&                       fna_mdf(nd0, ifc, 0, is)+dvd0%fna_mdf(nd0, ifc, &
&                       1, is))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna_mdf(ifc, 0, is)+&
&                     dv%fna_mdf(ifc, 1, is))
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxidd(nd0, nd) = totfluxidd(nd0, nd) - &
&                         temp2*(dvdd%fna(nd0, nd, ifc, 0, is)+dvdd%fna(&
&                         nd0, nd, ifc, 1, is))
                      END DO
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna(nd&
&                       , ifc, 0, is)+dvd%fna(nd, ifc, 1, is))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxid0(nd0) = totfluxid0(nd0) - temp2*(dvd0%&
&                       fna(nd0, ifc, 0, is)+dvd0%fna(nd0, ifc, 1, is))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna(ifc, 0, is)+dv%&
&                     fna(ifc, 1, is))
                  END IF
                  t0 = t0 + geo%cvvol(icv2)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*&
&                       pldd%na(nd0, nd, icv2, is)
                      nasdd(nd0, nd) = nasdd(nd0, nd) + geo%cvvol(icv2)*&
&                       pldd%na(nd0, nd, icv1, is)
                    END DO
                    t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%na(nd, icv2&
&                     , is)
                    nasd(nd) = nasd(nd) + geo%cvvol(icv2)*pld%na(nd, &
&                     icv1, is)
                  END DO
                  DO nd0=1,nbdirs0
                    t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%na(nd0&
&                     , icv2, is)
                    nasd0(nd0) = nasd0(nd0) + geo%cvvol(icv2)*pld0%na(&
&                     nd0, icv1, is)
                  END DO
                  t1 = t1 + pl%na(icv2, is)*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
!
                t1dd(nd0, nd) = t1dd(nd0, nd)/t0
! Volume-averaged density
                nasdd(nd0, nd) = nasdd(nd0, nd)/t0
              END DO
              t1d(nd) = t1d(nd)/t0
              nasd(nd) = nasd(nd)/t0
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0)/t0
              nasd0(nd0) = nasd0(nd0)/t0
            END DO
            t1 = t1/t0
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t3dd(nd0, nd) = conpardd(nd0, nd, is, ib, 2)
                END DO
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              DO nd0=1,nbdirs0
                t3d0(nd0) = conpard0(nd0, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
              t3d0 = 0.D0
              t3dd = 0.D0
            END IF
            IF (totfluxn .GE. 0.) THEN
              abs3 = totfluxn
            ELSE
              abs3 = -totfluxn
            END IF
            IF (totfluxi .GE. 0.) THEN
              abs9 = totfluxi
            ELSE
              abs9 = -totfluxi
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              abs13 = sconpar(is)
            ELSE
              abs13 = -sconpar(is)
            END IF
            IF (abs3 + abs9 + abs13 .GT. 0.0_R8) THEN
              IF (totfluxn .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs4dd(nd0, nd) = totfluxndd(nd0, nd)
                  END DO
                  abs4d(nd) = totfluxnd(nd)
                END DO
                DO nd0=1,nbdirs0
                  abs4d0(nd0) = totfluxnd0(nd0)
                END DO
                abs4 = totfluxn
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs4dd(nd0, nd) = -totfluxndd(nd0, nd)
                  END DO
                  abs4d(nd) = -totfluxnd(nd)
                END DO
                DO nd0=1,nbdirs0
                  abs4d0(nd0) = -totfluxnd0(nd0)
                END DO
                abs4 = -totfluxn
              END IF
              IF (totfluxi .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs10dd(nd0, nd) = totfluxidd(nd0, nd)
                  END DO
                  abs10d(nd) = totfluxid(nd)
                END DO
                DO nd0=1,nbdirs0
                  abs10d0(nd0) = totfluxid0(nd0)
                END DO
                abs10 = totfluxi
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs10dd(nd0, nd) = -totfluxidd(nd0, nd)
                  END DO
                  abs10d(nd) = -totfluxid(nd)
                END DO
                DO nd0=1,nbdirs0
                  abs10d0(nd0) = -totfluxid0(nd0)
                END DO
                abs10 = -totfluxi
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs14dd(nd0, nd) = sconpardd(nd0, nd, is)
                  END DO
                  abs14d(nd) = sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  abs14d0(nd0) = sconpard0(nd0, is)
                END DO
                abs14 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    abs14dd(nd0, nd) = -sconpardd(nd0, nd, is)
                  END DO
                  abs14d(nd) = -sconpard(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  abs14d0(nd0) = -sconpard0(nd0, is)
                END DO
                abs14 = -sconpar(is)
              END IF
              temp12 = t3/(abs4+abs10+abs14)
              temp2 = temp12
              DO nd0=1,nbdirs0
                temp2d(nd0) = (t3d0(nd0)-temp12*(abs4d0(nd0)+abs10d0(nd0&
&                 )+abs14d0(nd0)))/(abs4+abs10+abs14)
                temp4d(nd0) = -(temp2*(totfluxnd0(nd0)+totfluxid0(nd0)-&
&                 sconpard0(nd0, is))+(totfluxn+totfluxi-sconpar(is))*&
&                 temp2d(nd0))
              END DO
              temp4 = -((totfluxn+totfluxi-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                temp12 = abs4d(nd) + abs10d(nd) + abs14d(nd)
                temp11 = t3d(nd) - temp2*temp12
                temp10 = (totfluxn+totfluxi-sconpar(is))/(abs4+abs10+&
&                 abs14)
                temp9 = totfluxnd(nd) + totfluxid(nd) - sconpard(nd, is)
                temp6 = temp2*temp9 + temp10*temp11
                DO nd0=1,nbdirs0
                  nasdd(nd0, nd) = nasd(nd)*temp4d(nd0) + temp4*nasdd(&
&                   nd0, nd) - temp6*nasd0(nd0) - nas*(temp9*temp2d(nd0)&
&                   +temp2*(totfluxndd(nd0, nd)+totfluxidd(nd0, nd)-&
&                   sconpardd(nd0, nd, is))+temp11*(totfluxnd0(nd0)+&
&                   totfluxid0(nd0)-sconpard0(nd0, is)-temp10*(abs4d0(&
&                   nd0)+abs10d0(nd0)+abs14d0(nd0)))/(abs4+abs10+abs14)+&
&                   temp10*(t3dd(nd0, nd)-temp12*temp2d(nd0)-temp2*(&
&                   abs4dd(nd0, nd)+abs10dd(nd0, nd)+abs14dd(nd0, nd))))
                END DO
                nasd(nd) = temp4*nasd(nd) - nas*temp6
              END DO
              DO nd0=1,nbdirs0
                nasd0(nd0) = temp4*nasd0(nd0) + nas*temp4d(nd0)
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(5(a,es14.7))') ' NAS=', nas, ' totfluxn=', &
&           totfluxn, ' totfluxi=', totfluxi, ' SCONPAR=', sconpar(is), &
&           ' totfluxn+totfluxi=', totfluxn + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  temp2 = vbig*geo%fcs(ifc)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      srwdd%sna0(nd0, nd, icv1, 0, is) = temp2*(nasdd(&
&                       nd0, nd)+pldd%na(nd0, nd, icv2, is)-t1dd(nd0, nd&
&                       ))
                      srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
                      sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(&
&                       nd0, nd, icv1, 0, is)
                      sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(&
&                       nd0, nd, icv1, 1, is)
                    END DO
                    srwd%sna0(nd, icv1, 0, is) = temp2*(nasd(nd)+pld%na(&
&                     nd, icv2, is)-t1d(nd))
                    srwd%sna0(nd, icv1, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, &
&                     0, is)
                    sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, &
&                     1, is)
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%sna0(nd0, icv1, 0, is) = temp2*(nasd0(nd0)+&
&                     pld0%na(nd0, icv2, is)-t1d0(nd0))
                    srwd0%sna0(nd0, icv1, 1, is) = 0.D0
                    sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, &
&                     icv1, 0, is)
                    sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, &
&                     icv1, 1, is)
                  END DO
                  srw%sna0(icv1, 0, is) = temp2*(nas+pl%na(icv2, is)-t1)
                  srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                  sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=27 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (28) 
!
! -- BCCON=28  Prescribe the flux surface averaged density, with poloidal
!              perturbation taken from flux tube just inside domain
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCCON=28 intended for core boundaries only!')
          END DO
          IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) THEN
!srv 28.07.11
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                conpardd(nd0, nd, is, ib, 1) = 0.D0
              END DO
              conpard(nd, is, ib, 1) = 0.d0
            END DO
            DO nd0=1,nbdirs0
              conpard0(nd0, is, ib, 1) = 0.D0
            END DO
            conpar(is, ib, 1) = neb_astra
          END IF
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                conpardd(nd0, nd, is, ib, 1) = 0.D0
              END DO
              conpard(nd, is, ib, 1) = 0.d0
            END DO
            DO nd0=1,nbdirs0
              conpard0(nd0, is, ib, 1) = 0.D0
            END DO
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'constant density + perturbation', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 28, conpar(,,1) !> 0')
        END IF
!       ..compute average density on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
        t1d = 0.d0
        t1d0 = 0.D0
        t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
          IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%&
&                   na(nd0, nd, icv2, is)
                END DO
                t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%na(nd, icv2, is)
              END DO
              DO nd0=1,nbdirs0
                t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%na(nd0, &
&                 icv2, is)
              END DO
              t1 = t1 + geo%cvvol(icv2)*pl%na(icv2, is)
            END DO
          END IF
        END DO
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t1dd(nd0, nd) = t1dd(nd0, nd)/t0
          END DO
          t1d(nd) = t1d(nd)/t0
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = t1d0(nd0)/t0
        END DO
        t1 = t1/t0
!       ..impose density with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*geo%fcs(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = temp2*(pldd%na(nd0, nd&
&               , icv2, is)+conpardd(nd0, nd, is, ib, 1)-t1dd(nd0, nd))
              srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&               icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = temp2*(pld%na(nd, icv2, is)+&
&             conpard(nd, is, ib, 1)-t1d(nd))
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = temp2*(pld0%na(nd0, icv2, is)&
&             +conpard0(nd0, is, ib, 1)-t1d0(nd0))
            srwd0%sna0(nd0, icv1, 1, is) = 0.D0
            sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&             is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = temp2*(pl%na(icv2, is)+conpar(is, ib, &
&           1)-t1)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (29) 
!
! -- BCCON=29  Feedback on the total particle flux, by imposing a flux surface
!              averaged density, with poloidal perturbation taken from flux
!              tube just inside domain
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCCON=29 intended for core boundaries only!')
          END DO
        END IF
!       ..compute average density on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
        t2 = 0.0_R8
        totflux = 0.0_R8
        totpar = 0.0_R8
        totfluxd = 0.d0
        t1d = 0.d0
        t2d = 0.d0
        totpard = 0.d0
        totfluxd0 = 0.D0
        t2dd = 0.D0
        totpardd = 0.D0
        t1d0 = 0.D0
        t2d0 = 0.D0
        totpard0 = 0.D0
        totfluxdd = 0.D0
        t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
          IF (mpg%cvonclosedsurface(icv1)) THEN
            IF (bccon(is, ib0) .NE. 29) CALL XERRAB(&
&                                      'BCCON=29: incompatible core BCs'&
&                                            )
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%&
&                   na(nd0, nd, icv1, is)
                  t2dd(nd0, nd) = t2dd(nd0, nd) + geo%cvvol(icv2)*pldd%&
&                   na(nd0, nd, icv2, is)
                END DO
                t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%na(nd, icv1, is)
                t2d(nd) = t2d(nd) + geo%cvvol(icv2)*pld%na(nd, icv2, is)
              END DO
              DO nd0=1,nbdirs0
                t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%na(nd0, &
&                 icv1, is)
                t2d0(nd0) = t2d0(nd0) + geo%cvvol(icv2)*pld0%na(nd0, &
&                 icv2, is)
              END DO
              t1 = t1 + geo%cvvol(icv2)*pl%na(icv1, is)
              t2 = t2 + geo%cvvol(icv2)*pl%na(icv2, is)
              IF (bccon_flux_fb_style .EQ. 0) THEN
                temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(&
&                     dvdd%fna(nd0, nd, ifc, 0, is)+dvdd%fna(nd0, nd, &
&                     ifc, 1, is))
                  END DO
                  totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, ifc, &
&                   0, is)+dvd%fna(nd, ifc, 1, is))
                END DO
                DO nd0=1,nbdirs0
                  totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fna(nd0&
&                   , ifc, 0, is)+dvd0%fna(nd0, ifc, 1, is))
                END DO
                totflux = totflux - temp2*(dv%fna(ifc, 0, is)+dv%fna(ifc&
&                 , 1, is))
              ELSE
                temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(&
&                     dvdd%fna_eir(nd0, nd, ifc, 0, is)+dvdd%fna_eir(nd0&
&                     , nd, ifc, 1, is))
                  END DO
                  totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna_eir(nd, &
&                   ifc, 0, is)+dvd%fna_eir(nd, ifc, 1, is))
                END DO
                DO nd0=1,nbdirs0
                  totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fna_eir(&
&                   nd0, ifc, 0, is)+dvd0%fna_eir(nd0, ifc, 1, is))
                END DO
                totflux = totflux - temp2*(dv%fna_eir(ifc, 0, is)+dv%&
&                 fna_eir(ifc, 1, is))
              END IF
            END DO
!nh conpar(is,ib0,3) contains the contribution from the ionized neutrals
!   (ionising_core option)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                totpardd(nd0, nd) = totpardd(nd0, nd) + conpardd(nd0, nd&
&                 , is, ib0, 1) + conpardd(nd0, nd, is, ib0, 3)
              END DO
              totpard(nd) = totpard(nd) + conpard(nd, is, ib0, 1) + &
&               conpard(nd, is, ib0, 3)
            END DO
            DO nd0=1,nbdirs0
              totpard0(nd0) = totpard0(nd0) + conpard0(nd0, is, ib0, 1) &
&               + conpard0(nd0, is, ib0, 3)
            END DO
            totpar = totpar + conpar(is, ib0, 1) + conpar(is, ib0, 3)
          END IF
        END DO
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t1dd(nd0, nd) = t1dd(nd0, nd)/t0
            t2dd(nd0, nd) = t2dd(nd0, nd)/t0
          END DO
          t1d(nd) = t1d(nd)/t0
          t2d(nd) = t2d(nd)/t0
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = t1d0(nd0)/t0
          t2d0(nd0) = t2d0(nd0)/t0
        END DO
        t1 = t1/t0
        t2 = t2/t0
        IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t3dd(nd0, nd) = conpardd(nd0, nd, is, ib, 2)
            END DO
            t3d(nd) = conpard(nd, is, ib, 2)
          END DO
          DO nd0=1,nbdirs0
            t3d0(nd0) = conpard0(nd0, is, ib, 2)
          END DO
          t3 = conpar(is, ib, 2)
        END IF
        IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref
          t3d = 0.d0
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        IF (totflux .GE. 0.) THEN
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              x11dd(nd0, nd) = totfluxdd(nd0, nd)
            END DO
            x11d(nd) = totfluxd(nd)
          END DO
          DO nd0=1,nbdirs0
            x11d0(nd0) = totfluxd0(nd0)
          END DO
          x11 = totflux
        ELSE
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              x11dd(nd0, nd) = -totfluxdd(nd0, nd)
            END DO
            x11d(nd) = -totfluxd(nd)
          END DO
          DO nd0=1,nbdirs0
            x11d0(nd0) = -totfluxd0(nd0)
          END DO
          x11 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              y14dd(nd0, nd) = totpardd(nd0, nd)
            END DO
            y14d(nd) = totpard(nd)
          END DO
          DO nd0=1,nbdirs0
            y14d0(nd0) = totpard0(nd0)
          END DO
          y14 = totpar
        ELSE
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              y14dd(nd0, nd) = -totpardd(nd0, nd)
            END DO
            y14d(nd) = -totpard(nd)
          END DO
          DO nd0=1,nbdirs0
            y14d0(nd0) = -totpard0(nd0)
          END DO
          y14 = -totpar
        END IF
        IF (x11 .LT. y14) THEN
          IF (y14 .LT. 1.0e10_R8) THEN
            max18 = 1.0e10_R8
            max18d = 0.d0
            max18d0 = 0.D0
            max18dd = 0.D0
          ELSE
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max18dd(nd0, nd) = y14dd(nd0, nd)
              END DO
              max18d(nd) = y14d(nd)
            END DO
            DO nd0=1,nbdirs0
              max18d0(nd0) = y14d0(nd0)
            END DO
            max18 = y14
          END IF
        ELSE IF (x11 .LT. 1.0e10_R8) THEN
          max18 = 1.0e10_R8
          max18d = 0.d0
          max18d0 = 0.D0
          max18dd = 0.D0
        ELSE
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              max18dd(nd0, nd) = x11dd(nd0, nd)
            END DO
            max18d(nd) = x11d(nd)
          END DO
          DO nd0=1,nbdirs0
            max18d0(nd0) = x11d0(nd0)
          END DO
          max18 = x11
        END IF
        temp2 = t3/max18
        DO nd0=1,nbdirs0
          temp2d(nd0) = (t3d0(nd0)-t3*max18d0(nd0)/max18)/max18
          temp4d(nd0) = -(temp2*(totfluxd0(nd0)-totpard0(nd0))+(totflux-&
&           totpar)*temp2d(nd0))
        END DO
        temp4 = -((totflux-totpar)*temp2) + 1.0_R8
        DO nd=1,nbdirs
          temp12 = t3d(nd) - temp2*max18d(nd)
          temp11 = (totflux-totpar)/max18
          temp10 = temp2*(totfluxd(nd)-totpard(nd)) + temp11*temp12
          DO nd0=1,nbdirs0
            t4dd(nd0, nd) = t1d(nd)*temp4d(nd0) + temp4*t1dd(nd0, nd) - &
&             temp10*t1d0(nd0) - t1*((totfluxd(nd)-totpard(nd))*temp2d(&
&             nd0)+temp2*(totfluxdd(nd0, nd)-totpardd(nd0, nd))+temp12*(&
&             totfluxd0(nd0)-totpard0(nd0)-temp11*max18d0(nd0))/max18+&
&             temp11*(t3dd(nd0, nd)-max18d(nd)*temp2d(nd0)-temp2*max18dd&
&             (nd0, nd)))
          END DO
          t4d(nd) = temp4*t1d(nd) - t1*temp10
        END DO
        DO nd0=1,nbdirs0
          t4d0(nd0) = t1*temp4d(nd0) + temp4*t1d0(nd0)
        END DO
        t4 = temp4*t1
!       ..impose density with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*geo%fcs(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sna0(nd0, nd, icv1, 0, is) = temp2*(pldd%na(nd0, nd&
&               , icv2, is)+t4dd(nd0, nd)-t2dd(nd0, nd))
              srwdd%sna0(nd0, nd, icv1, 1, is) = 0.D0
              sna0_no_mdfdd(nd0, nd, icv1, 0, is) = srwdd%sna0(nd0, nd, &
&               icv1, 0, is)
              sna0_no_mdfdd(nd0, nd, icv1, 1, is) = srwdd%sna0(nd0, nd, &
&               icv1, 1, is)
            END DO
            srwd%sna0(nd, icv1, 0, is) = temp2*(pld%na(nd, icv2, is)+t4d&
&             (nd)-t2d(nd))
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sna0(nd0, icv1, 0, is) = temp2*(pld0%na(nd0, icv2, is)&
&             +t4d0(nd0)-t2d0(nd0))
            srwd0%sna0(nd0, icv1, 1, is) = 0.D0
            sna0_no_mdfd0(nd0, icv1, 0, is) = srwd0%sna0(nd0, icv1, 0, &
&             is)
            sna0_no_mdfd0(nd0, icv1, 1, is) = srwd0%sna0(nd0, icv1, 1, &
&             is)
          END DO
          srw%sna0(icv1, 0, is) = temp2*(pl%na(icv2, is)+t4-t2)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE DEFAULT
!
        WRITE(*, *) bccon(is, ib)
        CALL XERRAB('BCCON out of bounds')
      END SELECT
!
! -- BOUNDARY CONDITIONS FOR PARALLEL MOMENTUM EQUATIONS --
!
      SELECT CASE  (bcmom(is, ib)) 
      CASE (0) 

      CASE (1) 
!
! -- BCMOM=1 -- PRESCRIBE THE VALUE OF THE PARALLEL VELOCITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                            'BCMOM =  1 : specified parallel velocity '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*ne00*geo%fchz(ifc)
          temp1 = am(is)*geo%fcs(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 0, is) = 0.D0
              srwdd%smo0(nd0, nd, icv1, 1, is) = 0.D0
            END DO
            srwd%smo0(nd, icv1, 0, is) = temp2*temp1*mompard(nd, is, ib&
&             , 1)
            srwd%smo0(nd, icv1, 1, is) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 0, is) = temp2*temp1*mompard0(nd0, is&
&             , ib, 1)
            srwd0%smo0(nd0, icv1, 1, is) = 0.D0
          END DO
          srw%smo0(icv1, 0, is) = temp2*(temp1*mompar(is, ib, 1))
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (2) 
!
! -- BCMOM=2 -- PRESCRIBE THE GRADIENT OF THE PARALLEL VELOCITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                             'BCMOM =  2 : parallel velocity gradient '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          t1dd = 0.D0
          CALL INTVERTEX_S_DV_DV(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ua(:&
&                          , is), pld0%ua(:, :, is), pld%ua(:, :, is), &
&                          pldd%ua(:, :, :, is), t1, t1d0, t1d, t1dd, &
&                          nbdirs, nbdirs0)
          t2dd = 0.D0
          CALL INTVERTEX_S_DV_DV(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ua(:&
&                          , is), pld0%ua(:, :, is), pld%ua(:, :, is), &
&                          pldd%ua(:, :, :, is), t2, t2d0, t2d, t2dd, &
&                          nbdirs, nbdirs0)
          temp2 = vbig*am(is)*geo%fcs(ifc)*geo%fchz(ifc)
          temp1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          temp0 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc&
&           , 2))
          temp = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
          temp12 = temp*geo%fcqgam(ifc, 0)
          DO nd0=1,nbdirs0
            temp5d(nd0) = temp12*mompard0(nd0, is, ib, 1) - temp0*temp1*&
&             (t2d0(nd0)-t1d0(nd0))/geo%fcht(ifc) + pld0%ua(nd0, icv2, &
&             is)
          END DO
          temp5 = temp12*mompar(is, ib, 1) - temp0*temp1*((t2-t1)/geo%&
&           fcht(ifc)) + pl%ua(icv2, is)
          DO nd=1,nbdirs
            temp12 = temp*geo%fcqgam(ifc, 0)*mompard(nd, is, ib, 1) + &
&             pld%ua(nd, icv2, is) - temp0*temp1*(t2d(nd)-t1d(nd))/geo%&
&             fcht(ifc)
            DO nd0=1,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 0, is) = temp2*(pld%na(nd, icv1&
&               , is)*temp5d(nd0)+temp5*pldd%na(nd0, nd, icv1, is)+&
&               temp12*pld0%na(nd0, icv1, is)+pl%na(icv1, is)*(pldd%ua(&
&               nd0, nd, icv2, is)-temp0*temp1*(t2dd(nd0, nd)-t1dd(nd0, &
&               nd))/geo%fcht(ifc)))
            END DO
            srwd%smo0(nd, icv1, 0, is) = temp2*(temp5*pld%na(nd, icv1, &
&             is)+pl%na(icv1, is)*temp12)
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 0, is) = temp2*(temp5*pld0%na(nd0, &
&             icv1, is)+pl%na(icv1, is)*temp5d(nd0))
          END DO
          srw%smo0(icv1, 0, is) = temp2*(pl%na(icv1, is)*temp5)
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            temp12 = temp5*vbig*am(is)
            DO nd0=1,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 1, is) = -(temp12*pldd%na(nd0, &
&               nd, icv1, is))
            END DO
            srwd%smo0(nd, icv1, 1, is) = -(temp12*pld%na(nd, icv1, is))
          END DO
          temp12 = am(is)*vbig*temp5
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 1, is) = -(temp12*pld0%na(nd0, icv1, &
&             is))
          END DO
          srw%smo0(icv1, 1, is) = -(temp12*pl%na(icv1, is))
        END DO
      CASE (3) 
!
! -- BCMOM=3 -- SHEATH CONDITIONS, MACH NUMBER AS INPUT
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 3 not adapted for WG.'//&
&             ' Replace with drift-compatible BCMOM = 13')
! -- BCMOM=4 -- PRESCRIBE THE VALUE OF THE VELOCITY, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
      CASE (4) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM =  4 : weak velocity ', mompar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(mompar(is, ib, 2) .GT. 0.0_R8, &
&               'BCMOM = 4, MOMPAR(,,2) !> 0')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 0, is) = temp5*(mompard(nd, is, &
&               ib, 2)*mompard0(nd0, is, ib, 1)+mompard(nd, is, ib, 1)*&
&               mompard0(nd0, is, ib, 2))
            END DO
            srwd%smo0(nd, icv1, 0, is) = temp5*(mompar(is, ib, 1)*&
&             mompard(nd, is, ib, 2)+mompar(is, ib, 2)*mompard(nd, is, &
&             ib, 1))
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 0, is) = temp5*(mompar(is, ib, 1)*&
&             mompard0(nd0, is, ib, 2)+mompar(is, ib, 2)*mompard0(nd0, &
&             is, ib, 1))
          END DO
          srw%smo0(icv1, 0, is) = temp5*(mompar(is, ib, 2)*mompar(is, ib&
&           , 1))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 1, is) = 0.D0
            END DO
            srwd%smo0(nd, icv1, 1, is) = -(temp5*mompard(nd, is, ib, 2))
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 1, is) = -(temp5*mompard0(nd0, is, ib&
&             , 2))
          END DO
          srw%smo0(icv1, 1, is) = -(temp5*mompar(is, ib, 2))
        END DO
      CASE (5) 
!
! -- BCMOM=5 -- PRESCRIBE THE PARALLEL MOMENTUM FLUX PER UNIT AREA
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                   'BCMOM =  5 : parallel momentum flux per unit area '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 0, is) = 0.D0
              srwdd%smo0(nd0, nd, icv1, 1, is) = 0.D0
            END DO
            srwd%smo0(nd, icv1, 0, is) = temp5*mompard(nd, is, ib, 1)
            srwd%smo0(nd, icv1, 1, is) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 0, is) = temp5*mompard0(nd0, is, ib, 1&
&             )
            srwd0%smo0(nd0, icv1, 1, is) = 0.D0
          END DO
          srw%smo0(icv1, 0, is) = temp5*mompar(is, ib, 1)
          srw%smo0(icv1, 1, is) = 0.0_R8
        END DO
      CASE (6) 
!
! -- BCMOM=6 -- PRESCRIBE THE TOTAL PARALLEL MOMENTUM FLUX FOR A
!                 CONSTANT PARALLEL VELOCITY
!
        CALL XERRAB('B2STBC -- BCMOM=6, NOT YET AVAILABLE')
!
! -- BCMOM=7 -- PRESCRIBE THE GIVEN PROFILE OF VELOCITY
!
      CASE (7) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
          WRITE(*, '(4a,i3)') &
&         'BCMOM = 7 : specified parallel velocity on ', bcchar(ib), &
&         boundary_location(ib), ' for species ', is
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 0, is) = 0.D0
              srwdd%smo0(nd0, nd, icv1, 1, is) = 0.D0
            END DO
            srwd%smo0(nd, icv1, 0, is) = 0.d0
            srwd%smo0(nd, icv1, 1, is) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 0, is) = 0.D0
            srwd0%smo0(nd0, icv1, 1, is) = 0.D0
          END DO
          srw%smo0(icv1, 0, is) = vbig*ne00*am(is)*bv_ua(icv1, is)*geo%&
&           fcs(ifc)*geo%fchz(ifc)
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (8) 
!
! -- BCMOM=8 -- SPECIAL : LIMITED SHEAR
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&                              'BCMOM =  8 : limited shear velocity on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp8 = pl%ti(icv1)/pl%ti(icv2)
          DO nd0=1,nbdirs0
            temp4d(nd0) = (pld0%ti(nd0, icv1)-temp8*pld0%ti(nd0, icv2))/&
&             pl%ti(icv2)
          END DO
          temp4 = temp8
          DO nd=1,nbdirs
            temp8 = (pld%ti(nd, icv1)-temp4*pld%ti(nd, icv2))/pl%ti(icv2&
&             )
            DO nd0=1,nbdirs0
              arg12dd(nd0, nd) = (pldd%ti(nd0, nd, icv1)-pld%ti(nd, icv2&
&               )*temp4d(nd0)-temp4*pldd%ti(nd0, nd, icv2)-temp8*pld0%ti&
&               (nd0, icv2))/pl%ti(icv2)
            END DO
            arg12d(nd) = temp8
          END DO
          arg12 = temp4
          temp8 = SQRT(arg12)
          DO nd0=1,nbdirs0
            arg12d0(nd0) = temp4d(nd0)
            IF (arg12 .EQ. 0.D0) THEN
              temp4d(nd0) = 0.D0
            ELSE
              temp4d(nd0) = arg12d0(nd0)/(2.0*temp8)
            END IF
          END DO
          temp4 = temp8
          DO nd=1,nbdirs
            IF (arg12 .EQ. 0.d0) THEN
              DO nd0=1,nbdirs0
                y15dd(nd0, nd) = 0.D0
              END DO
              y15d(nd) = 0.d0
            ELSE
              temp8 = arg12d(nd)/(2.0*temp4)
              DO nd0=1,nbdirs0
                y15dd(nd0, nd) = (arg12dd(nd0, nd)-temp8*2.0*temp4d(nd0)&
&                 )/(2.0*temp4)
              END DO
              y15d(nd) = temp8
            END IF
          END DO
          DO nd0=1,nbdirs0
            y15d0(nd0) = temp4d(nd0)
          END DO
          y15 = temp4
          IF (1.0_R8 .GT. y15) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                add(nd0, nd) = y15dd(nd0, nd)
              END DO
              ad(nd) = y15d(nd)
            END DO
            DO nd0=1,nbdirs0
              ad0(nd0) = y15d0(nd0)
            END DO
            a = y15
          ELSE
            a = 1.0_R8
            ad = 0.d0
            add = 0.D0
            ad0 = 0.D0
          END IF
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)*vbig*am(is)
          DO nd0=1,nbdirs0
            temp4d(nd0) = a*pld0%na(nd0, icv1, is) + pl%na(icv1, is)*ad0&
&             (nd0)
          END DO
          temp4 = pl%na(icv1, is)*a
          DO nd=1,nbdirs
            temp12 = a*pld%na(nd, icv1, is) + pl%na(icv1, is)*ad(nd)
            DO nd0=1,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 0, is) = temp5*(temp12*pld0%ua(&
&               nd0, icv2, is)+pl%ua(icv2, is)*(pld%na(nd, icv1, is)*ad0&
&               (nd0)+a*pldd%na(nd0, nd, icv1, is)+ad(nd)*pld0%na(nd0, &
&               icv1, is)+pl%na(icv1, is)*add(nd0, nd))+pld%ua(nd, icv2&
&               , is)*temp4d(nd0)+temp4*pldd%ua(nd0, nd, icv2, is))
            END DO
            srwd%smo0(nd, icv1, 0, is) = temp5*(pl%ua(icv2, is)*temp12+&
&             temp4*pld%ua(nd, icv2, is))
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 0, is) = temp5*(pl%ua(icv2, is)*temp4d&
&             (nd0)+temp4*pld0%ua(nd0, icv2, is))
          END DO
          srw%smo0(icv1, 0, is) = temp5*(temp4*pl%ua(icv2, is))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            temp12 = temp5*vbig*am(is)
            DO nd0=1,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 0, is) = -(temp12*pldd%na(nd0, &
&               nd, icv1, is))
            END DO
            srwd%smo0(nd, icv1, 0, is) = -(temp12*pld%na(nd, icv1, is))
          END DO
          temp12 = temp5*vbig*am(is)
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 0, is) = -(temp12*pld0%na(nd0, icv1, &
&             is))
          END DO
          srw%smo0(icv1, 0, is) = -(temp12*pl%na(icv1, is))
        END DO
      CASE (9) 
!
! -- BCMOM=9 -- PRESCRIBE THE TOTAL PARALLEL MOMENTUM FLUX WITH
!                 CONSTANT FLUX DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                           'BCMOM =  9 : total parallel momentum flux '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
        us = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          us = us + geo%fcs(ifc)*geo%fchz(ifc)
        END DO
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%smo0(nd0, nd, icv, 0, is) = 0.D0
              srwdd%smo0(nd0, nd, icv, 1, is) = 0.D0
            END DO
            srwd%smo0(nd, icv, 0, is) = temp5*mompard(nd, is, ib, 1)/us
            srwd%smo0(nd, icv, 1, is) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv, 0, is) = temp5*mompard0(nd0, is, ib, 1)&
&             /us
            srwd0%smo0(nd0, icv, 1, is) = 0.D0
          END DO
          srw%smo0(icv, 0, is) = temp5*(mompar(is, ib, 1)/us)
          srw%smo0(icv, 1, is) = 0.0_R8
        END DO
      CASE (10) 
!
! -- BCMOM=10 -- PRESCRIBE THE DECAY LENGTH FOR THE PARALLEL MOMENTUM
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM = 10 : parallel momentum decay length ', mompar(is, ib&
&         , 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          CALL XERTST(mompar(is, ib, 1) .NE. 0.0_R8, &
&               'BCMOM = 10, MOMPAR(,,1) = 0')
          IF (bccon(is, ib) .NE. 9) THEN
            WRITE(0, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCMOM=10'
            WRITE(*, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCMOM=10'
            WRITE(*, '(1x,a)') &
&           'Please ensure that this boundary condition '//&
&           'is consistent with '//'the density boundary condition'
          END IF
        END IF
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          temp8 = co%vsa0(icv, is)/mompar(is, ib, 1)
          DO nd0=1,nbdirs0
            temp4d(nd0) = (cod0%vsa0(nd0, icv, is)-temp8*mompard0(nd0, &
&             is, ib, 1))/mompar(is, ib, 1)
          END DO
          temp4 = temp8
          DO nd=1,nbdirs
            temp8 = (cod%vsa0(nd, icv, is)-mompard(nd, is, ib, 1)*temp4)&
&             /mompar(is, ib, 1)
            DO nd0=1,nbdirs0
              srwdd%smo0(nd0, nd, icv, 0, is) = am(is)*mp*(pld%ua(nd, &
&               icv, is)*sna0_no_mdfd0(nd0, icv, 0, is)+sna0_no_mdf(icv&
&               , 0, is)*pldd%ua(nd0, nd, icv, is)+sna0_no_mdfd(nd, icv&
&               , 0, is)*pld0%ua(nd0, icv, is)+pl%ua(icv, is)*&
&               sna0_no_mdfdd(nd0, nd, icv, 0, is))
              srwdd%smo0(nd0, nd, icv, 1, is) = am(is)*mp*(sna0_no_mdfd(&
&               nd, icv, 1, is)*pld0%na(nd0, icv, is)+pl%na(icv, is)*&
&               sna0_no_mdfdd(nd0, nd, icv, 1, is)+pld%na(nd, icv, is)*&
&               sna0_no_mdfd0(nd0, icv, 1, is)+sna0_no_mdf(icv, 1, is)*&
&               pldd%na(nd0, nd, icv, is)) - temp5*(codd%vsa0(nd0, nd, &
&               icv, is)-mompard(nd, is, ib, 1)*temp4d(nd0)-temp8*&
&               mompard0(nd0, is, ib, 1))/mompar(is, ib, 1)
            END DO
            srwd%smo0(nd, icv, 0, is) = am(is)*mp*(sna0_no_mdf(icv, 0, &
&             is)*pld%ua(nd, icv, is)+pl%ua(icv, is)*sna0_no_mdfd(nd, &
&             icv, 0, is))
            srwd%smo0(nd, icv, 1, is) = am(is)*mp*(pl%na(icv, is)*&
&             sna0_no_mdfd(nd, icv, 1, is)+sna0_no_mdf(icv, 1, is)*pld%&
&             na(nd, icv, is)) - temp5*temp8
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv, 0, is) = am(is)*mp*(sna0_no_mdf(icv, 0&
&             , is)*pld0%ua(nd0, icv, is)+pl%ua(icv, is)*sna0_no_mdfd0(&
&             nd0, icv, 0, is))
            srwd0%smo0(nd0, icv, 1, is) = am(is)*mp*(pl%na(icv, is)*&
&             sna0_no_mdfd0(nd0, icv, 1, is)+sna0_no_mdf(icv, 1, is)*&
&             pld0%na(nd0, icv, is)) - temp5*temp4d(nd0)
          END DO
          srw%smo0(icv, 0, is) = am(is)*mp*pl%ua(icv, is)*sna0_no_mdf(&
&           icv, 0, is)
          srw%smo0(icv, 1, is) = am(is)*mp*(sna0_no_mdf(icv, 1, is)*pl%&
&           na(icv, is)) - temp5*temp4
        END DO
      CASE (11) 
!
! -- BCMOM=11 -- ROZHANSKY VISCOSITY CONDITION FOR THE PARALLEL MOMENTUM
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 11 not adapted for WG')
!
! -- BCMOM=12 -- CONDITION from b2stbc_spb FOR THE PARALLEL MOMENTUM   !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
      CASE (12) 
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)')&
&                   'BCMOM = 12 : from b2stbc_spb parallel momentum bc '&
&                                     //'with mompar1 =', mompar(is, ib&
&                                     , 1), ' and mompar2 =', mompar(is&
&                                     , ib, 2), ' on ', bcchar(ib), &
&                                     boundary_location(ib), &
&                                     ' for species ', is
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%smo0(nd0, nd, icv, 0, is) = 0.D0
              srwdd%smo0(nd0, nd, icv, 1, is) = 0.D0
              srwdd%smo0(nd0, nd, icv, 2, is) = 0.D0
            END DO
            srwd%smo0(nd, icv, 0, is) = 0.d0
            srwd%smo0(nd, icv, 1, is) = 0.d0
            srwd%smo0(nd, icv, 2, is) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv, 0, is) = 0.D0
            srwd0%smo0(nd0, icv, 1, is) = 0.D0
            srwd0%smo0(nd0, icv, 2, is) = 0.D0
          END DO
          srw%smo0(icv, 0, is) = 0.0_R8
          srw%smo0(icv, 1, is) = 0.0_R8
          srw%smo0(icv, 2, is) = 0.0_R8
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor&
&             (ifc, 1, is)) THEN
            temp5 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max19dd(nd0, nd) = temp5*dvdd%fna_fcor(nd0, nd, ifc, 1, &
&                 is)
              END DO
              max19d(nd) = temp5*dvd%fna_fcor(nd, ifc, 1, is)
            END DO
            DO nd0=1,nbdirs0
              max19d0(nd0) = temp5*dvd0%fna_fcor(nd0, ifc, 1, is)
            END DO
            max19 = temp5*dv%fna_fcor(ifc, 1, is)
          ELSE
            max19 = 0.0_R8
            max19d = 0.d0
            max19d0 = 0.D0
            max19dd = 0.D0
          END IF
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          temp12 = mompar(is, ib, 1)*max19/pl%na(icv, is)
          DO nd0=1,nbdirs0
            temp2d(nd0) = (max19*mompard0(nd0, is, ib, 1)+mompar(is, ib&
&             , 1)*max19d0(nd0)-temp12*pld0%na(nd0, icv, is))/pl%na(icv&
&             , is)
          END DO
          temp2 = temp12
          DO nd=1,nbdirs
            temp12 = (mompard(nd, is, ib, 1)*max19+mompar(is, ib, 1)*&
&             max19d(nd)-temp2*pld%na(nd, icv, is))/pl%na(icv, is)
            DO nd0=1,nbdirs0
              srwdd%smo0(nd0, nd, icv, 3, is) = srwdd%smo0(nd0, nd, icv&
&               , 3, is) + (mompard(nd, is, ib, 1)*max19d0(nd0)+max19d(&
&               nd)*mompard0(nd0, is, ib, 1)+mompar(is, ib, 1)*max19dd(&
&               nd0, nd)-pld%na(nd, icv, is)*temp2d(nd0)-temp2*pldd%na(&
&               nd0, nd, icv, is)-temp12*pld0%na(nd0, icv, is))/pl%na(&
&               icv, is)
            END DO
            srwd%smo0(nd, icv, 3, is) = temp5*mompard(nd, is, ib, 2) + &
&             srwd%smo0(nd, icv, 3, is) + temp12
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv, 3, is) = srwd0%smo0(nd0, icv, 3, is) + &
&             temp5*mompard0(nd0, is, ib, 2) + temp2d(nd0)
          END DO
          srw%smo0(icv, 3, is) = srw%smo0(icv, 3, is) + temp5*mompar(is&
&           , ib, 2) + temp2
        END DO
      CASE (13) 
!
! -- BCMOM=13 -- DRIFT-COMPATIBLE SHEATH CONDITION FOR THE PARALLEL MOMENTUM
!srv added accumulation in order to account twice b.c. for corner cells
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
            WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)') &
&           'BCMOM = 13 : from b2stbc_spb parallel momentum bc '//&
&           'with mompar1 =', mompar(is, ib, 1), ' and mompar2 =', &
&           mompar(is, ib, 2), ' on ', bcchar(ib), boundary_location(ib)&
&           , ' for species ', is
          ELSE
            WRITE(*, '(a,a,1p,g14.7,a,a,a,a,i3)') &
&           'BCMOM = 13 with MOMPAR(:,:,2) > 0.5 : non-marginal ', &
&           'sheath BC, with MOMPAR(:,:,1) = ', mompar(is, ib, 1), &
&           ' on boundary ', bcchar(ib), boundary_location(ib), &
&           ' for species ', is
          END IF
          CALL XERTST(bccon(is, ib) .EQ. 14, &
&               'BCCON = 14 must be used in conjunction '//&
&               'with BCMOM = 13!')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the internal cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          t1dd = 0.D0
          CALL INTVERTEX_S_DV_DV(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ua(:&
&                          , is), pld0%ua(:, :, is), pld%ua(:, :, is), &
&                          pldd%ua(:, :, :, is), t1, t1d0, t1d, t1dd, &
&                          nbdirs, nbdirs0)
          t2dd = 0.D0
          CALL INTVERTEX_S_DV_DV(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ua(:&
&                          , is), pld0%ua(:, :, is), pld%ua(:, :, is), &
&                          pldd%ua(:, :, :, is), t2, t2d0, t2d, t2dd, &
&                          nbdirs, nbdirs0)
          IF (geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3) .GE. &
&             0.) THEN
            wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          ELSE
            wrk = -(geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)&
&             )
          END IF
          IF (wrk .LT. geo%qalfmin) THEN
            temp5 = vbig*am(is)*geo%fcs(ifc)*geo%fchz(ifc)
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(&
&             ifc, 2))
            DO nd0=1,nbdirs0
              temp4d(nd0) = pld0%ua(nd0, icv2, is) - temp1*temp2*(t2d0(&
&               nd0)-t1d0(nd0))/geo%fcht(ifc)
            END DO
            temp4 = pl%ua(icv2, is) - temp1*temp2*(t2-t1)/geo%fcht(ifc)
            DO nd=1,nbdirs
              temp8 = pld%ua(nd, icv2, is) - temp1*temp2*(t2d(nd)-t1d(nd&
&               ))/geo%fcht(ifc)
              DO nd0=1,nbdirs0
                srwdd%smo0(nd0, nd, icv1, 0, is) = temp5*(pld%na(nd, &
&                 icv1, is)*temp4d(nd0)+temp4*pldd%na(nd0, nd, icv1, is)&
&                 +temp8*pld0%na(nd0, icv1, is)+pl%na(icv1, is)*(pldd%ua&
&                 (nd0, nd, icv2, is)-temp1*temp2*(t2dd(nd0, nd)-t1dd(&
&                 nd0, nd))/geo%fcht(ifc)))
              END DO
              srwd%smo0(nd, icv1, 0, is) = temp5*(temp4*pld%na(nd, icv1&
&               , is)+pl%na(icv1, is)*temp8)
            END DO
            DO nd0=1,nbdirs0
              srwd0%smo0(nd0, icv1, 0, is) = temp5*(temp4*pld0%na(nd0, &
&               icv1, is)+pl%na(icv1, is)*temp4d(nd0))
            END DO
            srw%smo0(icv1, 0, is) = temp5*(pl%na(icv1, is)*temp4)
            temp5 = geo%fcs(ifc)*geo%fchz(ifc)
            DO nd=1,nbdirs
              temp12 = temp5*vbig*am(is)
              DO nd0=1,nbdirs0
                srwdd%smo0(nd0, nd, icv1, 1, is) = -(temp12*pldd%na(nd0&
&                 , nd, icv1, is))
              END DO
              srwd%smo0(nd, icv1, 1, is) = -(temp12*pld%na(nd, icv1, is)&
&               )
            END DO
            temp12 = am(is)*vbig*temp5
            DO nd0=1,nbdirs0
              srwd0%smo0(nd0, icv1, 1, is) = -(temp12*pld0%na(nd0, icv1&
&               , is))
            END DO
            srw%smo0(icv1, 1, is) = -(temp12*pl%na(icv1, is))
          ELSE
!srv 15.02.26
            CALL VBC_IS_DV_DV(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, &
&                       is), csbcd0(:, icv1, is), csbcd(:, icv1, is), &
&                       csbcdd(:, :, icv1, is), wrk, nbdirs, nbdirs0)
!srv 07.05.09 {
            temp5 = ubig*mp*geo%fchz(ifc)*am(is)*geo%fcs(ifc)
            DO nd0=1,nbdirs0
              temp2d(nd0) = vbcd0(nd0, icv1, is)/epslon**2
              temp4d(nd0) = mompar(is, ib, 1)*pld0%na(nd0, icv1, is) + &
&               pl%na(icv1, is)*mompard0(nd0, is, ib, 1)
            END DO
            temp2 = vbc(icv1, is)/(epslon*epslon)
            temp4 = pl%na(icv1, is)*mompar(is, ib, 1)
            DO nd=1,nbdirs
              temp12 = mompar(is, ib, 1)*pld%na(nd, icv1, is) + mompard(&
&               nd, is, ib, 1)*pl%na(icv1, is)
              temp8 = temp4/(epslon*epslon)
              DO nd0=1,nbdirs0
                srwdd%smo0(nd0, nd, icv1, 0, is) = srwdd%smo0(nd0, nd, &
&                 icv1, 0, is) + temp5*(temp12*temp2d(nd0)+temp2*(pld%na&
&                 (nd, icv1, is)*mompard0(nd0, is, ib, 1)+mompar(is, ib&
&                 , 1)*pldd%na(nd0, nd, icv1, is)+mompard(nd, is, ib, 1)&
&                 *pld0%na(nd0, icv1, is))+temp8*vbcdd(nd0, nd, icv1, is&
&                 )+vbcd(nd, icv1, is)*temp4d(nd0)/epslon**2)
              END DO
              srwd%smo0(nd, icv1, 0, is) = srwd%smo0(nd, icv1, 0, is) + &
&               temp5*(temp2*temp12+vbcd(nd, icv1, is)*temp8)
            END DO
            DO nd0=1,nbdirs0
              srwd0%smo0(nd0, icv1, 0, is) = srwd0%smo0(nd0, icv1, 0, is&
&               ) + temp5*(temp2*temp4d(nd0)+temp4*temp2d(nd0))
            END DO
            srw%smo0(icv1, 0, is) = srw%smo0(icv1, 0, is) + temp5*(temp4&
&             *temp2)
            IF (geo%fcpbshz(ifc) .GE. 0.) THEN
              abs5 = geo%fcpbshz(ifc)
            ELSE
              abs5 = -geo%fcpbshz(ifc)
            END IF
!srv 07.05.09 }
            temp5 = am(is)*abs5*ubig*mp
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%smo0(nd0, nd, icv1, 1, is) = srwdd%smo0(nd0, nd, &
&                 icv1, 1, is) - temp5*pldd%na(nd0, nd, icv1, is)/epslon&
&                 **2
              END DO
              srwd%smo0(nd, icv1, 1, is) = srwd%smo0(nd, icv1, 1, is) - &
&               temp5*pld%na(nd, icv1, is)/epslon**2
            END DO
            DO nd0=1,nbdirs0
              srwd0%smo0(nd0, icv1, 1, is) = srwd0%smo0(nd0, icv1, 1, is&
&               ) - temp5*pld0%na(nd0, icv1, is)/epslon**2
            END DO
            srw%smo0(icv1, 1, is) = srw%smo0(icv1, 1, is) - temp5*(pl%na&
&             (icv1, is)/(epslon*epslon))
          END IF
!srv 01.02.09 }

        END DO
      CASE (14) 
!
! -- BCMOM=14 -- CONDITION from b2stbc_spb FOR THE PARALLEL MOMENTUM    !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)')&
&              'BCMOM = 14 : from b2stbc_spb momentum bc with mompar1 ='&
&                                     , mompar(is, ib, 1), &
&                                     ' and mompar2 =', mompar(is, ib, 2&
&                                     ), ' on ', bcchar(ib), &
&                                     boundary_location(ib), &
&                                     ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
!TODO: drift contributions!
              srwdd%smo0(nd0, nd, icv1, 0, is) = 0.D0
              srwdd%smo0(nd0, nd, icv1, 1, is) = 0.D0
              srwdd%smo0(nd0, nd, icv1, 2, is) = 0.D0
            END DO
            srwd%smo0(nd, icv1, 0, is) = 0.d0
            srwd%smo0(nd, icv1, 1, is) = 0.d0
            srwd%smo0(nd, icv1, 2, is) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 0, is) = 0.D0
            srwd0%smo0(nd0, icv1, 1, is) = 0.D0
            srwd0%smo0(nd0, icv1, 2, is) = 0.D0
          END DO
          srw%smo0(icv1, 0, is) = 0.0_R8
          srw%smo0(icv1, 1, is) = 0.0_R8
          srw%smo0(icv1, 2, is) = 0.0_R8
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor&
&             (ifc, 1, is)) THEN
            temp5 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max20dd(nd0, nd) = temp5*dvdd%fna_fcor(nd0, nd, ifc, 1, &
&                 is)
              END DO
              max20d(nd) = temp5*dvd%fna_fcor(nd, ifc, 1, is)
            END DO
            DO nd0=1,nbdirs0
              max20d0(nd0) = temp5*dvd0%fna_fcor(nd0, ifc, 1, is)
            END DO
            max20 = temp5*dv%fna_fcor(ifc, 1, is)
          ELSE
            max20 = 0.0_R8
            max20d = 0.d0
            max20d0 = 0.D0
            max20dd = 0.D0
          END IF
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          temp12 = mompar(is, ib, 1)*max20/pl%na(icv1, is)
          DO nd0=1,nbdirs0
            temp2d(nd0) = (max20*mompard0(nd0, is, ib, 1)+mompar(is, ib&
&             , 1)*max20d0(nd0)-temp12*pld0%na(nd0, icv1, is))/pl%na(&
&             icv1, is)
          END DO
          temp2 = temp12
          DO nd=1,nbdirs
            temp12 = (mompard(nd, is, ib, 1)*max20+mompar(is, ib, 1)*&
&             max20d(nd)-temp2*pld%na(nd, icv1, is))/pl%na(icv1, is)
            DO nd0=1,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 3, is) = srwdd%smo0(nd0, nd, &
&               icv1, 3, is) + (mompard(nd, is, ib, 1)*max20d0(nd0)+&
&               max20d(nd)*mompard0(nd0, is, ib, 1)+mompar(is, ib, 1)*&
&               max20dd(nd0, nd)-pld%na(nd, icv1, is)*temp2d(nd0)-temp2*&
&               pldd%na(nd0, nd, icv1, is)-temp12*pld0%na(nd0, icv1, is)&
&               )/pl%na(icv1, is)
            END DO
            srwd%smo0(nd, icv1, 3, is) = temp5*mompard(nd, is, ib, 2) + &
&             srwd%smo0(nd, icv1, 3, is) + temp12
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 3, is) = srwd0%smo0(nd0, icv1, 3, is) &
&             + temp5*mompard0(nd0, is, ib, 2) + temp2d(nd0)
          END DO
          srw%smo0(icv1, 3, is) = srw%smo0(icv1, 3, is) + temp5*mompar(&
&           is, ib, 2) + temp2
        END DO
      CASE (15) 
!
!
! -- BCMOM=15 -- PRESCRIBE THE VALUE OF THE PARALLEL VELOCITY, SCALED WITH
!                B_average/B_local
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 15 not adapted for WG')
!
! -- BCMOM=16 -- PRESCRIBE THE AVERAGE VALUE OF THE PARALLEL VELOCITY   !lk 12.12.12 {
!
      CASE (16) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM = 16 : specified average parallel velocity ', mompar(is&
&         , ib, 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCMOM=16 intended for core boundaries only!')
          END DO
        END IF
!       ..compute average parallel velocity on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
        t1d = 0.d0
        t1d0 = 0.D0
        t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
          IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%&
&                   ua(nd0, nd, icv2, is)
                END DO
                t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ua(nd, icv2, is)
              END DO
              DO nd0=1,nbdirs0
                t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%ua(nd0, &
&                 icv2, is)
              END DO
              t1 = t1 + geo%cvvol(icv2)*pl%ua(icv2, is)
            END DO
          END IF
        END DO
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t1dd(nd0, nd) = t1dd(nd0, nd)/t0
          END DO
          t1d(nd) = t1d(nd)/t0
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = t1d0(nd0)/t0
        END DO
        t1 = t1/t0
!       ..impose velocity
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp5 = vbig*ne00*geo%fchz(ifc)*am(is)*geo%fcs(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 0, is) = temp5*(pldd%ua(nd0, nd&
&               , icv2, is)-t1dd(nd0, nd))
              srwdd%smo0(nd0, nd, icv1, 1, is) = 0.D0
            END DO
            srwd%smo0(nd, icv1, 0, is) = temp5*(mompard(nd, is, ib, 1)+&
&             pld%ua(nd, icv2, is)-t1d(nd))
            srwd%smo0(nd, icv1, 1, is) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 0, is) = temp5*(mompard0(nd0, is, ib, &
&             1)+pld0%ua(nd0, icv2, is)-t1d0(nd0))
            srwd0%smo0(nd0, icv1, 1, is) = 0.D0
          END DO
          srw%smo0(icv1, 0, is) = temp5*(mompar(is, ib, 1)+pl%ua(icv2, &
&           is)-t1)
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (17) 
!
! -- BCMOM=17 -- leakage option for parallel momentum
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                              'BCMOM = 17 : parallel momentum leakage '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp)
          temp8 = SQRT(arg12)
          DO nd0=1,nbdirs0
            arg12d0(nd0) = (pl%te(icv1)*rtd0%rza(nd0, icv1, is)+rt%rza(&
&             icv1, is)*pld0%te(nd0, icv1)+pld0%ti(nd0, icv1))/(am(is)*&
&             mp)
            IF (arg12 .EQ. 0.D0) THEN
              temp4d(nd0) = 0.D0
            ELSE
              temp4d(nd0) = arg12d0(nd0)/(2.0*temp8)
            END IF
          END DO
          temp4 = temp8
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 0, is) = 0.D0
              arg12dd(nd0, nd) = (rtd%rza(nd, icv1, is)*pld0%te(nd0, &
&               icv1)+pl%te(icv1)*rtdd%rza(nd0, nd, icv1, is)+pld%te(nd&
&               , icv1)*rtd0%rza(nd0, icv1, is)+rt%rza(icv1, is)*pldd%te&
&               (nd0, nd, icv1)+pldd%ti(nd0, nd, icv1))/(am(is)*mp)
            END DO
            srwd%smo0(nd, icv1, 0, is) = 0.d0
            arg12d(nd) = (pl%te(icv1)*rtd%rza(nd, icv1, is)+rt%rza(icv1&
&             , is)*pld%te(nd, icv1)+pld%ti(nd, icv1))/(am(is)*mp)
            IF (arg12 .EQ. 0.d0) THEN
              DO nd0=1,nbdirs0
                result10dd(nd0, nd) = 0.D0
              END DO
              result10d(nd) = 0.d0
            ELSE
              temp8 = arg12d(nd)/(2.0*temp4)
              DO nd0=1,nbdirs0
                result10dd(nd0, nd) = (arg12dd(nd0, nd)-temp8*2.0*temp4d&
&                 (nd0))/(2.0*temp4)
              END DO
              result10d(nd) = temp8
            END IF
          END DO
          result10 = temp4
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 0, is) = 0.D0
            result10d0(nd0) = temp4d(nd0)
            temp4d(nd0) = mompar(is, ib, 1)*result10d0(nd0) + result10*&
&             mompard0(nd0, is, ib, 1)
          END DO
          srw%smo0(icv1, 0, is) = 0.0_R8
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)*am(is)*mp
          temp4 = result10*mompar(is, ib, 1)
          DO nd=1,nbdirs
            temp12 = mompar(is, ib, 1)*result10d(nd) + mompard(nd, is, &
&             ib, 1)*result10
            DO nd0=1,nbdirs0
              srwdd%smo0(nd0, nd, icv1, 1, is) = temp5*(temp12*pld0%na(&
&               nd0, icv1, is)+pl%na(icv1, is)*(result10d(nd)*mompard0(&
&               nd0, is, ib, 1)+mompar(is, ib, 1)*result10dd(nd0, nd)+&
&               mompard(nd, is, ib, 1)*result10d0(nd0))+pld%na(nd, icv1&
&               , is)*temp4d(nd0)+temp4*pldd%na(nd0, nd, icv1, is))
            END DO
            srwd%smo0(nd, icv1, 1, is) = temp5*(pl%na(icv1, is)*temp12+&
&             temp4*pld%na(nd, icv1, is))
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv1, 1, is) = temp5*(pl%na(icv1, is)*temp4d&
&             (nd0)+temp4*pld0%na(nd0, icv1, is))
          END DO
          srw%smo0(icv1, 1, is) = temp5*(temp4*pl%na(icv1, is))
        END DO
      CASE (18) 
!
! -- BCMOM=18 -- PRESCRIBE ZERO SOURCE TERMS (-> no flux)
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&               'BCMOM = 18 : specified zero source terms (no flux) on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%smo0(nd0, nd, icv, 0, is) = 0.D0
              srwdd%smo0(nd0, nd, icv, 1, is) = 0.D0
            END DO
            srwd%smo0(nd, icv, 0, is) = 0.d0
            srwd%smo0(nd, icv, 1, is) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%smo0(nd0, icv, 0, is) = 0.D0
            srwd0%smo0(nd0, icv, 1, is) = 0.D0
          END DO
          srw%smo0(icv, 0, is) = 0.0_R8
          srw%smo0(icv, 1, is) = 0.0_R8
        END DO
      CASE DEFAULT
!
        WRITE(*, *) bcmom(is, ib)
        CALL XERRAB('BCMOM out of bounds')
!
      END SELECT
! -- END LOOP OVER SPECIES

    END DO
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_SPECIES_DV_DV

!  Differentiation of b2stbc_phys_species in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: conpar sconpar *(srw.smo0)
!                *(srw.sna0) vbc sna0_no_mdf csbc
!   with respect to varying inputs: conpar mompar sconpar *(dv.fna)
!                *(dv.fna_mdf) *(dv.fnapsch) *(dv.fna_fcor) *(dv.fna_eir)
!                *(dv.vadia) *(dv.vaecrb) *(rt.rza) *(srw.smo0)
!                *(srw.sna0) *(co.cdna) *(co.dpa0) *(co.dna0) *(co.vsa0)
!                *(pl.na) *(pl.ua) *(pl.te) *(pl.ti) vbc sna0_no_mdf
!                rz csbc pz
!   Plus diff mem management of: dv.fna:in dv.fna_mdf:in dv.fnapsch:in
!                dv.fna_fcor:in dv.fna_eir:in dv.vadia:in dv.vaecrb:in
!                mpg.bcfcor:in geo.fcs:in geo.vxvol:in rt.rza:in
!                srw.smo0:in srw.sna0:in co.cdna:in co.dpa0:in
!                co.dna0:in co.vsa0:in pl.na:in pl.ua:in pl.te:in
!                pl.ti:in
!srv 15.02.26 }
!
  SUBROUTINE B2STBC_PHYS_SPECIES_DV(ib, nbdirs)
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER :: is, ib, ibc, ib0, ibc0, ibw, isb
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: s1, t0, t1, t2, t3, t4, vbnd, totpar, totflux, &
&   totfluxn, totfluxi, a, cs, csb, wrk
    REAL(kind=r8), DIMENSION(nbdirsmax) :: t0d, t1d, t2d, t3d, t4d, &
&   vbndd, totpard, totfluxd, totfluxnd, totfluxid, ad, csd, csbd
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    LOGICAL :: ishigh
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    REAL(r8) :: y1
    REAL(r8), DIMENSION(nbdirsmax) :: y1d
    REAL(r8) :: y2
    REAL(r8), DIMENSION(nbdirsmax) :: y2d
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8) :: y3
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y3d
    REAL(r8) :: y4
    REAL(r8), DIMENSION(nbdirsmax) :: y4d
    REAL(r8) :: y5
    REAL(r8), DIMENSION(nbdirsmax) :: y5d
    REAL(kind=r8) :: x2
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x2d
    REAL(kind=r8) :: y6
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y6d
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: y7
    REAL(kind=r8) :: x4
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x4d
    REAL(kind=r8) :: y8
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y8d
    REAL(kind=r8) :: x5
    REAL(kind=r8) :: y9
    REAL(kind=r8) :: x6
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x6d
    REAL(kind=r8) :: x7
    REAL(kind=r8) :: y10
    REAL(kind=r8) :: x8
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x8d
    REAL(kind=r8) :: y11
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y11d
    REAL(kind=r8) :: x9
    REAL(kind=r8) :: y12
    REAL(kind=r8) :: x10
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x10d
    REAL(kind=r8) :: y13
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y13d
    REAL(kind=r8) :: x11
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x11d
    REAL(kind=r8) :: y14
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y14d
    REAL(r8) :: y15
    REAL(r8), DIMENSION(nbdirsmax) :: y15d
    REAL(r8) :: max1
    REAL(r8), DIMENSION(nbdirsmax) :: max1d
    REAL(r8) :: min1
    REAL(r8), DIMENSION(nbdirsmax) :: min1d
    REAL(r8) :: max2
    REAL(r8), DIMENSION(nbdirsmax) :: max2d
    REAL(r8) :: min2
    REAL(r8), DIMENSION(nbdirsmax) :: min2d
    REAL(r8) :: max3
    REAL(r8), DIMENSION(nbdirsmax) :: max3d
    REAL(r8) :: max4
    REAL(r8), DIMENSION(nbdirsmax) :: max4d
    REAL(kind=r8) :: max5
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max5d
    REAL(kind=r8) :: abs0
    REAL(r8) :: max6
    REAL(r8), DIMENSION(nbdirsmax) :: max6d
    REAL(r8) :: max7
    REAL(r8), DIMENSION(nbdirsmax) :: max7d
    REAL(kind=r8) :: max8
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max8d
    REAL(r8) :: max9
    REAL(r8), DIMENSION(nbdirsmax) :: max9d
    REAL(r8) :: min3
    REAL(r8), DIMENSION(nbdirsmax) :: min3d
    REAL(kind=r8) :: max10
    REAL(kind=r8) :: max11
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max11d
    REAL(kind=r8) :: max12
    REAL(kind=r8) :: max13
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max13d
    REAL(kind=r8) :: max14
    REAL(kind=r8) :: max15
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max15d
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: abs2
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs2d
    REAL(kind=r8) :: max16
    REAL(kind=r8) :: max17
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max17d
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: abs4
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs4d
    REAL(kind=r8) :: max18
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max18d
    REAL(r8) :: max19
    REAL(r8), DIMENSION(nbdirsmax) :: max19d
    REAL(kind=r8) :: abs5
    REAL(r8) :: max20
    REAL(r8), DIMENSION(nbdirsmax) :: max20d
    REAL(kind=r8) :: abs6
    REAL(kind=r8) :: abs7
    REAL(kind=r8) :: abs8
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs8d
    REAL(kind=r8) :: abs9
    REAL(kind=r8) :: abs10
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs10d
    REAL(kind=r8) :: abs11
    REAL(kind=r8) :: abs12
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs12d
    REAL(kind=r8) :: abs13
    REAL(kind=r8) :: abs14
    REAL(kind=r8), DIMENSION(nbdirsmax) :: abs14d
    REAL(r8) :: arg12
    REAL(r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(r8) :: result10
    REAL(r8), DIMENSION(nbdirsmax) :: result10d
    LOGICAL :: result11
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(kind=r8) :: temp2
    REAL(r8) :: temp3
    REAL(r8) :: temp4
    REAL(kind=r8) :: temp5
    INTEGER :: nbdirs
    t3d = 0.d0
!
    DO is=0,ns-1
      IF (is .EQ. ns - 1) THEN
        ishigh = .true.
      ELSE
        ishigh = .NOT.LNEXT(is, is + 1)
      END IF
!
! -- BOUNDARY CONDITIONS FOR CONTINUITY EQUATIONS --
      SELECT CASE  (bccon(is, ib)) 
      CASE (0) 

      CASE (1) 
!
!
! -- BCCON=1 -- PRESCRIBE THE VALUE OF THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            DO nd=1,nbdirs
              conpard(nd, is, ib, 1) = 0.d0
            END DO
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  1 : constant density ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 1, CONPAR(,,1) !> 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 2)
          IF (mpg%cvonclosedsurface(icv)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
            IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 1'&
&                            )
          END IF
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp = vbig*geo%fcs(ifc)
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = temp*conpard(nd, is, ib, 1)
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = temp*conpar(is, ib, 1)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (2) 
!
! -- BCCON=2 -- PRESCRIBE THE GRADIENT OF THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  2 : density gradient ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 2'&
&                                                           )
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          CALL INTVERTEX_S_DV_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%&
&                              na(:, is), pld%na(:, :, is), t1, t1d, &
&                              nbdirs)
          CALL INTVERTEX_S_DV_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%&
&                              na(:, is), pld%na(:, :, is), t2, t2d, &
&                              nbdirs)
          temp = vbig*geo%fcs(ifc)
          temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
          temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc&
&           , 2))
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = temp*(temp0*geo%fcqgam(ifc, 0)*&
&             conpard(nd, is, ib, 1)-temp1*temp2*(t2d(nd)-t1d(nd))/geo%&
&             fcht(ifc)+pld%na(nd, icv2, is))
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = temp*(temp0*(geo%fcqgam(ifc, 0)*conpar&
&           (is, ib, 1))-temp1*(temp2*((t2-t1)/geo%fcht(ifc)))+pl%na(&
&           icv2, is))
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (3) 
!
! -- BCCON=3 -- SHEATH CONDITIONS
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&                                   'BCCON =  3 : sheath density bc on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = ubig*geo%fcs(ifc)
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = temp2*pld%na(nd, icv2, is)
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = temp2*pl%na(icv2, is)
          srw%sna0(icv1, 1, is) = -(ubig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (4) 
!
! -- BCCON=4 -- PRESCRIBE THE VALUE OF THE DENSITY, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            DO nd=1,nbdirs
              conpard(nd, is, ib, 1) = 0.d0
            END DO
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  4 : weak density ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 4, CONPAR(,,1) !> 0')
          CALL XERTST(conpar(is, ib, 2) .GT. 0.0_R8, &
&               'BCCON = 4, CONPAR(,,2) !> 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 4'&
&                                                           )
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = geo%fcs(ifc)*(conpar(is, ib, 1)&
&             *conpard(nd, is, ib, 2)+conpar(is, ib, 2)*conpard(nd, is, &
&             ib, 1))
            srwd%sna0(nd, icv1, 1, is) = -(geo%fcs(ifc)*conpard(nd, is, &
&             ib, 2))
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = conpar(is, ib, 2)*geo%fcs(ifc)*conpar(&
&           is, ib, 1)
          srw%sna0(icv1, 1, is) = -(conpar(is, ib, 2)*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (5) 
!
! -- BCCON=5 -- PRESCRIBE THE PARTICLE FLUX PER UNIT AREA
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                                 'BCCON =  5 : particle flux per area '&
&                                     , conpar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = geo%fcs(ifc)*conpard(nd, is, ib&
&             , 1)
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = conpar(is, ib, 1)*geo%fcs(ifc)
          srw%sna0(icv1, 1, is) = 0.0_R8
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
          IF (switch%mdf_fnb .NE. 0) THEN
!wdk Added correction to make mdf_fnb options equivalent
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp3 = pl%na(icv1, is) + pl%na(icv2, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1, &
&             is)
            DO nd=1,nbdirs
              t0d(nd) = temp2*(dvd%fnapsch(nd, ifc, 0, is)+dvd%fnapsch(&
&               nd, ifc, 1, is)+0.5_R8*(temp3*(temp1*dvd%vadia(nd, ifc, &
&               0, is)+temp0*dvd%vadia(nd, ifc, 1, is))+temp*(pld%na(nd&
&               , icv1, is)+pld%na(nd, icv2, is))))
            END DO
            t0 = temp2*(dv%fnapsch(ifc, 0, is)+dv%fnapsch(ifc, 1, is)+&
&             0.5_R8*(temp*temp3))
            IF (0.0_R8 .LT. t0) THEN
              DO nd=1,nbdirs
                max1d(nd) = t0d(nd)
              END DO
              max1 = t0
            ELSE
              max1 = 0.0_R8
              max1d = 0.d0
            END IF
            DO nd=1,nbdirs
              srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) + &
&               max1d(nd)
            END DO
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max1
            IF (0.0_R8 .GT. t0) THEN
              DO nd=1,nbdirs
                min1d(nd) = t0d(nd)
              END DO
              min1 = t0
            ELSE
              min1 = 0.0_R8
              min1d = 0.d0
            END IF
            temp3 = min1/pl%na(icv1, is)
            DO nd=1,nbdirs
              srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) + &
&               (min1d(nd)-temp3*pld%na(nd, icv1, is))/pl%na(icv1, is)
            END DO
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp3
          END IF
        END DO
      CASE (6) 
!
! -- BCCON=6 -- PRESCRIBE THE TOTAL PARTICLE FLUX FOR A
!                 CONSTANT DENSITY
!
        CALL XERRAB('b2stbc_phys -- BCCON = 6 not adapted for WG')
!
! -- BCCON=7 -- PRESCRIBE THE GIVEN PROFILE OF DENSITY
!
      CASE (7) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
          WRITE(*, '(4a,i3)') 'BCCON = 7 : specified density on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = 0.d0
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*bv_na(icv1, is)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (8) 
!
! -- BCCON=8 -- PRESCRIBE THE TOTAL PARTICLE FLUX WITH
!                 CONSTANT FLUX DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (is .EQ. ismain .AND. bcchar(ib) .EQ. 'S' .AND. switch%&
&             use_astra .NE. 0) THEN
            CALL XERRAB(&
&                 'Compile with -DASTRA option to couple to ASTRA!')
!
          END IF
          WRITE(*, '(a,1p,g14.7,a4,a1,a,a13,i3)') &
&         'BCCON =  8 : total particle flux ', conpar(is, ib, 1), ' on '&
&         , bcchar(ib), boundary_location(ib), ' for species ', is
        END IF
!wdk      Note: take full area for face, whether "poloidal" or "radial" or mixed
!wdk      Backwards compatibility issue for E/W and 5-pt stencil?
!wdk      Total flux will be fine, possibly distributed somewhat differently...
        us = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          us = us + geo%fcs(ifc)
        END DO
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) + &
&             geo%fcs(ifc)*conpard(nd, is, ib, 1)/us
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = sna0_no_mdfd(nd, icv1, 0, is&
&             ) + srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = sna0_no_mdfd(nd, icv1, 1, is&
&             ) + srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + conpar(is, ib&
&           , 1)/us*geo%fcs(ifc)
          srw%sna0(icv1, 1, is) = 0.0_R8
          sna0_no_mdf(icv1, 0, is) = sna0_no_mdf(icv1, 0, is) + srw%sna0&
&           (icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = sna0_no_mdf(icv1, 1, is) + srw%sna0&
&           (icv1, 1, is)
          IF (switch%mdf_fnb .NE. 0) THEN
!wdk Correction now involves vadia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_fnb = 0 option
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp3 = pl%na(icv1, is) + pl%na(icv2, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1, &
&             is)
            DO nd=1,nbdirs
              t0d(nd) = temp2*(dvd%fnapsch(nd, ifc, 0, is)+dvd%fnapsch(&
&               nd, ifc, 1, is)+0.5_R8*(temp3*(temp1*dvd%vadia(nd, ifc, &
&               0, is)+temp0*dvd%vadia(nd, ifc, 1, is))+temp*(pld%na(nd&
&               , icv1, is)+pld%na(nd, icv2, is))))
            END DO
            t0 = temp2*(dv%fnapsch(ifc, 0, is)+dv%fnapsch(ifc, 1, is)+&
&             0.5_R8*(temp*temp3))
            IF (0.0_R8 .LT. t0) THEN
              DO nd=1,nbdirs
                max2d(nd) = t0d(nd)
              END DO
              max2 = t0
            ELSE
              max2 = 0.0_R8
              max2d = 0.d0
            END IF
            DO nd=1,nbdirs
              srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) + &
&               max2d(nd)
            END DO
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max2
            IF (0.0_R8 .GT. t0) THEN
              DO nd=1,nbdirs
                min2d(nd) = t0d(nd)
              END DO
              min2 = t0
            ELSE
              min2 = 0.0_R8
              min2d = 0.d0
            END IF
            temp3 = min2/pl%na(icv1, is)
            DO nd=1,nbdirs
              srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) + &
&               (min2d(nd)-temp3*pld%na(nd, icv1, is))/pl%na(icv1, is)
            END DO
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp3
          END IF
        END DO
      CASE (9) 
!
! -- BCCON=9 -- PRESCRIBE THE DECAY LENGTH FOR THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  9 : density decay length ', conpar(is, ib, 1), &
&         ' on ', bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .NE. 0.0_R8, &
&               'B2STBC -- BCCON=9, CONPAR(,,1) = 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 9'&
&                                                           )
        END IF
!
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          sy = geo%fcs(ifc)
          temp3 = rt%rza(icv1, is)*pl%te(icv1) + pl%ti(icv1)
          temp4 = (co%dna0(icv1, is)+co%dpa0(icv1, is)*temp3)/conpar(is&
&           , ib, 1)
          DO nd=1,nbdirs
!
            srwd%sna0(nd, icv1, 0, is) = 0.d0
            srwd%sna0(nd, icv1, 1, is) = -(sy*(cod%dna0(nd, icv1, is)+&
&             temp3*cod%dpa0(nd, icv1, is)+co%dpa0(icv1, is)*(pl%te(icv1&
&             )*rtd%rza(nd, icv1, is)+rt%rza(icv1, is)*pld%te(nd, icv1)+&
&             pld%ti(nd, icv1))-temp4*conpard(nd, is, ib, 1))/conpar(is&
&             , ib, 1))
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = 0.0_R8
          srw%sna0(icv1, 1, is) = -(sy*temp4)
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
          IF (switch%mdf_fnb .EQ. 1) THEN
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              t0d(nd) = temp2*(dvd%fnapsch(nd, ifc, 0, is)+dvd%fnapsch(&
&               nd, ifc, 1, is))
            END DO
            t0 = temp2*(dv%fnapsch(ifc, 0, is)+dv%fnapsch(ifc, 1, is))
            IF (t0 .GE. 0.0_R8) THEN
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) &
&                 + t0d(nd)
              END DO
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
            ELSE
              temp2 = t0/pl%na(icv1, is)
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 + (t0d(nd)-temp2*pld%na(nd, icv1, is))/pl%na(icv1, is)
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp2
            END IF
            temp2 = 0.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp4 = pl%na(icv1, is) + pl%na(icv2, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*dv%vaecrb(ifc, 0, is) + temp0*dv%vaecrb(ifc, 1&
&             , is)
            DO nd=1,nbdirs
              t1d(nd) = -(temp2*(temp4*(temp1*dvd%vaecrb(nd, ifc, 0, is)&
&               +temp0*dvd%vaecrb(nd, ifc, 1, is))+temp*(pld%na(nd, icv1&
&               , is)+pld%na(nd, icv2, is))))
            END DO
            t1 = -(temp2*(temp*temp4))
            IF (t1 .GE. 0.0_R8) THEN
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) &
&                 + t1d(nd)
              END DO
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t1
            ELSE
              temp2 = t1/pl%na(icv1, is)
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 + (t1d(nd)-temp2*pld%na(nd, icv1, is))/pl%na(icv1, is)
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp2
            END IF
          END IF
        END DO
      CASE (10) 
!
! -- BCCON=10 -- leakage option for density, recommended for cases with drifts
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') 'BCCON = 10 : leakage ', &
&         conpar(is, ib, 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 10'&
&                                                           )
!lkw 30.06.2022
          CALL XERTST(conpar(is, ib, 2) .GE. 0.0_R8, &
&               'For BCCON = 10, CONPAR(,,2) should not be negative')
        END IF
!wdk      Note: now total face area taken. Need to check backwards
!wdk      compatibility for E/W boundaries
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the plasma cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp)
          temp4 = SQRT(arg12)
          result10 = temp4
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = 0.d0
            arg12d(nd) = (pl%te(icv1)*rtd%rza(nd, icv1, is)+rt%rza(icv1&
&             , is)*pld%te(nd, icv1)+pld%ti(nd, icv1))/(am(is)*mp)
            IF (arg12 .EQ. 0.d0) THEN
              result10d(nd) = 0.d0
            ELSE
              result10d(nd) = arg12d(nd)/(2.0*temp4)
            END IF
            srwd%sna0(nd, icv1, 1, is) = geo%fcs(ifc)*(conpar(is, ib, 1)&
&             *result10d(nd)+result10*conpard(nd, is, ib, 1))
            sna0_no_mdfd(nd, icv1, :, is) = sna0_no_mdfd(nd, icv1, :, is&
&             ) + srwd%sna0(nd, icv1, :, is)
          END DO
          srw%sna0(icv1, 0, is) = 0.0_R8
          srw%sna0(icv1, 1, is) = geo%fcs(ifc)*result10*conpar(is, ib, 1&
&           )
          sna0_no_mdf(icv1, :, is) = sna0_no_mdf(icv1, :, is) + srw%sna0&
&           (icv1, :, is)
          IF (switch%mdf_fnb .EQ. 0) THEN
            temp2 = 0.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp4 = (pl%na(icv1, is)+pl%na(icv2, is))/pl%na(icv1, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*(dv%vadia(ifc, 0, is)+dv%vaecrb(ifc, 0, is)) + &
&             temp0*(dv%vadia(ifc, 1, is)+dv%vaecrb(ifc, 1, is))
            DO nd=1,nbdirs
              y1d(nd) = temp2*(temp4*(temp1*(dvd%vadia(nd, ifc, 0, is)+&
&               dvd%vaecrb(nd, ifc, 0, is))+temp0*(dvd%vadia(nd, ifc, 1&
&               , is)+dvd%vaecrb(nd, ifc, 1, is)))+temp*((1.0-temp4)*pld&
&               %na(nd, icv1, is)+pld%na(nd, icv2, is))/pl%na(icv1, is))
            END DO
            y1 = temp2*(temp*temp4)
            IF (0.0_R8 .LT. y1) THEN
              DO nd=1,nbdirs
                max3d(nd) = y1d(nd)
              END DO
              max3 = y1
            ELSE
              max3 = 0.0_R8
              max3d = 0.d0
            END IF
            DO nd=1,nbdirs
              srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) - &
&               max3d(nd)
            END DO
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max3
          ELSE
            temp2 = 0.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp4 = (pl%na(icv1, is)+pl%na(icv2, is))/pl%na(icv1, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*dv%vaecrb(ifc, 0, is) + temp0*dv%vaecrb(ifc, 1&
&             , is)
            DO nd=1,nbdirs
              y2d(nd) = temp2*(temp4*(temp1*dvd%vaecrb(nd, ifc, 0, is)+&
&               temp0*dvd%vaecrb(nd, ifc, 1, is))+temp*((1.0-temp4)*pld%&
&               na(nd, icv1, is)+pld%na(nd, icv2, is))/pl%na(icv1, is))
            END DO
            y2 = temp2*(temp*temp4)
            IF (0.0_R8 .LT. y2) THEN
              DO nd=1,nbdirs
                max4d(nd) = y2d(nd)
              END DO
              max4 = y2
            ELSE
              max4 = 0.0_R8
              max4d = 0.d0
            END IF
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) - &
&               max4d(nd)
              t0d(nd) = temp2*(dvd%fnapsch(nd, ifc, 0, is)+dvd%fnapsch(&
&               nd, ifc, 1, is))
            END DO
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max4
            t0 = temp2*(dv%fnapsch(ifc, 0, is)+dv%fnapsch(ifc, 1, is))
            IF (t0 .GE. 0.0_R8) THEN
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) &
&                 + t0d(nd)
              END DO
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
            ELSE
              temp2 = t0/pl%na(icv1, is)
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 + (t0d(nd)-temp2*pld%na(nd, icv1, is))/pl%na(icv1, is)
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp2
            END IF
            arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*&
&             mp)
            temp4 = SQRT(arg12)
            result10 = temp4
            t0 = geo%fcs(ifc)*result10*conpar(is, ib, 2)
            DO nd=1,nbdirs
!lkw 30.06.2022{
              arg12d(nd) = (pl%te(icv1)*rtd%rza(nd, icv1, is)+rt%rza(&
&               icv1, is)*pld%te(nd, icv1)+pld%ti(nd, icv1))/(am(is)*mp)
              IF (arg12 .EQ. 0.d0) THEN
                result10d(nd) = 0.d0
              ELSE
                result10d(nd) = arg12d(nd)/(2.0*temp4)
              END IF
              t0d(nd) = geo%fcs(ifc)*(conpar(is, ib, 2)*result10d(nd)+&
&               result10*conpard(nd, is, ib, 2))
              srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) + &
&               pl%na(icv1, is)*t0d(nd) + t0*pld%na(nd, icv1, is)
!lkw 30.06.2022}
              srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) - &
&               t0d(nd)
            END DO
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0*pl%na(&
&             icv1, is)
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - t0
          END IF
        END DO
      CASE (11) 
!
! -- BCCON=11 -- particle flux feedback boundary condition
!
        CALL XERRAB('b2stbc_phys -- BCCON = 11 not adapted for WG')
!
! -- BCCON=12 -- particle density feedback boundary condition
!
      CASE (12) 
        CALL XERRAB('b2stbc_phys -- BCCON = 12 not adapted for WG')
!
! -- BCCON=13 -- Feedback constant density for a given particle flux
!
      CASE (13) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,a,a,i3,a,1p,2g14.7)') &
&         'BCCON = 13 : particle density to achieve '//&
&         'specified total flux on ', bcchar(ib), boundary_location(ib)&
&         , ' for species ', is, ' with parameters ', conpar(is, ib, 1)&
&         , conpar(is, ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (switch%ionising_core .GT. 0) WRITE(*, *) &
&               'imposed flux adapted due to ionising_core switch usage'
        END IF
!       ..compute average density on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
        totfluxd = 0.d0
        t1d = 0.d0
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t0 = t0 + geo%fcs(ifc)
          DO nd=1,nbdirs
            t1d(nd) = t1d(nd) + geo%fcs(ifc)*pld%na(nd, icv1, is)
          END DO
          t1 = t1 + geo%fcs(ifc)*pl%na(icv1, is)
          IF (bccon_flux_fb_style .EQ. 0) THEN
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, ifc, 0, &
&               is)+dvd%fna(nd, ifc, 1, is))
            END DO
            totflux = totflux - temp2*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1&
&             , is))
          ELSE
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna_eir(nd, ifc, &
&               0, is)+dvd%fna_eir(nd, ifc, 1, is))
            END DO
            totflux = totflux - temp2*(dv%fna_eir(ifc, 0, is)+dv%fna_eir&
&             (ifc, 1, is))
          END IF
        END DO
        DO nd=1,nbdirs
          t1d(nd) = t1d(nd)/t0
!nh conpar(is,ib,3) contains the contribution from the ionized neutrals
!   (ionising_core option)
          totpard(nd) = conpard(nd, is, ib, 1) + conpard(nd, is, ib, 3)
        END DO
        t1 = t1/t0
        totpar = conpar(is, ib, 1) + conpar(is, ib, 3)
        IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
          DO nd=1,nbdirs
            t3d(nd) = conpard(nd, is, ib, 2)
          END DO
          t3 = conpar(is, ib, 2)
        END IF
        IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref
          t3d = 0.d0
        END IF
        IF (totflux .GE. 0.) THEN
          DO nd=1,nbdirs
            x1d(nd) = totfluxd(nd)
          END DO
          x1 = totflux
        ELSE
          DO nd=1,nbdirs
            x1d(nd) = -totfluxd(nd)
          END DO
          x1 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          DO nd=1,nbdirs
            y3d(nd) = totpard(nd)
          END DO
          y3 = totpar
        ELSE
          DO nd=1,nbdirs
            y3d(nd) = -totpard(nd)
          END DO
          y3 = -totpar
        END IF
        IF (x1 .LT. y3) THEN
          IF (y3 .LT. 1.0e10_R8) THEN
            max5 = 1.0e10_R8
            max5d = 0.d0
          ELSE
            DO nd=1,nbdirs
              max5d(nd) = y3d(nd)
            END DO
            max5 = y3
          END IF
        ELSE IF (x1 .LT. 1.0e10_R8) THEN
          max5 = 1.0e10_R8
          max5d = 0.d0
        ELSE
          DO nd=1,nbdirs
            max5d(nd) = x1d(nd)
          END DO
          max5 = x1
        END IF
        temp2 = t3/max5
        temp4 = -((totflux-totpar)*temp2) + 1.0_R8
        DO nd=1,nbdirs
          t2d(nd) = temp4*t1d(nd) - t1*(temp2*(totfluxd(nd)-totpard(nd))&
&           +(totflux-totpar)*(t3d(nd)-temp2*max5d(nd))/max5)
        END DO
        t2 = temp4*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, &
&                                        '(a,i3,1p,4(1x,e15.6))') &
&             'bccon=13: is, curr_flux, desired_flux, old/new density, '&
&                                        , is, totflux, totpar, t1, t2
!       ..impose density
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = geo%fcs(ifc)*vbig*t2d(nd)
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*t2
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (14) 
!
! -- BCCON=14 -- Sound speed flux
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
            WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&           'BCCON = 14 : sound speed flux ', mompar(is, ib, 1), ' on '&
&           , bcchar(ib), boundary_location(ib), ' for species ', is
          ELSE
            WRITE(*, '(a,a,1p,g14.7,a,a,a,a,i3)') &
&           'BCCON = 14 with MOMPAR(:,:,2) > 0.5 : non-marginal ', &
&           'sheath BC, with MOMPAR(:,:,1) = ', mompar(is, ib, 1), &
&           ' on boundary ', bcchar(ib), boundary_location(ib), &
&           ' for species ', is
          END IF
          CALL XERTST(conpar(is, ib, 2) .GE. 0.0_R8, &
&               'BCCON = 14, CONPAR(,,2) < 0 not allowed!')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            s1 = geo%fcpbs(ifc)
          ELSE
            s1 = -geo%fcpbs(ifc)
          END IF
!srv 15.02.26
          CALL CSBC_IS_DV(icv1, ib, is, cs, csd, nbdirs)
!srv 15.02.26
          CALL VBC_IS_DV(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), &
&                  csbcd(:, icv1, is), wrk, nbdirs)
          IF (wrk .GE. 0.) THEN
            abs0 = wrk
          ELSE
            abs0 = -wrk
          END IF
          IF (abs0 .LT. geo%qalfmin) THEN
            temp2 = geo%fcs(ifc)*geo%qalfmax
            DO nd=1,nbdirs
              srwd%sna0(nd, icv1, 0, is) = 0.d0
              srwd%sna0(nd, icv1, 1, is) = -(temp2*(cs*mompard(nd, is, &
&               ib, 1)+mompar(is, ib, 1)*csd(nd)))
              sna0_no_mdfd(nd, icv1, :, is) = sna0_no_mdfd(nd, icv1, :, &
&               is) + srwd%sna0(nd, icv1, :, is)
            END DO
            srw%sna0(icv1, 0, is) = 0.0_R8
            srw%sna0(icv1, 1, is) = -(temp2*(mompar(is, ib, 1)*cs))
            sna0_no_mdf(icv1, :, is) = sna0_no_mdf(icv1, :, is) + srw%&
&             sna0(icv1, :, is)
            IF (switch%mdf_fnb .EQ. 0) THEN
              temp2 = 0.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
              temp4 = (pl%na(icv1, is)+pl%na(icv2, is))/pl%na(icv1, is)
              temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
              temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
              temp = temp1*dv%vaecrb(ifc, 0, is) + temp0*dv%vaecrb(ifc, &
&               1, is)
              DO nd=1,nbdirs
                y4d(nd) = temp2*(temp4*(temp1*dvd%vaecrb(nd, ifc, 0, is)&
&                 +temp0*dvd%vaecrb(nd, ifc, 1, is))+temp*((1.0-temp4)*&
&                 pld%na(nd, icv1, is)+pld%na(nd, icv2, is))/pl%na(icv1&
&                 , is))
              END DO
              y4 = temp2*(temp*temp4)
              IF (0.0_R8 .LT. y4) THEN
                DO nd=1,nbdirs
                  max6d(nd) = y4d(nd)
                END DO
                max6 = y4
              ELSE
                max6 = 0.0_R8
                max6d = 0.d0
              END IF
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 - max6d(nd)
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max6
            ELSE
              temp2 = 0.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
              temp4 = (pl%na(icv1, is)+pl%na(icv2, is))/pl%na(icv1, is)
              temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
              temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
              temp = temp1*(dv%vaecrb(ifc, 0, is)+dv%vadia(ifc, 0, is)) &
&               + temp0*(dv%vaecrb(ifc, 1, is)+dv%vadia(ifc, 1, is))
              DO nd=1,nbdirs
                y5d(nd) = temp2*(temp4*(temp1*(dvd%vaecrb(nd, ifc, 0, is&
&                 )+dvd%vadia(nd, ifc, 0, is))+temp0*(dvd%vaecrb(nd, ifc&
&                 , 1, is)+dvd%vadia(nd, ifc, 1, is)))+temp*((1.0-temp4)&
&                 *pld%na(nd, icv1, is)+pld%na(nd, icv2, is))/pl%na(icv1&
&                 , is))
              END DO
              y5 = temp2*(temp*temp4)
              IF (0.0_R8 .LT. y5) THEN
                DO nd=1,nbdirs
                  max7d(nd) = y5d(nd)
                END DO
                max7 = y5
              ELSE
                max7 = 0.0_R8
                max7d = 0.d0
              END IF
              temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 - max7d(nd)
                t0d(nd) = temp2*(dvd%fnapsch(nd, ifc, 0, is)+dvd%fnapsch&
&                 (nd, ifc, 1, is))
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max7
              t0 = temp2*(dv%fnapsch(ifc, 0, is)+dv%fnapsch(ifc, 1, is))
              IF (t0 .GE. 0.0_R8) THEN
                DO nd=1,nbdirs
                  srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is&
&                   ) + t0d(nd)
                END DO
                srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
              ELSE
                temp2 = t0/pl%na(icv1, is)
                DO nd=1,nbdirs
                  srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is&
&                   ) + (t0d(nd)-temp2*pld%na(nd, icv1, is))/pl%na(icv1&
&                   , is)
                END DO
                srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp2
              END IF
            END IF
          ELSE
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              vbndd(nd) = temp2*(geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, ifc, &
&               0, is)+geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc, 1, is))
              srwd%sna0(nd, icv1, 0, is) = 0.d0
            END DO
            vbnd = temp2*(geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%&
&             fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))
            srw%sna0(icv1, 0, is) = 0.0_R8
            IF (wrk .GE. 0.) THEN
              abs6 = wrk
            ELSE
              abs6 = -wrk
            END IF
            temp4 = SIGN(1.0_R8, wrk)
            DO nd=1,nbdirs
              x2d(nd) = abs6*csbcd(nd, icv1, is)
              y6d(nd) = temp4*vbcd(nd, icv1, is) + vbndd(nd)
            END DO
            x2 = csbc(icv1, is)*abs6
            y6 = temp4*vbc(icv1, is) + vbnd
            IF (x2 .LT. y6) THEN
              DO nd=1,nbdirs
                max8d(nd) = y6d(nd)
              END DO
              max8 = y6
            ELSE
              DO nd=1,nbdirs
                max8d(nd) = x2d(nd)
              END DO
              max8 = x2
            END IF
            DO nd=1,nbdirs
              srwd%sna0(nd, icv1, 1, is) = -(geo%fcs(ifc)*(max8*mompard(&
&               nd, is, ib, 1)+mompar(is, ib, 1)*max8d(nd)))
            END DO
            srw%sna0(icv1, 1, is) = -(geo%fcs(ifc)*mompar(is, ib, 1)*&
&             max8)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              temp4 = co%dna0(icv1, is)/conpar(is, ib, 2)
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 - geo%fcs(ifc)*(cod%dna0(nd, icv1, is)-temp4*conpard(&
&                 nd, is, ib, 2))/conpar(is, ib, 2)
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - geo%fcs(&
&               ifc)*temp4
            END IF
            DO nd=1,nbdirs
              sna0_no_mdfd(nd, icv1, :, is) = srwd%sna0(nd, icv1, :, is)
            END DO
            sna0_no_mdf(icv1, :, is) = srw%sna0(icv1, :, is)
            IF (switch%mdf_fnb .NE. 0) THEN
              temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
              temp4 = pl%na(icv1, is) + pl%na(icv2, is)
              temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
              temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
              temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1&
&               , is)
              DO nd=1,nbdirs
                t0d(nd) = temp2*(dvd%fnapsch(nd, ifc, 0, is)+dvd%fnapsch&
&                 (nd, ifc, 1, is)+0.5_R8*(temp4*(temp1*dvd%vadia(nd, &
&                 ifc, 0, is)+temp0*dvd%vadia(nd, ifc, 1, is))+temp*(pld&
&                 %na(nd, icv1, is)+pld%na(nd, icv2, is))))
              END DO
              t0 = temp2*(dv%fnapsch(ifc, 0, is)+dv%fnapsch(ifc, 1, is)+&
&               0.5_R8*(temp*temp4))
              IF (0.0_R8 .LT. t0) THEN
                DO nd=1,nbdirs
                  max9d(nd) = t0d(nd)
                END DO
                max9 = t0
              ELSE
                max9 = 0.0_R8
                max9d = 0.d0
              END IF
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is) &
&                 + max9d(nd)
              END DO
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max9
              IF (0.0_R8 .GT. t0) THEN
                DO nd=1,nbdirs
                  min3d(nd) = t0d(nd)
                END DO
                min3 = t0
              ELSE
                min3 = 0.0_R8
                min3d = 0.d0
              END IF
              temp4 = min3/pl%na(icv1, is)
              DO nd=1,nbdirs
                srwd%sna0(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is) &
&                 + (min3d(nd)-temp4*pld%na(nd, icv1, is))/pl%na(icv1, &
&                 is)
              END DO
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + temp4
            END IF
          END IF
        END DO
      CASE (15) 
!
! -- BCCON=15 -- prescribe a radial leakage velocity, as a multiplier to the local thermal velocity
!
!srv 25.09.09 16.02.12
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(2a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON = 15 : prescribe the decay length for the density', &
&         ' for drifs switched on ', conpar(is, ib, 1), ' on ', bcchar(&
&         ib), boundary_location(ib), ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 15'&
&                                                           )
        END IF
!wdk      Notes:
!wdk       * need correction for misaligned grids -> t1
!wdk       * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp)
          temp4 = SQRT(arg12)
          csb = temp4
          t0 = geo%fcqalf(ifc, 1)
          t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&           fcqbet(ifc, 0)
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1
          temp1 = t0*pl%na(icv2, is) - temp2*(pl%na(mpg%fcvx(ifc, 2), is&
&           )-pl%na(mpg%fcvx(ifc, 1), is))
          DO nd=1,nbdirs
            arg12d(nd) = (pl%te(icv1)*rtd%rza(nd, icv1, is)+rt%rza(icv1&
&             , is)*pld%te(nd, icv1)+pld%ti(nd, icv1))/(am(is)*mp)
            IF (arg12 .EQ. 0.d0) THEN
              csbd(nd) = 0.d0
            ELSE
              csbd(nd) = arg12d(nd)/(2.0*temp4)
            END IF
            srwd%sna0(nd, icv1, 0, is) = vbig*(temp1*cod%cdna(nd, ifc, 1&
&             , is)+co%cdna(ifc, 1, is)*(t0*pld%na(nd, icv2, is)-temp2*(&
&             pld%na(nd, mpg%fcvx(ifc, 2), is)-pld%na(nd, mpg%fcvx(ifc, &
&             1), is))))
            srwd%sna0(nd, icv1, 1, is) = -(vbig*(t0*cod%cdna(nd, ifc, 1&
&             , is)-geo%fcs(ifc)*(csb*conpard(nd, is, ib, 1)+conpar(is, &
&             ib, 1)*csbd(nd))))
            sna0_no_mdfd(nd, icv1, :, is) = srwd%sna0(nd, icv1, :, is)
          END DO
          srw%sna0(icv1, 0, is) = vbig*(co%cdna(ifc, 1, is)*temp1)
          srw%sna0(icv1, 1, is) = -(vbig*(co%cdna(ifc, 1, is)*t0-conpar(&
&           is, ib, 1)*geo%fcs(ifc)*csb))
          sna0_no_mdf(icv1, :, is) = srw%sna0(icv1, :, is)
!srv 25.09.09 }
        END DO
      CASE (16) 
!
! -- BCCON=16 -- Feedback boundary condition: given total particle flux with constant density  !srv 16.02.12 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 16 : given total particle flux with constant', &
&         ' density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 16 only applicable to core boundaries !')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 19 .OR. bccon(is, ibw) .EQ. 21)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB(&
&       'BCCON types 16, 19, 21, 22, 23, 25, 26 and 27 cannot be mixed!'&
&                  )
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 16'&
&                          )
        END IF
!srv 16.02.12 }
        IF (.NOT.once_bccon(is)) THEN
          IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                sconpard(nd, is) = 0.d0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=16: Summed value is ', sconpar(is)
            nas = 0.0_R8
            vs = 0.0_R8
            nasd = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  DO nd=1,nbdirs
                    nasd(nd) = nasd(nd) + geo%cvvol(icv)*pld%na(nd, icv&
&                     , is)
                  END DO
                  nas = nas + pl%na(icv, is)*geo%cvvol(icv)
                  vs = vs + geo%cvvol(icv)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              nasd(nd) = nasd(nd)/vs
            END DO
            nas = nas/vs
            totflux = 0.0_R8
            totfluxd = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                IF (switch%mdf_fnb .NE. 0) THEN
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna_mdf(&
&                       nd, ifc, 0, is)+dvd%fna_mdf(nd, ifc, 1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna_mdf(ifc, 0, is)+dv&
&                     %fna_mdf(ifc, 1, is))
                  END DO
                ELSE
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, &
&                       ifc, 0, is)+dvd%fna(nd, ifc, 1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna(ifc, 0, is)+dv%fna&
&                     (ifc, 1, is))
                  END DO
                END IF
              END IF
            END DO
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
            END IF
            IF (totflux .GE. 0.) THEN
              x3 = totflux
            ELSE
              x3 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y7 = sconpar(is)
            ELSE
              y7 = -sconpar(is)
            END IF
            IF (x3 .LT. y7) THEN
              max10 = y7
            ELSE
              max10 = x3
            END IF
            IF (max10 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                DO nd=1,nbdirs
                  x4d(nd) = totfluxd(nd)
                END DO
                x4 = totflux
              ELSE
                DO nd=1,nbdirs
                  x4d(nd) = -totfluxd(nd)
                END DO
                x4 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                DO nd=1,nbdirs
                  y8d(nd) = sconpard(nd, is)
                END DO
                y8 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  y8d(nd) = -sconpard(nd, is)
                END DO
                y8 = -sconpar(is)
              END IF
              IF (x4 .LT. y8) THEN
                DO nd=1,nbdirs
                  max11d(nd) = y8d(nd)
                END DO
                max11 = y8
              ELSE
                DO nd=1,nbdirs
                  max11d(nd) = x4d(nd)
                END DO
                max11 = x4
              END IF
              temp2 = t3/max11
              temp4 = -((totflux-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                nasd(nd) = temp4*nasd(nd) - nas*(temp2*(totfluxd(nd)-&
&                 sconpard(nd, is))+(totflux-sconpar(is))*(t3d(nd)-temp2&
&                 *max11d(nd))/max11)
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  DO nd=1,nbdirs
                    srwd%sna0(nd, icv, 0, is) = geo%fcs(ifc)*vbig*nasd(&
&                     nd)
                    srwd%sna0(nd, icv, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv, 0, is) = srwd%sna0(nd, icv, 0&
&                     , is)
                    sna0_no_mdfd(nd, icv, 1, is) = srwd%sna0(nd, icv, 1&
&                     , is)
                  END DO
                  srw%sna0(icv, 0, is) = vbig*nas*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          ELSE
!srv 16.02.12 }
            CALL XERRAB('B2STBC -- BCCON=16, NOT AVAILABLE FOR N,W,E')
          END IF
        END IF
      CASE (17) 
!
! -- BCCON=17 -- FILLER
!
        CALL XERRAB('B2STBC -- BCCON=17, NOT YET AVAILABLE')
!
! -- BCCON=18 -- FILLER
!
      CASE (18) 
        CALL XERRAB('B2STBC -- BCCON=18, NOT YET AVAILABLE')
!
! -- BCCON=19 -- Feedback boundary condition: given sum of integrated neutrals and
!                main ion particle fluxes with constant ion density.
!
      CASE (19) 
        IF (switch%spatial_hybrid .NE. 0) CALL XERRAB(&
&                          'BCCON = 19 not compatible with spatial hybr'&
&                                              )
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, *) 'BCCON = 19 : given sum of particle flux '//&
&         'for isonuclear sequence with constant '//&
&         'highest ionisation stage density '
!             write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 19 only applicable to core boundaries !')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 21)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (is .LT. ns - 1) THEN
            result11 = LNEXT(is, is + 1)
            CALL XERTST(.NOT.result11, &
&                 'BCCON = 19 can only be applied to ions in their '//&
&                 'highest ionisation stage')
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 19'&
&                          )
        END IF
!srv 16.02.12 }
        IF (.NOT.once_bccon(is)) THEN
          IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                sconpard(nd, is) = 0.d0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=19: Summed value is ', sconpar(is)
            nas = 0.0_R8
            vs = 0.0_R8
            nasd = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  DO nd=1,nbdirs
                    nasd(nd) = nasd(nd) + geo%cvvol(icv)*pld%na(nd, icv&
&                     , is)
                  END DO
                  nas = nas + pl%na(icv, is)*geo%cvvol(icv)
                  vs = vs + geo%cvvol(icv)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              nasd(nd) = nasd(nd)/vs
            END DO
            nas = nas/vs
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
            totfluxid = 0.d0
            totfluxnd = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
! totfluxn here means the sum of fluxes over all ions (including fluid
! neutrals) of this isotope except for the highest ionisation stage.
! For coupled runs, both fna and fna_mdf are rescaled for neutrals
! Note that for neutrals fna = fna_mdf
                  DO isb=0,ns-1
                    IF (b2espcr(is) .EQ. b2espcr(isb) .AND. is .NE. isb&
&                   ) THEN
                      IF ((.NOT.is_neutral(isb)) .OR. switch%use_eirene &
&                         .EQ. 0) THEN
                        IF (switch%mdf_fnb .NE. 0) THEN
                          temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                          DO nd=1,nbdirs
                            totfluxnd(nd) = totfluxnd(nd) - temp2*(dvd%&
&                             fna_mdf(nd, ifc, 0, is)+dvd%fna_mdf(nd, &
&                             ifc, 1, is))
                          END DO
                          totfluxn = totfluxn - temp2*(dv%fna_mdf(ifc, 0&
&                           , is)+dv%fna_mdf(ifc, 1, is))
                        ELSE
                          temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                          DO nd=1,nbdirs
                            totfluxnd(nd) = totfluxnd(nd) - temp2*(dvd%&
&                             fna(nd, ifc, 0, is)+dvd%fna(nd, ifc, 1, is&
&                             ))
                          END DO
                          totfluxn = totfluxn - temp2*(dv%fna(ifc, 0, is&
&                           )+dv%fna(ifc, 1, is))
                        END IF
                      END IF
                    END IF
                  END DO
! totfluxi here means the flux of the ion in the highest ionisation stage.
                  IF (switch%mdf_fnb .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna_mdf&
&                       (nd, ifc, 0, is)+dvd%fna_mdf(nd, ifc, 1, is))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna_mdf(ifc, 0, is)+&
&                     dv%fna_mdf(ifc, 1, is))
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna(nd&
&                       , ifc, 0, is)+dvd%fna(nd, ifc, 1, is))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna(ifc, 0, is)+dv%&
&                     fna(ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
            END IF
            IF (totfluxn + totfluxi .GE. 0.) THEN
              x5 = totfluxn + totfluxi
            ELSE
              x5 = -(totfluxn+totfluxi)
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y9 = sconpar(is)
            ELSE
              y9 = -sconpar(is)
            END IF
            IF (x5 .LT. y9) THEN
              max12 = y9
            ELSE
              max12 = x5
            END IF
            IF (max12 .GT. 0.0_R8) THEN
              IF (totfluxn + totfluxi .GE. 0.) THEN
                DO nd=1,nbdirs
                  x6d(nd) = totfluxnd(nd) + totfluxid(nd)
                END DO
                x6 = totfluxn + totfluxi
              ELSE
                DO nd=1,nbdirs
                  x6d(nd) = -totfluxnd(nd) - totfluxid(nd)
                END DO
                x6 = -(totfluxn+totfluxi)
              END IF
              IF (x6 .LT. sconpar(is)) THEN
                DO nd=1,nbdirs
                  max13d(nd) = sconpard(nd, is)
                END DO
                max13 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  max13d(nd) = x6d(nd)
                END DO
                max13 = x6
              END IF
              temp2 = t3/max13
              temp4 = -((totfluxn+totfluxi-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                nasd(nd) = temp4*nasd(nd) - nas*(temp2*(totfluxnd(nd)+&
&                 totfluxid(nd)-sconpard(nd, is))+(totfluxn+totfluxi-&
&                 sconpar(is))*(t3d(nd)-temp2*max13d(nd))/max13)
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,es14.7,a,es14.7)') &
&           ' NAS=', nas, ' totfluxn=', totfluxn, ' totfluxi=', totfluxi&
&           , ' SCONPAR=', sconpar(is), ' totfluxn+totfluxi=', totfluxn &
&           + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  DO nd=1,nbdirs
                    srwd%sna0(nd, icv, 0, is) = geo%fcs(ifc)*vbig*nasd(&
&                     nd)
                    srwd%sna0(nd, icv, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv, 0, is) = srwd%sna0(nd, icv, 0&
&                     , is)
                    sna0_no_mdfd(nd, icv, 1, is) = srwd%sna0(nd, icv, 1&
&                     , is)
                  END DO
                  srw%sna0(icv, 0, is) = vbig*nas*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          ELSE
!srv 16.02.12 }
            CALL XERRAB('B2STBC -- BCCON=19, NOT AVAILABLE FOR N,W,E')
          END IF
        END IF
      CASE (20) 
!
! -- BCCON=20 -- constant density feedback condition
!
        CALL XERRAB('b2stbc_phys -- BCCON = 20 not adapted for WG')
!
!    -- BCCON=21 -- PRESCRIBE THE VALUE OF THE DENSITY !lk and IYS 01.03.2013
!                   AND ADD A POLOIDAL DENSITY VARIATION TO GET A SOLUTION
!                   WHICH IS AS CLOSE AS POSSIBLE TO NEOCLASSICAL THEORY
!                   DERIVED FOR PURE H/D/T PLASMA ONLY.
!
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
! CORRESPONDING CONDITION ON ION TEMPERATURE (BCENI=23,24)
!
      CASE (21) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7)') 'BCCON = 21 : constant density', &
&         conpar(is, ib, 1)
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 21 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&                   'BCCON = 21, CONPAR(,,1) !> 0')
! IYS 22.01.2015
              CALL XERTST(conpar(is, ib, 1) .EQ. conpar(is, ibw, 1), &
&                   'BCCON = 21, Average density on all parts '//&
&                   'of the surface should be the same')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.21 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.21 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 21 is applied for main ion only ')
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=21 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=25 instead!'
            WRITE(6, *) &
&           'Use of BCCON=21 only meant for single-fluid runs!'
            WRITE(6, *) 'Use BCCON=25 instead!'
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 21'&
&                          )
        END IF
!lk and IYS 01.03.2013}
        IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') .AND. mpg%&
&           cvonclosedsurface(mpg%bccv(mpg%bccvp(ibw, 1), 2))) THEN
          IF (.NOT.once_bccon(is)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            t1d = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  t0 = t0 + geo%cvvol(icv2)
                  DO nd=1,nbdirs
                    t1d(nd) = t1d(nd) + geo%cvvol(icv2)*(pld%ti(nd, icv1&
&                     )+pld%te(nd, icv1))
                  END DO
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                END DO
              END IF
            END DO
! Sum of volume-averaged electron and ion temperatures
            IF (t0 .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                t1d(nd) = t1d(nd)/t0
              END DO
              t1 = t1/t0
            END IF
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  temp2 = vbig*geo%fcs(ifc)
                  temp4 = pl%ti(icv) + pl%te(icv)
                  temp1 = conpar(is, ibw, 1)*t1/temp4
                  DO nd=1,nbdirs
                    srwd%sna0(nd, icv, 0, is) = temp2*(t1*conpard(nd, is&
&                     , ibw, 1)+conpar(is, ibw, 1)*t1d(nd)-temp1*(pld%ti&
&                     (nd, icv)+pld%te(nd, icv)))/temp4
                    srwd%sna0(nd, icv, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv, 0, is) = srwd%sna0(nd, icv, 0&
&                     , is)
                    sna0_no_mdfd(nd, icv, 1, is) = srwd%sna0(nd, icv, 1&
&                     , is)
                  END DO
                  srw%sna0(icv, 0, is) = temp2*temp1
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCCON=21, VALID FOR CORE ONLY')
        END IF
      CASE (22) 
!
! -- BCCON=22 -- Feedback boundary condition: given total particle flux with
!    constant average density. The poloidal density variation is added to make
!    the solution as close as possible to the neoclassical value derived for
!    pure H/D/T plasma.
!    It is recommended to use this boundary condition
!    together with corresponding boundary condition on ion temperature
!    (BCENI=23,24) !srv 16.02.12, IYS 01.03.2013 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 22 : given total particle flux with constant', &
&         ' density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 22 only applicable to core boundaries !')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.22 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.22 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 22 is applied for main ion only ')
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=22 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=26 instead!'
            WRITE(6, *) &
&           'Use of BCCON=22 only meant for single-fluid runs!'
            WRITE(6, *) 'Use BCCON=26 instead!'
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 22'&
&                          )
        END IF
!iys 01.03.13 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                sconpard(nd, is) = 0.d0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=22: Summed value is ', sconpar(is)
            totflux = 0.0_R8
! Volume between two surfaces             !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            nas = 0.0_R8
            nasd = 0.d0
            totfluxd = 0.d0
            t1d = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  t0 = t0 + geo%cvvol(icv2)
                  DO nd=1,nbdirs
                    t1d(nd) = t1d(nd) + geo%cvvol(icv2)*(pld%ti(nd, icv1&
&                     )+pld%te(nd, icv1))
                    nasd(nd) = nasd(nd) + geo%cvvol(icv2)*pld%na(nd, &
&                     icv1, is)
                  END DO
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                  IF (switch%mdf_fnb .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna_mdf(&
&                       nd, ifc, 0, is)+dvd%fna_mdf(nd, ifc, 1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna_mdf(ifc, 0, is)+dv&
&                     %fna_mdf(ifc, 1, is))
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, &
&                       ifc, 0, is)+dvd%fna(nd, ifc, 1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna(ifc, 0, is)+dv%fna&
&                     (ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
! Sum of volume-averaged electron and ion temperatures
              t1d(nd) = t1d(nd)/t0
! Volume-averaged density
              nasd(nd) = nasd(nd)/t0
            END DO
            t1 = t1/t0
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
            END IF
            IF (totflux .GE. 0.) THEN
              x7 = totflux
            ELSE
              x7 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y10 = sconpar(is)
            ELSE
              y10 = -sconpar(is)
            END IF
            IF (x7 .LT. y10) THEN
              max14 = y10
            ELSE
              max14 = x7
            END IF
            IF (max14 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                DO nd=1,nbdirs
                  x8d(nd) = totfluxd(nd)
                END DO
                x8 = totflux
              ELSE
                DO nd=1,nbdirs
                  x8d(nd) = -totfluxd(nd)
                END DO
                x8 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                DO nd=1,nbdirs
                  y11d(nd) = sconpard(nd, is)
                END DO
                y11 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  y11d(nd) = -sconpard(nd, is)
                END DO
                y11 = -sconpar(is)
              END IF
              IF (x8 .LT. y11) THEN
                DO nd=1,nbdirs
                  max15d(nd) = y11d(nd)
                END DO
                max15 = y11
              ELSE
                DO nd=1,nbdirs
                  max15d(nd) = x8d(nd)
                END DO
                max15 = x8
              END IF
              temp2 = t3/max15
              temp4 = -((totflux-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                nasd(nd) = temp4*nasd(nd) - nas*(temp2*(totfluxd(nd)-&
&                 sconpard(nd, is))+(totflux-sconpar(is))*(t3d(nd)-temp2&
&                 *max15d(nd))/max15)
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  temp2 = vbig*geo%fcs(ifc)
                  temp4 = pl%ti(icv) + pl%te(icv)
                  temp1 = nas*t1/temp4
                  DO nd=1,nbdirs
                    srwd%sna0(nd, icv, 0, is) = temp2*(t1*nasd(nd)+nas*&
&                     t1d(nd)-temp1*(pld%ti(nd, icv)+pld%te(nd, icv)))/&
&                     temp4
                    srwd%sna0(nd, icv, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv, 0, is) = srwd%sna0(nd, icv, 0&
&                     , is)
                    sna0_no_mdfd(nd, icv, 1, is) = srwd%sna0(nd, icv, 1&
&                     , is)
                  END DO
                  srw%sna0(icv, 0, is) = temp2*temp1
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=22 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (23) 
!
! -- BCCON=23 -- Feedback boundary condition: given sum of integrated neutrals and
!    main ion particle fluxes with constant average density.
!    The poloidal density variation is added to make the solution
!    as close as possible to the neoclassical value derived for pure H/D/T plasma.
!    It is recommended to use this boundary condition with corresponding
!    boundary condition on ion temperature (BCENI=23,24) !srv 16.02.12, IYS 04.03.2013 {
!    Use this boundary condition for pure H/D/T plasma only,
!    If a minor impurity is present, please use the BCCON=27 instead. ! IYS 21.01.2016
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 23 : given total particle flux with constant', &
&         ' density for main ion is =', ismain
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 23 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GE. 0.0_R8, &
&                   'BCCON = 23, CONPAR(,,1) < 0')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.23 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.23 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=23 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=27 instead!'
            WRITE(6, *) &
&           'Use of BCCON=23 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=27 instead!'
          END IF
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 23 is applied for main ion only ')
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 23'&
&                          )
        END IF
!IYS 04.03.2013 }
!
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                sconpard(nd, is) = 0.d0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=23: Summed value is ', sconpar(is)
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            nas = 0.0_R8
            nasd = 0.d0
            t1d = 0.d0
            totfluxid = 0.d0
            totfluxnd = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  isb = ismain0
                  IF (is_neutral(isb)) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxnd(nd) = totfluxnd(nd) - temp2*(dvd%fna(nd&
&                       , ifc, 0, isb)+dvd%fna(nd, ifc, 1, isb))
                    END DO
                    totfluxn = totfluxn - temp2*(dv%fna(ifc, 0, isb)+dv%&
&                     fna(ifc, 1, isb))
                  END IF
                  isb = ismain
                  IF (switch%mdf_fnb .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna_mdf&
&                       (nd, ifc, 0, isb)+dvd%fna_mdf(nd, ifc, 1, isb))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna_mdf(ifc, 0, isb)&
&                     +dv%fna_mdf(ifc, 1, isb))
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna(nd&
&                       , ifc, 0, isb)+dvd%fna(nd, ifc, 1, isb))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna(ifc, 0, isb)+dv%&
&                     fna(ifc, 1, isb))
                  END IF
                  t0 = t0 + geo%cvvol(icv2)
                  DO nd=1,nbdirs
                    t1d(nd) = t1d(nd) + geo%cvvol(icv2)*(pld%ti(nd, icv1&
&                     )+pld%te(nd, icv1))
                    nasd(nd) = nasd(nd) + geo%cvvol(icv2)*pld%na(nd, &
&                     icv1, is)
                  END DO
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
! Sum of volume-averaged electron and ion temperatures
              t1d(nd) = t1d(nd)/t0
! Volume-averaged density
              nasd(nd) = nasd(nd)/t0
            END DO
            t1 = t1/t0
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
            END IF
            IF (totfluxn .GE. 0.) THEN
              abs1 = totfluxn
            ELSE
              abs1 = -totfluxn
            END IF
            IF (totfluxi .GE. 0.) THEN
              abs7 = totfluxi
            ELSE
              abs7 = -totfluxi
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              abs11 = sconpar(is)
            ELSE
              abs11 = -sconpar(is)
            END IF
            IF (abs1 + abs7 + abs11 .GT. 0.0_R8) THEN
              IF (totfluxn .GE. 0.) THEN
                DO nd=1,nbdirs
                  abs2d(nd) = totfluxnd(nd)
                END DO
                abs2 = totfluxn
              ELSE
                DO nd=1,nbdirs
                  abs2d(nd) = -totfluxnd(nd)
                END DO
                abs2 = -totfluxn
              END IF
              IF (totfluxi .GE. 0.) THEN
                DO nd=1,nbdirs
                  abs8d(nd) = totfluxid(nd)
                END DO
                abs8 = totfluxi
              ELSE
                DO nd=1,nbdirs
                  abs8d(nd) = -totfluxid(nd)
                END DO
                abs8 = -totfluxi
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                DO nd=1,nbdirs
                  abs12d(nd) = sconpard(nd, is)
                END DO
                abs12 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  abs12d(nd) = -sconpard(nd, is)
                END DO
                abs12 = -sconpar(is)
              END IF
              temp2 = t3/(abs2+abs8+abs12)
              temp4 = -((totfluxn+totfluxi-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                nasd(nd) = temp4*nasd(nd) - nas*(temp2*(totfluxnd(nd)+&
&                 totfluxid(nd)-sconpard(nd, is))+(totfluxn+totfluxi-&
&                 sconpar(is))*(t3d(nd)-temp2*(abs2d(nd)+abs8d(nd)+&
&                 abs12d(nd)))/(abs2+abs8+abs12))
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(5(a,es14.7))') ' NAS=', nas, ' totfluxn=', &
&           totfluxn, ' totfluxi=', totfluxi, ' SCONPAR=', sconpar(is), &
&           ' totfluxn+totfluxi=', totfluxn + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  temp2 = vbig*geo%fcs(ifc)
                  temp4 = pl%ti(icv) + pl%te(icv)
                  temp1 = nas*t1/temp4
                  DO nd=1,nbdirs
                    srwd%sna0(nd, icv, 0, is) = temp2*(t1*nasd(nd)+nas*&
&                     t1d(nd)-temp1*(pld%ti(nd, icv)+pld%te(nd, icv)))/&
&                     temp4
                    srwd%sna0(nd, icv, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv, 0, is) = srwd%sna0(nd, icv, 0&
&                     , is)
                    sna0_no_mdfd(nd, icv, 1, is) = srwd%sna0(nd, icv, 1&
&                     , is)
                  END DO
                  srw%sna0(icv, 0, is) = temp2*temp1
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=23 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (24) 
!
! -- BCCON=24 -- constant density scaled by density on the ring bc_type21_ref away
!
        CALL XERRAB('b2stbc_phys -- BCCON = 24 not adapted for WG')
!
! -- BCCON=25  Feedback boundary condition: PRESCRIBE THE AVERAGE VALUE OF THE DENSITY  !lk and IYS 01.03.2013{
!              AND ADD A POLOIDAL DENSITY VARIATION FROM NEIGHBOURING RADIAL CELL.
!              THIS BOUNDARY CONDITION IS SUITABLE FOR ANY SPECIES OF
!              MULTI-SPECIES PLASMA (I.E. IN THE CASE WHEN THE CONDITION USED
!              IN BCCON=21 FAILS)
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              CORRESPONDING CONDITION ON ION TEMPERATURE (BCENI=26,27)
!
      CASE (25) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7)') &
&         'BCCON = 25 : constant average density', conpar(is, ib, 1)
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 25 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GT. 0.0_R8, &
&                   'BCCON = 25, CONPAR(,,1) !> 0')
! IYS 22.01.2015
              CALL XERTST(conpar(is, ib, 1) .EQ. conpar(is, ibw, 1), &
&                   'BCCON = 25, Average density on all parts '//&
&                   'of the surface should be the same')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.25 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.25 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 25'&
&                          )
        END IF
!lk and IYS 01.03.2013}
!
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
          IF (.NOT.once_bccon(is)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
! Volume between two surfaces              !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged density
            t1 = 0.0_R8
            t1d = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  t0 = t0 + geo%cvvol(icv)
                  DO nd=1,nbdirs
                    t1d(nd) = t1d(nd) + geo%cvvol(icv)*pld%na(nd, icv, &
&                     is)
                  END DO
                  t1 = t1 + pl%na(icv, is)*geo%cvvol(icv)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              t1d(nd) = t1d(nd)/t0
            END DO
            t1 = t1/t0
            DO ibw=ib,nbc
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                temp2 = vbig*geo%fcs(ifc)
                DO nd=1,nbdirs
                  srwd%sna0(nd, icv1, 0, is) = temp2*(conpard(nd, is, &
&                   ibw, 1)+pld%na(nd, icv2, is)-t1d(nd))
                  srwd%sna0(nd, icv1, 1, is) = 0.d0
                  sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0&
&                   , is)
                  sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1&
&                   , is)
                END DO
                srw%sna0(icv1, 0, is) = temp2*(conpar(is, ibw, 1)+pl%na(&
&                 icv2, is)-t1)
                srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
              END DO
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCCON=25, VALID FOR CORE ONLY')
        END IF
      CASE (26) 
!
! -- BCCON=26  Feedback boundary condition: PRESCRIBE THE TOTAL ION FLUX AND
!              FIND THE AVERAGE DENSITY.  !lk and IYS 01.03.2013
!              THE POLOIDAL DENSITY VARIATION FROM THE NEIGHBOURING RADIAL
!              RING IS APPLIED ON TOP OF THE AVERAGE DENSITY.
!              THIS BOUNDARY CONDITION IS SUITABLE FOR ANY SPECIES OF
!              MULTI-SPECIES PLASMA (I.E. IN THE CASE WHEN THE CONDITION USED
!              IN BCCON=22 FAILS)
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              A CORRESPONDING CONDITION ON THE ION TEMPERATURE (BCENI=26,27)
!
! ncall_b2stbc_phys == 0
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!IYS 21.01.2016
!IYS 21.01.2016
!IYS 21.01.2016
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 26 : given total particle flux with ', &
&         'constant average density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 26 only applicable to core boundaries !')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.26 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.26 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               25) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 26'&
&                          )
        END IF
!IYS 01.03.2013 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                sconpard(nd, is) = 0.d0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=26: Summed value is ', sconpar(is)
            totflux = 0.0_R8
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Volume-averaged density on previous surface
            t1 = 0.0_R8
            nas = 0.0_R8
            nasd = 0.d0
            totfluxd = 0.d0
            t1d = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  t0 = t0 + geo%cvvol(icv2)
                  DO nd=1,nbdirs
                    t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%na(nd, icv2&
&                     , is)
                    nasd(nd) = nasd(nd) + geo%cvvol(icv2)*pld%na(nd, &
&                     icv1, is)
                  END DO
                  t1 = t1 + pl%na(icv2, is)*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                  IF (switch%mdf_fnb .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna_mdf(&
&                       nd, ifc, 0, is)+dvd%fna_mdf(nd, ifc, 1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna_mdf(ifc, 0, is)+dv&
&                     %fna_mdf(ifc, 1, is))
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, &
&                       ifc, 0, is)+dvd%fna(nd, ifc, 1, is))
                    END DO
                    totflux = totflux - temp2*(dv%fna(ifc, 0, is)+dv%fna&
&                     (ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
! Sum of volume-averaged electron and ion temperatures
              t1d(nd) = t1d(nd)/t0
! Volume-averaged density
              nasd(nd) = nasd(nd)/t0
            END DO
            t1 = t1/t0
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
            END IF
            IF (totflux .GE. 0.) THEN
              x9 = totflux
            ELSE
              x9 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y12 = sconpar(is)
            ELSE
              y12 = -sconpar(is)
            END IF
            IF (x9 .LT. y12) THEN
              max16 = y12
            ELSE
              max16 = x9
            END IF
            IF (max16 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                DO nd=1,nbdirs
                  x10d(nd) = totfluxd(nd)
                END DO
                x10 = totflux
              ELSE
                DO nd=1,nbdirs
                  x10d(nd) = -totfluxd(nd)
                END DO
                x10 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                DO nd=1,nbdirs
                  y13d(nd) = sconpard(nd, is)
                END DO
                y13 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  y13d(nd) = -sconpard(nd, is)
                END DO
                y13 = -sconpar(is)
              END IF
              IF (x10 .LT. y13) THEN
                DO nd=1,nbdirs
                  max17d(nd) = y13d(nd)
                END DO
                max17 = y13
              ELSE
                DO nd=1,nbdirs
                  max17d(nd) = x10d(nd)
                END DO
                max17 = x10
              END IF
              temp2 = t3/max17
              temp4 = -((totflux-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                nasd(nd) = temp4*nasd(nd) - nas*(temp2*(totfluxd(nd)-&
&                 sconpard(nd, is))+(totflux-sconpar(is))*(t3d(nd)-temp2&
&                 *max17d(nd))/max17)
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  temp2 = vbig*geo%fcs(ifc)
                  DO nd=1,nbdirs
                    srwd%sna0(nd, icv1, 0, is) = temp2*(nasd(nd)+pld%na(&
&                     nd, icv2, is)-t1d(nd))
                    srwd%sna0(nd, icv1, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, &
&                     0, is)
                    sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, &
&                     1, is)
                  END DO
                  srw%sna0(icv1, 0, is) = temp2*(nas+pl%na(icv2, is)-t1)
                  srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                  sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=26 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (27) 
!
! -- BCCON=27  Feedback boundary condition: prescribe the particle flux sum
!              for all neutrals and ions belonging to a given isonuclear sequence
!              and find the average density of the highest ionisation state.
!              THE POLOIDAL DENSITY VARIATION FROM THE NEIGHBOURING RADIAL
!              CELL IS ADDED TO THE AVERAGE DENSITY.
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              A CORRESPONDING CONDITION ON THE ION TEMPERATURE (BCENI=26,27)
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 27 : given total particle flux with constant', &
&         ' density for highest ionisation stage ion is =', is
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 27 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GE. 0.0_R8, &
&                   'BCCON = 27, CONPAR(,,1) < 0')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.27 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.27 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               25) .OR. bccon(is, ibw) .EQ. 26)) THEN
!IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
        END IF
!IYS 04.03.2013 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              DO nd=1,nbdirs
                sconpard(nd, is) = 0.d0
              END DO
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  DO nd=1,nbdirs
                    sconpard(nd, is) = sconpard(nd, is) + conpard(nd, is&
&                     , ibw, 1)
                  END DO
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCCON=27: Summed value is ', sconpar(is)
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
! Volume between two surfaces              !lk 12.12.12 {
            t0 = 0.0_R8
! Volume-averaged on neighbouring surface
            t1 = 0.0_R8
            nas = 0.0_R8
            nasd = 0.d0
            t1d = 0.d0
            totfluxid = 0.d0
            totfluxnd = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
! totfluxn here means the sum of fluxes over all ions (including fluid
! neutrals) of this isotope except for the highest ionisation stage.
! For coupled runs, both fna and fna_mdf are rescaled for neutrals
! Note that for neutrals fna = fna_mdf
                  DO isb=0,ns-1
                    IF (b2espcr(is) .EQ. b2espcr(isb) .AND. is .NE. isb&
&                   ) THEN
                      IF ((.NOT.is_neutral(isb)) .OR. switch%use_eirene &
&                         .EQ. 0) THEN
                        IF (switch%mdf_fnb .NE. 0) THEN
                          temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                          DO nd=1,nbdirs
                            totfluxnd(nd) = totfluxnd(nd) - temp2*(dvd%&
&                             fna_mdf(nd, ifc, 0, isb)+dvd%fna_mdf(nd, &
&                             ifc, 1, isb))
                          END DO
                          totfluxn = totfluxn - temp2*(dv%fna_mdf(ifc, 0&
&                           , isb)+dv%fna_mdf(ifc, 1, isb))
                        ELSE
                          temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                          DO nd=1,nbdirs
                            totfluxnd(nd) = totfluxnd(nd) - temp2*(dvd%&
&                             fna(nd, ifc, 0, isb)+dvd%fna(nd, ifc, 1, &
&                             isb))
                          END DO
                          totfluxn = totfluxn - temp2*(dv%fna(ifc, 0, &
&                           isb)+dv%fna(ifc, 1, isb))
                        END IF
                      END IF
                    END IF
                  END DO
! totfluxi here means the flux of the ion in the highest ionisation stage.
                  IF (switch%mdf_fnb .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna_mdf&
&                       (nd, ifc, 0, is)+dvd%fna_mdf(nd, ifc, 1, is))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna_mdf(ifc, 0, is)+&
&                     dv%fna_mdf(ifc, 1, is))
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxid(nd) = totfluxid(nd) - temp2*(dvd%fna(nd&
&                       , ifc, 0, is)+dvd%fna(nd, ifc, 1, is))
                    END DO
                    totfluxi = totfluxi - temp2*(dv%fna(ifc, 0, is)+dv%&
&                     fna(ifc, 1, is))
                  END IF
                  t0 = t0 + geo%cvvol(icv2)
                  DO nd=1,nbdirs
                    t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%na(nd, icv2&
&                     , is)
                    nasd(nd) = nasd(nd) + geo%cvvol(icv2)*pld%na(nd, &
&                     icv1, is)
                  END DO
                  t1 = t1 + pl%na(icv2, is)*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
!
              t1d(nd) = t1d(nd)/t0
! Volume-averaged density
              nasd(nd) = nasd(nd)/t0
            END DO
            t1 = t1/t0
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                t3d(nd) = conpard(nd, is, ib, 2)
              END DO
              t3 = conpar(is, ib, 2)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref
              t3d = 0.d0
            END IF
            IF (totfluxn .GE. 0.) THEN
              abs3 = totfluxn
            ELSE
              abs3 = -totfluxn
            END IF
            IF (totfluxi .GE. 0.) THEN
              abs9 = totfluxi
            ELSE
              abs9 = -totfluxi
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              abs13 = sconpar(is)
            ELSE
              abs13 = -sconpar(is)
            END IF
            IF (abs3 + abs9 + abs13 .GT. 0.0_R8) THEN
              IF (totfluxn .GE. 0.) THEN
                DO nd=1,nbdirs
                  abs4d(nd) = totfluxnd(nd)
                END DO
                abs4 = totfluxn
              ELSE
                DO nd=1,nbdirs
                  abs4d(nd) = -totfluxnd(nd)
                END DO
                abs4 = -totfluxn
              END IF
              IF (totfluxi .GE. 0.) THEN
                DO nd=1,nbdirs
                  abs10d(nd) = totfluxid(nd)
                END DO
                abs10 = totfluxi
              ELSE
                DO nd=1,nbdirs
                  abs10d(nd) = -totfluxid(nd)
                END DO
                abs10 = -totfluxi
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                DO nd=1,nbdirs
                  abs14d(nd) = sconpard(nd, is)
                END DO
                abs14 = sconpar(is)
              ELSE
                DO nd=1,nbdirs
                  abs14d(nd) = -sconpard(nd, is)
                END DO
                abs14 = -sconpar(is)
              END IF
              temp2 = t3/(abs4+abs10+abs14)
              temp4 = -((totfluxn+totfluxi-sconpar(is))*temp2) + 1.0_R8
              DO nd=1,nbdirs
                nasd(nd) = temp4*nasd(nd) - nas*(temp2*(totfluxnd(nd)+&
&                 totfluxid(nd)-sconpard(nd, is))+(totfluxn+totfluxi-&
&                 sconpar(is))*(t3d(nd)-temp2*(abs4d(nd)+abs10d(nd)+&
&                 abs14d(nd)))/(abs4+abs10+abs14))
              END DO
              nas = nas*temp4
            END IF
            WRITE(*, '(5(a,es14.7))') ' NAS=', nas, ' totfluxn=', &
&           totfluxn, ' totfluxi=', totfluxi, ' SCONPAR=', sconpar(is), &
&           ' totfluxn+totfluxi=', totfluxn + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  temp2 = vbig*geo%fcs(ifc)
                  DO nd=1,nbdirs
                    srwd%sna0(nd, icv1, 0, is) = temp2*(nasd(nd)+pld%na(&
&                     nd, icv2, is)-t1d(nd))
                    srwd%sna0(nd, icv1, 1, is) = 0.d0
                    sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, &
&                     0, is)
                    sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, &
&                     1, is)
                  END DO
                  srw%sna0(icv1, 0, is) = temp2*(nas+pl%na(icv2, is)-t1)
                  srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                  sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=27 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (28) 
!
! -- BCCON=28  Prescribe the flux surface averaged density, with poloidal
!              perturbation taken from flux tube just inside domain
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCCON=28 intended for core boundaries only!')
          END DO
          IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) THEN
!srv 28.07.11
            DO nd=1,nbdirs
              conpard(nd, is, ib, 1) = 0.d0
            END DO
            conpar(is, ib, 1) = neb_astra
          END IF
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            DO nd=1,nbdirs
              conpard(nd, is, ib, 1) = 0.d0
            END DO
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'constant density + perturbation', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 28, conpar(,,1) !> 0')
        END IF
!       ..compute average density on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
        t1d = 0.d0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
          IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              DO nd=1,nbdirs
                t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%na(nd, icv2, is)
              END DO
              t1 = t1 + geo%cvvol(icv2)*pl%na(icv2, is)
            END DO
          END IF
        END DO
        DO nd=1,nbdirs
          t1d(nd) = t1d(nd)/t0
        END DO
        t1 = t1/t0
!       ..impose density with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*geo%fcs(ifc)
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = temp2*(pld%na(nd, icv2, is)+&
&             conpard(nd, is, ib, 1)-t1d(nd))
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = temp2*(pl%na(icv2, is)+conpar(is, ib, &
&           1)-t1)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (29) 
!
! -- BCCON=29  Feedback on the total particle flux, by imposing a flux surface
!              averaged density, with poloidal perturbation taken from flux
!              tube just inside domain
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCCON=29 intended for core boundaries only!')
          END DO
        END IF
!       ..compute average density on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
        t2 = 0.0_R8
        totflux = 0.0_R8
        totpar = 0.0_R8
        totfluxd = 0.d0
        t1d = 0.d0
        t2d = 0.d0
        totpard = 0.d0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
          IF (mpg%cvonclosedsurface(icv1)) THEN
            IF (bccon(is, ib0) .NE. 29) CALL XERRAB(&
&                                      'BCCON=29: incompatible core BCs'&
&                                            )
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              DO nd=1,nbdirs
                t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%na(nd, icv1, is)
                t2d(nd) = t2d(nd) + geo%cvvol(icv2)*pld%na(nd, icv2, is)
              END DO
              t1 = t1 + geo%cvvol(icv2)*pl%na(icv1, is)
              t2 = t2 + geo%cvvol(icv2)*pl%na(icv2, is)
              IF (bccon_flux_fb_style .EQ. 0) THEN
                temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
                DO nd=1,nbdirs
                  totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, ifc, &
&                   0, is)+dvd%fna(nd, ifc, 1, is))
                END DO
                totflux = totflux - temp2*(dv%fna(ifc, 0, is)+dv%fna(ifc&
&                 , 1, is))
              ELSE
                temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
                DO nd=1,nbdirs
                  totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna_eir(nd, &
&                   ifc, 0, is)+dvd%fna_eir(nd, ifc, 1, is))
                END DO
                totflux = totflux - temp2*(dv%fna_eir(ifc, 0, is)+dv%&
&                 fna_eir(ifc, 1, is))
              END IF
            END DO
!nh conpar(is,ib0,3) contains the contribution from the ionized neutrals
!   (ionising_core option)
            DO nd=1,nbdirs
              totpard(nd) = totpard(nd) + conpard(nd, is, ib0, 1) + &
&               conpard(nd, is, ib0, 3)
            END DO
            totpar = totpar + conpar(is, ib0, 1) + conpar(is, ib0, 3)
          END IF
        END DO
        DO nd=1,nbdirs
          t1d(nd) = t1d(nd)/t0
          t2d(nd) = t2d(nd)/t0
        END DO
        t1 = t1/t0
        t2 = t2/t0
        IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
          DO nd=1,nbdirs
            t3d(nd) = conpard(nd, is, ib, 2)
          END DO
          t3 = conpar(is, ib, 2)
        END IF
        IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref
          t3d = 0.d0
        END IF
        IF (totflux .GE. 0.) THEN
          DO nd=1,nbdirs
            x11d(nd) = totfluxd(nd)
          END DO
          x11 = totflux
        ELSE
          DO nd=1,nbdirs
            x11d(nd) = -totfluxd(nd)
          END DO
          x11 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          DO nd=1,nbdirs
            y14d(nd) = totpard(nd)
          END DO
          y14 = totpar
        ELSE
          DO nd=1,nbdirs
            y14d(nd) = -totpard(nd)
          END DO
          y14 = -totpar
        END IF
        IF (x11 .LT. y14) THEN
          IF (y14 .LT. 1.0e10_R8) THEN
            max18 = 1.0e10_R8
            max18d = 0.d0
          ELSE
            DO nd=1,nbdirs
              max18d(nd) = y14d(nd)
            END DO
            max18 = y14
          END IF
        ELSE IF (x11 .LT. 1.0e10_R8) THEN
          max18 = 1.0e10_R8
          max18d = 0.d0
        ELSE
          DO nd=1,nbdirs
            max18d(nd) = x11d(nd)
          END DO
          max18 = x11
        END IF
        temp2 = t3/max18
        temp4 = -((totflux-totpar)*temp2) + 1.0_R8
        DO nd=1,nbdirs
          t4d(nd) = temp4*t1d(nd) - t1*(temp2*(totfluxd(nd)-totpard(nd))&
&           +(totflux-totpar)*(t3d(nd)-temp2*max18d(nd))/max18)
        END DO
        t4 = temp4*t1
!       ..impose density with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*geo%fcs(ifc)
          DO nd=1,nbdirs
            srwd%sna0(nd, icv1, 0, is) = temp2*(pld%na(nd, icv2, is)+t4d&
&             (nd)-t2d(nd))
            srwd%sna0(nd, icv1, 1, is) = 0.d0
            sna0_no_mdfd(nd, icv1, 0, is) = srwd%sna0(nd, icv1, 0, is)
            sna0_no_mdfd(nd, icv1, 1, is) = srwd%sna0(nd, icv1, 1, is)
          END DO
          srw%sna0(icv1, 0, is) = temp2*(pl%na(icv2, is)+t4-t2)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE DEFAULT
!
        WRITE(*, *) bccon(is, ib)
        CALL XERRAB('BCCON out of bounds')
      END SELECT
!
! -- BOUNDARY CONDITIONS FOR PARALLEL MOMENTUM EQUATIONS --
!
      SELECT CASE  (bcmom(is, ib)) 
      CASE (0) 

      CASE (1) 
!
! -- BCMOM=1 -- PRESCRIBE THE VALUE OF THE PARALLEL VELOCITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                            'BCMOM =  1 : specified parallel velocity '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*ne00*geo%fchz(ifc)
          temp1 = am(is)*geo%fcs(ifc)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 0, is) = temp2*temp1*mompard(nd, is, ib&
&             , 1)
            srwd%smo0(nd, icv1, 1, is) = 0.d0
          END DO
          srw%smo0(icv1, 0, is) = temp2*(temp1*mompar(is, ib, 1))
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (2) 
!
! -- BCMOM=2 -- PRESCRIBE THE GRADIENT OF THE PARALLEL VELOCITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                             'BCMOM =  2 : parallel velocity gradient '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          CALL INTVERTEX_S_DV_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%&
&                              ua(:, is), pld%ua(:, :, is), t1, t1d, &
&                              nbdirs)
          CALL INTVERTEX_S_DV_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%&
&                              ua(:, is), pld%ua(:, :, is), t2, t2d, &
&                              nbdirs)
          temp2 = vbig*am(is)*geo%fcs(ifc)*geo%fchz(ifc)
          temp1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          temp0 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc&
&           , 2))
          temp = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
          temp5 = temp*geo%fcqgam(ifc, 0)*mompar(is, ib, 1) - temp0*&
&           temp1*(t2-t1)/geo%fcht(ifc) + pl%ua(icv2, is)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 0, is) = temp2*(temp5*pld%na(nd, icv1, &
&             is)+pl%na(icv1, is)*(temp*geo%fcqgam(ifc, 0)*mompard(nd, &
&             is, ib, 1)-temp0*temp1*(t2d(nd)-t1d(nd))/geo%fcht(ifc)+pld&
&             %ua(nd, icv2, is)))
          END DO
          srw%smo0(icv1, 0, is) = temp2*(pl%na(icv1, is)*temp5)
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 1, is) = -(temp5*vbig*am(is)*pld%na(nd, &
&             icv1, is))
          END DO
          srw%smo0(icv1, 1, is) = -(vbig*am(is)*pl%na(icv1, is)*temp5)
        END DO
      CASE (3) 
!
! -- BCMOM=3 -- SHEATH CONDITIONS, MACH NUMBER AS INPUT
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 3 not adapted for WG.'//&
&             ' Replace with drift-compatible BCMOM = 13')
! -- BCMOM=4 -- PRESCRIBE THE VALUE OF THE VELOCITY, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
      CASE (4) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM =  4 : weak velocity ', mompar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(mompar(is, ib, 2) .GT. 0.0_R8, &
&               'BCMOM = 4, MOMPAR(,,2) !> 0')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 0, is) = temp5*(mompar(is, ib, 1)*&
&             mompard(nd, is, ib, 2)+mompar(is, ib, 2)*mompard(nd, is, &
&             ib, 1))
          END DO
          srw%smo0(icv1, 0, is) = temp5*(mompar(is, ib, 2)*mompar(is, ib&
&           , 1))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 1, is) = -(temp5*mompard(nd, is, ib, 2))
          END DO
          srw%smo0(icv1, 1, is) = -(temp5*mompar(is, ib, 2))
        END DO
      CASE (5) 
!
! -- BCMOM=5 -- PRESCRIBE THE PARALLEL MOMENTUM FLUX PER UNIT AREA
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                   'BCMOM =  5 : parallel momentum flux per unit area '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 0, is) = temp5*mompard(nd, is, ib, 1)
            srwd%smo0(nd, icv1, 1, is) = 0.d0
          END DO
          srw%smo0(icv1, 0, is) = temp5*mompar(is, ib, 1)
          srw%smo0(icv1, 1, is) = 0.0_R8
        END DO
      CASE (6) 
!
! -- BCMOM=6 -- PRESCRIBE THE TOTAL PARALLEL MOMENTUM FLUX FOR A
!                 CONSTANT PARALLEL VELOCITY
!
        CALL XERRAB('B2STBC -- BCMOM=6, NOT YET AVAILABLE')
!
! -- BCMOM=7 -- PRESCRIBE THE GIVEN PROFILE OF VELOCITY
!
      CASE (7) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
          WRITE(*, '(4a,i3)') &
&         'BCMOM = 7 : specified parallel velocity on ', bcchar(ib), &
&         boundary_location(ib), ' for species ', is
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 0, is) = 0.d0
            srwd%smo0(nd, icv1, 1, is) = 0.d0
          END DO
          srw%smo0(icv1, 0, is) = vbig*ne00*am(is)*bv_ua(icv1, is)*geo%&
&           fcs(ifc)*geo%fchz(ifc)
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (8) 
!
! -- BCMOM=8 -- SPECIAL : LIMITED SHEAR
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&                              'BCMOM =  8 : limited shear velocity on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp4 = pl%ti(icv1)/pl%ti(icv2)
          DO nd=1,nbdirs
            arg12d(nd) = (pld%ti(nd, icv1)-temp4*pld%ti(nd, icv2))/pl%ti&
&             (icv2)
          END DO
          arg12 = temp4
          temp4 = SQRT(arg12)
          DO nd=1,nbdirs
            IF (arg12 .EQ. 0.d0) THEN
              y15d(nd) = 0.d0
            ELSE
              y15d(nd) = arg12d(nd)/(2.0*temp4)
            END IF
          END DO
          y15 = temp4
          IF (1.0_R8 .GT. y15) THEN
            DO nd=1,nbdirs
              ad(nd) = y15d(nd)
            END DO
            a = y15
          ELSE
            a = 1.0_R8
            ad = 0.d0
          END IF
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)*vbig*am(is)
          temp4 = pl%na(icv1, is)*a
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 0, is) = temp5*(pl%ua(icv2, is)*(a*pld%&
&             na(nd, icv1, is)+pl%na(icv1, is)*ad(nd))+temp4*pld%ua(nd, &
&             icv2, is))
          END DO
          srw%smo0(icv1, 0, is) = temp5*(temp4*pl%ua(icv2, is))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 0, is) = -(temp5*vbig*am(is)*pld%na(nd, &
&             icv1, is))
          END DO
          srw%smo0(icv1, 0, is) = -(temp5*(vbig*am(is)*pl%na(icv1, is)))
        END DO
      CASE (9) 
!
! -- BCMOM=9 -- PRESCRIBE THE TOTAL PARALLEL MOMENTUM FLUX WITH
!                 CONSTANT FLUX DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                           'BCMOM =  9 : total parallel momentum flux '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
        us = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          us = us + geo%fcs(ifc)*geo%fchz(ifc)
        END DO
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv, 0, is) = temp5*mompard(nd, is, ib, 1)/us
            srwd%smo0(nd, icv, 1, is) = 0.d0
          END DO
          srw%smo0(icv, 0, is) = temp5*(mompar(is, ib, 1)/us)
          srw%smo0(icv, 1, is) = 0.0_R8
        END DO
      CASE (10) 
!
! -- BCMOM=10 -- PRESCRIBE THE DECAY LENGTH FOR THE PARALLEL MOMENTUM
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM = 10 : parallel momentum decay length ', mompar(is, ib&
&         , 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          CALL XERTST(mompar(is, ib, 1) .NE. 0.0_R8, &
&               'BCMOM = 10, MOMPAR(,,1) = 0')
          IF (bccon(is, ib) .NE. 9) THEN
            WRITE(0, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCMOM=10'
            WRITE(*, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCMOM=10'
            WRITE(*, '(1x,a)') &
&           'Please ensure that this boundary condition '//&
&           'is consistent with '//'the density boundary condition'
          END IF
        END IF
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          temp4 = co%vsa0(icv, is)/mompar(is, ib, 1)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv, 0, is) = am(is)*mp*(sna0_no_mdf(icv, 0, &
&             is)*pld%ua(nd, icv, is)+pl%ua(icv, is)*sna0_no_mdfd(nd, &
&             icv, 0, is))
            srwd%smo0(nd, icv, 1, is) = am(is)*mp*(pl%na(icv, is)*&
&             sna0_no_mdfd(nd, icv, 1, is)+sna0_no_mdf(icv, 1, is)*pld%&
&             na(nd, icv, is)) - temp5*(cod%vsa0(nd, icv, is)-temp4*&
&             mompard(nd, is, ib, 1))/mompar(is, ib, 1)
          END DO
          srw%smo0(icv, 0, is) = am(is)*mp*pl%ua(icv, is)*sna0_no_mdf(&
&           icv, 0, is)
          srw%smo0(icv, 1, is) = am(is)*mp*(sna0_no_mdf(icv, 1, is)*pl%&
&           na(icv, is)) - temp5*temp4
        END DO
      CASE (11) 
!
! -- BCMOM=11 -- ROZHANSKY VISCOSITY CONDITION FOR THE PARALLEL MOMENTUM
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 11 not adapted for WG')
!
! -- BCMOM=12 -- CONDITION from b2stbc_spb FOR THE PARALLEL MOMENTUM   !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
      CASE (12) 
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)')&
&                   'BCMOM = 12 : from b2stbc_spb parallel momentum bc '&
&                                     //'with mompar1 =', mompar(is, ib&
&                                     , 1), ' and mompar2 =', mompar(is&
&                                     , ib, 2), ' on ', bcchar(ib), &
&                                     boundary_location(ib), &
&                                     ' for species ', is
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          DO nd=1,nbdirs
            srwd%smo0(nd, icv, 0, is) = 0.d0
            srwd%smo0(nd, icv, 1, is) = 0.d0
            srwd%smo0(nd, icv, 2, is) = 0.d0
          END DO
          srw%smo0(icv, 0, is) = 0.0_R8
          srw%smo0(icv, 1, is) = 0.0_R8
          srw%smo0(icv, 2, is) = 0.0_R8
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor&
&             (ifc, 1, is)) THEN
            temp5 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              max19d(nd) = temp5*dvd%fna_fcor(nd, ifc, 1, is)
            END DO
            max19 = temp5*dv%fna_fcor(ifc, 1, is)
          ELSE
            max19 = 0.0_R8
            max19d = 0.d0
          END IF
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          temp2 = mompar(is, ib, 1)*max19/pl%na(icv, is)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv, 3, is) = srwd%smo0(nd, icv, 3, is) + &
&             temp5*mompard(nd, is, ib, 2) + (max19*mompard(nd, is, ib, &
&             1)+mompar(is, ib, 1)*max19d(nd)-temp2*pld%na(nd, icv, is))&
&             /pl%na(icv, is)
          END DO
          srw%smo0(icv, 3, is) = srw%smo0(icv, 3, is) + temp5*mompar(is&
&           , ib, 2) + temp2
        END DO
      CASE (13) 
!
! -- BCMOM=13 -- DRIFT-COMPATIBLE SHEATH CONDITION FOR THE PARALLEL MOMENTUM
!srv added accumulation in order to account twice b.c. for corner cells
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
            WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)') &
&           'BCMOM = 13 : from b2stbc_spb parallel momentum bc '//&
&           'with mompar1 =', mompar(is, ib, 1), ' and mompar2 =', &
&           mompar(is, ib, 2), ' on ', bcchar(ib), boundary_location(ib)&
&           , ' for species ', is
          ELSE
            WRITE(*, '(a,a,1p,g14.7,a,a,a,a,i3)') &
&           'BCMOM = 13 with MOMPAR(:,:,2) > 0.5 : non-marginal ', &
&           'sheath BC, with MOMPAR(:,:,1) = ', mompar(is, ib, 1), &
&           ' on boundary ', bcchar(ib), boundary_location(ib), &
&           ' for species ', is
          END IF
          CALL XERTST(bccon(is, ib) .EQ. 14, &
&               'BCCON = 14 must be used in conjunction '//&
&               'with BCMOM = 13!')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the internal cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          CALL INTVERTEX_S_DV_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%&
&                              ua(:, is), pld%ua(:, :, is), t1, t1d, &
&                              nbdirs)
          CALL INTVERTEX_S_DV_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%&
&                              ua(:, is), pld%ua(:, :, is), t2, t2d, &
&                              nbdirs)
          IF (geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3) .GE. &
&             0.) THEN
            wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          ELSE
            wrk = -(geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)&
&             )
          END IF
          IF (wrk .LT. geo%qalfmin) THEN
            temp5 = vbig*am(is)*geo%fcs(ifc)*geo%fchz(ifc)
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(&
&             ifc, 2))
            temp4 = pl%ua(icv2, is) - temp1*temp2*(t2-t1)/geo%fcht(ifc)
            DO nd=1,nbdirs
              srwd%smo0(nd, icv1, 0, is) = temp5*(temp4*pld%na(nd, icv1&
&               , is)+pl%na(icv1, is)*(pld%ua(nd, icv2, is)-temp1*temp2*&
&               (t2d(nd)-t1d(nd))/geo%fcht(ifc)))
            END DO
            srw%smo0(icv1, 0, is) = temp5*(pl%na(icv1, is)*temp4)
            temp5 = geo%fcs(ifc)*geo%fchz(ifc)
            DO nd=1,nbdirs
              srwd%smo0(nd, icv1, 1, is) = -(temp5*vbig*am(is)*pld%na(nd&
&               , icv1, is))
            END DO
            srw%smo0(icv1, 1, is) = -(vbig*am(is)*pl%na(icv1, is)*temp5)
          ELSE
!srv 15.02.26
            CALL VBC_IS_DV(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is)&
&                    , csbcd(:, icv1, is), wrk, nbdirs)
!srv 07.05.09 {
            temp5 = ubig*mp*geo%fchz(ifc)*am(is)*geo%fcs(ifc)
            temp2 = vbc(icv1, is)/(epslon*epslon)
            temp4 = pl%na(icv1, is)*mompar(is, ib, 1)
            DO nd=1,nbdirs
              srwd%smo0(nd, icv1, 0, is) = srwd%smo0(nd, icv1, 0, is) + &
&               temp5*(temp2*(mompar(is, ib, 1)*pld%na(nd, icv1, is)+pl%&
&               na(icv1, is)*mompard(nd, is, ib, 1))+temp4*vbcd(nd, icv1&
&               , is)/epslon**2)
            END DO
            srw%smo0(icv1, 0, is) = srw%smo0(icv1, 0, is) + temp5*(temp4&
&             *temp2)
            IF (geo%fcpbshz(ifc) .GE. 0.) THEN
              abs5 = geo%fcpbshz(ifc)
            ELSE
              abs5 = -geo%fcpbshz(ifc)
            END IF
!srv 07.05.09 }
            temp5 = am(is)*abs5*ubig*mp
            DO nd=1,nbdirs
              srwd%smo0(nd, icv1, 1, is) = srwd%smo0(nd, icv1, 1, is) - &
&               temp5*pld%na(nd, icv1, is)/epslon**2
            END DO
            srw%smo0(icv1, 1, is) = srw%smo0(icv1, 1, is) - temp5*(pl%na&
&             (icv1, is)/(epslon*epslon))
          END IF
!srv 01.02.09 }

        END DO
      CASE (14) 
!
! -- BCMOM=14 -- CONDITION from b2stbc_spb FOR THE PARALLEL MOMENTUM    !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)')&
&              'BCMOM = 14 : from b2stbc_spb momentum bc with mompar1 ='&
&                                     , mompar(is, ib, 1), &
&                                     ' and mompar2 =', mompar(is, ib, 2&
&                                     ), ' on ', bcchar(ib), &
&                                     boundary_location(ib), &
&                                     ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
!TODO: drift contributions!
            srwd%smo0(nd, icv1, 0, is) = 0.d0
            srwd%smo0(nd, icv1, 1, is) = 0.d0
            srwd%smo0(nd, icv1, 2, is) = 0.d0
          END DO
          srw%smo0(icv1, 0, is) = 0.0_R8
          srw%smo0(icv1, 1, is) = 0.0_R8
          srw%smo0(icv1, 2, is) = 0.0_R8
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor&
&             (ifc, 1, is)) THEN
            temp5 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              max20d(nd) = temp5*dvd%fna_fcor(nd, ifc, 1, is)
            END DO
            max20 = temp5*dv%fna_fcor(ifc, 1, is)
          ELSE
            max20 = 0.0_R8
            max20d = 0.d0
          END IF
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)
          temp2 = mompar(is, ib, 1)*max20/pl%na(icv1, is)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 3, is) = srwd%smo0(nd, icv1, 3, is) + &
&             temp5*mompard(nd, is, ib, 2) + (max20*mompard(nd, is, ib, &
&             1)+mompar(is, ib, 1)*max20d(nd)-temp2*pld%na(nd, icv1, is)&
&             )/pl%na(icv1, is)
          END DO
          srw%smo0(icv1, 3, is) = srw%smo0(icv1, 3, is) + temp5*mompar(&
&           is, ib, 2) + temp2
        END DO
      CASE (15) 
!
!
! -- BCMOM=15 -- PRESCRIBE THE VALUE OF THE PARALLEL VELOCITY, SCALED WITH
!                B_average/B_local
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 15 not adapted for WG')
!
! -- BCMOM=16 -- PRESCRIBE THE AVERAGE VALUE OF THE PARALLEL VELOCITY   !lk 12.12.12 {
!
      CASE (16) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM = 16 : specified average parallel velocity ', mompar(is&
&         , ib, 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCMOM=16 intended for core boundaries only!')
          END DO
        END IF
!       ..compute average parallel velocity on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
        t1d = 0.d0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
          IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              DO nd=1,nbdirs
                t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ua(nd, icv2, is)
              END DO
              t1 = t1 + geo%cvvol(icv2)*pl%ua(icv2, is)
            END DO
          END IF
        END DO
        DO nd=1,nbdirs
          t1d(nd) = t1d(nd)/t0
        END DO
        t1 = t1/t0
!       ..impose velocity
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp5 = vbig*ne00*geo%fchz(ifc)*am(is)*geo%fcs(ifc)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 0, is) = temp5*(mompard(nd, is, ib, 1)+&
&             pld%ua(nd, icv2, is)-t1d(nd))
            srwd%smo0(nd, icv1, 1, is) = 0.d0
          END DO
          srw%smo0(icv1, 0, is) = temp5*(mompar(is, ib, 1)+pl%ua(icv2, &
&           is)-t1)
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (17) 
!
! -- BCMOM=17 -- leakage option for parallel momentum
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                              'BCMOM = 17 : parallel momentum leakage '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp)
          temp4 = SQRT(arg12)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 0, is) = 0.d0
            arg12d(nd) = (pl%te(icv1)*rtd%rza(nd, icv1, is)+rt%rza(icv1&
&             , is)*pld%te(nd, icv1)+pld%ti(nd, icv1))/(am(is)*mp)
            IF (arg12 .EQ. 0.d0) THEN
              result10d(nd) = 0.d0
            ELSE
              result10d(nd) = arg12d(nd)/(2.0*temp4)
            END IF
          END DO
          srw%smo0(icv1, 0, is) = 0.0_R8
          result10 = temp4
          temp5 = geo%fcs(ifc)*geo%fchz(ifc)*am(is)*mp
          temp4 = result10*mompar(is, ib, 1)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv1, 1, is) = temp5*(pl%na(icv1, is)*(mompar(&
&             is, ib, 1)*result10d(nd)+result10*mompard(nd, is, ib, 1))+&
&             temp4*pld%na(nd, icv1, is))
          END DO
          srw%smo0(icv1, 1, is) = temp5*(temp4*pl%na(icv1, is))
        END DO
      CASE (18) 
!
! -- BCMOM=18 -- PRESCRIBE ZERO SOURCE TERMS (-> no flux)
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&               'BCMOM = 18 : specified zero source terms (no flux) on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          DO nd=1,nbdirs
            srwd%smo0(nd, icv, 0, is) = 0.d0
            srwd%smo0(nd, icv, 1, is) = 0.d0
          END DO
          srw%smo0(icv, 0, is) = 0.0_R8
          srw%smo0(icv, 1, is) = 0.0_R8
        END DO
      CASE DEFAULT
!
        WRITE(*, *) bcmom(is, ib)
        CALL XERRAB('BCMOM out of bounds')
!
      END SELECT
! -- END LOOP OVER SPECIES

    END DO
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_SPECIES_DV

!srv 15.02.26 }
!
  SUBROUTINE B2STBC_PHYS_SPECIES(ib)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER :: is, ib, ibc, ib0, ibc0, ibw, isb
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: s1, t0, t1, t2, t3, t4, vbnd, totpar, totflux, &
&   totfluxn, totfluxi, a, cs, csb, wrk
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    LOGICAL :: ishigh
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    REAL(r8) :: y1
    REAL(r8) :: y2
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: y3
    REAL(r8) :: y4
    REAL(r8) :: y5
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: y6
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: y7
    REAL(kind=r8) :: x4
    REAL(kind=r8) :: y8
    REAL(kind=r8) :: x5
    REAL(kind=r8) :: y9
    REAL(kind=r8) :: x6
    REAL(kind=r8) :: x7
    REAL(kind=r8) :: y10
    REAL(kind=r8) :: x8
    REAL(kind=r8) :: y11
    REAL(kind=r8) :: x9
    REAL(kind=r8) :: y12
    REAL(kind=r8) :: x10
    REAL(kind=r8) :: y13
    REAL(kind=r8) :: x11
    REAL(kind=r8) :: y14
    REAL(r8) :: y15
    REAL(r8) :: max1
    REAL(r8) :: min1
    REAL(r8) :: max2
    REAL(r8) :: min2
    REAL(r8) :: max3
    REAL(r8) :: max4
    REAL(kind=r8) :: max5
    REAL(kind=r8) :: abs0
    REAL(r8) :: max6
    REAL(r8) :: max7
    REAL(kind=r8) :: max8
    REAL(r8) :: max9
    REAL(r8) :: min3
    REAL(kind=r8) :: max10
    REAL(kind=r8) :: max11
    REAL(kind=r8) :: max12
    REAL(kind=r8) :: max13
    REAL(kind=r8) :: max14
    REAL(kind=r8) :: max15
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: max16
    REAL(kind=r8) :: max17
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: abs4
    REAL(kind=r8) :: max18
    REAL(r8) :: max19
    REAL(kind=r8) :: abs5
    REAL(r8) :: max20
    REAL(kind=r8) :: abs6
    REAL(kind=r8) :: abs7
    REAL(kind=r8) :: abs8
    REAL(kind=r8) :: abs9
    REAL(kind=r8) :: abs10
    REAL(kind=r8) :: abs11
    REAL(kind=r8) :: abs12
    REAL(kind=r8) :: abs13
    REAL(kind=r8) :: abs14
    REAL(r8) :: arg12
    REAL(r8) :: result10
    LOGICAL :: result11
!
    DO is=0,ns-1
      IF (is .EQ. ns - 1) THEN
        ishigh = .true.
      ELSE
        ishigh = .NOT.LNEXT(is, is + 1)
      END IF
!
! -- BOUNDARY CONDITIONS FOR CONTINUITY EQUATIONS --
      SELECT CASE  (bccon(is, ib)) 
      CASE (0) 

      CASE (1) 
!
!
! -- BCCON=1 -- PRESCRIBE THE VALUE OF THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  1 : constant density ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 1, CONPAR(,,1) !> 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 2)
          IF (mpg%cvonclosedsurface(icv)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
            IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 1'&
&                            )
          END IF
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*conpar(is, ib, 1)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (2) 
!
! -- BCCON=2 -- PRESCRIBE THE GRADIENT OF THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  2 : density gradient ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 2'&
&                                                           )
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          t1 = INTVERTEX_S_NODIFF_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol&
&           , pl%na(:, is))
          t2 = INTVERTEX_S_NODIFF_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol&
&           , pl%na(:, is))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*(conpar(is, ib, 1)*(&
&           geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(&
&           t2-t1)*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2)&
&           )/geo%fcht(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%na(&
&           icv2, is))
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (3) 
!
! -- BCCON=3 -- SHEATH CONDITIONS
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&                                   'BCCON =  3 : sheath density bc on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = ubig*geo%fcs(ifc)*pl%na(icv2, is)
          srw%sna0(icv1, 1, is) = -(ubig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (4) 
!
! -- BCCON=4 -- PRESCRIBE THE VALUE OF THE DENSITY, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  4 : weak density ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 4, CONPAR(,,1) !> 0')
          CALL XERTST(conpar(is, ib, 2) .GT. 0.0_R8, &
&               'BCCON = 4, CONPAR(,,2) !> 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 4'&
&                                                           )
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = conpar(is, ib, 2)*geo%fcs(ifc)*conpar(&
&           is, ib, 1)
          srw%sna0(icv1, 1, is) = -(conpar(is, ib, 2)*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (5) 
!
! -- BCCON=5 -- PRESCRIBE THE PARTICLE FLUX PER UNIT AREA
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                                 'BCCON =  5 : particle flux per area '&
&                                     , conpar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = conpar(is, ib, 1)*geo%fcs(ifc)
          srw%sna0(icv1, 1, is) = 0.0_R8
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
          IF (switch%mdf_fnb .NE. 0) THEN
!wdk Added correction to make mdf_fnb options equivalent
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0, &
&             is)+dv%fnapsch(ifc, 1, is)+(geo%fcs(ifc)*geo%fcqalf(ifc, 0&
&             )*dv%vadia(ifc, 0, is)+geo%fcs(ifc)*geo%fcqalf(ifc, 1)*dv%&
&             vadia(ifc, 1, is))*0.5_R8*(pl%na(icv1, is)+pl%na(icv2, is)&
&             ))
            IF (0.0_R8 .LT. t0) THEN
              max1 = t0
            ELSE
              max1 = 0.0_R8
            END IF
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max1
            IF (0.0_R8 .GT. t0) THEN
              min1 = t0
            ELSE
              min1 = 0.0_R8
            END IF
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + min1/pl%na(&
&             icv1, is)
          END IF
        END DO
      CASE (6) 
!
! -- BCCON=6 -- PRESCRIBE THE TOTAL PARTICLE FLUX FOR A
!                 CONSTANT DENSITY
!
        CALL XERRAB('b2stbc_phys -- BCCON = 6 not adapted for WG')
!
! -- BCCON=7 -- PRESCRIBE THE GIVEN PROFILE OF DENSITY
!
      CASE (7) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
          WRITE(*, '(4a,i3)') 'BCCON = 7 : specified density on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*bv_na(icv1, is)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (8) 
!
! -- BCCON=8 -- PRESCRIBE THE TOTAL PARTICLE FLUX WITH
!                 CONSTANT FLUX DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (is .EQ. ismain .AND. bcchar(ib) .EQ. 'S' .AND. switch%&
&             use_astra .NE. 0) THEN
            CALL XERRAB(&
&                 'Compile with -DASTRA option to couple to ASTRA!')
!
          END IF
          WRITE(*, '(a,1p,g14.7,a4,a1,a,a13,i3)') &
&         'BCCON =  8 : total particle flux ', conpar(is, ib, 1), ' on '&
&         , bcchar(ib), boundary_location(ib), ' for species ', is
        END IF
!wdk      Note: take full area for face, whether "poloidal" or "radial" or mixed
!wdk      Backwards compatibility issue for E/W and 5-pt stencil?
!wdk      Total flux will be fine, possibly distributed somewhat differently...
        us = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          us = us + geo%fcs(ifc)
        END DO
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + conpar(is, ib&
&           , 1)/us*geo%fcs(ifc)
          srw%sna0(icv1, 1, is) = 0.0_R8
          sna0_no_mdf(icv1, 0, is) = sna0_no_mdf(icv1, 0, is) + srw%sna0&
&           (icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = sna0_no_mdf(icv1, 1, is) + srw%sna0&
&           (icv1, 1, is)
          IF (switch%mdf_fnb .NE. 0) THEN
!wdk Correction now involves vadia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_fnb = 0 option
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0, &
&             is)+dv%fnapsch(ifc, 1, is)+(geo%fcs(ifc)*geo%fcqalf(ifc, 0&
&             )*dv%vadia(ifc, 0, is)+geo%fcs(ifc)*geo%fcqalf(ifc, 1)*dv%&
&             vadia(ifc, 1, is))*0.5_R8*(pl%na(icv1, is)+pl%na(icv2, is)&
&             ))
            IF (0.0_R8 .LT. t0) THEN
              max2 = t0
            ELSE
              max2 = 0.0_R8
            END IF
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max2
            IF (0.0_R8 .GT. t0) THEN
              min2 = t0
            ELSE
              min2 = 0.0_R8
            END IF
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + min2/pl%na(&
&             icv1, is)
          END IF
        END DO
      CASE (9) 
!
! -- BCCON=9 -- PRESCRIBE THE DECAY LENGTH FOR THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  9 : density decay length ', conpar(is, ib, 1), &
&         ' on ', bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .NE. 0.0_R8, &
&               'B2STBC -- BCCON=9, CONPAR(,,1) = 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 9'&
&                                                           )
        END IF
!
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          sy = geo%fcs(ifc)
!
          srw%sna0(icv1, 0, is) = 0.0_R8
          srw%sna0(icv1, 1, is) = -((co%dna0(icv1, is)+co%dpa0(icv1, is)&
&           *(rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1)))/conpar(is, ib, &
&           1)*sy)
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
          IF (switch%mdf_fnb .EQ. 1) THEN
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0, &
&             is)+dv%fnapsch(ifc, 1, is))
            IF (t0 .GE. 0.0_R8) THEN
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
            ELSE
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + t0/pl%na(&
&               icv1, is)
            END IF
            t1 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*0.5_R8*(pl%na(icv1, &
&             is)+pl%na(icv2, is)))
            IF (t1 .GE. 0.0_R8) THEN
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t1
            ELSE
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + t1/pl%na(&
&               icv1, is)
            END IF
          END IF
        END DO
      CASE (10) 
!
! -- BCCON=10 -- leakage option for density, recommended for cases with drifts
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') 'BCCON = 10 : leakage ', &
&         conpar(is, ib, 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 10'&
&                                                           )
!lkw 30.06.2022
          CALL XERTST(conpar(is, ib, 2) .GE. 0.0_R8, &
&               'For BCCON = 10, CONPAR(,,2) should not be negative')
        END IF
!wdk      Note: now total face area taken. Need to check backwards
!wdk      compatibility for E/W boundaries
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the plasma cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = 0.0_R8
          arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp)
          result10 = SQRT(arg12)
          srw%sna0(icv1, 1, is) = geo%fcs(ifc)*result10*conpar(is, ib, 1&
&           )
          sna0_no_mdf(icv1, :, is) = sna0_no_mdf(icv1, :, is) + srw%sna0&
&           (icv1, :, is)
          IF (switch%mdf_fnb .EQ. 0) THEN
            y1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 0)*(dv%vadia(ifc, 0, is)+dv%vaecrb(ifc, 0, is)&
&             )+geo%fcs(ifc)*geo%fcqalf(ifc, 1)*(dv%vadia(ifc, 1, is)+dv&
&             %vaecrb(ifc, 1, is)))*0.5_R8*(pl%na(icv1, is)+pl%na(icv2, &
&             is))/pl%na(icv1, is)
            IF (0.0_R8 .LT. y1) THEN
              max3 = y1
            ELSE
              max3 = 0.0_R8
            END IF
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max3
          ELSE
            y2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*0.5_R8*(pl%na(icv1, &
&             is)+pl%na(icv2, is))/pl%na(icv1, is)
            IF (0.0_R8 .LT. y2) THEN
              max4 = y2
            ELSE
              max4 = 0.0_R8
            END IF
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max4
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0, &
&             is)+dv%fnapsch(ifc, 1, is))
            IF (t0 .GE. 0.0_R8) THEN
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
            ELSE
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + t0/pl%na(&
&               icv1, is)
            END IF
!lkw 30.06.2022{
            arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*&
&             mp)
            result10 = SQRT(arg12)
            t0 = geo%fcs(ifc)*result10*conpar(is, ib, 2)
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0*pl%na(&
&             icv1, is)
!lkw 30.06.2022}
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - t0
          END IF
        END DO
      CASE (11) 
!
! -- BCCON=11 -- particle flux feedback boundary condition
!
        CALL XERRAB('b2stbc_phys -- BCCON = 11 not adapted for WG')
!
! -- BCCON=12 -- particle density feedback boundary condition
!
      CASE (12) 
        CALL XERRAB('b2stbc_phys -- BCCON = 12 not adapted for WG')
!
! -- BCCON=13 -- Feedback constant density for a given particle flux
!
      CASE (13) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,a,a,i3,a,1p,2g14.7)') &
&         'BCCON = 13 : particle density to achieve '//&
&         'specified total flux on ', bcchar(ib), boundary_location(ib)&
&         , ' for species ', is, ' with parameters ', conpar(is, ib, 1)&
&         , conpar(is, ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (switch%ionising_core .GT. 0) WRITE(*, *) &
&               'imposed flux adapted due to ionising_core switch usage'
        END IF
!       ..compute average density on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t0 = t0 + geo%fcs(ifc)
          t1 = t1 + geo%fcs(ifc)*pl%na(icv1, is)
          IF (bccon_flux_fb_style .EQ. 0) THEN
            totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%&
&             fna(ifc, 0, is)+dv%fna(ifc, 1, is))
          ELSE
            totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%&
&             fna_eir(ifc, 0, is)+dv%fna_eir(ifc, 1, is))
          END IF
        END DO
        t1 = t1/t0
!nh conpar(is,ib,3) contains the contribution from the ionized neutrals
!   (ionising_core option)
        totpar = conpar(is, ib, 1) + conpar(is, ib, 3)
        IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
        IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
        IF (totflux .GE. 0.) THEN
          x1 = totflux
        ELSE
          x1 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          y3 = totpar
        ELSE
          y3 = -totpar
        END IF
        IF (x1 .LT. y3) THEN
          IF (y3 .LT. 1.0e10_R8) THEN
            max5 = 1.0e10_R8
          ELSE
            max5 = y3
          END IF
        ELSE IF (x1 .LT. 1.0e10_R8) THEN
          max5 = 1.0e10_R8
        ELSE
          max5 = x1
        END IF
        t2 = (1.0_R8-t3*(totflux-totpar)/max5)*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, &
&                                        '(a,i3,1p,4(1x,e15.6))') &
&             'bccon=13: is, curr_flux, desired_flux, old/new density, '&
&                                        , is, totflux, totpar, t1, t2
!       ..impose density
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*t2
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (14) 
!
! -- BCCON=14 -- Sound speed flux
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
            WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&           'BCCON = 14 : sound speed flux ', mompar(is, ib, 1), ' on '&
&           , bcchar(ib), boundary_location(ib), ' for species ', is
          ELSE
            WRITE(*, '(a,a,1p,g14.7,a,a,a,a,i3)') &
&           'BCCON = 14 with MOMPAR(:,:,2) > 0.5 : non-marginal ', &
&           'sheath BC, with MOMPAR(:,:,1) = ', mompar(is, ib, 1), &
&           ' on boundary ', bcchar(ib), boundary_location(ib), &
&           ' for species ', is
          END IF
          CALL XERTST(conpar(is, ib, 2) .GE. 0.0_R8, &
&               'BCCON = 14, CONPAR(,,2) < 0 not allowed!')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            s1 = geo%fcpbs(ifc)
          ELSE
            s1 = -geo%fcpbs(ifc)
          END IF
!srv 15.02.26
          CALL CSBC_IS(icv1, ib, is, cs)
!srv 15.02.26
          CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), wrk)
          IF (wrk .GE. 0.) THEN
            abs0 = wrk
          ELSE
            abs0 = -wrk
          END IF
          IF (abs0 .LT. geo%qalfmin) THEN
            srw%sna0(icv1, 0, is) = 0.0_R8
            srw%sna0(icv1, 1, is) = -(geo%fcs(ifc)*mompar(is, ib, 1)*cs*&
&             geo%qalfmax)
            sna0_no_mdf(icv1, :, is) = sna0_no_mdf(icv1, :, is) + srw%&
&             sna0(icv1, :, is)
            IF (switch%mdf_fnb .EQ. 0) THEN
              y4 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(geo%fcs(ifc)*geo%&
&               fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcs(ifc)*geo%&
&               fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*0.5_R8*(pl%na(icv1&
&               , is)+pl%na(icv2, is))/pl%na(icv1, is)
              IF (0.0_R8 .LT. y4) THEN
                max6 = y4
              ELSE
                max6 = 0.0_R8
              END IF
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max6
            ELSE
              y5 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(geo%fcs(ifc)*geo%&
&               fcqalf(ifc, 0)*(dv%vaecrb(ifc, 0, is)+dv%vadia(ifc, 0, &
&               is))+geo%fcs(ifc)*geo%fcqalf(ifc, 1)*(dv%vaecrb(ifc, 1, &
&               is)+dv%vadia(ifc, 1, is)))*0.5_R8*(pl%na(icv1, is)+pl%na&
&               (icv2, is))/pl%na(icv1, is)
              IF (0.0_R8 .LT. y5) THEN
                max7 = y5
              ELSE
                max7 = 0.0_R8
              END IF
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max7
              t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0&
&               , is)+dv%fnapsch(ifc, 1, is))
              IF (t0 .GE. 0.0_R8) THEN
                srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
              ELSE
                srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + t0/pl%na&
&                 (icv1, is)
              END IF
            END IF
          ELSE
            vbnd = (dv%vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&             ifc, 1, is)*geo%fcqalf(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib, 1&
&             )+ibc-1)
            srw%sna0(icv1, 0, is) = 0.0_R8
            IF (wrk .GE. 0.) THEN
              abs6 = wrk
            ELSE
              abs6 = -wrk
            END IF
            x2 = csbc(icv1, is)*abs6
            y6 = vbc(icv1, is)*SIGN(1.0_R8, wrk) + vbnd
            IF (x2 .LT. y6) THEN
              max8 = y6
            ELSE
              max8 = x2
            END IF
            srw%sna0(icv1, 1, is) = -(geo%fcs(ifc)*mompar(is, ib, 1)*&
&             max8)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) srw%sna0(icv1, 1, is) = &
&               srw%sna0(icv1, 1, is) - co%dna0(icv1, is)/conpar(is, ib&
&               , 2)*geo%fcs(ifc)
            sna0_no_mdf(icv1, :, is) = srw%sna0(icv1, :, is)
            IF (switch%mdf_fnb .NE. 0) THEN
              t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0&
&               , is)+dv%fnapsch(ifc, 1, is)+(geo%fcs(ifc)*geo%fcqalf(&
&               ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)*geo%fcqalf(ifc&
&               , 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(icv1, is)+pl%na&
&               (icv2, is)))
              IF (0.0_R8 .LT. t0) THEN
                max9 = t0
              ELSE
                max9 = 0.0_R8
              END IF
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max9
              IF (0.0_R8 .GT. t0) THEN
                min3 = t0
              ELSE
                min3 = 0.0_R8
              END IF
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + min3/pl%na&
&               (icv1, is)
            END IF
          END IF
        END DO
      CASE (15) 
!
! -- BCCON=15 -- prescribe a radial leakage velocity, as a multiplier to the local thermal velocity
!
!srv 25.09.09 16.02.12
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(2a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON = 15 : prescribe the decay length for the density', &
&         ' for drifs switched on ', conpar(is, ib, 1), ' on ', bcchar(&
&         ib), boundary_location(ib), ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 15'&
&                                                           )
        END IF
!wdk      Notes:
!wdk       * need correction for misaligned grids -> t1
!wdk       * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp)
          csb = SQRT(arg12)
          t0 = geo%fcqalf(ifc, 1)
          t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&           fcqbet(ifc, 0)
          srw%sna0(icv1, 0, is) = vbig*co%cdna(ifc, 1, is)*(t0*pl%na(&
&           icv2, is)-mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1*(pl%na(mpg%&
&           fcvx(ifc, 2), is)-pl%na(mpg%fcvx(ifc, 1), is)))
          srw%sna0(icv1, 1, is) = -(vbig*(co%cdna(ifc, 1, is)*t0-conpar(&
&           is, ib, 1)*geo%fcs(ifc)*csb))
          sna0_no_mdf(icv1, :, is) = srw%sna0(icv1, :, is)
!srv 25.09.09 }
        END DO
      CASE (16) 
!
! -- BCCON=16 -- Feedback boundary condition: given total particle flux with constant density  !srv 16.02.12 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 16 : given total particle flux with constant', &
&         ' density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 16 only applicable to core boundaries !')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 19 .OR. bccon(is, ibw) .EQ. 21)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB(&
&       'BCCON types 16, 19, 21, 22, 23, 25, 26 and 27 cannot be mixed!'&
&                  )
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 16'&
&                          )
        END IF
!srv 16.02.12 }
        IF (.NOT.once_bccon(is)) THEN
          IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=16: Summed value is ', sconpar(is)
            nas = 0.0_R8
            vs = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  nas = nas + pl%na(icv, is)*geo%cvvol(icv)
                  vs = vs + geo%cvvol(icv)
                END DO
              END IF
            END DO
            nas = nas/vs
            totflux = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                IF (switch%mdf_fnb .NE. 0) THEN
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, is)&
&                     )
                  END DO
                ELSE
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                  END DO
                END IF
              END IF
            END DO
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totflux .GE. 0.) THEN
              x3 = totflux
            ELSE
              x3 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y7 = sconpar(is)
            ELSE
              y7 = -sconpar(is)
            END IF
            IF (x3 .LT. y7) THEN
              max10 = y7
            ELSE
              max10 = x3
            END IF
            IF (max10 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                x4 = totflux
              ELSE
                x4 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                y8 = sconpar(is)
              ELSE
                y8 = -sconpar(is)
              END IF
              IF (x4 .LT. y8) THEN
                max11 = y8
              ELSE
                max11 = x4
              END IF
              nas = nas*(1.0_R8-t3*(totflux-sconpar(is))/max11)
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%sna0(icv, 0, is) = vbig*nas*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          ELSE
!srv 16.02.12 }
            CALL XERRAB('B2STBC -- BCCON=16, NOT AVAILABLE FOR N,W,E')
          END IF
        END IF
      CASE (17) 
!
! -- BCCON=17 -- FILLER
!
        CALL XERRAB('B2STBC -- BCCON=17, NOT YET AVAILABLE')
!
! -- BCCON=18 -- FILLER
!
      CASE (18) 
        CALL XERRAB('B2STBC -- BCCON=18, NOT YET AVAILABLE')
!
! -- BCCON=19 -- Feedback boundary condition: given sum of integrated neutrals and
!                main ion particle fluxes with constant ion density.
!
      CASE (19) 
        IF (switch%spatial_hybrid .NE. 0) CALL XERRAB(&
&                          'BCCON = 19 not compatible with spatial hybr'&
&                                              )
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, *) 'BCCON = 19 : given sum of particle flux '//&
&         'for isonuclear sequence with constant '//&
&         'highest ionisation stage density '
!             write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 19 only applicable to core boundaries !')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 21)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (is .LT. ns - 1) THEN
            result11 = LNEXT(is, is + 1)
            CALL XERTST(.NOT.result11, &
&                 'BCCON = 19 can only be applied to ions in their '//&
&                 'highest ionisation stage')
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 19'&
&                          )
        END IF
!srv 16.02.12 }
        IF (.NOT.once_bccon(is)) THEN
          IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=19: Summed value is ', sconpar(is)
            nas = 0.0_R8
            vs = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  nas = nas + pl%na(icv, is)*geo%cvvol(icv)
                  vs = vs + geo%cvvol(icv)
                END DO
              END IF
            END DO
            nas = nas/vs
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
! totfluxn here means the sum of fluxes over all ions (including fluid
! neutrals) of this isotope except for the highest ionisation stage.
! For coupled runs, both fna and fna_mdf are rescaled for neutrals
! Note that for neutrals fna = fna_mdf
                  DO isb=0,ns-1
                    IF (b2espcr(is) .EQ. b2espcr(isb) .AND. is .NE. isb&
&                   ) THEN
                      IF ((.NOT.is_neutral(isb)) .OR. switch%use_eirene &
&                         .EQ. 0) THEN
                        IF (switch%mdf_fnb .NE. 0) THEN
                          totfluxn = totfluxn - mpg%bcfcor(mpg%bccvp(ibw&
&                           , 1)+ibc-1)*(dv%fna_mdf(ifc, 0, is)+dv%&
&                           fna_mdf(ifc, 1, is))
                        ELSE
                          totfluxn = totfluxn - mpg%bcfcor(mpg%bccvp(ibw&
&                           , 1)+ibc-1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, &
&                           1, is))
                        END IF
                      END IF
                    END IF
                  END DO
! totfluxi here means the flux of the ion in the highest ionisation stage.
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, &
&                     is))
                  ELSE
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totfluxn + totfluxi .GE. 0.) THEN
              x5 = totfluxn + totfluxi
            ELSE
              x5 = -(totfluxn+totfluxi)
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y9 = sconpar(is)
            ELSE
              y9 = -sconpar(is)
            END IF
            IF (x5 .LT. y9) THEN
              max12 = y9
            ELSE
              max12 = x5
            END IF
            IF (max12 .GT. 0.0_R8) THEN
              IF (totfluxn + totfluxi .GE. 0.) THEN
                x6 = totfluxn + totfluxi
              ELSE
                x6 = -(totfluxn+totfluxi)
              END IF
              IF (x6 .LT. sconpar(is)) THEN
                max13 = sconpar(is)
              ELSE
                max13 = x6
              END IF
              nas = nas*(1.0_R8-t3*(totfluxn+totfluxi-sconpar(is))/max13&
&               )
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,es14.7,a,es14.7)') &
&           ' NAS=', nas, ' totfluxn=', totfluxn, ' totfluxi=', totfluxi&
&           , ' SCONPAR=', sconpar(is), ' totfluxn+totfluxi=', totfluxn &
&           + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%sna0(icv, 0, is) = vbig*nas*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          ELSE
!srv 16.02.12 }
            CALL XERRAB('B2STBC -- BCCON=19, NOT AVAILABLE FOR N,W,E')
          END IF
        END IF
      CASE (20) 
!
! -- BCCON=20 -- constant density feedback condition
!
        CALL XERRAB('b2stbc_phys -- BCCON = 20 not adapted for WG')
!
!    -- BCCON=21 -- PRESCRIBE THE VALUE OF THE DENSITY !lk and IYS 01.03.2013
!                   AND ADD A POLOIDAL DENSITY VARIATION TO GET A SOLUTION
!                   WHICH IS AS CLOSE AS POSSIBLE TO NEOCLASSICAL THEORY
!                   DERIVED FOR PURE H/D/T PLASMA ONLY.
!
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
! CORRESPONDING CONDITION ON ION TEMPERATURE (BCENI=23,24)
!
      CASE (21) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7)') 'BCCON = 21 : constant density', &
&         conpar(is, ib, 1)
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 21 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&                   'BCCON = 21, CONPAR(,,1) !> 0')
! IYS 22.01.2015
              CALL XERTST(conpar(is, ib, 1) .EQ. conpar(is, ibw, 1), &
&                   'BCCON = 21, Average density on all parts '//&
&                   'of the surface should be the same')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.21 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.21 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 21 is applied for main ion only ')
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=21 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=25 instead!'
            WRITE(6, *) &
&           'Use of BCCON=21 only meant for single-fluid runs!'
            WRITE(6, *) 'Use BCCON=25 instead!'
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 21'&
&                          )
        END IF
!lk and IYS 01.03.2013}
        IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') .AND. mpg%&
&           cvonclosedsurface(mpg%bccv(mpg%bccvp(ibw, 1), 2))) THEN
          IF (.NOT.once_bccon(is)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                END DO
              END IF
            END DO
! Sum of volume-averaged electron and ion temperatures
            IF (t0 .GT. 0.0_R8) t1 = t1/t0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%sna0(icv, 0, is) = vbig*conpar(is, ibw, 1)*t1/(pl%&
&                   ti(icv)+pl%te(icv))*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCCON=21, VALID FOR CORE ONLY')
        END IF
      CASE (22) 
!
! -- BCCON=22 -- Feedback boundary condition: given total particle flux with
!    constant average density. The poloidal density variation is added to make
!    the solution as close as possible to the neoclassical value derived for
!    pure H/D/T plasma.
!    It is recommended to use this boundary condition
!    together with corresponding boundary condition on ion temperature
!    (BCENI=23,24) !srv 16.02.12, IYS 01.03.2013 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 22 : given total particle flux with constant', &
&         ' density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 22 only applicable to core boundaries !')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.22 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.22 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 22 is applied for main ion only ')
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=22 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=26 instead!'
            WRITE(6, *) &
&           'Use of BCCON=22 only meant for single-fluid runs!'
            WRITE(6, *) 'Use BCCON=26 instead!'
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 22'&
&                          )
        END IF
!iys 01.03.13 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=22: Summed value is ', sconpar(is)
            totflux = 0.0_R8
! Volume between two surfaces             !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            nas = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, is)&
&                     )
                  ELSE
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
! Sum of volume-averaged electron and ion temperatures
            t1 = t1/t0
! Volume-averaged density
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totflux .GE. 0.) THEN
              x7 = totflux
            ELSE
              x7 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y10 = sconpar(is)
            ELSE
              y10 = -sconpar(is)
            END IF
            IF (x7 .LT. y10) THEN
              max14 = y10
            ELSE
              max14 = x7
            END IF
            IF (max14 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                x8 = totflux
              ELSE
                x8 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                y11 = sconpar(is)
              ELSE
                y11 = -sconpar(is)
              END IF
              IF (x8 .LT. y11) THEN
                max15 = y11
              ELSE
                max15 = x8
              END IF
              nas = nas*(1.0_R8-t3*(totflux-sconpar(is))/max15)
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%sna0(icv, 0, is) = vbig*nas*t1*geo%fcs(ifc)/(pl%ti&
&                   (icv)+pl%te(icv))
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=22 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (23) 
!
! -- BCCON=23 -- Feedback boundary condition: given sum of integrated neutrals and
!    main ion particle fluxes with constant average density.
!    The poloidal density variation is added to make the solution
!    as close as possible to the neoclassical value derived for pure H/D/T plasma.
!    It is recommended to use this boundary condition with corresponding
!    boundary condition on ion temperature (BCENI=23,24) !srv 16.02.12, IYS 04.03.2013 {
!    Use this boundary condition for pure H/D/T plasma only,
!    If a minor impurity is present, please use the BCCON=27 instead. ! IYS 21.01.2016
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 23 : given total particle flux with constant', &
&         ' density for main ion is =', ismain
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 23 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GE. 0.0_R8, &
&                   'BCCON = 23, CONPAR(,,1) < 0')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.23 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.23 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=23 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=27 instead!'
            WRITE(6, *) &
&           'Use of BCCON=23 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=27 instead!'
          END IF
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 23 is applied for main ion only ')
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 23'&
&                          )
        END IF
!IYS 04.03.2013 }
!
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=23: Summed value is ', sconpar(is)
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            nas = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  isb = ismain0
                  IF (is_neutral(isb)) totfluxn = totfluxn - mpg%bcfcor(&
&                     mpg%bccvp(ibw, 1)+ibc-1)*(dv%fna(ifc, 0, isb)+dv%&
&                     fna(ifc, 1, isb))
                  isb = ismain
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna_mdf(ifc, 0, isb)+dv%fna_mdf(ifc, 1&
&                     , isb))
                  ELSE
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna(ifc, 0, isb)+dv%fna(ifc, 1, isb))
                  END IF
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                END DO
              END IF
            END DO
! Sum of volume-averaged electron and ion temperatures
            t1 = t1/t0
! Volume-averaged density
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totfluxn .GE. 0.) THEN
              abs1 = totfluxn
            ELSE
              abs1 = -totfluxn
            END IF
            IF (totfluxi .GE. 0.) THEN
              abs7 = totfluxi
            ELSE
              abs7 = -totfluxi
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              abs11 = sconpar(is)
            ELSE
              abs11 = -sconpar(is)
            END IF
            IF (abs1 + abs7 + abs11 .GT. 0.0_R8) THEN
              IF (totfluxn .GE. 0.) THEN
                abs2 = totfluxn
              ELSE
                abs2 = -totfluxn
              END IF
              IF (totfluxi .GE. 0.) THEN
                abs8 = totfluxi
              ELSE
                abs8 = -totfluxi
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                abs12 = sconpar(is)
              ELSE
                abs12 = -sconpar(is)
              END IF
              nas = nas*(1.0_R8-t3*(totfluxn+totfluxi-sconpar(is))/(abs2&
&               +abs8+abs12))
            END IF
            WRITE(*, '(5(a,es14.7))') ' NAS=', nas, ' totfluxn=', &
&           totfluxn, ' totfluxi=', totfluxi, ' SCONPAR=', sconpar(is), &
&           ' totfluxn+totfluxi=', totfluxn + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%sna0(icv, 0, is) = vbig*nas*t1/(pl%ti(icv)+pl%te(&
&                   icv))*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=23 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (24) 
!
! -- BCCON=24 -- constant density scaled by density on the ring bc_type21_ref away
!
        CALL XERRAB('b2stbc_phys -- BCCON = 24 not adapted for WG')
!
! -- BCCON=25  Feedback boundary condition: PRESCRIBE THE AVERAGE VALUE OF THE DENSITY  !lk and IYS 01.03.2013{
!              AND ADD A POLOIDAL DENSITY VARIATION FROM NEIGHBOURING RADIAL CELL.
!              THIS BOUNDARY CONDITION IS SUITABLE FOR ANY SPECIES OF
!              MULTI-SPECIES PLASMA (I.E. IN THE CASE WHEN THE CONDITION USED
!              IN BCCON=21 FAILS)
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              CORRESPONDING CONDITION ON ION TEMPERATURE (BCENI=26,27)
!
      CASE (25) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7)') &
&         'BCCON = 25 : constant average density', conpar(is, ib, 1)
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 25 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GT. 0.0_R8, &
&                   'BCCON = 25, CONPAR(,,1) !> 0')
! IYS 22.01.2015
              CALL XERTST(conpar(is, ib, 1) .EQ. conpar(is, ibw, 1), &
&                   'BCCON = 25, Average density on all parts '//&
&                   'of the surface should be the same')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.25 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.25 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 25'&
&                          )
        END IF
!lk and IYS 01.03.2013}
!
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
          IF (.NOT.once_bccon(is)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
! Volume between two surfaces              !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged density
            t1 = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  t0 = t0 + geo%cvvol(icv)
                  t1 = t1 + pl%na(icv, is)*geo%cvvol(icv)
                END DO
              END IF
            END DO
            t1 = t1/t0
            DO ibw=ib,nbc
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*(conpar(is, &
&                 ibw, 1)+pl%na(icv2, is)-t1)
                srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
              END DO
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCCON=25, VALID FOR CORE ONLY')
        END IF
      CASE (26) 
!
! -- BCCON=26  Feedback boundary condition: PRESCRIBE THE TOTAL ION FLUX AND
!              FIND THE AVERAGE DENSITY.  !lk and IYS 01.03.2013
!              THE POLOIDAL DENSITY VARIATION FROM THE NEIGHBOURING RADIAL
!              RING IS APPLIED ON TOP OF THE AVERAGE DENSITY.
!              THIS BOUNDARY CONDITION IS SUITABLE FOR ANY SPECIES OF
!              MULTI-SPECIES PLASMA (I.E. IN THE CASE WHEN THE CONDITION USED
!              IN BCCON=22 FAILS)
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              A CORRESPONDING CONDITION ON THE ION TEMPERATURE (BCENI=26,27)
!
! ncall_b2stbc_phys == 0
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!IYS 21.01.2016
!IYS 21.01.2016
!IYS 21.01.2016
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 26 : given total particle flux with ', &
&         'constant average density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 26 only applicable to core boundaries !')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.26 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.26 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               25) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 26'&
&                          )
        END IF
!IYS 01.03.2013 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=26: Summed value is ', sconpar(is)
            totflux = 0.0_R8
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Volume-averaged density on previous surface
            t1 = 0.0_R8
            nas = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + pl%na(icv2, is)*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, is)&
&                     )
                  ELSE
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
! Sum of volume-averaged electron and ion temperatures
            t1 = t1/t0
! Volume-averaged density
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totflux .GE. 0.) THEN
              x9 = totflux
            ELSE
              x9 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y12 = sconpar(is)
            ELSE
              y12 = -sconpar(is)
            END IF
            IF (x9 .LT. y12) THEN
              max16 = y12
            ELSE
              max16 = x9
            END IF
            IF (max16 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                x10 = totflux
              ELSE
                x10 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                y13 = sconpar(is)
              ELSE
                y13 = -sconpar(is)
              END IF
              IF (x10 .LT. y13) THEN
                max17 = y13
              ELSE
                max17 = x10
              END IF
              nas = nas*(1.0_R8-t3*(totflux-sconpar(is))/max17)
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  srw%sna0(icv1, 0, is) = vbig*(nas+pl%na(icv2, is)-t1)*&
&                   geo%fcs(ifc)
                  srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                  sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=26 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (27) 
!
! -- BCCON=27  Feedback boundary condition: prescribe the particle flux sum
!              for all neutrals and ions belonging to a given isonuclear sequence
!              and find the average density of the highest ionisation state.
!              THE POLOIDAL DENSITY VARIATION FROM THE NEIGHBOURING RADIAL
!              CELL IS ADDED TO THE AVERAGE DENSITY.
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              A CORRESPONDING CONDITION ON THE ION TEMPERATURE (BCENI=26,27)
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 27 : given total particle flux with constant', &
&         ' density for highest ionisation stage ion is =', is
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 27 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GE. 0.0_R8, &
&                   'BCCON = 27, CONPAR(,,1) < 0')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.27 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.27 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               25) .OR. bccon(is, ibw) .EQ. 26)) THEN
!IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
        END IF
!IYS 04.03.2013 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=27: Summed value is ', sconpar(is)
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
! Volume between two surfaces              !lk 12.12.12 {
            t0 = 0.0_R8
! Volume-averaged on neighbouring surface
            t1 = 0.0_R8
            nas = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
! totfluxn here means the sum of fluxes over all ions (including fluid
! neutrals) of this isotope except for the highest ionisation stage.
! For coupled runs, both fna and fna_mdf are rescaled for neutrals
! Note that for neutrals fna = fna_mdf
                  DO isb=0,ns-1
                    IF (b2espcr(is) .EQ. b2espcr(isb) .AND. is .NE. isb&
&                   ) THEN
                      IF ((.NOT.is_neutral(isb)) .OR. switch%use_eirene &
&                         .EQ. 0) THEN
                        IF (switch%mdf_fnb .NE. 0) THEN
                          totfluxn = totfluxn - mpg%bcfcor(mpg%bccvp(ibw&
&                           , 1)+ibc-1)*(dv%fna_mdf(ifc, 0, isb)+dv%&
&                           fna_mdf(ifc, 1, isb))
                        ELSE
                          totfluxn = totfluxn - mpg%bcfcor(mpg%bccvp(ibw&
&                           , 1)+ibc-1)*(dv%fna(ifc, 0, isb)+dv%fna(ifc&
&                           , 1, isb))
                        END IF
                      END IF
                    END IF
                  END DO
! totfluxi here means the flux of the ion in the highest ionisation stage.
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, &
&                     is))
                  ELSE
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                  END IF
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + pl%na(icv2, is)*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                END DO
              END IF
            END DO
!
            t1 = t1/t0
! Volume-averaged density
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totfluxn .GE. 0.) THEN
              abs3 = totfluxn
            ELSE
              abs3 = -totfluxn
            END IF
            IF (totfluxi .GE. 0.) THEN
              abs9 = totfluxi
            ELSE
              abs9 = -totfluxi
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              abs13 = sconpar(is)
            ELSE
              abs13 = -sconpar(is)
            END IF
            IF (abs3 + abs9 + abs13 .GT. 0.0_R8) THEN
              IF (totfluxn .GE. 0.) THEN
                abs4 = totfluxn
              ELSE
                abs4 = -totfluxn
              END IF
              IF (totfluxi .GE. 0.) THEN
                abs10 = totfluxi
              ELSE
                abs10 = -totfluxi
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                abs14 = sconpar(is)
              ELSE
                abs14 = -sconpar(is)
              END IF
              nas = nas*(1.0_R8-t3*(totfluxn+totfluxi-sconpar(is))/(abs4&
&               +abs10+abs14))
            END IF
            WRITE(*, '(5(a,es14.7))') ' NAS=', nas, ' totfluxn=', &
&           totfluxn, ' totfluxi=', totfluxi, ' SCONPAR=', sconpar(is), &
&           ' totfluxn+totfluxi=', totfluxn + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  srw%sna0(icv1, 0, is) = vbig*(nas+pl%na(icv2, is)-t1)*&
&                   geo%fcs(ifc)
                  srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                  sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=27 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (28) 
!
! -- BCCON=28  Prescribe the flux surface averaged density, with poloidal
!              perturbation taken from flux tube just inside domain
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCCON=28 intended for core boundaries only!')
          END DO
          IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) THEN
!srv 28.07.11
            conpar(is, ib, 1) = neb_astra
          END IF
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'constant density + perturbation', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 28, conpar(,,1) !> 0')
        END IF
!       ..compute average density on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
          IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              t1 = t1 + geo%cvvol(icv2)*pl%na(icv2, is)
            END DO
          END IF
        END DO
        t1 = t1/t0
!       ..impose density with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*(pl%na(icv2, is)+&
&           conpar(is, ib, 1)-t1)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (29) 
!
! -- BCCON=29  Feedback on the total particle flux, by imposing a flux surface
!              averaged density, with poloidal perturbation taken from flux
!              tube just inside domain
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCCON=29 intended for core boundaries only!')
          END DO
        END IF
!       ..compute average density on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
        t2 = 0.0_R8
        totflux = 0.0_R8
        totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
          IF (mpg%cvonclosedsurface(icv1)) THEN
            IF (bccon(is, ib0) .NE. 29) CALL XERRAB(&
&                                      'BCCON=29: incompatible core BCs'&
&                                            )
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              t1 = t1 + geo%cvvol(icv2)*pl%na(icv1, is)
              t2 = t2 + geo%cvvol(icv2)*pl%na(icv2, is)
              IF (bccon_flux_fb_style .EQ. 0) THEN
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)&
&                 *(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
              ELSE
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)&
&                 *(dv%fna_eir(ifc, 0, is)+dv%fna_eir(ifc, 1, is))
              END IF
            END DO
!nh conpar(is,ib0,3) contains the contribution from the ionized neutrals
!   (ionising_core option)
            totpar = totpar + conpar(is, ib0, 1) + conpar(is, ib0, 3)
          END IF
        END DO
        t1 = t1/t0
        t2 = t2/t0
        IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
        IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
        IF (totflux .GE. 0.) THEN
          x11 = totflux
        ELSE
          x11 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          y14 = totpar
        ELSE
          y14 = -totpar
        END IF
        IF (x11 .LT. y14) THEN
          IF (y14 .LT. 1.0e10_R8) THEN
            max18 = 1.0e10_R8
          ELSE
            max18 = y14
          END IF
        ELSE IF (x11 .LT. 1.0e10_R8) THEN
          max18 = 1.0e10_R8
        ELSE
          max18 = x11
        END IF
        t4 = (1.0_R8-t3*(totflux-totpar)/max18)*t1
!       ..impose density with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*(pl%na(icv2, is)+t4-&
&           t2)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE DEFAULT
!
        WRITE(*, *) bccon(is, ib)
        CALL XERRAB('BCCON out of bounds')
      END SELECT
!
! -- BOUNDARY CONDITIONS FOR PARALLEL MOMENTUM EQUATIONS --
!
      SELECT CASE  (bcmom(is, ib)) 
      CASE (0) 

      CASE (1) 
!
! -- BCMOM=1 -- PRESCRIBE THE VALUE OF THE PARALLEL VELOCITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                            'BCMOM =  1 : specified parallel velocity '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = vbig*ne00*am(is)*mompar(is, ib, 1)*geo&
&           %fcs(ifc)*geo%fchz(ifc)
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (2) 
!
! -- BCMOM=2 -- PRESCRIBE THE GRADIENT OF THE PARALLEL VELOCITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                             'BCMOM =  2 : parallel velocity gradient '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          t1 = INTVERTEX_S_NODIFF_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol&
&           , pl%ua(:, is))
          t2 = INTVERTEX_S_NODIFF_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol&
&           , pl%ua(:, is))
          srw%smo0(icv1, 0, is) = vbig*am(is)*pl%na(icv1, is)*geo%fcs(&
&           ifc)*geo%fchz(ifc)*(mompar(is, ib, 1)*(geo%fchc(ifc, 1)+geo%&
&           fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2-t1)*geo%fcqgam(ifc&
&           , 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*mpg%&
&           bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%ua(icv2, is))
          srw%smo0(icv1, 1, is) = -(vbig*am(is)*pl%na(icv1, is)*geo%fcs(&
&           ifc)*geo%fchz(ifc))
        END DO
      CASE (3) 
!
! -- BCMOM=3 -- SHEATH CONDITIONS, MACH NUMBER AS INPUT
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 3 not adapted for WG.'//&
&             ' Replace with drift-compatible BCMOM = 13')
! -- BCMOM=4 -- PRESCRIBE THE VALUE OF THE VELOCITY, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
      CASE (4) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM =  4 : weak velocity ', mompar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(mompar(is, ib, 2) .GT. 0.0_R8, &
&               'BCMOM = 4, MOMPAR(,,2) !> 0')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = mompar(is, ib, 2)*mompar(is, ib, 1)*&
&           geo%fcs(ifc)*geo%fchz(ifc)
          srw%smo0(icv1, 1, is) = -(mompar(is, ib, 2)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (5) 
!
! -- BCMOM=5 -- PRESCRIBE THE PARALLEL MOMENTUM FLUX PER UNIT AREA
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                   'BCMOM =  5 : parallel momentum flux per unit area '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = mompar(is, ib, 1)*geo%fcs(ifc)*geo%&
&           fchz(ifc)
          srw%smo0(icv1, 1, is) = 0.0_R8
        END DO
      CASE (6) 
!
! -- BCMOM=6 -- PRESCRIBE THE TOTAL PARALLEL MOMENTUM FLUX FOR A
!                 CONSTANT PARALLEL VELOCITY
!
        CALL XERRAB('B2STBC -- BCMOM=6, NOT YET AVAILABLE')
!
! -- BCMOM=7 -- PRESCRIBE THE GIVEN PROFILE OF VELOCITY
!
      CASE (7) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
          WRITE(*, '(4a,i3)') &
&         'BCMOM = 7 : specified parallel velocity on ', bcchar(ib), &
&         boundary_location(ib), ' for species ', is
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = vbig*ne00*am(is)*bv_ua(icv1, is)*geo%&
&           fcs(ifc)*geo%fchz(ifc)
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (8) 
!
! -- BCMOM=8 -- SPECIAL : LIMITED SHEAR
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&                              'BCMOM =  8 : limited shear velocity on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg12 = pl%ti(icv1)/pl%ti(icv2)
          y15 = SQRT(arg12)
          IF (1.0_R8 .GT. y15) THEN
            a = y15
          ELSE
            a = 1.0_R8
          END IF
          srw%smo0(icv1, 0, is) = vbig*geo%fcs(ifc)*geo%fchz(ifc)*am(is)&
&           *pl%na(icv1, is)*a*pl%ua(icv2, is)
          srw%smo0(icv1, 0, is) = -(vbig*geo%fcs(ifc)*geo%fchz(ifc)*am(&
&           is)*pl%na(icv1, is))
        END DO
      CASE (9) 
!
! -- BCMOM=9 -- PRESCRIBE THE TOTAL PARALLEL MOMENTUM FLUX WITH
!                 CONSTANT FLUX DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                           'BCMOM =  9 : total parallel momentum flux '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
        us = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          us = us + geo%fcs(ifc)*geo%fchz(ifc)
        END DO
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          srw%smo0(icv, 0, is) = mompar(is, ib, 1)/us*geo%fcs(ifc)*geo%&
&           fchz(ifc)
          srw%smo0(icv, 1, is) = 0.0_R8
        END DO
      CASE (10) 
!
! -- BCMOM=10 -- PRESCRIBE THE DECAY LENGTH FOR THE PARALLEL MOMENTUM
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM = 10 : parallel momentum decay length ', mompar(is, ib&
&         , 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          CALL XERTST(mompar(is, ib, 1) .NE. 0.0_R8, &
&               'BCMOM = 10, MOMPAR(,,1) = 0')
          IF (bccon(is, ib) .NE. 9) THEN
            WRITE(0, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCMOM=10'
            WRITE(*, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCMOM=10'
            WRITE(*, '(1x,a)') &
&           'Please ensure that this boundary condition '//&
&           'is consistent with '//'the density boundary condition'
          END IF
        END IF
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          srw%smo0(icv, 0, is) = am(is)*mp*pl%ua(icv, is)*sna0_no_mdf(&
&           icv, 0, is)
          srw%smo0(icv, 1, is) = -(co%vsa0(icv, is)/mompar(is, ib, 1)*&
&           geo%fcs(ifc)*geo%fchz(ifc)) + am(is)*mp*sna0_no_mdf(icv, 1, &
&           is)*pl%na(icv, is)
        END DO
      CASE (11) 
!
! -- BCMOM=11 -- ROZHANSKY VISCOSITY CONDITION FOR THE PARALLEL MOMENTUM
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 11 not adapted for WG')
!
! -- BCMOM=12 -- CONDITION from b2stbc_spb FOR THE PARALLEL MOMENTUM   !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
      CASE (12) 
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)')&
&                   'BCMOM = 12 : from b2stbc_spb parallel momentum bc '&
&                                     //'with mompar1 =', mompar(is, ib&
&                                     , 1), ' and mompar2 =', mompar(is&
&                                     , ib, 2), ' on ', bcchar(ib), &
&                                     boundary_location(ib), &
&                                     ' for species ', is
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          srw%smo0(icv, 0, is) = 0.0_R8
          srw%smo0(icv, 1, is) = 0.0_R8
          srw%smo0(icv, 2, is) = 0.0_R8
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor&
&             (ifc, 1, is)) THEN
            max19 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor(ifc, &
&             1, is)
          ELSE
            max19 = 0.0_R8
          END IF
          srw%smo0(icv, 3, is) = srw%smo0(icv, 3, is) + mompar(is, ib, 2&
&           )*geo%fcs(ifc)*geo%fchz(ifc) + mompar(is, ib, 1)*max19/pl%na&
&           (icv, is)
        END DO
      CASE (13) 
!
! -- BCMOM=13 -- DRIFT-COMPATIBLE SHEATH CONDITION FOR THE PARALLEL MOMENTUM
!srv added accumulation in order to account twice b.c. for corner cells
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
            WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)') &
&           'BCMOM = 13 : from b2stbc_spb parallel momentum bc '//&
&           'with mompar1 =', mompar(is, ib, 1), ' and mompar2 =', &
&           mompar(is, ib, 2), ' on ', bcchar(ib), boundary_location(ib)&
&           , ' for species ', is
          ELSE
            WRITE(*, '(a,a,1p,g14.7,a,a,a,a,i3)') &
&           'BCMOM = 13 with MOMPAR(:,:,2) > 0.5 : non-marginal ', &
&           'sheath BC, with MOMPAR(:,:,1) = ', mompar(is, ib, 1), &
&           ' on boundary ', bcchar(ib), boundary_location(ib), &
&           ' for species ', is
          END IF
          CALL XERTST(bccon(is, ib) .EQ. 14, &
&               'BCCON = 14 must be used in conjunction '//&
&               'with BCMOM = 13!')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the internal cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          t1 = INTVERTEX_S_NODIFF_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol&
&           , pl%ua(:, is))
          t2 = INTVERTEX_S_NODIFF_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol&
&           , pl%ua(:, is))
          IF (geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3) .GE. &
&             0.) THEN
            wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          ELSE
            wrk = -(geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)&
&             )
          END IF
          IF (wrk .LT. geo%qalfmin) THEN
            srw%smo0(icv1, 0, is) = vbig*am(is)*pl%na(icv1, is)*geo%fcs(&
&             ifc)*geo%fchz(ifc)*(-(cor9*(t2-t1)*geo%fcqgam(ifc, 1)*(geo&
&             %fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*mpg%bcfcor(&
&             mpg%bccvp(ib, 1)+ibc-1))+pl%ua(icv2, is))
            srw%smo0(icv1, 1, is) = -(vbig*am(is)*pl%na(icv1, is)*geo%&
&             fcs(ifc)*geo%fchz(ifc))
          ELSE
!srv 15.02.26
            CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), &
&                 wrk)
!srv 07.05.09 {
            srw%smo0(icv1, 0, is) = srw%smo0(icv1, 0, is) + ubig/epslon&
&             **2*am(is)*mp*pl%na(icv1, is)*mompar(is, ib, 1)*vbc(icv1, &
&             is)*geo%fcs(ifc)*geo%fchz(ifc)
            IF (geo%fcpbshz(ifc) .GE. 0.) THEN
              abs5 = geo%fcpbshz(ifc)
            ELSE
              abs5 = -geo%fcpbshz(ifc)
            END IF
!srv 07.05.09 }
            srw%smo0(icv1, 1, is) = srw%smo0(icv1, 1, is) - ubig/epslon&
&             **2*am(is)*mp*pl%na(icv1, is)*abs5
          END IF
!srv 01.02.09 }

        END DO
      CASE (14) 
!
! -- BCMOM=14 -- CONDITION from b2stbc_spb FOR THE PARALLEL MOMENTUM    !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)')&
&              'BCMOM = 14 : from b2stbc_spb momentum bc with mompar1 ='&
&                                     , mompar(is, ib, 1), &
&                                     ' and mompar2 =', mompar(is, ib, 2&
&                                     ), ' on ', bcchar(ib), &
&                                     boundary_location(ib), &
&                                     ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
!TODO: drift contributions!
          srw%smo0(icv1, 0, is) = 0.0_R8
          srw%smo0(icv1, 1, is) = 0.0_R8
          srw%smo0(icv1, 2, is) = 0.0_R8
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor&
&             (ifc, 1, is)) THEN
            max20 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor(ifc, &
&             1, is)
          ELSE
            max20 = 0.0_R8
          END IF
          srw%smo0(icv1, 3, is) = srw%smo0(icv1, 3, is) + mompar(is, ib&
&           , 2)*geo%fcs(ifc)*geo%fchz(ifc) + mompar(is, ib, 1)*max20/pl&
&           %na(icv1, is)
        END DO
      CASE (15) 
!
!
! -- BCMOM=15 -- PRESCRIBE THE VALUE OF THE PARALLEL VELOCITY, SCALED WITH
!                B_average/B_local
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 15 not adapted for WG')
!
! -- BCMOM=16 -- PRESCRIBE THE AVERAGE VALUE OF THE PARALLEL VELOCITY   !lk 12.12.12 {
!
      CASE (16) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM = 16 : specified average parallel velocity ', mompar(is&
&         , ib, 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCMOM=16 intended for core boundaries only!')
          END DO
        END IF
!       ..compute average parallel velocity on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
          IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              t1 = t1 + geo%cvvol(icv2)*pl%ua(icv2, is)
            END DO
          END IF
        END DO
        t1 = t1/t0
!       ..impose velocity
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = vbig*ne00*am(is)*geo%fcs(ifc)*geo%fchz&
&           (ifc)*(mompar(is, ib, 1)+pl%ua(icv2, is)-t1)
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (17) 
!
! -- BCMOM=17 -- leakage option for parallel momentum
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                              'BCMOM = 17 : parallel momentum leakage '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = 0.0_R8
          arg12 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp)
          result10 = SQRT(arg12)
          srw%smo0(icv1, 1, is) = geo%fcs(ifc)*geo%fchz(ifc)*result10*(&
&           am(is)*mp)*mompar(is, ib, 1)*pl%na(icv1, is)
        END DO
      CASE (18) 
!
! -- BCMOM=18 -- PRESCRIBE ZERO SOURCE TERMS (-> no flux)
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&               'BCMOM = 18 : specified zero source terms (no flux) on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srw%smo0(icv, 0, is) = 0.0_R8
          srw%smo0(icv, 1, is) = 0.0_R8
        END DO
      CASE DEFAULT
!
        WRITE(*, *) bcmom(is, ib)
        CALL XERRAB('BCMOM out of bounds')
!
      END SELECT
! -- END LOOP OVER SPECIES

    END DO
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_SPECIES

!  Differentiation of b2stbc_phys_ene_dv in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: enepar enepard senepar senepard
!                *(srwd.she0) *(srwd.shi0) *(srw.she0) *(srw.shi0)
!   with respect to varying inputs: conpar conpard enepar enepard
!                enipar enipard potpar potpard senepar senepard
!                *(srwd.she0) *(srwd.shi0) *(srwd.sna0) *(dv.fch_p)
!                *(dv.fna) *(dv.fne) *(dv.fhe) *(dv.fhe_mdf) *(dv.fhepsch)
!                *(dv.fhi) *(dv.kinrgy) *(dv.ne) *(dv.ni) *(dv.vaecrb)
!                *(dv.vedia) *(dv.veecrb) *(rtd.rza) *(rt.rza)
!                *(dvd.fch_p) *(dvd.fna) *(dvd.fne) *(dvd.fhe)
!                *(dvd.fhe_mdf) *(dvd.fhepsch) *(dvd.fhi) *(dvd.kinrgy)
!                *(dvd.ne) *(dvd.ni) *(dvd.vaecrb) *(dvd.vedia)
!                *(dvd.veecrb) *(srw.she0) *(srw.shi0) *(srw.sna0)
!                *(cod.chce) *(cod.hce0) *(cod.dna0) *(co.chce)
!                *(co.hce0) *(co.dna0) *(pld.na) *(pld.po) *(pld.te)
!                *(pld.ti) *(pl.na) *(pl.po) *(pl.te) *(pl.ti)
!                pzd rzd rz pz
!   Plus diff mem management of: srwd.she0:in srwd.shi0:in srwd.sna0:in
!                dv.fch_p:in dv.fna:in dv.fne:in dv.fhe:in dv.fhe_mdf:in
!                dv.fhepsch:in dv.fhi:in dv.kinrgy:in dv.ne:in
!                dv.ni:in dv.vaecrb:in dv.vedia:in dv.veecrb:in
!                geo.fcs:in geo.vxvol:in rtd.rza:in rt.rza:in dvd.fch_p:in
!                dvd.fna:in dvd.fne:in dvd.fhe:in dvd.fhe_mdf:in
!                dvd.fhepsch:in dvd.fhi:in dvd.kinrgy:in dvd.ne:in
!                dvd.ni:in dvd.vaecrb:in dvd.vedia:in dvd.veecrb:in
!                srw.she0:in srw.shi0:in srw.sna0:in cod.chce:in
!                cod.hce0:in cod.dna0:in co.chce:in co.hce0:in
!                co.dna0:in pld.na:in pld.po:in pld.te:in pld.ti:in
!                pl.na:in pl.po:in pl.te:in pl.ti:in
!  Differentiation of b2stbc_phys_ene in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: enepar senepar *(srw.she0)
!                *(srw.shi0)
!   with respect to varying inputs: conpar enepar enipar potpar
!                senepar *(dv.fch_p) *(dv.fna) *(dv.fne) *(dv.fhe)
!                *(dv.fhe_mdf) *(dv.fhepsch) *(dv.fhi) *(dv.kinrgy)
!                *(dv.ne) *(dv.ni) *(dv.vaecrb) *(dv.vedia) *(dv.veecrb)
!                *(rt.rza) *(srw.she0) *(srw.shi0) *(srw.sna0)
!                *(co.chce) *(co.hce0) *(co.dna0) *(pl.na) *(pl.po)
!                *(pl.te) *(pl.ti) rz pz
!   Plus diff mem management of: dv.fch_p:in dv.fna:in dv.fne:in
!                dv.fhe:in dv.fhe_mdf:in dv.fhepsch:in dv.fhi:in
!                dv.kinrgy:in dv.ne:in dv.ni:in dv.vaecrb:in dv.vedia:in
!                dv.veecrb:in mpg.bcfcor:in geo.fcs:in geo.vxvol:in
!                st_ext.ua:in rt.rza:in srw.she0:in srw.shi0:in
!                srw.sna0:in co.chce:in co.hce0:in co.dna0:in pl.na:in
!                pl.po:in pl.te:in pl.ti:in
!
  SUBROUTINE B2STBC_PHYS_ENE_DV_DV(ib, nbdirs, nbdirs0)
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    USE B2MOD_DIFFSIZES
!  Hint: nbdirsmax0 should be the maximum number of differentiation directions
    IMPLICIT NONE
    INTEGER :: ib, ibw, ibc, ibc0, ib0, is, ism
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, vte, s1, t0, t1, t2, t3, t4, neave, totpar, &
&   totflux, teave, weight, wrk
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: csd0, vted0, t0d0, t1d0, &
&   t2d0, t3d0, t4d0, neaved0, totpard0, totfluxd0, teaved0, weightd0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd, vted, t0d, t1d, t2d, t3d&
&   , t4d, neaved, totpard, totfluxd, teaved, weightd
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: csdd, vtedd, t0dd&
&   , t1dd, t2dd, t3dd, t4dd, neavedd, totpardd, totfluxdd, teavedd, &
&   weightdd
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(r8) :: y1
    REAL(r8), DIMENSION(nbdirsmax0) :: y1d0
    REAL(r8), DIMENSION(nbdirsmax) :: y1d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y1dd
    REAL(r8) :: y2
    REAL(r8), DIMENSION(nbdirsmax0) :: y2d0
    REAL(r8), DIMENSION(nbdirsmax) :: y2d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y2dd
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x1dd
    REAL(kind=r8) :: y3
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: y3d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y3d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y3dd
    REAL(kind=r8) :: x2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x2d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x2d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x2dd
    REAL(kind=r8) :: x3
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x3d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x3d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x3dd
    REAL(kind=r8) :: y4
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: y4d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y4d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y4dd
    REAL(r8) :: max1
    REAL(r8), DIMENSION(nbdirsmax0) :: max1d0
    REAL(r8), DIMENSION(nbdirsmax) :: max1d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max1dd
    REAL(r8) :: min1
    REAL(r8), DIMENSION(nbdirsmax0) :: min1d0
    REAL(r8), DIMENSION(nbdirsmax) :: min1d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min1dd
    REAL(r8) :: max2
    REAL(r8), DIMENSION(nbdirsmax0) :: max2d0
    REAL(r8), DIMENSION(nbdirsmax) :: max2d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max2dd
    REAL(r8) :: min2
    REAL(r8), DIMENSION(nbdirsmax0) :: min2d0
    REAL(r8), DIMENSION(nbdirsmax) :: min2d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min2dd
    REAL(r8) :: max3
    REAL(r8), DIMENSION(nbdirsmax0) :: max3d0
    REAL(r8), DIMENSION(nbdirsmax) :: max3d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max3dd
    REAL(r8) :: max4
    REAL(r8), DIMENSION(nbdirsmax0) :: max4d0
    REAL(r8), DIMENSION(nbdirsmax) :: max4d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max4dd
    REAL(r8) :: min3
    REAL(r8), DIMENSION(nbdirsmax0) :: min3d0
    REAL(r8), DIMENSION(nbdirsmax) :: min3d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min3dd
    REAL(r8) :: max5
    REAL(r8), DIMENSION(nbdirsmax0) :: max5d0
    REAL(r8), DIMENSION(nbdirsmax) :: max5d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max5dd
    REAL(r8) :: min4
    REAL(r8), DIMENSION(nbdirsmax0) :: min4d0
    REAL(r8), DIMENSION(nbdirsmax) :: min4d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min4dd
    REAL(kind=r8) :: abs0
    REAL(r8) :: min5
    REAL(r8), DIMENSION(nbdirsmax0) :: min5d0
    REAL(r8), DIMENSION(nbdirsmax) :: min5d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min5dd
    REAL(r8) :: max6
    REAL(r8), DIMENSION(nbdirsmax0) :: max6d0
    REAL(r8), DIMENSION(nbdirsmax) :: max6d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max6dd
    REAL(r8) :: min6
    REAL(r8), DIMENSION(nbdirsmax0) :: min6d0
    REAL(r8), DIMENSION(nbdirsmax) :: min6d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min6dd
    REAL(kind=r8) :: max7
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max7d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max7d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max7dd
    REAL(kind=r8) :: max8
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max8d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max8d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max8dd
    REAL(kind=r8) :: max9
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max9d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max9d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max9dd
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: arg12d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg12dd
    REAL(r8) :: arg13
    REAL(r8), DIMENSION(nbdirsmax0) :: arg13d0
    REAL(r8), DIMENSION(nbdirsmax) :: arg13d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg13dd
    REAL(r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: result20d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result20d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: result20dd
    REAL(kind=r8) :: result11
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: result11d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result11d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: result11dd
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: tempd
    REAL(kind=r8) :: temp0
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp0d
    REAL(kind=r8) :: temp1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp1d
    REAL(kind=r8) :: temp2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp2d
    REAL(r8) :: temp3
    REAL(r8), DIMENSION(nbdirsmax0) :: temp3d
    REAL(r8) :: temp4
    REAL(r8), DIMENSION(nbdirsmax0) :: temp4d
    REAL(r8) :: temp5
    REAL(r8), DIMENSION(nbdirsmax0) :: temp5d
    REAL(kind=r8) :: temp6
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp6d
    REAL(kind=r8) :: temp7
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp7d
    INTEGER :: nbdirs
    INTEGER :: nd0
    REAL(kind=r8) :: temp8
    REAL(r8) :: temp9
    REAL(r8) :: temp10
    REAL(r8) :: temp11
    REAL(kind=r8) :: temp12
    REAL(kind=r8) :: temp13
    REAL(kind=r8) :: temp14
    REAL(kind=r8) :: temp15
    REAL(kind=r8) :: temp16
    REAL(kind=r8) :: temp17
    REAL(kind=r8) :: temp18
    REAL(kind=r8) :: temp19
    INTEGER :: nbdirs0
!
! -- BOUNDARY CONDITIONS FOR ELECTRON ENERGY EQUATION --
!
    SELECT CASE  (bcene(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCENE=1 -- PRESCRIBE THE VALUE OF THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (bcchar(ib) .EQ. 'S' .AND. switch%use_astra .NE. 0) THEN
!srv 14.06.12
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              enepardd(nd0, nd, ib, 1) = 0.D0
            END DO
            enepard(nd, ib, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            enepard0(nd0, ib, 1) = 0.D0
          END DO
          enepar(ib, 1) = teb_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  1 : specified electron temperature ', enepar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 1, ENEPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        temp = geo%fcs(ifc)*ev
        DO nd=1,nbdirs
          temp8 = temp*vbig*ne00
          DO nd0=1,nbdirs0
            srwdd%she0(nd0, nd, icv, 0) = temp8*enepardd(nd0, nd, ib, 1)
            srwdd%she0(nd0, nd, icv, 1) = 0.D0
          END DO
          srwd%she0(nd, icv, 0) = temp8*enepard(nd, ib, 1)
          srwd%she0(nd, icv, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv, 0) = vbig*ne00*temp*enepard0(nd0, ib, 1)
          srwd0%she0(nd0, icv, 1) = 0.D0
        END DO
        srw%she0(icv, 0) = vbig*ne00*enepar(ib, 1)*temp
        srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENE=2 -- PRESCRIBE THE GRADIENT OF THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE =  2 : electron temperature gradient '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1dd = 0.D0
        CALL INTVERTEX_S_DV_DV(ivx1, ncv, nvx, mpg, geo%vxvol, pl%te, &
&                        pld0%te, pld%te, pldd%te, t1, t1d0, t1d, t1dd, &
&                        nbdirs, nbdirs0)
        t2dd = 0.D0
        CALL INTVERTEX_S_DV_DV(ivx2, ncv, nvx, mpg, geo%vxvol, pl%te, &
&                        pld0%te, pld%te, pldd%te, t2, t2d0, t2d, t2dd, &
&                        nbdirs, nbdirs0)
        temp = vbig*ne00*geo%fcs(ifc)
        temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
        temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, &
&         2))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          temp8 = geo%fcqgam(ifc, 0)*temp0*ev
          DO nd0=1,nbdirs0
            srwdd%she0(nd0, nd, icv1, 0) = temp*(temp8*enepardd(nd0, nd&
&             , ib, 1)-temp1*temp2*(t2dd(nd0, nd)-t1dd(nd0, nd))/geo%&
&             fcht(ifc)+pldd%te(nd0, nd, icv2))
            srwdd%she0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%she0(nd, icv1, 0) = temp*(temp8*enepard(nd, ib, 1)-temp1*&
&           temp2*((t2d(nd)-t1d(nd))/geo%fcht(ifc))+pld%te(nd, icv2))
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv1, 0) = temp*(temp0*ev*geo%fcqgam(ifc, 0)*&
&           enepard0(nd0, ib, 1)-temp1*temp2*(t2d0(nd0)-t1d0(nd0))/geo%&
&           fcht(ifc)+pld0%te(nd0, icv2))
          srwd0%she0(nd0, icv1, 1) = 0.D0
        END DO
        srw%she0(icv1, 0) = temp*(temp0*(geo%fcqgam(ifc, 0)*(ev*enepar(&
&         ib, 1)))-temp1*(temp2*((t2-t1)/geo%fcht(ifc)))+pl%te(icv2))
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENE=3 -- SHEATH CONDITIONS, ELECTRON ENERGY TRANSMISSION
!
      CALL XERRAB('b2stbc_phys -- BCENE = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCENE = 15')
!
! -- BCENE=4 -- PRESCRIBE THE VALUE OF THE ELECTRON TEMPERATURE,
!                 WEAKLY A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  4 : weak electron temperature ', enepar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 4, ENEPAR(,1) !> 0')
        CALL XERTST(enepar(ib, 2) .GT. 0.0_R8, &
&             'BCENE = 4, ENEPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%she0(nd0, nd, icv, 0) = geo%fcs(ifc)*(enepard(nd, ib, &
&             2)*enepard0(nd0, ib, 1)+enepar(ib, 1)*enepardd(nd0, nd, ib&
&             , 2)+enepard(nd, ib, 1)*enepard0(nd0, ib, 2)+enepar(ib, 2)&
&             *enepardd(nd0, nd, ib, 1))
            srwdd%she0(nd0, nd, icv, 1) = -(geo%fcs(ifc)*enepardd(nd0, &
&             nd, ib, 2)/ev)
          END DO
          srwd%she0(nd, icv, 0) = geo%fcs(ifc)*(enepar(ib, 1)*enepard(nd&
&           , ib, 2)+enepar(ib, 2)*enepard(nd, ib, 1))
          srwd%she0(nd, icv, 1) = -(geo%fcs(ifc)*enepard(nd, ib, 2)/ev)
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv, 0) = geo%fcs(ifc)*(enepar(ib, 1)*enepard0&
&           (nd0, ib, 2)+enepar(ib, 2)*enepard0(nd0, ib, 1))
          srwd0%she0(nd0, icv, 1) = -(geo%fcs(ifc)*enepard0(nd0, ib, 2)/&
&           ev)
        END DO
        srw%she0(icv, 0) = enepar(ib, 2)*geo%fcs(ifc)*enepar(ib, 1)
        srw%she0(icv, 1) = -(enepar(ib, 2)/ev*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCENE=5 -- PRESCRIBE THE ELECTRON ENERGY FLUX PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE =  5 : electron energy flux per area '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%she0(nd0, nd, icv, 0) = geo%fcs(ifc)*enepardd(nd0, nd&
&             , ib, 1)
            srwdd%she0(nd0, nd, icv, 1) = 0.D0
          END DO
          srwd%she0(nd, icv, 0) = geo%fcs(ifc)*enepard(nd, ib, 1)
          srwd%she0(nd, icv, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv, 0) = geo%fcs(ifc)*enepard0(nd0, ib, 1)
          srwd0%she0(nd0, icv, 1) = 0.D0
        END DO
        srw%she0(icv, 0) = enepar(ib, 1)*geo%fcs(ifc)
        srw%she0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCENE=6 -- PRESCRIBE THE TOTAL ELECTRON ENERGY FLUX FOR A
!                 CONSTANT ELECTRON TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENE = 6 not adapted for WG')
!
! -- BCENE=7 -- PRESCRIBE THE ELECTRON TEMPERATURE PROFILE
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') &
&       'BCENE = 7 : specified electron temperature on ', bcchar(ib), &
&       boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%she0(nd0, nd, icv1, 0) = 0.D0
            srwdd%she0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%she0(nd, icv1, 0) = 0.d0
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv1, 0) = 0.D0
          srwd0%she0(nd0, icv1, 1) = 0.D0
        END DO
        srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*bv_te(icv1)*ev
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCENE=8 -- PRESCRIBE THE TOTAL ELECTRON HEAT FLUX WITH CONSTANT
!                 FLUX DENSITY
!wdk BC not recommended for drifts!
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                      'Compile with -DASTRA option to couple to ASTRA!'&
&                                         )
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  8 : total electron energy flux ', enepar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
      END IF
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
      max1dd = 0.D0
      t0dd = 0.D0
      min1dd = 0.D0
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = fac_he_anom_bc*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%she0(nd0, nd, icv1, 0) = temp2*enepardd(nd0, nd, ib, 1&
&             )/us
            srwdd%she0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%she0(nd, icv1, 0) = temp2*enepard(nd, ib, 1)/us
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv1, 0) = temp2*enepard0(nd0, ib, 1)/us
          srwd0%she0(nd0, icv1, 1) = 0.D0
        END DO
        srw%she0(icv1, 0) = temp2*(enepar(ib, 1)/us)
        srw%she0(icv1, 1) = 0.0_R8
        IF (switch%mdf_fhe .NE. 0) THEN
!wdk Correction now involves vedia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_f = 0 option
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1, 0&
&               ) + temp2*(dvdd%fhepsch(nd0, nd, ifc, 0)+dvdd%fhepsch(&
&               nd0, nd, ifc, 1))
            END DO
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + temp2*(dvd&
&             %fhepsch(nd, ifc, 0)+dvd%fhepsch(nd, ifc, 1))
          END DO
          temp3 = pl%te(icv1) + pl%te(icv2)
          temp4 = dv%ne(icv1) + dv%ne(icv2)
          temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
          temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + temp2*&
&             (dvd0%fhepsch(nd0, ifc, 0)+dvd0%fhepsch(nd0, ifc, 1))
            temp3d(nd0) = pld0%te(nd0, icv1) + pld0%te(nd0, icv2)
            temp4d(nd0) = dvd0%ne(nd0, icv1) + dvd0%ne(nd0, icv2)
            temp5d(nd0) = temp3*temp4d(nd0) + temp4*temp3d(nd0)
            tempd(nd0) = temp1*dvd0%vedia(nd0, ifc, 0) + temp0*dvd0%&
&             vedia(nd0, ifc, 1)
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + temp2*(dv%fhepsch(ifc&
&           , 0)+dv%fhepsch(ifc, 1))
          temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&           0.5_R8)
          temp5 = temp4*temp3
          temp = temp1*dv%vedia(ifc, 0) + temp0*dv%vedia(ifc, 1)
          DO nd=1,nbdirs
            temp8 = temp1*dvd%vedia(nd, ifc, 0) + temp0*dvd%vedia(nd, &
&             ifc, 1)
            temp9 = pld%te(nd, icv1) + pld%te(nd, icv2)
            temp10 = dvd%ne(nd, icv1) + dvd%ne(nd, icv2)
            temp11 = temp3*temp10 + temp4*temp9
            DO nd0=1,nbdirs0
              t0dd(nd0, nd) = temp2*(temp8*temp5d(nd0)+temp5*(temp1*dvdd&
&               %vedia(nd0, nd, ifc, 0)+temp0*dvdd%vedia(nd0, nd, ifc, 1&
&               ))+temp11*tempd(nd0)+temp*(temp10*temp3d(nd0)+temp3*(&
&               dvdd%ne(nd0, nd, icv1)+dvdd%ne(nd0, nd, icv2))+temp9*&
&               temp4d(nd0)+temp4*(pldd%te(nd0, nd, icv1)+pldd%te(nd0, &
&               nd, icv2))))
            END DO
            t0d(nd) = temp2*(temp5*temp8+temp*temp11)
          END DO
          DO nd0=1,nbdirs0
            t0d0(nd0) = temp2*(temp5*tempd(nd0)+temp*temp5d(nd0))
          END DO
          t0 = temp2*(temp*temp5)
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max1dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              max1d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              max1d0(nd0) = t0d0(nd0)
            END DO
            max1 = t0
          ELSE
            max1 = 0.0_R8
            max1d = 0.d0
            max1d0 = 0.D0
            max1dd = 0.D0
          END IF
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1, 0&
&               ) + max1dd(nd0, nd)
            END DO
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + max1d(nd)
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + max1d0&
&             (nd0)
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max1
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                min1dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              min1d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              min1d0(nd0) = t0d0(nd0)
            END DO
            min1 = t0
          ELSE
            min1 = 0.0_R8
            min1d = 0.d0
            min1dd = 0.D0
            min1d0 = 0.D0
          END IF
          temp11 = min1/pl%te(icv1)
          DO nd0=1,nbdirs0
            temp5d(nd0) = (min1d0(nd0)-temp11*pld0%te(nd0, icv1))/pl%te(&
&             icv1)
          END DO
          temp5 = temp11
          DO nd=1,nbdirs
            temp11 = (min1d(nd)-temp5*pld%te(nd, icv1))/pl%te(icv1)
            DO nd0=1,nbdirs0
              srwdd%she0(nd0, nd, icv1, 1) = srwdd%she0(nd0, nd, icv1, 1&
&               ) + (min1dd(nd0, nd)-pld%te(nd, icv1)*temp5d(nd0)-temp5*&
&               pldd%te(nd0, nd, icv1)-temp11*pld0%te(nd0, icv1))/pl%te(&
&               icv1)
            END DO
            srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + temp11
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 1) = srwd0%she0(nd0, icv1, 1) + temp5d&
&             (nd0)
          END DO
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + temp5
        END IF
      END DO
    CASE (9) 
!
! -- BCENE=9 -- PRESCRIBE THE DECAY LENGTH FOR THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  9 : electron temperature decay length ', enepar(ib, 1)&
&       , ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0.0_R8, &
&             'BCENE = 9, ENEPAR(,1) = 0')
        ism = 0
        DO is=0,ns-1
          IF (bccon(is, ib) .NE. 9 .AND. (.NOT.is_neutral(is))) THEN
            ism = ism + 1
            WRITE(0, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCENE=9'
            WRITE(*, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCENE=9'
          END IF
          IF (bccon(is, ib) .EQ. 1) WRITE(0, *) &
&                      'Should use BCENE=19 in conjunction with BCCON=1'
          IF (ism .GT. 0) THEN
!srv 21.09.12
            WRITE(*, '(1x,a)') &
&           'Please ensure that this boundary condition '//&
&           'is consistent with the density boundary conditions'
          END IF
        END DO
        min2dd = 0.D0
        t0dd = 0.D0
        max2dd = 0.D0
      ELSE
        min2dd = 0.D0
        t0dd = 0.D0
        max2dd = 0.D0
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        sy = geo%fcs(ifc)
        temp11 = co%hce0(icv1)/enepar(ib, 1)
        DO nd0=1,nbdirs0
          temp5d(nd0) = (cod0%hce0(nd0, icv1)-temp11*enepard0(nd0, ib, 1&
&           ))/enepar(ib, 1)
        END DO
        temp5 = temp11
        DO nd=1,nbdirs
          temp11 = (cod%hce0(nd, icv1)-temp5*enepard(nd, ib, 1))/enepar(&
&           ib, 1)
          DO nd0=1,nbdirs0
            srwdd%she0(nd0, nd, icv1, 0) = 0.D0
            srwdd%she0(nd0, nd, icv1, 1) = -(sy*(codd%hce0(nd0, nd, icv1&
&             )-enepard(nd, ib, 1)*temp5d(nd0)-temp5*enepardd(nd0, nd, &
&             ib, 1)-temp11*enepard0(nd0, ib, 1))/enepar(ib, 1))
          END DO
          srwd%she0(nd, icv1, 0) = 0.d0
          srwd%she0(nd, icv1, 1) = -(sy*temp11)
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv1, 0) = 0.D0
          srwd0%she0(nd0, icv1, 1) = -(sy*temp5d(nd0))
        END DO
        srw%she0(icv1, 0) = 0.0_R8
        srw%she0(icv1, 1) = -(sy*temp5)
        DO is=0,ns-1
          DO nd0=1,nbdirs0
            temp5d(nd0) = pl%te(icv1)*rtd0%rza(nd0, icv1, is) + rt%rza(&
&             icv1, is)*pld0%te(nd0, icv1)
          END DO
          temp5 = rt%rza(icv1, is)*pl%te(icv1)
          DO nd=1,nbdirs
            temp11 = pl%te(icv1)*rtd%rza(nd, icv1, is) + rt%rza(icv1, is&
&             )*pld%te(nd, icv1)
            temp10 = srwd%sna0(nd, icv1, 0, is)
            DO nd0=1,nbdirs0
              srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1, 0&
&               ) + fac_he_anom*(temp11*srwd0%sna0(nd0, icv1, 0, is)+srw&
&               %sna0(icv1, 0, is)*(rtd%rza(nd, icv1, is)*pld0%te(nd0, &
&               icv1)+pl%te(icv1)*rtdd%rza(nd0, nd, icv1, is)+pld%te(nd&
&               , icv1)*rtd0%rza(nd0, icv1, is)+rt%rza(icv1, is)*pldd%te&
&               (nd0, nd, icv1))+temp10*temp5d(nd0)+temp5*srwdd%sna0(nd0&
&               , nd, icv1, 0, is))
            END DO
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + &
&             fac_he_anom*(srw%sna0(icv1, 0, is)*temp11+temp5*temp10)
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + &
&             fac_he_anom*(srw%sna0(icv1, 0, is)*temp5d(nd0)+temp5*srwd0&
&             %sna0(nd0, icv1, 0, is))
            temp5d(nd0) = pl%na(icv1, is)*rtd0%rza(nd0, icv1, is) + rt%&
&             rza(icv1, is)*pld0%na(nd0, icv1, is)
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + fac_he_anom*(temp5*srw&
&           %sna0(icv1, 0, is))
          temp5 = rt%rza(icv1, is)*pl%na(icv1, is)
          DO nd=1,nbdirs
            temp11 = srwd%sna0(nd, icv1, 1, is)
            temp10 = pl%na(icv1, is)*rtd%rza(nd, icv1, is) + rt%rza(icv1&
&             , is)*pld%na(nd, icv1, is)
            DO nd0=1,nbdirs0
              srwdd%she0(nd0, nd, icv1, 1) = srwdd%she0(nd0, nd, icv1, 1&
&               ) + fac_he_anom*(temp11*temp5d(nd0)+temp5*srwdd%sna0(nd0&
&               , nd, icv1, 1, is)+temp10*srwd0%sna0(nd0, icv1, 1, is)+&
&               srw%sna0(icv1, 1, is)*(rtd%rza(nd, icv1, is)*pld0%na(nd0&
&               , icv1, is)+pl%na(icv1, is)*rtdd%rza(nd0, nd, icv1, is)+&
&               pld%na(nd, icv1, is)*rtd0%rza(nd0, icv1, is)+rt%rza(icv1&
&               , is)*pldd%na(nd0, nd, icv1, is)))
            END DO
            srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + &
&             fac_he_anom*(temp5*temp11+srw%sna0(icv1, 1, is)*temp10)
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 1) = srwd0%she0(nd0, icv1, 1) + &
&             fac_he_anom*(temp5*srwd0%sna0(nd0, icv1, 1, is)+srw%sna0(&
&             icv1, 1, is)*temp5d(nd0))
          END DO
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + fac_he_anom*(srw%sna0(&
&           icv1, 1, is)*temp5)
!! end species loop
        END DO
        IF (switch%mdf_fhe .NE. 0) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1, 0&
&               ) + temp2*(dvdd%fhepsch(nd0, nd, ifc, 0)+dvdd%fhepsch(&
&               nd0, nd, ifc, 1))
            END DO
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + temp2*(dvd&
&             %fhepsch(nd, ifc, 0)+dvd%fhepsch(nd, ifc, 1))
          END DO
          temp5 = pl%te(icv1) + pl%te(icv2)
          temp4 = dv%ne(icv1) + dv%ne(icv2)
          temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
          temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + temp2*&
&             (dvd0%fhepsch(nd0, ifc, 0)+dvd0%fhepsch(nd0, ifc, 1))
            temp5d(nd0) = pld0%te(nd0, icv1) + pld0%te(nd0, icv2)
            temp4d(nd0) = dvd0%ne(nd0, icv1) + dvd0%ne(nd0, icv2)
            temp3d(nd0) = temp5*temp4d(nd0) + temp4*temp5d(nd0)
            tempd(nd0) = temp1*dvd0%veecrb(nd0, ifc, 0) + temp0*dvd0%&
&             veecrb(nd0, ifc, 1)
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + temp2*(dv%fhepsch(ifc&
&           , 0)+dv%fhepsch(ifc, 1))
          temp2 = 1.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&           0.5_R8)
          temp3 = temp4*temp5
          temp = temp1*dv%veecrb(ifc, 0) + temp0*dv%veecrb(ifc, 1)
          DO nd=1,nbdirs
            temp8 = temp1*dvd%veecrb(nd, ifc, 0) + temp0*dvd%veecrb(nd, &
&             ifc, 1)
            temp11 = pld%te(nd, icv1) + pld%te(nd, icv2)
            temp10 = dvd%ne(nd, icv1) + dvd%ne(nd, icv2)
            temp9 = temp5*temp10 + temp4*temp11
            DO nd0=1,nbdirs0
              t0dd(nd0, nd) = -(temp2*(temp8*temp3d(nd0)+temp3*(temp1*&
&               dvdd%veecrb(nd0, nd, ifc, 0)+temp0*dvdd%veecrb(nd0, nd, &
&               ifc, 1))+temp9*tempd(nd0)+temp*(temp10*temp5d(nd0)+temp5&
&               *(dvdd%ne(nd0, nd, icv1)+dvdd%ne(nd0, nd, icv2))+temp11*&
&               temp4d(nd0)+temp4*(pldd%te(nd0, nd, icv1)+pldd%te(nd0, &
&               nd, icv2)))))
            END DO
            t0d(nd) = -(temp2*(temp3*temp8+temp*temp9))
          END DO
          DO nd0=1,nbdirs0
            t0d0(nd0) = -(temp2*(temp3*tempd(nd0)+temp*temp3d(nd0)))
          END DO
          t0 = -(temp2*(temp*temp3))
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max2dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              max2d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              max2d0(nd0) = t0d0(nd0)
            END DO
            max2 = t0
          ELSE
            max2 = 0.0_R8
            max2d = 0.d0
            max2d0 = 0.D0
            max2dd = 0.D0
          END IF
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1, 0&
&               ) + max2dd(nd0, nd)
            END DO
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + max2d(nd)
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + max2d0&
&             (nd0)
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max2
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                min2dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              min2d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              min2d0(nd0) = t0d0(nd0)
            END DO
            min2 = t0
          ELSE
            min2 = 0.0_R8
            min2d = 0.d0
            min2dd = 0.D0
            min2d0 = 0.D0
          END IF
          temp11 = min2/pl%te(icv1)
          DO nd0=1,nbdirs0
            temp5d(nd0) = (min2d0(nd0)-temp11*pld0%te(nd0, icv1))/pl%te(&
&             icv1)
          END DO
          temp5 = temp11
          DO nd=1,nbdirs
            temp11 = (min2d(nd)-temp5*pld%te(nd, icv1))/pl%te(icv1)
            DO nd0=1,nbdirs0
              srwdd%she0(nd0, nd, icv1, 1) = srwdd%she0(nd0, nd, icv1, 1&
&               ) + (min2dd(nd0, nd)-pld%te(nd, icv1)*temp5d(nd0)-temp5*&
&               pldd%te(nd0, nd, icv1)-temp11*pld0%te(nd0, icv1))/pl%te(&
&               icv1)
            END DO
            srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + temp11
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 1) = srwd0%she0(nd0, icv1, 1) + temp5d&
&             (nd0)
          END DO
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + temp5
        END IF
!! end loop over cells

      END DO
    CASE (10) 
!
! -- BCENE=10 -- Feedback option for core
!
      CALL XERRAB('b2stbc_phys -- BCENE = 10 not adapted for WG')
!
! -- BCENE=11 -- FROM B2STBC_SPB                                       !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
    CASE (11) 
      CALL XERRAB('b2stbc_phys -- BCENE = 11 not adapted for WG')
!
! -- BCENE=12 -- SHEATH CONDITIONS, EL ENERGY TRANSMISSION COEFFICIENT
!
    CASE (12) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,1p,g14.7)') &
&       'BCENE = 12 : sheath electron bc on ', bcchar(ib), &
&       boundary_location(ib), ' with transmission coefficient ', enepar&
&       (ib, 1)
        WRITE(*, '(a)') &
&       'Obsolete. Use drift-compatible BCENE = 15 instead'
        max3dd = 0.D0
      ELSE
        max3dd = 0.D0
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fne(ifc, &
&           0)+dv%fne(ifc, 1))) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              max3dd(nd0, nd) = temp2*(dvdd%fne(nd0, nd, ifc, 0)+dvdd%&
&               fne(nd0, nd, ifc, 1))
            END DO
            max3d(nd) = temp2*(dvd%fne(nd, ifc, 0)+dvd%fne(nd, ifc, 1))
          END DO
          DO nd0=1,nbdirs0
            max3d0(nd0) = temp2*(dvd0%fne(nd0, ifc, 0)+dvd0%fne(nd0, ifc&
&             , 1))
          END DO
          max3 = temp2*(dv%fne(ifc, 0)+dv%fne(ifc, 1))
        ELSE
          max3 = 0.0_R8
          max3d = 0.d0
          max3d0 = 0.D0
          max3dd = 0.D0
        END IF
        temp8 = enepar(ib, 1)*max3/dv%ne(icv)
        DO nd0=1,nbdirs0
          temp2d(nd0) = (max3*enepard0(nd0, ib, 1)+enepar(ib, 1)*max3d0(&
&           nd0)-temp8*dvd0%ne(nd0, icv))/dv%ne(icv)
        END DO
        temp2 = temp8
        DO nd=1,nbdirs
          temp11 = (max3*enepard(nd, ib, 1)+enepar(ib, 1)*max3d(nd)-&
&           temp2*dvd%ne(nd, icv))/dv%ne(icv)
          DO nd0=1,nbdirs0
            srwdd%she0(nd0, nd, icv, 3) = srwdd%she0(nd0, nd, icv, 3) - &
&             (enepard(nd, ib, 1)*max3d0(nd0)+max3*enepardd(nd0, nd, ib&
&             , 1)+max3d(nd)*enepard0(nd0, ib, 1)+enepar(ib, 1)*max3dd(&
&             nd0, nd)-dvd%ne(nd, icv)*temp2d(nd0)-temp2*dvdd%ne(nd0, nd&
&             , icv)-temp11*dvd0%ne(nd0, icv))/dv%ne(icv)
          END DO
          srwd%she0(nd, icv, 3) = srwd%she0(nd, icv, 3) - temp11
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv, 3) = srwd0%she0(nd0, icv, 3) - temp2d(nd0&
&           )
        END DO
        srw%she0(icv, 3) = srw%she0(icv, 3) - temp2
      END DO
    CASE (13) 
!
! -- BCENE=13 -- PRESCRIBE THE ELECTRON ENERGY FLUX PER UNIT AREA
!             -- PROPORTIONAL TO TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE = 13 : electron energy flux per area '&
&                                   //'proportional to temperature ', &
&                                   enepar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%she0(nd0, nd, icv, 0) = geo%fcs(ifc)*(enepard(nd, ib, &
&             1)*pld0%te(nd0, icv)+pl%te(icv)*enepardd(nd0, nd, ib, 1)+&
&             pld%te(nd, icv)*enepard0(nd0, ib, 1)+enepar(ib, 1)*pldd%te&
&             (nd0, nd, icv))
            srwdd%she0(nd0, nd, icv, 1) = 0.D0
          END DO
          srwd%she0(nd, icv, 0) = geo%fcs(ifc)*(pl%te(icv)*enepard(nd, &
&           ib, 1)+enepar(ib, 1)*pld%te(nd, icv))
          srwd%she0(nd, icv, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv, 0) = geo%fcs(ifc)*(pl%te(icv)*enepard0(&
&           nd0, ib, 1)+enepar(ib, 1)*pld0%te(nd0, icv))
          srwd0%she0(nd0, icv, 1) = 0.D0
        END DO
        srw%she0(icv, 0) = enepar(ib, 1)*pl%te(icv)*geo%fcs(ifc)
        srw%she0(icv, 1) = 0.0_R8
      END DO
    CASE (14) 
!
! -- BCENE=14 -- leakage option for electron energy
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE = 14 : electron energy leakage ', enepar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        csdd = 0.D0
        min3dd = 0.D0
        max4dd = 0.D0
        arg12dd = 0.D0
        t0dd = 0.D0
      ELSE
        csdd = 0.D0
        min3dd = 0.D0
        max4dd = 0.D0
        arg12dd = 0.D0
        t0dd = 0.D0
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp8 = pz(icv1)/rz(icv1)
        DO nd0=1,nbdirs0
          temp2d(nd0) = (pzd0(nd0, icv1)-temp8*rzd0(nd0, icv1))/rz(icv1)
        END DO
        temp2 = temp8
        DO nd=1,nbdirs
          temp8 = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
          DO nd0=1,nbdirs0
            arg12dd(nd0, nd) = (pzdd(nd0, nd, icv1)-rzd(nd, icv1)*temp2d&
&             (nd0)-temp2*rzdd(nd0, nd, icv1)-temp8*rzd0(nd0, icv1))/rz(&
&             icv1)
          END DO
          arg12d(nd) = temp8
        END DO
        arg12 = temp2
        temp8 = SQRT(arg12)
        DO nd0=1,nbdirs0
          arg12d0(nd0) = temp2d(nd0)
          IF (arg12 .EQ. 0.D0) THEN
            temp2d(nd0) = 0.D0
          ELSE
            temp2d(nd0) = arg12d0(nd0)/(2.0*temp8)
          END IF
        END DO
        temp2 = temp8
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = 0.D0
            END DO
            csd(nd) = 0.d0
          ELSE
            temp8 = arg12d(nd)/(2.0*temp2)
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = (arg12dd(nd0, nd)-temp8*2.0*temp2d(nd0))/(&
&               2.0*temp2)
            END DO
            csd(nd) = temp8
          END IF
        END DO
        cs = temp2
        temp0 = cs*dv%ne(icv1)
        DO nd0=1,nbdirs0
          csd0(nd0) = temp2d(nd0)
          temp1d(nd0) = enepar(ib, 2)*enepard0(nd0, ib, 1) + enepar(ib, &
&           1)*enepard0(nd0, ib, 2)
          temp0d(nd0) = dv%ne(icv1)*csd0(nd0) + cs*dvd0%ne(nd0, icv1)
          tempd(nd0) = pl%po(icv1)*temp0d(nd0) + temp0*pld0%po(nd0, icv1&
&           )
        END DO
        temp2 = geo%fcs(ifc)*fac_he_anom_bc*qe
        temp1 = enepar(ib, 1)*enepar(ib, 2)
        temp = temp0*pl%po(icv1)
        DO nd=1,nbdirs
          temp11 = dv%ne(icv1)*csd(nd) + cs*dvd%ne(nd, icv1)
          temp10 = pl%po(icv1)*temp11 + temp0*pld%po(nd, icv1)
          temp8 = enepar(ib, 2)*enepard(nd, ib, 1) + enepar(ib, 1)*&
&           enepard(nd, ib, 2)
          DO nd0=1,nbdirs0
            srwdd%she0(nd0, nd, icv1, 0) = temp2*(temp10*temp1d(nd0)+&
&             temp1*(temp11*pld0%po(nd0, icv1)+pl%po(icv1)*(csd(nd)*dvd0&
&             %ne(nd0, icv1)+dv%ne(icv1)*csdd(nd0, nd)+dvd%ne(nd, icv1)*&
&             csd0(nd0)+cs*dvdd%ne(nd0, nd, icv1))+pld%po(nd, icv1)*&
&             temp0d(nd0)+temp0*pldd%po(nd0, nd, icv1))+temp8*tempd(nd0)&
&             +temp*(enepard(nd, ib, 1)*enepard0(nd0, ib, 2)+enepar(ib, &
&             2)*enepardd(nd0, nd, ib, 1)+enepard(nd, ib, 2)*enepard0(&
&             nd0, ib, 1)+enepar(ib, 1)*enepardd(nd0, nd, ib, 2)))
          END DO
          srwd%she0(nd, icv1, 0) = temp2*(temp1*temp10+temp*temp8)
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv1, 0) = temp2*(temp1*tempd(nd0)+temp*temp1d&
&           (nd0))
        END DO
        srw%she0(icv1, 0) = temp2*(temp*temp1)
        temp2 = geo%fcs(ifc)*fac_he_anom_bc
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%she0(nd0, nd, icv1, 3) = temp2*(csd(nd)*enepard0(nd0, &
&             ib, 1)+enepar(ib, 1)*csdd(nd0, nd)+enepard(nd, ib, 1)*csd0&
&             (nd0)+cs*enepardd(nd0, nd, ib, 1))
          END DO
          srwd%she0(nd, icv1, 3) = temp2*(enepar(ib, 1)*csd(nd)+cs*&
&           enepard(nd, ib, 1))
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv1, 3) = temp2*(enepar(ib, 1)*csd0(nd0)+cs*&
&           enepard0(nd0, ib, 1))
        END DO
        srw%she0(icv1, 3) = temp2*(cs*enepar(ib, 1))
        IF (switch%mdf_fhe .NE. 0) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1, 0&
&               ) + temp2*(dvdd%fhepsch(nd0, nd, ifc, 0)+dvdd%fhepsch(&
&               nd0, nd, ifc, 1))
            END DO
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + temp2*(dvd&
&             %fhepsch(nd, ifc, 0)+dvd%fhepsch(nd, ifc, 1))
          END DO
          temp5 = pl%te(icv1) + pl%te(icv2)
          temp4 = dv%ne(icv1) + dv%ne(icv2)
          temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
          temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + temp2*&
&             (dvd0%fhepsch(nd0, ifc, 0)+dvd0%fhepsch(nd0, ifc, 1))
            temp5d(nd0) = pld0%te(nd0, icv1) + pld0%te(nd0, icv2)
            temp4d(nd0) = dvd0%ne(nd0, icv1) + dvd0%ne(nd0, icv2)
            temp3d(nd0) = temp5*temp4d(nd0) + temp4*temp5d(nd0)
            tempd(nd0) = temp1*dvd0%vedia(nd0, ifc, 0) + temp0*dvd0%&
&             vedia(nd0, ifc, 1)
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + temp2*(dv%fhepsch(ifc&
&           , 0)+dv%fhepsch(ifc, 1))
          temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&           0.5_R8)
          temp3 = temp4*temp5
          temp = temp1*dv%vedia(ifc, 0) + temp0*dv%vedia(ifc, 1)
          DO nd=1,nbdirs
            temp8 = temp1*dvd%vedia(nd, ifc, 0) + temp0*dvd%vedia(nd, &
&             ifc, 1)
            temp11 = pld%te(nd, icv1) + pld%te(nd, icv2)
            temp10 = dvd%ne(nd, icv1) + dvd%ne(nd, icv2)
            temp9 = temp5*temp10 + temp4*temp11
            DO nd0=1,nbdirs0
              t0dd(nd0, nd) = temp2*(temp8*temp3d(nd0)+temp3*(temp1*dvdd&
&               %vedia(nd0, nd, ifc, 0)+temp0*dvdd%vedia(nd0, nd, ifc, 1&
&               ))+temp9*tempd(nd0)+temp*(temp10*temp5d(nd0)+temp5*(dvdd&
&               %ne(nd0, nd, icv1)+dvdd%ne(nd0, nd, icv2))+temp11*temp4d&
&               (nd0)+temp4*(pldd%te(nd0, nd, icv1)+pldd%te(nd0, nd, &
&               icv2))))
            END DO
            t0d(nd) = temp2*(temp3*temp8+temp*temp9)
          END DO
          DO nd0=1,nbdirs0
            t0d0(nd0) = temp2*(temp3*tempd(nd0)+temp*temp3d(nd0))
          END DO
          t0 = temp2*(temp*temp3)
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max4dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              max4d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              max4d0(nd0) = t0d0(nd0)
            END DO
            max4 = t0
          ELSE
            max4 = 0.0_R8
            max4d = 0.d0
            max4d0 = 0.D0
            max4dd = 0.D0
          END IF
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1, 0&
&               ) + max4dd(nd0, nd)
            END DO
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + max4d(nd)
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + max4d0&
&             (nd0)
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max4
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                min3dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              min3d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              min3d0(nd0) = t0d0(nd0)
            END DO
            min3 = t0
          ELSE
            min3 = 0.0_R8
            min3d = 0.d0
            min3dd = 0.D0
            min3d0 = 0.D0
          END IF
          temp11 = min3/pl%te(icv1)
          DO nd0=1,nbdirs0
            temp5d(nd0) = (min3d0(nd0)-temp11*pld0%te(nd0, icv1))/pl%te(&
&             icv1)
          END DO
          temp5 = temp11
          DO nd=1,nbdirs
            temp11 = (min3d(nd)-temp5*pld%te(nd, icv1))/pl%te(icv1)
            DO nd0=1,nbdirs0
              srwdd%she0(nd0, nd, icv1, 1) = srwdd%she0(nd0, nd, icv1, 1&
&               ) + (min3dd(nd0, nd)-pld%te(nd, icv1)*temp5d(nd0)-temp5*&
&               pldd%te(nd0, nd, icv1)-temp11*pld0%te(nd0, icv1))/pl%te(&
&               icv1)
            END DO
            srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + temp11
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 1) = srwd0%she0(nd0, icv1, 1) + temp5d&
&             (nd0)
          END DO
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + temp5
        END IF
      END DO
    CASE (15) 
!
! -- BCENE=15 -- DRIFT-COMPATIBLE SHEATH CONDITION                      !srv 01.02.09 {
!srv 20.09.17 }
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 20.09.17 {
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE = 15 (style = 0) : with GAMMAE =', gammae, ' on ', bcchar&
&       (ib), boundary_location(ib)
        WRITE(*, *) 'BCENE=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY ', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY ', ib&
&                                , ' FOR ALL IONS'
      END IF
!srv 01.02.09 }
!srv added accumulation in order to account twice b.c. for corner cells
      IF (bcene_15_style .EQ. 0) THEN
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a)') &
&         'BCENE = 15 (style = 0) : with GAMMAE =', gammae, ' on ', &
&         bcchar(ib), boundary_location(ib)
          y1dd = 0.D0
          csdd = 0.D0
          arg12dd = 0.D0
          t0dd = 0.D0
          min4dd = 0.D0
          max5dd = 0.D0
        ELSE
          y1dd = 0.D0
          csdd = 0.D0
          arg12dd = 0.D0
          t0dd = 0.D0
          min4dd = 0.D0
          max5dd = 0.D0
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp8 = pz(icv1)/rz(icv1)
          DO nd0=1,nbdirs0
            temp2d(nd0) = (pzd0(nd0, icv1)-temp8*rzd0(nd0, icv1))/rz(&
&             icv1)
          END DO
          temp2 = temp8
          DO nd=1,nbdirs
            temp8 = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
            DO nd0=1,nbdirs0
              arg12dd(nd0, nd) = (pzdd(nd0, nd, icv1)-rzd(nd, icv1)*&
&               temp2d(nd0)-temp2*rzdd(nd0, nd, icv1)-temp8*rzd0(nd0, &
&               icv1))/rz(icv1)
              t0dd(nd0, nd) = dvdd%ne(nd0, nd, icv1)
            END DO
            arg12d(nd) = temp8
            t0d(nd) = dvd%ne(nd, icv1)
          END DO
          arg12 = temp2
          temp8 = SQRT(arg12)
          DO nd0=1,nbdirs0
            arg12d0(nd0) = temp2d(nd0)
            IF (arg12 .EQ. 0.D0) THEN
              temp2d(nd0) = 0.D0
            ELSE
              temp2d(nd0) = arg12d0(nd0)/(2.0*temp8)
            END IF
          END DO
          temp2 = temp8
          DO nd=1,nbdirs
            IF (arg12 .EQ. 0.d0) THEN
              DO nd0=1,nbdirs0
                csdd(nd0, nd) = 0.D0
              END DO
              csd(nd) = 0.d0
            ELSE
              temp8 = arg12d(nd)/(2.0*temp2)
              DO nd0=1,nbdirs0
                csdd(nd0, nd) = (arg12dd(nd0, nd)-temp8*2.0*temp2d(nd0))&
&                 /(2.0*temp2)
              END DO
              csd(nd) = temp8
            END IF
          END DO
          DO nd0=1,nbdirs0
            csd0(nd0) = temp2d(nd0)
            t0d0(nd0) = dvd0%ne(nd0, icv1)
          END DO
          cs = temp2
          t0 = dv%ne(icv1)
          t1 = 0.0_R8
          t1d = 0.d0
          t1d0 = 0.D0
          t1dd = 0.D0
          DO is=0,ns-1
            IF (.NOT.is_neutral(is) .AND. conpar(is, ib, 2) .GT. 0.0_R8&
&           ) THEN
              temp11 = pl%na(icv1, is)/conpar(is, ib, 2)
              DO nd0=1,nbdirs0
                temp5d(nd0) = (pld0%na(nd0, icv1, is)-temp11*conpard0(&
&                 nd0, is, ib, 2))/conpar(is, ib, 2)
                temp4d(nd0) = rt%rza(icv1, is)*cod0%dna0(nd0, icv1, is) &
&                 + co%dna0(icv1, is)*rtd0%rza(nd0, icv1, is)
              END DO
              temp5 = temp11
              temp4 = co%dna0(icv1, is)*rt%rza(icv1, is)
              DO nd=1,nbdirs
                temp11 = rt%rza(icv1, is)*cod%dna0(nd, icv1, is) + co%&
&                 dna0(icv1, is)*rtd%rza(nd, icv1, is)
                temp10 = temp4/conpar(is, ib, 2)
                temp9 = pld%na(nd, icv1, is) - temp5*conpard(nd, is, ib&
&                 , 2)
                DO nd0=1,nbdirs0
                  t1dd(nd0, nd) = t1dd(nd0, nd) + temp11*temp5d(nd0) + &
&                   temp5*(cod%dna0(nd, icv1, is)*rtd0%rza(nd0, icv1, is&
&                   )+rt%rza(icv1, is)*codd%dna0(nd0, nd, icv1, is)+rtd%&
&                   rza(nd, icv1, is)*cod0%dna0(nd0, icv1, is)+co%dna0(&
&                   icv1, is)*rtdd%rza(nd0, nd, icv1, is)) + temp10*(&
&                   pldd%na(nd0, nd, icv1, is)-conpard(nd, is, ib, 2)*&
&                   temp5d(nd0)-temp5*conpardd(nd0, nd, is, ib, 2)) + &
&                   temp9*(temp4d(nd0)-temp10*conpard0(nd0, is, ib, 2))/&
&                   conpar(is, ib, 2)
                END DO
                t1d(nd) = t1d(nd) + temp5*temp11 + temp9*temp10
              END DO
              DO nd0=1,nbdirs0
                t1d0(nd0) = t1d0(nd0) + temp5*temp4d(nd0) + temp4*temp5d&
&                 (nd0)
              END DO
              t1 = t1 + temp4*temp5
            END IF
          END DO
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs1 = geo%fcpbs(ifc)
          ELSE
            abs1 = -geo%fcpbs(ifc)
          END IF
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              y1dd(nd0, nd) = abs1*(t0d(nd)*csd0(nd0)+cs*t0dd(nd0, nd)+&
&               csd(nd)*t0d0(nd0)+t0*csdd(nd0, nd)) - temp2*dvdd%fch_p(&
&               nd0, nd, ifc, 0)/qe
            END DO
            y1d(nd) = abs1*(cs*t0d(nd)+t0*csd(nd)) - temp2*dvd%fch_p(nd&
&             , ifc, 0)/qe
          END DO
          DO nd0=1,nbdirs0
            y1d0(nd0) = abs1*(cs*t0d0(nd0)+t0*csd0(nd0)) - temp2*dvd0%&
&             fch_p(nd0, ifc, 0)/qe
          END DO
          y1 = abs1*(t0*cs) - temp2*(dv%fch_p(ifc, 0)/qe)
          IF (0.0_R8 .LT. y1) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t0dd(nd0, nd) = y1dd(nd0, nd)
              END DO
              t0d(nd) = y1d(nd)
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = y1d0(nd0)
            END DO
            t0 = y1
          ELSE
            t0 = 0.0_R8
            t0d = 0.d0
            t0d0 = 0.D0
            t0dd = 0.D0
          END IF
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t1dd(nd0, nd) = geo%fcs(ifc)*t1dd(nd0, nd)
            END DO
            t1d(nd) = geo%fcs(ifc)*t1d(nd)
          END DO
          DO nd0=1,nbdirs0
            t1d0(nd0) = geo%fcs(ifc)*t1d0(nd0)
          END DO
          t1 = t1*geo%fcs(ifc)
!srv 27.02.13 }
          IF (switch%pot_eq .EQ. 1) THEN
!srv 07.11.12
            DO nd0=1,nbdirs0
              temp5d(nd0) = pld0%po(nd0, icv1) - potpard0(nd0, ib, 2)
            END DO
            temp5 = pl%po(icv1) - potpar(ib, 2)
            DO nd=1,nbdirs
              temp11 = pld%po(nd, icv1) - potpard(nd, ib, 2)
              DO nd0=1,nbdirs0
!srv 27.02.13 {
!srv 11.03.09 {
!srv 19.04.13
!wdk to check: correct for gammae?
                srwdd%she0(nd0, nd, icv1, 1) = srwdd%she0(nd0, nd, icv1&
&                 , 1) - (gammae+1.0_R8)*t0dd(nd0, nd)/(1.0_R8-gammae) -&
&                 fac_he_anom_bc*(enepard(nd, ib, 2)*t1d0(nd0)+t1*&
&                 enepardd(nd0, nd, ib, 2)+t1d(nd)*enepard0(nd0, ib, 2)+&
&                 enepar(ib, 2)*t1dd(nd0, nd))
                srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1&
&                 , 0) - qe*(temp11*(t0d0(nd0)+t1d0(nd0))+(t0+t1)*(pldd%&
&                 po(nd0, nd, icv1)-potpardd(nd0, nd, ib, 2))+(t0d(nd)+&
&                 t1d(nd))*temp5d(nd0)+temp5*(t0dd(nd0, nd)+t1dd(nd0, nd&
&                 )))
              END DO
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) - (gammae+&
&               1.0_R8)*t0d(nd)/(1.0_R8-gammae) - fac_he_anom_bc*(t1*&
&               enepard(nd, ib, 2)+enepar(ib, 2)*t1d(nd))
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) - qe*((t0+&
&               t1)*temp11+temp5*(t0d(nd)+t1d(nd)))
            END DO
            DO nd0=1,nbdirs0
              srwd0%she0(nd0, icv1, 1) = srwd0%she0(nd0, icv1, 1) - (&
&               gammae+1.0_R8)*t0d0(nd0)/(1.0_R8-gammae) - &
&               fac_he_anom_bc*(t1*enepard0(nd0, ib, 2)+enepar(ib, 2)*&
&               t1d0(nd0))
              srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) - qe*(&
&               (t0+t1)*temp5d(nd0)+temp5*(t0d0(nd0)+t1d0(nd0)))
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - (1.0_R8+gammae)/(&
&             1.0_R8-gammae)*t0 - fac_he_anom_bc*enepar(ib, 2)*t1
            srw%she0(icv1, 0) = srw%she0(icv1, 0) - qe*(temp5*(t0+t1))
          ELSE
!srv 27.02.13
!srv 11.03.09 {
!srv 19.04.13
!wdk to check: correct for gammae?
            temp2 = (gammae+1.0_R8)/(-gammae+1.0_R8) + switch%delpo
            DO nd0=1,nbdirs0
              temp1d(nd0) = fac_he_anom_bc*enepard0(nd0, ib, 2)
            END DO
            temp1 = switch%delpo + fac_he_anom_bc*enepar(ib, 2)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%she0(nd0, nd, icv1, 1) = srwdd%she0(nd0, nd, icv1&
&                 , 1) - temp2*t0dd(nd0, nd) - fac_he_anom_bc*(enepard(&
&                 nd, ib, 2)*t1d0(nd0)+t1*enepardd(nd0, nd, ib, 2)) - &
&                 t1d(nd)*temp1d(nd0) - temp1*t1dd(nd0, nd)
              END DO
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) - temp2*&
&               t0d(nd) - t1*fac_he_anom_bc*enepard(nd, ib, 2) - temp1*&
&               t1d(nd)
            END DO
            DO nd0=1,nbdirs0
              srwd0%she0(nd0, icv1, 1) = srwd0%she0(nd0, icv1, 1) - &
&               temp2*t0d0(nd0) - t1*temp1d(nd0) - temp1*t1d0(nd0)
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - temp2*t0 - temp1*t1
          END IF
          IF (switch%mdf_fhe .NE. 0) THEN
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1&
&                 , 0) + temp2*(dvdd%fhepsch(nd0, nd, ifc, 0)+dvdd%&
&                 fhepsch(nd0, nd, ifc, 1))
              END DO
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + temp2*(&
&               dvd%fhepsch(nd, ifc, 0)+dvd%fhepsch(nd, ifc, 1))
            END DO
            temp5 = pl%te(icv1) + pl%te(icv2)
            temp4 = dv%ne(icv1) + dv%ne(icv2)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + &
&               temp2*(dvd0%fhepsch(nd0, ifc, 0)+dvd0%fhepsch(nd0, ifc, &
&               1))
              temp5d(nd0) = pld0%te(nd0, icv1) + pld0%te(nd0, icv2)
              temp4d(nd0) = dvd0%ne(nd0, icv1) + dvd0%ne(nd0, icv2)
              temp3d(nd0) = temp5*temp4d(nd0) + temp4*temp5d(nd0)
              tempd(nd0) = temp1*dvd0%vedia(nd0, ifc, 0) + temp0*dvd0%&
&               vedia(nd0, ifc, 1)
            END DO
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + temp2*(dv%fhepsch(&
&             ifc, 0)+dv%fhepsch(ifc, 1))
            temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp3 = temp4*temp5
            temp = temp1*dv%vedia(ifc, 0) + temp0*dv%vedia(ifc, 1)
            DO nd=1,nbdirs
              temp8 = temp1*dvd%vedia(nd, ifc, 0) + temp0*dvd%vedia(nd, &
&               ifc, 1)
              temp11 = pld%te(nd, icv1) + pld%te(nd, icv2)
              temp10 = dvd%ne(nd, icv1) + dvd%ne(nd, icv2)
              temp9 = temp5*temp10 + temp4*temp11
              DO nd0=1,nbdirs0
                t0dd(nd0, nd) = temp2*(temp8*temp3d(nd0)+temp3*(temp1*&
&                 dvdd%vedia(nd0, nd, ifc, 0)+temp0*dvdd%vedia(nd0, nd, &
&                 ifc, 1))+temp9*tempd(nd0)+temp*(temp10*temp5d(nd0)+&
&                 temp5*(dvdd%ne(nd0, nd, icv1)+dvdd%ne(nd0, nd, icv2))+&
&                 temp11*temp4d(nd0)+temp4*(pldd%te(nd0, nd, icv1)+pldd%&
&                 te(nd0, nd, icv2))))
              END DO
              t0d(nd) = temp2*(temp3*temp8+temp*temp9)
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = temp2*(temp3*tempd(nd0)+temp*temp3d(nd0))
            END DO
            t0 = temp2*(temp*temp3)
            IF (0.0_R8 .LT. t0) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max5dd(nd0, nd) = t0dd(nd0, nd)
                END DO
                max5d(nd) = t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                max5d0(nd0) = t0d0(nd0)
              END DO
              max5 = t0
            ELSE
              max5 = 0.0_R8
              max5d = 0.d0
              max5d0 = 0.D0
              max5dd = 0.D0
            END IF
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1&
&                 , 0) + max5dd(nd0, nd)
              END DO
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + max5d(nd&
&               )
            END DO
            DO nd0=1,nbdirs0
              srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + &
&               max5d0(nd0)
            END DO
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + max5
            IF (0.0_R8 .GT. t0) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  min4dd(nd0, nd) = t0dd(nd0, nd)
                END DO
                min4d(nd) = t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                min4d0(nd0) = t0d0(nd0)
              END DO
              min4 = t0
            ELSE
              min4 = 0.0_R8
              min4d = 0.d0
              min4dd = 0.D0
              min4d0 = 0.D0
            END IF
            temp11 = min4/pl%te(icv1)
            DO nd0=1,nbdirs0
              temp5d(nd0) = (min4d0(nd0)-temp11*pld0%te(nd0, icv1))/pl%&
&               te(icv1)
            END DO
            temp5 = temp11
            DO nd=1,nbdirs
              temp11 = (min4d(nd)-temp5*pld%te(nd, icv1))/pl%te(icv1)
              DO nd0=1,nbdirs0
                srwdd%she0(nd0, nd, icv1, 1) = srwdd%she0(nd0, nd, icv1&
&                 , 1) + (min4dd(nd0, nd)-pld%te(nd, icv1)*temp5d(nd0)-&
&                 temp5*pldd%te(nd0, nd, icv1)-temp11*pld0%te(nd0, icv1)&
&                 )/pl%te(icv1)
              END DO
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + temp11
            END DO
            DO nd0=1,nbdirs0
              srwd0%she0(nd0, icv1, 1) = srwd0%she0(nd0, icv1, 1) + &
&               temp5d(nd0)
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) + temp5
          END IF
        END DO
      ELSE IF (bcene_15_style .EQ. 1) THEN
!wdk    Todo: corrections for BCCON.ne.14
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&         'BCENE = 15 (style = 1) : with GAMMAE = ', gammae, &
&         ' and ENEPAR(IB,1) = ', enepar(ib, 1), ' (def = 0), on ', &
&         bcchar(ib), boundary_location(ib)
          csdd = 0.D0
          max6dd = 0.D0
          min6dd = 0.D0
          y2dd = 0.D0
          vtedd = 0.D0
          arg12dd = 0.D0
          t0dd = 0.D0
          result20dd = 0.D0
          arg13dd = 0.D0
          min5dd = 0.D0
        ELSE
          csdd = 0.D0
          max6dd = 0.D0
          min6dd = 0.D0
          y2dd = 0.D0
          vtedd = 0.D0
          arg12dd = 0.D0
          t0dd = 0.D0
          result20dd = 0.D0
          arg13dd = 0.D0
          min5dd = 0.D0
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg13 = pl%te(icv1)/me
          temp11 = SQRT(arg13)
          DO nd0=1,nbdirs0
            arg13d0(nd0) = pld0%te(nd0, icv1)/me
            IF (arg13 .EQ. 0.D0) THEN
              temp5d(nd0) = 0.D0
            ELSE
              temp5d(nd0) = arg13d0(nd0)/(2.0*temp11)
            END IF
          END DO
          temp5 = temp11
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              arg13dd(nd0, nd) = pldd%te(nd0, nd, icv1)/me
            END DO
            arg13d(nd) = pld%te(nd, icv1)/me
            IF (arg13 .EQ. 0.d0) THEN
              DO nd0=1,nbdirs0
                vtedd(nd0, nd) = 0.D0
              END DO
              vted(nd) = 0.d0
            ELSE
              temp11 = arg13d(nd)/(2.0*temp5)
              DO nd0=1,nbdirs0
                vtedd(nd0, nd) = (arg13dd(nd0, nd)-temp11*2.0*temp5d(nd0&
&                 ))/(2.0*temp5)
              END DO
              vted(nd) = temp11
            END IF
          END DO
          DO nd0=1,nbdirs0
            vted0(nd0) = temp5d(nd0)
          END DO
          vte = temp5
          IF (geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3) .GE. &
&             0.) THEN
            wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          ELSE
            wrk = -(geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)&
&             )
          END IF
          IF (wrk .LT. geo%qalfmin) THEN
            IF (geo%fcs(ifc) .GE. 0.) THEN
              abs0 = geo%fcs(ifc)
            ELSE
              abs0 = -geo%fcs(ifc)
            END IF
            s1 = abs0*geo%qalfmax
          ELSE IF (geo%fcpbs(ifc) .GE. 0.) THEN
            s1 = geo%fcpbs(ifc)
          ELSE
            s1 = -geo%fcpbs(ifc)
          END IF
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t0dd(nd0, nd) = dvdd%ne(nd0, nd, icv1)
            END DO
            t0d(nd) = dvd%ne(nd, icv1)
          END DO
          DO nd0=1,nbdirs0
            t0d0(nd0) = dvd0%ne(nd0, icv1)
          END DO
          t0 = dv%ne(icv1)
          t1 = 0.0_R8
          t1d = 0.d0
          t1d0 = 0.D0
          t1dd = 0.D0
          DO is=0,ns-1
            IF (.NOT.is_neutral(is) .AND. conpar(is, ib, 2) .GT. 0.0_R8&
&           ) THEN
              temp11 = pl%na(icv1, is)/conpar(is, ib, 2)
              DO nd0=1,nbdirs0
                temp5d(nd0) = (pld0%na(nd0, icv1, is)-temp11*conpard0(&
&                 nd0, is, ib, 2))/conpar(is, ib, 2)
                temp4d(nd0) = rt%rza(icv1, is)*cod0%dna0(nd0, icv1, is) &
&                 + co%dna0(icv1, is)*rtd0%rza(nd0, icv1, is)
              END DO
              temp5 = temp11
              temp4 = co%dna0(icv1, is)*rt%rza(icv1, is)
              DO nd=1,nbdirs
                temp11 = rt%rza(icv1, is)*cod%dna0(nd, icv1, is) + co%&
&                 dna0(icv1, is)*rtd%rza(nd, icv1, is)
                temp10 = temp4/conpar(is, ib, 2)
                temp9 = pld%na(nd, icv1, is) - temp5*conpard(nd, is, ib&
&                 , 2)
                DO nd0=1,nbdirs0
                  t1dd(nd0, nd) = t1dd(nd0, nd) + temp11*temp5d(nd0) + &
&                   temp5*(cod%dna0(nd, icv1, is)*rtd0%rza(nd0, icv1, is&
&                   )+rt%rza(icv1, is)*codd%dna0(nd0, nd, icv1, is)+rtd%&
&                   rza(nd, icv1, is)*cod0%dna0(nd0, icv1, is)+co%dna0(&
&                   icv1, is)*rtdd%rza(nd0, nd, icv1, is)) + temp10*(&
&                   pldd%na(nd0, nd, icv1, is)-conpard(nd, is, ib, 2)*&
&                   temp5d(nd0)-temp5*conpardd(nd0, nd, is, ib, 2)) + &
&                   temp9*(temp4d(nd0)-temp10*conpard0(nd0, is, ib, 2))/&
&                   conpar(is, ib, 2)
                END DO
                t1d(nd) = t1d(nd) + temp5*temp11 + temp9*temp10
              END DO
              DO nd0=1,nbdirs0
                t1d0(nd0) = t1d0(nd0) + temp5*temp4d(nd0) + temp4*temp5d&
&                 (nd0)
              END DO
              t1 = t1 + temp4*temp5
            END IF
          END DO
          IF (-50.0_R8 .LT. -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)&
&             )) THEN
            temp11 = (pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)
            DO nd0=1,nbdirs0
              temp5d(nd0) = (pld0%po(nd0, icv1)-potpard0(nd0, ib, 2)-&
&               temp11*pld0%te(nd0, icv1))/pl%te(icv1)
            END DO
            temp5 = temp11
            DO nd=1,nbdirs
              temp11 = (pld%po(nd, icv1)-potpard(nd, ib, 2)-temp5*pld%te&
&               (nd, icv1))/pl%te(icv1)
              DO nd0=1,nbdirs0
                y2dd(nd0, nd) = -(qe*(pldd%po(nd0, nd, icv1)-potpardd(&
&                 nd0, nd, ib, 2)-pld%te(nd, icv1)*temp5d(nd0)-temp5*&
&                 pldd%te(nd0, nd, icv1)-temp11*pld0%te(nd0, icv1))/pl%&
&                 te(icv1))
              END DO
              y2d(nd) = -(qe*temp11)
            END DO
            DO nd0=1,nbdirs0
              y2d0(nd0) = -(qe*temp5d(nd0))
            END DO
            y2 = -(qe*temp5)
          ELSE
            y2 = -50.0_R8
            y2d = 0.d0
            y2d0 = 0.D0
            y2dd = 0.D0
          END IF
          IF (0.0_R8 .GT. y2) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                min5dd(nd0, nd) = y2dd(nd0, nd)
              END DO
              min5d(nd) = y2d(nd)
            END DO
            DO nd0=1,nbdirs0
              min5d0(nd0) = y2d0(nd0)
            END DO
            min5 = y2
          ELSE
            min5 = 0.0_R8
            min5d = 0.d0
            min5d0 = 0.D0
            min5dd = 0.D0
          END IF
!lkw 31.03.2023
          arg13 = 1.0_R8/(2.0_R8*pi)
          result10 = SQRT(arg13)
          CALL EXPU2_DV_DV(min5, min5d0, min5d, min5dd, result20, &
&                    result20d0, result20d, result20dd, nbdirs, nbdirs0)
          DO nd=1,nbdirs
            temp8 = vte*t0d(nd) + t0*vted(nd)
            DO nd0=1,nbdirs0
              t0dd(nd0, nd) = s1*result10*(temp8*result20d0(nd0)+&
&               result20*(t0d(nd)*vted0(nd0)+vte*t0dd(nd0, nd)+vted(nd)*&
&               t0d0(nd0)+t0*vtedd(nd0, nd))+result20d(nd)*(vte*t0d0(nd0&
&               )+t0*vted0(nd0))+t0*vte*result20dd(nd0, nd))
              t1dd(nd0, nd) = geo%fcs(ifc)*t1dd(nd0, nd)
            END DO
            t0d(nd) = s1*result10*(result20*temp8+t0*vte*result20d(nd))
            t1d(nd) = geo%fcs(ifc)*t1d(nd)
          END DO
          DO nd0=1,nbdirs0
            t0d0(nd0) = s1*result10*(result20*(vte*t0d0(nd0)+t0*vted0(&
&             nd0))+t0*vte*result20d0(nd0))
            t1d0(nd0) = geo%fcs(ifc)*t1d0(nd0)
          END DO
          t0 = s1*t0*result10*vte*result20
          t1 = t1*geo%fcs(ifc)
          IF (switch%pot_eq .EQ. 1) THEN
            DO nd0=1,nbdirs0
!wdk to check: correct 2nd term for gammae?
              temp2d(nd0) = enepard0(nd0, ib, 1)
!lkw 31.03.2023
!wdk to check: correct 2nd term for gammae?
              temp5d(nd0) = (1.0_R8-gammae)*qe*(pld0%po(nd0, icv1)-&
&               potpard0(nd0, ib, 2)) - switch%stab_coeff_sheath_te*pld0&
&               %te(nd0, icv1)
              temp4d(nd0) = pld0%po(nd0, icv1) - potpard0(nd0, ib, 2)
            END DO
            temp2 = gammae + switch%stab_coeff_sheath_te + enepar(ib, 1)&
&             + 1.0_R8
            temp5 = (-gammae+1.0_R8)*qe*(pl%po(icv1)-potpar(ib, 2)) - &
&             switch%stab_coeff_sheath_te*pl%te(icv1)
            temp4 = pl%po(icv1) - potpar(ib, 2)
            DO nd=1,nbdirs
              temp11 = (-gammae+1.0_R8)*qe*(pld%po(nd, icv1)-potpard(nd&
&               , ib, 2)) - switch%stab_coeff_sheath_te*pld%te(nd, icv1)
              temp10 = pld%po(nd, icv1) - potpard(nd, ib, 2)
              DO nd0=1,nbdirs0
                srwdd%she0(nd0, nd, icv1, 1) = srwdd%she0(nd0, nd, icv1&
&                 , 1) - enepard(nd, ib, 1)*t0d0(nd0) - t0*enepardd(nd0&
&                 , nd, ib, 1) - t0d(nd)*temp2d(nd0) - temp2*t0dd(nd0, &
&                 nd) - fac_he_anom_bc*(enepard(nd, ib, 2)*t1d0(nd0)+t1*&
&                 enepardd(nd0, nd, ib, 2)+t1d(nd)*enepard0(nd0, ib, 2)+&
&                 enepar(ib, 2)*t1dd(nd0, nd))
                srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1&
&                 , 0) - temp11*t0d0(nd0) - t0*((1.0_R8-gammae)*qe*(pldd&
&                 %po(nd0, nd, icv1)-potpardd(nd0, nd, ib, 2))-switch%&
&                 stab_coeff_sheath_te*pldd%te(nd0, nd, icv1)) - t0d(nd)&
&                 *temp5d(nd0) - temp5*t0dd(nd0, nd) - qe*(temp10*t1d0(&
&                 nd0)+t1*(pldd%po(nd0, nd, icv1)-potpardd(nd0, nd, ib, &
&                 2))+t1d(nd)*temp4d(nd0)+temp4*t1dd(nd0, nd))
              END DO
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) - t0*&
&               enepard(nd, ib, 1) - temp2*t0d(nd) - fac_he_anom_bc*(t1*&
&               enepard(nd, ib, 2)+enepar(ib, 2)*t1d(nd))
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) - t0*&
&               temp11 - temp5*t0d(nd) - qe*(t1*temp10+temp4*t1d(nd))
            END DO
            DO nd0=1,nbdirs0
              srwd0%she0(nd0, icv1, 1) = srwd0%she0(nd0, icv1, 1) - t0*&
&               temp2d(nd0) - temp2*t0d0(nd0) - fac_he_anom_bc*(t1*&
&               enepard0(nd0, ib, 2)+enepar(ib, 2)*t1d0(nd0))
              srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) - t0*&
&               temp5d(nd0) - temp5*t0d0(nd0) - qe*(t1*temp4d(nd0)+temp4&
&               *t1d0(nd0))
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - temp2*t0 - &
&             fac_he_anom_bc*(enepar(ib, 2)*t1)
            srw%she0(icv1, 0) = srw%she0(icv1, 0) - temp5*t0 - qe*(temp4&
&             *t1)
            IF (switch%b2nppo_restr_po .NE. 0.0_R8 .AND. srw%she0(icv1, &
&               0) + srw%she0(icv1, 1)*pl%te(icv1) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  srwdd%she0(nd0, nd, icv1, :) = 0.D0
                END DO
                srwd%she0(nd, icv1, :) = 0.d0
              END DO
              DO nd0=1,nbdirs0
                srwd0%she0(nd0, icv1, :) = 0.D0
              END DO
              srw%she0(icv1, :) = 0.0_R8
            END IF
          ELSE
            temp8 = pz(icv1)/rz(icv1)
            DO nd0=1,nbdirs0
              temp2d(nd0) = (pzd0(nd0, icv1)-temp8*rzd0(nd0, icv1))/rz(&
&               icv1)
            END DO
            temp2 = temp8
            DO nd=1,nbdirs
              temp8 = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
              DO nd0=1,nbdirs0
                arg12dd(nd0, nd) = (pzdd(nd0, nd, icv1)-rzd(nd, icv1)*&
&                 temp2d(nd0)-temp2*rzdd(nd0, nd, icv1)-temp8*rzd0(nd0, &
&                 icv1))/rz(icv1)
              END DO
              arg12d(nd) = temp8
            END DO
            arg12 = temp2
            temp8 = SQRT(arg12)
            DO nd0=1,nbdirs0
              arg12d0(nd0) = temp2d(nd0)
              IF (arg12 .EQ. 0.D0) THEN
                temp2d(nd0) = 0.D0
              ELSE
                temp2d(nd0) = arg12d0(nd0)/(2.0*temp8)
              END IF
            END DO
            temp2 = temp8
            DO nd=1,nbdirs
              IF (arg12 .EQ. 0.d0) THEN
                DO nd0=1,nbdirs0
                  csdd(nd0, nd) = 0.D0
                END DO
                csd(nd) = 0.d0
              ELSE
                temp8 = arg12d(nd)/(2.0*temp2)
                DO nd0=1,nbdirs0
                  csdd(nd0, nd) = (arg12dd(nd0, nd)-temp8*2.0*temp2d(nd0&
&                   ))/(2.0*temp2)
                END DO
                csd(nd) = temp8
              END IF
            END DO
            cs = temp2
            DO nd0=1,nbdirs0
              csd0(nd0) = temp2d(nd0)
!srv 11.03.09 {
!wdk to check: correct for gammae?
              temp2d(nd0) = enepard0(nd0, ib, 1)
              temp5d(nd0) = cs*dvd0%ne(nd0, icv1) + dv%ne(icv1)*csd0(nd0&
&               )
              temp1d(nd0) = fac_he_anom_bc*enepard0(nd0, ib, 2)
            END DO
            temp2 = gammae + (-gammae+1.0_R8)*switch%delpo + enepar(ib, &
&             1) + 1.0_R8
            temp5 = dv%ne(icv1)*cs
            temp1 = switch%delpo + fac_he_anom_bc*enepar(ib, 2)
            DO nd=1,nbdirs
              temp8 = cs*dvd%ne(nd, icv1) + dv%ne(icv1)*csd(nd)
              DO nd0=1,nbdirs0
                srwdd%she0(nd0, nd, icv1, 1) = srwdd%she0(nd0, nd, icv1&
&                 , 1) - s1*(temp8*temp2d(nd0)+temp2*(dvd%ne(nd, icv1)*&
&                 csd0(nd0)+cs*dvdd%ne(nd0, nd, icv1)+csd(nd)*dvd0%ne(&
&                 nd0, icv1)+dv%ne(icv1)*csdd(nd0, nd))+enepard(nd, ib, &
&                 1)*temp5d(nd0)+temp5*enepardd(nd0, nd, ib, 1)) - &
&                 fac_he_anom_bc*(enepard(nd, ib, 2)*t1d0(nd0)+t1*&
&                 enepardd(nd0, nd, ib, 2)) - t1d(nd)*temp1d(nd0) - &
&                 temp1*t1dd(nd0, nd)
              END DO
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) - s1*(&
&               temp2*temp8+temp5*enepard(nd, ib, 1)) - fac_he_anom_bc*(&
&               t1*enepard(nd, ib, 2)) - temp1*t1d(nd)
            END DO
            DO nd0=1,nbdirs0
              srwd0%she0(nd0, icv1, 1) = srwd0%she0(nd0, icv1, 1) - s1*(&
&               temp2*temp5d(nd0)+temp5*temp2d(nd0)) - t1*temp1d(nd0) - &
&               temp1*t1d0(nd0)
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - s1*(temp5*temp2) - &
&             temp1*t1
          END IF
          IF (switch%mdf_fhe .NE. 0) THEN
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1&
&                 , 0) + temp2*(dvdd%fhepsch(nd0, nd, ifc, 0)+dvdd%&
&                 fhepsch(nd0, nd, ifc, 1))
              END DO
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + temp2*(&
&               dvd%fhepsch(nd, ifc, 0)+dvd%fhepsch(nd, ifc, 1))
            END DO
            temp5 = pl%te(icv1) + pl%te(icv2)
            temp4 = dv%ne(icv1) + dv%ne(icv2)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + &
&               temp2*(dvd0%fhepsch(nd0, ifc, 0)+dvd0%fhepsch(nd0, ifc, &
&               1))
              temp5d(nd0) = pld0%te(nd0, icv1) + pld0%te(nd0, icv2)
              temp4d(nd0) = dvd0%ne(nd0, icv1) + dvd0%ne(nd0, icv2)
              temp3d(nd0) = temp5*temp4d(nd0) + temp4*temp5d(nd0)
              tempd(nd0) = temp1*dvd0%vedia(nd0, ifc, 0) + temp0*dvd0%&
&               vedia(nd0, ifc, 1)
            END DO
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + temp2*(dv%fhepsch(&
&             ifc, 0)+dv%fhepsch(ifc, 1))
            temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp3 = temp4*temp5
            temp = temp1*dv%vedia(ifc, 0) + temp0*dv%vedia(ifc, 1)
            DO nd=1,nbdirs
              temp8 = temp1*dvd%vedia(nd, ifc, 0) + temp0*dvd%vedia(nd, &
&               ifc, 1)
              temp11 = pld%te(nd, icv1) + pld%te(nd, icv2)
              temp10 = dvd%ne(nd, icv1) + dvd%ne(nd, icv2)
              temp9 = temp5*temp10 + temp4*temp11
              DO nd0=1,nbdirs0
                t0dd(nd0, nd) = temp2*(temp8*temp3d(nd0)+temp3*(temp1*&
&                 dvdd%vedia(nd0, nd, ifc, 0)+temp0*dvdd%vedia(nd0, nd, &
&                 ifc, 1))+temp9*tempd(nd0)+temp*(temp10*temp5d(nd0)+&
&                 temp5*(dvdd%ne(nd0, nd, icv1)+dvdd%ne(nd0, nd, icv2))+&
&                 temp11*temp4d(nd0)+temp4*(pldd%te(nd0, nd, icv1)+pldd%&
&                 te(nd0, nd, icv2))))
              END DO
              t0d(nd) = temp2*(temp3*temp8+temp*temp9)
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = temp2*(temp3*tempd(nd0)+temp*temp3d(nd0))
            END DO
            t0 = temp2*(temp*temp3)
            IF (0.0_R8 .LT. t0) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max6dd(nd0, nd) = t0dd(nd0, nd)
                END DO
                max6d(nd) = t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                max6d0(nd0) = t0d0(nd0)
              END DO
              max6 = t0
            ELSE
              max6 = 0.0_R8
              max6d = 0.d0
              max6dd = 0.D0
              max6d0 = 0.D0
            END IF
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%she0(nd0, nd, icv1, 0) = srwdd%she0(nd0, nd, icv1&
&                 , 0) + max6dd(nd0, nd)
              END DO
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + max6d(nd&
&               )
            END DO
            DO nd0=1,nbdirs0
              srwd0%she0(nd0, icv1, 0) = srwd0%she0(nd0, icv1, 0) + &
&               max6d0(nd0)
            END DO
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + max6
            IF (0.0_R8 .GT. t0) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  min6dd(nd0, nd) = t0dd(nd0, nd)
                END DO
                min6d(nd) = t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                min6d0(nd0) = t0d0(nd0)
              END DO
              min6 = t0
            ELSE
              min6 = 0.0_R8
              min6d = 0.d0
              min6dd = 0.D0
              min6d0 = 0.D0
            END IF
            temp11 = min6/pl%te(icv1)
            DO nd0=1,nbdirs0
              temp5d(nd0) = (min6d0(nd0)-temp11*pld0%te(nd0, icv1))/pl%&
&               te(icv1)
            END DO
            temp5 = temp11
            DO nd=1,nbdirs
              temp11 = (min6d(nd)-temp5*pld%te(nd, icv1))/pl%te(icv1)
              DO nd0=1,nbdirs0
                srwdd%she0(nd0, nd, icv1, 1) = srwdd%she0(nd0, nd, icv1&
&                 , 1) + (min6dd(nd0, nd)-pld%te(nd, icv1)*temp5d(nd0)-&
&                 temp5*pldd%te(nd0, nd, icv1)-temp11*pld0%te(nd0, icv1)&
&                 )/pl%te(icv1)
              END DO
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + temp11
            END DO
            DO nd0=1,nbdirs0
              srwd0%she0(nd0, icv1, 1) = srwd0%she0(nd0, icv1, 1) + &
&               temp5d(nd0)
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) + temp5
          END IF
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=15, incorrect bcene_15_style value'&
&            )
      END IF
    CASE (16) 
!
! -- BCENE=16 -- Feedback boundary condition with constant temperature
!
!
      IF (switch%bcene_16_style .EQ. 0) THEN
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&         'BCENE = 16 (style = 0) : '//&
&         'electron temperature feedback by flux ', enepar(ib, 1), &
&         ' with ', enepar(ib, 2), ' on ', bcchar(ib), boundary_location&
&         (ib)
          CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        END IF
!       ..compute average temperature on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
        totfluxd = 0.d0
        t0d = 0.d0
        t1d = 0.d0
        totfluxd0 = 0.D0
        t0d0 = 0.D0
        t1d0 = 0.D0
        t0dd = 0.D0
        totfluxdd = 0.D0
        t1dd = 0.D0
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t0dd(nd0, nd) = t0dd(nd0, nd) + geo%fcs(ifc)*dvdd%ne(nd0, &
&               nd, icv1)
              t1dd(nd0, nd) = t1dd(nd0, nd) + geo%fcs(ifc)*(dvd%ne(nd, &
&               icv1)*pld0%te(nd0, icv1)+pl%te(icv1)*dvdd%ne(nd0, nd, &
&               icv1)+pld%te(nd, icv1)*dvd0%ne(nd0, icv1)+dv%ne(icv1)*&
&               pldd%te(nd0, nd, icv1))
              totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%fhe(&
&               nd0, nd, ifc, 0)+dvdd%fhe(nd0, nd, ifc, 1))
            END DO
            t0d(nd) = t0d(nd) + geo%fcs(ifc)*dvd%ne(nd, icv1)
            t1d(nd) = t1d(nd) + geo%fcs(ifc)*(pl%te(icv1)*dvd%ne(nd, &
&             icv1)+dv%ne(icv1)*pld%te(nd, icv1))
            totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhe(nd, ifc, 0)+dvd&
&             %fhe(nd, ifc, 1))
          END DO
          DO nd0=1,nbdirs0
            t0d0(nd0) = t0d0(nd0) + geo%fcs(ifc)*dvd0%ne(nd0, icv1)
            t1d0(nd0) = t1d0(nd0) + geo%fcs(ifc)*(pl%te(icv1)*dvd0%ne(&
&             nd0, icv1)+dv%ne(icv1)*pld0%te(nd0, icv1))
            totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fhe(nd0, ifc, &
&             0)+dvd0%fhe(nd0, ifc, 1))
          END DO
          t0 = t0 + geo%fcs(ifc)*dv%ne(icv1)
          t1 = t1 + geo%fcs(ifc)*dv%ne(icv1)*pl%te(icv1)
          totflux = totflux - temp2*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1))
        END DO
        totpardd = 0.D0
        DO nd=1,nbdirs
          temp8 = t1/t0
          temp12 = (t1d(nd)-t0d(nd)*temp8)/t0
          DO nd0=1,nbdirs0
            t1dd(nd0, nd) = (t1dd(nd0, nd)-temp8*t0dd(nd0, nd)-t0d(nd)*(&
&             t1d0(nd0)-temp8*t0d0(nd0))/t0-temp12*t0d0(nd0))/t0
            totpardd(nd0, nd) = fac_he_anom_bc*enepardd(nd0, nd, ib, 1)
          END DO
          t1d(nd) = temp12
          totpard(nd) = fac_he_anom_bc*enepard(nd, ib, 1)
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = (t1d0(nd0)-t1*t0d0(nd0)/t0)/t0
          totpard0(nd0) = fac_he_anom_bc*enepard0(nd0, ib, 1)
        END DO
        t1 = t1/t0
        totpar = fac_he_anom_bc*enepar(ib, 1)
        IF (enepar(ib, 2) .GT. 0.0_R8) THEN
          t3dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t3dd(nd0, nd) = enepardd(nd0, nd, ib, 2)
            END DO
            t3d(nd) = enepard(nd, ib, 2)
          END DO
          DO nd0=1,nbdirs0
            t3d0(nd0) = enepard0(nd0, ib, 2)
          END DO
          t3 = enepar(ib, 2)
        ELSE
          t3d = 0.d0
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        IF (enepar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          t3d = 0.d0
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        IF (totflux .GE. 0.) THEN
          x1dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              x1dd(nd0, nd) = totfluxdd(nd0, nd)
            END DO
            x1d(nd) = totfluxd(nd)
          END DO
          DO nd0=1,nbdirs0
            x1d0(nd0) = totfluxd0(nd0)
          END DO
          x1 = totflux
        ELSE
          x1dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              x1dd(nd0, nd) = -totfluxdd(nd0, nd)
            END DO
            x1d(nd) = -totfluxd(nd)
          END DO
          DO nd0=1,nbdirs0
            x1d0(nd0) = -totfluxd0(nd0)
          END DO
          x1 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          y3dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              y3dd(nd0, nd) = totpardd(nd0, nd)
            END DO
            y3d(nd) = totpard(nd)
          END DO
          DO nd0=1,nbdirs0
            y3d0(nd0) = totpard0(nd0)
          END DO
          y3 = totpar
        ELSE
          y3dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              y3dd(nd0, nd) = -totpardd(nd0, nd)
            END DO
            y3d(nd) = -totpard(nd)
          END DO
          DO nd0=1,nbdirs0
            y3d0(nd0) = -totpard0(nd0)
          END DO
          y3 = -totpar
        END IF
        IF (x1 .LT. y3) THEN
          max7dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              max7dd(nd0, nd) = y3dd(nd0, nd)
            END DO
            max7d(nd) = y3d(nd)
          END DO
          DO nd0=1,nbdirs0
            max7d0(nd0) = y3d0(nd0)
          END DO
          max7 = y3
        ELSE
          max7dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              max7dd(nd0, nd) = x1dd(nd0, nd)
            END DO
            max7d(nd) = x1d(nd)
          END DO
          DO nd0=1,nbdirs0
            max7d0(nd0) = x1d0(nd0)
          END DO
          max7 = x1
        END IF
        temp2 = t3/max7
        DO nd0=1,nbdirs0
          temp2d(nd0) = (t3d0(nd0)-t3*max7d0(nd0)/max7)/max7
          temp5d(nd0) = -(temp2*(totfluxd0(nd0)-totpard0(nd0))+(totflux-&
&           totpar)*temp2d(nd0))
        END DO
        temp5 = -((totflux-totpar)*temp2) + 1.0_R8
        t2dd = 0.D0
        DO nd=1,nbdirs
          temp12 = t3d(nd) - temp2*max7d(nd)
          temp8 = (totflux-totpar)/max7
          temp13 = temp2*(totfluxd(nd)-totpard(nd)) + temp8*temp12
          DO nd0=1,nbdirs0
            t2dd(nd0, nd) = t1d(nd)*temp5d(nd0) + temp5*t1dd(nd0, nd) - &
&             temp13*t1d0(nd0) - t1*((totfluxd(nd)-totpard(nd))*temp2d(&
&             nd0)+temp2*(totfluxdd(nd0, nd)-totpardd(nd0, nd))+temp12*(&
&             totfluxd0(nd0)-totpard0(nd0)-temp8*max7d0(nd0))/max7+temp8&
&             *(t3dd(nd0, nd)-max7d(nd)*temp2d(nd0)-temp2*max7dd(nd0, nd&
&             )))
          END DO
          t2d(nd) = temp5*t1d(nd) - t1*temp13
        END DO
        DO nd0=1,nbdirs0
          t2d0(nd0) = t1*temp5d(nd0) + temp5*t1d0(nd0)
        END DO
        t2 = temp5*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&             'bcene=16: curr_flux, desired_flux, old/new temperature, '&
&                                        , totflux, totpar, t1/qe, t2/qe
!       ..impose temperature
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%she0(nd0, nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2dd&
&               (nd0, nd)
              srwdd%she0(nd0, nd, icv1, 1) = 0.D0
            END DO
            srwd%she0(nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2d(nd)
            srwd%she0(nd, icv1, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2d0(nd0)
            srwd0%she0(nd0, icv1, 1) = 0.D0
          END DO
          srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE IF (switch%bcene_16_style .EQ. 1) THEN
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a)') 'BCENE = 16 (style = 1) : '//&
&         'Given integrated electron heat flux with constant Te'
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcene(ibw) .EQ. bcene(ib)) THEN
              WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location&
&             (ibw)
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCENE = 16 only applicable to core boundaries !')
              CALL XERTST(enepar(ibw, 1) .NE. 0.0_R8, &
&                   'faulty parameter enepar1')
            END IF
          END DO
        END IF
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bcene) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              senepar = 0.0_R8
              senepard = 0.d0
              senepard0 = 0.D0
              senepardd = 0.D0
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bcene(ibw) .EQ. bcene(ib)) THEN
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      senepardd(nd0, nd) = senepardd(nd0, nd) + enepardd&
&                       (nd0, nd, ibw, 1)
                    END DO
                    senepard(nd) = senepard(nd) + enepard(nd, ibw, 1)
                  END DO
                  DO nd0=1,nbdirs0
                    senepard0(nd0) = senepard0(nd0) + enepard0(nd0, ibw&
&                     , 1)
                  END DO
                  senepar = senepar + enepar(ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCENE=16: Summed value is ', senepar
            tes = 0.0_R8
            volsum = 0.0_R8
            tesd = 0.d0
            tesd0 = 0.D0
            tesdd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      tesdd(nd0, nd) = tesdd(nd0, nd) + geo%cvvol(icv)*&
&                       pldd%te(nd0, nd, icv)
                    END DO
                    tesd(nd) = tesd(nd) + geo%cvvol(icv)*pld%te(nd, icv)
                  END DO
                  DO nd0=1,nbdirs0
                    tesd0(nd0) = tesd0(nd0) + geo%cvvol(icv)*pld0%te(nd0&
&                     , icv)
                  END DO
                  tes = tes + pl%te(icv)*geo%cvvol(icv)
                  volsum = volsum + geo%cvvol(icv)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                tesdd(nd0, nd) = tesdd(nd0, nd)/volsum
              END DO
              tesd(nd) = tesd(nd)/volsum
            END DO
            DO nd0=1,nbdirs0
              tesd0(nd0) = tesd0(nd0)/volsum
            END DO
            tes = tes/volsum
            totflux = 0.0_R8
            totfluxd = 0.d0
            totfluxd0 = 0.D0
            totfluxdd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  IF (switch%mdf_fhe .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (dvdd%fhe_mdf(nd0, nd, ifc, 0)+dvdd%fhe_mdf(&
&                         nd0, nd, ifc, 1))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhe_mdf(&
&                       nd, ifc, 0)+dvd%fhe_mdf(nd, ifc, 1))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%&
&                       fhe_mdf(nd0, ifc, 0)+dvd0%fhe_mdf(nd0, ifc, 1))
                      temp1d(nd0) = geo%fcqalf(ifc, 0)*dvd0%vaecrb(nd0, &
&                       ifc, 0, ns-1) + geo%fcqalf(ifc, 1)*dvd0%vaecrb(&
&                       nd0, ifc, 1, ns-1)
                      temp5d(nd0) = dv%ne(icv)*pld0%te(nd0, icv) + pl%te&
&                       (icv)*dvd0%ne(nd0, icv)
                    END DO
                    totflux = totflux - temp2*(dv%fhe_mdf(ifc, 0)+dv%&
&                     fhe_mdf(ifc, 1))
                    temp2 = geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)
                    temp1 = geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, ns-1) +&
&                     geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, ns-1)
                    temp5 = pl%te(icv)*dv%ne(icv)
                    DO nd=1,nbdirs
                      temp11 = dv%ne(icv)*pld%te(nd, icv) + pl%te(icv)*&
&                       dvd%ne(nd, icv)
                      temp13 = geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, ifc, 0&
&                       , ns-1) + geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc&
&                       , 1, ns-1)
                      DO nd0=1,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (temp11*temp1d(nd0)+temp1*(pld%te(nd, icv)*&
&                         dvd0%ne(nd0, icv)+dv%ne(icv)*pldd%te(nd0, nd, &
&                         icv)+dvd%ne(nd, icv)*pld0%te(nd0, icv)+pl%te(&
&                         icv)*dvdd%ne(nd0, nd, icv))+temp13*temp5d(nd0)&
&                         +temp5*(geo%fcqalf(ifc, 0)*dvdd%vaecrb(nd0, nd&
&                         , ifc, 0, ns-1)+geo%fcqalf(ifc, 1)*dvdd%vaecrb&
&                         (nd0, nd, ifc, 1, ns-1)))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(temp1*temp11+&
&                       temp5*temp13)
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(temp1*&
&                       temp5d(nd0)+temp5*temp1d(nd0))
                    END DO
                    totflux = totflux - temp2*(temp5*temp1)
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (dvdd%fhe(nd0, nd, ifc, 0)+dvdd%fhe(nd0, nd, &
&                         ifc, 1))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhe(nd, &
&                       ifc, 0)+dvd%fhe(nd, ifc, 1))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fhe(&
&                       nd0, ifc, 0)+dvd0%fhe(nd0, ifc, 1))
                    END DO
                    totflux = totflux - temp2*(dv%fhe(ifc, 0)+dv%fhe(ifc&
&                     , 1))
                  END IF
                END DO
              END IF
            END DO
            IF (enepar(ib, 2) .GT. 0.0_R8) THEN
              t3dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t3dd(nd0, nd) = enepardd(nd0, nd, ib, 2)
                END DO
                t3d(nd) = enepard(nd, ib, 2)
              END DO
              DO nd0=1,nbdirs0
                t3d0(nd0) = enepard0(nd0, ib, 2)
              END DO
              t3 = enepar(ib, 2)
            ELSE
              t3d = 0.d0
              t3d0 = 0.D0
              t3dd = 0.D0
            END IF
            IF (enepar(ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref_te
              t3d = 0.d0
              t3d0 = 0.D0
              t3dd = 0.D0
            END IF
            IF (totflux .GE. 0.) THEN
              x2dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  x2dd(nd0, nd) = totfluxdd(nd0, nd)
                END DO
                x2d(nd) = totfluxd(nd)
              END DO
              DO nd0=1,nbdirs0
                x2d0(nd0) = totfluxd0(nd0)
              END DO
              x2 = totflux
            ELSE
              x2dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  x2dd(nd0, nd) = -totfluxdd(nd0, nd)
                END DO
                x2d(nd) = -totfluxd(nd)
              END DO
              DO nd0=1,nbdirs0
                x2d0(nd0) = -totfluxd0(nd0)
              END DO
              x2 = -totflux
            END IF
            IF (x2 .LT. senepar) THEN
              max8dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max8dd(nd0, nd) = senepardd(nd0, nd)
                END DO
                max8d(nd) = senepard(nd)
              END DO
              DO nd0=1,nbdirs0
                max8d0(nd0) = senepard0(nd0)
              END DO
              max8 = senepar
            ELSE
              max8dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max8dd(nd0, nd) = x2dd(nd0, nd)
                END DO
                max8d(nd) = x2d(nd)
              END DO
              DO nd0=1,nbdirs0
                max8d0(nd0) = x2d0(nd0)
              END DO
              max8 = x2
            END IF
            temp2 = t3/max8
            DO nd0=1,nbdirs0
              temp2d(nd0) = (t3d0(nd0)-t3*max8d0(nd0)/max8)/max8
              temp5d(nd0) = -(temp2*(totfluxd0(nd0)-senepard0(nd0))+(&
&               totflux-senepar)*temp2d(nd0))
            END DO
            temp5 = -((totflux-senepar)*temp2) + 1.0_R8
            DO nd=1,nbdirs
              temp13 = t3d(nd) - temp2*max8d(nd)
              temp12 = (totflux-senepar)/max8
              temp8 = temp2*(totfluxd(nd)-senepard(nd)) + temp12*temp13
              DO nd0=1,nbdirs0
                tesdd(nd0, nd) = tesd(nd)*temp5d(nd0) + temp5*tesdd(nd0&
&                 , nd) - temp8*tesd0(nd0) - tes*((totfluxd(nd)-senepard&
&                 (nd))*temp2d(nd0)+temp2*(totfluxdd(nd0, nd)-senepardd(&
&                 nd0, nd))+temp13*(totfluxd0(nd0)-senepard0(nd0)-temp12&
&                 *max8d0(nd0))/max8+temp12*(t3dd(nd0, nd)-max8d(nd)*&
&                 temp2d(nd0)-temp2*max8dd(nd0, nd)))
              END DO
              tesd(nd) = temp5*tesd(nd) - tes*temp8
            END DO
            DO nd0=1,nbdirs0
              tesd0(nd0) = temp5*tesd0(nd0) + tes*temp5d(nd0)
            END DO
            tes = tes*temp5
            WRITE(*, '(3(a,es14.7))') ' TES=', tes/ev, ' totflux=', &
&           totflux, ' SENEPAR=', senepar
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      srwdd%she0(nd0, nd, icv, 0) = vbig*ne00*geo%fcs(&
&                       ifc)*tesdd(nd0, nd)
                      srwdd%she0(nd0, nd, icv, 1) = 0.D0
                    END DO
                    srwd%she0(nd, icv, 0) = vbig*ne00*geo%fcs(ifc)*tesd(&
&                     nd)
                    srwd%she0(nd, icv, 1) = 0.d0
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%she0(nd0, icv, 0) = vbig*ne00*geo%fcs(ifc)*&
&                     tesd0(nd0)
                    srwd0%she0(nd0, icv, 1) = 0.D0
                  END DO
                  srw%she0(icv, 0) = vbig*ne00*tes*geo%fcs(ifc)
                  srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
                END DO
              END IF
            END DO
            once_bcene = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCENE=16, ONLY AVAILABLE FOR CORE!')
        END IF
      ELSE
        CALL XERRAB(' Incorrect style of boundary condition')
      END IF
    CASE (17) 
!
! -- BCENE=17 -- Feedback boundary condition with constant shared temperature
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 17 : shared temperature feedback by flux ', enepar(ib, &
&       1), ' with ', enepar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        CALL XERTST(enepar(ib, 2) .GT. 0, 'faulty parameter enepar2')
        CALL XERTST(bcene(ib) .EQ. bceni(ib), &
&             'both bcene and bceni should be set to 17')
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        CALL XERTST(enipar(ib, 2) .GT. 0, 'faulty parameter enipar2')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        totfluxd = 0.d0
        t0d = 0.d0
        weightd = 0.d0
        weightdd = 0.D0
        totfluxd0 = 0.D0
        result11dd = 0.D0
        t0d0 = 0.D0
        t0dd = 0.D0
        weightd0 = 0.D0
        totfluxdd = 0.D0
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%fhe(&
&               nd0, nd, ifc, 0)+dvdd%fhe(nd0, nd, ifc, 1)+dvdd%fhi(nd0&
&               , nd, ifc, 0)+dvdd%fhi(nd0, nd, ifc, 1))
            END DO
            totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhe(nd, ifc, 0)+dvd&
&             %fhe(nd, ifc, 1)+dvd%fhi(nd, ifc, 0)+dvd%fhi(nd, ifc, 1))
          END DO
          DO nd0=1,nbdirs0
            totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fhe(nd0, ifc, &
&             0)+dvd0%fhe(nd0, ifc, 1)+dvd0%fhi(nd0, ifc, 0)+dvd0%fhi(&
&             nd0, ifc, 1))
          END DO
          totflux = totflux - temp2*(st_ext%fhi(ifc, 0)+st_ext%fhi(ifc, &
&           1)+dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%fhi(ifc, 0)+dv%fhi(ifc, &
&           1))
          IF (bc_type16_kinetic_energy .EQ. 1) THEN
            DO is=0,ns-1
              CALL INTFACE_S_DV_DV(ifc, ncv, nfc, mpg%fccv, geo%fcvol, &
&                            dv%kinrgy(1, is), dvd0%kinrgy(:, 1, is), &
&                            dvd%kinrgy(:, 1, is), dvdd%kinrgy(:, :, 1, &
&                            is), result11, result11d0, result11d, &
&                            result11dd, nbdirs, nbdirs0)
              temp5 = (-switch%boris+1.0_R8)*mpg%bcfcor(mpg%bccvp(ib, 1)&
&               +ibc-1)
              DO nd0=1,nbdirs0
                temp4d(nd0) = dvd0%fna(nd0, ifc, 0, is) + dvd0%fna(nd0, &
&                 ifc, 1, is)
              END DO
              temp4 = dv%fna(ifc, 0, is) + dv%fna(ifc, 1, is)
              DO nd=1,nbdirs
                temp11 = dvd%fna(nd, ifc, 0, is) + dvd%fna(nd, ifc, 1, &
&                 is)
                DO nd0=1,nbdirs0
                  totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp5*(&
&                   temp11*result11d0(nd0)+result11*(dvdd%fna(nd0, nd, &
&                   ifc, 0, is)+dvdd%fna(nd0, nd, ifc, 1, is))+result11d&
&                   (nd)*temp4d(nd0)+temp4*result11dd(nd0, nd))
                END DO
                totfluxd(nd) = totfluxd(nd) - temp5*(result11*temp11+&
&                 temp4*result11d(nd))
              END DO
              DO nd0=1,nbdirs0
                totfluxd0(nd0) = totfluxd0(nd0) - temp5*(result11*temp4d&
&                 (nd0)+temp4*result11d0(nd0))
              END DO
              totflux = totflux - temp5*(temp4*result11)
            END DO
            DO is=0,st_ext%ns-1
              result11 = INTFACE_S(ifc, ncv, nfc, mpg%fccv, geo%fcvol, &
&               st_ext%ua(1, is))
              totflux = totflux - (1.0_R8-switch%boris)*mpg%bcfcor(mpg%&
&               bccvp(ib, 1)+ibc-1)*(st_ext%fa(ifc, 0, is)+st_ext%fa(ifc&
&               , 1, is))*0.5_R8*st_ext%am(is)*mp*result11**2
            END DO
          END IF
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t0dd(nd0, nd) = t0dd(nd0, nd) + geo%cvvol(icv)*(pld%te(nd&
&               , icv)*dvd0%ne(nd0, icv)+dv%ne(icv)*pldd%te(nd0, nd, icv&
&               )+dvd%ne(nd, icv)*pld0%te(nd0, icv)+pl%te(icv)*dvdd%ne(&
&               nd0, nd, icv)+pld%ti(nd, icv)*dvd0%ni(nd0, icv, 0)+dv%ni&
&               (icv, 0)*pldd%ti(nd0, nd, icv)+dvd%ni(nd, icv, 0)*pld0%&
&               ti(nd0, icv)+pl%ti(icv)*dvdd%ni(nd0, nd, icv, 0))
              weightdd(nd0, nd) = weightdd(nd0, nd) + geo%cvvol(icv)*(&
&               dvdd%ne(nd0, nd, icv)+dvdd%ni(nd0, nd, icv, 0))
            END DO
            t0d(nd) = t0d(nd) + geo%cvvol(icv)*(dv%ne(icv)*pld%te(nd, &
&             icv)+pl%te(icv)*dvd%ne(nd, icv)+dv%ni(icv, 0)*pld%ti(nd, &
&             icv)+pl%ti(icv)*dvd%ni(nd, icv, 0))
            weightd(nd) = weightd(nd) + geo%cvvol(icv)*(dvd%ne(nd, icv)+&
&             dvd%ni(nd, icv, 0))
          END DO
          DO nd0=1,nbdirs0
            t0d0(nd0) = t0d0(nd0) + geo%cvvol(icv)*(dv%ne(icv)*pld0%te(&
&             nd0, icv)+pl%te(icv)*dvd0%ne(nd0, icv)+dv%ni(icv, 0)*pld0%&
&             ti(nd0, icv)+pl%ti(icv)*dvd0%ni(nd0, icv, 0))
            weightd0(nd0) = weightd0(nd0) + geo%cvvol(icv)*(dvd0%ne(nd0&
&             , icv)+dvd0%ni(nd0, icv, 0))
          END DO
          t0 = t0 + (pl%te(icv)*dv%ne(icv)+pl%ti(icv)*dv%ni(icv, 0))*geo&
&           %cvvol(icv)
          weight = weight + (dv%ne(icv)+dv%ni(icv, 0))*geo%cvvol(icv)
        END DO
        DO nd=1,nbdirs
          temp13 = t0/weight
          temp12 = (t0d(nd)-weightd(nd)*temp13)/weight
          DO nd0=1,nbdirs0
            t0dd(nd0, nd) = (t0dd(nd0, nd)-temp13*weightdd(nd0, nd)-&
&             weightd(nd)*(t0d0(nd0)-temp13*weightd0(nd0))/weight-temp12&
&             *weightd0(nd0))/weight
          END DO
          t0d(nd) = temp12
        END DO
        DO nd0=1,nbdirs0
          t0d0(nd0) = (t0d0(nd0)-t0*weightd0(nd0)/weight)/weight
        END DO
        t0 = t0/weight
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        temp13 = enipar(ib, 2)/enipar(ib, 1)
        DO nd0=1,nbdirs0
          temp2d(nd0) = (enipard0(nd0, ib, 2)-temp13*enipard0(nd0, ib, 1&
&           ))/enipar(ib, 1)
          temp1d(nd0) = enepard0(nd0, ib, 1) + enipard0(nd0, ib, 1)
          temp6d(nd0) = enepard0(nd0, ib, 1) + enipard0(nd0, ib, 1)
        END DO
        temp2 = temp13
        temp1 = enepar(ib, 1) + enipar(ib, 1)
        temp13 = totflux/temp1
        DO nd0=1,nbdirs0
          temp0d(nd0) = temp13*enipard0(nd0, ib, 1) + enipar(ib, 1)*(&
&           totfluxd0(nd0)-temp13*temp1d(nd0))/temp1
        END DO
        temp0 = enipar(ib, 1)*temp13
        temp13 = enepar(ib, 2)/enepar(ib, 1)
        DO nd0=1,nbdirs0
          tempd(nd0) = (enepard0(nd0, ib, 2)-temp13*enepard0(nd0, ib, 1)&
&           )/enepar(ib, 1)
        END DO
        temp = temp13
        temp6 = enepar(ib, 1) + enipar(ib, 1)
        temp13 = totflux/temp6
        temp7 = enepar(ib, 1)*temp13
        DO nd0=1,nbdirs0
          temp7d(nd0) = temp13*enepard0(nd0, ib, 1) + enepar(ib, 1)*(&
&           totfluxd0(nd0)-temp13*temp6d(nd0))/temp6
          temp5d(nd0) = -(temp*(temp7d(nd0)-enepard0(nd0, ib, 1))) - (&
&           temp7-enepar(ib, 1))*tempd(nd0) - temp2*(temp0d(nd0)-&
&           enipard0(nd0, ib, 1)) - (temp0-enipar(ib, 1))*temp2d(nd0)
        END DO
        temp5 = -((temp0-enipar(ib, 1))*temp2) - (temp7-enepar(ib, 1))*&
&         temp + 1.0_R8
        t1dd = 0.D0
        DO nd=1,nbdirs
          temp13 = enepard(nd, ib, 2) - temp*enepard(nd, ib, 1)
          temp12 = (temp7-enepar(ib, 1))/enepar(ib, 1)
          temp8 = enepard(nd, ib, 1) + enipard(nd, ib, 1)
          temp14 = (enepar(ib, 1)*totfluxd(nd)+totflux*enepard(nd, ib, 1&
&           )-temp7*temp8)/temp6
          temp15 = enipard(nd, ib, 2) - temp2*enipard(nd, ib, 1)
          temp16 = (temp0-enipar(ib, 1))/enipar(ib, 1)
          temp17 = enepard(nd, ib, 1) + enipard(nd, ib, 1)
          temp18 = (enipar(ib, 1)*totfluxd(nd)+totflux*enipard(nd, ib, 1&
&           )-temp0*temp17)/temp1
          temp19 = -(temp2*(temp18-enipard(nd, ib, 1))) - temp16*temp15 &
&           - temp*(temp14-enepard(nd, ib, 1)) - temp12*temp13
          DO nd0=1,nbdirs0
            t1dd(nd0, nd) = temp19*t0d0(nd0) + t0*(-((temp18-enipard(nd&
&             , ib, 1))*temp2d(nd0))-temp2*((totfluxd(nd)*enipard0(nd0, &
&             ib, 1)+enipar(ib, 1)*totfluxdd(nd0, nd)+enipard(nd, ib, 1)&
&             *totfluxd0(nd0)+totflux*enipardd(nd0, nd, ib, 1)-temp17*&
&             temp0d(nd0)-temp0*(enepardd(nd0, nd, ib, 1)+enipardd(nd0, &
&             nd, ib, 1))-temp18*temp1d(nd0))/temp1-enipardd(nd0, nd, ib&
&             , 1))-temp15*(temp0d(nd0)-(temp16+1.0)*enipard0(nd0, ib, 1&
&             ))/enipar(ib, 1)-temp16*(enipardd(nd0, nd, ib, 2)-enipard(&
&             nd, ib, 1)*temp2d(nd0)-temp2*enipardd(nd0, nd, ib, 1))-(&
&             temp14-enepard(nd, ib, 1))*tempd(nd0)-temp*((totfluxd(nd)*&
&             enepard0(nd0, ib, 1)+enepar(ib, 1)*totfluxdd(nd0, nd)+&
&             enepard(nd, ib, 1)*totfluxd0(nd0)+totflux*enepardd(nd0, nd&
&             , ib, 1)-temp8*temp7d(nd0)-temp7*(enepardd(nd0, nd, ib, 1)&
&             +enipardd(nd0, nd, ib, 1))-temp14*temp6d(nd0))/temp6-&
&             enepardd(nd0, nd, ib, 1))-temp13*(temp7d(nd0)-(temp12+1.0)&
&             *enepard0(nd0, ib, 1))/enepar(ib, 1)-temp12*(enepardd(nd0&
&             , nd, ib, 2)-enepard(nd, ib, 1)*tempd(nd0)-temp*enepardd(&
&             nd0, nd, ib, 1))) + t0d(nd)*temp5d(nd0) + temp5*t0dd(nd0, &
&             nd)
          END DO
          t1d(nd) = t0*temp19 + temp5*t0d(nd)
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = t0*temp5d(nd0) + temp5*t0d0(nd0)
        END DO
        t1 = temp5*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New shared temp :', t0/qe&
&                                        , t1/qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%she0(nd0, nd, icv, 0) = vbig*ne00*geo%fcs(ifc)*t1dd(&
&               nd0, nd)
              srwdd%she0(nd0, nd, icv, 1) = 0.D0
              srwdd%shi0(nd0, nd, icv, 0) = vbig*ne00*geo%fcs(ifc)*t1dd(&
&               nd0, nd)
              srwdd%shi0(nd0, nd, icv, 1) = 0.D0
            END DO
            srwd%she0(nd, icv, 0) = vbig*ne00*geo%fcs(ifc)*t1d(nd)
            srwd%she0(nd, icv, 1) = 0.d0
            srwd%shi0(nd, icv, 0) = vbig*ne00*geo%fcs(ifc)*t1d(nd)
            srwd%shi0(nd, icv, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv, 0) = vbig*ne00*geo%fcs(ifc)*t1d0(nd0)
            srwd0%she0(nd0, icv, 1) = 0.D0
            srwd0%shi0(nd0, icv, 0) = vbig*ne00*geo%fcs(ifc)*t1d0(nd0)
            srwd0%shi0(nd0, icv, 1) = 0.D0
          END DO
          srw%she0(icv, 0) = vbig*ne00*t1*geo%fcs(ifc)
          srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
          srw%shi0(icv, 0) = vbig*ne00*t1*geo%fcs(ifc)
          srw%shi0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=17, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (18) 
!
! -- BCENE=18 -- FRACTIONAL DROP CONDITION (FOR EDGE2D COMPARISON)
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE = 18 : electron temperature fractional drop ', enepar(ib&
&       , 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .LT. 1.0_R8, &
&             'BCENE = 18, ENEPAR(,1) => 1')
        t1dd = 0.D0
      ELSE
        t1dd = 0.D0
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t1dd(nd0, nd) = (1.0_R8-enepar(ib, 1))*pldd%te(nd0, nd, icv2&
&             ) - pld%te(nd, icv2)*enepard0(nd0, ib, 1) - enepard(nd, ib&
&             , 1)*pld0%te(nd0, icv2) - pl%te(icv2)*enepardd(nd0, nd, ib&
&             , 1)
            srwdd%she0(nd0, nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1dd(&
&             nd0, nd)
            srwdd%she0(nd0, nd, icv1, 1) = 0.D0
          END DO
          t1d(nd) = (1.0_R8-enepar(ib, 1))*pld%te(nd, icv2) - pl%te(icv2&
&           )*enepard(nd, ib, 1)
          srwd%she0(nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1d(nd)
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = (1.0_R8-enepar(ib, 1))*pld0%te(nd0, icv2) - pl%te(&
&           icv2)*enepard0(nd0, ib, 1)
          srwd0%she0(nd0, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1d0(nd0)
          srwd0%she0(nd0, icv1, 1) = 0.D0
        END DO
        t1 = (1.0_R8-enepar(ib, 1))*pl%te(icv2)
        srw%she0(icv1, 0) = vbig*ne00*t1*geo%fcs(ifc)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (19) 
!
! -- BCENE=19 -- PRESCRIBE THE DECAY LENGTH FOR THE ELECTRON TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENE = 19 not adapted for WG')
!
! -- BCENE=20 -- Feedback boundary condition with constant temperature
!
    CASE (20) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 20 : electron temperature feedback by flux ', enepar(ib&
&       , 1), ' with ', enepar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        teave = 0.0_R8
        neave = 0.0_R8
        teaved = 0.d0
        totfluxd = 0.d0
        t0d = 0.d0
        weightd = 0.d0
        neaved = 0.d0
        teaved0 = 0.D0
        weightdd = 0.D0
        totfluxd0 = 0.D0
        t0d0 = 0.D0
        t0dd = 0.D0
        weightd0 = 0.D0
        neaved0 = 0.D0
        totfluxdd = 0.D0
        neavedd = 0.D0
        teavedd = 0.D0
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp7 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp7*(dvdd%fhe(&
&               nd0, nd, ifc, 0)+dvdd%fhe(nd0, nd, ifc, 1))
              t0dd(nd0, nd) = t0dd(nd0, nd) + geo%cvvol(icv1)*(pld%te(nd&
&               , icv1)*dvd0%ne(nd0, icv1)+dv%ne(icv1)*pldd%te(nd0, nd, &
&               icv1)+dvd%ne(nd, icv1)*pld0%te(nd0, icv1)+pl%te(icv1)*&
&               dvdd%ne(nd0, nd, icv1))
              weightdd(nd0, nd) = weightdd(nd0, nd) + geo%cvvol(icv1)*&
&               dvdd%ne(nd0, nd, icv1)
              teavedd(nd0, nd) = teavedd(nd0, nd) + geo%cvvol(icv2)*(pld&
&               %te(nd, icv2)*dvd0%ne(nd0, icv2)+dv%ne(icv2)*pldd%te(nd0&
&               , nd, icv2)+dvd%ne(nd, icv2)*pld0%te(nd0, icv2)+pl%te(&
&               icv2)*dvdd%ne(nd0, nd, icv2))
              neavedd(nd0, nd) = neavedd(nd0, nd) + geo%cvvol(icv2)*dvdd&
&               %ne(nd0, nd, icv2)
            END DO
            totfluxd(nd) = totfluxd(nd) - temp7*(dvd%fhe(nd, ifc, 0)+dvd&
&             %fhe(nd, ifc, 1))
            t0d(nd) = t0d(nd) + geo%cvvol(icv1)*(dv%ne(icv1)*pld%te(nd, &
&             icv1)+pl%te(icv1)*dvd%ne(nd, icv1))
            weightd(nd) = weightd(nd) + geo%cvvol(icv1)*dvd%ne(nd, icv1)
            teaved(nd) = teaved(nd) + geo%cvvol(icv2)*(dv%ne(icv2)*pld%&
&             te(nd, icv2)+pl%te(icv2)*dvd%ne(nd, icv2))
            neaved(nd) = neaved(nd) + geo%cvvol(icv2)*dvd%ne(nd, icv2)
          END DO
          DO nd0=1,nbdirs0
            totfluxd0(nd0) = totfluxd0(nd0) - temp7*(dvd0%fhe(nd0, ifc, &
&             0)+dvd0%fhe(nd0, ifc, 1))
            t0d0(nd0) = t0d0(nd0) + geo%cvvol(icv1)*(dv%ne(icv1)*pld0%te&
&             (nd0, icv1)+pl%te(icv1)*dvd0%ne(nd0, icv1))
            weightd0(nd0) = weightd0(nd0) + geo%cvvol(icv1)*dvd0%ne(nd0&
&             , icv1)
            teaved0(nd0) = teaved0(nd0) + geo%cvvol(icv2)*(dv%ne(icv2)*&
&             pld0%te(nd0, icv2)+pl%te(icv2)*dvd0%ne(nd0, icv2))
            neaved0(nd0) = neaved0(nd0) + geo%cvvol(icv2)*dvd0%ne(nd0, &
&             icv2)
          END DO
          totflux = totflux - temp7*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1))
          t0 = t0 + pl%te(icv1)*dv%ne(icv1)*geo%cvvol(icv1)
          weight = weight + dv%ne(icv1)*geo%cvvol(icv1)
          teave = teave + pl%te(icv2)*dv%ne(icv2)*geo%cvvol(icv2)
          neave = neave + dv%ne(icv2)*geo%cvvol(icv2)
        END DO
        DO nd=1,nbdirs
          temp19 = t0/weight
          temp18 = (t0d(nd)-weightd(nd)*temp19)/weight
          DO nd0=1,nbdirs0
            t0dd(nd0, nd) = (t0dd(nd0, nd)-temp19*weightdd(nd0, nd)-&
&             weightd(nd)*(t0d0(nd0)-temp19*weightd0(nd0))/weight-temp18&
&             *weightd0(nd0))/weight
          END DO
          t0d(nd) = temp18
          temp19 = teave/neave
          temp18 = (teaved(nd)-neaved(nd)*temp19)/neave
          DO nd0=1,nbdirs0
            teavedd(nd0, nd) = (teavedd(nd0, nd)-temp19*neavedd(nd0, nd)&
&             -neaved(nd)*(teaved0(nd0)-temp19*neaved0(nd0))/neave-&
&             temp18*neaved0(nd0))/neave
          END DO
          teaved(nd) = temp18
        END DO
        DO nd0=1,nbdirs0
          t0d0(nd0) = (t0d0(nd0)-t0*weightd0(nd0)/weight)/weight
          teaved0(nd0) = (teaved0(nd0)-teave*neaved0(nd0)/neave)/neave
        END DO
        t0 = t0/weight
        teave = teave/neave
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        IF (enepar(ib, 2) .GT. 0.0_R8) THEN
          t3dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t3dd(nd0, nd) = enepardd(nd0, nd, ib, 2)
            END DO
            t3d(nd) = enepard(nd, ib, 2)
          END DO
          DO nd0=1,nbdirs0
            t3d0(nd0) = enepard0(nd0, ib, 2)
          END DO
          t3 = enepar(ib, 2)
        ELSE
          t3d = 0.d0
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        IF (enepar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          t3d = 0.d0
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        temp19 = t3/enepar(ib, 1)
        temp7 = temp19
        DO nd0=1,nbdirs0
          temp7d(nd0) = (t3d0(nd0)-temp19*enepard0(nd0, ib, 1))/enepar(&
&           ib, 1)
          temp5d(nd0) = -(temp7*(totfluxd0(nd0)-enepard0(nd0, ib, 1))+(&
&           totflux-enepar(ib, 1))*temp7d(nd0))
        END DO
        temp5 = -((totflux-enepar(ib, 1))*temp7) + 1.0_R8
        t1dd = 0.D0
        DO nd=1,nbdirs
          temp19 = t3d(nd) - temp7*enepard(nd, ib, 1)
          temp18 = (totflux-enepar(ib, 1))/enepar(ib, 1)
          temp17 = totfluxd(nd) - enepard(nd, ib, 1)
          temp16 = temp7*temp17 + temp18*temp19
          DO nd0=1,nbdirs0
            t1dd(nd0, nd) = t0d(nd)*temp5d(nd0) + temp5*t0dd(nd0, nd) - &
&             temp16*t0d0(nd0) - t0*(temp17*temp7d(nd0)+temp7*(totfluxdd&
&             (nd0, nd)-enepardd(nd0, nd, ib, 1))+temp19*(totfluxd0(nd0)&
&             -(temp18+1.0)*enepard0(nd0, ib, 1))/enepar(ib, 1)+temp18*(&
&             t3dd(nd0, nd)-enepard(nd, ib, 1)*temp7d(nd0)-temp7*&
&             enepardd(nd0, nd, ib, 1)))
          END DO
          t1d(nd) = temp5*t0d(nd) - t0*temp16
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = t0*temp5d(nd0) + temp5*t0d0(nd0)
        END DO
        t1 = temp5*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New electron temp :', t0/&
&                                        qe, t1/qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp7 = vbig*ne00*geo%fcs(ifc)
          DO nd0=1,nbdirs0
            temp6d(nd0) = (t1d0(nd0)-t1*teaved0(nd0)/teave)/teave
          END DO
          temp6 = t1/teave
          DO nd=1,nbdirs
            temp19 = t1d(nd) - temp6*teaved(nd)
            temp11 = pl%te(icv2)/teave
            DO nd0=1,nbdirs0
              srwdd%she0(nd0, nd, icv1, 0) = temp7*(pld%te(nd, icv2)*&
&               temp6d(nd0)+temp6*pldd%te(nd0, nd, icv2)+temp19*(pld0%te&
&               (nd0, icv2)-temp11*teaved0(nd0))/teave+temp11*(t1dd(nd0&
&               , nd)-teaved(nd)*temp6d(nd0)-temp6*teavedd(nd0, nd)))
              srwdd%she0(nd0, nd, icv1, 1) = 0.D0
            END DO
            srwd%she0(nd, icv1, 0) = temp7*(temp6*pld%te(nd, icv2)+&
&             temp11*temp19)
            srwd%she0(nd, icv1, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 0) = temp7*(temp6*pld0%te(nd0, icv2)+&
&             pl%te(icv2)*temp6d(nd0))
            srwd0%she0(nd0, icv1, 1) = 0.D0
          END DO
          srw%she0(icv1, 0) = temp7*(pl%te(icv2)*temp6)
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=20, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (21) 
!
! -- BCENE=21 -- constant temperature scaled by temperature on the ring bc_type21_ref away
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 21 : fixed electron temperature '//&
&       '(modified by nearby ring) ', enepar(ib, 1), ' with ', enepar(ib&
&       , 2), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0.0_R8, &
&             'faulty parameter enepar1')
      END IF
      IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'N') .OR. bcchar(ib)&
&         .EQ. 'A') THEN
        teave = 0.0_R8
        neave = 0.0_R8
        teaved = 0.d0
        neaved = 0.d0
        teaved0 = 0.D0
        neaved0 = 0.D0
        neavedd = 0.D0
        teavedd = 0.D0
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              teavedd(nd0, nd) = teavedd(nd0, nd) + geo%cvvol(icv)*(pld%&
&               te(nd, icv)*dvd0%ne(nd0, icv)+dv%ne(icv)*pldd%te(nd0, nd&
&               , icv)+dvd%ne(nd, icv)*pld0%te(nd0, icv)+pl%te(icv)*dvdd&
&               %ne(nd0, nd, icv))
              neavedd(nd0, nd) = neavedd(nd0, nd) + geo%cvvol(icv)*dvdd%&
&               ne(nd0, nd, icv)
            END DO
            teaved(nd) = teaved(nd) + geo%cvvol(icv)*(dv%ne(icv)*pld%te(&
&             nd, icv)+pl%te(icv)*dvd%ne(nd, icv))
            neaved(nd) = neaved(nd) + geo%cvvol(icv)*dvd%ne(nd, icv)
          END DO
          DO nd0=1,nbdirs0
            teaved0(nd0) = teaved0(nd0) + geo%cvvol(icv)*(dv%ne(icv)*&
&             pld0%te(nd0, icv)+pl%te(icv)*dvd0%ne(nd0, icv))
            neaved0(nd0) = neaved0(nd0) + geo%cvvol(icv)*dvd0%ne(nd0, &
&             icv)
          END DO
          teave = teave + pl%te(icv)*dv%ne(icv)*geo%cvvol(icv)
          neave = neave + dv%ne(icv)*geo%cvvol(icv)
        END DO
        DO nd=1,nbdirs
          temp19 = teave/neave
          temp18 = (teaved(nd)-neaved(nd)*temp19)/neave
          DO nd0=1,nbdirs0
            teavedd(nd0, nd) = (teavedd(nd0, nd)-temp19*neavedd(nd0, nd)&
&             -neaved(nd)*(teaved0(nd0)-temp19*neaved0(nd0))/neave-&
&             temp18*neaved0(nd0))/neave
          END DO
          teaved(nd) = temp18
        END DO
        DO nd0=1,nbdirs0
          teaved0(nd0) = (teaved0(nd0)-teave*neaved0(nd0)/neave)/neave
        END DO
        teave = teave/neave
        IF (enepar(ib, 2) .GT. 0.0_R8) THEN
          t3dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t3dd(nd0, nd) = enepardd(nd0, nd, ib, 2)
            END DO
            t3d(nd) = enepard(nd, ib, 2)
          END DO
          DO nd0=1,nbdirs0
            t3d0(nd0) = enepard0(nd0, ib, 2)
          END DO
          t3 = enepar(ib, 2)
        ELSE
          t3d = 0.d0
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        IF (enepar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          t3d = 0.d0
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp7 = vbig*ne00*ev*geo%fcs(ifc)
          temp6 = t3/teave
          DO nd0=1,nbdirs0
            temp6d(nd0) = (t3d0(nd0)-t3*teaved0(nd0)/teave)/teave
            temp5d(nd0) = temp6*pld0%te(nd0, icv2) + pl%te(icv2)*temp6d(&
&             nd0) - t3d0(nd0)
          END DO
          temp5 = pl%te(icv2)*temp6 - t3 + 1.0_R8
          DO nd=1,nbdirs
            temp19 = t3d(nd) - temp6*teaved(nd)
            temp11 = pl%te(icv2)/teave
            temp18 = temp6*pld%te(nd, icv2) + temp11*temp19 - t3d(nd)
            DO nd0=1,nbdirs0
              srwdd%she0(nd0, nd, icv1, 0) = temp7*(enepard(nd, ib, 1)*&
&               temp5d(nd0)+temp5*enepardd(nd0, nd, ib, 1)+temp18*&
&               enepard0(nd0, ib, 1)+enepar(ib, 1)*(pld%te(nd, icv2)*&
&               temp6d(nd0)+temp6*pldd%te(nd0, nd, icv2)+temp19*(pld0%te&
&               (nd0, icv2)-temp11*teaved0(nd0))/teave+temp11*(t3dd(nd0&
&               , nd)-teaved(nd)*temp6d(nd0)-temp6*teavedd(nd0, nd))-&
&               t3dd(nd0, nd)))
              srwdd%she0(nd0, nd, icv1, 1) = 0.D0
            END DO
            srwd%she0(nd, icv1, 0) = temp7*(temp5*enepard(nd, ib, 1)+&
&             enepar(ib, 1)*temp18)
            srwd%she0(nd, icv1, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%she0(nd0, icv1, 0) = temp7*(temp5*enepard0(nd0, ib, 1)&
&             +enepar(ib, 1)*temp5d(nd0))
            srwd0%she0(nd0, icv1, 1) = 0.D0
          END DO
          srw%she0(icv1, 0) = temp7*(enepar(ib, 1)*temp5)
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=21, NOT AVAILABLE FOR W,E')
      END IF
    CASE (22) 
!
! -- BCENE=22 -- RADIAL LEAKAGE CONDITION FOR THE ELECTRON TEMPERATURE   !srv 23.07.10 {
!                SPECIFIES A TEMPERATURE GRADIENT SUCH THAT THE DIFFUSIVE
!                FLUX IS SET TO BE EQUIVALENT TO A LEAKAGE VELOCITY, IN
!                UNITS OF THE ELECTRON THERMAL VELOCITY
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE = 22 : with ENEPAR(IB,1)= ', enepar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        vtedd = 0.D0
        arg13dd = 0.D0
      ELSE
        vtedd = 0.D0
        arg13dd = 0.D0
      END IF
!wdk    Notes:
!wdk     * need correction for misaligned grids -> t1
!wdk     * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg13 = pl%te(icv1)/me
        temp11 = SQRT(arg13)
        t0 = geo%fcqalf(ifc, 1)
        t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&         fcqbet(ifc, 0)
        temp6 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1
        DO nd0=1,nbdirs0
          arg13d0(nd0) = pld0%te(nd0, icv1)/me
          IF (arg13 .EQ. 0.D0) THEN
            temp5d(nd0) = 0.D0
          ELSE
            temp5d(nd0) = arg13d0(nd0)/(2.0*temp11)
          END IF
          temp2d(nd0) = t0*pld0%te(nd0, icv2) - temp6*(pld0%te(nd0, mpg%&
&           fcvx(ifc, 2))-pld0%te(nd0, mpg%fcvx(ifc, 1)))
        END DO
        temp5 = temp11
        temp7 = vbig*ne00*ev
        temp2 = t0*pl%te(icv2) - temp6*(pl%te(mpg%fcvx(ifc, 2))-pl%te(&
&         mpg%fcvx(ifc, 1)))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            arg13dd(nd0, nd) = pldd%te(nd0, nd, icv1)/me
          END DO
          arg13d(nd) = pld%te(nd, icv1)/me
          IF (arg13 .EQ. 0.d0) THEN
            DO nd0=1,nbdirs0
              vtedd(nd0, nd) = 0.D0
            END DO
            vted(nd) = 0.d0
          ELSE
            temp11 = arg13d(nd)/(2.0*temp5)
            DO nd0=1,nbdirs0
              vtedd(nd0, nd) = (arg13dd(nd0, nd)-temp11*2.0*temp5d(nd0))&
&               /(2.0*temp5)
            END DO
            vted(nd) = temp11
          END IF
          temp19 = t0*pld%te(nd, icv2) - temp6*(pld%te(nd, mpg%fcvx(ifc&
&           , 2))-pld%te(nd, mpg%fcvx(ifc, 1)))
          DO nd0=1,nbdirs0
            srwdd%she0(nd0, nd, icv1, 0) = temp7*(cod%chce(nd, ifc, 1)*&
&             temp2d(nd0)+temp2*codd%chce(nd0, nd, ifc, 1)+temp19*cod0%&
&             chce(nd0, ifc, 1)+co%chce(ifc, 1)*(t0*pldd%te(nd0, nd, &
&             icv2)-temp6*(pldd%te(nd0, nd, mpg%fcvx(ifc, 2))-pldd%te(&
&             nd0, nd, mpg%fcvx(ifc, 1)))))
          END DO
          srwd%she0(nd, icv1, 0) = temp7*(temp2*cod%chce(nd, ifc, 1)+co%&
&           chce(ifc, 1)*temp19)
        END DO
        vte = temp5
        DO nd0=1,nbdirs0
          vted0(nd0) = temp5d(nd0)
          srwd0%she0(nd0, icv1, 0) = temp7*(temp2*cod0%chce(nd0, ifc, 1)&
&           +co%chce(ifc, 1)*temp2d(nd0))
          temp6d(nd0) = vte*enepard0(nd0, ib, 1) + enepar(ib, 1)*vted0(&
&           nd0)
        END DO
        srw%she0(icv1, 0) = temp7*(co%chce(ifc, 1)*temp2)
        temp7 = vbig*ne00*ev
        temp6 = enepar(ib, 1)*vte
        DO nd=1,nbdirs
          temp19 = vte*enepard(nd, ib, 1) + enepar(ib, 1)*vted(nd)
          DO nd0=1,nbdirs0
            srwdd%she0(nd0, nd, icv1, 1) = -(temp7*(t0*codd%chce(nd0, nd&
&             , ifc, 1)-geo%fcs(ifc)*(temp19*dvd0%ne(nd0, icv1)+dv%ne(&
&             icv1)*(enepard(nd, ib, 1)*vted0(nd0)+vte*enepardd(nd0, nd&
&             , ib, 1)+vted(nd)*enepard0(nd0, ib, 1)+enepar(ib, 1)*vtedd&
&             (nd0, nd))+dvd%ne(nd, icv1)*temp6d(nd0)+temp6*dvdd%ne(nd0&
&             , nd, icv1))))
          END DO
          srwd%she0(nd, icv1, 1) = -(temp7*(t0*cod%chce(nd, ifc, 1)-geo%&
&           fcs(ifc)*(dv%ne(icv1)*temp19+temp6*dvd%ne(nd, icv1))))
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv1, 1) = -(temp7*(t0*cod0%chce(nd0, ifc, 1)-&
&           geo%fcs(ifc)*(dv%ne(icv1)*temp6d(nd0)+temp6*dvd0%ne(nd0, &
&           icv1))))
        END DO
        srw%she0(icv1, 1) = -(temp7*(t0*co%chce(ifc, 1)-geo%fcs(ifc)*(&
&         temp6*dv%ne(icv1))))
      END DO
    CASE (23) 
!
!
! -- BCENE=23 -- Prescribe the value of the electron temperature, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENE=23 intended for core boundaries only!')
        END DO
        IF (switch%use_astra .NE. 0) THEN
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              enepardd(nd0, nd, ib, 1) = 0.D0
            END DO
            enepard(nd, ib, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            enepard0(nd0, ib, 1) = 0.D0
          END DO
          enepar(ib, 1) = teb_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified electron temp. + perturbation', enepar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 23, ENEPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t1d = 0.d0
      t1d0 = 0.D0
      t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%te(&
&                 nd0, nd, icv2)
              END DO
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%te(nd, icv2)
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%te(nd0, icv2)
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%te(icv2)
          END DO
        END IF
      END DO
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          t1dd(nd0, nd) = t1dd(nd0, nd)/t0
        END DO
        t1d(nd) = t1d(nd)/t0
      END DO
      DO nd0=1,nbdirs0
        t1d0(nd0) = t1d0(nd0)/t0
      END DO
      t1 = t1/t0
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp7 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%she0(nd0, nd, icv1, 0) = temp7*(pldd%te(nd0, nd, icv2)&
&             +ev*enepardd(nd0, nd, ib, 1)-t1dd(nd0, nd))
            srwdd%she0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%she0(nd, icv1, 0) = temp7*(pld%te(nd, icv2)+ev*enepard(nd&
&           , ib, 1)-t1d(nd))
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv1, 0) = temp7*(pld0%te(nd0, icv2)+ev*&
&           enepard0(nd0, ib, 1)-t1d0(nd0))
          srwd0%she0(nd0, icv1, 1) = 0.D0
        END DO
        srw%she0(icv1, 0) = temp7*(pl%te(icv2)+ev*enepar(ib, 1)-t1)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (24) 
!
! -- BCENE=24 -- Feedback on the total electron energy flux, by imposing a flux surface
!                averaged temperature, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENE=24 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified electron heat flux', &
&       enepar(ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 24, ENEPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
      totfluxd = 0.d0
      t1d = 0.d0
      t2d = 0.d0
      totpard = 0.d0
      totfluxd0 = 0.D0
      t2dd = 0.D0
      totpardd = 0.D0
      t1d0 = 0.D0
      t2d0 = 0.D0
      totpard0 = 0.D0
      totfluxdd = 0.D0
      t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bcene(ib0) .NE. 24) CALL XERRAB(&
&                                      'BCENE=24: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            temp7 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%te(&
&                 nd0, nd, icv1)
                t2dd(nd0, nd) = t2dd(nd0, nd) + geo%cvvol(icv2)*pldd%te(&
&                 nd0, nd, icv2)
                totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp7*(dvdd%&
&                 fhe(nd0, nd, ifc, 0)+dvdd%fhe(nd0, nd, ifc, 1))
              END DO
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%te(nd, icv1)
              t2d(nd) = t2d(nd) + geo%cvvol(icv2)*pld%te(nd, icv2)
              totfluxd(nd) = totfluxd(nd) - temp7*(dvd%fhe(nd, ifc, 0)+&
&               dvd%fhe(nd, ifc, 1))
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%te(nd0, icv1)
              t2d0(nd0) = t2d0(nd0) + geo%cvvol(icv2)*pld0%te(nd0, icv2)
              totfluxd0(nd0) = totfluxd0(nd0) - temp7*(dvd0%fhe(nd0, ifc&
&               , 0)+dvd0%fhe(nd0, ifc, 1))
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%te(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%te(icv2)
            totflux = totflux - temp7*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1))
          END DO
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              totpardd(nd0, nd) = totpardd(nd0, nd) + enepardd(nd0, nd, &
&               ib0, 1)
            END DO
            totpard(nd) = totpard(nd) + enepard(nd, ib0, 1)
          END DO
          DO nd0=1,nbdirs0
            totpard0(nd0) = totpard0(nd0) + enepard0(nd0, ib0, 1)
          END DO
          totpar = totpar + enepar(ib0, 1)
        END IF
      END DO
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          totpardd(nd0, nd) = fac_he_anom_bc*totpardd(nd0, nd)
          t1dd(nd0, nd) = t1dd(nd0, nd)/t0
          t2dd(nd0, nd) = t2dd(nd0, nd)/t0
        END DO
        totpard(nd) = fac_he_anom_bc*totpard(nd)
        t1d(nd) = t1d(nd)/t0
        t2d(nd) = t2d(nd)/t0
      END DO
      DO nd0=1,nbdirs0
        totpard0(nd0) = fac_he_anom_bc*totpard0(nd0)
        t1d0(nd0) = t1d0(nd0)/t0
        t2d0(nd0) = t2d0(nd0)/t0
      END DO
      totpar = fac_he_anom_bc*totpar
      t1 = t1/t0
      t2 = t2/t0
      IF (enepar(ib, 2) .GT. 0.0_R8) THEN
        t3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t3dd(nd0, nd) = enepardd(nd0, nd, ib, 2)
          END DO
          t3d(nd) = enepard(nd, ib, 2)
        END DO
        DO nd0=1,nbdirs0
          t3d0(nd0) = enepard0(nd0, ib, 2)
        END DO
        t3 = enepar(ib, 2)
      ELSE
        t3d = 0.d0
        t3d0 = 0.D0
        t3dd = 0.D0
      END IF
      IF (enepar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_te
        t3d = 0.d0
        t3d0 = 0.D0
        t3dd = 0.D0
      END IF
      IF (totflux .GE. 0.) THEN
        x3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x3dd(nd0, nd) = totfluxdd(nd0, nd)
          END DO
          x3d(nd) = totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x3d0(nd0) = totfluxd0(nd0)
        END DO
        x3 = totflux
      ELSE
        x3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x3dd(nd0, nd) = -totfluxdd(nd0, nd)
          END DO
          x3d(nd) = -totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x3d0(nd0) = -totfluxd0(nd0)
        END DO
        x3 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y4dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y4dd(nd0, nd) = totpardd(nd0, nd)
          END DO
          y4d(nd) = totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          y4d0(nd0) = totpard0(nd0)
        END DO
        y4 = totpar
      ELSE
        y4dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y4dd(nd0, nd) = -totpardd(nd0, nd)
          END DO
          y4d(nd) = -totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          y4d0(nd0) = -totpard0(nd0)
        END DO
        y4 = -totpar
      END IF
      IF (x3 .LT. y4) THEN
        max9dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            max9dd(nd0, nd) = y4dd(nd0, nd)
          END DO
          max9d(nd) = y4d(nd)
        END DO
        DO nd0=1,nbdirs0
          max9d0(nd0) = y4d0(nd0)
        END DO
        max9 = y4
      ELSE
        max9dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            max9dd(nd0, nd) = x3dd(nd0, nd)
          END DO
          max9d(nd) = x3d(nd)
        END DO
        DO nd0=1,nbdirs0
          max9d0(nd0) = x3d0(nd0)
        END DO
        max9 = x3
      END IF
      temp7 = t3/max9
      DO nd0=1,nbdirs0
        temp7d(nd0) = (t3d0(nd0)-t3*max9d0(nd0)/max9)/max9
        temp5d(nd0) = -(temp7*(totfluxd0(nd0)-totpard0(nd0))+(totflux-&
&         totpar)*temp7d(nd0))
      END DO
      temp5 = -((totflux-totpar)*temp7) + 1.0_R8
      t4dd = 0.D0
      DO nd=1,nbdirs
        temp19 = t3d(nd) - temp7*max9d(nd)
        temp18 = (totflux-totpar)/max9
        temp17 = temp7*(totfluxd(nd)-totpard(nd)) + temp18*temp19
        DO nd0=1,nbdirs0
          t4dd(nd0, nd) = t1d(nd)*temp5d(nd0) + temp5*t1dd(nd0, nd) - &
&           temp17*t1d0(nd0) - t1*((totfluxd(nd)-totpard(nd))*temp7d(nd0&
&           )+temp7*(totfluxdd(nd0, nd)-totpardd(nd0, nd))+temp19*(&
&           totfluxd0(nd0)-totpard0(nd0)-temp18*max9d0(nd0))/max9+temp18&
&           *(t3dd(nd0, nd)-max9d(nd)*temp7d(nd0)-temp7*max9dd(nd0, nd))&
&           )
        END DO
        t4d(nd) = temp5*t1d(nd) - t1*temp17
      END DO
      DO nd0=1,nbdirs0
        t4d0(nd0) = t1*temp5d(nd0) + temp5*t1d0(nd0)
      END DO
      t4 = temp5*t1
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp7 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%she0(nd0, nd, icv1, 0) = temp7*(pldd%te(nd0, nd, icv2)&
&             +t4dd(nd0, nd)-t2dd(nd0, nd))
            srwdd%she0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%she0(nd, icv1, 0) = temp7*(pld%te(nd, icv2)+t4d(nd)-t2d(&
&           nd))
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%she0(nd0, icv1, 0) = temp7*(pld0%te(nd0, icv2)+t4d0(nd0)&
&           -t2d0(nd0))
          srwd0%she0(nd0, icv1, 1) = 0.D0
        END DO
        srw%she0(icv1, 0) = temp7*(pl%te(icv2)+t4-t2)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcene(ib)
      CALL XERRAB('BCENE out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENE_DV_DV

!  Differentiation of b2stbc_phys_ene in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: enepar senepar *(srw.she0)
!                *(srw.shi0)
!   with respect to varying inputs: conpar enepar enipar potpar
!                senepar *(dv.fch_p) *(dv.fna) *(dv.fne) *(dv.fhe)
!                *(dv.fhe_mdf) *(dv.fhepsch) *(dv.fhi) *(dv.kinrgy)
!                *(dv.ne) *(dv.ni) *(dv.vaecrb) *(dv.vedia) *(dv.veecrb)
!                *(rt.rza) *(srw.she0) *(srw.shi0) *(srw.sna0)
!                *(co.chce) *(co.hce0) *(co.dna0) *(pl.na) *(pl.po)
!                *(pl.te) *(pl.ti) rz pz
!   Plus diff mem management of: dv.fch_p:in dv.fna:in dv.fne:in
!                dv.fhe:in dv.fhe_mdf:in dv.fhepsch:in dv.fhi:in
!                dv.kinrgy:in dv.ne:in dv.ni:in dv.vaecrb:in dv.vedia:in
!                dv.veecrb:in mpg.bcfcor:in geo.fcs:in geo.vxvol:in
!                st_ext.ua:in rt.rza:in srw.she0:in srw.shi0:in
!                srw.sna0:in co.chce:in co.hce0:in co.dna0:in pl.na:in
!                pl.po:in pl.te:in pl.ti:in
!
  SUBROUTINE B2STBC_PHYS_ENE_DV(ib, nbdirs)
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER :: ib, ibw, ibc, ibc0, ib0, is, ism
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, vte, s1, t0, t1, t2, t3, t4, neave, totpar, &
&   totflux, teave, weight, wrk
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd, vted, t0d, t1d, t2d, t3d&
&   , t4d, neaved, totpard, totfluxd, teaved, weightd
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(r8) :: y1
    REAL(r8), DIMENSION(nbdirsmax) :: y1d
    REAL(r8) :: y2
    REAL(r8), DIMENSION(nbdirsmax) :: y2d
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8) :: y3
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y3d
    REAL(kind=r8) :: x2
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x2d
    REAL(kind=r8) :: x3
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x3d
    REAL(kind=r8) :: y4
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y4d
    REAL(r8) :: max1
    REAL(r8), DIMENSION(nbdirsmax) :: max1d
    REAL(r8) :: min1
    REAL(r8), DIMENSION(nbdirsmax) :: min1d
    REAL(r8) :: max2
    REAL(r8), DIMENSION(nbdirsmax) :: max2d
    REAL(r8) :: min2
    REAL(r8), DIMENSION(nbdirsmax) :: min2d
    REAL(r8) :: max3
    REAL(r8), DIMENSION(nbdirsmax) :: max3d
    REAL(r8) :: max4
    REAL(r8), DIMENSION(nbdirsmax) :: max4d
    REAL(r8) :: min3
    REAL(r8), DIMENSION(nbdirsmax) :: min3d
    REAL(r8) :: max5
    REAL(r8), DIMENSION(nbdirsmax) :: max5d
    REAL(r8) :: min4
    REAL(r8), DIMENSION(nbdirsmax) :: min4d
    REAL(kind=r8) :: abs0
    REAL(r8) :: min5
    REAL(r8), DIMENSION(nbdirsmax) :: min5d
    REAL(r8) :: max6
    REAL(r8), DIMENSION(nbdirsmax) :: max6d
    REAL(r8) :: min6
    REAL(r8), DIMENSION(nbdirsmax) :: min6d
    REAL(kind=r8) :: max7
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max7d
    REAL(kind=r8) :: max8
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max8d
    REAL(kind=r8) :: max9
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max9d
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(r8) :: arg13
    REAL(r8), DIMENSION(nbdirsmax) :: arg13d
    REAL(r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result20d
    REAL(kind=r8) :: result11
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result11d
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(kind=r8) :: temp2
    REAL(r8) :: temp3
    REAL(r8) :: temp4
    REAL(r8) :: temp5
    REAL(kind=r8) :: temp6
    REAL(kind=r8) :: temp7
    INTEGER :: nbdirs
!
! -- BOUNDARY CONDITIONS FOR ELECTRON ENERGY EQUATION --
!
    SELECT CASE  (bcene(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCENE=1 -- PRESCRIBE THE VALUE OF THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (bcchar(ib) .EQ. 'S' .AND. switch%use_astra .NE. 0) THEN
!srv 14.06.12
          DO nd=1,nbdirs
            enepard(nd, ib, 1) = 0.d0
          END DO
          enepar(ib, 1) = teb_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  1 : specified electron temperature ', enepar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 1, ENEPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        temp = geo%fcs(ifc)*ev
        DO nd=1,nbdirs
          srwd%she0(nd, icv, 0) = temp*vbig*ne00*enepard(nd, ib, 1)
          srwd%she0(nd, icv, 1) = 0.d0
        END DO
        srw%she0(icv, 0) = vbig*ne00*enepar(ib, 1)*temp
        srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENE=2 -- PRESCRIBE THE GRADIENT OF THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE =  2 : electron temperature gradient '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        CALL INTVERTEX_S_DV_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%te&
&                            , pld%te, t1, t1d, nbdirs)
        CALL INTVERTEX_S_DV_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%te&
&                            , pld%te, t2, t2d, nbdirs)
        temp = vbig*ne00*geo%fcs(ifc)
        temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
        temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, &
&         2))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          srwd%she0(nd, icv1, 0) = temp*(temp0*geo%fcqgam(ifc, 0)*ev*&
&           enepard(nd, ib, 1)-temp1*temp2*(t2d(nd)-t1d(nd))/geo%fcht(&
&           ifc)+pld%te(nd, icv2))
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        srw%she0(icv1, 0) = temp*(temp0*(geo%fcqgam(ifc, 0)*(ev*enepar(&
&         ib, 1)))-temp1*(temp2*((t2-t1)/geo%fcht(ifc)))+pl%te(icv2))
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENE=3 -- SHEATH CONDITIONS, ELECTRON ENERGY TRANSMISSION
!
      CALL XERRAB('b2stbc_phys -- BCENE = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCENE = 15')
!
! -- BCENE=4 -- PRESCRIBE THE VALUE OF THE ELECTRON TEMPERATURE,
!                 WEAKLY A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  4 : weak electron temperature ', enepar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 4, ENEPAR(,1) !> 0')
        CALL XERTST(enepar(ib, 2) .GT. 0.0_R8, &
&             'BCENE = 4, ENEPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          srwd%she0(nd, icv, 0) = geo%fcs(ifc)*(enepar(ib, 1)*enepard(nd&
&           , ib, 2)+enepar(ib, 2)*enepard(nd, ib, 1))
          srwd%she0(nd, icv, 1) = -(geo%fcs(ifc)*enepard(nd, ib, 2)/ev)
        END DO
        srw%she0(icv, 0) = enepar(ib, 2)*geo%fcs(ifc)*enepar(ib, 1)
        srw%she0(icv, 1) = -(enepar(ib, 2)/ev*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCENE=5 -- PRESCRIBE THE ELECTRON ENERGY FLUX PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE =  5 : electron energy flux per area '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          srwd%she0(nd, icv, 0) = geo%fcs(ifc)*enepard(nd, ib, 1)
          srwd%she0(nd, icv, 1) = 0.d0
        END DO
        srw%she0(icv, 0) = enepar(ib, 1)*geo%fcs(ifc)
        srw%she0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCENE=6 -- PRESCRIBE THE TOTAL ELECTRON ENERGY FLUX FOR A
!                 CONSTANT ELECTRON TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENE = 6 not adapted for WG')
!
! -- BCENE=7 -- PRESCRIBE THE ELECTRON TEMPERATURE PROFILE
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') &
&       'BCENE = 7 : specified electron temperature on ', bcchar(ib), &
&       boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          srwd%she0(nd, icv1, 0) = 0.d0
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*bv_te(icv1)*ev
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCENE=8 -- PRESCRIBE THE TOTAL ELECTRON HEAT FLUX WITH CONSTANT
!                 FLUX DENSITY
!wdk BC not recommended for drifts!
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                      'Compile with -DASTRA option to couple to ASTRA!'&
&                                         )
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  8 : total electron energy flux ', enepar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
      END IF
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = fac_he_anom_bc*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%she0(nd, icv1, 0) = temp2*enepard(nd, ib, 1)/us
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        srw%she0(icv1, 0) = temp2*(enepar(ib, 1)/us)
        srw%she0(icv1, 1) = 0.0_R8
        IF (switch%mdf_fhe .NE. 0) THEN
!wdk Correction now involves vedia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_f = 0 option
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + temp2*(dvd&
&             %fhepsch(nd, ifc, 0)+dvd%fhepsch(nd, ifc, 1))
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + temp2*(dv%fhepsch(ifc&
&           , 0)+dv%fhepsch(ifc, 1))
          temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&           0.5_R8)
          temp3 = pl%te(icv1) + pl%te(icv2)
          temp4 = dv%ne(icv1) + dv%ne(icv2)
          temp5 = temp4*temp3
          temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
          temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
          temp = temp1*dv%vedia(ifc, 0) + temp0*dv%vedia(ifc, 1)
          DO nd=1,nbdirs
            t0d(nd) = temp2*(temp5*(temp1*dvd%vedia(nd, ifc, 0)+temp0*&
&             dvd%vedia(nd, ifc, 1))+temp*(temp3*(dvd%ne(nd, icv1)+dvd%&
&             ne(nd, icv2))+temp4*(pld%te(nd, icv1)+pld%te(nd, icv2))))
          END DO
          t0 = temp2*(temp*temp5)
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              max1d(nd) = t0d(nd)
            END DO
            max1 = t0
          ELSE
            max1 = 0.0_R8
            max1d = 0.d0
          END IF
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + max1d(nd)
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max1
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              min1d(nd) = t0d(nd)
            END DO
            min1 = t0
          ELSE
            min1 = 0.0_R8
            min1d = 0.d0
          END IF
          temp5 = min1/pl%te(icv1)
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + (min1d(nd)&
&             -temp5*pld%te(nd, icv1))/pl%te(icv1)
          END DO
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + temp5
        END IF
      END DO
    CASE (9) 
!
! -- BCENE=9 -- PRESCRIBE THE DECAY LENGTH FOR THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  9 : electron temperature decay length ', enepar(ib, 1)&
&       , ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0.0_R8, &
&             'BCENE = 9, ENEPAR(,1) = 0')
        ism = 0
        DO is=0,ns-1
          IF (bccon(is, ib) .NE. 9 .AND. (.NOT.is_neutral(is))) THEN
            ism = ism + 1
            WRITE(0, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCENE=9'
            WRITE(*, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCENE=9'
          END IF
          IF (bccon(is, ib) .EQ. 1) WRITE(0, *) &
&                      'Should use BCENE=19 in conjunction with BCCON=1'
          IF (ism .GT. 0) THEN
!srv 21.09.12
            WRITE(*, '(1x,a)') &
&           'Please ensure that this boundary condition '//&
&           'is consistent with the density boundary conditions'
          END IF
        END DO
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        sy = geo%fcs(ifc)
        temp5 = co%hce0(icv1)/enepar(ib, 1)
        DO nd=1,nbdirs
          srwd%she0(nd, icv1, 0) = 0.d0
          srwd%she0(nd, icv1, 1) = -(sy*(cod%hce0(nd, icv1)-temp5*&
&           enepard(nd, ib, 1))/enepar(ib, 1))
        END DO
        srw%she0(icv1, 0) = 0.0_R8
        srw%she0(icv1, 1) = -(sy*temp5)
        DO is=0,ns-1
          temp5 = rt%rza(icv1, is)*pl%te(icv1)
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + &
&             fac_he_anom*(srw%sna0(icv1, 0, is)*(pl%te(icv1)*rtd%rza(nd&
&             , icv1, is)+rt%rza(icv1, is)*pld%te(nd, icv1))+temp5*srwd%&
&             sna0(nd, icv1, 0, is))
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + fac_he_anom*(temp5*srw&
&           %sna0(icv1, 0, is))
          temp5 = rt%rza(icv1, is)*pl%na(icv1, is)
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + &
&             fac_he_anom*(temp5*srwd%sna0(nd, icv1, 1, is)+srw%sna0(&
&             icv1, 1, is)*(pl%na(icv1, is)*rtd%rza(nd, icv1, is)+rt%rza&
&             (icv1, is)*pld%na(nd, icv1, is)))
          END DO
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + fac_he_anom*(srw%sna0(&
&           icv1, 1, is)*temp5)
!! end species loop
        END DO
        IF (switch%mdf_fhe .NE. 0) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + temp2*(dvd&
&             %fhepsch(nd, ifc, 0)+dvd%fhepsch(nd, ifc, 1))
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + temp2*(dv%fhepsch(ifc&
&           , 0)+dv%fhepsch(ifc, 1))
          temp2 = 1.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&           0.5_R8)
          temp5 = pl%te(icv1) + pl%te(icv2)
          temp4 = dv%ne(icv1) + dv%ne(icv2)
          temp3 = temp4*temp5
          temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
          temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
          temp = temp1*dv%veecrb(ifc, 0) + temp0*dv%veecrb(ifc, 1)
          DO nd=1,nbdirs
            t0d(nd) = -(temp2*(temp3*(temp1*dvd%veecrb(nd, ifc, 0)+temp0&
&             *dvd%veecrb(nd, ifc, 1))+temp*(temp5*(dvd%ne(nd, icv1)+dvd&
&             %ne(nd, icv2))+temp4*(pld%te(nd, icv1)+pld%te(nd, icv2))))&
&             )
          END DO
          t0 = -(temp2*(temp*temp3))
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              max2d(nd) = t0d(nd)
            END DO
            max2 = t0
          ELSE
            max2 = 0.0_R8
            max2d = 0.d0
          END IF
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + max2d(nd)
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max2
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              min2d(nd) = t0d(nd)
            END DO
            min2 = t0
          ELSE
            min2 = 0.0_R8
            min2d = 0.d0
          END IF
          temp5 = min2/pl%te(icv1)
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + (min2d(nd)&
&             -temp5*pld%te(nd, icv1))/pl%te(icv1)
          END DO
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + temp5
        END IF
!! end loop over cells

      END DO
    CASE (10) 
!
! -- BCENE=10 -- Feedback option for core
!
      CALL XERRAB('b2stbc_phys -- BCENE = 10 not adapted for WG')
!
! -- BCENE=11 -- FROM B2STBC_SPB                                       !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
    CASE (11) 
      CALL XERRAB('b2stbc_phys -- BCENE = 11 not adapted for WG')
!
! -- BCENE=12 -- SHEATH CONDITIONS, EL ENERGY TRANSMISSION COEFFICIENT
!
    CASE (12) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,1p,g14.7)') &
&       'BCENE = 12 : sheath electron bc on ', bcchar(ib), &
&       boundary_location(ib), ' with transmission coefficient ', enepar&
&       (ib, 1)
        WRITE(*, '(a)') &
&       'Obsolete. Use drift-compatible BCENE = 15 instead'
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fne(ifc, &
&           0)+dv%fne(ifc, 1))) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            max3d(nd) = temp2*(dvd%fne(nd, ifc, 0)+dvd%fne(nd, ifc, 1))
          END DO
          max3 = temp2*(dv%fne(ifc, 0)+dv%fne(ifc, 1))
        ELSE
          max3 = 0.0_R8
          max3d = 0.d0
        END IF
        temp2 = enepar(ib, 1)*max3/dv%ne(icv)
        DO nd=1,nbdirs
          srwd%she0(nd, icv, 3) = srwd%she0(nd, icv, 3) - (max3*enepard(&
&           nd, ib, 1)+enepar(ib, 1)*max3d(nd)-temp2*dvd%ne(nd, icv))/dv&
&           %ne(icv)
        END DO
        srw%she0(icv, 3) = srw%she0(icv, 3) - temp2
      END DO
    CASE (13) 
!
! -- BCENE=13 -- PRESCRIBE THE ELECTRON ENERGY FLUX PER UNIT AREA
!             -- PROPORTIONAL TO TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE = 13 : electron energy flux per area '&
&                                   //'proportional to temperature ', &
&                                   enepar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          srwd%she0(nd, icv, 0) = geo%fcs(ifc)*(pl%te(icv)*enepard(nd, &
&           ib, 1)+enepar(ib, 1)*pld%te(nd, icv))
          srwd%she0(nd, icv, 1) = 0.d0
        END DO
        srw%she0(icv, 0) = enepar(ib, 1)*pl%te(icv)*geo%fcs(ifc)
        srw%she0(icv, 1) = 0.0_R8
      END DO
    CASE (14) 
!
! -- BCENE=14 -- leakage option for electron energy
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                'BCENE = 14 : electron energy leakage '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = pz(icv1)/rz(icv1)
        DO nd=1,nbdirs
          arg12d(nd) = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
        END DO
        arg12 = temp2
        temp2 = SQRT(arg12)
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            csd(nd) = 0.d0
          ELSE
            csd(nd) = arg12d(nd)/(2.0*temp2)
          END IF
        END DO
        cs = temp2
        temp2 = geo%fcs(ifc)*fac_he_anom_bc*qe
        temp1 = enepar(ib, 1)*enepar(ib, 2)
        temp0 = cs*dv%ne(icv1)
        temp = temp0*pl%po(icv1)
        DO nd=1,nbdirs
          srwd%she0(nd, icv1, 0) = temp2*(temp1*(pl%po(icv1)*(dv%ne(icv1&
&           )*csd(nd)+cs*dvd%ne(nd, icv1))+temp0*pld%po(nd, icv1))+temp*&
&           (enepar(ib, 2)*enepard(nd, ib, 1)+enepar(ib, 1)*enepard(nd, &
&           ib, 2)))
        END DO
        srw%she0(icv1, 0) = temp2*(temp*temp1)
        temp2 = geo%fcs(ifc)*fac_he_anom_bc
        DO nd=1,nbdirs
          srwd%she0(nd, icv1, 3) = temp2*(enepar(ib, 1)*csd(nd)+cs*&
&           enepard(nd, ib, 1))
        END DO
        srw%she0(icv1, 3) = temp2*(cs*enepar(ib, 1))
        IF (switch%mdf_fhe .NE. 0) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + temp2*(dvd&
&             %fhepsch(nd, ifc, 0)+dvd%fhepsch(nd, ifc, 1))
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + temp2*(dv%fhepsch(ifc&
&           , 0)+dv%fhepsch(ifc, 1))
          temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&           0.5_R8)
          temp5 = pl%te(icv1) + pl%te(icv2)
          temp4 = dv%ne(icv1) + dv%ne(icv2)
          temp3 = temp4*temp5
          temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
          temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
          temp = temp1*dv%vedia(ifc, 0) + temp0*dv%vedia(ifc, 1)
          DO nd=1,nbdirs
            t0d(nd) = temp2*(temp3*(temp1*dvd%vedia(nd, ifc, 0)+temp0*&
&             dvd%vedia(nd, ifc, 1))+temp*(temp5*(dvd%ne(nd, icv1)+dvd%&
&             ne(nd, icv2))+temp4*(pld%te(nd, icv1)+pld%te(nd, icv2))))
          END DO
          t0 = temp2*(temp*temp3)
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              max4d(nd) = t0d(nd)
            END DO
            max4 = t0
          ELSE
            max4 = 0.0_R8
            max4d = 0.d0
          END IF
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + max4d(nd)
          END DO
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max4
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              min3d(nd) = t0d(nd)
            END DO
            min3 = t0
          ELSE
            min3 = 0.0_R8
            min3d = 0.d0
          END IF
          temp5 = min3/pl%te(icv1)
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + (min3d(nd)&
&             -temp5*pld%te(nd, icv1))/pl%te(icv1)
          END DO
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + temp5
        END IF
      END DO
    CASE (15) 
!
! -- BCENE=15 -- DRIFT-COMPATIBLE SHEATH CONDITION                      !srv 01.02.09 {
!srv 20.09.17 }
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 20.09.17 {
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE = 15 (style = 0) : with GAMMAE =', gammae, ' on ', bcchar&
&       (ib), boundary_location(ib)
        WRITE(*, *) 'BCENE=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY ', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY ', ib&
&                                , ' FOR ALL IONS'
      END IF
!srv 01.02.09 }
!srv added accumulation in order to account twice b.c. for corner cells
      IF (bcene_15_style .EQ. 0) THEN
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENE = 15 (style = 0) : with GAMMAE ='&
&                                     , gammae, ' on ', bcchar(ib), &
&                                     boundary_location(ib)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = pz(icv1)/rz(icv1)
          DO nd=1,nbdirs
            arg12d(nd) = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
            t0d(nd) = dvd%ne(nd, icv1)
          END DO
          arg12 = temp2
          temp2 = SQRT(arg12)
          DO nd=1,nbdirs
            IF (arg12 .EQ. 0.d0) THEN
              csd(nd) = 0.d0
            ELSE
              csd(nd) = arg12d(nd)/(2.0*temp2)
            END IF
          END DO
          cs = temp2
          t0 = dv%ne(icv1)
          t1 = 0.0_R8
          t1d = 0.d0
          DO is=0,ns-1
            IF (.NOT.is_neutral(is) .AND. conpar(is, ib, 2) .GT. 0.0_R8&
&           ) THEN
              temp5 = pl%na(icv1, is)/conpar(is, ib, 2)
              temp4 = co%dna0(icv1, is)*rt%rza(icv1, is)
              DO nd=1,nbdirs
                t1d(nd) = t1d(nd) + temp5*(rt%rza(icv1, is)*cod%dna0(nd&
&                 , icv1, is)+co%dna0(icv1, is)*rtd%rza(nd, icv1, is)) +&
&                 temp4*(pld%na(nd, icv1, is)-temp5*conpard(nd, is, ib, &
&                 2))/conpar(is, ib, 2)
              END DO
              t1 = t1 + temp4*temp5
            END IF
          END DO
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs1 = geo%fcpbs(ifc)
          ELSE
            abs1 = -geo%fcpbs(ifc)
          END IF
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            y1d(nd) = abs1*(cs*t0d(nd)+t0*csd(nd)) - temp2*dvd%fch_p(nd&
&             , ifc, 0)/qe
          END DO
          y1 = abs1*(t0*cs) - temp2*(dv%fch_p(ifc, 0)/qe)
          IF (0.0_R8 .LT. y1) THEN
            DO nd=1,nbdirs
              t0d(nd) = y1d(nd)
            END DO
            t0 = y1
          ELSE
            t0 = 0.0_R8
            t0d = 0.d0
          END IF
          DO nd=1,nbdirs
            t1d(nd) = geo%fcs(ifc)*t1d(nd)
          END DO
          t1 = t1*geo%fcs(ifc)
!srv 27.02.13 }
          IF (switch%pot_eq .EQ. 1) THEN
!srv 07.11.12
            temp5 = pl%po(icv1) - potpar(ib, 2)
            DO nd=1,nbdirs
!srv 27.02.13 {
!srv 11.03.09 {
!srv 19.04.13
!wdk to check: correct for gammae?
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) - (gammae+&
&               1.0_R8)*t0d(nd)/(1.0_R8-gammae) - fac_he_anom_bc*(t1*&
&               enepard(nd, ib, 2)+enepar(ib, 2)*t1d(nd))
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) - qe*((t0+&
&               t1)*(pld%po(nd, icv1)-potpard(nd, ib, 2))+temp5*(t0d(nd)&
&               +t1d(nd)))
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - (1.0_R8+gammae)/(&
&             1.0_R8-gammae)*t0 - fac_he_anom_bc*enepar(ib, 2)*t1
            srw%she0(icv1, 0) = srw%she0(icv1, 0) - qe*(temp5*(t0+t1))
          ELSE
!srv 27.02.13
!srv 11.03.09 {
!srv 19.04.13
!wdk to check: correct for gammae?
            temp2 = (gammae+1.0_R8)/(-gammae+1.0_R8) + switch%delpo
            temp1 = switch%delpo + fac_he_anom_bc*enepar(ib, 2)
            DO nd=1,nbdirs
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) - temp2*&
&               t0d(nd) - t1*fac_he_anom_bc*enepard(nd, ib, 2) - temp1*&
&               t1d(nd)
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - temp2*t0 - temp1*t1
          END IF
          IF (switch%mdf_fhe .NE. 0) THEN
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + temp2*(&
&               dvd%fhepsch(nd, ifc, 0)+dvd%fhepsch(nd, ifc, 1))
            END DO
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + temp2*(dv%fhepsch(&
&             ifc, 0)+dv%fhepsch(ifc, 1))
            temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp5 = pl%te(icv1) + pl%te(icv2)
            temp4 = dv%ne(icv1) + dv%ne(icv2)
            temp3 = temp4*temp5
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*dv%vedia(ifc, 0) + temp0*dv%vedia(ifc, 1)
            DO nd=1,nbdirs
              t0d(nd) = temp2*(temp3*(temp1*dvd%vedia(nd, ifc, 0)+temp0*&
&               dvd%vedia(nd, ifc, 1))+temp*(temp5*(dvd%ne(nd, icv1)+dvd&
&               %ne(nd, icv2))+temp4*(pld%te(nd, icv1)+pld%te(nd, icv2))&
&               ))
            END DO
            t0 = temp2*(temp*temp3)
            IF (0.0_R8 .LT. t0) THEN
              DO nd=1,nbdirs
                max5d(nd) = t0d(nd)
              END DO
              max5 = t0
            ELSE
              max5 = 0.0_R8
              max5d = 0.d0
            END IF
            DO nd=1,nbdirs
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + max5d(nd&
&               )
            END DO
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + max5
            IF (0.0_R8 .GT. t0) THEN
              DO nd=1,nbdirs
                min4d(nd) = t0d(nd)
              END DO
              min4 = t0
            ELSE
              min4 = 0.0_R8
              min4d = 0.d0
            END IF
            temp5 = min4/pl%te(icv1)
            DO nd=1,nbdirs
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + (min4d(&
&               nd)-temp5*pld%te(nd, icv1))/pl%te(icv1)
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) + temp5
          END IF
        END DO
      ELSE IF (bcene_15_style .EQ. 1) THEN
!wdk    Todo: corrections for BCCON.ne.14
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a)') &
&                              'BCENE = 15 (style = 1) : with GAMMAE = '&
&                                     , gammae, ' and ENEPAR(IB,1) = ', &
&                                     enepar(ib, 1), ' (def = 0), on ', &
&                                     bcchar(ib), boundary_location(ib)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg13 = pl%te(icv1)/me
          temp5 = SQRT(arg13)
          DO nd=1,nbdirs
            arg13d(nd) = pld%te(nd, icv1)/me
            IF (arg13 .EQ. 0.d0) THEN
              vted(nd) = 0.d0
            ELSE
              vted(nd) = arg13d(nd)/(2.0*temp5)
            END IF
          END DO
          vte = temp5
          IF (geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3) .GE. &
&             0.) THEN
            wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          ELSE
            wrk = -(geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)&
&             )
          END IF
          IF (wrk .LT. geo%qalfmin) THEN
            IF (geo%fcs(ifc) .GE. 0.) THEN
              abs0 = geo%fcs(ifc)
            ELSE
              abs0 = -geo%fcs(ifc)
            END IF
            s1 = abs0*geo%qalfmax
          ELSE IF (geo%fcpbs(ifc) .GE. 0.) THEN
            s1 = geo%fcpbs(ifc)
          ELSE
            s1 = -geo%fcpbs(ifc)
          END IF
          DO nd=1,nbdirs
            t0d(nd) = dvd%ne(nd, icv1)
          END DO
          t0 = dv%ne(icv1)
          t1 = 0.0_R8
          t1d = 0.d0
          DO is=0,ns-1
            IF (.NOT.is_neutral(is) .AND. conpar(is, ib, 2) .GT. 0.0_R8&
&           ) THEN
              temp5 = pl%na(icv1, is)/conpar(is, ib, 2)
              temp4 = co%dna0(icv1, is)*rt%rza(icv1, is)
              DO nd=1,nbdirs
                t1d(nd) = t1d(nd) + temp5*(rt%rza(icv1, is)*cod%dna0(nd&
&                 , icv1, is)+co%dna0(icv1, is)*rtd%rza(nd, icv1, is)) +&
&                 temp4*(pld%na(nd, icv1, is)-temp5*conpard(nd, is, ib, &
&                 2))/conpar(is, ib, 2)
              END DO
              t1 = t1 + temp4*temp5
            END IF
          END DO
          IF (-50.0_R8 .LT. -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)&
&             )) THEN
            temp5 = (pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)
            DO nd=1,nbdirs
              y2d(nd) = -(qe*(pld%po(nd, icv1)-potpard(nd, ib, 2)-temp5*&
&               pld%te(nd, icv1))/pl%te(icv1))
            END DO
            y2 = -(qe*temp5)
          ELSE
            y2 = -50.0_R8
            y2d = 0.d0
          END IF
          IF (0.0_R8 .GT. y2) THEN
            DO nd=1,nbdirs
              min5d(nd) = y2d(nd)
            END DO
            min5 = y2
          ELSE
            min5 = 0.0_R8
            min5d = 0.d0
          END IF
!lkw 31.03.2023
          arg13 = 1.0_R8/(2.0_R8*pi)
          result10 = SQRT(arg13)
          CALL EXPU2_DV(min5, min5d, result20, result20d, nbdirs)
          DO nd=1,nbdirs
            t0d(nd) = s1*result10*(result20*(vte*t0d(nd)+t0*vted(nd))+t0&
&             *vte*result20d(nd))
            t1d(nd) = geo%fcs(ifc)*t1d(nd)
          END DO
          t0 = s1*t0*result10*vte*result20
          t1 = t1*geo%fcs(ifc)
          IF (switch%pot_eq .EQ. 1) THEN
!wdk to check: correct 2nd term for gammae?
            temp2 = gammae + switch%stab_coeff_sheath_te + enepar(ib, 1)&
&             + 1.0_R8
!lkw 31.03.2023
!wdk to check: correct 2nd term for gammae?
            temp5 = (-gammae+1.0_R8)*qe*(pl%po(icv1)-potpar(ib, 2)) - &
&             switch%stab_coeff_sheath_te*pl%te(icv1)
            temp4 = pl%po(icv1) - potpar(ib, 2)
            DO nd=1,nbdirs
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) - t0*&
&               enepard(nd, ib, 1) - temp2*t0d(nd) - fac_he_anom_bc*(t1*&
&               enepard(nd, ib, 2)+enepar(ib, 2)*t1d(nd))
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) - t0*((&
&               1.0_R8-gammae)*qe*(pld%po(nd, icv1)-potpard(nd, ib, 2))-&
&               switch%stab_coeff_sheath_te*pld%te(nd, icv1)) - temp5*&
&               t0d(nd) - qe*(t1*(pld%po(nd, icv1)-potpard(nd, ib, 2))+&
&               temp4*t1d(nd))
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - temp2*t0 - &
&             fac_he_anom_bc*(enepar(ib, 2)*t1)
            srw%she0(icv1, 0) = srw%she0(icv1, 0) - temp5*t0 - qe*(temp4&
&             *t1)
            IF (switch%b2nppo_restr_po .NE. 0.0_R8 .AND. srw%she0(icv1, &
&               0) + srw%she0(icv1, 1)*pl%te(icv1) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                srwd%she0(nd, icv1, :) = 0.d0
              END DO
              srw%she0(icv1, :) = 0.0_R8
            END IF
          ELSE
            temp2 = pz(icv1)/rz(icv1)
            DO nd=1,nbdirs
              arg12d(nd) = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
            END DO
            arg12 = temp2
            temp2 = SQRT(arg12)
            DO nd=1,nbdirs
              IF (arg12 .EQ. 0.d0) THEN
                csd(nd) = 0.d0
              ELSE
                csd(nd) = arg12d(nd)/(2.0*temp2)
              END IF
            END DO
            cs = temp2
!srv 11.03.09 {
!wdk to check: correct for gammae?
            temp2 = gammae + (-gammae+1.0_R8)*switch%delpo + enepar(ib, &
&             1) + 1.0_R8
            temp5 = dv%ne(icv1)*cs
            temp1 = switch%delpo + fac_he_anom_bc*enepar(ib, 2)
            DO nd=1,nbdirs
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) - s1*(&
&               temp2*(cs*dvd%ne(nd, icv1)+dv%ne(icv1)*csd(nd))+temp5*&
&               enepard(nd, ib, 1)) - t1*fac_he_anom_bc*enepard(nd, ib, &
&               2) - temp1*t1d(nd)
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - s1*(temp5*temp2) - &
&             temp1*t1
          END IF
          IF (switch%mdf_fhe .NE. 0) THEN
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + temp2*(&
&               dvd%fhepsch(nd, ifc, 0)+dvd%fhepsch(nd, ifc, 1))
            END DO
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + temp2*(dv%fhepsch(&
&             ifc, 0)+dv%fhepsch(ifc, 1))
            temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp5 = pl%te(icv1) + pl%te(icv2)
            temp4 = dv%ne(icv1) + dv%ne(icv2)
            temp3 = temp4*temp5
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*dv%vedia(ifc, 0) + temp0*dv%vedia(ifc, 1)
            DO nd=1,nbdirs
              t0d(nd) = temp2*(temp3*(temp1*dvd%vedia(nd, ifc, 0)+temp0*&
&               dvd%vedia(nd, ifc, 1))+temp*(temp5*(dvd%ne(nd, icv1)+dvd&
&               %ne(nd, icv2))+temp4*(pld%te(nd, icv1)+pld%te(nd, icv2))&
&               ))
            END DO
            t0 = temp2*(temp*temp3)
            IF (0.0_R8 .LT. t0) THEN
              DO nd=1,nbdirs
                max6d(nd) = t0d(nd)
              END DO
              max6 = t0
            ELSE
              max6 = 0.0_R8
              max6d = 0.d0
            END IF
            DO nd=1,nbdirs
              srwd%she0(nd, icv1, 0) = srwd%she0(nd, icv1, 0) + max6d(nd&
&               )
            END DO
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + max6
            IF (0.0_R8 .GT. t0) THEN
              DO nd=1,nbdirs
                min6d(nd) = t0d(nd)
              END DO
              min6 = t0
            ELSE
              min6 = 0.0_R8
              min6d = 0.d0
            END IF
            temp5 = min6/pl%te(icv1)
            DO nd=1,nbdirs
              srwd%she0(nd, icv1, 1) = srwd%she0(nd, icv1, 1) + (min6d(&
&               nd)-temp5*pld%te(nd, icv1))/pl%te(icv1)
            END DO
            srw%she0(icv1, 1) = srw%she0(icv1, 1) + temp5
          END IF
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=15, incorrect bcene_15_style value'&
&            )
      END IF
    CASE (16) 
!
! -- BCENE=16 -- Feedback boundary condition with constant temperature
!
!
      IF (switch%bcene_16_style .EQ. 0) THEN
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&         'BCENE = 16 (style = 0) : '//&
&         'electron temperature feedback by flux ', enepar(ib, 1), &
&         ' with ', enepar(ib, 2), ' on ', bcchar(ib), boundary_location&
&         (ib)
          CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        END IF
!       ..compute average temperature on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
        totfluxd = 0.d0
        t0d = 0.d0
        t1d = 0.d0
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            t0d(nd) = t0d(nd) + geo%fcs(ifc)*dvd%ne(nd, icv1)
            t1d(nd) = t1d(nd) + geo%fcs(ifc)*(pl%te(icv1)*dvd%ne(nd, &
&             icv1)+dv%ne(icv1)*pld%te(nd, icv1))
            totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhe(nd, ifc, 0)+dvd&
&             %fhe(nd, ifc, 1))
          END DO
          t0 = t0 + geo%fcs(ifc)*dv%ne(icv1)
          t1 = t1 + geo%fcs(ifc)*dv%ne(icv1)*pl%te(icv1)
          totflux = totflux - temp2*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1))
        END DO
        DO nd=1,nbdirs
          t1d(nd) = (t1d(nd)-t1*t0d(nd)/t0)/t0
          totpard(nd) = fac_he_anom_bc*enepard(nd, ib, 1)
        END DO
        t1 = t1/t0
        totpar = fac_he_anom_bc*enepar(ib, 1)
        IF (enepar(ib, 2) .GT. 0.0_R8) THEN
          DO nd=1,nbdirs
            t3d(nd) = enepard(nd, ib, 2)
          END DO
          t3 = enepar(ib, 2)
        ELSE
          t3d = 0.d0
        END IF
        IF (enepar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          t3d = 0.d0
        END IF
        IF (totflux .GE. 0.) THEN
          DO nd=1,nbdirs
            x1d(nd) = totfluxd(nd)
          END DO
          x1 = totflux
        ELSE
          DO nd=1,nbdirs
            x1d(nd) = -totfluxd(nd)
          END DO
          x1 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          DO nd=1,nbdirs
            y3d(nd) = totpard(nd)
          END DO
          y3 = totpar
        ELSE
          DO nd=1,nbdirs
            y3d(nd) = -totpard(nd)
          END DO
          y3 = -totpar
        END IF
        IF (x1 .LT. y3) THEN
          DO nd=1,nbdirs
            max7d(nd) = y3d(nd)
          END DO
          max7 = y3
        ELSE
          DO nd=1,nbdirs
            max7d(nd) = x1d(nd)
          END DO
          max7 = x1
        END IF
        temp2 = t3/max7
        temp5 = -((totflux-totpar)*temp2) + 1.0_R8
        DO nd=1,nbdirs
          t2d(nd) = temp5*t1d(nd) - t1*(temp2*(totfluxd(nd)-totpard(nd))&
&           +(totflux-totpar)*(t3d(nd)-temp2*max7d(nd))/max7)
        END DO
        t2 = temp5*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&             'bcene=16: curr_flux, desired_flux, old/new temperature, '&
&                                        , totflux, totpar, t1/qe, t2/qe
!       ..impose temperature
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2d(nd)
            srwd%she0(nd, icv1, 1) = 0.d0
          END DO
          srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE IF (switch%bcene_16_style .EQ. 1) THEN
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a)') 'BCENE = 16 (style = 1) : '//&
&         'Given integrated electron heat flux with constant Te'
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcene(ibw) .EQ. bcene(ib)) THEN
              WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location&
&             (ibw)
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCENE = 16 only applicable to core boundaries !')
              CALL XERTST(enepar(ibw, 1) .NE. 0.0_R8, &
&                   'faulty parameter enepar1')
            END IF
          END DO
        END IF
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bcene) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              senepar = 0.0_R8
              senepard = 0.d0
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bcene(ibw) .EQ. bcene(ib)) THEN
                  DO nd=1,nbdirs
                    senepard(nd) = senepard(nd) + enepard(nd, ibw, 1)
                  END DO
                  senepar = senepar + enepar(ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCENE=16: Summed value is ', senepar
            tes = 0.0_R8
            volsum = 0.0_R8
            tesd = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  DO nd=1,nbdirs
                    tesd(nd) = tesd(nd) + geo%cvvol(icv)*pld%te(nd, icv)
                  END DO
                  tes = tes + pl%te(icv)*geo%cvvol(icv)
                  volsum = volsum + geo%cvvol(icv)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              tesd(nd) = tesd(nd)/volsum
            END DO
            tes = tes/volsum
            totflux = 0.0_R8
            totfluxd = 0.d0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  IF (switch%mdf_fhe .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhe_mdf(&
&                       nd, ifc, 0)+dvd%fhe_mdf(nd, ifc, 1))
                    END DO
                    totflux = totflux - temp2*(dv%fhe_mdf(ifc, 0)+dv%&
&                     fhe_mdf(ifc, 1))
                    temp2 = geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)
                    temp1 = geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, ns-1) +&
&                     geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, ns-1)
                    temp5 = pl%te(icv)*dv%ne(icv)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(temp1*(dv%ne(&
&                       icv)*pld%te(nd, icv)+pl%te(icv)*dvd%ne(nd, icv))&
&                       +temp5*(geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, ifc, 0&
&                       , ns-1)+geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc, 1&
&                       , ns-1)))
                    END DO
                    totflux = totflux - temp2*(temp5*temp1)
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhe(nd, &
&                       ifc, 0)+dvd%fhe(nd, ifc, 1))
                    END DO
                    totflux = totflux - temp2*(dv%fhe(ifc, 0)+dv%fhe(ifc&
&                     , 1))
                  END IF
                END DO
              END IF
            END DO
            IF (enepar(ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                t3d(nd) = enepard(nd, ib, 2)
              END DO
              t3 = enepar(ib, 2)
            ELSE
              t3d = 0.d0
            END IF
            IF (enepar(ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref_te
              t3d = 0.d0
            END IF
            IF (totflux .GE. 0.) THEN
              DO nd=1,nbdirs
                x2d(nd) = totfluxd(nd)
              END DO
              x2 = totflux
            ELSE
              DO nd=1,nbdirs
                x2d(nd) = -totfluxd(nd)
              END DO
              x2 = -totflux
            END IF
            IF (x2 .LT. senepar) THEN
              DO nd=1,nbdirs
                max8d(nd) = senepard(nd)
              END DO
              max8 = senepar
            ELSE
              DO nd=1,nbdirs
                max8d(nd) = x2d(nd)
              END DO
              max8 = x2
            END IF
            temp2 = t3/max8
            temp5 = -((totflux-senepar)*temp2) + 1.0_R8
            DO nd=1,nbdirs
              tesd(nd) = temp5*tesd(nd) - tes*(temp2*(totfluxd(nd)-&
&               senepard(nd))+(totflux-senepar)*(t3d(nd)-temp2*max8d(nd)&
&               )/max8)
            END DO
            tes = tes*temp5
            WRITE(*, '(3(a,es14.7))') ' TES=', tes/ev, ' totflux=', &
&           totflux, ' SENEPAR=', senepar
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  DO nd=1,nbdirs
                    srwd%she0(nd, icv, 0) = vbig*ne00*geo%fcs(ifc)*tesd(&
&                     nd)
                    srwd%she0(nd, icv, 1) = 0.d0
                  END DO
                  srw%she0(icv, 0) = vbig*ne00*tes*geo%fcs(ifc)
                  srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
                END DO
              END IF
            END DO
            once_bcene = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCENE=16, ONLY AVAILABLE FOR CORE!')
        END IF
      ELSE
        CALL XERRAB(' Incorrect style of boundary condition')
      END IF
    CASE (17) 
!
! -- BCENE=17 -- Feedback boundary condition with constant shared temperature
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 17 : shared temperature feedback by flux ', enepar(ib, &
&       1), ' with ', enepar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        CALL XERTST(enepar(ib, 2) .GT. 0, 'faulty parameter enepar2')
        CALL XERTST(bcene(ib) .EQ. bceni(ib), &
&             'both bcene and bceni should be set to 17')
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        CALL XERTST(enipar(ib, 2) .GT. 0, 'faulty parameter enipar2')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        totfluxd = 0.d0
        t0d = 0.d0
        weightd = 0.d0
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhe(nd, ifc, 0)+dvd&
&             %fhe(nd, ifc, 1)+dvd%fhi(nd, ifc, 0)+dvd%fhi(nd, ifc, 1))
          END DO
          totflux = totflux - temp2*(st_ext%fhi(ifc, 0)+st_ext%fhi(ifc, &
&           1)+dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%fhi(ifc, 0)+dv%fhi(ifc, &
&           1))
          IF (bc_type16_kinetic_energy .EQ. 1) THEN
            DO is=0,ns-1
              CALL INTFACE_S_DV(ifc, ncv, nfc, mpg%fccv, geo%fcvol, dv%&
&                         kinrgy(1, is), dvd%kinrgy(:, 1, is), result11&
&                         , result11d, nbdirs)
              temp5 = (-switch%boris+1.0_R8)*mpg%bcfcor(mpg%bccvp(ib, 1)&
&               +ibc-1)
              temp4 = dv%fna(ifc, 0, is) + dv%fna(ifc, 1, is)
              DO nd=1,nbdirs
                totfluxd(nd) = totfluxd(nd) - temp5*(result11*(dvd%fna(&
&                 nd, ifc, 0, is)+dvd%fna(nd, ifc, 1, is))+temp4*&
&                 result11d(nd))
              END DO
              totflux = totflux - temp5*(temp4*result11)
            END DO
            DO is=0,st_ext%ns-1
              result11 = INTFACE_S(ifc, ncv, nfc, mpg%fccv, geo%fcvol, &
&               st_ext%ua(1, is))
              totflux = totflux - (1.0_R8-switch%boris)*mpg%bcfcor(mpg%&
&               bccvp(ib, 1)+ibc-1)*(st_ext%fa(ifc, 0, is)+st_ext%fa(ifc&
&               , 1, is))*0.5_R8*st_ext%am(is)*mp*result11**2
            END DO
          END IF
          DO nd=1,nbdirs
            t0d(nd) = t0d(nd) + geo%cvvol(icv)*(dv%ne(icv)*pld%te(nd, &
&             icv)+pl%te(icv)*dvd%ne(nd, icv)+dv%ni(icv, 0)*pld%ti(nd, &
&             icv)+pl%ti(icv)*dvd%ni(nd, icv, 0))
            weightd(nd) = weightd(nd) + geo%cvvol(icv)*(dvd%ne(nd, icv)+&
&             dvd%ni(nd, icv, 0))
          END DO
          t0 = t0 + (pl%te(icv)*dv%ne(icv)+pl%ti(icv)*dv%ni(icv, 0))*geo&
&           %cvvol(icv)
          weight = weight + (dv%ne(icv)+dv%ni(icv, 0))*geo%cvvol(icv)
        END DO
        DO nd=1,nbdirs
          t0d(nd) = (t0d(nd)-t0*weightd(nd)/weight)/weight
        END DO
        t0 = t0/weight
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        temp2 = enipar(ib, 2)/enipar(ib, 1)
        temp1 = enepar(ib, 1) + enipar(ib, 1)
        temp0 = totflux*enipar(ib, 1)/temp1
        temp = enepar(ib, 2)/enepar(ib, 1)
        temp6 = enepar(ib, 1) + enipar(ib, 1)
        temp7 = totflux*enepar(ib, 1)/temp6
        temp5 = -((temp0-enipar(ib, 1))*temp2) - (temp7-enepar(ib, 1))*&
&         temp + 1.0_R8
        DO nd=1,nbdirs
          t1d(nd) = t0*(-(temp2*((enipar(ib, 1)*totfluxd(nd)+totflux*&
&           enipard(nd, ib, 1)-temp0*(enepard(nd, ib, 1)+enipard(nd, ib&
&           , 1)))/temp1-enipard(nd, ib, 1)))-(temp0-enipar(ib, 1))*(&
&           enipard(nd, ib, 2)-temp2*enipard(nd, ib, 1))/enipar(ib, 1)-&
&           temp*((enepar(ib, 1)*totfluxd(nd)+totflux*enepard(nd, ib, 1)&
&           -temp7*(enepard(nd, ib, 1)+enipard(nd, ib, 1)))/temp6-&
&           enepard(nd, ib, 1))-(temp7-enepar(ib, 1))*(enepard(nd, ib, 2&
&           )-temp*enepard(nd, ib, 1))/enepar(ib, 1)) + temp5*t0d(nd)
        END DO
        t1 = temp5*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New shared temp :', t0/qe&
&                                        , t1/qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          DO nd=1,nbdirs
            srwd%she0(nd, icv, 0) = vbig*ne00*geo%fcs(ifc)*t1d(nd)
            srwd%she0(nd, icv, 1) = 0.d0
            srwd%shi0(nd, icv, 0) = vbig*ne00*geo%fcs(ifc)*t1d(nd)
            srwd%shi0(nd, icv, 1) = 0.d0
          END DO
          srw%she0(icv, 0) = vbig*ne00*t1*geo%fcs(ifc)
          srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
          srw%shi0(icv, 0) = vbig*ne00*t1*geo%fcs(ifc)
          srw%shi0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=17, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (18) 
!
! -- BCENE=18 -- FRACTIONAL DROP CONDITION (FOR EDGE2D COMPARISON)
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE = 18 : electron temperature fractional drop ', enepar(ib&
&       , 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .LT. 1.0_R8, &
&             'BCENE = 18, ENEPAR(,1) => 1')
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          t1d(nd) = (1.0_R8-enepar(ib, 1))*pld%te(nd, icv2) - pl%te(icv2&
&           )*enepard(nd, ib, 1)
          srwd%she0(nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1d(nd)
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        t1 = (1.0_R8-enepar(ib, 1))*pl%te(icv2)
        srw%she0(icv1, 0) = vbig*ne00*t1*geo%fcs(ifc)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (19) 
!
! -- BCENE=19 -- PRESCRIBE THE DECAY LENGTH FOR THE ELECTRON TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENE = 19 not adapted for WG')
!
! -- BCENE=20 -- Feedback boundary condition with constant temperature
!
    CASE (20) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 20 : electron temperature feedback by flux ', enepar(ib&
&       , 1), ' with ', enepar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        teave = 0.0_R8
        neave = 0.0_R8
        teaved = 0.d0
        totfluxd = 0.d0
        t0d = 0.d0
        weightd = 0.d0
        neaved = 0.d0
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp7 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            totfluxd(nd) = totfluxd(nd) - temp7*(dvd%fhe(nd, ifc, 0)+dvd&
&             %fhe(nd, ifc, 1))
            t0d(nd) = t0d(nd) + geo%cvvol(icv1)*(dv%ne(icv1)*pld%te(nd, &
&             icv1)+pl%te(icv1)*dvd%ne(nd, icv1))
            weightd(nd) = weightd(nd) + geo%cvvol(icv1)*dvd%ne(nd, icv1)
            teaved(nd) = teaved(nd) + geo%cvvol(icv2)*(dv%ne(icv2)*pld%&
&             te(nd, icv2)+pl%te(icv2)*dvd%ne(nd, icv2))
            neaved(nd) = neaved(nd) + geo%cvvol(icv2)*dvd%ne(nd, icv2)
          END DO
          totflux = totflux - temp7*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1))
          t0 = t0 + pl%te(icv1)*dv%ne(icv1)*geo%cvvol(icv1)
          weight = weight + dv%ne(icv1)*geo%cvvol(icv1)
          teave = teave + pl%te(icv2)*dv%ne(icv2)*geo%cvvol(icv2)
          neave = neave + dv%ne(icv2)*geo%cvvol(icv2)
        END DO
        DO nd=1,nbdirs
          t0d(nd) = (t0d(nd)-t0*weightd(nd)/weight)/weight
          teaved(nd) = (teaved(nd)-teave*neaved(nd)/neave)/neave
        END DO
        t0 = t0/weight
        teave = teave/neave
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        IF (enepar(ib, 2) .GT. 0.0_R8) THEN
          DO nd=1,nbdirs
            t3d(nd) = enepard(nd, ib, 2)
          END DO
          t3 = enepar(ib, 2)
        ELSE
          t3d = 0.d0
        END IF
        IF (enepar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          t3d = 0.d0
        END IF
        temp7 = t3/enepar(ib, 1)
        temp5 = -((totflux-enepar(ib, 1))*temp7) + 1.0_R8
        DO nd=1,nbdirs
          t1d(nd) = temp5*t0d(nd) - t0*(temp7*(totfluxd(nd)-enepard(nd, &
&           ib, 1))+(totflux-enepar(ib, 1))*(t3d(nd)-temp7*enepard(nd, &
&           ib, 1))/enepar(ib, 1))
        END DO
        t1 = temp5*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New electron temp :', t0/&
&                                        qe, t1/qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp7 = vbig*ne00*geo%fcs(ifc)
          temp6 = t1/teave
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 0) = temp7*(temp6*pld%te(nd, icv2)+pl%te&
&             (icv2)*(t1d(nd)-temp6*teaved(nd))/teave)
            srwd%she0(nd, icv1, 1) = 0.d0
          END DO
          srw%she0(icv1, 0) = temp7*(pl%te(icv2)*temp6)
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=20, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (21) 
!
! -- BCENE=21 -- constant temperature scaled by temperature on the ring bc_type21_ref away
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 21 : fixed electron temperature '//&
&       '(modified by nearby ring) ', enepar(ib, 1), ' with ', enepar(ib&
&       , 2), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0.0_R8, &
&             'faulty parameter enepar1')
      END IF
      IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'N') .OR. bcchar(ib)&
&         .EQ. 'A') THEN
        teave = 0.0_R8
        neave = 0.0_R8
        teaved = 0.d0
        neaved = 0.d0
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          DO nd=1,nbdirs
            teaved(nd) = teaved(nd) + geo%cvvol(icv)*(dv%ne(icv)*pld%te(&
&             nd, icv)+pl%te(icv)*dvd%ne(nd, icv))
            neaved(nd) = neaved(nd) + geo%cvvol(icv)*dvd%ne(nd, icv)
          END DO
          teave = teave + pl%te(icv)*dv%ne(icv)*geo%cvvol(icv)
          neave = neave + dv%ne(icv)*geo%cvvol(icv)
        END DO
        DO nd=1,nbdirs
          teaved(nd) = (teaved(nd)-teave*neaved(nd)/neave)/neave
        END DO
        teave = teave/neave
        IF (enepar(ib, 2) .GT. 0.0_R8) THEN
          DO nd=1,nbdirs
            t3d(nd) = enepard(nd, ib, 2)
          END DO
          t3 = enepar(ib, 2)
        ELSE
          t3d = 0.d0
        END IF
        IF (enepar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          t3d = 0.d0
        END IF
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp7 = vbig*ne00*ev*geo%fcs(ifc)
          temp6 = t3/teave
          temp5 = pl%te(icv2)*temp6 - t3 + 1.0_R8
          DO nd=1,nbdirs
            srwd%she0(nd, icv1, 0) = temp7*(temp5*enepard(nd, ib, 1)+&
&             enepar(ib, 1)*(temp6*pld%te(nd, icv2)+pl%te(icv2)*(t3d(nd)&
&             -temp6*teaved(nd))/teave-t3d(nd)))
            srwd%she0(nd, icv1, 1) = 0.d0
          END DO
          srw%she0(icv1, 0) = temp7*(enepar(ib, 1)*temp5)
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=21, NOT AVAILABLE FOR W,E')
      END IF
    CASE (22) 
!
! -- BCENE=22 -- RADIAL LEAKAGE CONDITION FOR THE ELECTRON TEMPERATURE   !srv 23.07.10 {
!                SPECIFIES A TEMPERATURE GRADIENT SUCH THAT THE DIFFUSIVE
!                FLUX IS SET TO BE EQUIVALENT TO A LEAKAGE VELOCITY, IN
!                UNITS OF THE ELECTRON THERMAL VELOCITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCENE = 22 : with ENEPAR(IB,1)= ', &
&                                   enepar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
!wdk    Notes:
!wdk     * need correction for misaligned grids -> t1
!wdk     * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg13 = pl%te(icv1)/me
        temp5 = SQRT(arg13)
        t0 = geo%fcqalf(ifc, 1)
        t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&         fcqbet(ifc, 0)
        temp7 = vbig*ne00*ev
        temp6 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1
        temp2 = t0*pl%te(icv2) - temp6*(pl%te(mpg%fcvx(ifc, 2))-pl%te(&
&         mpg%fcvx(ifc, 1)))
        DO nd=1,nbdirs
          arg13d(nd) = pld%te(nd, icv1)/me
          IF (arg13 .EQ. 0.d0) THEN
            vted(nd) = 0.d0
          ELSE
            vted(nd) = arg13d(nd)/(2.0*temp5)
          END IF
          srwd%she0(nd, icv1, 0) = temp7*(temp2*cod%chce(nd, ifc, 1)+co%&
&           chce(ifc, 1)*(t0*pld%te(nd, icv2)-temp6*(pld%te(nd, mpg%fcvx&
&           (ifc, 2))-pld%te(nd, mpg%fcvx(ifc, 1)))))
        END DO
        vte = temp5
        srw%she0(icv1, 0) = temp7*(co%chce(ifc, 1)*temp2)
        temp7 = vbig*ne00*ev
        temp6 = enepar(ib, 1)*vte
        DO nd=1,nbdirs
          srwd%she0(nd, icv1, 1) = -(temp7*(t0*cod%chce(nd, ifc, 1)-geo%&
&           fcs(ifc)*(dv%ne(icv1)*(vte*enepard(nd, ib, 1)+enepar(ib, 1)*&
&           vted(nd))+temp6*dvd%ne(nd, icv1))))
        END DO
        srw%she0(icv1, 1) = -(temp7*(t0*co%chce(ifc, 1)-geo%fcs(ifc)*(&
&         temp6*dv%ne(icv1))))
      END DO
    CASE (23) 
!
!
! -- BCENE=23 -- Prescribe the value of the electron temperature, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENE=23 intended for core boundaries only!')
        END DO
        IF (switch%use_astra .NE. 0) THEN
          DO nd=1,nbdirs
            enepard(nd, ib, 1) = 0.d0
          END DO
          enepar(ib, 1) = teb_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified electron temp. + perturbation', enepar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 23, ENEPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t1d = 0.d0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            DO nd=1,nbdirs
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%te(nd, icv2)
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%te(icv2)
          END DO
        END IF
      END DO
      DO nd=1,nbdirs
        t1d(nd) = t1d(nd)/t0
      END DO
      t1 = t1/t0
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp7 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%she0(nd, icv1, 0) = temp7*(pld%te(nd, icv2)+ev*enepard(nd&
&           , ib, 1)-t1d(nd))
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        srw%she0(icv1, 0) = temp7*(pl%te(icv2)+ev*enepar(ib, 1)-t1)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (24) 
!
! -- BCENE=24 -- Feedback on the total electron energy flux, by imposing a flux surface
!                averaged temperature, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENE=24 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified electron heat flux', &
&       enepar(ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 24, ENEPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
      totfluxd = 0.d0
      t1d = 0.d0
      t2d = 0.d0
      totpard = 0.d0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bcene(ib0) .NE. 24) CALL XERRAB(&
&                                      'BCENE=24: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            temp7 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
            DO nd=1,nbdirs
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%te(nd, icv1)
              t2d(nd) = t2d(nd) + geo%cvvol(icv2)*pld%te(nd, icv2)
              totfluxd(nd) = totfluxd(nd) - temp7*(dvd%fhe(nd, ifc, 0)+&
&               dvd%fhe(nd, ifc, 1))
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%te(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%te(icv2)
            totflux = totflux - temp7*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1))
          END DO
          DO nd=1,nbdirs
            totpard(nd) = totpard(nd) + enepard(nd, ib0, 1)
          END DO
          totpar = totpar + enepar(ib0, 1)
        END IF
      END DO
      DO nd=1,nbdirs
        totpard(nd) = fac_he_anom_bc*totpard(nd)
        t1d(nd) = t1d(nd)/t0
        t2d(nd) = t2d(nd)/t0
      END DO
      totpar = fac_he_anom_bc*totpar
      t1 = t1/t0
      t2 = t2/t0
      IF (enepar(ib, 2) .GT. 0.0_R8) THEN
        DO nd=1,nbdirs
          t3d(nd) = enepard(nd, ib, 2)
        END DO
        t3 = enepar(ib, 2)
      ELSE
        t3d = 0.d0
      END IF
      IF (enepar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_te
        t3d = 0.d0
      END IF
      IF (totflux .GE. 0.) THEN
        DO nd=1,nbdirs
          x3d(nd) = totfluxd(nd)
        END DO
        x3 = totflux
      ELSE
        DO nd=1,nbdirs
          x3d(nd) = -totfluxd(nd)
        END DO
        x3 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        DO nd=1,nbdirs
          y4d(nd) = totpard(nd)
        END DO
        y4 = totpar
      ELSE
        DO nd=1,nbdirs
          y4d(nd) = -totpard(nd)
        END DO
        y4 = -totpar
      END IF
      IF (x3 .LT. y4) THEN
        DO nd=1,nbdirs
          max9d(nd) = y4d(nd)
        END DO
        max9 = y4
      ELSE
        DO nd=1,nbdirs
          max9d(nd) = x3d(nd)
        END DO
        max9 = x3
      END IF
      temp7 = t3/max9
      temp5 = -((totflux-totpar)*temp7) + 1.0_R8
      DO nd=1,nbdirs
        t4d(nd) = temp5*t1d(nd) - t1*(temp7*(totfluxd(nd)-totpard(nd))+(&
&         totflux-totpar)*(t3d(nd)-temp7*max9d(nd))/max9)
      END DO
      t4 = temp5*t1
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp7 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%she0(nd, icv1, 0) = temp7*(pld%te(nd, icv2)+t4d(nd)-t2d(&
&           nd))
          srwd%she0(nd, icv1, 1) = 0.d0
        END DO
        srw%she0(icv1, 0) = temp7*(pl%te(icv2)+t4-t2)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcene(ib)
      CALL XERRAB('BCENE out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENE_DV

!
  SUBROUTINE B2STBC_PHYS_ENE(ib)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER :: ib, ibw, ibc, ibc0, ib0, is, ism
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, vte, s1, t0, t1, t2, t3, t4, neave, totpar, &
&   totflux, teave, weight, wrk
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(r8) :: y1
    REAL(r8) :: y2
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: y3
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: y4
    REAL(r8) :: max1
    REAL(r8) :: min1
    REAL(r8) :: max2
    REAL(r8) :: min2
    REAL(r8) :: max3
    REAL(r8) :: max4
    REAL(r8) :: min3
    REAL(r8) :: max5
    REAL(r8) :: min4
    REAL(kind=r8) :: abs0
    REAL(r8) :: min5
    REAL(r8) :: max6
    REAL(r8) :: min6
    REAL(kind=r8) :: max7
    REAL(kind=r8) :: max8
    REAL(kind=r8) :: max9
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: arg12
    REAL(r8) :: arg13
    REAL(r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8) :: result11
!
! -- BOUNDARY CONDITIONS FOR ELECTRON ENERGY EQUATION --
!
    SELECT CASE  (bcene(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCENE=1 -- PRESCRIBE THE VALUE OF THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (bcchar(ib) .EQ. 'S' .AND. switch%use_astra .NE. 0) THEN
!srv 14.06.12
          enepar(ib, 1) = teb_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  1 : specified electron temperature ', enepar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 1, ENEPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%she0(icv, 0) = vbig*ne00*geo%fcs(ifc)*enepar(ib, 1)*ev
        srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENE=2 -- PRESCRIBE THE GRADIENT OF THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE =  2 : electron temperature gradient '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1 = INTVERTEX_S_NODIFF_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, &
&         pl%te)
        t2 = INTVERTEX_S_NODIFF_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, &
&         pl%te)
        srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(ev*enepar(ib, 1)*(&
&         geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2&
&         -t1)*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/&
&         geo%fcht(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%te(icv2))
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENE=3 -- SHEATH CONDITIONS, ELECTRON ENERGY TRANSMISSION
!
      CALL XERRAB('b2stbc_phys -- BCENE = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCENE = 15')
!
! -- BCENE=4 -- PRESCRIBE THE VALUE OF THE ELECTRON TEMPERATURE,
!                 WEAKLY A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  4 : weak electron temperature ', enepar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 4, ENEPAR(,1) !> 0')
        CALL XERTST(enepar(ib, 2) .GT. 0.0_R8, &
&             'BCENE = 4, ENEPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%she0(icv, 0) = enepar(ib, 2)*geo%fcs(ifc)*enepar(ib, 1)
        srw%she0(icv, 1) = -(enepar(ib, 2)/ev*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCENE=5 -- PRESCRIBE THE ELECTRON ENERGY FLUX PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE =  5 : electron energy flux per area '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%she0(icv, 0) = enepar(ib, 1)*geo%fcs(ifc)
        srw%she0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCENE=6 -- PRESCRIBE THE TOTAL ELECTRON ENERGY FLUX FOR A
!                 CONSTANT ELECTRON TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENE = 6 not adapted for WG')
!
! -- BCENE=7 -- PRESCRIBE THE ELECTRON TEMPERATURE PROFILE
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') &
&       'BCENE = 7 : specified electron temperature on ', bcchar(ib), &
&       boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*bv_te(icv1)*ev
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCENE=8 -- PRESCRIBE THE TOTAL ELECTRON HEAT FLUX WITH CONSTANT
!                 FLUX DENSITY
!wdk BC not recommended for drifts!
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                      'Compile with -DASTRA option to couple to ASTRA!'&
&                                         )
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  8 : total electron energy flux ', enepar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
      END IF
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%she0(icv1, 0) = fac_he_anom_bc*enepar(ib, 1)/us*geo%fcs(ifc)
        srw%she0(icv1, 1) = 0.0_R8
        IF (switch%mdf_fhe .NE. 0) THEN
!wdk Correction now involves vedia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_f = 0 option
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
          t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)*&
&           geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%fcqalf(&
&           ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne(icv2))*&
&           0.5_R8*(pl%te(icv1)+pl%te(icv2))
          IF (0.0_R8 .LT. t0) THEN
            max1 = t0
          ELSE
            max1 = 0.0_R8
          END IF
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max1
          IF (0.0_R8 .GT. t0) THEN
            min1 = t0
          ELSE
            min1 = 0.0_R8
          END IF
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + min1/pl%te(icv1)
        END IF
      END DO
    CASE (9) 
!
! -- BCENE=9 -- PRESCRIBE THE DECAY LENGTH FOR THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  9 : electron temperature decay length ', enepar(ib, 1)&
&       , ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0.0_R8, &
&             'BCENE = 9, ENEPAR(,1) = 0')
        ism = 0
        DO is=0,ns-1
          IF (bccon(is, ib) .NE. 9 .AND. (.NOT.is_neutral(is))) THEN
            ism = ism + 1
            WRITE(0, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCENE=9'
            WRITE(*, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCENE=9'
          END IF
          IF (bccon(is, ib) .EQ. 1) WRITE(0, *) &
&                      'Should use BCENE=19 in conjunction with BCCON=1'
          IF (ism .GT. 0) THEN
!srv 21.09.12
            WRITE(*, '(1x,a)') &
&           'Please ensure that this boundary condition '//&
&           'is consistent with the density boundary conditions'
          END IF
        END DO
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        sy = geo%fcs(ifc)
        srw%she0(icv1, 0) = 0.0_R8
        srw%she0(icv1, 1) = -(co%hce0(icv1)/enepar(ib, 1)*sy)
        DO is=0,ns-1
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + rt%rza(icv1, is)*&
&           fac_he_anom*pl%te(icv1)*srw%sna0(icv1, 0, is)
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + rt%rza(icv1, is)*&
&           fac_he_anom*srw%sna0(icv1, 1, is)*pl%na(icv1, is)
!! end species loop
        END DO
        IF (switch%mdf_fhe .NE. 0) THEN
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
          t0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*1.5_R8*(geo%fcs(ifc)&
&           *geo%fcqalf(ifc, 0)*dv%veecrb(ifc, 0)+geo%fcs(ifc)*geo%&
&           fcqalf(ifc, 1)*dv%veecrb(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne(&
&           icv2))*0.5_R8*(pl%te(icv1)+pl%te(icv2)))
          IF (0.0_R8 .LT. t0) THEN
            max2 = t0
          ELSE
            max2 = 0.0_R8
          END IF
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max2
          IF (0.0_R8 .GT. t0) THEN
            min2 = t0
          ELSE
            min2 = 0.0_R8
          END IF
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + min2/pl%te(icv1)
        END IF
!! end loop over cells

      END DO
    CASE (10) 
!
! -- BCENE=10 -- Feedback option for core
!
      CALL XERRAB('b2stbc_phys -- BCENE = 10 not adapted for WG')
!
! -- BCENE=11 -- FROM B2STBC_SPB                                       !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
    CASE (11) 
      CALL XERRAB('b2stbc_phys -- BCENE = 11 not adapted for WG')
!
! -- BCENE=12 -- SHEATH CONDITIONS, EL ENERGY TRANSMISSION COEFFICIENT
!
    CASE (12) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,1p,g14.7)') &
&       'BCENE = 12 : sheath electron bc on ', bcchar(ib), &
&       boundary_location(ib), ' with transmission coefficient ', enepar&
&       (ib, 1)
        WRITE(*, '(a)') &
&       'Obsolete. Use drift-compatible BCENE = 15 instead'
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fne(ifc, &
&           0)+dv%fne(ifc, 1))) THEN
          max3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fne(ifc, 0)+dv%&
&           fne(ifc, 1))
        ELSE
          max3 = 0.0_R8
        END IF
        srw%she0(icv, 3) = srw%she0(icv, 3) - enepar(ib, 1)*max3/dv%ne(&
&         icv)
      END DO
    CASE (13) 
!
! -- BCENE=13 -- PRESCRIBE THE ELECTRON ENERGY FLUX PER UNIT AREA
!             -- PROPORTIONAL TO TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE = 13 : electron energy flux per area '&
&                                   //'proportional to temperature ', &
&                                   enepar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%she0(icv, 0) = enepar(ib, 1)*pl%te(icv)*geo%fcs(ifc)
        srw%she0(icv, 1) = 0.0_R8
      END DO
    CASE (14) 
!
! -- BCENE=14 -- leakage option for electron energy
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                'BCENE = 14 : electron energy leakage '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        srw%she0(icv1, 0) = geo%fcs(ifc)*cs*dv%ne(icv1)*fac_he_anom_bc*&
&         enepar(ib, 1)*enepar(ib, 2)*pl%po(icv1)*qe
        srw%she0(icv1, 3) = geo%fcs(ifc)*cs*fac_he_anom_bc*enepar(ib, 1)
        IF (switch%mdf_fhe .NE. 0) THEN
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
          t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)*&
&           geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%fcqalf(&
&           ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne(icv2))*&
&           0.5_R8*(pl%te(icv1)+pl%te(icv2))
          IF (0.0_R8 .LT. t0) THEN
            max4 = t0
          ELSE
            max4 = 0.0_R8
          END IF
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max4
          IF (0.0_R8 .GT. t0) THEN
            min3 = t0
          ELSE
            min3 = 0.0_R8
          END IF
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + min3/pl%te(icv1)
        END IF
      END DO
    CASE (15) 
!
! -- BCENE=15 -- DRIFT-COMPATIBLE SHEATH CONDITION                      !srv 01.02.09 {
!srv 20.09.17 }
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 20.09.17 {
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE = 15 (style = 0) : with GAMMAE =', gammae, ' on ', bcchar&
&       (ib), boundary_location(ib)
        WRITE(*, *) 'BCENE=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY ', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY ', ib&
&                                , ' FOR ALL IONS'
      END IF
!srv 01.02.09 }
!srv added accumulation in order to account twice b.c. for corner cells
      IF (bcene_15_style .EQ. 0) THEN
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENE = 15 (style = 0) : with GAMMAE ='&
&                                     , gammae, ' on ', bcchar(ib), &
&                                     boundary_location(ib)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg12 = pz(icv1)/rz(icv1)
          cs = SQRT(arg12)
          t0 = dv%ne(icv1)
          t1 = 0.0_R8
          DO is=0,ns-1
            IF (.NOT.is_neutral(is) .AND. conpar(is, ib, 2) .GT. 0.0_R8&
&           ) t1 = t1 + co%dna0(icv1, is)/conpar(is, ib, 2)*rt%rza(icv1&
&               , is)*pl%na(icv1, is)
          END DO
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs1 = geo%fcpbs(ifc)
          ELSE
            abs1 = -geo%fcpbs(ifc)
          END IF
          y1 = abs1*t0*cs - dv%fch_p(ifc, 0)*mpg%bcfcor(mpg%bccvp(ib, 1)&
&           +ibc-1)/qe
          IF (0.0_R8 .LT. y1) THEN
            t0 = y1
          ELSE
            t0 = 0.0_R8
          END IF
          t1 = t1*geo%fcs(ifc)
!srv 27.02.13 }
          IF (switch%pot_eq .EQ. 1) THEN
!srv 27.02.13 {
!srv 11.03.09 {
!srv 19.04.13
!wdk to check: correct for gammae?
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - (1.0_R8+gammae)/(&
&             1.0_R8-gammae)*t0 - fac_he_anom_bc*enepar(ib, 2)*t1
!srv 07.11.12
            srw%she0(icv1, 0) = srw%she0(icv1, 0) - qe*(pl%po(icv1)-&
&             potpar(ib, 2))*(t0+t1)
          ELSE
!srv 27.02.13
!srv 11.03.09 {
!srv 19.04.13
!wdk to check: correct for gammae?
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - ((1.0_R8+gammae)/(&
&             1.0_R8-gammae)+switch%delpo)*t0 - (fac_he_anom_bc*enepar(&
&             ib, 2)+switch%delpo)*t1
          END IF
          IF (switch%mdf_fhe .NE. 0) THEN
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp&
&             (ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne&
&             (icv2))*0.5_R8*(pl%te(icv1)+pl%te(icv2))
            IF (0.0_R8 .LT. t0) THEN
              max5 = t0
            ELSE
              max5 = 0.0_R8
            END IF
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + max5
            IF (0.0_R8 .GT. t0) THEN
              min4 = t0
            ELSE
              min4 = 0.0_R8
            END IF
            srw%she0(icv1, 1) = srw%she0(icv1, 1) + min4/pl%te(icv1)
          END IF
        END DO
      ELSE IF (bcene_15_style .EQ. 1) THEN
!wdk    Todo: corrections for BCCON.ne.14
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a)') &
&                              'BCENE = 15 (style = 1) : with GAMMAE = '&
&                                     , gammae, ' and ENEPAR(IB,1) = ', &
&                                     enepar(ib, 1), ' (def = 0), on ', &
&                                     bcchar(ib), boundary_location(ib)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          arg13 = pl%te(icv1)/me
          vte = SQRT(arg13)
          IF (geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3) .GE. &
&             0.) THEN
            wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          ELSE
            wrk = -(geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)&
&             )
          END IF
          IF (wrk .LT. geo%qalfmin) THEN
            IF (geo%fcs(ifc) .GE. 0.) THEN
              abs0 = geo%fcs(ifc)
            ELSE
              abs0 = -geo%fcs(ifc)
            END IF
            s1 = abs0*geo%qalfmax
          ELSE IF (geo%fcpbs(ifc) .GE. 0.) THEN
            s1 = geo%fcpbs(ifc)
          ELSE
            s1 = -geo%fcpbs(ifc)
          END IF
          t0 = dv%ne(icv1)
          t1 = 0.0_R8
          DO is=0,ns-1
            IF (.NOT.is_neutral(is) .AND. conpar(is, ib, 2) .GT. 0.0_R8&
&           ) t1 = t1 + co%dna0(icv1, is)/conpar(is, ib, 2)*rt%rza(icv1&
&               , is)*pl%na(icv1, is)
          END DO
          IF (-50.0_R8 .LT. -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)&
&             )) THEN
            y2 = -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1))
          ELSE
            y2 = -50.0_R8
          END IF
          IF (0.0_R8 .GT. y2) THEN
            min5 = y2
          ELSE
            min5 = 0.0_R8
          END IF
!lkw 31.03.2023
          arg13 = 1.0_R8/(2.0_R8*pi)
          result10 = SQRT(arg13)
          result20 = EXPU2(min5)
          t0 = s1*t0*result10*vte*result20
          t1 = t1*geo%fcs(ifc)
          IF (switch%pot_eq .EQ. 1) THEN
!wdk to check: correct 2nd term for gammae?
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - (1.0_R8+gammae+&
&             enepar(ib, 1)+switch%stab_coeff_sheath_te)*t0 - &
&             fac_he_anom_bc*enepar(ib, 2)*t1
!lkw 31.03.2023
!wdk to check: correct 2nd term for gammae?
            srw%she0(icv1, 0) = srw%she0(icv1, 0) - ((1.0_R8-gammae)*qe*&
&             (pl%po(icv1)-potpar(ib, 2))-switch%stab_coeff_sheath_te*pl&
&             %te(icv1))*t0 - qe*(pl%po(icv1)-potpar(ib, 2))*t1
            IF (switch%b2nppo_restr_po .NE. 0.0_R8 .AND. srw%she0(icv1, &
&               0) + srw%she0(icv1, 1)*pl%te(icv1) .GT. 0.0_R8) srw%she0&
&             (icv1, :) = 0.0_R8
          ELSE
            arg12 = pz(icv1)/rz(icv1)
            cs = SQRT(arg12)
!srv 11.03.09 {
!wdk to check: correct for gammae?
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - s1*dv%ne(icv1)*cs*(&
&             1.0_R8+gammae+enepar(ib, 1)+(1.0_R8-gammae)*switch%delpo) &
&             - (fac_he_anom_bc*enepar(ib, 2)+switch%delpo)*t1
          END IF
          IF (switch%mdf_fhe .NE. 0) THEN
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp&
&             (ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne&
&             (icv2))*0.5_R8*(pl%te(icv1)+pl%te(icv2))
            IF (0.0_R8 .LT. t0) THEN
              max6 = t0
            ELSE
              max6 = 0.0_R8
            END IF
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + max6
            IF (0.0_R8 .GT. t0) THEN
              min6 = t0
            ELSE
              min6 = 0.0_R8
            END IF
            srw%she0(icv1, 1) = srw%she0(icv1, 1) + min6/pl%te(icv1)
          END IF
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=15, incorrect bcene_15_style value'&
&            )
      END IF
    CASE (16) 
!
! -- BCENE=16 -- Feedback boundary condition with constant temperature
!
!
      IF (switch%bcene_16_style .EQ. 0) THEN
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&         'BCENE = 16 (style = 0) : '//&
&         'electron temperature feedback by flux ', enepar(ib, 1), &
&         ' with ', enepar(ib, 2), ' on ', bcchar(ib), boundary_location&
&         (ib)
          CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        END IF
!       ..compute average temperature on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t0 = t0 + geo%fcs(ifc)*dv%ne(icv1)
          t1 = t1 + geo%fcs(ifc)*dv%ne(icv1)*pl%te(icv1)
          totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1))*mpg%bcfcor&
&           (mpg%bccvp(ib, 1)+ibc-1)
        END DO
        t1 = t1/t0
        totpar = fac_he_anom_bc*enepar(ib, 1)
        IF (enepar(ib, 2) .GT. 0.0_R8) t3 = enepar(ib, 2)
        IF (enepar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
        IF (totflux .GE. 0.) THEN
          x1 = totflux
        ELSE
          x1 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          y3 = totpar
        ELSE
          y3 = -totpar
        END IF
        IF (x1 .LT. y3) THEN
          max7 = y3
        ELSE
          max7 = x1
        END IF
        t2 = (1.0_R8-t3*(totflux-totpar)/max7)*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&             'bcene=16: curr_flux, desired_flux, old/new temperature, '&
&                                        , totflux, totpar, t1/qe, t2/qe
!       ..impose temperature
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE IF (switch%bcene_16_style .EQ. 1) THEN
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a)') 'BCENE = 16 (style = 1) : '//&
&         'Given integrated electron heat flux with constant Te'
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcene(ibw) .EQ. bcene(ib)) THEN
              WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location&
&             (ibw)
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCENE = 16 only applicable to core boundaries !')
              CALL XERTST(enepar(ibw, 1) .NE. 0.0_R8, &
&                   'faulty parameter enepar1')
            END IF
          END DO
        END IF
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bcene) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              senepar = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bcene(ibw) .EQ. bcene(ib)) senepar = senepar +&
&                   enepar(ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCENE=16: Summed value is ', senepar
            tes = 0.0_R8
            volsum = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  tes = tes + pl%te(icv)*geo%cvvol(icv)
                  volsum = volsum + geo%cvvol(icv)
                END DO
              END IF
            END DO
            tes = tes/volsum
            totflux = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  IF (switch%mdf_fhe .NE. 0) THEN
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhe_mdf(ifc, 0)+dv%fhe_mdf(ifc, 1))
                    totflux = totflux - pl%te(icv)*dv%ne(icv)*geo%fcs(&
&                     ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv%&
&                     vaecrb(ifc, 0, ns-1)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&                     ifc, 1, ns-1)*geo%fcqalf(ifc, 1))
                  ELSE
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1))
                  END IF
                END DO
              END IF
            END DO
            IF (enepar(ib, 2) .GT. 0.0_R8) t3 = enepar(ib, 2)
            IF (enepar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
            IF (totflux .GE. 0.) THEN
              x2 = totflux
            ELSE
              x2 = -totflux
            END IF
            IF (x2 .LT. senepar) THEN
              max8 = senepar
            ELSE
              max8 = x2
            END IF
            tes = tes*(1.0_R8-t3*(totflux-senepar)/max8)
            WRITE(*, '(3(a,es14.7))') ' TES=', tes/ev, ' totflux=', &
&           totflux, ' SENEPAR=', senepar
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%she0(icv, 0) = vbig*ne00*tes*geo%fcs(ifc)
                  srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
                END DO
              END IF
            END DO
            once_bcene = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCENE=16, ONLY AVAILABLE FOR CORE!')
        END IF
      ELSE
        CALL XERRAB(' Incorrect style of boundary condition')
      END IF
    CASE (17) 
!
! -- BCENE=17 -- Feedback boundary condition with constant shared temperature
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 17 : shared temperature feedback by flux ', enepar(ib, &
&       1), ' with ', enepar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        CALL XERTST(enepar(ib, 2) .GT. 0, 'faulty parameter enepar2')
        CALL XERTST(bcene(ib) .EQ. bceni(ib), &
&             'both bcene and bceni should be set to 17')
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        CALL XERTST(enipar(ib, 2) .GT. 0, 'faulty parameter enipar2')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%fhi(ifc&
&           , 0)+dv%fhi(ifc, 1)+st_ext%fhi(ifc, 0)+st_ext%fhi(ifc, 1))*&
&           mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          IF (bc_type16_kinetic_energy .EQ. 1) THEN
            DO is=0,ns-1
              result11 = INTFACE_S(ifc, ncv, nfc, mpg%fccv, geo%fcvol, &
&               dv%kinrgy(1, is))
              totflux = totflux - (1.0_R8-switch%boris)*mpg%bcfcor(mpg%&
&               bccvp(ib, 1)+ibc-1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, &
&               is))*result11
            END DO
            DO is=0,st_ext%ns-1
              result11 = INTFACE_S(ifc, ncv, nfc, mpg%fccv, geo%fcvol, &
&               st_ext%ua(1, is))
              totflux = totflux - (1.0_R8-switch%boris)*mpg%bcfcor(mpg%&
&               bccvp(ib, 1)+ibc-1)*(st_ext%fa(ifc, 0, is)+st_ext%fa(ifc&
&               , 1, is))*0.5_R8*st_ext%am(is)*mp*result11**2
            END DO
          END IF
          t0 = t0 + (pl%te(icv)*dv%ne(icv)+pl%ti(icv)*dv%ni(icv, 0))*geo&
&           %cvvol(icv)
          weight = weight + (dv%ne(icv)+dv%ni(icv, 0))*geo%cvvol(icv)
        END DO
        t0 = t0/weight
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        t1 = (1.0_R8-enepar(ib, 2)*(totflux*enepar(ib, 1)/(enepar(ib, 1)&
&         +enipar(ib, 1))-enepar(ib, 1))/enepar(ib, 1)-enipar(ib, 2)*(&
&         totflux*enipar(ib, 1)/(enepar(ib, 1)+enipar(ib, 1))-enipar(ib&
&         , 1))/enipar(ib, 1))*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New shared temp :', t0/qe&
&                                        , t1/qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          srw%she0(icv, 0) = vbig*ne00*t1*geo%fcs(ifc)
          srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
          srw%shi0(icv, 0) = vbig*ne00*t1*geo%fcs(ifc)
          srw%shi0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=17, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (18) 
!
! -- BCENE=18 -- FRACTIONAL DROP CONDITION (FOR EDGE2D COMPARISON)
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE = 18 : electron temperature fractional drop ', enepar(ib&
&       , 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .LT. 1.0_R8, &
&             'BCENE = 18, ENEPAR(,1) => 1')
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t1 = (1.0_R8-enepar(ib, 1))*pl%te(icv2)
        srw%she0(icv1, 0) = vbig*ne00*t1*geo%fcs(ifc)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (19) 
!
! -- BCENE=19 -- PRESCRIBE THE DECAY LENGTH FOR THE ELECTRON TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENE = 19 not adapted for WG')
!
! -- BCENE=20 -- Feedback boundary condition with constant temperature
!
    CASE (20) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 20 : electron temperature feedback by flux ', enepar(ib&
&       , 1), ' with ', enepar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        teave = 0.0_R8
        neave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fhe&
&           (ifc, 0)+dv%fhe(ifc, 1))
          t0 = t0 + pl%te(icv1)*dv%ne(icv1)*geo%cvvol(icv1)
          weight = weight + dv%ne(icv1)*geo%cvvol(icv1)
          teave = teave + pl%te(icv2)*dv%ne(icv2)*geo%cvvol(icv2)
          neave = neave + dv%ne(icv2)*geo%cvvol(icv2)
        END DO
        t0 = t0/weight
        teave = teave/neave
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        IF (enepar(ib, 2) .GT. 0.0_R8) t3 = enepar(ib, 2)
        IF (enepar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
        t1 = (1.0_R8-t3*(totflux-enepar(ib, 1))/enepar(ib, 1))*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New electron temp :', t0/&
&                                        qe, t1/qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1*pl%te(icv2)/&
&           teave
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=20, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (21) 
!
! -- BCENE=21 -- constant temperature scaled by temperature on the ring bc_type21_ref away
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 21 : fixed electron temperature '//&
&       '(modified by nearby ring) ', enepar(ib, 1), ' with ', enepar(ib&
&       , 2), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0.0_R8, &
&             'faulty parameter enepar1')
      END IF
      IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'N') .OR. bcchar(ib)&
&         .EQ. 'A') THEN
        teave = 0.0_R8
        neave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          teave = teave + pl%te(icv)*dv%ne(icv)*geo%cvvol(icv)
          neave = neave + dv%ne(icv)*geo%cvvol(icv)
        END DO
        teave = teave/neave
        IF (enepar(ib, 2) .GT. 0.0_R8) t3 = enepar(ib, 2)
        IF (enepar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%she0(icv1, 0) = vbig*ne00*enepar(ib, 1)*ev*geo%fcs(ifc)*(&
&           1.0_R8-t3+t3*pl%te(icv2)/teave)
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=21, NOT AVAILABLE FOR W,E')
      END IF
    CASE (22) 
!
! -- BCENE=22 -- RADIAL LEAKAGE CONDITION FOR THE ELECTRON TEMPERATURE   !srv 23.07.10 {
!                SPECIFIES A TEMPERATURE GRADIENT SUCH THAT THE DIFFUSIVE
!                FLUX IS SET TO BE EQUIVALENT TO A LEAKAGE VELOCITY, IN
!                UNITS OF THE ELECTRON THERMAL VELOCITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCENE = 22 : with ENEPAR(IB,1)= ', &
&                                   enepar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
!wdk    Notes:
!wdk     * need correction for misaligned grids -> t1
!wdk     * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg13 = pl%te(icv1)/me
        vte = SQRT(arg13)
        t0 = geo%fcqalf(ifc, 1)
        t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&         fcqbet(ifc, 0)
        srw%she0(icv1, 0) = vbig*ne00*ev*co%chce(ifc, 1)*(t0*pl%te(icv2)&
&         -mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1*(pl%te(mpg%fcvx(ifc, 2)&
&         )-pl%te(mpg%fcvx(ifc, 1))))
        srw%she0(icv1, 1) = -(vbig*ne00*ev*(co%chce(ifc, 1)*t0-enepar(ib&
&         , 1)*geo%fcs(ifc)*vte*dv%ne(icv1)))
      END DO
    CASE (23) 
!
!
! -- BCENE=23 -- Prescribe the value of the electron temperature, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENE=23 intended for core boundaries only!')
        END DO
        IF (switch%use_astra .NE. 0) enepar(ib, 1) = teb_astra*1.0e3_R8
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified electron temp. + perturbation', enepar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 23, ENEPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%te(icv2)
          END DO
        END IF
      END DO
      t1 = t1/t0
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%te(icv2)+enepar(&
&         ib, 1)*ev-t1)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (24) 
!
! -- BCENE=24 -- Feedback on the total electron energy flux, by imposing a flux surface
!                averaged temperature, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENE=24 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified electron heat flux', &
&       enepar(ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 24, ENEPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bcene(ib0) .NE. 24) CALL XERRAB(&
&                                      'BCENE=24: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%te(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%te(icv2)
            totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
          END DO
          totpar = totpar + enepar(ib0, 1)
        END IF
      END DO
      totpar = fac_he_anom_bc*totpar
      t1 = t1/t0
      t2 = t2/t0
      IF (enepar(ib, 2) .GT. 0.0_R8) t3 = enepar(ib, 2)
      IF (enepar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
      IF (totflux .GE. 0.) THEN
        x3 = totflux
      ELSE
        x3 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y4 = totpar
      ELSE
        y4 = -totpar
      END IF
      IF (x3 .LT. y4) THEN
        max9 = y4
      ELSE
        max9 = x3
      END IF
      t4 = (1.0_R8-t3*(totflux-totpar)/max9)*t1
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%te(icv2)+t4-t2)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcene(ib)
      CALL XERRAB('BCENE out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENE

!  Differentiation of b2stbc_phys_eni_dv in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: enipar enipard senipar senipard
!                tisd nivsd *(srwd.shi0) *(srw.shi0) vbc csbc vbcd
!                csbcd
!   with respect to varying inputs: conpar conpard mompar enipar
!                enipard senipar senipard tisd nivsd *(srwd.shi0)
!                *(srwd.sna0) *(dv.fna) *(dv.fhi) *(dv.fhi_mdf)
!                *(dv.fhipsch) *(dv.fhm) *(dv.ne) *(dv.ni) *(dv.vadia)
!                *(dv.vaecrb) *(rtd.rza) *(rt.rza) *(dvd.fna) *(dvd.fhi)
!                *(dvd.fhi_mdf) *(dvd.fhipsch) *(dvd.fhm) *(dvd.ne)
!                *(dvd.ni) *(dvd.vadia) *(dvd.vaecrb) *(srw.shi0)
!                *(srw.sna0) *(cod.chci) *(cod.hci0) *(cod.hcn0)
!                *(cod.dna0) *(co.chci) *(co.hci0) *(co.hcn0) *(co.dna0)
!                *(pld.na) *(pld.ua) *(pld.te) *(pld.ti) *(pl.na)
!                *(pl.ua) *(pl.te) *(pl.ti) pzd vbc rzd rz csbc
!                vbcd csbcd pz
!   Plus diff mem management of: srwd.shi0:in srwd.sna0:in dv.fna:in
!                dv.fhi:in dv.fhi_mdf:in dv.fhipsch:in dv.fhm:in
!                dv.ne:in dv.ni:in dv.vadia:in dv.vaecrb:in geo.fcs:in
!                geo.vxvol:in rtd.rza:in rt.rza:in dvd.fna:in dvd.fhi:in
!                dvd.fhi_mdf:in dvd.fhipsch:in dvd.fhm:in dvd.ne:in
!                dvd.ni:in dvd.vadia:in dvd.vaecrb:in srw.shi0:in
!                srw.sna0:in cod.chci:in cod.hci0:in cod.hcn0:in
!                cod.dna0:in co.chci:in co.hci0:in co.hcn0:in co.dna0:in
!                pld.na:in pld.ua:in pld.te:in pld.ti:in pl.na:in
!                pl.ua:in pl.te:in pl.ti:in
!  Differentiation of b2stbc_phys_eni in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: enipar senipar *(srw.shi0)
!                vbc csbc
!   with respect to varying inputs: conpar mompar enipar senipar
!                *(dv.fna) *(dv.fhi) *(dv.fhi_mdf) *(dv.fhipsch)
!                *(dv.fhm) *(dv.ne) *(dv.ni) *(dv.vadia) *(dv.vaecrb)
!                *(rt.rza) *(srw.shi0) *(srw.sna0) *(co.chci) *(co.hci0)
!                *(co.hcn0) *(co.dna0) *(pl.na) *(pl.ua) *(pl.te)
!                *(pl.ti) vbc rz csbc pz
!   Plus diff mem management of: dv.fna:in dv.fhi:in dv.fhi_mdf:in
!                dv.fhipsch:in dv.fhm:in dv.ne:in dv.ni:in dv.vadia:in
!                dv.vaecrb:in mpg.bcfcor:in geo.fcs:in geo.vxvol:in
!                rt.rza:in srw.shi0:in srw.sna0:in co.chci:in co.hci0:in
!                co.hcn0:in co.dna0:in pl.na:in pl.ua:in pl.te:in
!                pl.ti:in
!
  SUBROUTINE B2STBC_PHYS_ENI_DV_DV(ib, nbdirs, nbdirs0)
    USE B2MOD_DIFFSIZES
!  Hint: nbdirsmax0 should be the maximum number of differentiation directions
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: ib, ibw, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: t0, t1, t2, t3, t4, dsh, vt, vbnd, niave, tiave, &
&   totpar, totflux, weight, cs, csb, wrk
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: t0d0, t1d0, t2d0, t3d0, t4d0&
&   , dshd0, vtd0, vbndd0, niaved0, tiaved0, totpard0, totfluxd0, &
&   weightd0, csd0, csbd0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: t0d, t1d, t2d, t3d, t4d, dshd&
&   , vtd, vbndd, niaved, tiaved, totpard, totfluxd, weightd, csd, csbd
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: t0dd, t1dd, t2dd&
&   , t3dd, t4dd, dshdd, vtdd, vbnddd, niavedd, tiavedd, totpardd, &
&   totfluxdd, weightdd, csdd, csbdd
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    LOGICAL :: decay_length_ok
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC NINT
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x1dd
    REAL(kind=r8) :: y1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: y1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y1dd
    REAL(kind=r8) :: x2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x2d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x2d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x2dd
    REAL(kind=r8) :: y2
