    REAL(kind=r8), DIMENSION(nbdirsmax) :: x4d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x4dd
    REAL(kind=r8) :: x5
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x5d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x5d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x5dd
    REAL(kind=r8) :: x6
