    REAL(kind=r8), DIMENSION(nbdirsmax) :: x6d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x6dd
    REAL(kind=r8) :: y3
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: y3d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y3d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y3dd
    REAL(r8) :: max1
    REAL(r8), DIMENSION(nbdirsmax0) :: max1d0
    REAL(r8), DIMENSION(nbdirsmax) :: max1d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max1dd
    REAL(r8) :: min1
    REAL(r8), DIMENSION(nbdirsmax0) :: min1d0
    REAL(r8), DIMENSION(nbdirsmax) :: min1d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min1dd
    REAL(r8) :: max2
    REAL(r8), DIMENSION(nbdirsmax0) :: max2d0
    REAL(r8), DIMENSION(nbdirsmax) :: max2d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max2dd
    REAL(r8) :: min2
    REAL(r8), DIMENSION(nbdirsmax0) :: min2d0
    REAL(r8), DIMENSION(nbdirsmax) :: min2d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min2dd
    REAL(r8) :: max3
    REAL(r8), DIMENSION(nbdirsmax0) :: max3d0
    REAL(r8), DIMENSION(nbdirsmax) :: max3d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max3dd
    REAL(r8) :: max4
    REAL(r8), DIMENSION(nbdirsmax0) :: max4d0
    REAL(r8), DIMENSION(nbdirsmax) :: max4d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max4dd
    REAL(r8) :: min3
    REAL(r8), DIMENSION(nbdirsmax0) :: min3d0
    REAL(r8), DIMENSION(nbdirsmax) :: min3d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min3dd
    REAL(kind=r8) :: abs0
    REAL(r8) :: max5
    REAL(r8), DIMENSION(nbdirsmax0) :: max5d0
    REAL(r8), DIMENSION(nbdirsmax) :: max5d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max5dd
    REAL(r8) :: min4
    REAL(r8), DIMENSION(nbdirsmax0) :: min4d0
    REAL(r8), DIMENSION(nbdirsmax) :: min4d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min4dd
    REAL(kind=r8) :: max6
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max6d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max6d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max6dd
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: abs4
    REAL(r8) :: max7
    REAL(r8), DIMENSION(nbdirsmax0) :: max7d0
    REAL(r8), DIMENSION(nbdirsmax) :: max7d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max7dd
    REAL(r8) :: min5
    REAL(r8), DIMENSION(nbdirsmax0) :: min5d0
    REAL(r8), DIMENSION(nbdirsmax) :: min5d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min5dd
    REAL(kind=r8) :: max8
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max8d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max8d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max8dd
    REAL(kind=r8) :: max9
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max9d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max9d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max9dd
    REAL(kind=r8) :: max10
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max10d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max10d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max10dd
    REAL(kind=r8) :: max11
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max11d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max11d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max11dd
    REAL(kind=r8) :: max12
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max12d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max12d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max12dd
    REAL(kind=r8) :: abs5
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: arg12d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg12dd
    REAL(r8) :: arg13
    REAL(r8), DIMENSION(nbdirsmax0) :: arg13d0
    REAL(r8), DIMENSION(nbdirsmax) :: arg13d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg13dd
    REAL(kind=r8) :: result10
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: result10d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result10d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: result10dd
    REAL(kind=r8) :: result20
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: result20d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result20d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: result20dd
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: tempd
    REAL(kind=r8) :: temp0
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp0d
    REAL(kind=r8) :: temp1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp1d
    REAL(kind=r8) :: temp2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp2d
    REAL(r8) :: temp3
    REAL(r8), DIMENSION(nbdirsmax0) :: temp3d
    REAL(r8) :: temp4
    REAL(r8), DIMENSION(nbdirsmax0) :: temp4d
    REAL(r8) :: temp5
    REAL(r8), DIMENSION(nbdirsmax0) :: temp5d
    REAL(kind=r8) :: temp6
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp6d
    INTEGER :: nbdirs
    INTEGER :: nd0
    REAL(kind=r8) :: temp7
    REAL(r8) :: temp8
    REAL(r8) :: temp9
    REAL(r8) :: temp10
    REAL(kind=r8) :: temp11
    REAL(kind=r8) :: temp12
    REAL(kind=r8) :: temp13
    REAL(kind=r8) :: temp14
    REAL(kind=r8) :: temp15
    REAL(kind=r8) :: temp16
    INTEGER :: nbdirs0
!
! -- BOUNDARY CONDITIONS FOR ION ENERGY EQUATIONS --
!
    SELECT CASE  (bceni(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCENI=1 -- PRESCRIBE THE VALUE OF THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (bcchar(ib) .EQ. 'S' .AND. switch%use_astra .NE. 0) THEN
!srv 14.06.12
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              enipardd(nd0, nd, ib, 1) = 0.D0
            END DO
            enipard(nd, ib, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            enipard0(nd0, ib, 1) = 0.D0
          END DO
          enipar(ib, 1) = tib_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  1 : specified ion temperature ', enipar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 1, ENIPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp = geo%fcs(ifc)*ev
        DO nd=1,nbdirs
          temp7 = temp*vbig*ne00
          DO nd0=1,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 0) = temp7*enipardd(nd0, nd, ib, 1&
&             )
            srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%shi0(nd, icv1, 0) = temp7*enipard(nd, ib, 1)
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 0) = vbig*ne00*temp*enipard0(nd0, ib, 1)
          srwd0%shi0(nd0, icv1, 1) = 0.D0
        END DO
        srw%shi0(icv1, 0) = vbig*ne00*enipar(ib, 1)*temp
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENI=2 -- PRESCRIBE THE GRADIENT OF THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI =  2 : ion temperature gradient '&
&                                   , enipar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1dd = 0.D0
        CALL INTVERTEX_S_DV_DV(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ti, &
&                        pld0%ti, pld%ti, pldd%ti, t1, t1d0, t1d, t1dd, &
&                        nbdirs, nbdirs0)
        t2dd = 0.D0
        CALL INTVERTEX_S_DV_DV(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ti, &
&                        pld0%ti, pld%ti, pldd%ti, t2, t2d0, t2d, t2dd, &
&                        nbdirs, nbdirs0)
        temp = vbig*ne00*geo%fcs(ifc)
        temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
        temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, &
&         2))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          temp7 = geo%fcqgam(ifc, 0)*temp0*ev
          DO nd0=1,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 0) = temp*(temp7*enipardd(nd0, nd&
&             , ib, 1)-temp1*temp2*(t2dd(nd0, nd)-t1dd(nd0, nd))/geo%&
&             fcht(ifc)+pldd%ti(nd0, nd, icv2))
            srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%shi0(nd, icv1, 0) = temp*(temp7*enipard(nd, ib, 1)-temp1*&
&           temp2*((t2d(nd)-t1d(nd))/geo%fcht(ifc))+pld%ti(nd, icv2))
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 0) = temp*(temp0*ev*geo%fcqgam(ifc, 0)*&
&           enipard0(nd0, ib, 1)-temp1*temp2*(t2d0(nd0)-t1d0(nd0))/geo%&
&           fcht(ifc)+pld0%ti(nd0, icv2))
          srwd0%shi0(nd0, icv1, 1) = 0.D0
        END DO
        srw%shi0(icv1, 0) = temp*(temp0*(geo%fcqgam(ifc, 0)*(ev*enipar(&
&         ib, 1)))-temp1*(temp2*((t2-t1)/geo%fcht(ifc)))+pl%ti(icv2))
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENI=3 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
      CALL XERRAB('b2stbc_phys -- BCENI = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCENI = 15')
!
! -- BCENI=4 -- PRESCRIBE THE VALUE OF THE ION TEMPERATURE, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  4 : weak ion temperature ', enipar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 4, ENIPAR(,1) !> 0')
!srv 02.02.11
        CALL XERTST(enipar(ib, 2) .GT. 0.0_R8, &
&             'BCENI = 4, ENIPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 0) = geo%fcs(ifc)*(enipard(nd, ib&
&             , 2)*enipard0(nd0, ib, 1)+enipar(ib, 1)*enipardd(nd0, nd, &
&             ib, 2)+enipard(nd, ib, 1)*enipard0(nd0, ib, 2)+enipar(ib, &
&             2)*enipardd(nd0, nd, ib, 1))
            srwdd%shi0(nd0, nd, icv1, 1) = -(geo%fcs(ifc)*enipardd(nd0, &
&             nd, ib, 2)/ev)
          END DO
          srwd%shi0(nd, icv1, 0) = geo%fcs(ifc)*(enipar(ib, 1)*enipard(&
&           nd, ib, 2)+enipar(ib, 2)*enipard(nd, ib, 1))
          srwd%shi0(nd, icv1, 1) = -(geo%fcs(ifc)*enipard(nd, ib, 2)/ev)
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 0) = geo%fcs(ifc)*(enipar(ib, 1)*&
&           enipard0(nd0, ib, 2)+enipar(ib, 2)*enipard0(nd0, ib, 1))
          srwd0%shi0(nd0, icv1, 1) = -(geo%fcs(ifc)*enipard0(nd0, ib, 2)&
&           /ev)
        END DO
        srw%shi0(icv1, 0) = enipar(ib, 2)*geo%fcs(ifc)*enipar(ib, 1)
        srw%shi0(icv1, 1) = -(enipar(ib, 2)/ev*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCENI=5 -- PRESCRIBE THE ION ENERGY FLUX PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI =  5 : ion energy flux per area '&
&                                   , enipar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%shi0(nd0, nd, icv, 0) = geo%fcs(ifc)*enipardd(nd0, nd&
&             , ib, 1)
            srwdd%shi0(nd0, nd, icv, 1) = 0.D0
          END DO
          srwd%shi0(nd, icv, 0) = geo%fcs(ifc)*enipard(nd, ib, 1)
          srwd%shi0(nd, icv, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv, 0) = geo%fcs(ifc)*enipard0(nd0, ib, 1)
          srwd0%shi0(nd0, icv, 1) = 0.D0
        END DO
        srw%shi0(icv, 0) = enipar(ib, 1)*geo%fcs(ifc)
        srw%shi0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCENI=6 -- PRESCRIBE THE TOTAL ION ENERGY FLUX FOR A
!                 CONSTANT ION TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENI = 6 not adapted for WG')
!
! -- BCENI=7 -- PRESCRIBE THE ION TEMPERATURE PROFILE
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') 'BCENI = 7 : specified ion temperature on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 0) = 0.D0
            srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%shi0(nd, icv1, 0) = 0.d0
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 0) = 0.D0
          srwd0%shi0(nd0, icv1, 1) = 0.D0
        END DO
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*bv_ti(icv1)*ev
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCENI=8 -- PRESCRIBE THE TOTAL ION HEAT FLUX WITH CONSTANT
!                 FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 28.07.11
        IF (switch%use_astra .NE. 0) THEN
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              enipardd(nd0, nd, ib, 1) = 0.D0
            END DO
            enipard(nd, ib, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            enipard0(nd0, ib, 1) = 0.D0
          END DO
          enipar(ib, 1) = fhib_astra
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  8 : total ion energy flux', enipar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
      max1dd = 0.D0
      t0dd = 0.D0
      min1dd = 0.D0
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = fac_he_anom_bc*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 0) = temp2*enipardd(nd0, nd, ib, 1&
&             )/us
            srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%shi0(nd, icv1, 0) = temp2*enipard(nd, ib, 1)/us
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 0) = temp2*enipard0(nd0, ib, 1)/us
          srwd0%shi0(nd0, icv1, 1) = 0.D0
        END DO
        srw%shi0(icv1, 0) = temp2*(enipar(ib, 1)/us)
        srw%shi0(icv1, 1) = 0.0_R8
        IF (switch%mdf_fhi .NE. 0) THEN
!wdk Correction now involves vedia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_fhi = 0 option
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1, 0&
&               ) + temp2*(dvdd%fhipsch(nd0, nd, ifc, 0)+dvdd%fhipsch(&
&               nd0, nd, ifc, 1))
            END DO
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*(dvd&
&             %fhipsch(nd, ifc, 0)+dvd%fhipsch(nd, ifc, 1))
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + temp2*&
&             (dvd0%fhipsch(nd0, ifc, 0)+dvd0%fhipsch(nd0, ifc, 1))
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(dv%fhipsch(ifc&
&           , 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              t0dd(nd0, nd) = 0.D0
            END DO
            t0d(nd) = 0.d0
          END DO
          t0d0 = 0.D0
          DO is=0,ns-1
            temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp3 = pl%ti(icv1) + pl%ti(icv2)
            temp4 = pl%na(icv1, is) + pl%na(icv2, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              temp3d(nd0) = pld0%ti(nd0, icv1) + pld0%ti(nd0, icv2)
              temp4d(nd0) = pld0%na(nd0, icv1, is) + pld0%na(nd0, icv2, &
&               is)
              temp5d(nd0) = temp3*temp4d(nd0) + temp4*temp3d(nd0)
              tempd(nd0) = temp1*dvd0%vadia(nd0, ifc, 0, is) + temp0*&
&               dvd0%vadia(nd0, ifc, 1, is)
            END DO
            temp5 = temp4*temp3
            temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1, &
&             is)
            DO nd=1,nbdirs
              temp7 = temp1*dvd%vadia(nd, ifc, 0, is) + temp0*dvd%vadia(&
&               nd, ifc, 1, is)
              temp8 = pld%ti(nd, icv1) + pld%ti(nd, icv2)
              temp9 = pld%na(nd, icv1, is) + pld%na(nd, icv2, is)
              temp10 = temp3*temp9 + temp4*temp8
              DO nd0=1,nbdirs0
                t0dd(nd0, nd) = t0dd(nd0, nd) + temp2*(temp7*temp5d(nd0)&
&                 +temp5*(temp1*dvdd%vadia(nd0, nd, ifc, 0, is)+temp0*&
&                 dvdd%vadia(nd0, nd, ifc, 1, is))+temp10*tempd(nd0)+&
&                 temp*(temp9*temp3d(nd0)+temp3*(pldd%na(nd0, nd, icv1, &
&                 is)+pldd%na(nd0, nd, icv2, is))+temp8*temp4d(nd0)+&
&                 temp4*(pldd%ti(nd0, nd, icv1)+pldd%ti(nd0, nd, icv2)))&
&                 )
              END DO
              t0d(nd) = t0d(nd) + temp2*(temp5*temp7+temp*temp10)
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = t0d0(nd0) + temp2*(temp5*tempd(nd0)+temp*&
&               temp5d(nd0))
            END DO
            t0 = t0 + temp2*(temp*temp5)
          END DO
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max1dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              max1d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              max1d0(nd0) = t0d0(nd0)
            END DO
            max1 = t0
          ELSE
            max1 = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                max1dd(nd0, nd) = 0.D0
              END DO
              max1d(nd) = 0.d0
            END DO
            max1d0 = 0.D0
          END IF
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1, 0&
&               ) + max1dd(nd0, nd)
            END DO
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + max1d(nd)
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + max1d0&
&             (nd0)
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max1
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                min1dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              min1d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              min1d0(nd0) = t0d0(nd0)
            END DO
            min1 = t0
          ELSE
            min1 = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                min1dd(nd0, nd) = 0.D0
              END DO
              min1d(nd) = 0.d0
            END DO
            min1d0 = 0.D0
          END IF
          temp10 = min1/pl%ti(icv1)
          DO nd0=1,nbdirs0
            temp5d(nd0) = (min1d0(nd0)-temp10*pld0%ti(nd0, icv1))/pl%ti(&
&             icv1)
          END DO
          temp5 = temp10
          DO nd=1,nbdirs
            temp10 = (min1d(nd)-temp5*pld%ti(nd, icv1))/pl%ti(icv1)
            DO nd0=1,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 1) = srwdd%shi0(nd0, nd, icv1, 1&
&               ) + (min1dd(nd0, nd)-pld%ti(nd, icv1)*temp5d(nd0)-temp5*&
&               pldd%ti(nd0, nd, icv1)-temp10*pld0%ti(nd0, icv1))/pl%ti(&
&               icv1)
            END DO
            srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + temp10
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 1) = srwd0%shi0(nd0, icv1, 1) + temp5d&
&             (nd0)
          END DO
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + temp5
        END IF
      END DO
    CASE (9) 
!
! -- BCENI=9 -- PRESCRIBE THE DECAY LENGTH FOR THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  9 : ion temperature decay length ', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0.0_R8, &
&             'BCENI = 9, ENIPAR(,1) = 0')
        decay_length_ok = .true.
        DO is=0,ns-1
          decay_length_ok = decay_length_ok .AND. ((bccon(is, ib) .EQ. 9&
&           .OR. bccon(is, ib) .EQ. 0) .OR. (is_neutral(is) .AND. switch&
&           %use_eirene .EQ. 1))
          IF (bccon(is, ib) .EQ. 1) WRITE(0, *) &
&                      'Should use BCENI=19 in conjunction with BCCON=1'
        END DO
        IF (.NOT.decay_length_ok) THEN
          WRITE(0, *) 'Should use BCENI.EQ.9 together with BCCON=9'
          WRITE(*, *) 'Should use BCENI.EQ.9 together with BCCON=9'
!srv 21.09.12
          WRITE(*, '(1x,a)') &
&         'Please ensure that this boundary condition '//&
&         'is consistent with '//'the density boundary condition'
          min2dd = 0.D0
          t0dd = 0.D0
          max2dd = 0.D0
        ELSE
          min2dd = 0.D0
          t0dd = 0.D0
          max2dd = 0.D0
        END IF
      ELSE
        min2dd = 0.D0
        t0dd = 0.D0
        max2dd = 0.D0
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        sy = geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 0) = 0.D0
          END DO
          srwd%shi0(nd, icv1, 0) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 0) = 0.D0
        END DO
        srw%shi0(icv1, 0) = 0.0_R8
        IF (switch%recycle_afn .EQ. 0 .OR. switch%tn_style .NE. 0) THEN
!! Note that
!! if tn_style=0: hci0 includes contributions from all ions and all fluid neutrals
!! if tn_style=1: hci0 includes contributions from ions only
!! if tn_style=2: hci0 includes contributions from all ions and non-hydrogenic neutrals
          temp10 = co%hci0(icv1)/enipar(ib, 1)
          DO nd0=1,nbdirs0
            temp5d(nd0) = (cod0%hci0(nd0, icv1)-temp10*enipard0(nd0, ib&
&             , 1))/enipar(ib, 1)
          END DO
          temp5 = temp10
          DO nd=1,nbdirs
            temp10 = (cod%hci0(nd, icv1)-temp5*enipard(nd, ib, 1))/&
&             enipar(ib, 1)
            DO nd0=1,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 1) = -(sy*(codd%hci0(nd0, nd, &
&               icv1)-enipard(nd, ib, 1)*temp5d(nd0)-temp5*enipardd(nd0&
&               , nd, ib, 1)-temp10*enipard0(nd0, ib, 1))/enipar(ib, 1))
            END DO
            srwd%shi0(nd, icv1, 1) = -(sy*temp10)
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 1) = -(sy*temp5d(nd0))
          END DO
          srw%shi0(icv1, 1) = -(sy*temp5)
        ELSE
!! tn_style=0.and.recycle_afn=1 => take out hydrogenic atoms
          temp10 = (co%hci0(icv1)-co%hcn0(icv1))/enipar(ib, 1)
          DO nd0=1,nbdirs0
            temp5d(nd0) = (cod0%hci0(nd0, icv1)-cod0%hcn0(nd0, icv1)-&
&             temp10*enipard0(nd0, ib, 1))/enipar(ib, 1)
          END DO
          temp5 = temp10
          DO nd=1,nbdirs
            temp10 = (cod%hci0(nd, icv1)-cod%hcn0(nd, icv1)-temp5*&
&             enipard(nd, ib, 1))/enipar(ib, 1)
            DO nd0=1,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 1) = -(sy*(codd%hci0(nd0, nd, &
&               icv1)-codd%hcn0(nd0, nd, icv1)-enipard(nd, ib, 1)*temp5d&
&               (nd0)-temp5*enipardd(nd0, nd, ib, 1)-temp10*enipard0(nd0&
&               , ib, 1))/enipar(ib, 1))
            END DO
            srwd%shi0(nd, icv1, 1) = -(sy*temp10)
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 1) = -(sy*temp5d(nd0))
          END DO
          srw%shi0(icv1, 1) = -(sy*temp5)
        END IF
        DO is=0,ns-1
          IF (((.NOT.is_neutral(is)) .OR. switch%tn_style .EQ. 0) .OR. (&
&             switch%tn_style .EQ. 2 .AND. NINT(zn(is)) .NE. 1)) THEN
            DO nd=1,nbdirs
              temp10 = srwd%sna0(nd, icv1, 0, is)
              DO nd0=1,nbdirs0
                srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1&
&                 , 0) + fac_he_anom*(pld%ti(nd, icv1)*srwd0%sna0(nd0, &
&                 icv1, 0, is)+srw%sna0(icv1, 0, is)*pldd%ti(nd0, nd, &
&                 icv1)+temp10*pld0%ti(nd0, icv1)+pl%ti(icv1)*srwdd%sna0&
&                 (nd0, nd, icv1, 0, is))
              END DO
              srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + &
&               fac_he_anom*(srw%sna0(icv1, 0, is)*pld%ti(nd, icv1)+pl%&
&               ti(icv1)*temp10)
              temp10 = srwd%sna0(nd, icv1, 1, is)
              DO nd0=1,nbdirs0
                srwdd%shi0(nd0, nd, icv1, 1) = srwdd%shi0(nd0, nd, icv1&
&                 , 1) + fac_he_anom*(pld%na(nd, icv1, is)*srwd0%sna0(&
&                 nd0, icv1, 1, is)+srw%sna0(icv1, 1, is)*pldd%na(nd0, &
&                 nd, icv1, is)+temp10*pld0%na(nd0, icv1, is)+pl%na(icv1&
&                 , is)*srwdd%sna0(nd0, nd, icv1, 1, is))
              END DO
              srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + &
&               fac_he_anom*(srw%sna0(icv1, 1, is)*pld%na(nd, icv1, is)+&
&               pl%na(icv1, is)*temp10)
            END DO
            DO nd0=1,nbdirs0
              srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + &
&               fac_he_anom*(srw%sna0(icv1, 0, is)*pld0%ti(nd0, icv1)+pl&
&               %ti(icv1)*srwd0%sna0(nd0, icv1, 0, is))
              srwd0%shi0(nd0, icv1, 1) = srwd0%shi0(nd0, icv1, 1) + &
&               fac_he_anom*(srw%sna0(icv1, 1, is)*pld0%na(nd0, icv1, is&
&               )+pl%na(icv1, is)*srwd0%sna0(nd0, icv1, 1, is))
            END DO
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + fac_he_anom*pl%ti(&
&             icv1)*srw%sna0(icv1, 0, is)
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + fac_he_anom*pl%na(&
&             icv1, is)*srw%sna0(icv1, 1, is)
          END IF
!! end species loop

        END DO
        IF (switch%mdf_fhi .NE. 0) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1, 0&
&               ) + temp2*(dvdd%fhipsch(nd0, nd, ifc, 0)+dvdd%fhipsch(&
&               nd0, nd, ifc, 1))
            END DO
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*(dvd&
&             %fhipsch(nd, ifc, 0)+dvd%fhipsch(nd, ifc, 1))
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + temp2*&
&             (dvd0%fhipsch(nd0, ifc, 0)+dvd0%fhipsch(nd0, ifc, 1))
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(dv%fhipsch(ifc&
&           , 0)+dv%fhipsch(ifc, 1))
          DO is=0,ns-1
            temp2 = 1.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp5 = pl%ti(icv1) + pl%ti(icv2)
            temp4 = pl%na(icv1, is) + pl%na(icv2, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              temp5d(nd0) = pld0%ti(nd0, icv1) + pld0%ti(nd0, icv2)
              temp4d(nd0) = pld0%na(nd0, icv1, is) + pld0%na(nd0, icv2, &
&               is)
              temp3d(nd0) = temp5*temp4d(nd0) + temp4*temp5d(nd0)
              tempd(nd0) = temp1*dvd0%vaecrb(nd0, ifc, 0, is) + temp0*&
&               dvd0%vaecrb(nd0, ifc, 1, is)
            END DO
            temp3 = temp4*temp5
            temp = temp1*dv%vaecrb(ifc, 0, is) + temp0*dv%vaecrb(ifc, 1&
&             , is)
            DO nd=1,nbdirs
              temp7 = temp1*dvd%vaecrb(nd, ifc, 0, is) + temp0*dvd%&
&               vaecrb(nd, ifc, 1, is)
              temp10 = pld%ti(nd, icv1) + pld%ti(nd, icv2)
              temp9 = pld%na(nd, icv1, is) + pld%na(nd, icv2, is)
              temp8 = temp5*temp9 + temp4*temp10
              DO nd0=1,nbdirs0
                t0dd(nd0, nd) = -(temp2*(temp7*temp3d(nd0)+temp3*(temp1*&
&                 dvdd%vaecrb(nd0, nd, ifc, 0, is)+temp0*dvdd%vaecrb(nd0&
&                 , nd, ifc, 1, is))+temp8*tempd(nd0)+temp*(temp9*temp5d&
&                 (nd0)+temp5*(pldd%na(nd0, nd, icv1, is)+pldd%na(nd0, &
&                 nd, icv2, is))+temp10*temp4d(nd0)+temp4*(pldd%ti(nd0, &
&                 nd, icv1)+pldd%ti(nd0, nd, icv2)))))
              END DO
              t0d(nd) = -(temp2*(temp3*temp7+temp*temp8))
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = -(temp2*(temp3*tempd(nd0)+temp*temp3d(nd0)))
            END DO
            t0 = -(temp2*(temp*temp3))
            IF (0.0_R8 .LT. t0) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max2dd(nd0, nd) = t0dd(nd0, nd)
                END DO
                max2d(nd) = t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                max2d0(nd0) = t0d0(nd0)
              END DO
              max2 = t0
            ELSE
              max2 = 0.0_R8
              DO nd=1,nbdirsmax
                DO nd0=1,nbdirs0
                  max2dd(nd0, nd) = 0.D0
                END DO
                max2d(nd) = 0.d0
              END DO
              max2d0 = 0.D0
            END IF
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1&
&                 , 0) + max2dd(nd0, nd)
              END DO
              srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + max2d(nd&
&               )
            END DO
            DO nd0=1,nbdirs0
              srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + &
&               max2d0(nd0)
            END DO
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max2
            IF (0.0_R8 .GT. t0) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  min2dd(nd0, nd) = t0dd(nd0, nd)
                END DO
                min2d(nd) = t0d(nd)
              END DO
              DO nd0=1,nbdirs0
                min2d0(nd0) = t0d0(nd0)
              END DO
              min2 = t0
            ELSE
              min2 = 0.0_R8
              DO nd=1,nbdirsmax
                DO nd0=1,nbdirs0
                  min2dd(nd0, nd) = 0.D0
                END DO
                min2d(nd) = 0.d0
              END DO
              min2d0 = 0.D0
            END IF
            temp10 = min2/pl%ti(icv1)
            DO nd0=1,nbdirs0
              temp5d(nd0) = (min2d0(nd0)-temp10*pld0%ti(nd0, icv1))/pl%&
&               ti(icv1)
            END DO
            temp5 = temp10
            DO nd=1,nbdirs
              temp10 = (min2d(nd)-temp5*pld%ti(nd, icv1))/pl%ti(icv1)
              DO nd0=1,nbdirs0
                srwdd%shi0(nd0, nd, icv1, 1) = srwdd%shi0(nd0, nd, icv1&
&                 , 1) + (min2dd(nd0, nd)-pld%ti(nd, icv1)*temp5d(nd0)-&
&                 temp5*pldd%ti(nd0, nd, icv1)-temp10*pld0%ti(nd0, icv1)&
&                 )/pl%ti(icv1)
              END DO
              srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + temp10
            END DO
            DO nd0=1,nbdirs0
              srwd0%shi0(nd0, icv1, 1) = srwd0%shi0(nd0, icv1, 1) + &
&               temp5d(nd0)
            END DO
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + temp5
          END DO
        END IF
!! end boundary cell loop

      END DO
    CASE (10) 
!
! -- BCENI=10 -- Feedback option for core
!
      CALL XERRAB('b2stbc_phys -- BCENI = 10 not adapted for WG')
!
! -- BCENI=11 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
    CASE (11) 
      CALL XERRAB('b2stbc_phys -- BCENI = 11 not adapted for WG')
!
! -- BCENI=12 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
    CASE (12) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a)') 'BCENI = 12 : sheath ion bc on ', bcchar(ib)&
&       , boundary_location(ib)
        WRITE(*, '(a)') &
&       'Obsolete. Use drift-compatible BCENI = 15 instead'
        max3dd = 0.D0
      ELSE
        max3dd = 0.D0
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO is=0,ns-1
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fna(ifc&
&             , 0, is)+dv%fna(ifc, 1, is))) THEN
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max3dd(nd0, nd) = temp2*(dvdd%fna(nd0, nd, ifc, 0, is)+&
&                 dvdd%fna(nd0, nd, ifc, 1, is))
              END DO
              max3d(nd) = temp2*(dvd%fna(nd, ifc, 0, is)+dvd%fna(nd, ifc&
&               , 1, is))
            END DO
            DO nd0=1,nbdirs0
              max3d0(nd0) = temp2*(dvd0%fna(nd0, ifc, 0, is)+dvd0%fna(&
&               nd0, ifc, 1, is))
            END DO
            max3 = temp2*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
          ELSE
            max3 = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                max3dd(nd0, nd) = 0.D0
              END DO
              max3d(nd) = 0.d0
            END DO
            max3d0 = 0.D0
          END IF
          temp7 = enipar(ib, 1)*max3/dv%ni(icv, 0)
          DO nd0=1,nbdirs0
            temp2d(nd0) = (max3*enipard0(nd0, ib, 1)+enipar(ib, 1)*&
&             max3d0(nd0)-temp7*dvd0%ni(nd0, icv, 0))/dv%ni(icv, 0)
          END DO
          temp2 = temp7
          DO nd=1,nbdirs
            temp10 = (max3*enipard(nd, ib, 1)+enipar(ib, 1)*max3d(nd)-&
&             temp2*dvd%ni(nd, icv, 0))/dv%ni(icv, 0)
            DO nd0=1,nbdirs0
              srwdd%shi0(nd0, nd, icv, 3) = srwdd%shi0(nd0, nd, icv, 3) &
&               - (enipard(nd, ib, 1)*max3d0(nd0)+max3*enipardd(nd0, nd&
&               , ib, 1)+max3d(nd)*enipard0(nd0, ib, 1)+enipar(ib, 1)*&
&               max3dd(nd0, nd)-dvd%ni(nd, icv, 0)*temp2d(nd0)-temp2*&
&               dvdd%ni(nd0, nd, icv, 0)-temp10*dvd0%ni(nd0, icv, 0))/dv&
&               %ni(icv, 0)
            END DO
            srwd%shi0(nd, icv, 3) = srwd%shi0(nd, icv, 3) - temp10
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv, 3) = srwd0%shi0(nd0, icv, 3) - temp2d(&
&             nd0)
          END DO
          srw%shi0(icv, 3) = srw%shi0(icv, 3) - temp2
        END DO
      END DO
    CASE (13) 
!
! -- BCENI=13 -- PRESCRIBE THE ION ENERGY FLUX PER UNIT AREA
!             -- PROPORTIONAL TO TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI = 13 : ion energy flux per area '&
&                                   //'proportional to temperature ', &
&                                   enipar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%shi0(nd0, nd, icv, 0) = geo%fcs(ifc)*(enipard(nd, ib, &
&             1)*pld0%ti(nd0, icv)+pl%ti(icv)*enipardd(nd0, nd, ib, 1)+&
&             pld%ti(nd, icv)*enipard0(nd0, ib, 1)+enipar(ib, 1)*pldd%ti&
&             (nd0, nd, icv))
            srwdd%shi0(nd0, nd, icv, 1) = 0.D0
          END DO
          srwd%shi0(nd, icv, 0) = geo%fcs(ifc)*(pl%ti(icv)*enipard(nd, &
&           ib, 1)+enipar(ib, 1)*pld%ti(nd, icv))
          srwd%shi0(nd, icv, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv, 0) = geo%fcs(ifc)*(pl%ti(icv)*enipard0(&
&           nd0, ib, 1)+enipar(ib, 1)*pld0%ti(nd0, icv))
          srwd0%shi0(nd0, icv, 1) = 0.D0
        END DO
        srw%shi0(icv, 0) = enipar(ib, 1)*pl%ti(icv)*geo%fcs(ifc)
        srw%shi0(icv, 1) = 0.0_R8
      END DO
    CASE (14) 
!
! -- BCENI=14 -- leakage option for ion energy
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI = 14 : ion energy leakage ', enipar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        csdd = 0.D0
        min3dd = 0.D0
        max4dd = 0.D0
        arg12dd = 0.D0
        t0dd = 0.D0
      ELSE
        csdd = 0.D0
        min3dd = 0.D0
        max4dd = 0.D0
        arg12dd = 0.D0
        t0dd = 0.D0
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp7 = pz(icv1)/rz(icv1)
        DO nd0=1,nbdirs0
          temp2d(nd0) = (pzd0(nd0, icv1)-temp7*rzd0(nd0, icv1))/rz(icv1)
        END DO
        temp2 = temp7
        DO nd=1,nbdirs
          temp7 = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
          DO nd0=1,nbdirs0
            arg12dd(nd0, nd) = (pzdd(nd0, nd, icv1)-rzd(nd, icv1)*temp2d&
&             (nd0)-temp2*rzdd(nd0, nd, icv1)-temp7*rzd0(nd0, icv1))/rz(&
&             icv1)
            srwdd%shi0(nd0, nd, icv1, 0) = 0.D0
          END DO
          arg12d(nd) = temp7
          srwd%shi0(nd, icv1, 0) = 0.d0
        END DO
        arg12 = temp2
        temp7 = SQRT(arg12)
        DO nd0=1,nbdirs0
          arg12d0(nd0) = temp2d(nd0)
          IF (arg12 .EQ. 0.D0) THEN
            temp2d(nd0) = 0.D0
          ELSE
            temp2d(nd0) = arg12d0(nd0)/(2.0*temp7)
          END IF
        END DO
        temp2 = temp7
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = 0.D0
            END DO
            csd(nd) = 0.d0
          ELSE
            temp7 = arg12d(nd)/(2.0*temp2)
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = (arg12dd(nd0, nd)-temp7*2.0*temp2d(nd0))/(&
&               2.0*temp2)
            END DO
            csd(nd) = temp7
          END IF
        END DO
        DO nd0=1,nbdirs0
          csd0(nd0) = temp2d(nd0)
          srwd0%shi0(nd0, icv1, 0) = 0.D0
        END DO
        cs = temp2
        srw%shi0(icv1, 0) = 0.0_R8
        temp2 = geo%fcs(ifc)*fac_he_anom_bc
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 3) = temp2*(csd(nd)*enipard0(nd0, &
&             ib, 1)+enipar(ib, 1)*csdd(nd0, nd)+enipard(nd, ib, 1)*csd0&
&             (nd0)+cs*enipardd(nd0, nd, ib, 1))
          END DO
          srwd%shi0(nd, icv1, 3) = temp2*(enipar(ib, 1)*csd(nd)+cs*&
&           enipard(nd, ib, 1))
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 3) = temp2*(enipar(ib, 1)*csd0(nd0)+cs*&
&           enipard0(nd0, ib, 1))
        END DO
        srw%shi0(icv1, 3) = temp2*(cs*enipar(ib, 1))
        IF (switch%mdf_fhi .NE. 0) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1, 0&
&               ) + temp2*(dvdd%fhipsch(nd0, nd, ifc, 0)+dvdd%fhipsch(&
&               nd0, nd, ifc, 1))
            END DO
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*(dvd&
&             %fhipsch(nd, ifc, 0)+dvd%fhipsch(nd, ifc, 1))
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + temp2*&
&             (dvd0%fhipsch(nd0, ifc, 0)+dvd0%fhipsch(nd0, ifc, 1))
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(dv%fhipsch(ifc&
&           , 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              t0dd(nd0, nd) = 0.D0
            END DO
            t0d(nd) = 0.d0
          END DO
          t0d0 = 0.D0
          DO is=0,ns-1
            temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp5 = pl%ti(icv1) + pl%ti(icv2)
            temp4 = pl%na(icv1, is) + pl%na(icv2, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              temp5d(nd0) = pld0%ti(nd0, icv1) + pld0%ti(nd0, icv2)
              temp4d(nd0) = pld0%na(nd0, icv1, is) + pld0%na(nd0, icv2, &
&               is)
              temp3d(nd0) = temp5*temp4d(nd0) + temp4*temp5d(nd0)
              tempd(nd0) = temp1*dvd0%vadia(nd0, ifc, 0, is) + temp0*&
&               dvd0%vadia(nd0, ifc, 1, is)
            END DO
            temp3 = temp4*temp5
            temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1, &
&             is)
            DO nd=1,nbdirs
              temp7 = temp1*dvd%vadia(nd, ifc, 0, is) + temp0*dvd%vadia(&
&               nd, ifc, 1, is)
              temp10 = pld%ti(nd, icv1) + pld%ti(nd, icv2)
              temp9 = pld%na(nd, icv1, is) + pld%na(nd, icv2, is)
              temp8 = temp5*temp9 + temp4*temp10
              DO nd0=1,nbdirs0
                t0dd(nd0, nd) = t0dd(nd0, nd) + temp2*(temp7*temp3d(nd0)&
&                 +temp3*(temp1*dvdd%vadia(nd0, nd, ifc, 0, is)+temp0*&
&                 dvdd%vadia(nd0, nd, ifc, 1, is))+temp8*tempd(nd0)+temp&
&                 *(temp9*temp5d(nd0)+temp5*(pldd%na(nd0, nd, icv1, is)+&
&                 pldd%na(nd0, nd, icv2, is))+temp10*temp4d(nd0)+temp4*(&
&                 pldd%ti(nd0, nd, icv1)+pldd%ti(nd0, nd, icv2))))
              END DO
              t0d(nd) = t0d(nd) + temp2*(temp3*temp7+temp*temp8)
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = t0d0(nd0) + temp2*(temp3*tempd(nd0)+temp*&
&               temp3d(nd0))
            END DO
            t0 = t0 + temp2*(temp*temp3)
          END DO
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max4dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              max4d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              max4d0(nd0) = t0d0(nd0)
            END DO
            max4 = t0
          ELSE
            max4 = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                max4dd(nd0, nd) = 0.D0
              END DO
              max4d(nd) = 0.d0
            END DO
            max4d0 = 0.D0
          END IF
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1, 0&
&               ) + max4dd(nd0, nd)
            END DO
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + max4d(nd)
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + max4d0&
&             (nd0)
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max4
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                min3dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              min3d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              min3d0(nd0) = t0d0(nd0)
            END DO
            min3 = t0
          ELSE
            min3 = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                min3dd(nd0, nd) = 0.D0
              END DO
              min3d(nd) = 0.d0
            END DO
            min3d0 = 0.D0
          END IF
          temp10 = min3/pl%ti(icv1)
          DO nd0=1,nbdirs0
            temp5d(nd0) = (min3d0(nd0)-temp10*pld0%ti(nd0, icv1))/pl%ti(&
&             icv1)
          END DO
          temp5 = temp10
          DO nd=1,nbdirs
            temp10 = (min3d(nd)-temp5*pld%ti(nd, icv1))/pl%ti(icv1)
            DO nd0=1,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 1) = srwdd%shi0(nd0, nd, icv1, 1&
&               ) + (min3dd(nd0, nd)-pld%ti(nd, icv1)*temp5d(nd0)-temp5*&
&               pldd%ti(nd0, nd, icv1)-temp10*pld0%ti(nd0, icv1))/pl%ti(&
&               icv1)
            END DO
            srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + temp10
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 1) = srwd0%shi0(nd0, icv1, 1) + temp5d&
&             (nd0)
          END DO
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + temp5
        END IF
      END DO
    CASE (15) 
!
! -- BCENI=15 -- DRIFT-COMPATIBLE SHEATH CONDITION                   !srv 01.02.09 {
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 20.09.17
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 15 : drift-compatible sheath condition '//&
&       'for ion temperature with ENIPAR(IB,1) =', enipar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        WRITE(*, *) 'BCENI=15 - should have BCCON=14 for all ions'
!srv 20.09.17
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 15, ENIPAR(IB,1) <= 0 not allowed!')
        IF (bceni_15_style .NE. 0) WRITE(*, *) 'bceni_15_style <> 0'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY ', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) THEN
          WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&         'HAS NOT BEEN IMPOSED AT BOUNDARY ', ib, ' FOR ALL IONS'
          IF (bceni_15_style .EQ. 0) THEN
            CALL XERRAB('When BCENI=15 and bceni_15_style.eq.0, '//&
&                 'one must have BCCON=14 for all ion species!')
            y1dd = 0.D0
            csdd = 0.D0
            vbnddd = 0.D0
            result10dd = 0.D0
            max6dd = 0.D0
            t2dd = 0.D0
            x1dd = 0.D0
            dshdd = 0.D0
            max7dd = 0.D0
            arg12dd = 0.D0
            t3dd = 0.D0
            t0dd = 0.D0
            min4dd = 0.D0
            result20dd = 0.D0
            max5dd = 0.D0
            arg13dd = 0.D0
            t4dd = 0.D0
            vtdd = 0.D0
            t1dd = 0.D0
            min5dd = 0.D0
          ELSE
            y1dd = 0.D0
            csdd = 0.D0
            vbnddd = 0.D0
            result10dd = 0.D0
            max6dd = 0.D0
            t2dd = 0.D0
            x1dd = 0.D0
            dshdd = 0.D0
            max7dd = 0.D0
            arg12dd = 0.D0
            t3dd = 0.D0
            t0dd = 0.D0
            min4dd = 0.D0
            result20dd = 0.D0
            max5dd = 0.D0
            arg13dd = 0.D0
            t4dd = 0.D0
            vtdd = 0.D0
            t1dd = 0.D0
            min5dd = 0.D0
          END IF
        ELSE
          y1dd = 0.D0
          csdd = 0.D0
          vbnddd = 0.D0
          result10dd = 0.D0
          max6dd = 0.D0
          t2dd = 0.D0
          x1dd = 0.D0
          dshdd = 0.D0
          max7dd = 0.D0
          arg12dd = 0.D0
          t3dd = 0.D0
          t0dd = 0.D0
          min4dd = 0.D0
          result20dd = 0.D0
          max5dd = 0.D0
          arg13dd = 0.D0
          t4dd = 0.D0
          vtdd = 0.D0
          t1dd = 0.D0
          min5dd = 0.D0
        END IF
      ELSE
        y1dd = 0.D0
        csdd = 0.D0
        vbnddd = 0.D0
        result10dd = 0.D0
        max6dd = 0.D0
        t2dd = 0.D0
        x1dd = 0.D0
        dshdd = 0.D0
        max7dd = 0.D0
        arg12dd = 0.D0
        t3dd = 0.D0
        t0dd = 0.D0
        min4dd = 0.D0
        result20dd = 0.D0
        max5dd = 0.D0
        arg13dd = 0.D0
        t4dd = 0.D0
        vtdd = 0.D0
        t1dd = 0.D0
        min5dd = 0.D0
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
!srv 15.02.26 {
        DO is=0,ns-1
          CALL CSBC_IS_DV_DV(icv1, ib, is, cs, csd0, csd, csdd, nbdirs, &
&                      nbdirs0)
          CALL VBC_IS_DV_DV(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is)&
&                     , csbcd0(:, icv1, is), csbcd(:, icv1, is), csbcdd(&
&                     :, :, icv1, is), wrk, nbdirs, nbdirs0)
!srv 15.02.26 }
        END DO
        temp7 = pz(icv1)/rz(icv1)
        DO nd0=1,nbdirs0
          temp2d(nd0) = (pzd0(nd0, icv1)-temp7*rzd0(nd0, icv1))/rz(icv1)
        END DO
        temp2 = temp7
        DO nd=1,nbdirs
          temp7 = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
          DO nd0=1,nbdirs0
            arg12dd(nd0, nd) = (pzdd(nd0, nd, icv1)-rzd(nd, icv1)*temp2d&
&             (nd0)-temp2*rzdd(nd0, nd, icv1)-temp7*rzd0(nd0, icv1))/rz(&
&             icv1)
          END DO
          arg12d(nd) = temp7
        END DO
        arg12 = temp2
        temp7 = SQRT(arg12)
        DO nd0=1,nbdirs0
          arg12d0(nd0) = temp2d(nd0)
          IF (arg12 .EQ. 0.D0) THEN
            temp2d(nd0) = 0.D0
          ELSE
            temp2d(nd0) = arg12d0(nd0)/(2.0*temp7)
          END IF
        END DO
        temp2 = temp7
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = 0.D0
            END DO
            csd(nd) = 0.d0
          ELSE
            temp7 = arg12d(nd)/(2.0*temp2)
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = (arg12dd(nd0, nd)-temp7*2.0*temp2d(nd0))/(&
&               2.0*temp2)
            END DO
            csd(nd) = temp7
          END IF
        END DO
        DO nd0=1,nbdirs0
          csd0(nd0) = temp2d(nd0)
        END DO
        cs = temp2
        t0 = 0.0_R8
        t1 = 0.0_R8
        t2 = 0.0_R8
        wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
        IF (bceni_15_style .EQ. 0) THEN
          IF (wrk .GE. 0.) THEN
            abs0 = wrk
          ELSE
            abs0 = -wrk
          END IF
          IF (abs0 .LT. geo%qalfmin) THEN
            temp2 = 1.5_R8*geo%fcs(ifc)*geo%qalfmax
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%shi0(nd0, nd, icv1, 0) = 0.D0
                srwdd%shi0(nd0, nd, icv1, 1) = -(temp2*(csd(nd)*dvd0%ni(&
&                 nd0, icv1, 1)+dv%ni(icv1, 1)*csdd(nd0, nd)+dvd%ni(nd, &
&                 icv1, 1)*csd0(nd0)+cs*dvdd%ni(nd0, nd, icv1, 1)))
              END DO
              srwd%shi0(nd, icv1, 0) = 0.d0
              srwd%shi0(nd, icv1, 1) = -(temp2*(dv%ni(icv1, 1)*csd(nd)+&
&               cs*dvd%ni(nd, icv1, 1)))
            END DO
            DO nd0=1,nbdirs0
              srwd0%shi0(nd0, icv1, 0) = 0.D0
              srwd0%shi0(nd0, icv1, 1) = -(temp2*(dv%ni(icv1, 1)*csd0(&
&               nd0)+cs*dvd0%ni(nd0, icv1, 1)))
            END DO
            srw%shi0(icv1, 0) = 0.0_R8
            srw%shi0(icv1, 1) = -(temp2*(cs*dv%ni(icv1, 1)))
            IF (switch%mdf_fhi .NE. 0) THEN
              temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, &
&                   icv1, 0) + temp2*(dvdd%fhipsch(nd0, nd, ifc, 0)+dvdd&
&                   %fhipsch(nd0, nd, ifc, 1))
                END DO
                srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*&
&                 (dvd%fhipsch(nd, ifc, 0)+dvd%fhipsch(nd, ifc, 1))
              END DO
              DO nd0=1,nbdirs0
                srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + &
&                 temp2*(dvd0%fhipsch(nd0, ifc, 0)+dvd0%fhipsch(nd0, ifc&
&                 , 1))
              END DO
              srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(dv%fhipsch(&
&               ifc, 0)+dv%fhipsch(ifc, 1))
              t0 = 0.0_R8
              DO nd=1,nbdirsmax
                DO nd0=1,nbdirs0
                  t0dd(nd0, nd) = 0.D0
                END DO
                t0d(nd) = 0.d0
              END DO
              t0d0 = 0.D0
              DO is=0,ns-1
                temp2 = 1.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(&
&                 0.5_R8*0.5_R8)
                temp5 = pl%ti(icv1) + pl%ti(icv2)
                temp4 = pl%na(icv1, is) + pl%na(icv2, is)
                temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
                temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
                DO nd0=1,nbdirs0
                  temp5d(nd0) = pld0%ti(nd0, icv1) + pld0%ti(nd0, icv2)
                  temp4d(nd0) = pld0%na(nd0, icv1, is) + pld0%na(nd0, &
&                   icv2, is)
                  temp3d(nd0) = temp5*temp4d(nd0) + temp4*temp5d(nd0)
                  tempd(nd0) = temp1*dvd0%vaecrb(nd0, ifc, 0, is) + &
&                   temp0*dvd0%vaecrb(nd0, ifc, 1, is)
                END DO
                temp3 = temp4*temp5
                temp = temp1*dv%vaecrb(ifc, 0, is) + temp0*dv%vaecrb(ifc&
&                 , 1, is)
                DO nd=1,nbdirs
                  temp7 = temp1*dvd%vaecrb(nd, ifc, 0, is) + temp0*dvd%&
&                   vaecrb(nd, ifc, 1, is)
                  temp10 = pld%ti(nd, icv1) + pld%ti(nd, icv2)
                  temp9 = pld%na(nd, icv1, is) + pld%na(nd, icv2, is)
                  temp8 = temp5*temp9 + temp4*temp10
                  DO nd0=1,nbdirs0
                    t0dd(nd0, nd) = t0dd(nd0, nd) + temp2*(temp7*temp3d(&
&                     nd0)+temp3*(temp1*dvdd%vaecrb(nd0, nd, ifc, 0, is)&
&                     +temp0*dvdd%vaecrb(nd0, nd, ifc, 1, is))+temp8*&
&                     tempd(nd0)+temp*(temp9*temp5d(nd0)+temp5*(pldd%na(&
&                     nd0, nd, icv1, is)+pldd%na(nd0, nd, icv2, is))+&
&                     temp10*temp4d(nd0)+temp4*(pldd%ti(nd0, nd, icv1)+&
&                     pldd%ti(nd0, nd, icv2))))
                  END DO
                  t0d(nd) = t0d(nd) + temp2*(temp3*temp7+temp*temp8)
                END DO
                DO nd0=1,nbdirs0
                  t0d0(nd0) = t0d0(nd0) + temp2*(temp3*tempd(nd0)+temp*&
&                   temp3d(nd0))
                END DO
                t0 = t0 + temp2*(temp*temp3)
              END DO
              IF (0.0_R8 .LT. t0) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max5dd(nd0, nd) = t0dd(nd0, nd)
                  END DO
                  max5d(nd) = t0d(nd)
                END DO
                DO nd0=1,nbdirs0
                  max5d0(nd0) = t0d0(nd0)
                END DO
                max5 = t0
              ELSE
                max5 = 0.0_R8
                DO nd=1,nbdirsmax
                  DO nd0=1,nbdirs0
                    max5dd(nd0, nd) = 0.D0
                  END DO
                  max5d(nd) = 0.d0
                END DO
                max5d0 = 0.D0
              END IF
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, &
&                   icv1, 0) + max5dd(nd0, nd)
                END DO
                srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + max5d(&
&                 nd)
              END DO
              DO nd0=1,nbdirs0
                srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + &
&                 max5d0(nd0)
              END DO
              srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max5
              IF (0.0_R8 .GT. t0) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    min4dd(nd0, nd) = t0dd(nd0, nd)
                  END DO
                  min4d(nd) = t0d(nd)
                END DO
                DO nd0=1,nbdirs0
                  min4d0(nd0) = t0d0(nd0)
                END DO
                min4 = t0
              ELSE
                min4 = 0.0_R8
                DO nd=1,nbdirsmax
                  DO nd0=1,nbdirs0
                    min4dd(nd0, nd) = 0.D0
                  END DO
                  min4d(nd) = 0.d0
                END DO
                min4d0 = 0.D0
              END IF
              temp10 = min4/pl%ti(icv1)
              DO nd0=1,nbdirs0
                temp5d(nd0) = (min4d0(nd0)-temp10*pld0%ti(nd0, icv1))/pl&
&                 %ti(icv1)
              END DO
              temp5 = temp10
              DO nd=1,nbdirs
                temp10 = (min4d(nd)-temp5*pld%ti(nd, icv1))/pl%ti(icv1)
                DO nd0=1,nbdirs0
                  srwdd%shi0(nd0, nd, icv1, 1) = srwdd%shi0(nd0, nd, &
&                   icv1, 1) + (min4dd(nd0, nd)-pld%ti(nd, icv1)*temp5d(&
&                   nd0)-temp5*pldd%ti(nd0, nd, icv1)-temp10*pld0%ti(nd0&
&                   , icv1))/pl%ti(icv1)
                END DO
                srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + temp10
              END DO
              DO nd0=1,nbdirs0
                srwd0%shi0(nd0, icv1, 1) = srwd0%shi0(nd0, icv1, 1) + &
&                 temp5d(nd0)
              END DO
              srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + temp5
            END IF
          ELSE
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                t0dd(nd0, nd) = 0.D0
              END DO
              t0d(nd) = 0.d0
            END DO
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                t1dd(nd0, nd) = 0.D0
              END DO
              t1d(nd) = 0.d0
            END DO
            t0d0 = 0.D0
            t1d0 = 0.D0
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) THEN
                temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    vbnddd(nd0, nd) = temp2*(geo%fcqalf(ifc, 0)*dvdd%&
&                     vaecrb(nd0, nd, ifc, 0, is)+geo%fcqalf(ifc, 1)*&
&                     dvdd%vaecrb(nd0, nd, ifc, 1, is))
                  END DO
                  vbndd(nd) = temp2*(geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, &
&                   ifc, 0, is)+geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc, 1&
&                   , is))
                END DO
                DO nd0=1,nbdirs0
                  vbndd0(nd0) = temp2*(geo%fcqalf(ifc, 0)*dvd0%vaecrb(&
&                   nd0, ifc, 0, is)+geo%fcqalf(ifc, 1)*dvd0%vaecrb(nd0&
&                   , ifc, 1, is))
                END DO
                vbnd = temp2*(geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+&
&                 geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))
                IF (wrk .GE. 0.) THEN
                  abs5 = wrk
                ELSE
                  abs5 = -wrk
                END IF
                temp5 = SIGN(1.0_R8, wrk)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    x1dd(nd0, nd) = abs5*csbcdd(nd0, nd, icv1, is)
                    y1dd(nd0, nd) = temp5*vbcdd(nd0, nd, icv1, is) + &
&                     vbnddd(nd0, nd)
                  END DO
                  x1d(nd) = abs5*csbcd(nd, icv1, is)
                  y1d(nd) = temp5*vbcd(nd, icv1, is) + vbndd(nd)
                END DO
                DO nd0=1,nbdirs0
                  x1d0(nd0) = abs5*csbcd0(nd0, icv1, is)
                  y1d0(nd0) = temp5*vbcd0(nd0, icv1, is) + vbndd0(nd0)
                END DO
                x1 = csbc(icv1, is)*abs5
                y1 = temp5*vbc(icv1, is) + vbnd
                IF (x1 .LT. y1) THEN
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      max6dd(nd0, nd) = y1dd(nd0, nd)
                    END DO
                    max6d(nd) = y1d(nd)
                  END DO
                  DO nd0=1,nbdirs0
                    max6d0(nd0) = y1d0(nd0)
                  END DO
                  max6 = y1
                ELSE
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      max6dd(nd0, nd) = x1dd(nd0, nd)
                    END DO
                    max6d(nd) = x1d(nd)
                  END DO
                  DO nd0=1,nbdirs0
                    max6d0(nd0) = x1d0(nd0)
                  END DO
                  max6 = x1
                END IF
                DO nd0=1,nbdirs0
                  temp2d(nd0) = max6*mompard0(nd0, is, ib, 1) + mompar(&
&                   is, ib, 1)*max6d0(nd0)
                END DO
                temp2 = mompar(is, ib, 1)*max6
                DO nd=1,nbdirs
                  temp7 = mompard(nd, is, ib, 1)*max6 + mompar(is, ib, 1&
&                   )*max6d(nd)
                  DO nd0=1,nbdirs0
                    t0dd(nd0, nd) = t0dd(nd0, nd) + geo%fcs(ifc)*(temp7*&
&                     pld0%na(nd0, icv1, is)+pl%na(icv1, is)*(mompard(nd&
&                     , is, ib, 1)*max6d0(nd0)+max6d(nd)*mompard0(nd0, &
&                     is, ib, 1)+mompar(is, ib, 1)*max6dd(nd0, nd))+pld%&
&                     na(nd, icv1, is)*temp2d(nd0)+temp2*pldd%na(nd0, nd&
&                     , icv1, is))
                  END DO
                  t0d(nd) = t0d(nd) + geo%fcs(ifc)*(pl%na(icv1, is)*&
&                   temp7+temp2*pld%na(nd, icv1, is))
                END DO
                DO nd0=1,nbdirs0
                  t0d0(nd0) = t0d0(nd0) + geo%fcs(ifc)*(pl%na(icv1, is)*&
&                   temp2d(nd0)+temp2*pld0%na(nd0, icv1, is))
                END DO
                t0 = t0 + geo%fcs(ifc)*(temp2*pl%na(icv1, is))
                IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
                  temp10 = co%dna0(icv1, is)*pl%na(icv1, is)/conpar(is, &
&                   ib, 2)
                  DO nd0=1,nbdirs0
                    temp5d(nd0) = (pl%na(icv1, is)*cod0%dna0(nd0, icv1, &
&                     is)+co%dna0(icv1, is)*pld0%na(nd0, icv1, is)-&
&                     temp10*conpard0(nd0, is, ib, 2))/conpar(is, ib, 2)
                  END DO
                  temp5 = temp10
                  DO nd=1,nbdirs
                    temp10 = (pl%na(icv1, is)*cod%dna0(nd, icv1, is)+co%&
&                     dna0(icv1, is)*pld%na(nd, icv1, is)-temp5*conpard(&
&                     nd, is, ib, 2))/conpar(is, ib, 2)
                    DO nd0=1,nbdirs0
                      t1dd(nd0, nd) = t1dd(nd0, nd) + (cod%dna0(nd, icv1&
&                       , is)*pld0%na(nd0, icv1, is)+pl%na(icv1, is)*&
&                       codd%dna0(nd0, nd, icv1, is)+pld%na(nd, icv1, is&
&                       )*cod0%dna0(nd0, icv1, is)+co%dna0(icv1, is)*&
&                       pldd%na(nd0, nd, icv1, is)-conpard(nd, is, ib, 2&
&                       )*temp5d(nd0)-temp5*conpardd(nd0, nd, is, ib, 2)&
&                       -temp10*conpard0(nd0, is, ib, 2))/conpar(is, ib&
&                       , 2)
                    END DO
                    t1d(nd) = t1d(nd) + temp10
                  END DO
                  DO nd0=1,nbdirs0
                    t1d0(nd0) = t1d0(nd0) + temp5d(nd0)
                  END DO
                  t1 = t1 + temp5
                END IF
              END IF
            END DO
            temp2 = switch%stab_coeff_sheath_ti*geo%fcs(ifc)
            temp1 = fac_he_anom_bc*geo%fcs(ifc)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%shi0(nd0, nd, icv1, 1) = srwdd%shi0(nd0, nd, icv1&
&                 , 1) - enipard(nd, ib, 1)*t0d0(nd0) - t0*enipardd(nd0&
&                 , nd, ib, 1) - t0d(nd)*enipard0(nd0, ib, 1) - enipar(&
&                 ib, 1)*t0dd(nd0, nd) - temp2*(dvd%ne(nd, icv1)*csd0(&
&                 nd0)+cs*dvdd%ne(nd0, nd, icv1)+csd(nd)*dvd0%ne(nd0, &
&                 icv1)+dv%ne(icv1)*csdd(nd0, nd)) - temp1*(enipard(nd, &
&                 ib, 2)*t1d0(nd0)+t1*enipardd(nd0, nd, ib, 2)+t1d(nd)*&
&                 enipard0(nd0, ib, 2)+enipar(ib, 2)*t1dd(nd0, nd))
              END DO
              srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) - t0*&
&               enipard(nd, ib, 1) - enipar(ib, 1)*t0d(nd) - temp2*(cs*&
&               dvd%ne(nd, icv1)+dv%ne(icv1)*csd(nd)) - temp1*(t1*&
&               enipard(nd, ib, 2)+enipar(ib, 2)*t1d(nd))
            END DO
            DO nd0=1,nbdirs0
              srwd0%shi0(nd0, icv1, 1) = srwd0%shi0(nd0, icv1, 1) - t0*&
&               enipard0(nd0, ib, 1) - enipar(ib, 1)*t0d0(nd0) - temp2*(&
&               cs*dvd0%ne(nd0, icv1)+dv%ne(icv1)*csd0(nd0)) - temp1*(t1&
&               *enipard0(nd0, ib, 2)+enipar(ib, 2)*t1d0(nd0))
              temp5d(nd0) = cs*dvd0%ne(nd0, icv1) + dv%ne(icv1)*csd0(nd0&
&               )
            END DO
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) - enipar(ib, 1)*t0 - &
&             temp2*(dv%ne(icv1)*cs) - temp1*(enipar(ib, 2)*t1)
            temp2 = switch%stab_coeff_sheath_ti*geo%fcs(ifc)
            temp5 = dv%ne(icv1)*cs
            DO nd=1,nbdirs
              temp7 = cs*dvd%ne(nd, icv1) + dv%ne(icv1)*csd(nd)
              DO nd0=1,nbdirs0
                srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1&
&                 , 0) + temp2*(temp7*pld0%ti(nd0, icv1)+pl%ti(icv1)*(&
&                 dvd%ne(nd, icv1)*csd0(nd0)+cs*dvdd%ne(nd0, nd, icv1)+&
&                 csd(nd)*dvd0%ne(nd0, icv1)+dv%ne(icv1)*csdd(nd0, nd))+&
&                 pld%ti(nd, icv1)*temp5d(nd0)+temp5*pldd%ti(nd0, nd, &
&                 icv1))
              END DO
              srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*(&
&               pl%ti(icv1)*temp7+temp5*pld%ti(nd, icv1))
            END DO
            DO nd0=1,nbdirs0
              srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + &
&               temp2*(pl%ti(icv1)*temp5d(nd0)+temp5*pld0%ti(nd0, icv1))
            END DO
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(temp5*pl%ti(&
&             icv1))
          END IF
        ELSE
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              t0dd(nd0, nd) = 0.D0
            END DO
            t0d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              t1dd(nd0, nd) = 0.D0
            END DO
            t1d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              t2dd(nd0, nd) = 0.D0
            END DO
            t2d(nd) = 0.d0
          END DO
          t0d0 = 0.D0
          t1d0 = 0.D0
          t2d0 = 0.D0
!wdk sheath transmission factor consistent with truncated
!    Maxwellian distribution on Eirene side (NEMODS=7)
!    See Eirene manual for details.
          DO is=0,ns-1
            IF (.NOT.is_neutral(is)) THEN
              arg13 = 2.0_R8*pl%ti(icv1)/(am(is)*mp)
              temp10 = SQRT(arg13)
              DO nd0=1,nbdirs0
                arg13d0(nd0) = 2.0_R8*pld0%ti(nd0, icv1)/(am(is)*mp)
                IF (arg13 .EQ. 0.D0) THEN
                  temp6d(nd0) = 0.D0
                ELSE
                  temp6d(nd0) = arg13d0(nd0)/(2.0*temp10)
                END IF
              END DO
              temp6 = temp10
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  arg13dd(nd0, nd) = 2.0_R8*pldd%ti(nd0, nd, icv1)/(am(&
&                   is)*mp)
                END DO
                arg13d(nd) = 2.0_R8*pld%ti(nd, icv1)/(am(is)*mp)
                IF (arg13 .EQ. 0.d0) THEN
                  DO nd0=1,nbdirs0
                    vtdd(nd0, nd) = 0.D0
                  END DO
                  vtd(nd) = 0.d0
                ELSE
                  temp10 = arg13d(nd)/(2.0*temp6)
                  DO nd0=1,nbdirs0
                    vtdd(nd0, nd) = (arg13dd(nd0, nd)-temp10*2.0*temp6d(&
&                     nd0))/(2.0*temp6)
                  END DO
                  vtd(nd) = temp10
                END IF
              END DO
              DO nd0=1,nbdirs0
                vtd0(nd0) = temp6d(nd0)
              END DO
              vt = temp6
              IF (geo%fcqalf(ifc, 0) .GE. 0.) THEN
                abs1 = geo%fcqalf(ifc, 0)
              ELSE
                abs1 = -geo%fcqalf(ifc, 0)
              END IF
              result10 = PIT(icv1)
              DO nd=1,nbdirs
                temp7 = cs/vt
                temp11 = (csd(nd)-vtd(nd)*temp7)/vt
                DO nd0=1,nbdirs0
                  t3dd(nd0, nd) = result10*abs1*(csdd(nd0, nd)-temp7*&
&                   vtdd(nd0, nd)-vtd(nd)*(csd0(nd0)-temp7*vtd0(nd0))/vt&
&                   -temp11*vtd0(nd0))/vt
                END DO
                t3d(nd) = result10*abs1*temp11
              END DO
              DO nd0=1,nbdirs0
                t3d0(nd0) = result10*abs1*(csd0(nd0)-cs*vtd0(nd0)/vt)/vt
              END DO
              t3 = result10*abs1*cs/vt
              IF (geo%fcqalf(ifc, 1) .GE. 0.) THEN
                abs2 = geo%fcqalf(ifc, 1)
              ELSE
                abs2 = -geo%fcqalf(ifc, 1)
              END IF
!WG_TODO correct for drift contributions!
              result10 = PIT(icv1)
              temp1 = geo%cvbb(icv1, 3)*vt
              DO nd0=1,nbdirs0
                temp2d(nd0) = result10*abs2*(csd0(nd0)-cs*vtd0(nd0)/vt)/&
&                 vt
                temp1d(nd0) = geo%cvbb(icv1, 3)*vtd0(nd0)
                temp0d(nd0) = (csd0(nd0)-cs*temp1d(nd0)/temp1)/temp1
                tempd(nd0) = geo%cvbb(icv1, 2)*temp0d(nd0)
              END DO
              temp2 = result10*abs2*cs/vt
              temp0 = cs/temp1
              temp = geo%cvbb(icv1, 2)*temp0
              DO nd=1,nbdirs
                temp11 = 2*result10*abs2
                temp7 = temp2/vt
                temp12 = cs/vt
                temp13 = csd(nd) - vtd(nd)*temp12
                temp14 = 2*geo%cvbb(icv1, 2)
                temp15 = temp/temp1
                temp16 = csd(nd) - geo%cvbb(icv1, 3)*temp0*vtd(nd)
                DO nd0=1,nbdirs0
                  arg12dd(nd0, nd) = temp11*(temp7*(csdd(nd0, nd)-temp12&
&                   *vtdd(nd0, nd)-vtd(nd)*(csd0(nd0)-temp12*vtd0(nd0))/&
&                   vt)+temp13*(temp2d(nd0)-temp7*vtd0(nd0))/vt) + &
&                   temp14*(temp15*(csdd(nd0, nd)-geo%cvbb(icv1, 3)*(vtd&
&                   (nd)*temp0d(nd0)+temp0*vtdd(nd0, nd)))+temp16*(tempd&
&                   (nd0)-temp15*temp1d(nd0))/temp1)
                END DO
                arg12d(nd) = temp11*(temp13*temp7) + temp14*(temp16*&
&                 temp15)
              END DO
              arg12 = temp2*temp2 + temp*temp
              temp16 = SQRT(arg12)
              DO nd0=1,nbdirs0
                arg12d0(nd0) = 2*temp2*temp2d(nd0) + 2*temp*tempd(nd0)
                IF (arg12 .EQ. 0.D0) THEN
                  temp2d(nd0) = 0.D0
                ELSE
                  temp2d(nd0) = arg12d0(nd0)/(2.0*temp16)
                END IF
              END DO
              temp2 = temp16
              DO nd=1,nbdirs
                IF (arg12 .EQ. 0.d0) THEN
                  DO nd0=1,nbdirs0
                    t4dd(nd0, nd) = 0.D0
                  END DO
                  t4d(nd) = 0.d0
                ELSE
                  temp16 = arg12d(nd)/(2.0*temp2)
                  DO nd0=1,nbdirs0
                    t4dd(nd0, nd) = (arg12dd(nd0, nd)-temp16*2.0*temp2d(&
&                     nd0))/(2.0*temp2)
                  END DO
                  t4d(nd) = temp16
                END IF
              END DO
!corrected for factor 3/2 in parallel convection
              CALL SHEATH_G_DV_DV(t3, t3d0, t3d, t3dd, result10, &
&                           result10d0, result10d, result10dd, nbdirs, &
&                           nbdirs0)
              CALL SHEATH_G_DV_DV(t3, t3d0, t3d, t3dd, result20, &
&                           result20d0, result20d, result20dd, nbdirs, &
&                           nbdirs0)
              temp16 = (result10-1.0_R8)/result20
              DO nd0=1,nbdirs0
                t4d0(nd0) = temp2d(nd0)
                temp2d(nd0) = (result10d0(nd0)-temp16*result20d0(nd0))/&
&                 result20
              END DO
              t4 = temp2
              temp2 = temp16
              DO nd=1,nbdirs
                temp16 = (result10d(nd)-temp2*result20d(nd))/result20
                DO nd0=1,nbdirs0
                  dshdd(nd0, nd) = t3d(nd)*2*t3d0(nd0) + 2*t3*t3dd(nd0, &
&                   nd) + t4d(nd)*2*t4d0(nd0) + 2*t4*t4dd(nd0, nd) + &
&                   0.5_R8*(result10dd(nd0, nd)-result20d(nd)*temp2d(nd0&
&                   )-temp2*result20dd(nd0, nd)-temp16*result20d0(nd0))/&
&                   result20
                END DO
                dshd(nd) = 2*t3*t3d(nd) + 2*t4*t4d(nd) + 0.5_R8*temp16
              END DO
              dsh = t3*t3 + t4*t4 + 0.5_R8*temp2 + 1.0_R8
              DO nd0=1,nbdirs0
                dshd0(nd0) = 2*t3*t3d0(nd0) + 2*t4*t4d0(nd0) + 0.5_R8*&
&                 temp2d(nd0)
                temp2d(nd0) = mompar(is, ib, 1)*dshd0(nd0) + dsh*&
&                 mompard0(nd0, is, ib, 1)
              END DO
              temp2 = dsh*mompar(is, ib, 1)
              DO nd=1,nbdirs
                temp16 = mompar(is, ib, 1)*dshd(nd) + mompard(nd, is, ib&
&                 , 1)*dsh
                DO nd0=1,nbdirs0
                  t0dd(nd0, nd) = t0dd(nd0, nd) + temp16*pld0%na(nd0, &
&                   icv1, is) + pl%na(icv1, is)*(dshd(nd)*mompard0(nd0, &
&                   is, ib, 1)+mompar(is, ib, 1)*dshdd(nd0, nd)+mompard(&
&                   nd, is, ib, 1)*dshd0(nd0)) + pld%na(nd, icv1, is)*&
&                   temp2d(nd0) + temp2*pldd%na(nd0, nd, icv1, is)
                END DO
                t0d(nd) = t0d(nd) + pl%na(icv1, is)*temp16 + temp2*pld%&
&                 na(nd, icv1, is)
              END DO
              DO nd0=1,nbdirs0
                t0d0(nd0) = t0d0(nd0) + pl%na(icv1, is)*temp2d(nd0) + &
&                 temp2*pld0%na(nd0, icv1, is)
              END DO
              t0 = t0 + temp2*pl%na(icv1, is)
              IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
                temp10 = pl%na(icv1, is)/conpar(is, ib, 2)
                DO nd0=1,nbdirs0
                  temp5d(nd0) = (pld0%na(nd0, icv1, is)-temp10*conpard0(&
&                   nd0, is, ib, 2))/conpar(is, ib, 2)
                  temp2d(nd0) = co%dna0(icv1, is)*enipard0(nd0, ib, 2) +&
&                   enipar(ib, 2)*cod0%dna0(nd0, icv1, is)
                END DO
                temp5 = temp10
                temp2 = enipar(ib, 2)*co%dna0(icv1, is)
                DO nd=1,nbdirs
                  temp10 = co%dna0(icv1, is)*enipard(nd, ib, 2) + enipar&
&                   (ib, 2)*cod%dna0(nd, icv1, is)
                  temp16 = temp2/conpar(is, ib, 2)
                  temp9 = pld%na(nd, icv1, is) - temp5*conpard(nd, is, &
&                   ib, 2)
                  DO nd0=1,nbdirs0
                    t1dd(nd0, nd) = t1dd(nd0, nd) + fac_he_anom_bc*(&
&                     temp10*temp5d(nd0)+temp5*(enipard(nd, ib, 2)*cod0%&
&                     dna0(nd0, icv1, is)+co%dna0(icv1, is)*enipardd(nd0&
&                     , nd, ib, 2)+cod%dna0(nd, icv1, is)*enipard0(nd0, &
&                     ib, 2)+enipar(ib, 2)*codd%dna0(nd0, nd, icv1, is))&
&                     +temp16*(pldd%na(nd0, nd, icv1, is)-conpard(nd, is&
&                     , ib, 2)*temp5d(nd0)-temp5*conpardd(nd0, nd, is, &
&                     ib, 2))+temp9*(temp2d(nd0)-temp16*conpard0(nd0, is&
&                     , ib, 2))/conpar(is, ib, 2))
                  END DO
                  t1d(nd) = t1d(nd) + fac_he_anom_bc*(temp5*temp10+temp9&
&                   *temp16)
                END DO
                DO nd0=1,nbdirs0
                  t1d0(nd0) = t1d0(nd0) + fac_he_anom_bc*(temp5*temp2d(&
&                   nd0)+temp2*temp5d(nd0))
                END DO
                t1 = t1 + fac_he_anom_bc*(temp2*temp5)
              END IF
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t2dd(nd0, nd) = t2dd(nd0, nd) + dvdd%fhm(nd0, nd, ifc&
&                   , 0, is) + dvdd%fhm(nd0, nd, ifc, 1, is)
                END DO
                t2d(nd) = t2d(nd) + dvd%fhm(nd, ifc, 0, is) + dvd%fhm(nd&
&                 , ifc, 1, is)
              END DO
              DO nd0=1,nbdirs0
                t2d0(nd0) = t2d0(nd0) + dvd0%fhm(nd0, ifc, 0, is) + dvd0&
&                 %fhm(nd0, ifc, 1, is)
              END DO
              t2 = t2 + dv%fhm(ifc, 0, is) + dv%fhm(ifc, 1, is)
            END IF
          END DO
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs3 = geo%fcpbs(ifc)
          ELSE
            abs3 = -geo%fcpbs(ifc)
          END IF
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 1) = srwdd%shi0(nd0, nd, icv1, 1&
&               ) - (switch%stab_coeff_sheath_ti+1.0_R8)*abs3*(t0d(nd)*&
&               csd0(nd0)+cs*t0dd(nd0, nd)+csd(nd)*t0d0(nd0)+t0*csdd(nd0&
&               , nd)) + temp2*t2dd(nd0, nd) - geo%fcs(ifc)*t1dd(nd0, nd&
&               )
            END DO
            srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) - (switch%&
&             stab_coeff_sheath_ti+1.0_R8)*abs3*(cs*t0d(nd)+t0*csd(nd)) &
&             + temp2*t2d(nd) - geo%fcs(ifc)*t1d(nd)
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 1) = srwd0%shi0(nd0, icv1, 1) - (&
&             switch%stab_coeff_sheath_ti+1.0_R8)*abs3*(cs*t0d0(nd0)+t0*&
&             csd0(nd0)) + temp2*t2d0(nd0) - geo%fcs(ifc)*t1d0(nd0)
          END DO
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) - (switch%&
&           stab_coeff_sheath_ti+1.0_R8)*abs3*(t0*cs) + temp2*t2 - geo%&
&           fcs(ifc)*t1
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs4 = geo%fcpbs(ifc)
          ELSE
            abs4 = -geo%fcpbs(ifc)
          END IF
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1, 0&
&               ) + switch%stab_coeff_sheath_ti*abs4*(t0d(nd)*csd0(nd0)+&
&               cs*t0dd(nd0, nd)+csd(nd)*t0d0(nd0)+t0*csdd(nd0, nd))
            END DO
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + switch%&
&             stab_coeff_sheath_ti*abs4*(cs*t0d(nd)+t0*csd(nd))
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + switch&
&             %stab_coeff_sheath_ti*abs4*(cs*t0d0(nd0)+t0*csd0(nd0))
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + switch%&
&           stab_coeff_sheath_ti*t0*cs*abs4
        END IF
        IF (switch%mdf_fhi .NE. 0) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1, 0&
&               ) + temp2*(dvdd%fhipsch(nd0, nd, ifc, 0)+dvdd%fhipsch(&
&               nd0, nd, ifc, 1))
            END DO
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*(dvd&
&             %fhipsch(nd, ifc, 0)+dvd%fhipsch(nd, ifc, 1))
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + temp2*&
&             (dvd0%fhipsch(nd0, ifc, 0)+dvd0%fhipsch(nd0, ifc, 1))
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(dv%fhipsch(ifc&
&           , 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              t0dd(nd0, nd) = 0.D0
            END DO
            t0d(nd) = 0.d0
          END DO
          t0d0 = 0.D0
          DO is=0,ns-1
            temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp5 = pl%ti(icv1) + pl%ti(icv2)
            temp4 = pl%na(icv1, is) + pl%na(icv2, is)
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              temp5d(nd0) = pld0%ti(nd0, icv1) + pld0%ti(nd0, icv2)
              temp4d(nd0) = pld0%na(nd0, icv1, is) + pld0%na(nd0, icv2, &
&               is)
              temp3d(nd0) = temp5*temp4d(nd0) + temp4*temp5d(nd0)
              tempd(nd0) = temp1*dvd0%vadia(nd0, ifc, 0, is) + temp0*&
&               dvd0%vadia(nd0, ifc, 1, is)
            END DO
            temp3 = temp4*temp5
            temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1, &
&             is)
            DO nd=1,nbdirs
              temp16 = temp1*dvd%vadia(nd, ifc, 0, is) + temp0*dvd%vadia&
&               (nd, ifc, 1, is)
              temp10 = pld%ti(nd, icv1) + pld%ti(nd, icv2)
              temp9 = pld%na(nd, icv1, is) + pld%na(nd, icv2, is)
              temp8 = temp5*temp9 + temp4*temp10
              DO nd0=1,nbdirs0
                t0dd(nd0, nd) = t0dd(nd0, nd) + temp2*(temp16*temp3d(nd0&
&                 )+temp3*(temp1*dvdd%vadia(nd0, nd, ifc, 0, is)+temp0*&
&                 dvdd%vadia(nd0, nd, ifc, 1, is))+temp8*tempd(nd0)+temp&
&                 *(temp9*temp5d(nd0)+temp5*(pldd%na(nd0, nd, icv1, is)+&
&                 pldd%na(nd0, nd, icv2, is))+temp10*temp4d(nd0)+temp4*(&
&                 pldd%ti(nd0, nd, icv1)+pldd%ti(nd0, nd, icv2))))
              END DO
              t0d(nd) = t0d(nd) + temp2*(temp3*temp16+temp*temp8)
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = t0d0(nd0) + temp2*(temp3*tempd(nd0)+temp*&
&               temp3d(nd0))
            END DO
            t0 = t0 + temp2*(temp*temp3)
          END DO
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max7dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              max7d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              max7d0(nd0) = t0d0(nd0)
            END DO
            max7 = t0
          ELSE
            max7 = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                max7dd(nd0, nd) = 0.D0
              END DO
              max7d(nd) = 0.d0
            END DO
            max7d0 = 0.D0
          END IF
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd, icv1, 0&
&               ) + max7dd(nd0, nd)
            END DO
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + max7d(nd)
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) + max7d0&
&             (nd0)
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max7
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                min5dd(nd0, nd) = t0dd(nd0, nd)
              END DO
              min5d(nd) = t0d(nd)
            END DO
            DO nd0=1,nbdirs0
              min5d0(nd0) = t0d0(nd0)
            END DO
            min5 = t0
          ELSE
            min5 = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                min5dd(nd0, nd) = 0.D0
              END DO
              min5d(nd) = 0.d0
            END DO
            min5d0 = 0.D0
          END IF
          temp10 = min5/pl%ti(icv1)
          DO nd0=1,nbdirs0
            temp5d(nd0) = (min5d0(nd0)-temp10*pld0%ti(nd0, icv1))/pl%ti(&
&             icv1)
          END DO
          temp5 = temp10
          DO nd=1,nbdirs
            temp10 = (min5d(nd)-temp5*pld%ti(nd, icv1))/pl%ti(icv1)
            DO nd0=1,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 1) = srwdd%shi0(nd0, nd, icv1, 1&
&               ) + (min5dd(nd0, nd)-pld%ti(nd, icv1)*temp5d(nd0)-temp5*&
&               pldd%ti(nd0, nd, icv1)-temp10*pld0%ti(nd0, icv1))/pl%ti(&
&               icv1)
            END DO
            srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + temp10
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 1) = srwd0%shi0(nd0, icv1, 1) + temp5d&
&             (nd0)
          END DO
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + temp5
        END IF
!wdk    Todo: corrections for BCCON.ne.14
!srv 01.02.09 }

      END DO
    CASE (16) 
!
! -- BCENI=16 -- Feedback boundary condition with constant temperature
!
!
      IF (switch%bceni_16_style .EQ. 0) THEN
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&         'ion temperature feedback by flux ', enipar(ib, 1), ' with ', &
&         enipar(ib, 2), ' on ', bcchar(ib), boundary_location(ib)
          CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        END IF
!       ..compute average temperature on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
        DO nd=1,nbdirsmax
          totfluxd(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          t0d(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          t1d(nd) = 0.d0
        END DO
        totfluxd0 = 0.D0
        t0d0 = 0.D0
        t1d0 = 0.D0
        t0dd = 0.D0
        totfluxdd = 0.D0
        t1dd = 0.D0
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t0dd(nd0, nd) = t0dd(nd0, nd) + geo%fcs(ifc)*dvdd%ni(nd0, &
&               nd, icv1, 0)
!wdk at the moment, totflux only contains ion/neutral heat flux;
!wdk bc_type16_kinetic_energy.eq.1 option not yet included
              t1dd(nd0, nd) = t1dd(nd0, nd) + geo%fcs(ifc)*(dvd%ni(nd, &
&               icv1, 0)*pld0%ti(nd0, icv1)+pl%ti(icv1)*dvdd%ni(nd0, nd&
&               , icv1, 0)+pld%ti(nd, icv1)*dvd0%ni(nd0, icv1, 0)+dv%ni(&
&               icv1, 0)*pldd%ti(nd0, nd, icv1))
              totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%fhi(&
&               nd0, nd, ifc, 0)+dvdd%fhi(nd0, nd, ifc, 1))
            END DO
            t0d(nd) = t0d(nd) + geo%fcs(ifc)*dvd%ni(nd, icv1, 0)
            t1d(nd) = t1d(nd) + geo%fcs(ifc)*(pl%ti(icv1)*dvd%ni(nd, &
&             icv1, 0)+dv%ni(icv1, 0)*pld%ti(nd, icv1))
            totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, ifc, 0)+dvd&
&             %fhi(nd, ifc, 1))
          END DO
          DO nd0=1,nbdirs0
            t0d0(nd0) = t0d0(nd0) + geo%fcs(ifc)*dvd0%ni(nd0, icv1, 0)
            t1d0(nd0) = t1d0(nd0) + geo%fcs(ifc)*(pl%ti(icv1)*dvd0%ni(&
&             nd0, icv1, 0)+dv%ni(icv1, 0)*pld0%ti(nd0, icv1))
            totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fhi(nd0, ifc, &
&             0)+dvd0%fhi(nd0, ifc, 1))
          END DO
          t0 = t0 + geo%fcs(ifc)*dv%ni(icv1, 0)
          t1 = t1 + geo%fcs(ifc)*dv%ni(icv1, 0)*pl%ti(icv1)
          totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
        END DO
        totpardd = 0.D0
        DO nd=1,nbdirs
          temp16 = t1/t0
          temp15 = (t1d(nd)-t0d(nd)*temp16)/t0
          DO nd0=1,nbdirs0
            t1dd(nd0, nd) = (t1dd(nd0, nd)-temp16*t0dd(nd0, nd)-t0d(nd)*&
&             (t1d0(nd0)-temp16*t0d0(nd0))/t0-temp15*t0d0(nd0))/t0
            totpardd(nd0, nd) = fac_he_anom_bc*enipardd(nd0, nd, ib, 1)
          END DO
          t1d(nd) = temp15
          totpard(nd) = fac_he_anom_bc*enipard(nd, ib, 1)
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = (t1d0(nd0)-t1*t0d0(nd0)/t0)/t0
          totpard0(nd0) = fac_he_anom_bc*enipard0(nd0, ib, 1)
        END DO
        t1 = t1/t0
        totpar = fac_he_anom_bc*enipar(ib, 1)
        IF (enipar(ib, 2) .GT. 0.0_R8) THEN
          t3dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t3dd(nd0, nd) = enipardd(nd0, nd, ib, 2)
            END DO
            t3d(nd) = enipard(nd, ib, 2)
          END DO
          DO nd0=1,nbdirs0
            t3d0(nd0) = enipard0(nd0, ib, 2)
          END DO
          t3 = enipar(ib, 2)
        ELSE
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        IF (enipar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_ti
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              t3dd(nd0, nd) = 0.D0
            END DO
            t3d(nd) = 0.d0
          END DO
          t3d0 = 0.D0
        END IF
        IF (totflux .GE. 0.) THEN
          x2dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              x2dd(nd0, nd) = totfluxdd(nd0, nd)
            END DO
            x2d(nd) = totfluxd(nd)
          END DO
          DO nd0=1,nbdirs0
            x2d0(nd0) = totfluxd0(nd0)
          END DO
          x2 = totflux
        ELSE
          x2dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              x2dd(nd0, nd) = -totfluxdd(nd0, nd)
            END DO
            x2d(nd) = -totfluxd(nd)
          END DO
          DO nd0=1,nbdirs0
            x2d0(nd0) = -totfluxd0(nd0)
          END DO
          x2 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          y2dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              y2dd(nd0, nd) = totpardd(nd0, nd)
            END DO
            y2d(nd) = totpard(nd)
          END DO
          DO nd0=1,nbdirs0
            y2d0(nd0) = totpard0(nd0)
          END DO
          y2 = totpar
        ELSE
          y2dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              y2dd(nd0, nd) = -totpardd(nd0, nd)
            END DO
            y2d(nd) = -totpard(nd)
          END DO
          DO nd0=1,nbdirs0
            y2d0(nd0) = -totpard0(nd0)
          END DO
          y2 = -totpar
        END IF
        IF (x2 .LT. y2) THEN
          max8dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              max8dd(nd0, nd) = y2dd(nd0, nd)
            END DO
            max8d(nd) = y2d(nd)
          END DO
          DO nd0=1,nbdirs0
            max8d0(nd0) = y2d0(nd0)
          END DO
          max8 = y2
        ELSE
          max8dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              max8dd(nd0, nd) = x2dd(nd0, nd)
            END DO
            max8d(nd) = x2d(nd)
          END DO
          DO nd0=1,nbdirs0
            max8d0(nd0) = x2d0(nd0)
          END DO
          max8 = x2
        END IF
        temp2 = t3/max8
        DO nd0=1,nbdirs0
          temp2d(nd0) = (t3d0(nd0)-t3*max8d0(nd0)/max8)/max8
          temp5d(nd0) = -(temp2*(totfluxd0(nd0)-totpard0(nd0))+(totflux-&
&           totpar)*temp2d(nd0))
        END DO
        temp5 = -((totflux-totpar)*temp2) + 1.0_R8
        t2dd = 0.D0
        DO nd=1,nbdirs
          temp16 = t3d(nd) - temp2*max8d(nd)
          temp15 = (totflux-totpar)/max8
          temp14 = temp2*(totfluxd(nd)-totpard(nd)) + temp15*temp16
          DO nd0=1,nbdirs0
            t2dd(nd0, nd) = t1d(nd)*temp5d(nd0) + temp5*t1dd(nd0, nd) - &
&             temp14*t1d0(nd0) - t1*((totfluxd(nd)-totpard(nd))*temp2d(&
&             nd0)+temp2*(totfluxdd(nd0, nd)-totpardd(nd0, nd))+temp16*(&
&             totfluxd0(nd0)-totpard0(nd0)-temp15*max8d0(nd0))/max8+&
&             temp15*(t3dd(nd0, nd)-max8d(nd)*temp2d(nd0)-temp2*max8dd(&
&             nd0, nd)))
          END DO
          t2d(nd) = temp5*t1d(nd) - t1*temp14
        END DO
        DO nd0=1,nbdirs0
          t2d0(nd0) = t1*temp5d(nd0) + temp5*t1d0(nd0)
        END DO
        t2 = temp5*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&             'bceni=16: curr_flux, desired_flux, old/new temperature, '&
&                                        , totflux, totpar, t1/qe, t2/qe
!       ..impose temperature
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2dd&
&               (nd0, nd)
              srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
            END DO
            srwd%shi0(nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2d(nd)
            srwd%shi0(nd, icv1, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2d0(nd0)
            srwd0%shi0(nd0, icv1, 1) = 0.D0
          END DO
          srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2
          srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE IF (switch%bceni_16_style .EQ. 1) THEN
!
!srv 16.02.12 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, *) 'BCENI = 16 (style = 1) : '//&
&         'Given integrated ion heat flux with constant Ti '
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location&
&             (ibw)
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCENI = 16 only applicable to core boundaries !')
              CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                   'faulty parameter enipar1')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               ((bceni(ibw) .EQ. 23 .OR. bceni(ibw) .EQ. 24) .OR. bceni&
&               (ibw) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
              CALL XERRAB(&
&                   'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!'&
&                  )
            END IF
          END DO
        END IF
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bceni) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              senipar = 0.0_R8
              DO nd=1,nbdirsmax
                DO nd0=1,nbdirs0
                  senipardd(nd0, nd) = 0.D0
                END DO
                senipard(nd) = 0.d0
              END DO
              senipard0 = 0.D0
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bceni(ibw) .EQ. bceni(ib)) THEN
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      senipardd(nd0, nd) = senipardd(nd0, nd) + enipardd&
&                       (nd0, nd, ibw, 1)
                    END DO
                    senipard(nd) = senipard(nd) + enipard(nd, ibw, 1)
                  END DO
                  DO nd0=1,nbdirs0
                    senipard0(nd0) = senipard0(nd0) + enipard0(nd0, ibw&
&                     , 1)
                  END DO
                  senipar = senipar + enipar(ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCENI=16: Summed value is ', senipar
            tis = 0.0_R8
            nivs = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                tisdd(nd0, nd) = 0.D0
              END DO
              tisd(nd) = 0.d0
            END DO
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                nivsdd(nd0, nd) = 0.D0
              END DO
              nivsd(nd) = 0.d0
            END DO
            tisd0 = 0.D0
            nivsd0 = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      tisdd(nd0, nd) = tisdd(nd0, nd) + geo%cvvol(icv)*(&
&                       pld%ti(nd, icv)*dvd0%ni(nd0, icv, 0)+dv%ni(icv, &
&                       0)*pldd%ti(nd0, nd, icv)+dvd%ni(nd, icv, 0)*pld0&
&                       %ti(nd0, icv)+pl%ti(icv)*dvdd%ni(nd0, nd, icv, 0&
&                       ))
                      nivsdd(nd0, nd) = nivsdd(nd0, nd) + geo%cvvol(icv)&
&                       *dvdd%ni(nd0, nd, icv, 0)
                    END DO
                    tisd(nd) = tisd(nd) + geo%cvvol(icv)*(dv%ni(icv, 0)*&
&                     pld%ti(nd, icv)+pl%ti(icv)*dvd%ni(nd, icv, 0))
                    nivsd(nd) = nivsd(nd) + geo%cvvol(icv)*dvd%ni(nd, &
&                     icv, 0)
                  END DO
                  DO nd0=1,nbdirs0
                    tisd0(nd0) = tisd0(nd0) + geo%cvvol(icv)*(dv%ni(icv&
&                     , 0)*pld0%ti(nd0, icv)+pl%ti(icv)*dvd0%ni(nd0, icv&
&                     , 0))
                    nivsd0(nd0) = nivsd0(nd0) + geo%cvvol(icv)*dvd0%ni(&
&                     nd0, icv, 0)
                  END DO
                  tis = tis + pl%ti(icv)*dv%ni(icv, 0)*geo%cvvol(icv)
                  nivs = nivs + dv%ni(icv, 0)*geo%cvvol(icv)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              temp16 = tis/nivs
              temp15 = (tisd(nd)-nivsd(nd)*temp16)/nivs
              DO nd0=1,nbdirs0
                tisdd(nd0, nd) = (tisdd(nd0, nd)-temp16*nivsdd(nd0, nd)-&
&                 nivsd(nd)*(tisd0(nd0)-temp16*nivsd0(nd0))/nivs-temp15*&
&                 nivsd0(nd0))/nivs
              END DO
              tisd(nd) = temp15
            END DO
            DO nd0=1,nbdirs0
              tisd0(nd0) = (tisd0(nd0)-tis*nivsd0(nd0)/nivs)/nivs
            END DO
            tis = tis/nivs
            totflux = 0.0_R8
            DO nd=1,nbdirsmax
              totfluxd(nd) = 0.d0
            END DO
            totfluxd0 = 0.D0
            totfluxdd = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  IF (switch%mdf_fhi .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (dvdd%fhi_mdf(nd0, nd, ifc, 0)+dvdd%fhi_mdf(&
&                         nd0, nd, ifc, 1))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi_mdf(&
&                       nd, ifc, 0)+dvd%fhi_mdf(nd, ifc, 1))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%&
&                       fhi_mdf(nd0, ifc, 0)+dvd0%fhi_mdf(nd0, ifc, 1))
                    END DO
                    totflux = totflux - temp2*(dv%fhi_mdf(ifc, 0)+dv%&
&                     fhi_mdf(ifc, 1))
                    DO is=0,ns-1
                      temp2 = geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                       ibc-1)
                      DO nd0=1,nbdirs0
                        temp1d(nd0) = geo%fcqalf(ifc, 0)*dvd0%vaecrb(nd0&
&                         , ifc, 0, is) + geo%fcqalf(ifc, 1)*dvd0%vaecrb&
&                         (nd0, ifc, 1, is)
                        temp5d(nd0) = pl%na(icv, is)*pld0%ti(nd0, icv) +&
&                         pl%ti(icv)*pld0%na(nd0, icv, is)
                      END DO
                      temp1 = geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is) +&
&                       geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is)
                      temp5 = pl%ti(icv)*pl%na(icv, is)
                      DO nd=1,nbdirs
                        temp10 = pl%na(icv, is)*pld%ti(nd, icv) + pl%ti(&
&                         icv)*pld%na(nd, icv, is)
                        temp16 = geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, ifc, &
&                         0, is) + geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc&
&                         , 1, is)
                        DO nd0=1,nbdirs0
                          totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - &
&                           temp2*(temp10*temp1d(nd0)+temp1*(pld%ti(nd, &
&                           icv)*pld0%na(nd0, icv, is)+pl%na(icv, is)*&
&                           pldd%ti(nd0, nd, icv)+pld%na(nd, icv, is)*&
&                           pld0%ti(nd0, icv)+pl%ti(icv)*pldd%na(nd0, nd&
&                           , icv, is))+temp16*temp5d(nd0)+temp5*(geo%&
&                           fcqalf(ifc, 0)*dvdd%vaecrb(nd0, nd, ifc, 0, &
&                           is)+geo%fcqalf(ifc, 1)*dvdd%vaecrb(nd0, nd, &
&                           ifc, 1, is)))
                        END DO
                        totfluxd(nd) = totfluxd(nd) - temp2*(temp1*&
&                         temp10+temp5*temp16)
                      END DO
                      DO nd0=1,nbdirs0
                        totfluxd0(nd0) = totfluxd0(nd0) - temp2*(temp1*&
&                         temp5d(nd0)+temp5*temp1d(nd0))
                      END DO
                      totflux = totflux - temp2*(temp5*temp1)
                    END DO
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (dvdd%fhi(nd0, nd, ifc, 0)+dvdd%fhi(nd0, nd, &
&                         ifc, 1))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, &
&                       ifc, 0)+dvd%fhi(nd, ifc, 1))
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fhi(&
&                       nd0, ifc, 0)+dvd0%fhi(nd0, ifc, 1))
                    END DO
                    totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc&
&                     , 1))
                  END IF
                END DO
              END IF
            END DO
            IF (enipar(ib, 2) .GT. 0.0_R8) THEN
              t3dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  t3dd(nd0, nd) = enipardd(nd0, nd, ib, 2)
                END DO
                t3d(nd) = enipard(nd, ib, 2)
              END DO
              DO nd0=1,nbdirs0
                t3d0(nd0) = enipard0(nd0, ib, 2)
              END DO
              t3 = enipar(ib, 2)
            ELSE
              DO nd=1,nbdirsmax
                t3d(nd) = 0.d0
              END DO
              t3d0 = 0.D0
              t3dd = 0.D0
            END IF
            IF (enipar(ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref_ti
              DO nd=1,nbdirsmax
                DO nd0=1,nbdirs0
                  t3dd(nd0, nd) = 0.D0
                END DO
                t3d(nd) = 0.d0
              END DO
              t3d0 = 0.D0
            END IF
            IF (totflux .GE. 0.) THEN
              x3dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  x3dd(nd0, nd) = totfluxdd(nd0, nd)
                END DO
                x3d(nd) = totfluxd(nd)
              END DO
              DO nd0=1,nbdirs0
                x3d0(nd0) = totfluxd0(nd0)
              END DO
              x3 = totflux
            ELSE
              x3dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  x3dd(nd0, nd) = -totfluxdd(nd0, nd)
                END DO
                x3d(nd) = -totfluxd(nd)
              END DO
              DO nd0=1,nbdirs0
                x3d0(nd0) = -totfluxd0(nd0)
              END DO
              x3 = -totflux
            END IF
            IF (x3 .LT. senipar) THEN
              max9dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max9dd(nd0, nd) = senipardd(nd0, nd)
                END DO
                max9d(nd) = senipard(nd)
              END DO
              DO nd0=1,nbdirs0
                max9d0(nd0) = senipard0(nd0)
              END DO
              max9 = senipar
            ELSE
              max9dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max9dd(nd0, nd) = x3dd(nd0, nd)
                END DO
                max9d(nd) = x3d(nd)
              END DO
              DO nd0=1,nbdirs0
                max9d0(nd0) = x3d0(nd0)
              END DO
              max9 = x3
            END IF
            temp2 = t3/max9
            DO nd0=1,nbdirs0
              temp2d(nd0) = (t3d0(nd0)-t3*max9d0(nd0)/max9)/max9
              temp5d(nd0) = -(temp2*(totfluxd0(nd0)-senipard0(nd0))+(&
&               totflux-senipar)*temp2d(nd0))
            END DO
            temp5 = -((totflux-senipar)*temp2) + 1.0_R8
            DO nd=1,nbdirs
              temp16 = t3d(nd) - temp2*max9d(nd)
              temp15 = (totflux-senipar)/max9
              temp14 = temp2*(totfluxd(nd)-senipard(nd)) + temp15*temp16
              DO nd0=1,nbdirs0
                tisdd(nd0, nd) = tisd(nd)*temp5d(nd0) + temp5*tisdd(nd0&
&                 , nd) - temp14*tisd0(nd0) - tis*((totfluxd(nd)-&
&                 senipard(nd))*temp2d(nd0)+temp2*(totfluxdd(nd0, nd)-&
&                 senipardd(nd0, nd))+temp16*(totfluxd0(nd0)-senipard0(&
&                 nd0)-temp15*max9d0(nd0))/max9+temp15*(t3dd(nd0, nd)-&
&                 max9d(nd)*temp2d(nd0)-temp2*max9dd(nd0, nd)))
              END DO
              tisd(nd) = temp5*tisd(nd) - tis*temp14
            END DO
            DO nd0=1,nbdirs0
              tisd0(nd0) = temp5*tisd0(nd0) + tis*temp5d(nd0)
            END DO
            tis = tis*temp5
            WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&           totflux, ' SENIPAR=', senipar
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      srwdd%shi0(nd0, nd, icv, 0) = vbig*ne00*geo%fcs(&
&                       ifc)*tisdd(nd0, nd)
                      srwdd%shi0(nd0, nd, icv, 1) = 0.D0
                    END DO
                    srwd%shi0(nd, icv, 0) = vbig*ne00*geo%fcs(ifc)*tisd(&
&                     nd)
                    srwd%shi0(nd, icv, 1) = 0.d0
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%shi0(nd0, icv, 0) = vbig*ne00*geo%fcs(ifc)*&
&                     tisd0(nd0)
                    srwd0%shi0(nd0, icv, 1) = 0.D0
                  END DO
                  srw%shi0(icv, 0) = vbig*ne00*tis*geo%fcs(ifc)
                  srw%shi0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
                END DO
              END IF
            END DO
            once_bceni = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCENI=16, ONLY AVAILABLE FOR CORE!')
        END IF
      ELSE
        CALL XERRAB(' Incorrect style of boundary condition')
      END IF
    CASE (17) 
!
! -- BCENI=17 -- Feedback boundary condition with constant temperature
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 17 : ion temperature feedback by flux ', enipar(ib, 1)&
&       , ' with ', enipar(ib, 2), ' on ', bcchar(ib), boundary_location&
&       (ib)
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        CALL XERTST(enipar(ib, 2) .GT. 0, 'faulty parameter enipar2')
        CALL XERTST(bcene(ib) .EQ. bceni(ib), &
&             'both bcene and bceni should be set to 17')
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        CALL XERTST(enepar(ib, 2) .GT. 0, 'faulty parameter enepar2')
      END IF
      IF (.NOT.(bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A')) THEN
! already handled when the electron heat bc was handled
! see label 2980
        CALL XERRAB('B2STBC -- BCENI=17, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (18) 
!
! -- BCENI=18 -- FRACTIONAL DROP CONDITION (FOR EDGE2D COMPARISON)
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI = 18 : ion temperature fractional drop', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .LT. 1.0_R8, &
&             'BCENI = 18, ENIPAR(,1) => 1')
        t1dd = 0.D0
      ELSE
        t1dd = 0.D0
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t1dd(nd0, nd) = (1.0_R8-enipar(ib, 1))*pldd%ti(nd0, nd, icv2&
&             ) - pld%ti(nd, icv2)*enipard0(nd0, ib, 1) - enipard(nd, ib&
&             , 1)*pld0%ti(nd0, icv2) - pl%ti(icv2)*enipardd(nd0, nd, ib&
&             , 1)
            srwdd%shi0(nd0, nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1dd(&
&             nd0, nd)
            srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
          END DO
          t1d(nd) = (1.0_R8-enipar(ib, 1))*pld%ti(nd, icv2) - pl%ti(icv2&
&           )*enipard(nd, ib, 1)
          srwd%shi0(nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1d(nd)
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = (1.0_R8-enipar(ib, 1))*pld0%ti(nd0, icv2) - pl%ti(&
&           icv2)*enipard0(nd0, ib, 1)
          srwd0%shi0(nd0, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1d0(nd0)
          srwd0%shi0(nd0, icv1, 1) = 0.D0
        END DO
        t1 = (1.0_R8-enipar(ib, 1))*pl%ti(icv2)
        srw%shi0(icv1, 0) = vbig*ne00*t1*geo%fcs(ifc)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (19) 
!
! -- BCENI=19 -- PRESCRIBE THE DECAY LENGTH FOR THE ION TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENI = 19 not adapted for WG')
!
! -- BCENI=20 -- Feedback boundary condition with constant temperature
!
    CASE (20) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 20 : ion temperature feedback by flux (neo) ', enipar(&
&       ib, 1), ' with ', enipar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        tiave = 0.0_R8
        niave = 0.0_R8
        DO nd=1,nbdirsmax
          totfluxd(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          niaved(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          t0d(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          tiaved(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          weightd(nd) = 0.d0
        END DO
        weightdd = 0.D0
        totfluxd0 = 0.D0
        niaved0 = 0.D0
        t0d0 = 0.D0
        t0dd = 0.D0
        tiaved0 = 0.D0
        weightd0 = 0.D0
        niavedd = 0.D0
        totfluxdd = 0.D0
        tiavedd = 0.D0
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%fhi(&
&               nd0, nd, ifc, 0)+dvdd%fhi(nd0, nd, ifc, 1))
              t0dd(nd0, nd) = t0dd(nd0, nd) + geo%cvvol(icv1)*(pld%ti(nd&
&               , icv1)*dvd0%ni(nd0, icv1, 0)+dv%ni(icv1, 0)*pldd%ti(nd0&
&               , nd, icv1)+dvd%ni(nd, icv1, 0)*pld0%ti(nd0, icv1)+pl%ti&
&               (icv1)*dvdd%ni(nd0, nd, icv1, 0))
              weightdd(nd0, nd) = weightdd(nd0, nd) + geo%cvvol(icv1)*&
&               dvdd%ni(nd0, nd, icv1, 0)
              tiavedd(nd0, nd) = tiavedd(nd0, nd) + geo%cvvol(icv2)*(pld&
&               %ti(nd, icv2)*dvd0%ni(nd0, icv2, 0)+dv%ni(icv2, 0)*pldd%&
&               ti(nd0, nd, icv2)+dvd%ni(nd, icv2, 0)*pld0%ti(nd0, icv2)&
&               +pl%ti(icv2)*dvdd%ni(nd0, nd, icv2, 0))
              niavedd(nd0, nd) = niavedd(nd0, nd) + geo%cvvol(icv2)*dvdd&
&               %ni(nd0, nd, icv2, 0)
            END DO
            totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, ifc, 0)+dvd&
&             %fhi(nd, ifc, 1))
            t0d(nd) = t0d(nd) + geo%cvvol(icv1)*(dv%ni(icv1, 0)*pld%ti(&
&             nd, icv1)+pl%ti(icv1)*dvd%ni(nd, icv1, 0))
            weightd(nd) = weightd(nd) + geo%cvvol(icv1)*dvd%ni(nd, icv1&
&             , 0)
            tiaved(nd) = tiaved(nd) + geo%cvvol(icv2)*(dv%ni(icv2, 0)*&
&             pld%ti(nd, icv2)+pl%ti(icv2)*dvd%ni(nd, icv2, 0))
            niaved(nd) = niaved(nd) + geo%cvvol(icv2)*dvd%ni(nd, icv2, 0&
&             )
          END DO
          DO nd0=1,nbdirs0
            totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fhi(nd0, ifc, &
&             0)+dvd0%fhi(nd0, ifc, 1))
            t0d0(nd0) = t0d0(nd0) + geo%cvvol(icv1)*(dv%ni(icv1, 0)*pld0&
&             %ti(nd0, icv1)+pl%ti(icv1)*dvd0%ni(nd0, icv1, 0))
            weightd0(nd0) = weightd0(nd0) + geo%cvvol(icv1)*dvd0%ni(nd0&
&             , icv1, 0)
            tiaved0(nd0) = tiaved0(nd0) + geo%cvvol(icv2)*(dv%ni(icv2, 0&
&             )*pld0%ti(nd0, icv2)+pl%ti(icv2)*dvd0%ni(nd0, icv2, 0))
            niaved0(nd0) = niaved0(nd0) + geo%cvvol(icv2)*dvd0%ni(nd0, &
&             icv2, 0)
          END DO
          totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
          t0 = t0 + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv1)
          weight = weight + dv%ni(icv1, 0)*geo%cvvol(icv1)
          tiave = tiave + pl%ti(icv2)*dv%ni(icv2, 0)*geo%cvvol(icv2)
          niave = niave + dv%ni(icv2, 0)*geo%cvvol(icv2)
        END DO
        DO nd=1,nbdirs
          temp16 = t0/weight
          temp15 = (t0d(nd)-weightd(nd)*temp16)/weight
          DO nd0=1,nbdirs0
            t0dd(nd0, nd) = (t0dd(nd0, nd)-temp16*weightdd(nd0, nd)-&
&             weightd(nd)*(t0d0(nd0)-temp16*weightd0(nd0))/weight-temp15&
&             *weightd0(nd0))/weight
          END DO
          t0d(nd) = temp15
          temp16 = tiave/niave
          temp15 = (tiaved(nd)-niaved(nd)*temp16)/niave
          DO nd0=1,nbdirs0
            tiavedd(nd0, nd) = (tiavedd(nd0, nd)-temp16*niavedd(nd0, nd)&
&             -niaved(nd)*(tiaved0(nd0)-temp16*niaved0(nd0))/niave-&
&             temp15*niaved0(nd0))/niave
          END DO
          tiaved(nd) = temp15
        END DO
        DO nd0=1,nbdirs0
          t0d0(nd0) = (t0d0(nd0)-t0*weightd0(nd0)/weight)/weight
          tiaved0(nd0) = (tiaved0(nd0)-tiave*niaved0(nd0)/niave)/niave
        END DO
        t0 = t0/weight
        tiave = tiave/niave
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        IF (enipar(ib, 2) .GT. 0.0_R8) THEN
          t3dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t3dd(nd0, nd) = enipardd(nd0, nd, ib, 2)
            END DO
            t3d(nd) = enipard(nd, ib, 2)
          END DO
          DO nd0=1,nbdirs0
            t3d0(nd0) = enipard0(nd0, ib, 2)
          END DO
          t3 = enipar(ib, 2)
        ELSE
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        IF (enipar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_ti
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              t3dd(nd0, nd) = 0.D0
            END DO
            t3d(nd) = 0.d0
          END DO
          t3d0 = 0.D0
        END IF
        temp16 = t3/enipar(ib, 1)
        temp2 = temp16
        DO nd0=1,nbdirs0
          temp2d(nd0) = (t3d0(nd0)-temp16*enipard0(nd0, ib, 1))/enipar(&
&           ib, 1)
          temp5d(nd0) = -(temp2*(totfluxd0(nd0)-enipard0(nd0, ib, 1))+(&
&           totflux-enipar(ib, 1))*temp2d(nd0))
        END DO
        temp5 = -((totflux-enipar(ib, 1))*temp2) + 1.0_R8
        t1dd = 0.D0
        DO nd=1,nbdirs
          temp16 = t3d(nd) - temp2*enipard(nd, ib, 1)
          temp15 = (totflux-enipar(ib, 1))/enipar(ib, 1)
          temp14 = totfluxd(nd) - enipard(nd, ib, 1)
          temp13 = temp2*temp14 + temp15*temp16
          DO nd0=1,nbdirs0
            t1dd(nd0, nd) = t0d(nd)*temp5d(nd0) + temp5*t0dd(nd0, nd) - &
&             temp13*t0d0(nd0) - t0*(temp14*temp2d(nd0)+temp2*(totfluxdd&
&             (nd0, nd)-enipardd(nd0, nd, ib, 1))+temp16*(totfluxd0(nd0)&
&             -(temp15+1.0)*enipard0(nd0, ib, 1))/enipar(ib, 1)+temp15*(&
&             t3dd(nd0, nd)-enipard(nd, ib, 1)*temp2d(nd0)-temp2*&
&             enipardd(nd0, nd, ib, 1)))
          END DO
          t1d(nd) = temp5*t0d(nd) - t0*temp13
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = t0*temp5d(nd0) + temp5*t0d0(nd0)
        END DO
        t1 = temp5*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New ion temp :', t0/qe, t1&
&                                        /qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*ne00*geo%fcs(ifc)
          DO nd0=1,nbdirs0
            temp1d(nd0) = (t1d0(nd0)-t1*tiaved0(nd0)/tiave)/tiave
          END DO
          temp1 = t1/tiave
          DO nd=1,nbdirs
            temp16 = t1d(nd) - temp1*tiaved(nd)
            temp10 = pl%ti(icv2)/tiave
            DO nd0=1,nbdirs0
              srwdd%shi0(nd0, nd, icv1, 0) = temp2*(pld%ti(nd, icv2)*&
&               temp1d(nd0)+temp1*pldd%ti(nd0, nd, icv2)+temp16*(pld0%ti&
&               (nd0, icv2)-temp10*tiaved0(nd0))/tiave+temp10*(t1dd(nd0&
&               , nd)-tiaved(nd)*temp1d(nd0)-temp1*tiavedd(nd0, nd)))
              srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
            END DO
            srwd%shi0(nd, icv1, 0) = temp2*(temp1*pld%ti(nd, icv2)+&
&             temp10*temp16)
            srwd%shi0(nd, icv1, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%shi0(nd0, icv1, 0) = temp2*(temp1*pld0%ti(nd0, icv2)+&
&             pl%ti(icv2)*temp1d(nd0))
            srwd0%shi0(nd0, icv1, 1) = 0.D0
          END DO
          srw%shi0(icv1, 0) = temp2*(pl%ti(icv2)*temp1)
          srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENI=20, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (21) 
!
!! FIXME: Clash here with 5.0/5.1 BCENI=21 type
!xpb Careful here because of BC number clash
! From 5.0: starting at version 01.001.030
! -- BCCON=21 -- constant ion temperature scaled by ion temperature on the ring bc_type21_ref away
! has been moved up to next available number (BCENI=25)
!
! From 5.2, after version number 01.001.078:
! -- BCENI=21 -- from b2stbc_spb                                     !srv 01.02.09 {
!
      CALL XERRAB('b2stbc_phys -- BCENI = 21 not adapted for WG')
!
! -- BCENI=22 -- RADIAL LEAKAGE CONDITION FOR THE ION TEMPERATURE    !srv 23.07.10 {
!                SPECIFIES A TEMPERATURE GRADIENT SUCH THAT THE DIFFUSIVE
!                FLUX IS SET TO BE EQUIVALENT TO A LEAKAGE VELOCITY, IN
!                UNITS OF THE COLLECTIVE ION THERMAL VELOCITY
!
    CASE (22) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI = 22 : with ENIPAR(IB,1)= ', enipar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        t2dd = 0.D0
        csbdd = 0.D0
        arg13dd = 0.D0
      ELSE
        t2dd = 0.D0
        csbdd = 0.D0
        arg13dd = 0.D0
      END IF
!wdk    Notes:
!wdk     * need correction for misaligned grids -> t1
!wdk     * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = geo%fcqalf(ifc, 1)
        t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&         fcqbet(ifc, 0)
        t2 = 0.0_R8
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            t2dd(nd0, nd) = 0.D0
          END DO
          t2d(nd) = 0.d0
        END DO
        t2d0 = 0.D0
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            arg13 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*&
&             mp)
            temp10 = SQRT(arg13)
            DO nd0=1,nbdirs0
              arg13d0(nd0) = (pl%te(icv1)*rtd0%rza(nd0, icv1, is)+rt%rza&
&               (icv1, is)*pld0%te(nd0, icv1)+pld0%ti(nd0, icv1))/(am(is&
&               )*mp)
              IF (arg13 .EQ. 0.D0) THEN
                temp5d(nd0) = 0.D0
              ELSE
                temp5d(nd0) = arg13d0(nd0)/(2.0*temp10)
              END IF
              csbd0(nd0) = temp5d(nd0)
            END DO
            temp5 = temp10
            csb = temp5
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                arg13dd(nd0, nd) = (rtd%rza(nd, icv1, is)*pld0%te(nd0, &
&                 icv1)+pl%te(icv1)*rtdd%rza(nd0, nd, icv1, is)+pld%te(&
&                 nd, icv1)*rtd0%rza(nd0, icv1, is)+rt%rza(icv1, is)*&
&                 pldd%te(nd0, nd, icv1)+pldd%ti(nd0, nd, icv1))/(am(is)&
&                 *mp)
              END DO
              arg13d(nd) = (pl%te(icv1)*rtd%rza(nd, icv1, is)+rt%rza(&
&               icv1, is)*pld%te(nd, icv1)+pld%ti(nd, icv1))/(am(is)*mp)
              IF (arg13 .EQ. 0.d0) THEN
                DO nd0=1,nbdirs0
                  csbdd(nd0, nd) = 0.D0
                END DO
                csbd(nd) = 0.d0
              ELSE
                temp10 = arg13d(nd)/(2.0*temp5)
                DO nd0=1,nbdirs0
                  csbdd(nd0, nd) = (arg13dd(nd0, nd)-temp10*2.0*temp5d(&
&                   nd0))/(2.0*temp5)
                END DO
                csbd(nd) = temp10
              END IF
              DO nd0=1,nbdirs0
                t2dd(nd0, nd) = t2dd(nd0, nd) + csbd(nd)*pld0%na(nd0, &
&                 icv1, is) + pl%na(icv1, is)*csbdd(nd0, nd) + pld%na(nd&
&                 , icv1, is)*csbd0(nd0) + csb*pldd%na(nd0, nd, icv1, is&
&                 )
              END DO
              t2d(nd) = t2d(nd) + pl%na(icv1, is)*csbd(nd) + csb*pld%na(&
&               nd, icv1, is)
            END DO
            DO nd0=1,nbdirs0
              t2d0(nd0) = t2d0(nd0) + pl%na(icv1, is)*csbd0(nd0) + csb*&
&               pld0%na(nd0, icv1, is)
            END DO
            t2 = t2 + csb*pl%na(icv1, is)
          END IF
        END DO
        temp2 = vbig*ne00*ev
        temp1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1
        DO nd0=1,nbdirs0
          temp0d(nd0) = t0*pld0%ti(nd0, icv2) - temp1*(pld0%ti(nd0, mpg%&
&           fcvx(ifc, 2))-pld0%ti(nd0, mpg%fcvx(ifc, 1)))
        END DO
        temp0 = t0*pl%ti(icv2) - temp1*(pl%ti(mpg%fcvx(ifc, 2))-pl%ti(&
&         mpg%fcvx(ifc, 1)))
        DO nd=1,nbdirs
          temp16 = t0*pld%ti(nd, icv2) - temp1*(pld%ti(nd, mpg%fcvx(ifc&
&           , 2))-pld%ti(nd, mpg%fcvx(ifc, 1)))
          DO nd0=1,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 0) = temp2*(cod%chci(nd, ifc, 1)*&
&             temp0d(nd0)+temp0*codd%chci(nd0, nd, ifc, 1)+temp16*cod0%&
&             chci(nd0, ifc, 1)+co%chci(ifc, 1)*(t0*pldd%ti(nd0, nd, &
&             icv2)-temp1*(pldd%ti(nd0, nd, mpg%fcvx(ifc, 2))-pldd%ti(&
&             nd0, nd, mpg%fcvx(ifc, 1)))))
          END DO
          srwd%shi0(nd, icv1, 0) = temp2*(temp0*cod%chci(nd, ifc, 1)+co%&
&           chci(ifc, 1)*temp16)
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 0) = temp2*(temp0*cod0%chci(nd0, ifc, 1)&
&           +co%chci(ifc, 1)*temp0d(nd0))
        END DO
        srw%shi0(icv1, 0) = temp2*(co%chci(ifc, 1)*temp0)
        temp2 = vbig*ne00*ev
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 1) = -(temp2*(t0*codd%chci(nd0, nd&
&             , ifc, 1)-geo%fcs(ifc)*(enipard(nd, ib, 1)*t2d0(nd0)+t2*&
&             enipardd(nd0, nd, ib, 1)+t2d(nd)*enipard0(nd0, ib, 1)+&
&             enipar(ib, 1)*t2dd(nd0, nd))))
          END DO
          srwd%shi0(nd, icv1, 1) = -(temp2*(t0*cod%chci(nd, ifc, 1)-geo%&
&           fcs(ifc)*(t2*enipard(nd, ib, 1)+enipar(ib, 1)*t2d(nd))))
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 1) = -(temp2*(t0*cod0%chci(nd0, ifc, 1)-&
&           geo%fcs(ifc)*(t2*enipard0(nd0, ib, 1)+enipar(ib, 1)*t2d0(nd0&
&           ))))
        END DO
        srw%shi0(icv1, 1) = -(temp2*(t0*co%chci(ifc, 1)-geo%fcs(ifc)*(&
&         enipar(ib, 1)*t2)))
!srv 23.07.10 }
      END DO
    CASE (23) 
!
! -- BCENI=23 -- PRESCRIBE THE POLOIDALLY AVERAGED VALUE OF THE ION TEMPERATURE
! AND INTRODUCE A POLOIDAL VARIATION AS CLOSE AS POSSIBLE TO NEOCLASSICAL SOLUTION.
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 21,22,23
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7)') &
&       'BCENI = 23 : specified ion temperature ', enipar(ib, 1)
!          write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 23 only applicable to core boundaries !')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ib, 1) .EQ. &
&                 enipar(ibw, 1), &
&                 'BCENI = 23, inconsistent ENIPAR(,1) values!')
            IF (.NOT.((bccon(ismain, ib) .EQ. 21 .OR. bccon(ismain, ib) &
&               .EQ. 22) .OR. bccon(ismain, ib) .EQ. 23)) THEN
              WRITE(0, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=23'
              WRITE(*, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=23'
!srv 21.09.12
              WRITE(*, '(1x,a)') &
&             'Please ensure that this boundary condition '//&
&             'is consistent with '//&
&             'the ion density boundary condition'
            END IF
            IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&           THEN
              WRITE(0, *) &
&             'Use of BCENI=23 only meant for single-fluid runs!'
              WRITE(0, *) 'Use BCENI=26 instead!'
              WRITE(6, *) &
&             'Use of BCENI=23 only meant for single-fluid runs!'
              WRITE(6, *) 'Use BCENI=26 instead!'
            END IF
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 24) .OR. bceni(ibw&
&             ) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
        CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ibw, 1) .GT. &
&             0.0_R8, 'BCENI = 23, ENIPAR(,1) !> 0')
      END IF
!
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                    'Compile with -DASTRA option to couple with ASTRA!'&
&                                         )
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! Poloidally volume-averaged electron density in the cell next to boundary
          t2 = 0.0_R8
! Poloidally volume-averaged electron density in the boundary cell
          t3 = 0.0_R8
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t2d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
          t2dd = 0.D0
          t1d0 = 0.D0
          t2d0 = 0.D0
          t3d0 = 0.D0
          t3dd = 0.D0
          t1dd = 0.D0
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd&
&                     %ti(nd0, nd, icv2)
                    t2dd(nd0, nd) = t2dd(nd0, nd) + geo%cvvol(icv2)*dvdd&
&                     %ne(nd0, nd, icv2)
                    t3dd(nd0, nd) = t3dd(nd0, nd) + geo%cvvol(icv2)*dvdd&
&                     %ne(nd0, nd, icv1)
                  END DO
                  t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)
                  t2d(nd) = t2d(nd) + geo%cvvol(icv2)*dvd%ne(nd, icv2)
                  t3d(nd) = t3d(nd) + geo%cvvol(icv2)*dvd%ne(nd, icv1)
                END DO
                DO nd0=1,nbdirs0
                  t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%ti(nd0, &
&                   icv2)
                  t2d0(nd0) = t2d0(nd0) + geo%cvvol(icv2)*dvd0%ne(nd0, &
&                   icv2)
                  t3d0(nd0) = t3d0(nd0) + geo%cvvol(icv2)*dvd0%ne(nd0, &
&                   icv1)
                END DO
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                t2 = t2 + dv%ne(icv2)*geo%cvvol(icv2)
                t3 = t3 + dv%ne(icv1)*geo%cvvol(icv2)
              END DO
            END IF
          END DO
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t1dd(nd0, nd) = t1dd(nd0, nd)/t0
              t2dd(nd0, nd) = t2dd(nd0, nd)/t0
              t3dd(nd0, nd) = t3dd(nd0, nd)/t0
            END DO
            t1d(nd) = t1d(nd)/t0
            t2d(nd) = t2d(nd)/t0
            t3d(nd) = t3d(nd)/t0
          END DO
          DO nd0=1,nbdirs0
            t1d0(nd0) = t1d0(nd0)/t0
            t2d0(nd0) = t2d0(nd0)/t0
            t3d0(nd0) = t3d0(nd0)/t0
          END DO
          t1 = t1/t0
          t2 = t2/t0
          t3 = t3/t0
          DO ibw=ib,nbc
!lk 12.12.12 }
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                IF (mpg%cvonclosedsurface(icv2)) THEN
                  temp2 = vbig*ne00*geo%fcs(ifc)
                  temp1 = ev*t3*enipar(ibw, 1)
                  temp10 = (pl%ti(icv2)-t1)/temp1
                  DO nd0=1,nbdirs0
                    temp1d(nd0) = ev*(enipar(ibw, 1)*t3d0(nd0)+t3*&
&                     enipard0(nd0, ibw, 1))
                    temp5d(nd0) = t1*t2*(pld0%ti(nd0, icv2)-t1d0(nd0)-&
&                     temp10*temp1d(nd0))/temp1 + temp10*(t2*t1d0(nd0)+&
&                     t1*t2d0(nd0))
                  END DO
                  temp5 = temp10*(t1*t2)
                  DO nd=1,nbdirs
                    temp10 = pld%ti(nd, icv2) - t1d(nd)
                    temp16 = t2*t1d(nd) + t1*t2d(nd)
                    temp15 = ev*enipar(ibw, 1)*t3d(nd) + ev*t3*enipard(&
&                     nd, ibw, 1)
                    temp14 = (t1*t2*temp10+(pl%ti(icv2)-t1)*temp16-temp5&
&                     *temp15)/temp1
                    DO nd0=1,nbdirs0
                      srwdd%shi0(nd0, nd, icv1, 0) = srwdd%shi0(nd0, nd&
&                       , icv1, 0) + temp2*(ev*enipardd(nd0, nd, ibw, 1)&
&                       +(temp10*(t2*t1d0(nd0)+t1*t2d0(nd0))+t1*t2*(pldd&
&                       %ti(nd0, nd, icv2)-t1dd(nd0, nd))+temp16*(pld0%&
&                       ti(nd0, icv2)-t1d0(nd0))+(pl%ti(icv2)-t1)*(t1d(&
&                       nd)*t2d0(nd0)+t2*t1dd(nd0, nd)+t2d(nd)*t1d0(nd0)&
&                       +t1*t2dd(nd0, nd))-temp15*temp5d(nd0)-temp5*(ev*&
&                       (t3d(nd)*enipard0(nd0, ibw, 1)+enipar(ibw, 1)*&
&                       t3dd(nd0, nd))+ev*(enipard(nd, ibw, 1)*t3d0(nd0)&
&                       +t3*enipardd(nd0, nd, ibw, 1)))-temp14*temp1d(&
&                       nd0))/temp1)
                      srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
                    END DO
                    srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + &
&                     temp2*(ev*enipard(nd, ibw, 1)+temp14)
                    srwd%shi0(nd, icv1, 1) = 0.d0
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%shi0(nd0, icv1, 0) = srwd0%shi0(nd0, icv1, 0) &
&                     + temp2*(ev*enipard0(nd0, ibw, 1)+temp5d(nd0))
                    srwd0%shi0(nd0, icv1, 1) = 0.D0
                  END DO
                  srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(ev*&
&                   enipar(ibw, 1)+temp5)
                  srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
                END IF
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB(&
&              'B2STBC -- BCENI=23 IS AVAILABLE FOR CORE BOUNDARY ONLY.'&
&              )
        END IF
      END IF
    CASE (24) 
!
! -- BCENI=24 -- Feedback boundary condition with prescribed total ion heat flux,
!                constant poloidally averaged ion temperature and a
!                poloidal variation as close as possible to neoclassical solution.
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 21,22,23
!
!IYS 04.03.2013 {
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a)') 'BCENI = 24 : Given integrated ion heat flux', &
&       ' with constant Ti '
!          write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 24 only applicable to core boundaries !')
            CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                 'faulty parameter enipar1')
            IF (.NOT.((bccon(ismain, ib) .EQ. 21 .OR. bccon(ismain, ib) &
&               .EQ. 22) .OR. bccon(ismain, ib) .EQ. 23)) THEN
              WRITE(0, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=24'
              WRITE(*, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=24'
!srv 21.09.12
              WRITE(*, '(1x,a)') &
&             'Please ensure that this boundary condition '//&
&             'is consistent with '//&
&             'the ion density boundary condition'
            END IF
            IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&           THEN
              WRITE(0, *) &
&             'Use of BCENI=24 only meant for single-fluid runs!'
              WRITE(0, *) 'Use BCENI=27 instead!'
              WRITE(6, *) &
&             'Use of BCENI=24 only meant for single-fluid runs!'
              WRITE(6, *) 'Use BCENI=27 instead!'
            END IF
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
!srv 16.02.12 }
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) THEN
          CALL XERRAB(&
&               'Compile with -DASTRA option to couple with ASTRA!')
        ELSE
          senipar = 0.0_R8
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              senipardd(nd0, nd) = 0.D0
            END DO
            senipard(nd) = 0.d0
          END DO
          senipard0 = 0.D0
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  senipardd(nd0, nd) = senipardd(nd0, nd) + enipardd(nd0&
&                   , nd, ibw, 1)
                END DO
                senipard(nd) = senipard(nd) + enipard(nd, ibw, 1)
              END DO
              DO nd0=1,nbdirs0
                senipard0(nd0) = senipard0(nd0) + enipard0(nd0, ibw, 1)
              END DO
              senipar = senipar + enipar(ibw, 1)
            END IF
          END DO
        END IF
        WRITE(*, *) 'BCENI=24: Summed value is ', senipar
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Poloidally density-averaged ion temperature in the boundary cell     !IYS 21.01.2016
          tis = 0.0_R8
          nivs = 0.0_R8
          totflux = 0.0_R8
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! Poloidally volume-averaged electron density in the cell next to boundary
          t2 = 0.0_R8
! Poloidally volume-averaged electron density in the boundary cell
          t3 = 0.0_R8
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              tisdd(nd0, nd) = 0.D0
            END DO
            tisd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              nivsdd(nd0, nd) = 0.D0
            END DO
            nivsd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            totfluxd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t2d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
          tisd0 = 0.D0
          nivsd0 = 0.D0
          totfluxd0 = 0.D0
          t2dd = 0.D0
          t1d0 = 0.D0
          t2d0 = 0.D0
          t3d0 = 0.D0
          t3dd = 0.D0
          totfluxdd = 0.D0
          t1dd = 0.D0
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd&
&                     %ti(nd0, nd, icv2)
                    tisdd(nd0, nd) = tisdd(nd0, nd) + geo%cvvol(icv2)*(&
&                     pld%ti(nd, icv1)*dvd0%ni(nd0, icv1, 0)+dv%ni(icv1&
&                     , 0)*pldd%ti(nd0, nd, icv1)+dvd%ni(nd, icv1, 0)*&
&                     pld0%ti(nd0, icv1)+pl%ti(icv1)*dvdd%ni(nd0, nd, &
&                     icv1, 0))
                    nivsdd(nd0, nd) = nivsdd(nd0, nd) + geo%cvvol(icv2)*&
&                     dvdd%ni(nd0, nd, icv1, 0)
                    t2dd(nd0, nd) = t2dd(nd0, nd) + geo%cvvol(icv2)*dvdd&
&                     %ne(nd0, nd, icv2)
                    t3dd(nd0, nd) = t3dd(nd0, nd) + geo%cvvol(icv2)*dvdd&
&                     %ne(nd0, nd, icv1)
                  END DO
                  t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)
                  tisd(nd) = tisd(nd) + geo%cvvol(icv2)*(dv%ni(icv1, 0)*&
&                   pld%ti(nd, icv1)+pl%ti(icv1)*dvd%ni(nd, icv1, 0))
                  nivsd(nd) = nivsd(nd) + geo%cvvol(icv2)*dvd%ni(nd, &
&                   icv1, 0)
                  t2d(nd) = t2d(nd) + geo%cvvol(icv2)*dvd%ne(nd, icv2)
                  t3d(nd) = t3d(nd) + geo%cvvol(icv2)*dvd%ne(nd, icv1)
                END DO
                DO nd0=1,nbdirs0
                  t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%ti(nd0, &
&                   icv2)
                  tisd0(nd0) = tisd0(nd0) + geo%cvvol(icv2)*(dv%ni(icv1&
&                   , 0)*pld0%ti(nd0, icv1)+pl%ti(icv1)*dvd0%ni(nd0, &
&                   icv1, 0))
                  nivsd0(nd0) = nivsd0(nd0) + geo%cvvol(icv2)*dvd0%ni(&
&                   nd0, icv1, 0)
                  t2d0(nd0) = t2d0(nd0) + geo%cvvol(icv2)*dvd0%ne(nd0, &
&                   icv2)
                  t3d0(nd0) = t3d0(nd0) + geo%cvvol(icv2)*dvd0%ne(nd0, &
&                   icv1)
                END DO
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                tis = tis + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv2)
                nivs = nivs + dv%ni(icv1, 0)*geo%cvvol(icv2)
                t2 = t2 + dv%ne(icv2)*geo%cvvol(icv2)
                t3 = t3 + dv%ne(icv1)*geo%cvvol(icv2)
                IF (switch%mdf_fhi .NE. 0) THEN
                  temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(&
&                       dvdd%fhi_mdf(nd0, nd, ifc, 0)+dvdd%fhi_mdf(nd0, &
&                       nd, ifc, 1))
                    END DO
                    totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi_mdf(nd&
&                     , ifc, 0)+dvd%fhi_mdf(nd, ifc, 1))
                  END DO
                  DO nd0=1,nbdirs0
                    totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%&
&                     fhi_mdf(nd0, ifc, 0)+dvd0%fhi_mdf(nd0, ifc, 1))
                  END DO
                  totflux = totflux - temp2*(dv%fhi_mdf(ifc, 0)+dv%&
&                   fhi_mdf(ifc, 1))
                  DO is=0,ns-1
                    temp2 = geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)
                    DO nd0=1,nbdirs0
                      temp1d(nd0) = geo%fcqalf(ifc, 0)*dvd0%vaecrb(nd0, &
&                       ifc, 0, is) + geo%fcqalf(ifc, 1)*dvd0%vaecrb(nd0&
&                       , ifc, 1, is)
                      temp5d(nd0) = pl%na(icv1, is)*pld0%ti(nd0, icv1) +&
&                       pl%ti(icv1)*pld0%na(nd0, icv1, is)
                    END DO
                    temp1 = geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is) + &
&                     geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is)
                    temp5 = pl%ti(icv1)*pl%na(icv1, is)
                    DO nd=1,nbdirs
                      temp10 = pl%na(icv1, is)*pld%ti(nd, icv1) + pl%ti(&
&                       icv1)*pld%na(nd, icv1, is)
                      temp16 = geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, ifc, 0&
&                       , is) + geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc, 1&
&                       , is)
                      DO nd0=1,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (temp10*temp1d(nd0)+temp1*(pld%ti(nd, icv1)*&
&                         pld0%na(nd0, icv1, is)+pl%na(icv1, is)*pldd%ti&
&                         (nd0, nd, icv1)+pld%na(nd, icv1, is)*pld0%ti(&
&                         nd0, icv1)+pl%ti(icv1)*pldd%na(nd0, nd, icv1, &
&                         is))+temp16*temp5d(nd0)+temp5*(geo%fcqalf(ifc&
&                         , 0)*dvdd%vaecrb(nd0, nd, ifc, 0, is)+geo%&
&                         fcqalf(ifc, 1)*dvdd%vaecrb(nd0, nd, ifc, 1, is&
&                         )))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(temp1*temp10+&
&                       temp5*temp16)
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(temp1*&
&                       temp5d(nd0)+temp5*temp1d(nd0))
                    END DO
                    totflux = totflux - temp2*(temp5*temp1)
                  END DO
                ELSE
                  temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(&
&                       dvdd%fhi(nd0, nd, ifc, 0)+dvdd%fhi(nd0, nd, ifc&
&                       , 1))
                    END DO
                    totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, ifc&
&                     , 0)+dvd%fhi(nd, ifc, 1))
                  END DO
                  DO nd0=1,nbdirs0
                    totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fhi(&
&                     nd0, ifc, 0)+dvd0%fhi(nd0, ifc, 1))
                  END DO
                  totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc, &
&                   1))
                END IF
              END DO
            END IF
          END DO
          DO nd=1,nbdirs
            temp16 = tis/nivs
            temp15 = (tisd(nd)-nivsd(nd)*temp16)/nivs
            DO nd0=1,nbdirs0
              tisdd(nd0, nd) = (tisdd(nd0, nd)-temp16*nivsdd(nd0, nd)-&
&               nivsd(nd)*(tisd0(nd0)-temp16*nivsd0(nd0))/nivs-temp15*&
&               nivsd0(nd0))/nivs
              t1dd(nd0, nd) = t1dd(nd0, nd)/t0
              t2dd(nd0, nd) = t2dd(nd0, nd)/t0
              t3dd(nd0, nd) = t3dd(nd0, nd)/t0
            END DO
            tisd(nd) = temp15
            t1d(nd) = t1d(nd)/t0
            t2d(nd) = t2d(nd)/t0
            t3d(nd) = t3d(nd)/t0
          END DO
          DO nd0=1,nbdirs0
            tisd0(nd0) = (tisd0(nd0)-tis*nivsd0(nd0)/nivs)/nivs
            t1d0(nd0) = t1d0(nd0)/t0
            t2d0(nd0) = t2d0(nd0)/t0
            t3d0(nd0) = t3d0(nd0)/t0
          END DO
          tis = tis/nivs
          t1 = t1/t0
          t2 = t2/t0
          t3 = t3/t0
          IF (enipar(ib, 2) .GT. 0.0_R8) THEN
            t4dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t4dd(nd0, nd) = enipardd(nd0, nd, ib, 2)
              END DO
              t4d(nd) = enipard(nd, ib, 2)
            END DO
            DO nd0=1,nbdirs0
              t4d0(nd0) = enipard0(nd0, ib, 2)
            END DO
            t4 = enipar(ib, 2)
          ELSE
            DO nd=1,nbdirsmax
              t4d(nd) = 0.d0
            END DO
            t4d0 = 0.D0
            t4dd = 0.D0
          END IF
          IF (enipar(ib, 2) .LE. 0.0_R8) THEN
            t4 = switch%b2stbc_bc_ref_ti
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                t4dd(nd0, nd) = 0.D0
              END DO
              t4d(nd) = 0.d0
            END DO
            t4d0 = 0.D0
          END IF
          IF (totflux .GE. 0.) THEN
            x4dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                x4dd(nd0, nd) = totfluxdd(nd0, nd)
              END DO
              x4d(nd) = totfluxd(nd)
            END DO
            DO nd0=1,nbdirs0
              x4d0(nd0) = totfluxd0(nd0)
            END DO
            x4 = totflux
          ELSE
            x4dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                x4dd(nd0, nd) = -totfluxdd(nd0, nd)
              END DO
              x4d(nd) = -totfluxd(nd)
            END DO
            DO nd0=1,nbdirs0
              x4d0(nd0) = -totfluxd0(nd0)
            END DO
            x4 = -totflux
          END IF
          IF (x4 .LT. senipar) THEN
            max10dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max10dd(nd0, nd) = senipardd(nd0, nd)
              END DO
              max10d(nd) = senipard(nd)
            END DO
            DO nd0=1,nbdirs0
              max10d0(nd0) = senipard0(nd0)
            END DO
            max10 = senipar
          ELSE
            max10dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max10dd(nd0, nd) = x4dd(nd0, nd)
              END DO
              max10d(nd) = x4d(nd)
            END DO
            DO nd0=1,nbdirs0
              max10d0(nd0) = x4d0(nd0)
            END DO
            max10 = x4
          END IF
          temp2 = t4/max10
          DO nd0=1,nbdirs0
            temp2d(nd0) = (t4d0(nd0)-t4*max10d0(nd0)/max10)/max10
            temp5d(nd0) = -(temp2*(totfluxd0(nd0)-senipard0(nd0))+(&
&             totflux-senipar)*temp2d(nd0))
          END DO
          temp5 = -((totflux-senipar)*temp2) + 1.0_R8
          DO nd=1,nbdirs
            temp16 = t4d(nd) - temp2*max10d(nd)
            temp15 = (totflux-senipar)/max10
            temp14 = temp2*(totfluxd(nd)-senipard(nd)) + temp15*temp16
            DO nd0=1,nbdirs0
              tisdd(nd0, nd) = tisd(nd)*temp5d(nd0) + temp5*tisdd(nd0, &
&               nd) - temp14*tisd0(nd0) - tis*((totfluxd(nd)-senipard(nd&
&               ))*temp2d(nd0)+temp2*(totfluxdd(nd0, nd)-senipardd(nd0, &
&               nd))+temp16*(totfluxd0(nd0)-senipard0(nd0)-temp15*&
&               max10d0(nd0))/max10+temp15*(t4dd(nd0, nd)-max10d(nd)*&
&               temp2d(nd0)-temp2*max10dd(nd0, nd)))
            END DO
            tisd(nd) = temp5*tisd(nd) - tis*temp14
          END DO
          DO nd0=1,nbdirs0
            tisd0(nd0) = temp5*tisd0(nd0) + tis*temp5d(nd0)
          END DO
          tis = tis*temp5
          WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&         totflux, ' SENIPAR=', senipar
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                temp2 = vbig*ne00*geo%fcs(ifc)
                temp10 = (pl%ti(icv2)-t1)*t1*t2/(t3*tis)
                DO nd0=1,nbdirs0
                  temp5d(nd0) = (t1*t2*(pld0%ti(nd0, icv2)-t1d0(nd0))+(&
&                   pl%ti(icv2)-t1)*(t2*t1d0(nd0)+t1*t2d0(nd0))-temp10*(&
&                   tis*t3d0(nd0)+t3*tisd0(nd0)))/(t3*tis)
                END DO
                temp5 = temp10
                DO nd=1,nbdirs
                  temp10 = pld%ti(nd, icv2) - t1d(nd)
                  temp16 = t2*t1d(nd) + t1*t2d(nd)
                  temp15 = tis*t3d(nd) + t3*tisd(nd)
                  temp14 = (t1*t2*temp10+(pl%ti(icv2)-t1)*temp16-temp5*&
&                   temp15)/(t3*tis)
                  DO nd0=1,nbdirs0
                    srwdd%shi0(nd0, nd, icv1, 0) = temp2*(tisdd(nd0, nd)&
&                     +(temp10*(t2*t1d0(nd0)+t1*t2d0(nd0))+t1*t2*(pldd%&
&                     ti(nd0, nd, icv2)-t1dd(nd0, nd))+temp16*(pld0%ti(&
&                     nd0, icv2)-t1d0(nd0))+(pl%ti(icv2)-t1)*(t1d(nd)*&
&                     t2d0(nd0)+t2*t1dd(nd0, nd)+t2d(nd)*t1d0(nd0)+t1*&
&                     t2dd(nd0, nd))-temp15*temp5d(nd0)-temp5*(t3d(nd)*&
&                     tisd0(nd0)+tis*t3dd(nd0, nd)+tisd(nd)*t3d0(nd0)+t3&
&                     *tisdd(nd0, nd))-temp14*(tis*t3d0(nd0)+t3*tisd0(&
&                     nd0)))/(t3*tis))
                    srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
                  END DO
                  srwd%shi0(nd, icv1, 0) = temp2*(tisd(nd)+temp14)
                  srwd%shi0(nd, icv1, 1) = 0.d0
                END DO
                DO nd0=1,nbdirs0
                  srwd0%shi0(nd0, icv1, 0) = temp2*(tisd0(nd0)+temp5d(&
&                   nd0))
                  srwd0%shi0(nd0, icv1, 1) = 0.D0
                END DO
                srw%shi0(icv1, 0) = temp2*(tis+temp5)
                srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB('B2STBC -- BCENI=24 IS AVAILABLE FOR CORE ONLY')
        END IF
      END IF
    CASE (25) 
!
! -- BCENI=25 -- constant ion temperature scaled by inner ring
! was BCENI=21 in 5.0/5.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 25 : fixed ion temperature '//&
&       '(modified by nearby ring) ', enipar(ib, 1), ' with ', enipar(ib&
&       , 2), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0.0_R8, &
&             'faulty parameter enipar1')
      END IF
      tiave = 0.0_R8
      niave = 0.0_R8
      DO nd=1,nbdirsmax
        niaved(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        tiaved(nd) = 0.d0
      END DO
      niaved0 = 0.D0
      tiaved0 = 0.D0
      niavedd = 0.D0
      tiavedd = 0.D0
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            tiavedd(nd0, nd) = tiavedd(nd0, nd) + geo%cvvol(icv)*(pld%ti&
&             (nd, icv)*dvd0%ni(nd0, icv, 0)+dv%ni(icv, 0)*pldd%ti(nd0, &
&             nd, icv)+dvd%ni(nd, icv, 0)*pld0%ti(nd0, icv)+pl%ti(icv)*&
&             dvdd%ni(nd0, nd, icv, 0))
            niavedd(nd0, nd) = niavedd(nd0, nd) + geo%cvvol(icv)*dvdd%ni&
&             (nd0, nd, icv, 0)
          END DO
          tiaved(nd) = tiaved(nd) + geo%cvvol(icv)*(dv%ni(icv, 0)*pld%ti&
&           (nd, icv)+pl%ti(icv)*dvd%ni(nd, icv, 0))
          niaved(nd) = niaved(nd) + geo%cvvol(icv)*dvd%ni(nd, icv, 0)
        END DO
        DO nd0=1,nbdirs0
          tiaved0(nd0) = tiaved0(nd0) + geo%cvvol(icv)*(dv%ni(icv, 0)*&
&           pld0%ti(nd0, icv)+pl%ti(icv)*dvd0%ni(nd0, icv, 0))
          niaved0(nd0) = niaved0(nd0) + geo%cvvol(icv)*dvd0%ni(nd0, icv&
&           , 0)
        END DO
        tiave = tiave + pl%ti(icv)*dv%ni(icv, 0)*geo%cvvol(icv)
        niave = niave + dv%ni(icv, 0)*geo%cvvol(icv)
      END DO
      DO nd=1,nbdirs
        temp16 = tiave/niave
        temp15 = (tiaved(nd)-niaved(nd)*temp16)/niave
        DO nd0=1,nbdirs0
          tiavedd(nd0, nd) = (tiavedd(nd0, nd)-temp16*niavedd(nd0, nd)-&
&           niaved(nd)*(tiaved0(nd0)-temp16*niaved0(nd0))/niave-temp15*&
&           niaved0(nd0))/niave
        END DO
        tiaved(nd) = temp15
      END DO
      DO nd0=1,nbdirs0
        tiaved0(nd0) = (tiaved0(nd0)-tiave*niaved0(nd0)/niave)/niave
      END DO
      tiave = tiave/niave
      IF (enipar(ib, 2) .GT. 0.0_R8) THEN
        t3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t3dd(nd0, nd) = enipardd(nd0, nd, ib, 2)
          END DO
          t3d(nd) = enipard(nd, ib, 2)
        END DO
        DO nd0=1,nbdirs0
          t3d0(nd0) = enipard0(nd0, ib, 2)
        END DO
        t3 = enipar(ib, 2)
      ELSE
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
        t3dd = 0.D0
      END IF
      IF (enipar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_ti
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            t3dd(nd0, nd) = 0.D0
          END DO
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = vbig*ne00*ev*geo%fcs(ifc)
        temp1 = t3/tiave
        DO nd0=1,nbdirs0
          temp1d(nd0) = (t3d0(nd0)-t3*tiaved0(nd0)/tiave)/tiave
          temp5d(nd0) = temp1*pld0%ti(nd0, icv2) + pl%ti(icv2)*temp1d(&
&           nd0) - t3d0(nd0)
        END DO
        temp5 = pl%ti(icv2)*temp1 - t3 + 1.0_R8
        DO nd=1,nbdirs
          temp16 = t3d(nd) - temp1*tiaved(nd)
          temp10 = pl%ti(icv2)/tiave
          temp15 = temp1*pld%ti(nd, icv2) + temp10*temp16 - t3d(nd)
          DO nd0=1,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 0) = temp2*(enipard(nd, ib, 1)*&
&             temp5d(nd0)+temp5*enipardd(nd0, nd, ib, 1)+temp15*enipard0&
&             (nd0, ib, 1)+enipar(ib, 1)*(pld%ti(nd, icv2)*temp1d(nd0)+&
&             temp1*pldd%ti(nd0, nd, icv2)+temp16*(pld0%ti(nd0, icv2)-&
&             temp10*tiaved0(nd0))/tiave+temp10*(t3dd(nd0, nd)-tiaved(nd&
&             )*temp1d(nd0)-temp1*tiavedd(nd0, nd))-t3dd(nd0, nd)))
            srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%shi0(nd, icv1, 0) = temp2*(temp5*enipard(nd, ib, 1)+&
&           enipar(ib, 1)*temp15)
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 0) = temp2*(temp5*enipard0(nd0, ib, 1)+&
&           enipar(ib, 1)*temp5d(nd0))
          srwd0%shi0(nd0, icv1, 1) = 0.D0
        END DO
        srw%shi0(icv1, 0) = temp2*(enipar(ib, 1)*temp5)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (26) 
!
! -- BCENI=26 -- PRESCRIBE THE POLOIDALLY AVERAGED VALUE OF THE ION TEMPERATURE
! AND INTRODUCE A POLOIDAL VARIATION IN A SIMPLIFIED MANNER.
! THIS BOUNDARY CONDITION IS SUITABLE FOR ANY PLASMA COMPOSITION (i.e. when BCENI=23 fails).
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 25,26,27
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7)') &
&       'BCENI = 26 : specified ion temperature ', enipar(ib, 1)
!         write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 26 only applicable to core boundaries !')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ibw, 1) .GT.&
&                 0.0_R8, 'BCENI = 26, ENIPAR(,1) !> 0')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ib, 1) .EQ. &
&                 enipar(ibw, 1), &
&                 'BCENI = 26, inconsistent ENIPAR(,1) values!')
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 24) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
!
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                    'Compile with -DASTRA option to couple with ASTRA!'&
&                                         )
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          t1d0 = 0.D0
          t1dd = 0.D0
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                t0 = t0 + geo%cvvol(icv)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv)*pldd%&
&                     ti(nd0, nd, icv)
                  END DO
                  t1d(nd) = t1d(nd) + geo%cvvol(icv)*pld%ti(nd, icv)
                END DO
                DO nd0=1,nbdirs0
                  t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv)*pld0%ti(nd0, &
&                   icv)
                END DO
                t1 = t1 + pl%ti(icv)*geo%cvvol(icv)
              END DO
            END IF
          END DO
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t1dd(nd0, nd) = t1dd(nd0, nd)/t0
            END DO
            t1d(nd) = t1d(nd)/t0
          END DO
          DO nd0=1,nbdirs0
            t1d0(nd0) = t1d0(nd0)/t0
          END DO
          t1 = t1/t0
          DO ibw=ib,nbc
!lk 12.12.12 }
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                IF (mpg%cvonclosedsurface(icv2)) THEN
                  temp2 = vbig*ne00*geo%fcs(ifc)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      srwdd%shi0(nd0, nd, icv1, 0) = temp2*(ev*enipardd(&
&                       nd0, nd, ibw, 1)+pldd%ti(nd0, nd, icv2)-t1dd(nd0&
&                       , nd))
                      srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
                    END DO
                    srwd%shi0(nd, icv1, 0) = temp2*(ev*enipard(nd, ibw, &
&                     1)+pld%ti(nd, icv2)-t1d(nd))
                    srwd%shi0(nd, icv1, 1) = 0.d0
                  END DO
                  DO nd0=1,nbdirs0
                    srwd0%shi0(nd0, icv1, 0) = temp2*(ev*enipard0(nd0, &
&                     ibw, 1)+pld0%ti(nd0, icv2)-t1d0(nd0))
                    srwd0%shi0(nd0, icv1, 1) = 0.D0
                  END DO
                  srw%shi0(icv1, 0) = temp2*(ev*enipar(ibw, 1)+pl%ti(&
&                   icv2)-t1)
                  srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
                END IF
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB(&
&              'B2STBC -- BCENI=26 IS AVAILABLE FOR CORE BOUNDARY ONLY.'&
&              )
        END IF
      END IF
    CASE (27) 
!
! -- BCENI=27 -- Feedback boundary condition with prescribed total ion heat flux,
!                constant poloidally averaged ion temperature and a
!                poloidal variation in a simplified manner.
! THIS BOUNDARY CONDITION IS SUITABLE FOR ANY PLASMA COMPOSITION (i.e. when BCENI=24 fails).
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 25,26,27
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENI = 27 : Given integrated ion heat flux', &
&       ' with constant Ti '
!         write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 27 only applicable to core boundaries !')
            CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                 'faulty parameter enipar1')
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 24) .OR. bceni(ibw) .EQ. 26)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
        IF (.NOT.once_bceni) THEN
          IF (switch%use_astra .NE. 0) THEN
            CALL XERRAB(&
&                 'Compile with -DASTRA option to couple with ASTRA!')
          ELSE
            senipar = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                senipardd(nd0, nd) = 0.D0
              END DO
              senipard(nd) = 0.d0
            END DO
            senipard0 = 0.D0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    senipardd(nd0, nd) = senipardd(nd0, nd) + enipardd(&
&                     nd0, nd, ibw, 1)
                  END DO
                  senipard(nd) = senipard(nd) + enipard(nd, ibw, 1)
                END DO
                DO nd0=1,nbdirs0
                  senipard0(nd0) = senipard0(nd0) + enipard0(nd0, ibw, 1&
&                   )
                END DO
                senipar = senipar + enipar(ibw, 1)
              END IF
            END DO
          END IF
          WRITE(*, *) 'BCENI=27: Summed value is ', senipar
! Poloidally density-averaged ion temperature in the boundary cell
          tis = 0.0_R8
          nivs = 0.0_R8
! Volume                                      !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! IYS 22.03.2017
          totflux = 0.0_R8
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              tisdd(nd0, nd) = 0.D0
            END DO
            tisd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              nivsdd(nd0, nd) = 0.D0
            END DO
            nivsd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            totfluxd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          tisd0 = 0.D0
          nivsd0 = 0.D0
          totfluxd0 = 0.D0
          t1d0 = 0.D0
          totfluxdd = 0.D0
          t1dd = 0.D0
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    tisdd(nd0, nd) = tisdd(nd0, nd) + geo%cvvol(icv2)*(&
&                     pld%ti(nd, icv1)*dvd0%ni(nd0, icv1, 0)+dv%ni(icv1&
&                     , 0)*pldd%ti(nd0, nd, icv1)+dvd%ni(nd, icv1, 0)*&
&                     pld0%ti(nd0, icv1)+pl%ti(icv1)*dvdd%ni(nd0, nd, &
&                     icv1, 0))
                    nivsdd(nd0, nd) = nivsdd(nd0, nd) + geo%cvvol(icv2)*&
&                     dvdd%ni(nd0, nd, icv1, 0)
                    t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd&
&                     %ti(nd0, nd, icv2)
                  END DO
                  tisd(nd) = tisd(nd) + geo%cvvol(icv2)*(dv%ni(icv1, 0)*&
&                   pld%ti(nd, icv1)+pl%ti(icv1)*dvd%ni(nd, icv1, 0))
                  nivsd(nd) = nivsd(nd) + geo%cvvol(icv2)*dvd%ni(nd, &
&                   icv1, 0)
                  t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)
                END DO
                DO nd0=1,nbdirs0
                  tisd0(nd0) = tisd0(nd0) + geo%cvvol(icv2)*(dv%ni(icv1&
&                   , 0)*pld0%ti(nd0, icv1)+pl%ti(icv1)*dvd0%ni(nd0, &
&                   icv1, 0))
                  nivsd0(nd0) = nivsd0(nd0) + geo%cvvol(icv2)*dvd0%ni(&
&                   nd0, icv1, 0)
                  t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%ti(nd0, &
&                   icv2)
                END DO
                tis = tis + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv2)
                nivs = nivs + dv%ni(icv1, 0)*geo%cvvol(icv2)
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                IF (switch%mdf_fhi .NE. 0) THEN
                  temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(&
&                       dvdd%fhi_mdf(nd0, nd, ifc, 0)+dvdd%fhi_mdf(nd0, &
&                       nd, ifc, 1))
                    END DO
                    totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi_mdf(nd&
&                     , ifc, 0)+dvd%fhi_mdf(nd, ifc, 1))
                  END DO
                  DO nd0=1,nbdirs0
                    totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%&
&                     fhi_mdf(nd0, ifc, 0)+dvd0%fhi_mdf(nd0, ifc, 1))
                  END DO
                  totflux = totflux - temp2*(dv%fhi_mdf(ifc, 0)+dv%&
&                   fhi_mdf(ifc, 1))
                  DO is=0,ns-1
                    temp2 = geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)
                    DO nd0=1,nbdirs0
                      temp1d(nd0) = geo%fcqalf(ifc, 0)*dvd0%vaecrb(nd0, &
&                       ifc, 0, is) + geo%fcqalf(ifc, 1)*dvd0%vaecrb(nd0&
&                       , ifc, 1, is)
                      temp5d(nd0) = pl%na(icv1, is)*pld0%ti(nd0, icv1) +&
&                       pl%ti(icv1)*pld0%na(nd0, icv1, is)
                    END DO
                    temp1 = geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is) + &
&                     geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is)
                    temp5 = pl%ti(icv1)*pl%na(icv1, is)
                    DO nd=1,nbdirs
                      temp10 = pl%na(icv1, is)*pld%ti(nd, icv1) + pl%ti(&
&                       icv1)*pld%na(nd, icv1, is)
                      temp16 = geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, ifc, 0&
&                       , is) + geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc, 1&
&                       , is)
                      DO nd0=1,nbdirs0
                        totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*&
&                         (temp10*temp1d(nd0)+temp1*(pld%ti(nd, icv1)*&
&                         pld0%na(nd0, icv1, is)+pl%na(icv1, is)*pldd%ti&
&                         (nd0, nd, icv1)+pld%na(nd, icv1, is)*pld0%ti(&
&                         nd0, icv1)+pl%ti(icv1)*pldd%na(nd0, nd, icv1, &
&                         is))+temp16*temp5d(nd0)+temp5*(geo%fcqalf(ifc&
&                         , 0)*dvdd%vaecrb(nd0, nd, ifc, 0, is)+geo%&
&                         fcqalf(ifc, 1)*dvdd%vaecrb(nd0, nd, ifc, 1, is&
&                         )))
                      END DO
                      totfluxd(nd) = totfluxd(nd) - temp2*(temp1*temp10+&
&                       temp5*temp16)
                    END DO
                    DO nd0=1,nbdirs0
                      totfluxd0(nd0) = totfluxd0(nd0) - temp2*(temp1*&
&                       temp5d(nd0)+temp5*temp1d(nd0))
                    END DO
                    totflux = totflux - temp2*(temp5*temp1)
                  END DO
                ELSE
                  temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                  DO nd=1,nbdirs
                    DO nd0=nd,nbdirs0
                      totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(&
&                       dvdd%fhi(nd0, nd, ifc, 0)+dvdd%fhi(nd0, nd, ifc&
&                       , 1))
                    END DO
                    totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, ifc&
&                     , 0)+dvd%fhi(nd, ifc, 1))
                  END DO
                  DO nd0=1,nbdirs0
                    totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fhi(&
&                     nd0, ifc, 0)+dvd0%fhi(nd0, ifc, 1))
                  END DO
                  totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc, &
&                   1))
                END IF
              END DO
            END IF
          END DO
          DO nd=1,nbdirs
            temp16 = tis/nivs
            temp15 = (tisd(nd)-nivsd(nd)*temp16)/nivs
            DO nd0=1,nbdirs0
              tisdd(nd0, nd) = (tisdd(nd0, nd)-temp16*nivsdd(nd0, nd)-&
&               nivsd(nd)*(tisd0(nd0)-temp16*nivsd0(nd0))/nivs-temp15*&
&               nivsd0(nd0))/nivs
              t1dd(nd0, nd) = t1dd(nd0, nd)/t0
            END DO
            tisd(nd) = temp15
            t1d(nd) = t1d(nd)/t0
          END DO
          DO nd0=1,nbdirs0
            tisd0(nd0) = (tisd0(nd0)-tis*nivsd0(nd0)/nivs)/nivs
            t1d0(nd0) = t1d0(nd0)/t0
          END DO
          tis = tis/nivs
          t1 = t1/t0
          IF (enipar(ib, 2) .GT. 0.0_R8) THEN
            t3dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t3dd(nd0, nd) = enipardd(nd0, nd, ib, 2)
              END DO
              t3d(nd) = enipard(nd, ib, 2)
            END DO
            DO nd0=1,nbdirs0
              t3d0(nd0) = enipard0(nd0, ib, 2)
            END DO
            t3 = enipar(ib, 2)
          ELSE
            DO nd=1,nbdirsmax
              t3d(nd) = 0.d0
            END DO
            t3d0 = 0.D0
            t3dd = 0.D0
          END IF
          IF (enipar(ib, 2) .LE. 0.0_R8) THEN
            t3 = switch%b2stbc_bc_ref_ti
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                t3dd(nd0, nd) = 0.D0
              END DO
              t3d(nd) = 0.d0
            END DO
            t3d0 = 0.D0
          END IF
          IF (totflux .GE. 0.) THEN
            x5dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                x5dd(nd0, nd) = totfluxdd(nd0, nd)
              END DO
              x5d(nd) = totfluxd(nd)
            END DO
            DO nd0=1,nbdirs0
              x5d0(nd0) = totfluxd0(nd0)
            END DO
            x5 = totflux
          ELSE
            x5dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                x5dd(nd0, nd) = -totfluxdd(nd0, nd)
              END DO
              x5d(nd) = -totfluxd(nd)
            END DO
            DO nd0=1,nbdirs0
              x5d0(nd0) = -totfluxd0(nd0)
            END DO
            x5 = -totflux
          END IF
          IF (x5 .LT. senipar) THEN
            max11dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max11dd(nd0, nd) = senipardd(nd0, nd)
              END DO
              max11d(nd) = senipard(nd)
            END DO
            DO nd0=1,nbdirs0
              max11d0(nd0) = senipard0(nd0)
            END DO
            max11 = senipar
          ELSE
            max11dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max11dd(nd0, nd) = x5dd(nd0, nd)
              END DO
              max11d(nd) = x5d(nd)
            END DO
            DO nd0=1,nbdirs0
              max11d0(nd0) = x5d0(nd0)
            END DO
            max11 = x5
          END IF
          temp2 = t3/max11
          DO nd0=1,nbdirs0
            temp2d(nd0) = (t3d0(nd0)-t3*max11d0(nd0)/max11)/max11
            temp5d(nd0) = -(temp2*(totfluxd0(nd0)-senipard0(nd0))+(&
&             totflux-senipar)*temp2d(nd0))
          END DO
          temp5 = -((totflux-senipar)*temp2) + 1.0_R8
          DO nd=1,nbdirs
            temp16 = t3d(nd) - temp2*max11d(nd)
            temp15 = (totflux-senipar)/max11
            temp14 = temp2*(totfluxd(nd)-senipard(nd)) + temp15*temp16
            DO nd0=1,nbdirs0
              tisdd(nd0, nd) = tisd(nd)*temp5d(nd0) + temp5*tisdd(nd0, &
&               nd) - temp14*tisd0(nd0) - tis*((totfluxd(nd)-senipard(nd&
&               ))*temp2d(nd0)+temp2*(totfluxdd(nd0, nd)-senipardd(nd0, &
&               nd))+temp16*(totfluxd0(nd0)-senipard0(nd0)-temp15*&
&               max11d0(nd0))/max11+temp15*(t3dd(nd0, nd)-max11d(nd)*&
&               temp2d(nd0)-temp2*max11dd(nd0, nd)))
            END DO
            tisd(nd) = temp5*tisd(nd) - tis*temp14
          END DO
          DO nd0=1,nbdirs0
            tisd0(nd0) = temp5*tisd0(nd0) + tis*temp5d(nd0)
          END DO
          tis = tis*temp5
          WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&         totflux, ' SENIPAR=', senipar
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                temp2 = vbig*ne00*geo%fcs(ifc)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    srwdd%shi0(nd0, nd, icv1, 0) = temp2*(tisdd(nd0, nd)&
&                     +pldd%ti(nd0, nd, icv2)-t1dd(nd0, nd))
                    srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
                  END DO
                  srwd%shi0(nd, icv1, 0) = temp2*(tisd(nd)+pld%ti(nd, &
&                   icv2)-t1d(nd))
                  srwd%shi0(nd, icv1, 1) = 0.d0
                END DO
                DO nd0=1,nbdirs0
                  srwd0%shi0(nd0, icv1, 0) = temp2*(tisd0(nd0)+pld0%ti(&
&                   nd0, icv2)-t1d0(nd0))
                  srwd0%shi0(nd0, icv1, 1) = 0.D0
                END DO
                srw%shi0(icv1, 0) = temp2*(tis+pl%ti(icv2)-t1)
                srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bceni = .true.
        END IF
      ELSE
        CALL XERRAB('B2STBC -- BCENI=27 IS AVAILABLE FOR CORE ONLY')
      END IF
    CASE (28) 
!
! -- BCENI=28 -- Prescribe the value of the ion temperature, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENI=28 intended for core boundaries only!')
        END DO
        IF (switch%use_astra .NE. 0) THEN
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              enipardd(nd0, nd, ib, 1) = 0.D0
            END DO
            enipard(nd, ib, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            enipard0(nd0, ib, 1) = 0.D0
          END DO
          enipar(ib, 1) = teb_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified ion temperature + perturbation', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 28, ENIPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      t1d0 = 0.D0
      t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%ti(&
&                 nd0, nd, icv2)
              END DO
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%ti(nd0, icv2)
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%ti(icv2)
          END DO
        END IF
      END DO
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          t1dd(nd0, nd) = t1dd(nd0, nd)/t0
        END DO
        t1d(nd) = t1d(nd)/t0
      END DO
      DO nd0=1,nbdirs0
        t1d0(nd0) = t1d0(nd0)/t0
      END DO
      t1 = t1/t0
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 0) = temp2*(pldd%ti(nd0, nd, icv2)&
&             +ev*enipardd(nd0, nd, ib, 1)-t1dd(nd0, nd))
            srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%shi0(nd, icv1, 0) = temp2*(pld%ti(nd, icv2)+ev*enipard(nd&
&           , ib, 1)-t1d(nd))
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 0) = temp2*(pld0%ti(nd0, icv2)+ev*&
&           enipard0(nd0, ib, 1)-t1d0(nd0))
          srwd0%shi0(nd0, icv1, 1) = 0.D0
        END DO
        srw%shi0(icv1, 0) = temp2*(pl%ti(icv2)+ev*enipar(ib, 1)-t1)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (29) 
!
! -- BCENI=29 -- Feedback on the total ion energy flux, by imposing a flux surface
!                averaged temperature, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENI=29 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified ion heat flux', enipar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 29, ENIPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t2d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        totpard(nd) = 0.d0
      END DO
      totfluxd0 = 0.D0
      t2dd = 0.D0
      totpardd = 0.D0
      t1d0 = 0.D0
      t2d0 = 0.D0
      totpard0 = 0.D0
      totfluxdd = 0.D0
      t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bceni(ib0) .NE. 29) CALL XERRAB(&
&                                      'BCENI=29: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%ti(&
&                 nd0, nd, icv1)
                t2dd(nd0, nd) = t2dd(nd0, nd) + geo%cvvol(icv2)*pldd%ti(&
&                 nd0, nd, icv2)
                totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%&
&                 fhi(nd0, nd, ifc, 0)+dvdd%fhi(nd0, nd, ifc, 1))
              END DO
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv1)
              t2d(nd) = t2d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, ifc, 0)+&
&               dvd%fhi(nd, ifc, 1))
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%ti(nd0, icv1)
              t2d0(nd0) = t2d0(nd0) + geo%cvvol(icv2)*pld0%ti(nd0, icv2)
              totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fhi(nd0, ifc&
&               , 0)+dvd0%fhi(nd0, ifc, 1))
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%ti(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%ti(icv2)
            totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
          END DO
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              totpardd(nd0, nd) = totpardd(nd0, nd) + enipardd(nd0, nd, &
&               ib0, 1)
            END DO
            totpard(nd) = totpard(nd) + enipard(nd, ib0, 1)
          END DO
          DO nd0=1,nbdirs0
            totpard0(nd0) = totpard0(nd0) + enipard0(nd0, ib0, 1)
          END DO
          totpar = totpar + enipar(ib0, 1)
        END IF
      END DO
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          totpardd(nd0, nd) = fac_he_anom_bc*totpardd(nd0, nd)
          t1dd(nd0, nd) = t1dd(nd0, nd)/t0
          t2dd(nd0, nd) = t2dd(nd0, nd)/t0
        END DO
        totpard(nd) = fac_he_anom_bc*totpard(nd)
        t1d(nd) = t1d(nd)/t0
        t2d(nd) = t2d(nd)/t0
      END DO
      DO nd0=1,nbdirs0
        totpard0(nd0) = fac_he_anom_bc*totpard0(nd0)
        t1d0(nd0) = t1d0(nd0)/t0
        t2d0(nd0) = t2d0(nd0)/t0
      END DO
      totpar = fac_he_anom_bc*totpar
      t1 = t1/t0
      t2 = t2/t0
      IF (enipar(ib, 2) .GT. 0.0_R8) THEN
        t3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t3dd(nd0, nd) = enipardd(nd0, nd, ib, 2)
          END DO
          t3d(nd) = enipard(nd, ib, 2)
        END DO
        DO nd0=1,nbdirs0
          t3d0(nd0) = enipard0(nd0, ib, 2)
        END DO
        t3 = enipar(ib, 2)
      ELSE
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
        t3dd = 0.D0
      END IF
      IF (enipar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_ti
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            t3dd(nd0, nd) = 0.D0
          END DO
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
      END IF
      IF (totflux .GE. 0.) THEN
        x6dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x6dd(nd0, nd) = totfluxdd(nd0, nd)
          END DO
          x6d(nd) = totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x6d0(nd0) = totfluxd0(nd0)
        END DO
        x6 = totflux
      ELSE
        x6dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x6dd(nd0, nd) = -totfluxdd(nd0, nd)
          END DO
          x6d(nd) = -totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x6d0(nd0) = -totfluxd0(nd0)
        END DO
        x6 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y3dd(nd0, nd) = totpardd(nd0, nd)
          END DO
          y3d(nd) = totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          y3d0(nd0) = totpard0(nd0)
        END DO
        y3 = totpar
      ELSE
        y3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y3dd(nd0, nd) = -totpardd(nd0, nd)
          END DO
          y3d(nd) = -totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          y3d0(nd0) = -totpard0(nd0)
        END DO
        y3 = -totpar
      END IF
      IF (x6 .LT. y3) THEN
        max12dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            max12dd(nd0, nd) = y3dd(nd0, nd)
          END DO
          max12d(nd) = y3d(nd)
        END DO
        DO nd0=1,nbdirs0
          max12d0(nd0) = y3d0(nd0)
        END DO
        max12 = y3
      ELSE
        max12dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            max12dd(nd0, nd) = x6dd(nd0, nd)
          END DO
          max12d(nd) = x6d(nd)
        END DO
        DO nd0=1,nbdirs0
          max12d0(nd0) = x6d0(nd0)
        END DO
        max12 = x6
      END IF
      temp2 = t3/max12
      DO nd0=1,nbdirs0
        temp2d(nd0) = (t3d0(nd0)-t3*max12d0(nd0)/max12)/max12
        temp5d(nd0) = -(temp2*(totfluxd0(nd0)-totpard0(nd0))+(totflux-&
&         totpar)*temp2d(nd0))
      END DO
      temp5 = -((totflux-totpar)*temp2) + 1.0_R8
      t4dd = 0.D0
      DO nd=1,nbdirs
        temp16 = t3d(nd) - temp2*max12d(nd)
        temp15 = (totflux-totpar)/max12
        temp14 = temp2*(totfluxd(nd)-totpard(nd)) + temp15*temp16
        DO nd0=1,nbdirs0
          t4dd(nd0, nd) = t1d(nd)*temp5d(nd0) + temp5*t1dd(nd0, nd) - &
&           temp14*t1d0(nd0) - t1*((totfluxd(nd)-totpard(nd))*temp2d(nd0&
&           )+temp2*(totfluxdd(nd0, nd)-totpardd(nd0, nd))+temp16*(&
&           totfluxd0(nd0)-totpard0(nd0)-temp15*max12d0(nd0))/max12+&
&           temp15*(t3dd(nd0, nd)-max12d(nd)*temp2d(nd0)-temp2*max12dd(&
&           nd0, nd)))
        END DO
        t4d(nd) = temp5*t1d(nd) - t1*temp14
      END DO
      DO nd0=1,nbdirs0
        t4d0(nd0) = t1*temp5d(nd0) + temp5*t1d0(nd0)
      END DO
      t4 = temp5*t1
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%shi0(nd0, nd, icv1, 0) = temp2*(pldd%ti(nd0, nd, icv2)&
&             +t4dd(nd0, nd)-t2dd(nd0, nd))
            srwdd%shi0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%shi0(nd, icv1, 0) = temp2*(pld%ti(nd, icv2)+t4d(nd)-t2d(&
&           nd))
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%shi0(nd0, icv1, 0) = temp2*(pld0%ti(nd0, icv2)+t4d0(nd0)&
&           -t2d0(nd0))
          srwd0%shi0(nd0, icv1, 1) = 0.D0
        END DO
        srw%shi0(icv1, 0) = temp2*(pl%ti(icv2)+t4-t2)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bceni(ib)
      CALL XERRAB('BCENI out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENI_DV_DV

!  Differentiation of b2stbc_phys_eni in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: enipar senipar *(srw.shi0)
!                vbc csbc
!   with respect to varying inputs: conpar mompar enipar senipar
!                *(dv.fna) *(dv.fhi) *(dv.fhi_mdf) *(dv.fhipsch)
!                *(dv.fhm) *(dv.ne) *(dv.ni) *(dv.vadia) *(dv.vaecrb)
!                *(rt.rza) *(srw.shi0) *(srw.sna0) *(co.chci) *(co.hci0)
!                *(co.hcn0) *(co.dna0) *(pl.na) *(pl.ua) *(pl.te)
!                *(pl.ti) vbc rz csbc pz
!   Plus diff mem management of: dv.fna:in dv.fhi:in dv.fhi_mdf:in
!                dv.fhipsch:in dv.fhm:in dv.ne:in dv.ni:in dv.vadia:in
!                dv.vaecrb:in mpg.bcfcor:in geo.fcs:in geo.vxvol:in
!                rt.rza:in srw.shi0:in srw.sna0:in co.chci:in co.hci0:in
!                co.hcn0:in co.dna0:in pl.na:in pl.ua:in pl.te:in
!                pl.ti:in
!
  SUBROUTINE B2STBC_PHYS_ENI_DV(ib, nbdirs)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: ib, ibw, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: t0, t1, t2, t3, t4, dsh, vt, vbnd, niave, tiave, &
&   totpar, totflux, weight, cs, csb, wrk
    REAL(kind=r8), DIMENSION(nbdirsmax) :: t0d, t1d, t2d, t3d, t4d, dshd&
&   , vtd, vbndd, niaved, tiaved, totpard, totfluxd, weightd, csd, csbd
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    LOGICAL :: decay_length_ok
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC NINT
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8) :: y1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y1d
    REAL(kind=r8) :: x2
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x2d
    REAL(kind=r8) :: y2
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y2d
    REAL(kind=r8) :: x3
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x3d
    REAL(kind=r8) :: x4
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x4d
    REAL(kind=r8) :: x5
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x5d
    REAL(kind=r8) :: x6
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x6d
    REAL(kind=r8) :: y3
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y3d
    REAL(r8) :: max1
    REAL(r8), DIMENSION(nbdirsmax) :: max1d
    REAL(r8) :: min1
    REAL(r8), DIMENSION(nbdirsmax) :: min1d
    REAL(r8) :: max2
    REAL(r8), DIMENSION(nbdirsmax) :: max2d
    REAL(r8) :: min2
    REAL(r8), DIMENSION(nbdirsmax) :: min2d
    REAL(r8) :: max3
    REAL(r8), DIMENSION(nbdirsmax) :: max3d
    REAL(r8) :: max4
    REAL(r8), DIMENSION(nbdirsmax) :: max4d
    REAL(r8) :: min3
    REAL(r8), DIMENSION(nbdirsmax) :: min3d
    REAL(kind=r8) :: abs0
    REAL(r8) :: max5
    REAL(r8), DIMENSION(nbdirsmax) :: max5d
    REAL(r8) :: min4
    REAL(r8), DIMENSION(nbdirsmax) :: min4d
    REAL(kind=r8) :: max6
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max6d
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: abs4
    REAL(r8) :: max7
    REAL(r8), DIMENSION(nbdirsmax) :: max7d
    REAL(r8) :: min5
    REAL(r8), DIMENSION(nbdirsmax) :: min5d
    REAL(kind=r8) :: max8
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max8d
    REAL(kind=r8) :: max9
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max9d
    REAL(kind=r8) :: max10
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max10d
    REAL(kind=r8) :: max11
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max11d
    REAL(kind=r8) :: max12
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max12d
    REAL(kind=r8) :: abs5
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(r8) :: arg13
    REAL(r8), DIMENSION(nbdirsmax) :: arg13d
    REAL(kind=r8) :: result10
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result10d
    REAL(kind=r8) :: result20
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result20d
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(kind=r8) :: temp2
    REAL(r8) :: temp3
    REAL(r8) :: temp4
    REAL(r8) :: temp5
    REAL(kind=r8) :: temp6
    INTEGER :: nbdirs
!
! -- BOUNDARY CONDITIONS FOR ION ENERGY EQUATIONS --
!
    SELECT CASE  (bceni(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCENI=1 -- PRESCRIBE THE VALUE OF THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (bcchar(ib) .EQ. 'S' .AND. switch%use_astra .NE. 0) THEN
!srv 14.06.12
          DO nd=1,nbdirs
            enipard(nd, ib, 1) = 0.d0
          END DO
          enipar(ib, 1) = tib_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  1 : specified ion temperature ', enipar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 1, ENIPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp = geo%fcs(ifc)*ev
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 0) = temp*vbig*ne00*enipard(nd, ib, 1)
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        srw%shi0(icv1, 0) = vbig*ne00*enipar(ib, 1)*temp
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENI=2 -- PRESCRIBE THE GRADIENT OF THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI =  2 : ion temperature gradient '&
&                                   , enipar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        CALL INTVERTEX_S_DV_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ti&
&                            , pld%ti, t1, t1d, nbdirs)
        CALL INTVERTEX_S_DV_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ti&
&                            , pld%ti, t2, t2d, nbdirs)
        temp = vbig*ne00*geo%fcs(ifc)
        temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
        temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, &
&         2))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 0) = temp*(temp0*geo%fcqgam(ifc, 0)*ev*&
&           enipard(nd, ib, 1)-temp1*temp2*(t2d(nd)-t1d(nd))/geo%fcht(&
&           ifc)+pld%ti(nd, icv2))
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        srw%shi0(icv1, 0) = temp*(temp0*(geo%fcqgam(ifc, 0)*(ev*enipar(&
&         ib, 1)))-temp1*(temp2*((t2-t1)/geo%fcht(ifc)))+pl%ti(icv2))
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENI=3 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
      CALL XERRAB('b2stbc_phys -- BCENI = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCENI = 15')
!
! -- BCENI=4 -- PRESCRIBE THE VALUE OF THE ION TEMPERATURE, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  4 : weak ion temperature ', enipar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 4, ENIPAR(,1) !> 0')
!srv 02.02.11
        CALL XERTST(enipar(ib, 2) .GT. 0.0_R8, &
&             'BCENI = 4, ENIPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 0) = geo%fcs(ifc)*(enipar(ib, 1)*enipard(&
&           nd, ib, 2)+enipar(ib, 2)*enipard(nd, ib, 1))
          srwd%shi0(nd, icv1, 1) = -(geo%fcs(ifc)*enipard(nd, ib, 2)/ev)
        END DO
        srw%shi0(icv1, 0) = enipar(ib, 2)*geo%fcs(ifc)*enipar(ib, 1)
        srw%shi0(icv1, 1) = -(enipar(ib, 2)/ev*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCENI=5 -- PRESCRIBE THE ION ENERGY FLUX PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI =  5 : ion energy flux per area '&
&                                   , enipar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          srwd%shi0(nd, icv, 0) = geo%fcs(ifc)*enipard(nd, ib, 1)
          srwd%shi0(nd, icv, 1) = 0.d0
        END DO
        srw%shi0(icv, 0) = enipar(ib, 1)*geo%fcs(ifc)
        srw%shi0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCENI=6 -- PRESCRIBE THE TOTAL ION ENERGY FLUX FOR A
!                 CONSTANT ION TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENI = 6 not adapted for WG')
!
! -- BCENI=7 -- PRESCRIBE THE ION TEMPERATURE PROFILE
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') 'BCENI = 7 : specified ion temperature on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 0) = 0.d0
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*bv_ti(icv1)*ev
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCENI=8 -- PRESCRIBE THE TOTAL ION HEAT FLUX WITH CONSTANT
!                 FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 28.07.11
        IF (switch%use_astra .NE. 0) THEN
          DO nd=1,nbdirs
            enipard(nd, ib, 1) = 0.d0
          END DO
          enipar(ib, 1) = fhib_astra
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  8 : total ion energy flux', enipar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = fac_he_anom_bc*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 0) = temp2*enipard(nd, ib, 1)/us
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        srw%shi0(icv1, 0) = temp2*(enipar(ib, 1)/us)
        srw%shi0(icv1, 1) = 0.0_R8
        IF (switch%mdf_fhi .NE. 0) THEN
!wdk Correction now involves vedia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_fhi = 0 option
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*(dvd&
&             %fhipsch(nd, ifc, 0)+dvd%fhipsch(nd, ifc, 1))
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(dv%fhipsch(ifc&
&           , 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO nd=1,nbdirsmax
            t0d(nd) = 0.d0
          END DO
          DO is=0,ns-1
            temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp3 = pl%ti(icv1) + pl%ti(icv2)
            temp4 = pl%na(icv1, is) + pl%na(icv2, is)
            temp5 = temp4*temp3
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1, &
&             is)
            DO nd=1,nbdirs
              t0d(nd) = t0d(nd) + temp2*(temp5*(temp1*dvd%vadia(nd, ifc&
&               , 0, is)+temp0*dvd%vadia(nd, ifc, 1, is))+temp*(temp3*(&
&               pld%na(nd, icv1, is)+pld%na(nd, icv2, is))+temp4*(pld%ti&
&               (nd, icv1)+pld%ti(nd, icv2))))
            END DO
            t0 = t0 + temp2*(temp*temp5)
          END DO
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              max1d(nd) = t0d(nd)
            END DO
            max1 = t0
          ELSE
            max1 = 0.0_R8
            DO nd=1,nbdirsmax
              max1d(nd) = 0.d0
            END DO
          END IF
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + max1d(nd)
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max1
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              min1d(nd) = t0d(nd)
            END DO
            min1 = t0
          ELSE
            min1 = 0.0_R8
            DO nd=1,nbdirsmax
              min1d(nd) = 0.d0
            END DO
          END IF
          temp5 = min1/pl%ti(icv1)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + (min1d(nd)&
&             -temp5*pld%ti(nd, icv1))/pl%ti(icv1)
          END DO
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + temp5
        END IF
      END DO
    CASE (9) 
!
! -- BCENI=9 -- PRESCRIBE THE DECAY LENGTH FOR THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  9 : ion temperature decay length ', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0.0_R8, &
&             'BCENI = 9, ENIPAR(,1) = 0')
        decay_length_ok = .true.
        DO is=0,ns-1
          decay_length_ok = decay_length_ok .AND. ((bccon(is, ib) .EQ. 9&
&           .OR. bccon(is, ib) .EQ. 0) .OR. (is_neutral(is) .AND. switch&
&           %use_eirene .EQ. 1))
          IF (bccon(is, ib) .EQ. 1) WRITE(0, *) &
&                      'Should use BCENI=19 in conjunction with BCCON=1'
        END DO
        IF (.NOT.decay_length_ok) THEN
          WRITE(0, *) 'Should use BCENI.EQ.9 together with BCCON=9'
          WRITE(*, *) 'Should use BCENI.EQ.9 together with BCCON=9'
!srv 21.09.12
          WRITE(*, '(1x,a)') &
&         'Please ensure that this boundary condition '//&
&         'is consistent with '//'the density boundary condition'
        END IF
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        sy = geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 0) = 0.d0
        END DO
        srw%shi0(icv1, 0) = 0.0_R8
        IF (switch%recycle_afn .EQ. 0 .OR. switch%tn_style .NE. 0) THEN
!! Note that
!! if tn_style=0: hci0 includes contributions from all ions and all fluid neutrals
!! if tn_style=1: hci0 includes contributions from ions only
!! if tn_style=2: hci0 includes contributions from all ions and non-hydrogenic neutrals
          temp5 = co%hci0(icv1)/enipar(ib, 1)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 1) = -(sy*(cod%hci0(nd, icv1)-temp5*&
&             enipard(nd, ib, 1))/enipar(ib, 1))
          END DO
          srw%shi0(icv1, 1) = -(sy*temp5)
        ELSE
!! tn_style=0.and.recycle_afn=1 => take out hydrogenic atoms
          temp5 = (co%hci0(icv1)-co%hcn0(icv1))/enipar(ib, 1)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 1) = -(sy*(cod%hci0(nd, icv1)-cod%hcn0(&
&             nd, icv1)-temp5*enipard(nd, ib, 1))/enipar(ib, 1))
          END DO
          srw%shi0(icv1, 1) = -(sy*temp5)
        END IF
        DO is=0,ns-1
          IF (((.NOT.is_neutral(is)) .OR. switch%tn_style .EQ. 0) .OR. (&
&             switch%tn_style .EQ. 2 .AND. NINT(zn(is)) .NE. 1)) THEN
            DO nd=1,nbdirs
              srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + &
&               fac_he_anom*(srw%sna0(icv1, 0, is)*pld%ti(nd, icv1)+pl%&
&               ti(icv1)*srwd%sna0(nd, icv1, 0, is))
              srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + &
&               fac_he_anom*(srw%sna0(icv1, 1, is)*pld%na(nd, icv1, is)+&
&               pl%na(icv1, is)*srwd%sna0(nd, icv1, 1, is))
            END DO
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + fac_he_anom*pl%ti(&
&             icv1)*srw%sna0(icv1, 0, is)
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + fac_he_anom*pl%na(&
&             icv1, is)*srw%sna0(icv1, 1, is)
          END IF
!! end species loop

        END DO
        IF (switch%mdf_fhi .NE. 0) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*(dvd&
&             %fhipsch(nd, ifc, 0)+dvd%fhipsch(nd, ifc, 1))
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(dv%fhipsch(ifc&
&           , 0)+dv%fhipsch(ifc, 1))
          DO is=0,ns-1
            temp2 = 1.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp5 = pl%ti(icv1) + pl%ti(icv2)
            temp4 = pl%na(icv1, is) + pl%na(icv2, is)
            temp3 = temp4*temp5
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*dv%vaecrb(ifc, 0, is) + temp0*dv%vaecrb(ifc, 1&
&             , is)
            DO nd=1,nbdirs
              t0d(nd) = -(temp2*(temp3*(temp1*dvd%vaecrb(nd, ifc, 0, is)&
&               +temp0*dvd%vaecrb(nd, ifc, 1, is))+temp*(temp5*(pld%na(&
&               nd, icv1, is)+pld%na(nd, icv2, is))+temp4*(pld%ti(nd, &
&               icv1)+pld%ti(nd, icv2)))))
            END DO
            t0 = -(temp2*(temp*temp3))
            IF (0.0_R8 .LT. t0) THEN
              DO nd=1,nbdirs
                max2d(nd) = t0d(nd)
              END DO
              max2 = t0
            ELSE
              max2 = 0.0_R8
              DO nd=1,nbdirsmax
                max2d(nd) = 0.d0
              END DO
            END IF
            DO nd=1,nbdirs
              srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + max2d(nd&
&               )
            END DO
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max2
            IF (0.0_R8 .GT. t0) THEN
              DO nd=1,nbdirs
                min2d(nd) = t0d(nd)
              END DO
              min2 = t0
            ELSE
              min2 = 0.0_R8
              DO nd=1,nbdirsmax
                min2d(nd) = 0.d0
              END DO
            END IF
            temp5 = min2/pl%ti(icv1)
            DO nd=1,nbdirs
              srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + (min2d(&
&               nd)-temp5*pld%ti(nd, icv1))/pl%ti(icv1)
            END DO
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + temp5
          END DO
        END IF
!! end boundary cell loop

      END DO
    CASE (10) 
!
! -- BCENI=10 -- Feedback option for core
!
      CALL XERRAB('b2stbc_phys -- BCENI = 10 not adapted for WG')
!
! -- BCENI=11 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
    CASE (11) 
      CALL XERRAB('b2stbc_phys -- BCENI = 11 not adapted for WG')
!
! -- BCENI=12 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
    CASE (12) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a)') 'BCENI = 12 : sheath ion bc on ', bcchar(ib)&
&       , boundary_location(ib)
        WRITE(*, '(a)') &
&       'Obsolete. Use drift-compatible BCENI = 15 instead'
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO is=0,ns-1
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fna(ifc&
&             , 0, is)+dv%fna(ifc, 1, is))) THEN
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              max3d(nd) = temp2*(dvd%fna(nd, ifc, 0, is)+dvd%fna(nd, ifc&
&               , 1, is))
            END DO
            max3 = temp2*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
          ELSE
            max3 = 0.0_R8
            DO nd=1,nbdirsmax
              max3d(nd) = 0.d0
            END DO
          END IF
          temp2 = enipar(ib, 1)*max3/dv%ni(icv, 0)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv, 3) = srwd%shi0(nd, icv, 3) - (max3*&
&             enipard(nd, ib, 1)+enipar(ib, 1)*max3d(nd)-temp2*dvd%ni(nd&
&             , icv, 0))/dv%ni(icv, 0)
          END DO
          srw%shi0(icv, 3) = srw%shi0(icv, 3) - temp2
        END DO
      END DO
    CASE (13) 
!
! -- BCENI=13 -- PRESCRIBE THE ION ENERGY FLUX PER UNIT AREA
!             -- PROPORTIONAL TO TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI = 13 : ion energy flux per area '&
&                                   //'proportional to temperature ', &
&                                   enipar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          srwd%shi0(nd, icv, 0) = geo%fcs(ifc)*(pl%ti(icv)*enipard(nd, &
&           ib, 1)+enipar(ib, 1)*pld%ti(nd, icv))
          srwd%shi0(nd, icv, 1) = 0.d0
        END DO
        srw%shi0(icv, 0) = enipar(ib, 1)*pl%ti(icv)*geo%fcs(ifc)
        srw%shi0(icv, 1) = 0.0_R8
      END DO
    CASE (14) 
!
! -- BCENI=14 -- leakage option for ion energy
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCENI = 14 : ion energy leakage ', &
&                                   enipar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = pz(icv1)/rz(icv1)
        DO nd=1,nbdirs
          arg12d(nd) = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
          srwd%shi0(nd, icv1, 0) = 0.d0
        END DO
        arg12 = temp2
        temp2 = SQRT(arg12)
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            csd(nd) = 0.d0
          ELSE
            csd(nd) = arg12d(nd)/(2.0*temp2)
          END IF
        END DO
        cs = temp2
        srw%shi0(icv1, 0) = 0.0_R8
        temp2 = geo%fcs(ifc)*fac_he_anom_bc
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 3) = temp2*(enipar(ib, 1)*csd(nd)+cs*&
&           enipard(nd, ib, 1))
        END DO
        srw%shi0(icv1, 3) = temp2*(cs*enipar(ib, 1))
        IF (switch%mdf_fhi .NE. 0) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*(dvd&
&             %fhipsch(nd, ifc, 0)+dvd%fhipsch(nd, ifc, 1))
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(dv%fhipsch(ifc&
&           , 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO nd=1,nbdirsmax
            t0d(nd) = 0.d0
          END DO
          DO is=0,ns-1
            temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp5 = pl%ti(icv1) + pl%ti(icv2)
            temp4 = pl%na(icv1, is) + pl%na(icv2, is)
            temp3 = temp4*temp5
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1, &
&             is)
            DO nd=1,nbdirs
              t0d(nd) = t0d(nd) + temp2*(temp3*(temp1*dvd%vadia(nd, ifc&
&               , 0, is)+temp0*dvd%vadia(nd, ifc, 1, is))+temp*(temp5*(&
&               pld%na(nd, icv1, is)+pld%na(nd, icv2, is))+temp4*(pld%ti&
&               (nd, icv1)+pld%ti(nd, icv2))))
            END DO
            t0 = t0 + temp2*(temp*temp3)
          END DO
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              max4d(nd) = t0d(nd)
            END DO
            max4 = t0
          ELSE
            max4 = 0.0_R8
            DO nd=1,nbdirsmax
              max4d(nd) = 0.d0
            END DO
          END IF
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + max4d(nd)
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max4
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              min3d(nd) = t0d(nd)
            END DO
            min3 = t0
          ELSE
            min3 = 0.0_R8
            DO nd=1,nbdirsmax
              min3d(nd) = 0.d0
            END DO
          END IF
          temp5 = min3/pl%ti(icv1)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + (min3d(nd)&
&             -temp5*pld%ti(nd, icv1))/pl%ti(icv1)
          END DO
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + temp5
        END IF
      END DO
    CASE (15) 
!
! -- BCENI=15 -- DRIFT-COMPATIBLE SHEATH CONDITION                   !srv 01.02.09 {
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 20.09.17
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 15 : drift-compatible sheath condition '//&
&       'for ion temperature with ENIPAR(IB,1) =', enipar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        WRITE(*, *) 'BCENI=15 - should have BCCON=14 for all ions'
!srv 20.09.17
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 15, ENIPAR(IB,1) <= 0 not allowed!')
        IF (bceni_15_style .NE. 0) WRITE(*, *) 'bceni_15_style <> 0'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY ', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) THEN
          WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&         'HAS NOT BEEN IMPOSED AT BOUNDARY ', ib, ' FOR ALL IONS'
          IF (bceni_15_style .EQ. 0) CALL XERRAB(&
&                              'When BCENI=15 and bceni_15_style.eq.0, '&
&                                          //&
&                          'one must have BCCON=14 for all ion species!'&
&                                         )
        END IF
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
!srv 15.02.26 {
        DO is=0,ns-1
          CALL CSBC_IS_DV(icv1, ib, is, cs, csd, nbdirs)
          CALL VBC_IS_DV(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), &
&                  csbcd(:, icv1, is), wrk, nbdirs)
!srv 15.02.26 }
        END DO
        temp2 = pz(icv1)/rz(icv1)
        DO nd=1,nbdirs
          arg12d(nd) = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
        END DO
        arg12 = temp2
        temp2 = SQRT(arg12)
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            csd(nd) = 0.d0
          ELSE
            csd(nd) = arg12d(nd)/(2.0*temp2)
          END IF
        END DO
        cs = temp2
        t0 = 0.0_R8
        t1 = 0.0_R8
        t2 = 0.0_R8
        wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
        IF (bceni_15_style .EQ. 0) THEN
          IF (wrk .GE. 0.) THEN
            abs0 = wrk
          ELSE
            abs0 = -wrk
          END IF
          IF (abs0 .LT. geo%qalfmin) THEN
            temp2 = 1.5_R8*geo%fcs(ifc)*geo%qalfmax
            DO nd=1,nbdirs
              srwd%shi0(nd, icv1, 0) = 0.d0
              srwd%shi0(nd, icv1, 1) = -(temp2*(dv%ni(icv1, 1)*csd(nd)+&
&               cs*dvd%ni(nd, icv1, 1)))
            END DO
            srw%shi0(icv1, 0) = 0.0_R8
            srw%shi0(icv1, 1) = -(temp2*(cs*dv%ni(icv1, 1)))
            IF (switch%mdf_fhi .NE. 0) THEN
              temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
              DO nd=1,nbdirs
                srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*&
&                 (dvd%fhipsch(nd, ifc, 0)+dvd%fhipsch(nd, ifc, 1))
              END DO
              srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(dv%fhipsch(&
&               ifc, 0)+dv%fhipsch(ifc, 1))
              t0 = 0.0_R8
              DO nd=1,nbdirsmax
                t0d(nd) = 0.d0
              END DO
              DO is=0,ns-1
                temp2 = 1.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(&
&                 0.5_R8*0.5_R8)
                temp5 = pl%ti(icv1) + pl%ti(icv2)
                temp4 = pl%na(icv1, is) + pl%na(icv2, is)
                temp3 = temp4*temp5
                temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
                temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
                temp = temp1*dv%vaecrb(ifc, 0, is) + temp0*dv%vaecrb(ifc&
&                 , 1, is)
                DO nd=1,nbdirs
                  t0d(nd) = t0d(nd) + temp2*(temp3*(temp1*dvd%vaecrb(nd&
&                   , ifc, 0, is)+temp0*dvd%vaecrb(nd, ifc, 1, is))+temp&
&                   *(temp5*(pld%na(nd, icv1, is)+pld%na(nd, icv2, is))+&
&                   temp4*(pld%ti(nd, icv1)+pld%ti(nd, icv2))))
                END DO
                t0 = t0 + temp2*(temp*temp3)
              END DO
              IF (0.0_R8 .LT. t0) THEN
                DO nd=1,nbdirs
                  max5d(nd) = t0d(nd)
                END DO
                max5 = t0
              ELSE
                max5 = 0.0_R8
                DO nd=1,nbdirsmax
                  max5d(nd) = 0.d0
                END DO
              END IF
              DO nd=1,nbdirs
                srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + max5d(&
&                 nd)
              END DO
              srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max5
              IF (0.0_R8 .GT. t0) THEN
                DO nd=1,nbdirs
                  min4d(nd) = t0d(nd)
                END DO
                min4 = t0
              ELSE
                min4 = 0.0_R8
                DO nd=1,nbdirsmax
                  min4d(nd) = 0.d0
                END DO
              END IF
              temp5 = min4/pl%ti(icv1)
              DO nd=1,nbdirs
                srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + (min4d&
&                 (nd)-temp5*pld%ti(nd, icv1))/pl%ti(icv1)
              END DO
              srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + temp5
            END IF
          ELSE
            DO nd=1,nbdirsmax
              t0d(nd) = 0.d0
            END DO
            DO nd=1,nbdirsmax
              t1d(nd) = 0.d0
            END DO
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) THEN
                temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
                DO nd=1,nbdirs
                  vbndd(nd) = temp2*(geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, &
&                   ifc, 0, is)+geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc, 1&
&                   , is))
                END DO
                vbnd = temp2*(geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+&
&                 geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))
                IF (wrk .GE. 0.) THEN
                  abs5 = wrk
                ELSE
                  abs5 = -wrk
                END IF
                temp5 = SIGN(1.0_R8, wrk)
                DO nd=1,nbdirs
                  x1d(nd) = abs5*csbcd(nd, icv1, is)
                  y1d(nd) = temp5*vbcd(nd, icv1, is) + vbndd(nd)
                END DO
                x1 = csbc(icv1, is)*abs5
                y1 = temp5*vbc(icv1, is) + vbnd
                IF (x1 .LT. y1) THEN
                  DO nd=1,nbdirs
                    max6d(nd) = y1d(nd)
                  END DO
                  max6 = y1
                ELSE
                  DO nd=1,nbdirs
                    max6d(nd) = x1d(nd)
                  END DO
                  max6 = x1
                END IF
                temp2 = mompar(is, ib, 1)*max6
                DO nd=1,nbdirs
                  t0d(nd) = t0d(nd) + geo%fcs(ifc)*(pl%na(icv1, is)*(&
&                   max6*mompard(nd, is, ib, 1)+mompar(is, ib, 1)*max6d(&
&                   nd))+temp2*pld%na(nd, icv1, is))
                END DO
                t0 = t0 + geo%fcs(ifc)*(temp2*pl%na(icv1, is))
                IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
                  temp5 = co%dna0(icv1, is)*pl%na(icv1, is)/conpar(is, &
&                   ib, 2)
                  DO nd=1,nbdirs
                    t1d(nd) = t1d(nd) + (pl%na(icv1, is)*cod%dna0(nd, &
&                     icv1, is)+co%dna0(icv1, is)*pld%na(nd, icv1, is)-&
&                     temp5*conpard(nd, is, ib, 2))/conpar(is, ib, 2)
                  END DO
                  t1 = t1 + temp5
                END IF
              END IF
            END DO
            temp2 = switch%stab_coeff_sheath_ti*geo%fcs(ifc)
            temp1 = fac_he_anom_bc*geo%fcs(ifc)
            DO nd=1,nbdirs
              srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) - t0*&
&               enipard(nd, ib, 1) - enipar(ib, 1)*t0d(nd) - temp2*(cs*&
&               dvd%ne(nd, icv1)+dv%ne(icv1)*csd(nd)) - temp1*(t1*&
&               enipard(nd, ib, 2)+enipar(ib, 2)*t1d(nd))
            END DO
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) - enipar(ib, 1)*t0 - &
&             temp2*(dv%ne(icv1)*cs) - temp1*(enipar(ib, 2)*t1)
            temp2 = switch%stab_coeff_sheath_ti*geo%fcs(ifc)
            temp5 = dv%ne(icv1)*cs
            DO nd=1,nbdirs
              srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*(&
&               pl%ti(icv1)*(cs*dvd%ne(nd, icv1)+dv%ne(icv1)*csd(nd))+&
&               temp5*pld%ti(nd, icv1))
            END DO
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(temp5*pl%ti(&
&             icv1))
          END IF
        ELSE
          DO nd=1,nbdirsmax
            t0d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t2d(nd) = 0.d0
          END DO
!wdk sheath transmission factor consistent with truncated
!    Maxwellian distribution on Eirene side (NEMODS=7)
!    See Eirene manual for details.
          DO is=0,ns-1
            IF (.NOT.is_neutral(is)) THEN
              arg13 = 2.0_R8*pl%ti(icv1)/(am(is)*mp)
              temp6 = SQRT(arg13)
              DO nd=1,nbdirs
                arg13d(nd) = 2.0_R8*pld%ti(nd, icv1)/(am(is)*mp)
                IF (arg13 .EQ. 0.d0) THEN
                  vtd(nd) = 0.d0
                ELSE
                  vtd(nd) = arg13d(nd)/(2.0*temp6)
                END IF
              END DO
              vt = temp6
              IF (geo%fcqalf(ifc, 0) .GE. 0.) THEN
                abs1 = geo%fcqalf(ifc, 0)
              ELSE
                abs1 = -geo%fcqalf(ifc, 0)
              END IF
              result10 = PIT(icv1)
              DO nd=1,nbdirs
                t3d(nd) = result10*abs1*(csd(nd)-cs*vtd(nd)/vt)/vt
              END DO
              t3 = result10*abs1*cs/vt
              IF (geo%fcqalf(ifc, 1) .GE. 0.) THEN
                abs2 = geo%fcqalf(ifc, 1)
              ELSE
                abs2 = -geo%fcqalf(ifc, 1)
              END IF
!WG_TODO correct for drift contributions!
              result10 = PIT(icv1)
              temp2 = result10*abs2*cs/vt
              temp1 = geo%cvbb(icv1, 3)*vt
              temp0 = cs/temp1
              temp = geo%cvbb(icv1, 2)*temp0
              DO nd=1,nbdirs
                arg12d(nd) = 2*temp2*result10*abs2*(csd(nd)-cs*vtd(nd)/&
&                 vt)/vt + 2*temp*geo%cvbb(icv1, 2)*(csd(nd)-temp0*geo%&
&                 cvbb(icv1, 3)*vtd(nd))/temp1
              END DO
              arg12 = temp2*temp2 + temp*temp
              temp2 = SQRT(arg12)
              DO nd=1,nbdirs
                IF (arg12 .EQ. 0.d0) THEN
                  t4d(nd) = 0.d0
                ELSE
                  t4d(nd) = arg12d(nd)/(2.0*temp2)
                END IF
              END DO
              t4 = temp2
!corrected for factor 3/2 in parallel convection
              CALL SHEATH_G_DV(t3, t3d, result10, result10d, nbdirs)
              CALL SHEATH_G_DV(t3, t3d, result20, result20d, nbdirs)
              temp2 = (result10-1.0_R8)/result20
              DO nd=1,nbdirs
                dshd(nd) = 2*t3*t3d(nd) + 2*t4*t4d(nd) + 0.5_R8*(&
&                 result10d(nd)-temp2*result20d(nd))/result20
              END DO
              dsh = t3*t3 + t4*t4 + 0.5_R8*temp2 + 1.0_R8
              temp2 = dsh*mompar(is, ib, 1)
              DO nd=1,nbdirs
                t0d(nd) = t0d(nd) + pl%na(icv1, is)*(mompar(is, ib, 1)*&
&                 dshd(nd)+dsh*mompard(nd, is, ib, 1)) + temp2*pld%na(nd&
&                 , icv1, is)
              END DO
              t0 = t0 + temp2*pl%na(icv1, is)
              IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
                temp5 = pl%na(icv1, is)/conpar(is, ib, 2)
                temp2 = enipar(ib, 2)*co%dna0(icv1, is)
                DO nd=1,nbdirs
                  t1d(nd) = t1d(nd) + fac_he_anom_bc*(temp5*(co%dna0(&
&                   icv1, is)*enipard(nd, ib, 2)+enipar(ib, 2)*cod%dna0(&
&                   nd, icv1, is))+temp2*(pld%na(nd, icv1, is)-temp5*&
&                   conpard(nd, is, ib, 2))/conpar(is, ib, 2))
                END DO
                t1 = t1 + fac_he_anom_bc*(temp2*temp5)
              END IF
              DO nd=1,nbdirs
                t2d(nd) = t2d(nd) + dvd%fhm(nd, ifc, 0, is) + dvd%fhm(nd&
&                 , ifc, 1, is)
              END DO
              t2 = t2 + dv%fhm(ifc, 0, is) + dv%fhm(ifc, 1, is)
            END IF
          END DO
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs3 = geo%fcpbs(ifc)
          ELSE
            abs3 = -geo%fcpbs(ifc)
          END IF
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) - (switch%&
&             stab_coeff_sheath_ti+1.0_R8)*abs3*(cs*t0d(nd)+t0*csd(nd)) &
&             + temp2*t2d(nd) - geo%fcs(ifc)*t1d(nd)
          END DO
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) - (switch%&
&           stab_coeff_sheath_ti+1.0_R8)*abs3*(t0*cs) + temp2*t2 - geo%&
&           fcs(ifc)*t1
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs4 = geo%fcpbs(ifc)
          ELSE
            abs4 = -geo%fcpbs(ifc)
          END IF
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + switch%&
&             stab_coeff_sheath_ti*abs4*(cs*t0d(nd)+t0*csd(nd))
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + switch%&
&           stab_coeff_sheath_ti*t0*cs*abs4
        END IF
        IF (switch%mdf_fhi .NE. 0) THEN
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + temp2*(dvd&
&             %fhipsch(nd, ifc, 0)+dvd%fhipsch(nd, ifc, 1))
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(dv%fhipsch(ifc&
&           , 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO nd=1,nbdirsmax
            t0d(nd) = 0.d0
          END DO
          DO is=0,ns-1
            temp2 = 2.5_R8*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(0.5_R8*&
&             0.5_R8)
            temp5 = pl%ti(icv1) + pl%ti(icv2)
            temp4 = pl%na(icv1, is) + pl%na(icv2, is)
            temp3 = temp4*temp5
            temp1 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            temp = temp1*dv%vadia(ifc, 0, is) + temp0*dv%vadia(ifc, 1, &
&             is)
            DO nd=1,nbdirs
              t0d(nd) = t0d(nd) + temp2*(temp3*(temp1*dvd%vadia(nd, ifc&
&               , 0, is)+temp0*dvd%vadia(nd, ifc, 1, is))+temp*(temp5*(&
&               pld%na(nd, icv1, is)+pld%na(nd, icv2, is))+temp4*(pld%ti&
&               (nd, icv1)+pld%ti(nd, icv2))))
            END DO
            t0 = t0 + temp2*(temp*temp3)
          END DO
          IF (0.0_R8 .LT. t0) THEN
            DO nd=1,nbdirs
              max7d(nd) = t0d(nd)
            END DO
            max7 = t0
          ELSE
            max7 = 0.0_R8
            DO nd=1,nbdirsmax
              max7d(nd) = 0.d0
            END DO
          END IF
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + max7d(nd)
          END DO
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max7
          IF (0.0_R8 .GT. t0) THEN
            DO nd=1,nbdirs
              min5d(nd) = t0d(nd)
            END DO
            min5 = t0
          ELSE
            min5 = 0.0_R8
            DO nd=1,nbdirsmax
              min5d(nd) = 0.d0
            END DO
          END IF
          temp5 = min5/pl%ti(icv1)
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 1) = srwd%shi0(nd, icv1, 1) + (min5d(nd)&
&             -temp5*pld%ti(nd, icv1))/pl%ti(icv1)
          END DO
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + temp5
        END IF
!wdk    Todo: corrections for BCCON.ne.14
!srv 01.02.09 }

      END DO
    CASE (16) 
!
! -- BCENI=16 -- Feedback boundary condition with constant temperature
!
!
      IF (switch%bceni_16_style .EQ. 0) THEN
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&         'ion temperature feedback by flux ', enipar(ib, 1), ' with ', &
&         enipar(ib, 2), ' on ', bcchar(ib), boundary_location(ib)
          CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        END IF
!       ..compute average temperature on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
        DO nd=1,nbdirsmax
          totfluxd(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          t0d(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          t1d(nd) = 0.d0
        END DO
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            t0d(nd) = t0d(nd) + geo%fcs(ifc)*dvd%ni(nd, icv1, 0)
!wdk at the moment, totflux only contains ion/neutral heat flux;
!wdk bc_type16_kinetic_energy.eq.1 option not yet included
            t1d(nd) = t1d(nd) + geo%fcs(ifc)*(pl%ti(icv1)*dvd%ni(nd, &
&             icv1, 0)+dv%ni(icv1, 0)*pld%ti(nd, icv1))
            totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, ifc, 0)+dvd&
&             %fhi(nd, ifc, 1))
          END DO
          t0 = t0 + geo%fcs(ifc)*dv%ni(icv1, 0)
          t1 = t1 + geo%fcs(ifc)*dv%ni(icv1, 0)*pl%ti(icv1)
          totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
        END DO
        DO nd=1,nbdirs
          t1d(nd) = (t1d(nd)-t1*t0d(nd)/t0)/t0
          totpard(nd) = fac_he_anom_bc*enipard(nd, ib, 1)
        END DO
        t1 = t1/t0
        totpar = fac_he_anom_bc*enipar(ib, 1)
        IF (enipar(ib, 2) .GT. 0.0_R8) THEN
          DO nd=1,nbdirs
            t3d(nd) = enipard(nd, ib, 2)
          END DO
          t3 = enipar(ib, 2)
        ELSE
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
        END IF
        IF (enipar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_ti
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
        END IF
        IF (totflux .GE. 0.) THEN
          DO nd=1,nbdirs
            x2d(nd) = totfluxd(nd)
          END DO
          x2 = totflux
        ELSE
          DO nd=1,nbdirs
            x2d(nd) = -totfluxd(nd)
          END DO
          x2 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          DO nd=1,nbdirs
            y2d(nd) = totpard(nd)
          END DO
          y2 = totpar
        ELSE
          DO nd=1,nbdirs
            y2d(nd) = -totpard(nd)
          END DO
          y2 = -totpar
        END IF
        IF (x2 .LT. y2) THEN
          DO nd=1,nbdirs
            max8d(nd) = y2d(nd)
          END DO
          max8 = y2
        ELSE
          DO nd=1,nbdirs
            max8d(nd) = x2d(nd)
          END DO
          max8 = x2
        END IF
        temp2 = t3/max8
        temp5 = -((totflux-totpar)*temp2) + 1.0_R8
        DO nd=1,nbdirs
          t2d(nd) = temp5*t1d(nd) - t1*(temp2*(totfluxd(nd)-totpard(nd))&
&           +(totflux-totpar)*(t3d(nd)-temp2*max8d(nd))/max8)
        END DO
        t2 = temp5*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&             'bceni=16: curr_flux, desired_flux, old/new temperature, '&
&                                        , totflux, totpar, t1/qe, t2/qe
!       ..impose temperature
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2d(nd)
            srwd%shi0(nd, icv1, 1) = 0.d0
          END DO
          srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2
          srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE IF (switch%bceni_16_style .EQ. 1) THEN
!
!srv 16.02.12 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, *) 'BCENI = 16 (style = 1) : '//&
&         'Given integrated ion heat flux with constant Ti '
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location&
&             (ibw)
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCENI = 16 only applicable to core boundaries !')
              CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                   'faulty parameter enipar1')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               ((bceni(ibw) .EQ. 23 .OR. bceni(ibw) .EQ. 24) .OR. bceni&
&               (ibw) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
              CALL XERRAB(&
&                   'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!'&
&                  )
            END IF
          END DO
        END IF
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bceni) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              senipar = 0.0_R8
              DO nd=1,nbdirsmax
                senipard(nd) = 0.d0
              END DO
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bceni(ibw) .EQ. bceni(ib)) THEN
                  DO nd=1,nbdirs
                    senipard(nd) = senipard(nd) + enipard(nd, ibw, 1)
                  END DO
                  senipar = senipar + enipar(ibw, 1)
                END IF
              END DO
            END IF
            WRITE(*, *) 'BCENI=16: Summed value is ', senipar
            tis = 0.0_R8
            nivs = 0.0_R8
            DO nd=1,nbdirsmax
              tisd(nd) = 0.d0
            END DO
            DO nd=1,nbdirsmax
              nivsd(nd) = 0.d0
            END DO
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  DO nd=1,nbdirs
                    tisd(nd) = tisd(nd) + geo%cvvol(icv)*(dv%ni(icv, 0)*&
&                     pld%ti(nd, icv)+pl%ti(icv)*dvd%ni(nd, icv, 0))
                    nivsd(nd) = nivsd(nd) + geo%cvvol(icv)*dvd%ni(nd, &
&                     icv, 0)
                  END DO
                  tis = tis + pl%ti(icv)*dv%ni(icv, 0)*geo%cvvol(icv)
                  nivs = nivs + dv%ni(icv, 0)*geo%cvvol(icv)
                END DO
              END IF
            END DO
            DO nd=1,nbdirs
              tisd(nd) = (tisd(nd)-tis*nivsd(nd)/nivs)/nivs
            END DO
            tis = tis/nivs
            totflux = 0.0_R8
            DO nd=1,nbdirsmax
              totfluxd(nd) = 0.d0
            END DO
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  IF (switch%mdf_fhi .NE. 0) THEN
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi_mdf(&
&                       nd, ifc, 0)+dvd%fhi_mdf(nd, ifc, 1))
                    END DO
                    totflux = totflux - temp2*(dv%fhi_mdf(ifc, 0)+dv%&
&                     fhi_mdf(ifc, 1))
                    DO is=0,ns-1
                      temp2 = geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                       ibc-1)
                      temp1 = geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is) +&
&                       geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is)
                      temp5 = pl%ti(icv)*pl%na(icv, is)
                      DO nd=1,nbdirs
                        totfluxd(nd) = totfluxd(nd) - temp2*(temp1*(pl%&
&                         na(icv, is)*pld%ti(nd, icv)+pl%ti(icv)*pld%na(&
&                         nd, icv, is))+temp5*(geo%fcqalf(ifc, 0)*dvd%&
&                         vaecrb(nd, ifc, 0, is)+geo%fcqalf(ifc, 1)*dvd%&
&                         vaecrb(nd, ifc, 1, is)))
                      END DO
                      totflux = totflux - temp2*(temp5*temp1)
                    END DO
                  ELSE
                    temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, &
&                       ifc, 0)+dvd%fhi(nd, ifc, 1))
                    END DO
                    totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc&
&                     , 1))
                  END IF
                END DO
              END IF
            END DO
            IF (enipar(ib, 2) .GT. 0.0_R8) THEN
              DO nd=1,nbdirs
                t3d(nd) = enipard(nd, ib, 2)
              END DO
              t3 = enipar(ib, 2)
            ELSE
              DO nd=1,nbdirsmax
                t3d(nd) = 0.d0
              END DO
            END IF
            IF (enipar(ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref_ti
              DO nd=1,nbdirsmax
                t3d(nd) = 0.d0
              END DO
            END IF
            IF (totflux .GE. 0.) THEN
              DO nd=1,nbdirs
                x3d(nd) = totfluxd(nd)
              END DO
              x3 = totflux
            ELSE
              DO nd=1,nbdirs
                x3d(nd) = -totfluxd(nd)
              END DO
              x3 = -totflux
            END IF
            IF (x3 .LT. senipar) THEN
              DO nd=1,nbdirs
                max9d(nd) = senipard(nd)
              END DO
              max9 = senipar
            ELSE
              DO nd=1,nbdirs
                max9d(nd) = x3d(nd)
              END DO
              max9 = x3
            END IF
            temp2 = t3/max9
            temp5 = -((totflux-senipar)*temp2) + 1.0_R8
            DO nd=1,nbdirs
              tisd(nd) = temp5*tisd(nd) - tis*(temp2*(totfluxd(nd)-&
&               senipard(nd))+(totflux-senipar)*(t3d(nd)-temp2*max9d(nd)&
&               )/max9)
            END DO
            tis = tis*temp5
            WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&           totflux, ' SENIPAR=', senipar
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  DO nd=1,nbdirs
                    srwd%shi0(nd, icv, 0) = vbig*ne00*geo%fcs(ifc)*tisd(&
&                     nd)
                    srwd%shi0(nd, icv, 1) = 0.d0
                  END DO
                  srw%shi0(icv, 0) = vbig*ne00*tis*geo%fcs(ifc)
                  srw%shi0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
                END DO
              END IF
            END DO
            once_bceni = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCENI=16, ONLY AVAILABLE FOR CORE!')
        END IF
      ELSE
        CALL XERRAB(' Incorrect style of boundary condition')
      END IF
    CASE (17) 
!
! -- BCENI=17 -- Feedback boundary condition with constant temperature
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 17 : ion temperature feedback by flux ', enipar(ib, 1)&
&       , ' with ', enipar(ib, 2), ' on ', bcchar(ib), boundary_location&
&       (ib)
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        CALL XERTST(enipar(ib, 2) .GT. 0, 'faulty parameter enipar2')
        CALL XERTST(bcene(ib) .EQ. bceni(ib), &
&             'both bcene and bceni should be set to 17')
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        CALL XERTST(enepar(ib, 2) .GT. 0, 'faulty parameter enepar2')
      END IF
      IF (.NOT.(bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A')) THEN
! already handled when the electron heat bc was handled
! see label 2980
        CALL XERRAB('B2STBC -- BCENI=17, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (18) 
!
! -- BCENI=18 -- FRACTIONAL DROP CONDITION (FOR EDGE2D COMPARISON)
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI = 18 : ion temperature fractional drop', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .LT. 1.0_R8, &
&             'BCENI = 18, ENIPAR(,1) => 1')
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          t1d(nd) = (1.0_R8-enipar(ib, 1))*pld%ti(nd, icv2) - pl%ti(icv2&
&           )*enipard(nd, ib, 1)
          srwd%shi0(nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1d(nd)
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        t1 = (1.0_R8-enipar(ib, 1))*pl%ti(icv2)
        srw%shi0(icv1, 0) = vbig*ne00*t1*geo%fcs(ifc)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (19) 
!
! -- BCENI=19 -- PRESCRIBE THE DECAY LENGTH FOR THE ION TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENI = 19 not adapted for WG')
!
! -- BCENI=20 -- Feedback boundary condition with constant temperature
!
    CASE (20) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 20 : ion temperature feedback by flux (neo) ', enipar(&
&       ib, 1), ' with ', enipar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        tiave = 0.0_R8
        niave = 0.0_R8
        DO nd=1,nbdirsmax
          totfluxd(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          niaved(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          t0d(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          tiaved(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          weightd(nd) = 0.d0
        END DO
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, ifc, 0)+dvd&
&             %fhi(nd, ifc, 1))
            t0d(nd) = t0d(nd) + geo%cvvol(icv1)*(dv%ni(icv1, 0)*pld%ti(&
&             nd, icv1)+pl%ti(icv1)*dvd%ni(nd, icv1, 0))
            weightd(nd) = weightd(nd) + geo%cvvol(icv1)*dvd%ni(nd, icv1&
&             , 0)
            tiaved(nd) = tiaved(nd) + geo%cvvol(icv2)*(dv%ni(icv2, 0)*&
&             pld%ti(nd, icv2)+pl%ti(icv2)*dvd%ni(nd, icv2, 0))
            niaved(nd) = niaved(nd) + geo%cvvol(icv2)*dvd%ni(nd, icv2, 0&
&             )
          END DO
          totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
          t0 = t0 + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv1)
          weight = weight + dv%ni(icv1, 0)*geo%cvvol(icv1)
          tiave = tiave + pl%ti(icv2)*dv%ni(icv2, 0)*geo%cvvol(icv2)
          niave = niave + dv%ni(icv2, 0)*geo%cvvol(icv2)
        END DO
        DO nd=1,nbdirs
          t0d(nd) = (t0d(nd)-t0*weightd(nd)/weight)/weight
          tiaved(nd) = (tiaved(nd)-tiave*niaved(nd)/niave)/niave
        END DO
        t0 = t0/weight
        tiave = tiave/niave
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        IF (enipar(ib, 2) .GT. 0.0_R8) THEN
          DO nd=1,nbdirs
            t3d(nd) = enipard(nd, ib, 2)
          END DO
          t3 = enipar(ib, 2)
        ELSE
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
        END IF
        IF (enipar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_ti
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
        END IF
        temp2 = t3/enipar(ib, 1)
        temp5 = -((totflux-enipar(ib, 1))*temp2) + 1.0_R8
        DO nd=1,nbdirs
          t1d(nd) = temp5*t0d(nd) - t0*(temp2*(totfluxd(nd)-enipard(nd, &
&           ib, 1))+(totflux-enipar(ib, 1))*(t3d(nd)-temp2*enipard(nd, &
&           ib, 1))/enipar(ib, 1))
        END DO
        t1 = temp5*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New ion temp :', t0/qe, t1&
&                                        /qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*ne00*geo%fcs(ifc)
          temp1 = t1/tiave
          DO nd=1,nbdirs
            srwd%shi0(nd, icv1, 0) = temp2*(temp1*pld%ti(nd, icv2)+pl%ti&
&             (icv2)*(t1d(nd)-temp1*tiaved(nd))/tiave)
            srwd%shi0(nd, icv1, 1) = 0.d0
          END DO
          srw%shi0(icv1, 0) = temp2*(pl%ti(icv2)*temp1)
          srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENI=20, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (21) 
!
!! FIXME: Clash here with 5.0/5.1 BCENI=21 type
!xpb Careful here because of BC number clash
! From 5.0: starting at version 01.001.030
! -- BCCON=21 -- constant ion temperature scaled by ion temperature on the ring bc_type21_ref away
! has been moved up to next available number (BCENI=25)
!
! From 5.2, after version number 01.001.078:
! -- BCENI=21 -- from b2stbc_spb                                     !srv 01.02.09 {
!
      CALL XERRAB('b2stbc_phys -- BCENI = 21 not adapted for WG')
!
! -- BCENI=22 -- RADIAL LEAKAGE CONDITION FOR THE ION TEMPERATURE    !srv 23.07.10 {
!                SPECIFIES A TEMPERATURE GRADIENT SUCH THAT THE DIFFUSIVE
!                FLUX IS SET TO BE EQUIVALENT TO A LEAKAGE VELOCITY, IN
!                UNITS OF THE COLLECTIVE ION THERMAL VELOCITY
!
    CASE (22) 
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCENI = 22 : with ENIPAR(IB,1)= ', &
&                                   enipar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
!wdk    Notes:
!wdk     * need correction for misaligned grids -> t1
!wdk     * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = geo%fcqalf(ifc, 1)
        t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&         fcqbet(ifc, 0)
        t2 = 0.0_R8
        DO nd=1,nbdirsmax
          t2d(nd) = 0.d0
        END DO
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            arg13 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*&
&             mp)
            temp5 = SQRT(arg13)
            csb = temp5
            DO nd=1,nbdirs
              arg13d(nd) = (pl%te(icv1)*rtd%rza(nd, icv1, is)+rt%rza(&
&               icv1, is)*pld%te(nd, icv1)+pld%ti(nd, icv1))/(am(is)*mp)
              IF (arg13 .EQ. 0.d0) THEN
                csbd(nd) = 0.d0
              ELSE
                csbd(nd) = arg13d(nd)/(2.0*temp5)
              END IF
              t2d(nd) = t2d(nd) + pl%na(icv1, is)*csbd(nd) + csb*pld%na(&
&               nd, icv1, is)
            END DO
            t2 = t2 + csb*pl%na(icv1, is)
          END IF
        END DO
        temp2 = vbig*ne00*ev
        temp1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1
        temp0 = t0*pl%ti(icv2) - temp1*(pl%ti(mpg%fcvx(ifc, 2))-pl%ti(&
&         mpg%fcvx(ifc, 1)))
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 0) = temp2*(temp0*cod%chci(nd, ifc, 1)+co%&
&           chci(ifc, 1)*(t0*pld%ti(nd, icv2)-temp1*(pld%ti(nd, mpg%fcvx&
&           (ifc, 2))-pld%ti(nd, mpg%fcvx(ifc, 1)))))
        END DO
        srw%shi0(icv1, 0) = temp2*(co%chci(ifc, 1)*temp0)
        temp2 = vbig*ne00*ev
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 1) = -(temp2*(t0*cod%chci(nd, ifc, 1)-geo%&
&           fcs(ifc)*(t2*enipard(nd, ib, 1)+enipar(ib, 1)*t2d(nd))))
        END DO
        srw%shi0(icv1, 1) = -(temp2*(t0*co%chci(ifc, 1)-geo%fcs(ifc)*(&
&         enipar(ib, 1)*t2)))
!srv 23.07.10 }
      END DO
    CASE (23) 
!
! -- BCENI=23 -- PRESCRIBE THE POLOIDALLY AVERAGED VALUE OF THE ION TEMPERATURE
! AND INTRODUCE A POLOIDAL VARIATION AS CLOSE AS POSSIBLE TO NEOCLASSICAL SOLUTION.
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 21,22,23
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7)') &
&       'BCENI = 23 : specified ion temperature ', enipar(ib, 1)
!          write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 23 only applicable to core boundaries !')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ib, 1) .EQ. &
&                 enipar(ibw, 1), &
&                 'BCENI = 23, inconsistent ENIPAR(,1) values!')
            IF (.NOT.((bccon(ismain, ib) .EQ. 21 .OR. bccon(ismain, ib) &
&               .EQ. 22) .OR. bccon(ismain, ib) .EQ. 23)) THEN
              WRITE(0, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=23'
              WRITE(*, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=23'
!srv 21.09.12
              WRITE(*, '(1x,a)') &
&             'Please ensure that this boundary condition '//&
&             'is consistent with '//&
&             'the ion density boundary condition'
            END IF
            IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&           THEN
              WRITE(0, *) &
&             'Use of BCENI=23 only meant for single-fluid runs!'
              WRITE(0, *) 'Use BCENI=26 instead!'
              WRITE(6, *) &
&             'Use of BCENI=23 only meant for single-fluid runs!'
              WRITE(6, *) 'Use BCENI=26 instead!'
            END IF
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 24) .OR. bceni(ibw&
&             ) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
        CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ibw, 1) .GT. &
&             0.0_R8, 'BCENI = 23, ENIPAR(,1) !> 0')
      END IF
!
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                    'Compile with -DASTRA option to couple with ASTRA!'&
&                                         )
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! Poloidally volume-averaged electron density in the cell next to boundary
          t2 = 0.0_R8
! Poloidally volume-averaged electron density in the boundary cell
          t3 = 0.0_R8
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t2d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                DO nd=1,nbdirs
                  t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)
                  t2d(nd) = t2d(nd) + geo%cvvol(icv2)*dvd%ne(nd, icv2)
                  t3d(nd) = t3d(nd) + geo%cvvol(icv2)*dvd%ne(nd, icv1)
                END DO
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                t2 = t2 + dv%ne(icv2)*geo%cvvol(icv2)
                t3 = t3 + dv%ne(icv1)*geo%cvvol(icv2)
              END DO
            END IF
          END DO
          DO nd=1,nbdirs
            t1d(nd) = t1d(nd)/t0
            t2d(nd) = t2d(nd)/t0
            t3d(nd) = t3d(nd)/t0
          END DO
          t1 = t1/t0
          t2 = t2/t0
          t3 = t3/t0
          DO ibw=ib,nbc
!lk 12.12.12 }
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                IF (mpg%cvonclosedsurface(icv2)) THEN
                  temp2 = vbig*ne00*geo%fcs(ifc)
                  temp1 = ev*t3*enipar(ibw, 1)
                  temp5 = (pl%ti(icv2)-t1)*t1*t2/temp1
                  DO nd=1,nbdirs
                    srwd%shi0(nd, icv1, 0) = srwd%shi0(nd, icv1, 0) + &
&                     temp2*(ev*enipard(nd, ibw, 1)+(t1*t2*(pld%ti(nd, &
&                     icv2)-t1d(nd))+(pl%ti(icv2)-t1)*(t2*t1d(nd)+t1*t2d&
&                     (nd))-temp5*(enipar(ibw, 1)*ev*t3d(nd)+ev*t3*&
&                     enipard(nd, ibw, 1)))/temp1)
                    srwd%shi0(nd, icv1, 1) = 0.d0
                  END DO
                  srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + temp2*(ev*&
&                   enipar(ibw, 1)+temp5)
                  srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
                END IF
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB(&
&              'B2STBC -- BCENI=23 IS AVAILABLE FOR CORE BOUNDARY ONLY.'&
&              )
        END IF
      END IF
    CASE (24) 
!
! -- BCENI=24 -- Feedback boundary condition with prescribed total ion heat flux,
!                constant poloidally averaged ion temperature and a
!                poloidal variation as close as possible to neoclassical solution.
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 21,22,23
!
!IYS 04.03.2013 {
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a)') 'BCENI = 24 : Given integrated ion heat flux', &
&       ' with constant Ti '
!          write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 24 only applicable to core boundaries !')
            CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                 'faulty parameter enipar1')
            IF (.NOT.((bccon(ismain, ib) .EQ. 21 .OR. bccon(ismain, ib) &
&               .EQ. 22) .OR. bccon(ismain, ib) .EQ. 23)) THEN
              WRITE(0, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=24'
              WRITE(*, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=24'
!srv 21.09.12
              WRITE(*, '(1x,a)') &
&             'Please ensure that this boundary condition '//&
&             'is consistent with '//&
&             'the ion density boundary condition'
            END IF
            IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&           THEN
              WRITE(0, *) &
&             'Use of BCENI=24 only meant for single-fluid runs!'
              WRITE(0, *) 'Use BCENI=27 instead!'
              WRITE(6, *) &
&             'Use of BCENI=24 only meant for single-fluid runs!'
              WRITE(6, *) 'Use BCENI=27 instead!'
            END IF
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
!srv 16.02.12 }
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) THEN
          CALL XERRAB(&
&               'Compile with -DASTRA option to couple with ASTRA!')
        ELSE
          senipar = 0.0_R8
          DO nd=1,nbdirsmax
            senipard(nd) = 0.d0
          END DO
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO nd=1,nbdirs
                senipard(nd) = senipard(nd) + enipard(nd, ibw, 1)
              END DO
              senipar = senipar + enipar(ibw, 1)
            END IF
          END DO
        END IF
        WRITE(*, *) 'BCENI=24: Summed value is ', senipar
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Poloidally density-averaged ion temperature in the boundary cell     !IYS 21.01.2016
          tis = 0.0_R8
          nivs = 0.0_R8
          totflux = 0.0_R8
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! Poloidally volume-averaged electron density in the cell next to boundary
          t2 = 0.0_R8
! Poloidally volume-averaged electron density in the boundary cell
          t3 = 0.0_R8
          DO nd=1,nbdirsmax
            tisd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            nivsd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            totfluxd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t2d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                DO nd=1,nbdirs
                  t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)
                  tisd(nd) = tisd(nd) + geo%cvvol(icv2)*(dv%ni(icv1, 0)*&
&                   pld%ti(nd, icv1)+pl%ti(icv1)*dvd%ni(nd, icv1, 0))
                  nivsd(nd) = nivsd(nd) + geo%cvvol(icv2)*dvd%ni(nd, &
&                   icv1, 0)
                  t2d(nd) = t2d(nd) + geo%cvvol(icv2)*dvd%ne(nd, icv2)
                  t3d(nd) = t3d(nd) + geo%cvvol(icv2)*dvd%ne(nd, icv1)
                END DO
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                tis = tis + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv2)
                nivs = nivs + dv%ni(icv1, 0)*geo%cvvol(icv2)
                t2 = t2 + dv%ne(icv2)*geo%cvvol(icv2)
                t3 = t3 + dv%ne(icv1)*geo%cvvol(icv2)
                IF (switch%mdf_fhi .NE. 0) THEN
                  temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                  DO nd=1,nbdirs
                    totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi_mdf(nd&
&                     , ifc, 0)+dvd%fhi_mdf(nd, ifc, 1))
                  END DO
                  totflux = totflux - temp2*(dv%fhi_mdf(ifc, 0)+dv%&
&                   fhi_mdf(ifc, 1))
                  DO is=0,ns-1
                    temp2 = geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)
                    temp1 = geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is) + &
&                     geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is)
                    temp5 = pl%ti(icv1)*pl%na(icv1, is)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(temp1*(pl%na(&
&                       icv1, is)*pld%ti(nd, icv1)+pl%ti(icv1)*pld%na(nd&
&                       , icv1, is))+temp5*(geo%fcqalf(ifc, 0)*dvd%&
&                       vaecrb(nd, ifc, 0, is)+geo%fcqalf(ifc, 1)*dvd%&
&                       vaecrb(nd, ifc, 1, is)))
                    END DO
                    totflux = totflux - temp2*(temp5*temp1)
                  END DO
                ELSE
                  temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                  DO nd=1,nbdirs
                    totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, ifc&
&                     , 0)+dvd%fhi(nd, ifc, 1))
                  END DO
                  totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc, &
&                   1))
                END IF
              END DO
            END IF
          END DO
          DO nd=1,nbdirs
            tisd(nd) = (tisd(nd)-tis*nivsd(nd)/nivs)/nivs
            t1d(nd) = t1d(nd)/t0
            t2d(nd) = t2d(nd)/t0
            t3d(nd) = t3d(nd)/t0
          END DO
          tis = tis/nivs
          t1 = t1/t0
          t2 = t2/t0
          t3 = t3/t0
          IF (enipar(ib, 2) .GT. 0.0_R8) THEN
            DO nd=1,nbdirs
              t4d(nd) = enipard(nd, ib, 2)
            END DO
            t4 = enipar(ib, 2)
          ELSE
            DO nd=1,nbdirsmax
              t4d(nd) = 0.d0
            END DO
          END IF
          IF (enipar(ib, 2) .LE. 0.0_R8) THEN
            t4 = switch%b2stbc_bc_ref_ti
            DO nd=1,nbdirsmax
              t4d(nd) = 0.d0
            END DO
          END IF
          IF (totflux .GE. 0.) THEN
            DO nd=1,nbdirs
              x4d(nd) = totfluxd(nd)
            END DO
            x4 = totflux
          ELSE
            DO nd=1,nbdirs
              x4d(nd) = -totfluxd(nd)
            END DO
            x4 = -totflux
          END IF
          IF (x4 .LT. senipar) THEN
            DO nd=1,nbdirs
              max10d(nd) = senipard(nd)
            END DO
            max10 = senipar
          ELSE
            DO nd=1,nbdirs
              max10d(nd) = x4d(nd)
            END DO
            max10 = x4
          END IF
          temp2 = t4/max10
          temp5 = -((totflux-senipar)*temp2) + 1.0_R8
          DO nd=1,nbdirs
            tisd(nd) = temp5*tisd(nd) - tis*(temp2*(totfluxd(nd)-&
&             senipard(nd))+(totflux-senipar)*(t4d(nd)-temp2*max10d(nd))&
&             /max10)
          END DO
          tis = tis*temp5
          WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&         totflux, ' SENIPAR=', senipar
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                temp2 = vbig*ne00*geo%fcs(ifc)
                temp5 = (pl%ti(icv2)-t1)*t1*t2/(t3*tis)
                DO nd=1,nbdirs
                  srwd%shi0(nd, icv1, 0) = temp2*(tisd(nd)+(t1*t2*(pld%&
&                   ti(nd, icv2)-t1d(nd))+(pl%ti(icv2)-t1)*(t2*t1d(nd)+&
&                   t1*t2d(nd))-temp5*(tis*t3d(nd)+t3*tisd(nd)))/(t3*tis&
&                   ))
                  srwd%shi0(nd, icv1, 1) = 0.d0
                END DO
                srw%shi0(icv1, 0) = temp2*(tis+temp5)
                srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB('B2STBC -- BCENI=24 IS AVAILABLE FOR CORE ONLY')
        END IF
      END IF
    CASE (25) 
!
! -- BCENI=25 -- constant ion temperature scaled by inner ring
! was BCENI=21 in 5.0/5.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 25 : fixed ion temperature '//&
&       '(modified by nearby ring) ', enipar(ib, 1), ' with ', enipar(ib&
&       , 2), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0.0_R8, &
&             'faulty parameter enipar1')
      END IF
      tiave = 0.0_R8
      niave = 0.0_R8
      DO nd=1,nbdirsmax
        niaved(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        tiaved(nd) = 0.d0
      END DO
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        DO nd=1,nbdirs
          tiaved(nd) = tiaved(nd) + geo%cvvol(icv)*(dv%ni(icv, 0)*pld%ti&
&           (nd, icv)+pl%ti(icv)*dvd%ni(nd, icv, 0))
          niaved(nd) = niaved(nd) + geo%cvvol(icv)*dvd%ni(nd, icv, 0)
        END DO
        tiave = tiave + pl%ti(icv)*dv%ni(icv, 0)*geo%cvvol(icv)
        niave = niave + dv%ni(icv, 0)*geo%cvvol(icv)
      END DO
      DO nd=1,nbdirs
        tiaved(nd) = (tiaved(nd)-tiave*niaved(nd)/niave)/niave
      END DO
      tiave = tiave/niave
      IF (enipar(ib, 2) .GT. 0.0_R8) THEN
        DO nd=1,nbdirs
          t3d(nd) = enipard(nd, ib, 2)
        END DO
        t3 = enipar(ib, 2)
      ELSE
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      IF (enipar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_ti
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = vbig*ne00*ev*geo%fcs(ifc)
        temp1 = t3/tiave
        temp5 = pl%ti(icv2)*temp1 - t3 + 1.0_R8
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 0) = temp2*(temp5*enipard(nd, ib, 1)+&
&           enipar(ib, 1)*(temp1*pld%ti(nd, icv2)+pl%ti(icv2)*(t3d(nd)-&
&           temp1*tiaved(nd))/tiave-t3d(nd)))
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        srw%shi0(icv1, 0) = temp2*(enipar(ib, 1)*temp5)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (26) 
!
! -- BCENI=26 -- PRESCRIBE THE POLOIDALLY AVERAGED VALUE OF THE ION TEMPERATURE
! AND INTRODUCE A POLOIDAL VARIATION IN A SIMPLIFIED MANNER.
! THIS BOUNDARY CONDITION IS SUITABLE FOR ANY PLASMA COMPOSITION (i.e. when BCENI=23 fails).
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 25,26,27
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7)') &
&       'BCENI = 26 : specified ion temperature ', enipar(ib, 1)
!         write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 26 only applicable to core boundaries !')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ibw, 1) .GT.&
&                 0.0_R8, 'BCENI = 26, ENIPAR(,1) !> 0')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ib, 1) .EQ. &
&                 enipar(ibw, 1), &
&                 'BCENI = 26, inconsistent ENIPAR(,1) values!')
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 24) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
!
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                    'Compile with -DASTRA option to couple with ASTRA!'&
&                                         )
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                t0 = t0 + geo%cvvol(icv)
                DO nd=1,nbdirs
                  t1d(nd) = t1d(nd) + geo%cvvol(icv)*pld%ti(nd, icv)
                END DO
                t1 = t1 + pl%ti(icv)*geo%cvvol(icv)
              END DO
            END IF
          END DO
          DO nd=1,nbdirs
            t1d(nd) = t1d(nd)/t0
          END DO
          t1 = t1/t0
          DO ibw=ib,nbc
!lk 12.12.12 }
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                IF (mpg%cvonclosedsurface(icv2)) THEN
                  temp2 = vbig*ne00*geo%fcs(ifc)
                  DO nd=1,nbdirs
                    srwd%shi0(nd, icv1, 0) = temp2*(ev*enipard(nd, ibw, &
&                     1)+pld%ti(nd, icv2)-t1d(nd))
                    srwd%shi0(nd, icv1, 1) = 0.d0
                  END DO
                  srw%shi0(icv1, 0) = temp2*(ev*enipar(ibw, 1)+pl%ti(&
&                   icv2)-t1)
                  srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
                END IF
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB(&
&              'B2STBC -- BCENI=26 IS AVAILABLE FOR CORE BOUNDARY ONLY.'&
&              )
        END IF
      END IF
    CASE (27) 
!
! -- BCENI=27 -- Feedback boundary condition with prescribed total ion heat flux,
!                constant poloidally averaged ion temperature and a
!                poloidal variation in a simplified manner.
! THIS BOUNDARY CONDITION IS SUITABLE FOR ANY PLASMA COMPOSITION (i.e. when BCENI=24 fails).
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 25,26,27
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENI = 27 : Given integrated ion heat flux', &
&       ' with constant Ti '
!         write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 27 only applicable to core boundaries !')
            CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                 'faulty parameter enipar1')
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 24) .OR. bceni(ibw) .EQ. 26)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
        IF (.NOT.once_bceni) THEN
          IF (switch%use_astra .NE. 0) THEN
            CALL XERRAB(&
&                 'Compile with -DASTRA option to couple with ASTRA!')
          ELSE
            senipar = 0.0_R8
            DO nd=1,nbdirsmax
              senipard(nd) = 0.d0
            END DO
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO nd=1,nbdirs
                  senipard(nd) = senipard(nd) + enipard(nd, ibw, 1)
                END DO
                senipar = senipar + enipar(ibw, 1)
              END IF
            END DO
          END IF
          WRITE(*, *) 'BCENI=27: Summed value is ', senipar
! Poloidally density-averaged ion temperature in the boundary cell
          tis = 0.0_R8
          nivs = 0.0_R8
! Volume                                      !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! IYS 22.03.2017
          totflux = 0.0_R8
          DO nd=1,nbdirsmax
            tisd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            nivsd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            totfluxd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                DO nd=1,nbdirs
                  tisd(nd) = tisd(nd) + geo%cvvol(icv2)*(dv%ni(icv1, 0)*&
&                   pld%ti(nd, icv1)+pl%ti(icv1)*dvd%ni(nd, icv1, 0))
                  nivsd(nd) = nivsd(nd) + geo%cvvol(icv2)*dvd%ni(nd, &
&                   icv1, 0)
                  t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)
                END DO
                tis = tis + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv2)
                nivs = nivs + dv%ni(icv1, 0)*geo%cvvol(icv2)
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                IF (switch%mdf_fhi .NE. 0) THEN
                  temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                  DO nd=1,nbdirs
                    totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi_mdf(nd&
&                     , ifc, 0)+dvd%fhi_mdf(nd, ifc, 1))
                  END DO
                  totflux = totflux - temp2*(dv%fhi_mdf(ifc, 0)+dv%&
&                   fhi_mdf(ifc, 1))
                  DO is=0,ns-1
                    temp2 = geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)
                    temp1 = geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is) + &
&                     geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is)
                    temp5 = pl%ti(icv1)*pl%na(icv1, is)
                    DO nd=1,nbdirs
                      totfluxd(nd) = totfluxd(nd) - temp2*(temp1*(pl%na(&
&                       icv1, is)*pld%ti(nd, icv1)+pl%ti(icv1)*pld%na(nd&
&                       , icv1, is))+temp5*(geo%fcqalf(ifc, 0)*dvd%&
&                       vaecrb(nd, ifc, 0, is)+geo%fcqalf(ifc, 1)*dvd%&
&                       vaecrb(nd, ifc, 1, is)))
                    END DO
                    totflux = totflux - temp2*(temp5*temp1)
                  END DO
                ELSE
                  temp2 = mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)
                  DO nd=1,nbdirs
                    totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, ifc&
&                     , 0)+dvd%fhi(nd, ifc, 1))
                  END DO
                  totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc, &
&                   1))
                END IF
              END DO
            END IF
          END DO
          DO nd=1,nbdirs
            tisd(nd) = (tisd(nd)-tis*nivsd(nd)/nivs)/nivs
            t1d(nd) = t1d(nd)/t0
          END DO
          tis = tis/nivs
          t1 = t1/t0
          IF (enipar(ib, 2) .GT. 0.0_R8) THEN
            DO nd=1,nbdirs
              t3d(nd) = enipard(nd, ib, 2)
            END DO
            t3 = enipar(ib, 2)
          ELSE
            DO nd=1,nbdirsmax
              t3d(nd) = 0.d0
            END DO
          END IF
          IF (enipar(ib, 2) .LE. 0.0_R8) THEN
            t3 = switch%b2stbc_bc_ref_ti
            DO nd=1,nbdirsmax
              t3d(nd) = 0.d0
            END DO
          END IF
          IF (totflux .GE. 0.) THEN
            DO nd=1,nbdirs
              x5d(nd) = totfluxd(nd)
            END DO
            x5 = totflux
          ELSE
            DO nd=1,nbdirs
              x5d(nd) = -totfluxd(nd)
            END DO
            x5 = -totflux
          END IF
          IF (x5 .LT. senipar) THEN
            DO nd=1,nbdirs
              max11d(nd) = senipard(nd)
            END DO
            max11 = senipar
          ELSE
            DO nd=1,nbdirs
              max11d(nd) = x5d(nd)
            END DO
            max11 = x5
          END IF
          temp2 = t3/max11
          temp5 = -((totflux-senipar)*temp2) + 1.0_R8
          DO nd=1,nbdirs
            tisd(nd) = temp5*tisd(nd) - tis*(temp2*(totfluxd(nd)-&
&             senipard(nd))+(totflux-senipar)*(t3d(nd)-temp2*max11d(nd))&
&             /max11)
          END DO
          tis = tis*temp5
          WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&         totflux, ' SENIPAR=', senipar
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                temp2 = vbig*ne00*geo%fcs(ifc)
                DO nd=1,nbdirs
                  srwd%shi0(nd, icv1, 0) = temp2*(tisd(nd)+pld%ti(nd, &
&                   icv2)-t1d(nd))
                  srwd%shi0(nd, icv1, 1) = 0.d0
                END DO
                srw%shi0(icv1, 0) = temp2*(tis+pl%ti(icv2)-t1)
                srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bceni = .true.
        END IF
      ELSE
        CALL XERRAB('B2STBC -- BCENI=27 IS AVAILABLE FOR CORE ONLY')
      END IF
    CASE (28) 
!
! -- BCENI=28 -- Prescribe the value of the ion temperature, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENI=28 intended for core boundaries only!')
        END DO
        IF (switch%use_astra .NE. 0) THEN
          DO nd=1,nbdirs
            enipard(nd, ib, 1) = 0.d0
          END DO
          enipar(ib, 1) = teb_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified ion temperature + perturbation', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 28, ENIPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            DO nd=1,nbdirs
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%ti(icv2)
          END DO
        END IF
      END DO
      DO nd=1,nbdirs
        t1d(nd) = t1d(nd)/t0
      END DO
      t1 = t1/t0
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 0) = temp2*(pld%ti(nd, icv2)+ev*enipard(nd&
&           , ib, 1)-t1d(nd))
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        srw%shi0(icv1, 0) = temp2*(pl%ti(icv2)+ev*enipar(ib, 1)-t1)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (29) 
!
! -- BCENI=29 -- Feedback on the total ion energy flux, by imposing a flux surface
!                averaged temperature, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENI=29 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified ion heat flux', enipar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 29, ENIPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t2d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        totpard(nd) = 0.d0
      END DO
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bceni(ib0) .NE. 29) CALL XERRAB(&
&                                      'BCENI=29: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
            DO nd=1,nbdirs
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv1)
              t2d(nd) = t2d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhi(nd, ifc, 0)+&
&               dvd%fhi(nd, ifc, 1))
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%ti(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%ti(icv2)
            totflux = totflux - temp2*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
          END DO
          DO nd=1,nbdirs
            totpard(nd) = totpard(nd) + enipard(nd, ib0, 1)
          END DO
          totpar = totpar + enipar(ib0, 1)
        END IF
      END DO
      DO nd=1,nbdirs
        totpard(nd) = fac_he_anom_bc*totpard(nd)
        t1d(nd) = t1d(nd)/t0
        t2d(nd) = t2d(nd)/t0
      END DO
      totpar = fac_he_anom_bc*totpar
      t1 = t1/t0
      t2 = t2/t0
      IF (enipar(ib, 2) .GT. 0.0_R8) THEN
        DO nd=1,nbdirs
          t3d(nd) = enipard(nd, ib, 2)
        END DO
        t3 = enipar(ib, 2)
      ELSE
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      IF (enipar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_ti
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      IF (totflux .GE. 0.) THEN
        DO nd=1,nbdirs
          x6d(nd) = totfluxd(nd)
        END DO
        x6 = totflux
      ELSE
        DO nd=1,nbdirs
          x6d(nd) = -totfluxd(nd)
        END DO
        x6 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        DO nd=1,nbdirs
          y3d(nd) = totpard(nd)
        END DO
        y3 = totpar
      ELSE
        DO nd=1,nbdirs
          y3d(nd) = -totpard(nd)
        END DO
        y3 = -totpar
      END IF
      IF (x6 .LT. y3) THEN
        DO nd=1,nbdirs
          max12d(nd) = y3d(nd)
        END DO
        max12 = y3
      ELSE
        DO nd=1,nbdirs
          max12d(nd) = x6d(nd)
        END DO
        max12 = x6
      END IF
      temp2 = t3/max12
      temp5 = -((totflux-totpar)*temp2) + 1.0_R8
      DO nd=1,nbdirs
        t4d(nd) = temp5*t1d(nd) - t1*(temp2*(totfluxd(nd)-totpard(nd))+(&
&         totflux-totpar)*(t3d(nd)-temp2*max12d(nd))/max12)
      END DO
      t4 = temp5*t1
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%shi0(nd, icv1, 0) = temp2*(pld%ti(nd, icv2)+t4d(nd)-t2d(&
&           nd))
          srwd%shi0(nd, icv1, 1) = 0.d0
        END DO
        srw%shi0(icv1, 0) = temp2*(pl%ti(icv2)+t4-t2)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bceni(ib)
      CALL XERRAB('BCENI out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENI_DV

!
  SUBROUTINE B2STBC_PHYS_ENI(ib)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER :: ib, ibw, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: t0, t1, t2, t3, t4, dsh, vt, vbnd, niave, tiave, &
&   totpar, totflux, weight, cs, csb, wrk
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    LOGICAL :: decay_length_ok
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC NINT
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: y1
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: y2
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: x4
    REAL(kind=r8) :: x5
    REAL(kind=r8) :: x6
    REAL(kind=r8) :: y3
    REAL(r8) :: max1
    REAL(r8) :: min1
    REAL(r8) :: max2
    REAL(r8) :: min2
    REAL(r8) :: max3
    REAL(r8) :: max4
    REAL(r8) :: min3
    REAL(kind=r8) :: abs0
    REAL(r8) :: max5
    REAL(r8) :: min4
    REAL(kind=r8) :: max6
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: abs4
    REAL(r8) :: max7
    REAL(r8) :: min5
    REAL(kind=r8) :: max8
    REAL(kind=r8) :: max9
    REAL(kind=r8) :: max10
    REAL(kind=r8) :: max11
    REAL(kind=r8) :: max12
    REAL(kind=r8) :: abs5
    REAL(kind=r8) :: arg12
    REAL(r8) :: arg13
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result20
!
! -- BOUNDARY CONDITIONS FOR ION ENERGY EQUATIONS --
!
    SELECT CASE  (bceni(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCENI=1 -- PRESCRIBE THE VALUE OF THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (bcchar(ib) .EQ. 'S' .AND. switch%use_astra .NE. 0) THEN
!srv 14.06.12
          enipar(ib, 1) = tib_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  1 : specified ion temperature ', enipar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 1, ENIPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*enipar(ib, 1)*ev
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENI=2 -- PRESCRIBE THE GRADIENT OF THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI =  2 : ion temperature gradient '&
&                                   , enipar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1 = INTVERTEX_S_NODIFF_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, &
&         pl%ti)
        t2 = INTVERTEX_S_NODIFF_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, &
&         pl%ti)
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(ev*enipar(ib, 1)*(&
&         geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2&
&         -t1)*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/&
&         geo%fcht(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%ti(icv2))
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENI=3 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
      CALL XERRAB('b2stbc_phys -- BCENI = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCENI = 15')
!
! -- BCENI=4 -- PRESCRIBE THE VALUE OF THE ION TEMPERATURE, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  4 : weak ion temperature ', enipar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 4, ENIPAR(,1) !> 0')
!srv 02.02.11
        CALL XERTST(enipar(ib, 2) .GT. 0.0_R8, &
&             'BCENI = 4, ENIPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = enipar(ib, 2)*geo%fcs(ifc)*enipar(ib, 1)
        srw%shi0(icv1, 1) = -(enipar(ib, 2)/ev*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCENI=5 -- PRESCRIBE THE ION ENERGY FLUX PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI =  5 : ion energy flux per area '&
&                                   , enipar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%shi0(icv, 0) = enipar(ib, 1)*geo%fcs(ifc)
        srw%shi0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCENI=6 -- PRESCRIBE THE TOTAL ION ENERGY FLUX FOR A
!                 CONSTANT ION TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENI = 6 not adapted for WG')
!
! -- BCENI=7 -- PRESCRIBE THE ION TEMPERATURE PROFILE
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') 'BCENI = 7 : specified ion temperature on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*bv_ti(icv1)*ev
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCENI=8 -- PRESCRIBE THE TOTAL ION HEAT FLUX WITH CONSTANT
!                 FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 28.07.11
        IF (switch%use_astra .NE. 0) enipar(ib, 1) = fhib_astra
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  8 : total ion energy flux', enipar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = fac_he_anom_bc*enipar(ib, 1)/us*geo%fcs(ifc)
        srw%shi0(icv1, 1) = 0.0_R8
        IF (switch%mdf_fhi .NE. 0) THEN
!wdk Correction now involves vedia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_fhi = 0 option
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhipsch(ifc, 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO is=0,ns-1
            t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs&
&             (ifc)*geo%fcqalf(ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             )
          END DO
          IF (0.0_R8 .LT. t0) THEN
            max1 = t0
          ELSE
            max1 = 0.0_R8
          END IF
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max1
          IF (0.0_R8 .GT. t0) THEN
            min1 = t0
          ELSE
            min1 = 0.0_R8
          END IF
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + min1/pl%ti(icv1)
        END IF
      END DO
    CASE (9) 
!
! -- BCENI=9 -- PRESCRIBE THE DECAY LENGTH FOR THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  9 : ion temperature decay length ', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0.0_R8, &
&             'BCENI = 9, ENIPAR(,1) = 0')
        decay_length_ok = .true.
        DO is=0,ns-1
          decay_length_ok = decay_length_ok .AND. ((bccon(is, ib) .EQ. 9&
&           .OR. bccon(is, ib) .EQ. 0) .OR. (is_neutral(is) .AND. switch&
&           %use_eirene .EQ. 1))
          IF (bccon(is, ib) .EQ. 1) WRITE(0, *) &
&                      'Should use BCENI=19 in conjunction with BCCON=1'
        END DO
        IF (.NOT.decay_length_ok) THEN
          WRITE(0, *) 'Should use BCENI.EQ.9 together with BCCON=9'
          WRITE(*, *) 'Should use BCENI.EQ.9 together with BCCON=9'
!srv 21.09.12
          WRITE(*, '(1x,a)') &
&         'Please ensure that this boundary condition '//&
&         'is consistent with '//'the density boundary condition'
        END IF
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        sy = geo%fcs(ifc)
        srw%shi0(icv1, 0) = 0.0_R8
        IF (switch%recycle_afn .EQ. 0 .OR. switch%tn_style .NE. 0) THEN
!! Note that
!! if tn_style=0: hci0 includes contributions from all ions and all fluid neutrals
!! if tn_style=1: hci0 includes contributions from ions only
!! if tn_style=2: hci0 includes contributions from all ions and non-hydrogenic neutrals
          srw%shi0(icv1, 1) = -(co%hci0(icv1)/enipar(ib, 1)*sy)
        ELSE
!! tn_style=0.and.recycle_afn=1 => take out hydrogenic atoms
          srw%shi0(icv1, 1) = -((co%hci0(icv1)-co%hcn0(icv1))/enipar(ib&
&           , 1)*sy)
        END IF
        DO is=0,ns-1
          IF (((.NOT.is_neutral(is)) .OR. switch%tn_style .EQ. 0) .OR. (&
&             switch%tn_style .EQ. 2 .AND. NINT(zn(is)) .NE. 1)) THEN
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + fac_he_anom*pl%ti(&
&             icv1)*srw%sna0(icv1, 0, is)
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + fac_he_anom*pl%na(&
&             icv1, is)*srw%sna0(icv1, 1, is)
          END IF
!! end species loop

        END DO
        IF (switch%mdf_fhi .NE. 0) THEN
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhipsch(ifc, 0)+dv%fhipsch(ifc, 1))
          DO is=0,ns-1
            t0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*1.5_R8*(geo%fcs(&
&             ifc)*geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             ))
            IF (0.0_R8 .LT. t0) THEN
              max2 = t0
            ELSE
              max2 = 0.0_R8
            END IF
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max2
            IF (0.0_R8 .GT. t0) THEN
              min2 = t0
            ELSE
              min2 = 0.0_R8
            END IF
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + min2/pl%ti(icv1)
          END DO
        END IF
!! end boundary cell loop

      END DO
    CASE (10) 
!
! -- BCENI=10 -- Feedback option for core
!
      CALL XERRAB('b2stbc_phys -- BCENI = 10 not adapted for WG')
!
! -- BCENI=11 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
    CASE (11) 
      CALL XERRAB('b2stbc_phys -- BCENI = 11 not adapted for WG')
!
! -- BCENI=12 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
    CASE (12) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a)') 'BCENI = 12 : sheath ion bc on ', bcchar(ib)&
&       , boundary_location(ib)
        WRITE(*, '(a)') &
&       'Obsolete. Use drift-compatible BCENI = 15 instead'
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO is=0,ns-1
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fna(ifc&
&             , 0, is)+dv%fna(ifc, 1, is))) THEN
            max3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fna(ifc, 0, is&
&             )+dv%fna(ifc, 1, is))
          ELSE
            max3 = 0.0_R8
          END IF
          srw%shi0(icv, 3) = srw%shi0(icv, 3) - enipar(ib, 1)*max3/dv%ni&
&           (icv, 0)
        END DO
      END DO
    CASE (13) 
!
! -- BCENI=13 -- PRESCRIBE THE ION ENERGY FLUX PER UNIT AREA
!             -- PROPORTIONAL TO TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI = 13 : ion energy flux per area '&
&                                   //'proportional to temperature ', &
&                                   enipar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%shi0(icv, 0) = enipar(ib, 1)*pl%ti(icv)*geo%fcs(ifc)
        srw%shi0(icv, 1) = 0.0_R8
      END DO
    CASE (14) 
!
! -- BCENI=14 -- leakage option for ion energy
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCENI = 14 : ion energy leakage ', &
&                                   enipar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        srw%shi0(icv1, 0) = 0.0_R8
        srw%shi0(icv1, 3) = geo%fcs(ifc)*cs*fac_he_anom_bc*enipar(ib, 1)
        IF (switch%mdf_fhi .NE. 0) THEN
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhipsch(ifc, 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO is=0,ns-1
            t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs&
&             (ifc)*geo%fcqalf(ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             )
          END DO
          IF (0.0_R8 .LT. t0) THEN
            max4 = t0
          ELSE
            max4 = 0.0_R8
          END IF
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max4
          IF (0.0_R8 .GT. t0) THEN
            min3 = t0
          ELSE
            min3 = 0.0_R8
          END IF
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + min3/pl%ti(icv1)
        END IF
      END DO
    CASE (15) 
!
! -- BCENI=15 -- DRIFT-COMPATIBLE SHEATH CONDITION                   !srv 01.02.09 {
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 20.09.17
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 15 : drift-compatible sheath condition '//&
&       'for ion temperature with ENIPAR(IB,1) =', enipar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        WRITE(*, *) 'BCENI=15 - should have BCCON=14 for all ions'
!srv 20.09.17
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 15, ENIPAR(IB,1) <= 0 not allowed!')
        IF (bceni_15_style .NE. 0) WRITE(*, *) 'bceni_15_style <> 0'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY ', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) THEN
          WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&         'HAS NOT BEEN IMPOSED AT BOUNDARY ', ib, ' FOR ALL IONS'
          IF (bceni_15_style .EQ. 0) CALL XERRAB(&
&                              'When BCENI=15 and bceni_15_style.eq.0, '&
&                                          //&
&                          'one must have BCCON=14 for all ion species!'&
&                                         )
        END IF
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
!srv 15.02.26 {
        DO is=0,ns-1
          CALL CSBC_IS(icv1, ib, is, cs)
          CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), wrk)
!srv 15.02.26 }
        END DO
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        t0 = 0.0_R8
        t1 = 0.0_R8
        t2 = 0.0_R8
        wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
        IF (bceni_15_style .EQ. 0) THEN
          IF (wrk .GE. 0.) THEN
            abs0 = wrk
          ELSE
            abs0 = -wrk
          END IF
          IF (abs0 .LT. geo%qalfmin) THEN
            srw%shi0(icv1, 0) = 0.0_R8
            srw%shi0(icv1, 1) = -(1.5_R8*geo%fcs(ifc)*geo%qalfmax*cs*dv%&
&             ni(icv1, 1))
            IF (switch%mdf_fhi .NE. 0) THEN
              srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + mpg%bcfcor(mpg%&
&               bccvp(ib, 1)+ibc-1)*(dv%fhipsch(ifc, 0)+dv%fhipsch(ifc, &
&               1))
              t0 = 0.0_R8
              DO is=0,ns-1
                t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*1.5_R8*(geo&
&                 %fcs(ifc)*geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo&
&                 %fcs(ifc)*geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*&
&                 0.5_R8*(pl%na(icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti&
&                 (icv1)+pl%ti(icv2))
              END DO
              IF (0.0_R8 .LT. t0) THEN
                max5 = t0
              ELSE
                max5 = 0.0_R8
              END IF
              srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max5
              IF (0.0_R8 .GT. t0) THEN
                min4 = t0
              ELSE
                min4 = 0.0_R8
              END IF
              srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + min4/pl%ti(icv1)
            END IF
          ELSE
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) THEN
                vbnd = (dv%vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%&
&                 vaecrb(ifc, 1, is)*geo%fcqalf(ifc, 1))*mpg%bcfcor(mpg%&
&                 bccvp(ib, 1)+ibc-1)
                IF (wrk .GE. 0.) THEN
                  abs5 = wrk
                ELSE
                  abs5 = -wrk
                END IF
                x1 = csbc(icv1, is)*abs5
                y1 = vbc(icv1, is)*SIGN(1.0_R8, wrk) + vbnd
                IF (x1 .LT. y1) THEN
                  max6 = y1
                ELSE
                  max6 = x1
                END IF
                t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)*geo%fcs(ifc)&
&                 *max6
                IF (conpar(is, ib, 2) .GT. 0.0_R8) t1 = t1 + co%dna0(&
&                   icv1, is)/conpar(is, ib, 2)*pl%na(icv1, is)
              END IF
            END DO
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) - enipar(ib, 1)*t0 - &
&             switch%stab_coeff_sheath_ti*dv%ne(icv1)*cs*geo%fcs(ifc) - &
&             fac_he_anom_bc*enipar(ib, 2)*t1*geo%fcs(ifc)
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + switch%&
&             stab_coeff_sheath_ti*dv%ne(icv1)*cs*geo%fcs(ifc)*pl%ti(&
&             icv1)
          END IF
        ELSE
!wdk sheath transmission factor consistent with truncated
!    Maxwellian distribution on Eirene side (NEMODS=7)
!    See Eirene manual for details.
          DO is=0,ns-1
            IF (.NOT.is_neutral(is)) THEN
              arg13 = 2.0_R8*pl%ti(icv1)/(am(is)*mp)
              vt = SQRT(arg13)
              IF (geo%fcqalf(ifc, 0) .GE. 0.) THEN
                abs1 = geo%fcqalf(ifc, 0)
              ELSE
                abs1 = -geo%fcqalf(ifc, 0)
              END IF
              result10 = PIT(icv1)
              t3 = result10*abs1*cs/vt
              IF (geo%fcqalf(ifc, 1) .GE. 0.) THEN
                abs2 = geo%fcqalf(ifc, 1)
              ELSE
                abs2 = -geo%fcqalf(ifc, 1)
              END IF
!WG_TODO correct for drift contributions!
              result10 = PIT(icv1)
              arg12 = (result10*abs2*cs/vt)**2 + (geo%cvbb(icv1, 2)/geo%&
&               cvbb(icv1, 3)*cs/vt)**2
              t4 = SQRT(arg12)
!corrected for factor 3/2 in parallel convection
              result10 = SHEATH_G(t3)
              result20 = SHEATH_G(t3)
              dsh = 1.0_R8 + t3**2 + t4**2 + 0.5_R8*(result10-1.0_R8)/&
&               result20
              t0 = t0 + dsh*mompar(is, ib, 1)*pl%na(icv1, is)
              IF (conpar(is, ib, 2) .GT. 0.0_R8) t1 = t1 + &
&                 fac_he_anom_bc*enipar(ib, 2)*co%dna0(icv1, is)/conpar(&
&                 is, ib, 2)*pl%na(icv1, is)
              t2 = t2 + dv%fhm(ifc, 0, is) + dv%fhm(ifc, 1, is)
            END IF
          END DO
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs3 = geo%fcpbs(ifc)
          ELSE
            abs3 = -geo%fcpbs(ifc)
          END IF
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) - (1.0_R8+switch%&
&           stab_coeff_sheath_ti)*t0*cs*abs3 - t1*geo%fcs(ifc) + t2*mpg%&
&           bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs4 = geo%fcpbs(ifc)
          ELSE
            abs4 = -geo%fcpbs(ifc)
          END IF
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + switch%&
&           stab_coeff_sheath_ti*t0*cs*abs4
        END IF
        IF (switch%mdf_fhi .NE. 0) THEN
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhipsch(ifc, 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO is=0,ns-1
            t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs&
&             (ifc)*geo%fcqalf(ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             )
          END DO
          IF (0.0_R8 .LT. t0) THEN
            max7 = t0
          ELSE
            max7 = 0.0_R8
          END IF
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max7
          IF (0.0_R8 .GT. t0) THEN
            min5 = t0
          ELSE
            min5 = 0.0_R8
          END IF
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + min5/pl%ti(icv1)
        END IF
!wdk    Todo: corrections for BCCON.ne.14
!srv 01.02.09 }

      END DO
    CASE (16) 
!
! -- BCENI=16 -- Feedback boundary condition with constant temperature
!
!
      IF (switch%bceni_16_style .EQ. 0) THEN
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&         'ion temperature feedback by flux ', enipar(ib, 1), ' with ', &
&         enipar(ib, 2), ' on ', bcchar(ib), boundary_location(ib)
          CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        END IF
!       ..compute average temperature on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t0 = t0 + geo%fcs(ifc)*dv%ni(icv1, 0)
!wdk at the moment, totflux only contains ion/neutral heat flux;
!wdk bc_type16_kinetic_energy.eq.1 option not yet included
          t1 = t1 + geo%fcs(ifc)*dv%ni(icv1, 0)*pl%ti(icv1)
          totflux = totflux - (dv%fhi(ifc, 0)+dv%fhi(ifc, 1))*mpg%bcfcor&
&           (mpg%bccvp(ib, 1)+ibc-1)
        END DO
        t1 = t1/t0
        totpar = fac_he_anom_bc*enipar(ib, 1)
        IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
        IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
        IF (totflux .GE. 0.) THEN
          x2 = totflux
        ELSE
          x2 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          y2 = totpar
        ELSE
          y2 = -totpar
        END IF
        IF (x2 .LT. y2) THEN
          max8 = y2
        ELSE
          max8 = x2
        END IF
        t2 = (1.0_R8-t3*(totflux-totpar)/max8)*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&             'bceni=16: curr_flux, desired_flux, old/new temperature, '&
&                                        , totflux, totpar, t1/qe, t2/qe
!       ..impose temperature
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2
          srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE IF (switch%bceni_16_style .EQ. 1) THEN
!
!srv 16.02.12 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, *) 'BCENI = 16 (style = 1) : '//&
&         'Given integrated ion heat flux with constant Ti '
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location&
&             (ibw)
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCENI = 16 only applicable to core boundaries !')
              CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                   'faulty parameter enipar1')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               ((bceni(ibw) .EQ. 23 .OR. bceni(ibw) .EQ. 24) .OR. bceni&
&               (ibw) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
              CALL XERRAB(&
&                   'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!'&
&                  )
            END IF
          END DO
        END IF
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bceni) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              senipar = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bceni(ibw) .EQ. bceni(ib)) senipar = senipar +&
&                   enipar(ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCENI=16: Summed value is ', senipar
            tis = 0.0_R8
            nivs = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  tis = tis + pl%ti(icv)*dv%ni(icv, 0)*geo%cvvol(icv)
                  nivs = nivs + dv%ni(icv, 0)*geo%cvvol(icv)
                END DO
              END IF
            END DO
            tis = tis/nivs
            totflux = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  IF (switch%mdf_fhi .NE. 0) THEN
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhi_mdf(ifc, 0)+dv%fhi_mdf(ifc, 1))
                    DO is=0,ns-1
                      totflux = totflux - pl%ti(icv)*pl%na(icv, is)*geo%&
&                       fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv&
&                       %vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb&
&                       (ifc, 1, is)*geo%fcqalf(ifc, 1))
                    END DO
                  ELSE
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
                  END IF
                END DO
              END IF
            END DO
            IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
            IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
            IF (totflux .GE. 0.) THEN
              x3 = totflux
            ELSE
              x3 = -totflux
            END IF
            IF (x3 .LT. senipar) THEN
              max9 = senipar
            ELSE
              max9 = x3
            END IF
            tis = tis*(1.0_R8-t3*(totflux-senipar)/max9)
            WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&           totflux, ' SENIPAR=', senipar
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%shi0(icv, 0) = vbig*ne00*tis*geo%fcs(ifc)
                  srw%shi0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
                END DO
              END IF
            END DO
            once_bceni = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCENI=16, ONLY AVAILABLE FOR CORE!')
        END IF
      ELSE
        CALL XERRAB(' Incorrect style of boundary condition')
      END IF
    CASE (17) 
!
! -- BCENI=17 -- Feedback boundary condition with constant temperature
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 17 : ion temperature feedback by flux ', enipar(ib, 1)&
&       , ' with ', enipar(ib, 2), ' on ', bcchar(ib), boundary_location&
&       (ib)
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        CALL XERTST(enipar(ib, 2) .GT. 0, 'faulty parameter enipar2')
        CALL XERTST(bcene(ib) .EQ. bceni(ib), &
&             'both bcene and bceni should be set to 17')
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        CALL XERTST(enepar(ib, 2) .GT. 0, 'faulty parameter enepar2')
      END IF
      IF (.NOT.(bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A')) THEN
! already handled when the electron heat bc was handled
! see label 2980
        CALL XERRAB('B2STBC -- BCENI=17, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (18) 
!
! -- BCENI=18 -- FRACTIONAL DROP CONDITION (FOR EDGE2D COMPARISON)
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI = 18 : ion temperature fractional drop', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .LT. 1.0_R8, &
&             'BCENI = 18, ENIPAR(,1) => 1')
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t1 = (1.0_R8-enipar(ib, 1))*pl%ti(icv2)
        srw%shi0(icv1, 0) = vbig*ne00*t1*geo%fcs(ifc)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (19) 
!
! -- BCENI=19 -- PRESCRIBE THE DECAY LENGTH FOR THE ION TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENI = 19 not adapted for WG')
!
! -- BCENI=20 -- Feedback boundary condition with constant temperature
!
    CASE (20) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 20 : ion temperature feedback by flux (neo) ', enipar(&
&       ib, 1), ' with ', enipar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        tiave = 0.0_R8
        niave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fhi&
&           (ifc, 0)+dv%fhi(ifc, 1))
          t0 = t0 + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv1)
          weight = weight + dv%ni(icv1, 0)*geo%cvvol(icv1)
          tiave = tiave + pl%ti(icv2)*dv%ni(icv2, 0)*geo%cvvol(icv2)
          niave = niave + dv%ni(icv2, 0)*geo%cvvol(icv2)
        END DO
        t0 = t0/weight
        tiave = tiave/niave
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
        IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
        t1 = (1.0_R8-t3*(totflux-enipar(ib, 1))/enipar(ib, 1))*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New ion temp :', t0/qe, t1&
&                                        /qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1*pl%ti(icv2)/&
&           tiave
          srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENI=20, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (21) 
!
!! FIXME: Clash here with 5.0/5.1 BCENI=21 type
!xpb Careful here because of BC number clash
! From 5.0: starting at version 01.001.030
! -- BCCON=21 -- constant ion temperature scaled by ion temperature on the ring bc_type21_ref away
! has been moved up to next available number (BCENI=25)
!
! From 5.2, after version number 01.001.078:
! -- BCENI=21 -- from b2stbc_spb                                     !srv 01.02.09 {
!
      CALL XERRAB('b2stbc_phys -- BCENI = 21 not adapted for WG')
!
! -- BCENI=22 -- RADIAL LEAKAGE CONDITION FOR THE ION TEMPERATURE    !srv 23.07.10 {
!                SPECIFIES A TEMPERATURE GRADIENT SUCH THAT THE DIFFUSIVE
!                FLUX IS SET TO BE EQUIVALENT TO A LEAKAGE VELOCITY, IN
!                UNITS OF THE COLLECTIVE ION THERMAL VELOCITY
!
    CASE (22) 
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCENI = 22 : with ENIPAR(IB,1)= ', &
&                                   enipar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
!wdk    Notes:
!wdk     * need correction for misaligned grids -> t1
!wdk     * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = geo%fcqalf(ifc, 1)
        t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&         fcqbet(ifc, 0)
        t2 = 0.0_R8
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            arg13 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*&
&             mp)
            csb = SQRT(arg13)
            t2 = t2 + csb*pl%na(icv1, is)
          END IF
        END DO
        srw%shi0(icv1, 0) = vbig*ne00*ev*co%chci(ifc, 1)*(t0*pl%ti(icv2)&
&         -mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1*(pl%ti(mpg%fcvx(ifc, 2)&
&         )-pl%ti(mpg%fcvx(ifc, 1))))
        srw%shi0(icv1, 1) = -(vbig*ne00*ev*(co%chci(ifc, 1)*t0-enipar(ib&
&         , 1)*geo%fcs(ifc)*t2))
!srv 23.07.10 }
      END DO
    CASE (23) 
!
! -- BCENI=23 -- PRESCRIBE THE POLOIDALLY AVERAGED VALUE OF THE ION TEMPERATURE
! AND INTRODUCE A POLOIDAL VARIATION AS CLOSE AS POSSIBLE TO NEOCLASSICAL SOLUTION.
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 21,22,23
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7)') &
&       'BCENI = 23 : specified ion temperature ', enipar(ib, 1)
!          write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 23 only applicable to core boundaries !')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ib, 1) .EQ. &
&                 enipar(ibw, 1), &
&                 'BCENI = 23, inconsistent ENIPAR(,1) values!')
            IF (.NOT.((bccon(ismain, ib) .EQ. 21 .OR. bccon(ismain, ib) &
&               .EQ. 22) .OR. bccon(ismain, ib) .EQ. 23)) THEN
              WRITE(0, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=23'
              WRITE(*, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=23'
!srv 21.09.12
              WRITE(*, '(1x,a)') &
&             'Please ensure that this boundary condition '//&
&             'is consistent with '//&
&             'the ion density boundary condition'
            END IF
            IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&           THEN
              WRITE(0, *) &
&             'Use of BCENI=23 only meant for single-fluid runs!'
              WRITE(0, *) 'Use BCENI=26 instead!'
              WRITE(6, *) &
&             'Use of BCENI=23 only meant for single-fluid runs!'
              WRITE(6, *) 'Use BCENI=26 instead!'
            END IF
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 24) .OR. bceni(ibw&
&             ) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
        CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ibw, 1) .GT. &
&             0.0_R8, 'BCENI = 23, ENIPAR(,1) !> 0')
      END IF
!
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                    'Compile with -DASTRA option to couple with ASTRA!'&
&                                         )
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! Poloidally volume-averaged electron density in the cell next to boundary
          t2 = 0.0_R8
! Poloidally volume-averaged electron density in the boundary cell
          t3 = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                t2 = t2 + dv%ne(icv2)*geo%cvvol(icv2)
                t3 = t3 + dv%ne(icv1)*geo%cvvol(icv2)
              END DO
            END IF
          END DO
          t1 = t1/t0
          t2 = t2/t0
          t3 = t3/t0
          DO ibw=ib,nbc
!lk 12.12.12 }
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                IF (mpg%cvonclosedsurface(icv2)) THEN
                  srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + vbig*ne00*(&
&                   enipar(ibw, 1)*ev+(pl%ti(icv2)-t1)*t1*t2/t3/enipar(&
&                   ibw, 1)/ev)*geo%fcs(ifc)
                  srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
                END IF
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB(&
&              'B2STBC -- BCENI=23 IS AVAILABLE FOR CORE BOUNDARY ONLY.'&
&              )
        END IF
      END IF
    CASE (24) 
!
! -- BCENI=24 -- Feedback boundary condition with prescribed total ion heat flux,
!                constant poloidally averaged ion temperature and a
!                poloidal variation as close as possible to neoclassical solution.
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 21,22,23
!
!IYS 04.03.2013 {
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a)') 'BCENI = 24 : Given integrated ion heat flux', &
&       ' with constant Ti '
!          write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 24 only applicable to core boundaries !')
            CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                 'faulty parameter enipar1')
            IF (.NOT.((bccon(ismain, ib) .EQ. 21 .OR. bccon(ismain, ib) &
&               .EQ. 22) .OR. bccon(ismain, ib) .EQ. 23)) THEN
              WRITE(0, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=24'
              WRITE(*, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=24'
!srv 21.09.12
              WRITE(*, '(1x,a)') &
&             'Please ensure that this boundary condition '//&
&             'is consistent with '//&
&             'the ion density boundary condition'
            END IF
            IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&           THEN
              WRITE(0, *) &
&             'Use of BCENI=24 only meant for single-fluid runs!'
              WRITE(0, *) 'Use BCENI=27 instead!'
              WRITE(6, *) &
&             'Use of BCENI=24 only meant for single-fluid runs!'
              WRITE(6, *) 'Use BCENI=27 instead!'
            END IF
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
!srv 16.02.12 }
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) THEN
          CALL XERRAB(&
&               'Compile with -DASTRA option to couple with ASTRA!')
        ELSE
          senipar = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) senipar = senipar + enipar(&
&               ibw, 1)
          END DO
        END IF
        WRITE(*, *) 'BCENI=24: Summed value is ', senipar
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Poloidally density-averaged ion temperature in the boundary cell     !IYS 21.01.2016
          tis = 0.0_R8
          nivs = 0.0_R8
          totflux = 0.0_R8
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! Poloidally volume-averaged electron density in the cell next to boundary
          t2 = 0.0_R8
! Poloidally volume-averaged electron density in the boundary cell
          t3 = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                tis = tis + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv2)
                nivs = nivs + dv%ni(icv1, 0)*geo%cvvol(icv2)
                t2 = t2 + dv%ne(icv2)*geo%cvvol(icv2)
                t3 = t3 + dv%ne(icv1)*geo%cvvol(icv2)
                IF (switch%mdf_fhi .NE. 0) THEN
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi_mdf(ifc, 0)+dv%fhi_mdf(ifc, 1))
                  DO is=0,ns-1
                    totflux = totflux - pl%ti(icv1)*pl%na(icv1, is)*geo%&
&                     fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv%&
&                     vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&                     ifc, 1, is)*geo%fcqalf(ifc, 1))
                  END DO
                ELSE
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
                END IF
              END DO
            END IF
          END DO
          tis = tis/nivs
          t1 = t1/t0
          t2 = t2/t0
          t3 = t3/t0
          IF (enipar(ib, 2) .GT. 0.0_R8) t4 = enipar(ib, 2)
          IF (enipar(ib, 2) .LE. 0.0_R8) t4 = switch%b2stbc_bc_ref_ti
          IF (totflux .GE. 0.) THEN
            x4 = totflux
          ELSE
            x4 = -totflux
          END IF
          IF (x4 .LT. senipar) THEN
            max10 = senipar
          ELSE
            max10 = x4
          END IF
          tis = tis*(1.0_R8-t4*(totflux-senipar)/max10)
          WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&         totflux, ' SENIPAR=', senipar
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                srw%shi0(icv1, 0) = vbig*ne00*(tis+(pl%ti(icv2)-t1)*t1*&
&                 t2/t3/tis)*geo%fcs(ifc)
                srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB('B2STBC -- BCENI=24 IS AVAILABLE FOR CORE ONLY')
        END IF
      END IF
    CASE (25) 
!
! -- BCENI=25 -- constant ion temperature scaled by inner ring
! was BCENI=21 in 5.0/5.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 25 : fixed ion temperature '//&
&       '(modified by nearby ring) ', enipar(ib, 1), ' with ', enipar(ib&
&       , 2), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0.0_R8, &
&             'faulty parameter enipar1')
      END IF
      tiave = 0.0_R8
      niave = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        tiave = tiave + pl%ti(icv)*dv%ni(icv, 0)*geo%cvvol(icv)
        niave = niave + dv%ni(icv, 0)*geo%cvvol(icv)
      END DO
      tiave = tiave/niave
      IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
      IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = vbig*ne00*enipar(ib, 1)*ev*geo%fcs(ifc)*(&
&         1.0_R8-t3+t3*pl%ti(icv2)/tiave)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (26) 
!
! -- BCENI=26 -- PRESCRIBE THE POLOIDALLY AVERAGED VALUE OF THE ION TEMPERATURE
! AND INTRODUCE A POLOIDAL VARIATION IN A SIMPLIFIED MANNER.
! THIS BOUNDARY CONDITION IS SUITABLE FOR ANY PLASMA COMPOSITION (i.e. when BCENI=23 fails).
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 25,26,27
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7)') &
&       'BCENI = 26 : specified ion temperature ', enipar(ib, 1)
!         write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 26 only applicable to core boundaries !')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ibw, 1) .GT.&
&                 0.0_R8, 'BCENI = 26, ENIPAR(,1) !> 0')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ib, 1) .EQ. &
&                 enipar(ibw, 1), &
&                 'BCENI = 26, inconsistent ENIPAR(,1) values!')
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 24) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
!
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                    'Compile with -DASTRA option to couple with ASTRA!'&
&                                         )
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                t0 = t0 + geo%cvvol(icv)
                t1 = t1 + pl%ti(icv)*geo%cvvol(icv)
              END DO
            END IF
          END DO
          t1 = t1/t0
          DO ibw=ib,nbc
!lk 12.12.12 }
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                IF (mpg%cvonclosedsurface(icv2)) THEN
                  srw%shi0(icv1, 0) = vbig*ne00*(enipar(ibw, 1)*ev+(pl%&
&                   ti(icv2)-t1))*geo%fcs(ifc)
                  srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
                END IF
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB(&
&              'B2STBC -- BCENI=26 IS AVAILABLE FOR CORE BOUNDARY ONLY.'&
&              )
        END IF
      END IF
    CASE (27) 
!
! -- BCENI=27 -- Feedback boundary condition with prescribed total ion heat flux,
!                constant poloidally averaged ion temperature and a
!                poloidal variation in a simplified manner.
! THIS BOUNDARY CONDITION IS SUITABLE FOR ANY PLASMA COMPOSITION (i.e. when BCENI=24 fails).
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 25,26,27
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENI = 27 : Given integrated ion heat flux', &
&       ' with constant Ti '
!         write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
