          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 24) .OR. bceni(ibw) .EQ. 26)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
        IF (.NOT.once_bceni) THEN
          IF (switch%use_astra .NE. 0) THEN
            CALL XERRAB(&
&                 'Compile with -DASTRA option to couple with ASTRA!')
          ELSE
            senipar = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) senipar = senipar + enipar(&
&                 ibw, 1)
            END DO
          END IF
          WRITE(*, *) 'BCENI=27: Summed value is ', senipar
! Poloidally density-averaged ion temperature in the boundary cell
          tis = 0.0_R8
          nivs = 0.0_R8
! Volume                                      !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! IYS 22.03.2017
          totflux = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                tis = tis + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv2)
                nivs = nivs + dv%ni(icv1, 0)*geo%cvvol(icv2)
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                IF (switch%mdf_fhi .NE. 0) THEN
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi_mdf(ifc, 0)+dv%fhi_mdf(ifc, 1))
                  DO is=0,ns-1
                    totflux = totflux - pl%ti(icv1)*pl%na(icv1, is)*geo%&
&                     fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv%&
&                     vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&                     ifc, 1, is)*geo%fcqalf(ifc, 1))
                  END DO
                ELSE
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
                END IF
              END DO
            END IF
          END DO
          tis = tis/nivs
          t1 = t1/t0
          IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
          IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
          IF (totflux .GE. 0.) THEN
            x5 = totflux
          ELSE
            x5 = -totflux
          END IF
          IF (x5 .LT. senipar) THEN
            max11 = senipar
          ELSE
            max11 = x5
          END IF
          tis = tis*(1.0_R8-t3*(totflux-senipar)/max11)
          WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&         totflux, ' SENIPAR=', senipar
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                srw%shi0(icv1, 0) = vbig*ne00*(tis+(pl%ti(icv2)-t1))*geo&
&                 %fcs(ifc)
                srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bceni = .true.
        END IF
      ELSE
        CALL XERRAB('B2STBC -- BCENI=27 IS AVAILABLE FOR CORE ONLY')
      END IF
    CASE (28) 
!
! -- BCENI=28 -- Prescribe the value of the ion temperature, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENI=28 intended for core boundaries only!')
        END DO
        IF (switch%use_astra .NE. 0) enipar(ib, 1) = teb_astra*1.0e3_R8
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified ion temperature + perturbation', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 28, ENIPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%ti(icv2)
          END DO
        END IF
      END DO
      t1 = t1/t0
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%ti(icv2)+enipar(&
&         ib, 1)*ev-t1)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (29) 
!
! -- BCENI=29 -- Feedback on the total ion energy flux, by imposing a flux surface
!                averaged temperature, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENI=29 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified ion heat flux', enipar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 29, ENIPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bceni(ib0) .NE. 29) CALL XERRAB(&
&                                      'BCENI=29: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%ti(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%ti(icv2)
            totflux = totflux - (dv%fhi(ifc, 0)+dv%fhi(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
          END DO
          totpar = totpar + enipar(ib0, 1)
        END IF
      END DO
      totpar = fac_he_anom_bc*totpar
      t1 = t1/t0
      t2 = t2/t0
      IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
      IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
      IF (totflux .GE. 0.) THEN
        x6 = totflux
      ELSE
        x6 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y3 = totpar
      ELSE
        y3 = -totpar
      END IF
      IF (x6 .LT. y3) THEN
        max12 = y3
      ELSE
        max12 = x6
      END IF
      t4 = (1.0_R8-t3*(totflux-totpar)/max12)*t1
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%ti(icv2)+t4-t2)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bceni(ib)
      CALL XERRAB('BCENI out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENI

!  Differentiation of b2stbc_phys_pot_dv in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: scurpar scurpard prev_cur_delta
!                po_prev po_curr coeff_16 prev_cur_deltad cur_deltad
!                po_stepd po_prevd po_currd coeff_16d pos posd
!                *(srwd.sch0) *(srw.sch0) vbc csbc vbcd csbcd
!   with respect to varying inputs: mompar potpar potpard scurpar
!                scurpard prev_cur_delta po_prev po_curr coeff_16
!                prev_cur_deltad cur_deltad po_stepd po_prevd po_currd
!                coeff_16d pos posd *(srwd.sch0) *(dv.fch) *(dv.fchdia)
!                *(dv.fchin) *(dv.fchvispar) *(dv.fchvisper) *(dv.fchvisq)
!                *(dv.fchinert) *(dv.fchviskt) *(dv.ne) *(dv.vaecrb)
!                *(rtd.rza) *(rt.rza) *(dvd.fch) *(dvd.fchdia)
!                *(dvd.fchin) *(dvd.fchvispar) *(dvd.fchvisper)
!                *(dvd.fchvisq) *(dvd.fchinert) *(dvd.fchviskt)
!                *(dvd.ne) *(dvd.vaecrb) *(srw.sch0) *(cod.sig0)
!                *(co.sig0) *(pld.na) *(pld.ua) *(pld.po) *(pld.te)
!                *(pld.ti) *(pl.na) *(pl.ua) *(pl.po) *(pl.te)
!                *(pl.ti) pzd naua2averaged pzaveraged naua2average
!                vbc rzd rz csbc vbcd pzaverage csbcd pz
!   Plus diff mem management of: srwd.sch0:in dv.fch:in dv.fchdia:in
!                dv.fchin:in dv.fchvispar:in dv.fchvisper:in dv.fchvisq:in
!                dv.fchinert:in dv.fchviskt:in dv.ne:in dv.vaecrb:in
!                geo.vxvol:in rtd.rza:in rt.rza:in dvd.fch:in dvd.fchdia:in
!                dvd.fchin:in dvd.fchvispar:in dvd.fchvisper:in
!                dvd.fchvisq:in dvd.fchinert:in dvd.fchviskt:in
!                dvd.ne:in dvd.vaecrb:in srw.sch0:in cod.sig0:in
!                co.sig0:in pld.na:in pld.ua:in pld.po:in pld.te:in
!                pld.ti:in pl.na:in pl.ua:in pl.po:in pl.te:in
!                pl.ti:in
!  Differentiation of b2stbc_phys_pot in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: scurpar prev_cur_delta po_prev
!                po_curr coeff_16 pos *(srw.sch0) vbc csbc
!   with respect to varying inputs: mompar potpar scurpar prev_cur_delta
!                po_prev po_curr coeff_16 pos *(dv.fch) *(dv.fchdia)
!                *(dv.fchin) *(dv.fchvispar) *(dv.fchvisper) *(dv.fchvisq)
!                *(dv.fchinert) *(dv.fchviskt) *(dv.ne) *(dv.vaecrb)
!                *(rt.rza) *(srw.sch0) *(co.sig0) *(pl.na) *(pl.ua)
!                *(pl.po) *(pl.te) *(pl.ti) naua2average vbc rz
!                csbc pzaverage pz
!   Plus diff mem management of: dv.fch:in dv.fchdia:in dv.fchin:in
!                dv.fchvispar:in dv.fchvisper:in dv.fchvisq:in
!                dv.fchinert:in dv.fchviskt:in dv.ne:in dv.vaecrb:in
!                dv.facdrift:in mpg.bcfcor:in geo.vxvol:in rt.rza:in
!                srw.sch0:in co.sig0:in pl.na:in pl.ua:in pl.po:in
!                pl.te:in pl.ti:in
!
  SUBROUTINE B2STBC_PHYS_POT_DV_DV(ib, nbdirs, nbdirs0)
    USE B2MOD_DIFFSIZES
!  Hint: nbdirsmax0 should be the maximum number of differentiation directions
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: ib, ib0, ibc, ibc0, ibw, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, vte, vbnd, s1, fche, fchi, t0, t1, t2, t3, t4, &
&   neave, poave, totpar, totflux, wrk, seec, fchy_dia, fchy_inertia
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: csd0, vted0, vbndd0, fched0&
&   , fchid0, t0d0, t1d0, t2d0, t3d0, t4d0, neaved0, poaved0, totpard0, &
&   totfluxd0, fchy_diad0, fchy_inertiad0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd, vted, vbndd, fched, &
&   fchid, t0d, t1d, t2d, t3d, t4d, neaved, poaved, totpard, totfluxd, &
&   fchy_diad, fchy_inertiad
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: csdd, vtedd, &
&   vbnddd, fchedd, fchidd, t0dd, t1dd, t2dd, t3dd, t4dd, neavedd, &
&   poavedd, totpardd, totfluxdd, fchy_diadd, fchy_inertiadd
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    INTRINSIC MIN
    INTRINSIC MOD
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x1dd
    REAL(kind=r8) :: y1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: y1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y1dd
    REAL(kind=r8) :: y2
    REAL(kind=r8) :: x2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x2d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x2d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x2dd
    REAL(kind=r8) :: x3
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x3d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x3d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x3dd
    REAL(kind=r8) :: y3
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: y3d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y3d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y3dd
    REAL(kind=r8) :: x4
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x4d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x4d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x4dd
    REAL(kind=r8) :: y4
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: y4d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y4d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y4dd
    REAL(kind=r8) :: x5
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x5d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x5d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x5dd
    REAL(kind=r8) :: y5
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: y5d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y5d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y5dd
    REAL(r8) :: y6
    REAL(r8), DIMENSION(nbdirsmax0) :: y6d0
    REAL(r8), DIMENSION(nbdirsmax) :: y6d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: y6dd
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: max1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max1dd
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: max2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max2d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max2d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max2dd
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: max3
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max3d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max3d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max3dd
    REAL(kind=r8) :: max4
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max4d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max4d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max4dd
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: max5
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max5d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max5d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max5dd
    REAL(kind=r8) :: max6
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max6d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max6d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max6dd
    REAL(kind=r8) :: abs4
    REAL(r8) :: min1
    REAL(r8), DIMENSION(nbdirsmax0) :: min1d0
    REAL(r8), DIMENSION(nbdirsmax) :: min1d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: min1dd
    REAL(kind=r8) :: abs5
    REAL(r8) :: arg12
    REAL(r8), DIMENSION(nbdirsmax0) :: arg12d0
    REAL(r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg12dd
    REAL(kind=r8) :: arg13
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: result20d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result20d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: result20dd
    REAL(kind=r8) :: result11
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp1d
    REAL(kind=r8) :: temp2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp2d
    REAL(r8) :: temp3
    REAL(r8), DIMENSION(nbdirsmax0) :: temp3d
    INTEGER :: nbdirs
    INTRINSIC MAXVAL
    INTEGER :: nd0
    REAL(kind=r8) :: temp4
    REAL(r8) :: temp5
    REAL(kind=r8) :: temp6
    REAL(kind=r8) :: temp7
    INTEGER :: nbdirs0
!
! -- BOUNDARY CONDITIONS FOR POTENTIAL EQUATION --
!
    SELECT CASE  (bcpot(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCPOT=1 -- PRESCRIBE THE VALUE OF THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  1 : specified potential '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp = pbig*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = temp*potpardd(nd0, nd, ib, 1)
            srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%sch0(nd, icv1, 0) = temp*potpard(nd, ib, 1)
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = temp*potpard0(nd0, ib, 1)
          srwd0%sch0(nd0, icv1, 1) = 0.D0
        END DO
        srw%sch0(icv1, 0) = temp*potpar(ib, 1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCPOT=2 -- PRESCRIBE THE GRADIENT OF THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  2 : potential gradient ', &
&                                   potpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1dd = 0.D0
        CALL INTVERTEX_S_DV_DV(ivx1, ncv, nvx, mpg, geo%vxvol, pl%po, &
&                        pld0%po, pld%po, pldd%po, t1, t1d0, t1d, t1dd, &
&                        nbdirs, nbdirs0)
        t2dd = 0.D0
        CALL INTVERTEX_S_DV_DV(ivx2, ncv, nvx, mpg, geo%vxvol, pl%po, &
&                        pld0%po, pld%po, pldd%po, t2, t2d0, t2d, t2dd, &
&                        nbdirs, nbdirs0)
        temp = pbig*geo%fcs(ifc)
        temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
        temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, &
&         2))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          temp4 = temp0*geo%fcqgam(ifc, 0)
          DO nd0=1,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = temp*(temp4*potpardd(nd0, nd&
&             , ib, 1)-temp1*temp2*(t2dd(nd0, nd)-t1dd(nd0, nd))/geo%&
&             fcht(ifc)+pldd%po(nd0, nd, icv2))
            srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%sch0(nd, icv1, 0) = temp*(temp4*potpard(nd, ib, 1)-temp1*&
&           temp2*((t2d(nd)-t1d(nd))/geo%fcht(ifc))+pld%po(nd, icv2))
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = temp*(geo%fcqgam(ifc, 0)*temp0*&
&           potpard0(nd0, ib, 1)-temp1*temp2*(t2d0(nd0)-t1d0(nd0))/geo%&
&           fcht(ifc)+pld0%po(nd0, icv2))
          srwd0%sch0(nd0, icv1, 1) = 0.D0
        END DO
        srw%sch0(icv1, 0) = temp*(temp0*(geo%fcqgam(ifc, 0)*potpar(ib, 1&
&         ))-temp1*(temp2*((t2-t1)/geo%fcht(ifc)))+pl%po(icv2))
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCPOT=3 -- SHEATH CONDITIONS, ELECTRON ENERGY TRANSMISSION
!
      CALL XERRAB('b2stbc_phys -- BCPOT = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCPOT = 11')
!
! -- BCPOT=4 -- PRESCRIBE THE VALUE OF THE POTENTIAL,
!                 WEAKLY A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'BCPOT =  4 : weak potential ', &
&       potpar(ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(potpar(ib, 2) .GT. 0.0_R8, &
&             'BCPOT = 4, POTPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = geo%fcs(ifc)*(potpard(nd, ib&
&             , 2)*potpard0(nd0, ib, 1)+potpar(ib, 1)*potpardd(nd0, nd, &
&             ib, 2)+potpard(nd, ib, 1)*potpard0(nd0, ib, 2)+potpar(ib, &
&             2)*potpardd(nd0, nd, ib, 1))
            srwdd%sch0(nd0, nd, icv1, 1) = -(geo%fcs(ifc)*potpardd(nd0, &
&             nd, ib, 2))
          END DO
          srwd%sch0(nd, icv1, 0) = geo%fcs(ifc)*(potpar(ib, 1)*potpard(&
&           nd, ib, 2)+potpar(ib, 2)*potpard(nd, ib, 1))
          srwd%sch0(nd, icv1, 1) = -(geo%fcs(ifc)*potpard(nd, ib, 2))
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = geo%fcs(ifc)*(potpar(ib, 1)*&
&           potpard0(nd0, ib, 2)+potpar(ib, 2)*potpard0(nd0, ib, 1))
          srwd0%sch0(nd0, icv1, 1) = -(geo%fcs(ifc)*potpard0(nd0, ib, 2)&
&           )
        END DO
        srw%sch0(icv1, 0) = potpar(ib, 2)*geo%fcs(ifc)*potpar(ib, 1)
        srw%sch0(icv1, 1) = -(potpar(ib, 2)*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCPOT=5 -- PRESCRIBE THE CURRENT FLUX DENSITY PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCPOT =  5 : current flux density per area '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv, 0) = geo%fcs(ifc)*potpardd(nd0, nd&
&             , ib, 1)
            srwdd%sch0(nd0, nd, icv, 1) = 0.D0
          END DO
          srwd%sch0(nd, icv, 0) = geo%fcs(ifc)*potpard(nd, ib, 1)
          srwd%sch0(nd, icv, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv, 0) = geo%fcs(ifc)*potpard0(nd0, ib, 1)
          srwd0%sch0(nd0, icv, 1) = 0.D0
        END DO
        srw%sch0(icv, 0) = potpar(ib, 1)*geo%fcs(ifc)
        srw%sch0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCPOT=6 -- PRESCRIBE THE TOTAL CURRENT FLUX DENSITY FOR A
!                 CONSTANT POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                             'BCPOT =  6 : total current flux density '&
&                                   , potpar(ib, 1), &
&                                   ' with const potential on ', bcchar(&
&                                   ib), boundary_location(ib)
      CALL XERRAB('B2STBC -- BCPOT=6, NOT YET AVAILABLE')
!
! -- BCPOT=7 -- PRESCRIBE THE GIVEN PROFILE OF POTENTIAL
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') 'BCPOT = 7 : specified potential on ', bcchar(&
&       ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = 0.D0
            srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%sch0(nd, icv1, 0) = 0.d0
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = 0.D0
          srwd0%sch0(nd0, icv1, 1) = 0.D0
        END DO
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*bv_po(icv1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCPOT=8 -- PRESCRIBE THE TOTAL ELECTRON CURRENT WITH CONSTANT
!                 FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  8 : total current ', &
&                                   potpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = geo%fcs(ifc)*potpardd(nd0, nd&
&             , ib, 1)/us
            srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%sch0(nd, icv1, 0) = geo%fcs(ifc)*potpard(nd, ib, 1)/us
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = geo%fcs(ifc)*potpard0(nd0, ib, 1)/&
&           us
          srwd0%sch0(nd0, icv1, 1) = 0.D0
        END DO
        srw%sch0(icv1, 0) = potpar(ib, 1)/us*geo%fcs(ifc)
        srw%sch0(icv1, 1) = 0.0_R8
      END DO
    CASE (9) 
!
! -- BCPOT=9 -- PRESCRIBE THE DECAY LENGTH FOR
!                 THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT =  9 : potential decay length ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(potpar(ib, 1) .NE. 0.0_R8, &
&             'BCPOT = 9, POTPAR(,1) = 0')
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        temp2 = qe*potpar(ib, 1)
        temp1 = temp2*dv%ne(icv)
        temp5 = co%sig0(ifc)/temp1
        DO nd0=1,nbdirs0
          temp2d(nd0) = qe*potpard0(nd0, ib, 1)
          temp1d(nd0) = dv%ne(icv)*temp2d(nd0) + temp2*dvd0%ne(nd0, icv)
          temp3d(nd0) = (cod0%sig0(nd0, ifc)-temp5*temp1d(nd0))/temp1
        END DO
        temp3 = temp5
        DO nd=1,nbdirs
          temp4 = qe*dv%ne(icv)*potpard(nd, ib, 1) + temp2*dvd%ne(nd, &
&           icv)
          temp5 = (cod%sig0(nd, ifc)-temp3*temp4)/temp1
          DO nd0=1,nbdirs0
            srwdd%sch0(nd0, nd, icv, 0) = 0.D0
            srwdd%sch0(nd0, nd, icv, 1) = -(geo%fcs(ifc)*(codd%sig0(nd0&
&             , nd, ifc)-temp4*temp3d(nd0)-temp3*(qe*(potpard(nd, ib, 1)&
&             *dvd0%ne(nd0, icv)+dv%ne(icv)*potpardd(nd0, nd, ib, 1))+&
&             dvd%ne(nd, icv)*temp2d(nd0)+temp2*dvdd%ne(nd0, nd, icv))-&
&             temp5*temp1d(nd0))/temp1)
          END DO
          srwd%sch0(nd, icv, 0) = 0.d0
          srwd%sch0(nd, icv, 1) = -(geo%fcs(ifc)*temp5)
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv, 0) = 0.D0
          srwd0%sch0(nd0, icv, 1) = -(geo%fcs(ifc)*temp3d(nd0))
        END DO
        srw%sch0(icv, 0) = 0.0_R8
        srw%sch0(icv, 1) = -(geo%fcs(ifc)*temp3)
      END DO
    CASE (10) 
!
! -- BCPOT=10 -- Feedback option for core
!                NOT YET TESTED!!!!!!!!!
!
      CALL XERRAB('b2stbc_phys -- BCPOT = 10 not adapted for WG')
!
! -- BCPOT=11 -- SHEATH CONDITION, CURRENT CONTINUITY                !srv 01.02.09 {
!
    CASE (11) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCPOT = 11 : sheath potential current continuity bc', &
&       ' with POTPAR(IB,2) =', potpar(ib, 2), ' gammae =', gammae, &
&       ' on ', bcchar(ib), boundary_location(ib)
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) CALL XERTST(bccon(is, ib) .EQ. 14, &
&                                        'When BCPOT=11, '//&
&                          'one must have BCCON=14 for all ion species!'&
&                                       )
        END DO
      END IF
!srv 15.02.26
      conv_bcpot11 = .true.
!srv 15.02.26
      mrs = 0.0_R8
      y1dd = 0.D0
      csdd = 0.D0
      vbnddd = 0.D0
      fchedd = 0.D0
      x1dd = 0.D0
      vtedd = 0.D0
      fchidd = 0.D0
      max1dd = 0.D0
      y6dd = 0.D0
      arg12dd = 0.D0
      t0dd = 0.D0
      result20dd = 0.D0
      min1dd = 0.D0
      max2dd = 0.D0
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
!srv 15.02.26 {
        DO is=0,ns-1
          CALL CSBC_IS_DV_DV(icv1, ib, is, cs, csd0, csd, csdd, nbdirs, &
&                      nbdirs0)
          CALL VBC_IS_DV_DV(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is)&
&                     , csbcd0(:, icv1, is), csbcd(:, icv1, is), csbcdd(&
&                     :, :, icv1, is), wrk, nbdirs, nbdirs0)
!srv 15.02.26 }
        END DO
        arg12 = pl%te(icv1)/me
        temp5 = SQRT(arg12)
        DO nd0=1,nbdirs0
          arg12d0(nd0) = pld0%te(nd0, icv1)/me
          IF (arg12 .EQ. 0.D0) THEN
            temp3d(nd0) = 0.D0
          ELSE
            temp3d(nd0) = arg12d0(nd0)/(2.0*temp5)
          END IF
        END DO
        temp3 = temp5
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            arg12dd(nd0, nd) = pldd%te(nd0, nd, icv1)/me
          END DO
          arg12d(nd) = pld%te(nd, icv1)/me
          IF (arg12 .EQ. 0.d0) THEN
            DO nd0=1,nbdirs0
              vtedd(nd0, nd) = 0.D0
            END DO
            vted(nd) = 0.d0
          ELSE
            temp5 = arg12d(nd)/(2.0*temp3)
            DO nd0=1,nbdirs0
              vtedd(nd0, nd) = (arg12dd(nd0, nd)-temp5*2.0*temp3d(nd0))/&
&               (2.0*temp3)
            END DO
            vted(nd) = temp5
          END IF
        END DO
        DO nd0=1,nbdirs0
          vted0(nd0) = temp3d(nd0)
        END DO
        vte = temp3
        t0 = 0.0_R8
        wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
        IF (wrk .GE. 0.) THEN
          abs0 = wrk
        ELSE
          abs0 = -wrk
        END IF
        IF (abs0 .LT. geo%qalfmin) THEN
          t1dd = 0.D0
          CALL INTVERTEX_S_DV_DV(ivx1, ncv, nvx, mpg, geo%vxvol, pl%po, &
&                          pld0%po, pld%po, pldd%po, t1, t1d0, t1d, t1dd&
&                          , nbdirs, nbdirs0)
          t2dd = 0.D0
          CALL INTVERTEX_S_DV_DV(ivx2, ncv, nvx, mpg, geo%vxvol, pl%po, &
&                          pld0%po, pld%po, pldd%po, t2, t2d0, t2d, t2dd&
&                          , nbdirs, nbdirs0)
          temp2 = pbig*geo%fcs(ifc)
          temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc&
&           , 2))
          temp0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%sch0(nd0, nd, icv1, 0) = temp2*(pldd%po(nd0, nd, &
&               icv2)-temp1*temp0*(t2dd(nd0, nd)-t1dd(nd0, nd))/geo%fcht&
&               (ifc))
              srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
            END DO
            srwd%sch0(nd, icv1, 0) = temp2*(pld%po(nd, icv2)-temp1*temp0&
&             *(t2d(nd)-t1d(nd))/geo%fcht(ifc))
            srwd%sch0(nd, icv1, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%sch0(nd0, icv1, 0) = temp2*(pld0%po(nd0, icv2)-temp1*&
&             temp0*(t2d0(nd0)-t1d0(nd0))/geo%fcht(ifc))
            srwd0%sch0(nd0, icv1, 1) = 0.D0
          END DO
          srw%sch0(icv1, 0) = temp2*(pl%po(icv2)-temp1*(temp0*((t2-t1)/&
&           geo%fcht(ifc))))
          srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
        ELSE
          s1 = geo%fcs(ifc)
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              t0dd(nd0, nd) = 0.D0
            END DO
            t0d(nd) = 0.d0
          END DO
          t0d0 = 0.D0
          DO is=0,ns-1
            IF (.NOT.is_neutral(is)) THEN
              temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  vbnddd(nd0, nd) = temp2*(geo%fcqalf(ifc, 0)*dvdd%&
&                   vaecrb(nd0, nd, ifc, 0, is)+geo%fcqalf(ifc, 1)*dvdd%&
&                   vaecrb(nd0, nd, ifc, 1, is))
                END DO
                vbndd(nd) = temp2*(geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, ifc&
&                 , 0, is)+geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc, 1, is)&
&                 )
              END DO
              DO nd0=1,nbdirs0
                vbndd0(nd0) = temp2*(geo%fcqalf(ifc, 0)*dvd0%vaecrb(nd0&
&                 , ifc, 0, is)+geo%fcqalf(ifc, 1)*dvd0%vaecrb(nd0, ifc&
&                 , 1, is))
              END DO
              vbnd = temp2*(geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo&
&               %fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))
              IF (wrk .GE. 0.) THEN
                abs4 = wrk
              ELSE
                abs4 = -wrk
              END IF
              temp3 = SIGN(1.0_R8, wrk)
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  x1dd(nd0, nd) = abs4*csbcdd(nd0, nd, icv1, is)
                  y1dd(nd0, nd) = temp3*vbcdd(nd0, nd, icv1, is) + &
&                   vbnddd(nd0, nd)
                END DO
                x1d(nd) = abs4*csbcd(nd, icv1, is)
                y1d(nd) = temp3*vbcd(nd, icv1, is) + vbndd(nd)
              END DO
              DO nd0=1,nbdirs0
                x1d0(nd0) = abs4*csbcd0(nd0, icv1, is)
                y1d0(nd0) = temp3*vbcd0(nd0, icv1, is) + vbndd0(nd0)
              END DO
              x1 = csbc(icv1, is)*abs4
              y1 = temp3*vbc(icv1, is) + vbnd
              IF (x1 .LT. y1) THEN
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max1dd(nd0, nd) = y1dd(nd0, nd)
                  END DO
                  max1d(nd) = y1d(nd)
                END DO
                DO nd0=1,nbdirs0
                  max1d0(nd0) = y1d0(nd0)
                END DO
                max1 = y1
              ELSE
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    max1dd(nd0, nd) = x1dd(nd0, nd)
                  END DO
                  max1d(nd) = x1d(nd)
                END DO
                DO nd0=1,nbdirs0
                  max1d0(nd0) = x1d0(nd0)
                END DO
                max1 = x1
              END IF
              DO nd0=1,nbdirs0
                temp2d(nd0) = pl%na(icv1, is)*mompard0(nd0, is, ib, 1) +&
&                 mompar(is, ib, 1)*pld0%na(nd0, icv1, is)
                temp3d(nd0) = max1*rtd0%rza(nd0, icv1, is) + rt%rza(icv1&
&                 , is)*max1d0(nd0)
              END DO
              temp2 = mompar(is, ib, 1)*pl%na(icv1, is)
              temp3 = rt%rza(icv1, is)*max1
              DO nd=1,nbdirs
                temp4 = max1*rtd%rza(nd, icv1, is) + rt%rza(icv1, is)*&
&                 max1d(nd)
                temp6 = mompard(nd, is, ib, 1)*pl%na(icv1, is) + mompar(&
&                 is, ib, 1)*pld%na(nd, icv1, is)
                DO nd0=1,nbdirs0
                  t0dd(nd0, nd) = t0dd(nd0, nd) + s1*(temp4*temp2d(nd0)+&
&                   temp2*(rtd%rza(nd, icv1, is)*max1d0(nd0)+max1*rtdd%&
&                   rza(nd0, nd, icv1, is)+max1d(nd)*rtd0%rza(nd0, icv1&
&                   , is)+rt%rza(icv1, is)*max1dd(nd0, nd))+temp6*temp3d&
&                   (nd0)+temp3*(mompard(nd, is, ib, 1)*pld0%na(nd0, &
&                   icv1, is)+pld%na(nd, icv1, is)*mompard0(nd0, is, ib&
&                   , 1)+mompar(is, ib, 1)*pldd%na(nd0, nd, icv1, is)))
                END DO
                t0d(nd) = t0d(nd) + s1*(temp2*temp4+temp3*temp6)
              END DO
              DO nd0=1,nbdirs0
                t0d0(nd0) = t0d0(nd0) + s1*(temp2*temp3d(nd0)+temp3*&
&                 temp2d(nd0))
              END DO
              t0 = t0 + s1*(temp3*temp2)
            END IF
          END DO
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              fchidd(nd0, nd) = qe*t0dd(nd0, nd)
            END DO
            fchid(nd) = qe*t0d(nd)
          END DO
          DO nd0=1,nbdirs0
            fchid0(nd0) = qe*t0d0(nd0)
          END DO
          fchi = qe*t0
          IF (wrk .GE. 0.) THEN
            abs1 = wrk
          ELSE
            abs1 = -wrk
          END IF
          IF (-50.0_R8 .LT. -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)&
&             )) THEN
            temp5 = (pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)
            DO nd0=1,nbdirs0
              temp3d(nd0) = (pld0%po(nd0, icv1)-potpard0(nd0, ib, 2)-&
&               temp5*pld0%te(nd0, icv1))/pl%te(icv1)
            END DO
            temp3 = temp5
            DO nd=1,nbdirs
              temp5 = (pld%po(nd, icv1)-potpard(nd, ib, 2)-temp3*pld%te(&
&               nd, icv1))/pl%te(icv1)
              DO nd0=1,nbdirs0
                y6dd(nd0, nd) = -(qe*(pldd%po(nd0, nd, icv1)-potpardd(&
&                 nd0, nd, ib, 2)-pld%te(nd, icv1)*temp3d(nd0)-temp3*&
&                 pldd%te(nd0, nd, icv1)-temp5*pld0%te(nd0, icv1))/pl%te&
&                 (icv1))
              END DO
              y6d(nd) = -(qe*temp5)
            END DO
            DO nd0=1,nbdirs0
              y6d0(nd0) = -(qe*temp3d(nd0))
            END DO
            y6 = -(qe*temp3)
          ELSE
            y6 = -50.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                y6dd(nd0, nd) = 0.D0
              END DO
              y6d(nd) = 0.d0
            END DO
            y6d0 = 0.D0
          END IF
          IF (0.0_R8 .GT. y6) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                min1dd(nd0, nd) = y6dd(nd0, nd)
              END DO
              min1d(nd) = y6d(nd)
            END DO
            DO nd0=1,nbdirs0
              min1d0(nd0) = y6d0(nd0)
            END DO
            min1 = y6
          ELSE
            min1 = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                min1dd(nd0, nd) = 0.D0
              END DO
              min1d(nd) = 0.d0
            END DO
            min1d0 = 0.D0
          END IF
!lkw 31.03.2023
          arg13 = 1/(2*pi)
          result10 = SQRT(arg13)
          CALL EXPU2_DV_DV(min1, min1d0, min1d, min1dd, result20, &
&                    result20d0, result20d, result20dd, nbdirs, nbdirs0)
          temp2 = result10*qe*s1*abs1
          DO nd=1,nbdirs
            temp6 = result20*vted(nd) + vte*result20d(nd)
            DO nd0=1,nbdirs0
              fchedd(nd0, nd) = temp2*(dvd%ne(nd, icv1)*(result20*vted0(&
&               nd0)+vte*result20d0(nd0))+vte*result20*dvdd%ne(nd0, nd, &
&               icv1)+temp6*dvd0%ne(nd0, icv1)+dv%ne(icv1)*(vted(nd)*&
&               result20d0(nd0)+result20*vtedd(nd0, nd)+result20d(nd)*&
&               vted0(nd0)+vte*result20dd(nd0, nd)))
            END DO
            fched(nd) = temp2*(vte*result20*dvd%ne(nd, icv1)+dv%ne(icv1)&
&             *temp6)
          END DO
          DO nd0=1,nbdirs0
            fched0(nd0) = temp2*(vte*result20*dvd0%ne(nd0, icv1)+dv%ne(&
&             icv1)*(result20*vted0(nd0)+vte*result20d0(nd0)))
          END DO
          fche = temp2*(dv%ne(icv1)*(vte*result20))
          seec = gammae
          IF (fchi .LT. (1.0_R8-seec)*fche) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max2dd(nd0, nd) = (1.0_R8-seec)*fchedd(nd0, nd)
              END DO
              max2d(nd) = (1.0_R8-seec)*fched(nd)
            END DO
            DO nd0=1,nbdirs0
              max2d0(nd0) = (1.0_R8-seec)*fched0(nd0)
            END DO
            max2 = (1.0_R8-seec)*fche
          ELSE
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max2dd(nd0, nd) = fchidd(nd0, nd)
              END DO
              max2d(nd) = fchid(nd)
            END DO
            DO nd0=1,nbdirs0
              max2d0(nd0) = fchid0(nd0)
            END DO
            max2 = fchi
          END IF
          temp6 = max2/pl%te(icv1)
          DO nd0=1,nbdirs0
            temp2d(nd0) = (max2d0(nd0)-temp6*pld0%te(nd0, icv1))/pl%te(&
&             icv1)
            t0d0(nd0) = qe*temp2d(nd0)
          END DO
          temp2 = temp6
          t0 = qe*temp2
          DO nd=1,nbdirs
            temp6 = (max2d(nd)-temp2*pld%te(nd, icv1))/pl%te(icv1)
            t0d(nd) = qe*temp6
            DO nd0=1,nbdirs0
              t0dd(nd0, nd) = qe*(max2dd(nd0, nd)-pld%te(nd, icv1)*&
&               temp2d(nd0)-temp2*pldd%te(nd0, nd, icv1)-temp6*pld0%te(&
&               nd0, icv1))/pl%te(icv1)
!    ..compute charge source
              srwdd%sch0(nd0, nd, icv1, 0) = (1.0_R8-seec)*fchedd(nd0, &
&               nd) - fchidd(nd0, nd) + t0d(nd)*pld0%po(nd0, icv1) + pl%&
&               po(icv1)*t0dd(nd0, nd) + pld%po(nd, icv1)*t0d0(nd0) + t0&
&               *pldd%po(nd0, nd, icv1)
              srwdd%sch0(nd0, nd, icv1, 1) = -t0dd(nd0, nd)
            END DO
            srwd%sch0(nd, icv1, 0) = (1.0_R8-seec)*fched(nd) - fchid(nd)&
&             + pl%po(icv1)*t0d(nd) + t0*pld%po(nd, icv1)
            srwd%sch0(nd, icv1, 1) = -t0d(nd)
          END DO
          DO nd0=1,nbdirs0
            srwd0%sch0(nd0, icv1, 0) = (1.0_R8-seec)*fched0(nd0) - &
&             fchid0(nd0) + pl%po(icv1)*t0d0(nd0) + t0*pld0%po(nd0, icv1&
&             )
            srwd0%sch0(nd0, icv1, 1) = -t0d0(nd0)
          END DO
          srw%sch0(icv1, 0) = (1.0_R8-seec)*fche - fchi + t0*pl%po(icv1)
          srw%sch0(icv1, 1) = -t0
!    ..compute the maximum difference between the left and right sides of the boundary condition
!srv 15.02.26 {
          fch_sch = srw%sch0(icv1, 0) + srw%sch0(icv1, 1)*pl%po(icv1)
          fch_bnd = dv%fch(ifc, 0) + dv%fch(ifc, 1)
          IF (mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1) .GT. 0.0_R8) fch_bnd = &
&             -fch_bnd
          res_bcpot11 = fch_sch - fch_bnd
          IF (res_bcpot11 .GE. 0.) THEN
            abs2 = res_bcpot11
          ELSE
            abs2 = -res_bcpot11
          END IF
          IF (fch_bnd .GE. 0.) THEN
            abs5 = fch_bnd
          ELSE
            abs5 = -fch_bnd
          END IF
          IF (abs2 .GE. abs5*switch%bcpot11_epsr + switch%bcpot11_epsa) &
&           conv_bcpot11 = .false.
          IF (res_bcpot11 .GE. 0.) THEN
            y2 = res_bcpot11
          ELSE
            y2 = -res_bcpot11
          END IF
          IF (mrs .LT. y2) THEN
            mrs = y2
          ELSE
            mrs = mrs
          END IF
        END IF
!wdk Todo: seecmodel
        wrong_flow = .false.
      END DO
    CASE (12) 
!
! -- BCPOT=12 -- Test condition for south core region ! Solovyev 07.04.14   !srv 03.03.15 {
! code here is a part of code from 50000 for istyle_cur_contr_on_S_and_N.eq.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,a)') 'BCPOT = 12 : Adding contributions ', &
&       'from diamagnetic and inertial currents ', 'on ', bcchar(ib), &
&       boundary_location(ib)
        IF (switch%istyle_cur_contr_on_s_and_n .EQ. 0 .OR. switch%&
&           istyle_cur_contr_on_s_and_n .EQ. 1) THEN
          WRITE(*, *) ' BCPOT=12 cannot be used when ', &
&         'istyle_cur_contr_on_S_and_N = 0 or 1'
          CALL XERRAB('faulty parameter istyle_cur_contr_on_S_and_N !')
        ELSE
          DO ibc=1,mpg%bccvp(ib, 2)
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL XERTST(mpg%cvonclosedsurface(icv1), &
&                 'BCPOT=12 intended for core boundaries only!')
          END DO
        END IF
      END IF
      result11 = MAXVAL(dv%facdrift)
      IF (result11 .NE. 0.0_R8) THEN
!       ..compute the source
        IF (bcpot_12_style .EQ. -1) THEN
          fchy_diadd = 0.D0
          fchy_inertiadd = 0.D0
!wdk with <fcBb(:,2)>
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = switch%b2stbc_phm0*bzaverage*geo%fcqalf(ifc, 1)*&
&             gonedbsq(ifc, 0)*geo%fcs(ifc)
            temp1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                fchy_diadd(nd0, nd) = -(temp2*temp1*dv%facdrift(ifc)*&
&                 pzaveragedd(nd0, nd))
                srwdd%sch0(nd0, nd, icv1, 0) = srwdd%sch0(nd0, nd, icv1&
&                 , 0) - fchy_diadd(nd0, nd)
              END DO
              fchy_diad(nd) = -(temp2*temp1*dv%facdrift(ifc)*pzaveraged(&
&               nd))
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_diad(nd)
            END DO
            DO nd0=1,nbdirs0
              fchy_diad0(nd0) = -(temp1*temp2*dv%facdrift(ifc)*&
&               pzaveraged0(nd0))
              srwd0%sch0(nd0, icv1, 0) = srwd0%sch0(nd0, icv1, 0) - &
&               fchy_diad0(nd0)
            END DO
            fchy_dia = -(temp1*(dv%facdrift(ifc)*pzaverage)*temp2)
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            fchy_inertia = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                fchy_inertiadd(nd0, nd) = 0.D0
              END DO
              fchy_inertiad(nd) = 0.d0
            END DO
            fchy_inertiad0 = 0.D0
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) THEN
                temp2 = 0.5_R8*switch%b2stbc_phm1*geo%fcs(ifc)*dv%&
&                 facdrift(ifc)*gonedbsq(ifc, 0)
                temp1 = mp*bzaverage*geo%fcqalf(ifc, 1)
                temp0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    fchy_inertiadd(nd0, nd) = fchy_inertiadd(nd0, nd) - &
&                     temp0*am(is)*temp2*temp1*naua2averagedd(nd0, nd, &
&                     is)
                  END DO
                  fchy_inertiad(nd) = fchy_inertiad(nd) - temp2*temp1*&
&                   temp0*am(is)*naua2averaged(nd, is)
                END DO
                DO nd0=1,nbdirs0
                  fchy_inertiad0(nd0) = fchy_inertiad0(nd0) - am(is)*&
&                   temp2*temp0*temp1*naua2averaged0(nd0, is)
                END DO
                fchy_inertia = fchy_inertia - temp0*(am(is)*naua2average&
&                 (is))*temp1*temp2
              END IF
            END DO
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%sch0(nd0, nd, icv1, 0) = srwdd%sch0(nd0, nd, icv1&
&                 , 0) - fchy_inertiadd(nd0, nd)
              END DO
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_inertiad(nd)
            END DO
            DO nd0=1,nbdirs0
              srwd0%sch0(nd0, icv1, 0) = srwd0%sch0(nd0, icv1, 0) - &
&               fchy_inertiad0(nd0)
            END DO
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 0) THEN
          fchy_diadd = 0.D0
          fchy_inertiadd = 0.D0
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
!wdk now uses fcBb(iFc,2) instead of <fcBb(:,2)>
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%facdrift(ifc)*&
&             gonedbsq(ifc, 0)
            temp1 = geo%fcbb(ifc, 2)*geo%fcs(ifc)
            DO nd=1,nbdirs
              temp6 = temp2*temp1*geo%fcqalf(ifc, 1)
              DO nd0=1,nbdirs0
                fchy_diadd(nd0, nd) = -(temp6*switch%b2stbc_phm0*&
&                 pzaveragedd(nd0, nd))
                srwdd%sch0(nd0, nd, icv1, 0) = srwdd%sch0(nd0, nd, icv1&
&                 , 0) - fchy_diadd(nd0, nd)
              END DO
              fchy_diad(nd) = -(temp6*(switch%b2stbc_phm0*pzaveraged(nd)&
&               ))
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_diad(nd)
            END DO
            temp6 = temp2*temp1*geo%fcqalf(ifc, 1)
            DO nd0=1,nbdirs0
              fchy_diad0(nd0) = -(temp6*switch%b2stbc_phm0*pzaveraged0(&
&               nd0))
              srwd0%sch0(nd0, icv1, 0) = srwd0%sch0(nd0, icv1, 0) - &
&               fchy_diad0(nd0)
            END DO
            fchy_dia = -(temp6*(switch%b2stbc_phm0*pzaverage))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            fchy_inertia = 0.0_R8
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                fchy_inertiadd(nd0, nd) = 0.D0
              END DO
              fchy_inertiad(nd) = 0.d0
            END DO
            fchy_inertiad0 = 0.D0
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) THEN
                temp2 = 0.5_R8*switch%b2stbc_phm1*geo%fcbb(ifc, 2)*&
&                 gonedbsq(ifc, 0)*geo%fcs(ifc)
                temp1 = am(is)*mp*geo%fcqalf(ifc, 1)
                temp0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
                DO nd=1,nbdirs
                  temp6 = temp0*dv%facdrift(ifc)
                  DO nd0=1,nbdirs0
                    fchy_inertiadd(nd0, nd) = fchy_inertiadd(nd0, nd) - &
&                     temp6*temp2*temp1*naua2averagedd(nd0, nd, is)
                  END DO
                  fchy_inertiad(nd) = fchy_inertiad(nd) - temp2*temp1*&
&                   naua2averaged(nd, is)*temp6
                END DO
                temp6 = temp1*temp0*dv%facdrift(ifc)
                DO nd0=1,nbdirs0
                  fchy_inertiad0(nd0) = fchy_inertiad0(nd0) - temp6*&
&                   temp2*naua2averaged0(nd0, is)
                END DO
                fchy_inertia = fchy_inertia - temp6*(temp2*naua2average(&
&                 is))
              END IF
            END DO
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%sch0(nd0, nd, icv1, 0) = srwdd%sch0(nd0, nd, icv1&
&                 , 0) - fchy_inertiadd(nd0, nd)
              END DO
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_inertiad(nd)
            END DO
            DO nd0=1,nbdirs0
              srwd0%sch0(nd0, icv1, 0) = srwd0%sch0(nd0, icv1, 0) - &
&               fchy_inertiad0(nd0)
            END DO
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 1) THEN
          fchy_diadd = 0.D0
          fchy_inertiadd = 0.D0
!wdk experimental - use fchdia / fchinert as computed
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
!wdk now uses fcBb(iFc,2) instead of <fcBb(:,2)>
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                fchy_diadd(nd0, nd) = temp2*(dvdd%fchdia(nd0, nd, ifc, 0&
&                 )+dvdd%fchdia(nd0, nd, ifc, 1))
                srwdd%sch0(nd0, nd, icv1, 0) = srwdd%sch0(nd0, nd, icv1&
&                 , 0) - fchy_diadd(nd0, nd)
              END DO
              fchy_diad(nd) = temp2*(dvd%fchdia(nd, ifc, 0)+dvd%fchdia(&
&               nd, ifc, 1))
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_diad(nd)
            END DO
            DO nd0=1,nbdirs0
              fchy_diad0(nd0) = temp2*(dvd0%fchdia(nd0, ifc, 0)+dvd0%&
&               fchdia(nd0, ifc, 1))
              srwd0%sch0(nd0, icv1, 0) = srwd0%sch0(nd0, icv1, 0) - &
&               fchy_diad0(nd0)
            END DO
            fchy_dia = temp2*(dv%fchdia(ifc, 0)+dv%fchdia(ifc, 1))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                fchy_inertiadd(nd0, nd) = temp2*(dvdd%fchinert(nd0, nd, &
&                 ifc, 0)+dvdd%fchinert(nd0, nd, ifc, 1))
                srwdd%sch0(nd0, nd, icv1, 0) = srwdd%sch0(nd0, nd, icv1&
&                 , 0) - fchy_inertiadd(nd0, nd)
              END DO
              fchy_inertiad(nd) = temp2*(dvd%fchinert(nd, ifc, 0)+dvd%&
&               fchinert(nd, ifc, 1))
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_inertiad(nd)
            END DO
            DO nd0=1,nbdirs0
              fchy_inertiad0(nd0) = temp2*(dvd0%fchinert(nd0, ifc, 0)+&
&               dvd0%fchinert(nd0, ifc, 1))
              srwd0%sch0(nd0, icv1, 0) = srwd0%sch0(nd0, icv1, 0) - &
&               fchy_inertiad0(nd0)
            END DO
            fchy_inertia = temp2*(dv%fchinert(ifc, 0)+dv%fchinert(ifc, 1&
&             ))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 2) THEN
!wdk experimental - find constant potential (with
!    perturbation taken from flux tube just inside
!    domain) such that total current through core
!    is sum of dia + inert currents
!     ..compute average potential on core boundary
          t0 = 0.0_R8
          t1 = 0.0_R8
          t2 = 0.0_R8
          totflux = 0.0_R8
          totpar = 0.0_R8
          DO nd=1,nbdirsmax
            totfluxd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t2d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            totpard(nd) = 0.d0
          END DO
          totfluxd0 = 0.D0
          t2dd = 0.D0
          totpardd = 0.D0
          t1d0 = 0.D0
          t2d0 = 0.D0
          totpard0 = 0.D0
          totfluxdd = 0.D0
          t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
          DO ib0=1,nbc
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
            IF (mpg%cvonclosedsurface(icv1)) THEN
              IF (bcpot(ib0) .NE. 12) CALL XERRAB(&
&                                      'BCPOT=12: incompatible core BCs'&
&                                          )
! loop over number of cells in the boundary
              DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
                icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
                icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd&
&                     %po(nd0, nd, icv1)
                    t2dd(nd0, nd) = t2dd(nd0, nd) + geo%cvvol(icv2)*pldd&
&                     %po(nd0, nd, icv2)
                    totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(&
&                     dvdd%fch(nd0, nd, ifc, 0)+dvdd%fch(nd0, nd, ifc, 1&
&                     ))
                  END DO
                  t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%po(nd, icv1)
                  t2d(nd) = t2d(nd) + geo%cvvol(icv2)*pld%po(nd, icv2)
                  totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fch(nd, ifc, &
&                   0)+dvd%fch(nd, ifc, 1))
                END DO
                DO nd0=1,nbdirs0
                  t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%po(nd0, &
&                   icv1)
                  t2d0(nd0) = t2d0(nd0) + geo%cvvol(icv2)*pld0%po(nd0, &
&                   icv2)
                  totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fch(nd0&
&                   , ifc, 0)+dvd0%fch(nd0, ifc, 1))
                END DO
                t1 = t1 + geo%cvvol(icv2)*pl%po(icv1)
                t2 = t2 + geo%cvvol(icv2)*pl%po(icv2)
                totflux = totflux - temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1)&
&                 )
                temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    totpardd(nd0, nd) = totpardd(nd0, nd) - temp2*(dvdd%&
&                     fchdia(nd0, nd, ifc, 0)+dvdd%fchdia(nd0, nd, ifc, &
&                     1)+dvdd%fchinert(nd0, nd, ifc, 0)+dvdd%fchinert(&
&                     nd0, nd, ifc, 1))
                  END DO
                  totpard(nd) = totpard(nd) - temp2*(dvd%fchdia(nd, ifc&
&                   , 0)+dvd%fchdia(nd, ifc, 1)+dvd%fchinert(nd, ifc, 0)&
&                   +dvd%fchinert(nd, ifc, 1))
                END DO
                DO nd0=1,nbdirs0
                  totpard0(nd0) = totpard0(nd0) - temp2*(dvd0%fchdia(nd0&
&                   , ifc, 0)+dvd0%fchdia(nd0, ifc, 1)+dvd0%fchinert(nd0&
&                   , ifc, 0)+dvd0%fchinert(nd0, ifc, 1))
                END DO
                totpar = totpar - temp2*(dv%fchdia(ifc, 0)+dv%fchdia(ifc&
&                 , 1)+dv%fchinert(ifc, 0)+dv%fchinert(ifc, 1))
              END DO
            END IF
          END DO
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t1dd(nd0, nd) = t1dd(nd0, nd)/t0
              t2dd(nd0, nd) = t2dd(nd0, nd)/t0
            END DO
            t1d(nd) = t1d(nd)/t0
            t2d(nd) = t2d(nd)/t0
          END DO
          DO nd0=1,nbdirs0
            t1d0(nd0) = t1d0(nd0)/t0
            t2d0(nd0) = t2d0(nd0)/t0
          END DO
          t1 = t1/t0
          t2 = t2/t0
          IF (potpar(ib, 2) .GT. 0.0_R8) THEN
            t3dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t3dd(nd0, nd) = potpardd(nd0, nd, ib, 2)
              END DO
              t3d(nd) = potpard(nd, ib, 2)
            END DO
            DO nd0=1,nbdirs0
              t3d0(nd0) = potpard0(nd0, ib, 2)
            END DO
            t3 = potpar(ib, 2)
          ELSE
            DO nd=1,nbdirsmax
              t3d(nd) = 0.d0
            END DO
            t3d0 = 0.D0
            t3dd = 0.D0
          END IF
          IF (potpar(ib, 2) .LE. 0.0_R8) THEN
            t3 = switch%b2stbc_bc_ref_te
            DO nd=1,nbdirsmax
              DO nd0=1,nbdirs0
                t3dd(nd0, nd) = 0.D0
              END DO
              t3d(nd) = 0.d0
            END DO
            t3d0 = 0.D0
          END IF
          IF (totflux .GE. 0.) THEN
            x2dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                x2dd(nd0, nd) = totfluxdd(nd0, nd)
              END DO
              x2d(nd) = totfluxd(nd)
            END DO
            DO nd0=1,nbdirs0
              x2d0(nd0) = totfluxd0(nd0)
            END DO
            x2 = totflux
          ELSE
            x2dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                x2dd(nd0, nd) = -totfluxdd(nd0, nd)
              END DO
              x2d(nd) = -totfluxd(nd)
            END DO
            DO nd0=1,nbdirs0
              x2d0(nd0) = -totfluxd0(nd0)
            END DO
            x2 = -totflux
          END IF
          IF (x2 .LT. totpar) THEN
            IF (totpar .LT. 1.0e-10_R8) THEN
              max3 = 1.0e-10_R8
              DO nd=1,nbdirsmax
                max3d(nd) = 0.d0
              END DO
              max3d0 = 0.D0
              max3dd = 0.D0
            ELSE
              max3dd = 0.D0
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  max3dd(nd0, nd) = totpardd(nd0, nd)
                END DO
                max3d(nd) = totpard(nd)
              END DO
              DO nd0=1,nbdirs0
                max3d0(nd0) = totpard0(nd0)
              END DO
              max3 = totpar
            END IF
          ELSE IF (x2 .LT. 1.0e-10_R8) THEN
            max3 = 1.0e-10_R8
            DO nd=1,nbdirsmax
              max3d(nd) = 0.d0
            END DO
            max3d0 = 0.D0
            max3dd = 0.D0
          ELSE
            max3dd = 0.D0
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                max3dd(nd0, nd) = x2dd(nd0, nd)
              END DO
              max3d(nd) = x2d(nd)
            END DO
            DO nd0=1,nbdirs0
              max3d0(nd0) = x2d0(nd0)
            END DO
            max3 = x2
          END IF
          temp2 = t3/max3
          DO nd0=1,nbdirs0
            temp2d(nd0) = (t3d0(nd0)-t3*max3d0(nd0)/max3)/max3
            temp3d(nd0) = -(temp2*(totfluxd0(nd0)-totpard0(nd0))+(&
&             totflux-totpar)*temp2d(nd0))
          END DO
          temp3 = -((totflux-totpar)*temp2) + 1.0_R8
          t4dd = 0.D0
          DO nd=1,nbdirs
            temp6 = t3d(nd) - temp2*max3d(nd)
            temp4 = (totflux-totpar)/max3
            temp7 = temp2*(totfluxd(nd)-totpard(nd)) + temp4*temp6
            DO nd0=1,nbdirs0
              t4dd(nd0, nd) = t1d(nd)*temp3d(nd0) + temp3*t1dd(nd0, nd) &
&               - temp7*t1d0(nd0) - t1*((totfluxd(nd)-totpard(nd))*&
&               temp2d(nd0)+temp2*(totfluxdd(nd0, nd)-totpardd(nd0, nd))&
&               +temp6*(totfluxd0(nd0)-totpard0(nd0)-temp4*max3d0(nd0))/&
&               max3+temp4*(t3dd(nd0, nd)-max3d(nd)*temp2d(nd0)-temp2*&
&               max3dd(nd0, nd)))
            END DO
            t4d(nd) = temp3*t1d(nd) - t1*temp7
          END DO
          DO nd0=1,nbdirs0
            t4d0(nd0) = t1*temp3d(nd0) + temp3*t1d0(nd0)
          END DO
          t4 = temp3*t1
!       ..impose potential with perturbation
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = pbig*geo%fcs(ifc)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                srwdd%sch0(nd0, nd, icv1, 0) = temp2*(pldd%po(nd0, nd, &
&                 icv2)+t4dd(nd0, nd)-t2dd(nd0, nd))
                srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
              END DO
              srwd%sch0(nd, icv1, 0) = temp2*(pld%po(nd, icv2)+t4d(nd)-&
&               t2d(nd))
              srwd%sch0(nd, icv1, 1) = 0.d0
            END DO
            DO nd0=1,nbdirs0
              srwd0%sch0(nd0, icv1, 0) = temp2*(pld0%po(nd0, icv2)+t4d0(&
&               nd0)-t2d0(nd0))
              srwd0%sch0(nd0, icv1, 1) = 0.D0
            END DO
            srw%sch0(icv1, 0) = temp2*(pl%po(icv2)+t4-t2)
            srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
          END DO
        ELSE
          CALL XERRAB('wrong value bcpot_12_style')
        END IF
      END IF
    CASE (13) 
!
! -- BCPOT=13 -- Test condition for south private & north regions ! Solovyev 07.04.14
! code here is a part of code from 50000 for istyle_cur_contr_on_S_and_N.eq.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,a)') 'Adding contributions ', &
&       'from all currents ', 'on ', bcchar(ib), boundary_location(ib)
        IF (switch%istyle_cur_contr_on_s_and_n .EQ. 0 .OR. switch%&
&           istyle_cur_contr_on_s_and_n .EQ. 1) THEN
          WRITE(*, *) ' BCPOT=13 cannot be used when ', &
&         'istyle_cur_contr_on_S_and_N = 0 or 1'
          CALL XERRAB('faulty parameter istyle_cur_contr_on_S_and_N !')
        ELSE
          DO ibc=1,mpg%bccvp(ib, 2)
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL XERTST(.NOT.mpg%cvonclosedsurface(icv1), &
&                 'BCPOT=13 not intended for core boundaries!')
          END DO
        END IF
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = srwdd%sch0(nd0, nd, icv1, 0) &
&             - temp2*(dvdd%fchdia(nd0, nd, ifc, 0)+dvdd%fchdia(nd0, nd&
&             , ifc, 1)+dvdd%fchin(nd0, nd, ifc, 0)+dvdd%fchin(nd0, nd, &
&             ifc, 1)+dvdd%fchvispar(nd0, nd, ifc, 0)+dvdd%fchvispar(nd0&
&             , nd, ifc, 1)+dvdd%fchvisq(nd0, nd, ifc, 0)+dvdd%fchvisq(&
&             nd0, nd, ifc, 1)+dvdd%fchviskt(nd0, nd, ifc, 0)+dvdd%&
&             fchviskt(nd0, nd, ifc, 1)+dvdd%fchvisper(nd0, nd, ifc, 0)+&
&             dvdd%fchvisper(nd0, nd, ifc, 1)+dvdd%fchinert(nd0, nd, ifc&
&             , 0)+dvdd%fchinert(nd0, nd, ifc, 1))
          END DO
          srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - temp2*(dvd%&
&           fchdia(nd, ifc, 0)+dvd%fchdia(nd, ifc, 1)+dvd%fchin(nd, ifc&
&           , 0)+dvd%fchin(nd, ifc, 1)+dvd%fchvispar(nd, ifc, 0)+dvd%&
&           fchvispar(nd, ifc, 1)+dvd%fchvisq(nd, ifc, 0)+dvd%fchvisq(nd&
&           , ifc, 1)+dvd%fchviskt(nd, ifc, 0)+dvd%fchviskt(nd, ifc, 1)+&
&           dvd%fchvisper(nd, ifc, 0)+dvd%fchvisper(nd, ifc, 1)+dvd%&
&           fchinert(nd, ifc, 0)+dvd%fchinert(nd, ifc, 1))
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = srwd0%sch0(nd0, icv1, 0) - temp2*(&
&           dvd0%fchdia(nd0, ifc, 0)+dvd0%fchdia(nd0, ifc, 1)+dvd0%fchin&
&           (nd0, ifc, 0)+dvd0%fchin(nd0, ifc, 1)+dvd0%fchvispar(nd0, &
&           ifc, 0)+dvd0%fchvispar(nd0, ifc, 1)+dvd0%fchvisq(nd0, ifc, 0&
&           )+dvd0%fchvisq(nd0, ifc, 1)+dvd0%fchviskt(nd0, ifc, 0)+dvd0%&
&           fchviskt(nd0, ifc, 1)+dvd0%fchvisper(nd0, ifc, 0)+dvd0%&
&           fchvisper(nd0, ifc, 1)+dvd0%fchinert(nd0, ifc, 0)+dvd0%&
&           fchinert(nd0, ifc, 1))
        END DO
        srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - temp2*(dv%fchdia(ifc, 0)&
&         +dv%fchdia(ifc, 1)+dv%fchin(ifc, 0)+dv%fchin(ifc, 1)+dv%&
&         fchvispar(ifc, 0)+dv%fchvispar(ifc, 1)+dv%fchvisq(ifc, 0)+dv%&
&         fchvisq(ifc, 1)+dv%fchviskt(ifc, 0)+dv%fchviskt(ifc, 1)+dv%&
&         fchvisper(ifc, 0)+dv%fchvisper(ifc, 1)+dv%fchinert(ifc, 0)+dv%&
&         fchinert(ifc, 1))
!srv 03.03.15 }
      END DO
    CASE (14) 
!
! -- BCPOT=14 -- PRESCRIBE THE TOTAL CURRENT WITHOUT IMPOSING A
!                 SPECIFIC PROFILE. FOLLOW PROFILE OF 1st RING INSIDE.
!wdk    Intended use: core boundary, total PF boundary,...
!wdk    For testing purposes, use with care!
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                'BCPOT = 14 : specified total current '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      us = 0.0_R8
      t0 = 0.0_R8
      DO nd=1,nbdirsmax
        t0d(nd) = 0.d0
      END DO
      t0d0 = 0.D0
      t0dd = 0.D0
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t0dd(nd0, nd) = t0dd(nd0, nd) + temp2*(dvdd%fch(nd0, nd, ifc&
&             , 0)+dvdd%fch(nd0, nd, ifc, 1))
          END DO
          t0d(nd) = t0d(nd) + temp2*(dvd%fch(nd, ifc, 0)+dvd%fch(nd, ifc&
&           , 1))
        END DO
        DO nd0=1,nbdirs0
          t0d0(nd0) = t0d0(nd0) + temp2*(dvd0%fch(nd0, ifc, 0)+dvd0%fch(&
&           nd0, ifc, 1))
        END DO
        t0 = t0 + temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1))
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = geo%fcs(ifc)*(t0dd(nd0, nd)-&
&             potpardd(nd0, nd, ib, 1))/us - temp2*(dvdd%fch(nd0, nd, &
&             ifc, 0)+dvdd%fch(nd0, nd, ifc, 1))
            srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%sch0(nd, icv1, 0) = geo%fcs(ifc)*(t0d(nd)-potpard(nd, ib&
&           , 1))/us - temp2*(dvd%fch(nd, ifc, 0)+dvd%fch(nd, ifc, 1))
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = geo%fcs(ifc)*(t0d0(nd0)-potpard0(&
&           nd0, ib, 1))/us - temp2*(dvd0%fch(nd0, ifc, 0)+dvd0%fch(nd0&
&           , ifc, 1))
          srwd0%sch0(nd0, icv1, 1) = 0.D0
        END DO
        srw%sch0(icv1, 0) = geo%fcs(ifc)*((t0-potpar(ib, 1))/us) - temp2&
&         *(dv%fch(ifc, 0)+dv%fch(ifc, 1))
        srw%sch0(icv1, 1) = 0.0_R8
      END DO
    CASE (15) 
!
! -- BCPOT=15 -- Feedback boundary condition on total current with constant potential
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCPOT = 15 : zero net anomalous current on '&
&                                   , bcchar(ib), boundary_location(ib)
!     ..compute average potential on boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      totflux = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      totfluxd0 = 0.D0
      t1d0 = 0.D0
      totfluxdd = 0.D0
      t1dd = 0.D0
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = t0 + geo%fcs(ifc)
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t1dd(nd0, nd) = t1dd(nd0, nd) + geo%fcs(ifc)*pldd%po(nd0, nd&
&             , icv1)
            totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%fch(&
&             nd0, nd, ifc, 0)+dvdd%fch(nd0, nd, ifc, 1))
          END DO
          t1d(nd) = t1d(nd) + geo%fcs(ifc)*pld%po(nd, icv1)
          totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fch(nd, ifc, 0)+dvd%&
&           fch(nd, ifc, 1))
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = t1d0(nd0) + geo%fcs(ifc)*pld0%po(nd0, icv1)
          totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fch(nd0, ifc, 0)&
&           +dvd0%fch(nd0, ifc, 1))
        END DO
        t1 = t1 + geo%fcs(ifc)*pl%po(icv1)
        totflux = totflux - temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1))
      END DO
      totpardd = 0.D0
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          t1dd(nd0, nd) = t1dd(nd0, nd)/t0
          totpardd(nd0, nd) = potpardd(nd0, nd, ib, 1)
        END DO
        t1d(nd) = t1d(nd)/t0
        totpard(nd) = potpard(nd, ib, 1)
      END DO
      DO nd0=1,nbdirs0
        t1d0(nd0) = t1d0(nd0)/t0
        totpard0(nd0) = potpard0(nd0, ib, 1)
      END DO
      t1 = t1/t0
      totpar = potpar(ib, 1)
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        t3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t3dd(nd0, nd) = potpardd(nd0, nd, ib, 2)
          END DO
          t3d(nd) = potpard(nd, ib, 2)
        END DO
        DO nd0=1,nbdirs0
          t3d0(nd0) = potpard0(nd0, ib, 2)
        END DO
        t3 = potpar(ib, 2)
      ELSE
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
        t3dd = 0.D0
      END IF
      IF (potpar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_te
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            t3dd(nd0, nd) = 0.D0
          END DO
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
      END IF
      IF (totflux .GE. 0.) THEN
        x3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x3dd(nd0, nd) = totfluxdd(nd0, nd)
          END DO
          x3d(nd) = totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x3d0(nd0) = totfluxd0(nd0)
        END DO
        x3 = totflux
      ELSE
        x3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x3dd(nd0, nd) = -totfluxdd(nd0, nd)
          END DO
          x3d(nd) = -totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x3d0(nd0) = -totfluxd0(nd0)
        END DO
        x3 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y3dd(nd0, nd) = totpardd(nd0, nd)
          END DO
          y3d(nd) = totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          y3d0(nd0) = totpard0(nd0)
        END DO
        y3 = totpar
      ELSE
        y3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y3dd(nd0, nd) = -totpardd(nd0, nd)
          END DO
          y3d(nd) = -totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          y3d0(nd0) = -totpard0(nd0)
        END DO
        y3 = -totpar
      END IF
      IF (x3 .LT. y3) THEN
        IF (y3 .LT. 1.0_R8) THEN
          max4 = 1.0_R8
          DO nd=1,nbdirsmax
            max4d(nd) = 0.d0
          END DO
          max4d0 = 0.D0
          max4dd = 0.D0
        ELSE
          max4dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              max4dd(nd0, nd) = y3dd(nd0, nd)
            END DO
            max4d(nd) = y3d(nd)
          END DO
          DO nd0=1,nbdirs0
            max4d0(nd0) = y3d0(nd0)
          END DO
          max4 = y3
        END IF
      ELSE IF (x3 .LT. 1.0_R8) THEN
        max4 = 1.0_R8
        DO nd=1,nbdirsmax
          max4d(nd) = 0.d0
        END DO
        max4d0 = 0.D0
        max4dd = 0.D0
      ELSE
        max4dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            max4dd(nd0, nd) = x3dd(nd0, nd)
          END DO
          max4d(nd) = x3d(nd)
        END DO
        DO nd0=1,nbdirs0
          max4d0(nd0) = x3d0(nd0)
        END DO
        max4 = x3
      END IF
      temp2 = t3/max4
      DO nd0=1,nbdirs0
        temp2d(nd0) = (t3d0(nd0)-t3*max4d0(nd0)/max4)/max4
        temp3d(nd0) = -(temp2*(totfluxd0(nd0)-totpard0(nd0))+(totflux-&
&         totpar)*temp2d(nd0))
      END DO
      temp3 = -((totflux-totpar)*temp2) + 1.0_R8
      t2dd = 0.D0
      DO nd=1,nbdirs
        temp7 = t3d(nd) - temp2*max4d(nd)
        temp6 = (totflux-totpar)/max4
        temp4 = temp2*(totfluxd(nd)-totpard(nd)) + temp6*temp7
        DO nd0=1,nbdirs0
          t2dd(nd0, nd) = t1d(nd)*temp3d(nd0) + temp3*t1dd(nd0, nd) - &
&           temp4*t1d0(nd0) - t1*((totfluxd(nd)-totpard(nd))*temp2d(nd0)&
&           +temp2*(totfluxdd(nd0, nd)-totpardd(nd0, nd))+temp7*(&
&           totfluxd0(nd0)-totpard0(nd0)-temp6*max4d0(nd0))/max4+temp6*(&
&           t3dd(nd0, nd)-max4d(nd)*temp2d(nd0)-temp2*max4dd(nd0, nd)))
        END DO
        t2d(nd) = temp3*t1d(nd) - t1*temp4
      END DO
      DO nd0=1,nbdirs0
        t2d0(nd0) = t1*temp3d(nd0) + temp3*t1d0(nd0)
      END DO
      t2 = temp3*t1
      IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&               'bcpot=15: curr_flux, desired_flux, old/new potential, '&
&                                      , totflux, totpar, t1, t2
!     ..impose potential
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = geo%fcs(ifc)*pbig*t2dd(nd0, &
&             nd)
            srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%sch0(nd, icv1, 0) = geo%fcs(ifc)*pbig*t2d(nd)
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = geo%fcs(ifc)*pbig*t2d0(nd0)
          srwd0%sch0(nd0, icv1, 1) = 0.D0
        END DO
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*t2
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (16) 
!
! -- BCPOT=16 -- Feedback boundary condition with constant potential    !Solovyev 22.03.14 !srv 29.09.15
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a)') &
&       'BCPOT = 16 : electric potential feedback by current on ', &
&       bcchar(ib), boundary_location(ib)
! add smth about #ifdef ASTRA here
! Init variables for BCPOT=16                                  { Solovyev 01.05.14
! square of delta between desired and calculated current
        cur_delta = 0.0_R8
! previous value of upper value
        prev_cur_delta = 0.0_R8
! step of approximation (set after 1st iteration)
        po_step = 0.0_R8
        coeff_16 = 1.0_R8
!************************************************************* } Solovyev 01.05.14
        scurpar = 0.0_R8
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            scurpardd(nd0, nd) = 0.D0
          END DO
          scurpard(nd) = 0.d0
        END DO
        scurpard0 = 0.D0
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bcpot(ibw) .EQ. bcpot(ib)) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                scurpardd(nd0, nd) = scurpardd(nd0, nd) + potpardd(nd0, &
&                 nd, ibw, 1)
              END DO
              scurpard(nd) = scurpard(nd) + potpard(nd, ibw, 1)
            END DO
            DO nd0=1,nbdirs0
              scurpard0(nd0) = scurpard0(nd0) + potpard0(nd0, ibw, 1)
            END DO
            scurpar = scurpar + potpar(ibw, 1)
          END IF
        END DO
        WRITE(*, *) 'SCURPAR = ', scurpar
!srv 29.09.15
        pos = 0.0_R8
        vs = 0.0_R8
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            posdd(nd0, nd) = 0.D0
          END DO
          posd(nd) = 0.d0
        END DO
        posd0 = 0.D0
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bcpot(ibw) .EQ. bcpot(ib)) THEN
            DO ibc=1,mpg%bccvp(ibw, 2)
              icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  posdd(nd0, nd) = posdd(nd0, nd) + geo%cvvol(icv)*pldd%&
&                   po(nd0, nd, icv)
                END DO
                posd(nd) = posd(nd) + geo%cvvol(icv)*pld%po(nd, icv)
              END DO
              DO nd0=1,nbdirs0
                posd0(nd0) = posd0(nd0) + geo%cvvol(icv)*pld0%po(nd0, &
&                 icv)
              END DO
              pos = pos + pl%po(icv)*geo%cvvol(icv)
              vs = vs + geo%cvvol(icv)
            END DO
          END IF
        END DO
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
!srv 29.09.15 }
            posdd(nd0, nd) = posdd(nd0, nd)/vs
            po_prevdd(nd0, nd) = posdd(nd0, nd)
          END DO
          posd(nd) = posd(nd)/vs
          po_prevd(nd) = posd(nd)
        END DO
        DO nd0=1,nbdirs0
          posd0(nd0) = posd0(nd0)/vs
          po_prevd0(nd0) = posd0(nd0)
        END DO
        pos = pos/vs
        po_prev = pos
        WRITE(*, *) 'POS at 0 = ', pos
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            prev_cur_deltadd(nd0, nd) = 0.D0
          END DO
          prev_cur_deltad(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            coeff_16dd(nd0, nd) = 0.D0
          END DO
          coeff_16d(nd) = 0.d0
        END DO
        prev_cur_deltad0 = 0.D0
        coeff_16d0 = 0.D0
      END IF
!srv 29.09.15 }
      IF (.NOT.once_bcpot) THEN
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
          totflux = 0.0_R8
          DO nd=1,nbdirsmax
            totfluxd(nd) = 0.d0
          END DO
          totfluxd0 = 0.D0
          totfluxdd = 0.D0
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcpot(ibw) .EQ. bcpot(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
                    totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(&
&                     dvdd%fch(nd0, nd, ifc, 0)+dvdd%fch(nd0, nd, ifc, 1&
&                     ))
                  END DO
                  totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fch(nd, ifc, &
&                   0)+dvd%fch(nd, ifc, 1))
                END DO
                DO nd0=1,nbdirs0
                  totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fch(nd0&
&                   , ifc, 0)+dvd0%fch(nd0, ifc, 1))
                END DO
                totflux = totflux - temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1)&
&                 )
              END DO
            END IF
          END DO
! The implementation is based on one step of Newton method
! { Solovyev 03.05.14
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              cur_deltadd(nd0, nd) = totfluxdd(nd0, nd) - scurpardd(nd0&
&               , nd)
            END DO
            cur_deltad(nd) = totfluxd(nd) - scurpard(nd)
          END DO
          DO nd0=1,nbdirs0
            cur_deltad0(nd0) = totfluxd0(nd0) - scurpard0(nd0)
          END DO
          cur_delta = totflux - scurpar
! } Solovyev 03.05.14
          IF (ncall_b2stbc_phys .EQ. 0) THEN
            WRITE(*, *) '# Newton'
! previous value of upper value
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                prev_cur_deltadd(nd0, nd) = cur_deltadd(nd0, nd)
              END DO
              prev_cur_deltad(nd) = cur_deltad(nd)
            END DO
            DO nd0=1,nbdirs0
              prev_cur_deltad0(nd0) = cur_deltad0(nd0)
            END DO
            prev_cur_delta = cur_delta
          ELSE
!Solovyev 23.05.14
            IF (ncall_b2stbc_phys .EQ. 1) THEN
! Solovyev 23.05.14
!srv 29.09.15
              po_curr = 0.0_R8
              vs = 0.0_R8
              DO nd=1,nbdirsmax
                DO nd0=1,nbdirs0
                  po_currdd(nd0, nd) = 0.D0
                END DO
                po_currd(nd) = 0.d0
              END DO
              po_currd0 = 0.D0
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bcene(ibw) .EQ. bcene(ib)) THEN
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    DO nd=1,nbdirs
                      DO nd0=nd,nbdirs0
                        po_currdd(nd0, nd) = po_currdd(nd0, nd) + geo%&
&                         cvvol(icv)*pldd%po(nd0, nd, icv)
                      END DO
                      po_currd(nd) = po_currd(nd) + geo%cvvol(icv)*pld%&
&                       po(nd, icv)
                    END DO
                    DO nd0=1,nbdirs0
                      po_currd0(nd0) = po_currd0(nd0) + geo%cvvol(icv)*&
&                       pld0%po(nd0, icv)
                    END DO
                    po_curr = po_curr + pl%po(icv)*geo%cvvol(icv)
                    vs = vs + geo%cvvol(icv)
                  END DO
                END IF
              END DO
!srv 29.09.15 }
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
                  po_currdd(nd0, nd) = po_currdd(nd0, nd)/vs
                END DO
                po_currd(nd) = po_currd(nd)/vs
              END DO
              DO nd0=1,nbdirs0
                po_currd0(nd0) = po_currd0(nd0)/vs
              END DO
              po_curr = po_curr/vs
            END IF
! Solovyev 23.05.14
            IF (MOD(ncall_b2stbc_phys, bcpot_16_step) .EQ. 0) THEN
              IF (cur_delta - prev_cur_delta .GE. 0.) THEN
                abs3 = cur_delta - prev_cur_delta
              ELSE
                abs3 = -(cur_delta-prev_cur_delta)
              END IF
!Solovyev 23.05.14
              IF (abs3 .GT. 1.0e-20_R8) THEN
!{ Solovyev 24.05.14
                temp7 = (po_prev-po_curr)/(cur_delta-prev_cur_delta)
                DO nd0=1,nbdirs0
                  temp2d(nd0) = (po_prevd0(nd0)-po_currd0(nd0)-temp7*(&
&                   cur_deltad0(nd0)-prev_cur_deltad0(nd0)))/(cur_delta-&
&                   prev_cur_delta)
                END DO
                temp2 = temp7
                DO nd=1,nbdirs
                  temp7 = (po_prevd(nd)-po_currd(nd)-temp2*(cur_deltad(&
&                   nd)-prev_cur_deltad(nd)))/(cur_delta-prev_cur_delta)
                  DO nd0=1,nbdirs0
                    coeff_16dd(nd0, nd) = (po_prevdd(nd0, nd)-po_currdd(&
&                     nd0, nd)-(cur_deltad(nd)-prev_cur_deltad(nd))*&
&                     temp2d(nd0)-temp2*(cur_deltadd(nd0, nd)-&
&                     prev_cur_deltadd(nd0, nd))-temp7*(cur_deltad0(nd0)&
&                     -prev_cur_deltad0(nd0)))/(cur_delta-prev_cur_delta&
&                     )
                  END DO
                  coeff_16d(nd) = temp7
                END DO
                DO nd0=1,nbdirs0
                  coeff_16d0(nd0) = temp2d(nd0)
                END DO
                coeff_16 = temp2
              END IF
              DO nd=1,nbdirs
                DO nd0=nd,nbdirs0
!} Solovyev 24.05.14
                  po_stepdd(nd0, nd) = coeff_16d(nd)*cur_deltad0(nd0) + &
&                   cur_delta*coeff_16dd(nd0, nd) + cur_deltad(nd)*&
&                   coeff_16d0(nd0) + coeff_16*cur_deltadd(nd0, nd)
                  posdd(nd0, nd) = po_currdd(nd0, nd) + po_stepdd(nd0, &
&                   nd)
                  prev_cur_deltadd(nd0, nd) = cur_deltadd(nd0, nd)
                  po_prevdd(nd0, nd) = po_currdd(nd0, nd)
                  po_currdd(nd0, nd) = posdd(nd0, nd)
                END DO
                po_stepd(nd) = cur_delta*coeff_16d(nd) + coeff_16*&
&                 cur_deltad(nd)
                posd(nd) = po_currd(nd) + po_stepd(nd)
                prev_cur_deltad(nd) = cur_deltad(nd)
                po_prevd(nd) = po_currd(nd)
                po_currd(nd) = posd(nd)
              END DO
              DO nd0=1,nbdirs0
                po_stepd0(nd0) = cur_delta*coeff_16d0(nd0) + coeff_16*&
&                 cur_deltad0(nd0)
                posd0(nd0) = po_currd0(nd0) + po_stepd0(nd0)
                prev_cur_deltad0(nd0) = cur_deltad0(nd0)
                po_prevd0(nd0) = po_currd0(nd0)
                po_currd0(nd0) = posd0(nd0)
              END DO
              po_step = coeff_16*cur_delta
              pos = po_curr + po_step
              prev_cur_delta = cur_delta
              po_prev = po_curr
              po_curr = pos
            END IF
          END IF
! end of implementation
!Solovyev 29.04.14 - test output to b2fdebug
          WRITE(*, *) 'ncall, totflux, POS', ncall_b2stbc_phys, totflux&
&         , pos
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcpot(ibw) .EQ. bcpot(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                DO nd=1,nbdirs
                  DO nd0=nd,nbdirs0
!Solovyev 27.04.14
                    srwdd%sch0(nd0, nd, icv, 0) = geo%fcs(ifc)*pbig*&
&                     posdd(nd0, nd)
!Solovyev 27.04.14
                    srwdd%sch0(nd0, nd, icv, 1) = 0.D0
                  END DO
                  srwd%sch0(nd, icv, 0) = geo%fcs(ifc)*pbig*posd(nd)
                  srwd%sch0(nd, icv, 1) = 0.d0
                END DO
                DO nd0=1,nbdirs0
                  srwd0%sch0(nd0, icv, 0) = geo%fcs(ifc)*pbig*posd0(nd0)
                  srwd0%sch0(nd0, icv, 1) = 0.D0
                END DO
                srw%sch0(icv, 0) = pbig*pos*geo%fcs(ifc)
                srw%sch0(icv, 1) = -(pbig*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bcpot = .true.
        ELSE
          CALL XERRAB('B2STBC -- BCPOT=16, NOT AVAILABLE FOR N,W,E')
        END IF
      END IF
    CASE (17) 
!
! -- BCPOT=17 -- Feedback boundary condition on total current, imposing potential,
!                with same profile as neighbouring flux tube
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT = 17 : imposed current on ', &
&                                   bcchar(ib), boundary_location(ib)
!     ..compute average potential on boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      totfluxd0 = 0.D0
      t1d0 = 0.D0
      totfluxdd = 0.D0
      t1dd = 0.D0
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the plasma cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = t0 + geo%fcs(ifc)
        t1 = t1 + geo%fcs(ifc)*pl%po(icv1)
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t1dd(nd0, nd) = geo%fcs(ifc)*pldd%po(nd0, nd, icv2)
            totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%fch(&
&             nd0, nd, ifc, 0)+dvdd%fch(nd0, nd, ifc, 1))
          END DO
          t1d(nd) = geo%fcs(ifc)*pld%po(nd, icv2)
          totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fch(nd, ifc, 0)+dvd%&
&           fch(nd, ifc, 1))
        END DO
        DO nd0=1,nbdirs0
          t1d0(nd0) = geo%fcs(ifc)*pld0%po(nd0, icv2)
          totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fch(nd0, ifc, 0)&
&           +dvd0%fch(nd0, ifc, 1))
        END DO
        t1 = t2 + geo%fcs(ifc)*pl%po(icv2)
        totflux = totflux - temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1))
      END DO
      totpardd = 0.D0
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          t1dd(nd0, nd) = t1dd(nd0, nd)/t0
          totpardd(nd0, nd) = potpardd(nd0, nd, ib, 1)
        END DO
        t1d(nd) = t1d(nd)/t0
        totpard(nd) = potpard(nd, ib, 1)
      END DO
      DO nd0=1,nbdirs0
        t1d0(nd0) = t1d0(nd0)/t0
        totpard0(nd0) = potpard0(nd0, ib, 1)
      END DO
      t1 = t1/t0
      t2 = t2/t0
      totpar = potpar(ib, 1)
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        t3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t3dd(nd0, nd) = potpardd(nd0, nd, ib, 2)
          END DO
          t3d(nd) = potpard(nd, ib, 2)
        END DO
        DO nd0=1,nbdirs0
          t3d0(nd0) = potpard0(nd0, ib, 2)
        END DO
        t3 = potpar(ib, 2)
      ELSE
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
        t3dd = 0.D0
      END IF
      IF (potpar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_te
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            t3dd(nd0, nd) = 0.D0
          END DO
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
      END IF
      IF (totflux .GE. 0.) THEN
        x4dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x4dd(nd0, nd) = totfluxdd(nd0, nd)
          END DO
          x4d(nd) = totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x4d0(nd0) = totfluxd0(nd0)
        END DO
        x4 = totflux
      ELSE
        x4dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x4dd(nd0, nd) = -totfluxdd(nd0, nd)
          END DO
          x4d(nd) = -totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x4d0(nd0) = -totfluxd0(nd0)
        END DO
        x4 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y4dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y4dd(nd0, nd) = totpardd(nd0, nd)
          END DO
          y4d(nd) = totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          y4d0(nd0) = totpard0(nd0)
        END DO
        y4 = totpar
      ELSE
        y4dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y4dd(nd0, nd) = -totpardd(nd0, nd)
          END DO
          y4d(nd) = -totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          y4d0(nd0) = -totpard0(nd0)
        END DO
        y4 = -totpar
      END IF
      IF (x4 .LT. y4) THEN
        IF (y4 .LT. 1.0_R8) THEN
          max5 = 1.0_R8
          DO nd=1,nbdirsmax
            max5d(nd) = 0.d0
          END DO
          max5d0 = 0.D0
          max5dd = 0.D0
        ELSE
          max5dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              max5dd(nd0, nd) = y4dd(nd0, nd)
            END DO
            max5d(nd) = y4d(nd)
          END DO
          DO nd0=1,nbdirs0
            max5d0(nd0) = y4d0(nd0)
          END DO
          max5 = y4
        END IF
      ELSE IF (x4 .LT. 1.0_R8) THEN
        max5 = 1.0_R8
        DO nd=1,nbdirsmax
          max5d(nd) = 0.d0
        END DO
        max5d0 = 0.D0
        max5dd = 0.D0
      ELSE
        max5dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            max5dd(nd0, nd) = x4dd(nd0, nd)
          END DO
          max5d(nd) = x4d(nd)
        END DO
        DO nd0=1,nbdirs0
          max5d0(nd0) = x4d0(nd0)
        END DO
        max5 = x4
      END IF
      temp2 = t3/max5
      DO nd0=1,nbdirs0
        temp2d(nd0) = (t3d0(nd0)-t3*max5d0(nd0)/max5)/max5
        temp3d(nd0) = -(temp2*(totfluxd0(nd0)-totpard0(nd0))+(totflux-&
&         totpar)*temp2d(nd0))
      END DO
      temp3 = -((totflux-totpar)*temp2) + 1.0_R8
      t4dd = 0.D0
      DO nd=1,nbdirs
        temp7 = t3d(nd) - temp2*max5d(nd)
        temp6 = (totflux-totpar)/max5
        temp4 = temp2*(totfluxd(nd)-totpard(nd)) + temp6*temp7
        DO nd0=1,nbdirs0
          t4dd(nd0, nd) = t1d(nd)*temp3d(nd0) + temp3*t1dd(nd0, nd) - &
&           temp4*t1d0(nd0) - t1*((totfluxd(nd)-totpard(nd))*temp2d(nd0)&
&           +temp2*(totfluxdd(nd0, nd)-totpardd(nd0, nd))+temp7*(&
&           totfluxd0(nd0)-totpard0(nd0)-temp6*max5d0(nd0))/max5+temp6*(&
&           t3dd(nd0, nd)-max5d(nd)*temp2d(nd0)-temp2*max5dd(nd0, nd)))
        END DO
        t4d(nd) = temp3*t1d(nd) - t1*temp4
      END DO
      DO nd0=1,nbdirs0
        t4d0(nd0) = t1*temp3d(nd0) + temp3*t1d0(nd0)
      END DO
      t4 = temp3*t1
      IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&               'bcpot=17: curr_flux, desired_flux, old/new potential, '&
&                                      , totflux, totpar, t1, t4
!     ..impose potential
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = pbig*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = temp2*(pldd%po(nd0, nd, icv2)&
&             +t4dd(nd0, nd))
            srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%sch0(nd, icv1, 0) = temp2*(pld%po(nd, icv2)+t4d(nd))
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = temp2*(pld0%po(nd0, icv2)+t4d0(nd0)&
&           )
          srwd0%sch0(nd0, icv1, 1) = 0.D0
        END DO
        srw%sch0(icv1, 0) = temp2*(pl%po(icv2)-t2+t4)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (18) 
!
! -- BCPOT=18 -- Nothing implemented
!
      CALL XERRAB('B2STBC -- BCPOT=18, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=19 -- Nothing implemented
!
    CASE (19) 
      CALL XERRAB('B2STBC -- BCPOT=19, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=20 -- Nothing implemented
!
    CASE (20) 
      CALL XERRAB('B2STBC -- BCPOT=20, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=21 -- constant potential scaled by potential on the ring bc_type21_ref away
!
    CASE (21) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCPOT = 21 : fixed potential (modified by nearby ring) ', &
&       potpar(ib, 1), ' with ', potpar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(potpar(ib, 2) .GT. 0.0_R8, &
&             'faulty parameter potpar2')
      END IF
      IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'N') .OR. bcchar(ib)&
&         .EQ. 'A') THEN
        poave = 0.0_R8
        neave = 0.0_R8
        DO nd=1,nbdirsmax
          poaved(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          neaved(nd) = 0.d0
        END DO
        poavedd = 0.D0
        poaved0 = 0.D0
        neaved0 = 0.D0
        neavedd = 0.D0
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              poavedd(nd0, nd) = poavedd(nd0, nd) + geo%cvvol(icv)*(pld%&
&               po(nd, icv)*dvd0%ne(nd0, icv)+dv%ne(icv)*pldd%po(nd0, nd&
&               , icv)+dvd%ne(nd, icv)*pld0%po(nd0, icv)+pl%po(icv)*dvdd&
&               %ne(nd0, nd, icv))
              neavedd(nd0, nd) = neavedd(nd0, nd) + geo%cvvol(icv)*dvdd%&
&               ne(nd0, nd, icv)
            END DO
            poaved(nd) = poaved(nd) + geo%cvvol(icv)*(dv%ne(icv)*pld%po(&
&             nd, icv)+pl%po(icv)*dvd%ne(nd, icv))
            neaved(nd) = neaved(nd) + geo%cvvol(icv)*dvd%ne(nd, icv)
          END DO
          DO nd0=1,nbdirs0
            poaved0(nd0) = poaved0(nd0) + geo%cvvol(icv)*(dv%ne(icv)*&
&             pld0%po(nd0, icv)+pl%po(icv)*dvd0%ne(nd0, icv))
            neaved0(nd0) = neaved0(nd0) + geo%cvvol(icv)*dvd0%ne(nd0, &
&             icv)
          END DO
          poave = poave + pl%po(icv)*dv%ne(icv)*geo%cvvol(icv)
          neave = neave + dv%ne(icv)*geo%cvvol(icv)
        END DO
        DO nd=1,nbdirs
          temp7 = poave/neave
          temp6 = (poaved(nd)-neaved(nd)*temp7)/neave
          DO nd0=1,nbdirs0
            poavedd(nd0, nd) = (poavedd(nd0, nd)-temp7*neavedd(nd0, nd)-&
&             neaved(nd)*(poaved0(nd0)-temp7*neaved0(nd0))/neave-temp6*&
&             neaved0(nd0))/neave
          END DO
          poaved(nd) = temp6
        END DO
        DO nd0=1,nbdirs0
          poaved0(nd0) = (poaved0(nd0)-poave*neaved0(nd0)/neave)/neave
        END DO
        poave = poave/neave
        IF (potpar(ib, 2) .GT. 0.0_R8) THEN
          t3dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              t3dd(nd0, nd) = potpardd(nd0, nd, ib, 2)
            END DO
            t3d(nd) = potpard(nd, ib, 2)
          END DO
          DO nd0=1,nbdirs0
            t3d0(nd0) = potpard0(nd0, ib, 2)
          END DO
          t3 = potpar(ib, 2)
        ELSE
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
          t3d0 = 0.D0
          t3dd = 0.D0
        END IF
        IF (potpar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          DO nd=1,nbdirsmax
            DO nd0=1,nbdirs0
              t3dd(nd0, nd) = 0.D0
            END DO
            t3d(nd) = 0.d0
          END DO
          t3d0 = 0.D0
        END IF
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*geo%fcs(ifc)
          temp1 = t3/poave
          DO nd0=1,nbdirs0
            temp1d(nd0) = (t3d0(nd0)-t3*poaved0(nd0)/poave)/poave
            temp3d(nd0) = temp1*pld0%po(nd0, icv) + pl%po(icv)*temp1d(&
&             nd0) - t3d0(nd0)
          END DO
          temp3 = pl%po(icv)*temp1 - t3 + 1.0_R8
          DO nd=1,nbdirs
            temp7 = t3d(nd) - temp1*poaved(nd)
            temp5 = pl%po(icv)/poave
            temp6 = temp1*pld%po(nd, icv) + temp5*temp7 - t3d(nd)
            DO nd0=1,nbdirs0
              srwdd%sch0(nd0, nd, icv, 0) = temp2*(potpard(nd, ib, 1)*&
&               temp3d(nd0)+temp3*potpardd(nd0, nd, ib, 1)+temp6*&
&               potpard0(nd0, ib, 1)+potpar(ib, 1)*(pld%po(nd, icv)*&
&               temp1d(nd0)+temp1*pldd%po(nd0, nd, icv)+temp7*(pld0%po(&
&               nd0, icv)-temp5*poaved0(nd0))/poave+temp5*(t3dd(nd0, nd)&
&               -poaved(nd)*temp1d(nd0)-temp1*poavedd(nd0, nd))-t3dd(nd0&
&               , nd)))
              srwdd%sch0(nd0, nd, icv, 1) = 0.D0
            END DO
            srwd%sch0(nd, icv, 0) = temp2*(temp3*potpard(nd, ib, 1)+&
&             potpar(ib, 1)*temp6)
            srwd%sch0(nd, icv, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%sch0(nd0, icv, 0) = temp2*(temp3*potpard0(nd0, ib, 1)+&
&             potpar(ib, 1)*temp3d(nd0))
            srwd0%sch0(nd0, icv, 1) = 0.D0
          END DO
          srw%sch0(icv, 0) = temp2*(potpar(ib, 1)*temp3)
          srw%sch0(icv, 1) = -(vbig*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCPOT=21, NOT AVAILABLE FOR W,E')
      END IF
    CASE (22) 
!
! -- BCPOT=22 -- Prescribe the value of the potential, with perturbation taken
!                from first flux tube in the domain
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT = 22 : specified potential ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCPOT=22 intended for core boundaries only!')
        END DO
      END IF
!     ..compute average potential on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      t1d0 = 0.D0
      t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%po(&
&                 nd0, nd, icv2)
              END DO
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%po(nd, icv2)
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%po(nd0, icv2)
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%po(icv2)
          END DO
        END IF
      END DO
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          t1dd(nd0, nd) = t1dd(nd0, nd)/t0
        END DO
        t1d(nd) = t1d(nd)/t0
      END DO
      DO nd0=1,nbdirs0
        t1d0(nd0) = t1d0(nd0)/t0
      END DO
      t1 = t1/t0
!     ..impose potential with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = pbig*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = temp2*(pldd%po(nd0, nd, icv2)&
&             +potpardd(nd0, nd, ib, 1)-t1dd(nd0, nd))
            srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%sch0(nd, icv1, 0) = temp2*(pld%po(nd, icv2)+potpard(nd, &
&           ib, 1)-t1d(nd))
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = temp2*(pld0%po(nd0, icv2)+potpard0(&
&           nd0, ib, 1)-t1d0(nd0))
          srwd0%sch0(nd0, icv1, 1) = 0.D0
        END DO
        srw%sch0(icv1, 0) = temp2*(pl%po(icv2)+potpar(ib, 1)-t1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (23) 
!
! -- BCPOT=23 -- Feedback on the total current for the South core boundary, by imposing a flux surface
!                averaged potential, with poloidal perturbation taken from flux
!                tube just inside domain. The feedback is scaled with the ion temperature.
!               POTPAR(,,1) specifies the desired integral current through flux surfaces(A).
!               POTPAR(,,2) is the strength of the feedback
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT = 23 : specified potential ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCPOT=23 intended for core boundaries only!')
        END DO
      END IF
!     ..compute average potential on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
!lkw
      t4 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t2d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t4d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        totpard(nd) = 0.d0
      END DO
      totfluxd0 = 0.D0
      t2dd = 0.D0
      totpardd = 0.D0
      t1d0 = 0.D0
      t2d0 = 0.D0
      t4d0 = 0.D0
      totpard0 = 0.D0
      totfluxdd = 0.D0
      t4dd = 0.D0
      t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bcpot(ib0) .NE. 23) CALL XERRAB(&
&                                      'BCPOT=23: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%po(&
&                 nd0, nd, icv1)
                t2dd(nd0, nd) = t2dd(nd0, nd) + geo%cvvol(icv2)*pldd%po(&
&                 nd0, nd, icv2)
! lkw 10.09.2022{
                t4dd(nd0, nd) = t4dd(nd0, nd) + geo%cvvol(icv2)*pldd%ti(&
&                 nd0, nd, icv2)/qe
                totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%&
&                 fch(nd0, nd, ifc, 0)+dvdd%fch(nd0, nd, ifc, 1))
              END DO
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%po(nd, icv1)
              t2d(nd) = t2d(nd) + geo%cvvol(icv2)*pld%po(nd, icv2)
              t4d(nd) = t4d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)/qe
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fch(nd, ifc, 0)+&
&               dvd%fch(nd, ifc, 1))
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%po(nd0, icv1)
              t2d0(nd0) = t2d0(nd0) + geo%cvvol(icv2)*pld0%po(nd0, icv2)
              t4d0(nd0) = t4d0(nd0) + geo%cvvol(icv2)*pld0%ti(nd0, icv2)&
&               /qe
              totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fch(nd0, ifc&
&               , 0)+dvd0%fch(nd0, ifc, 1))
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%po(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%po(icv2)
            t4 = t4 + geo%cvvol(icv2)*pl%ti(icv2)/qe
            totflux = totflux - temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1))
          END DO
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              totpardd(nd0, nd) = totpardd(nd0, nd) + potpardd(nd0, nd, &
&               ib0, 1)
            END DO
            totpard(nd) = totpard(nd) + potpard(nd, ib0, 1)
          END DO
          DO nd0=1,nbdirs0
            totpard0(nd0) = totpard0(nd0) + potpard0(nd0, ib0, 1)
          END DO
          totpar = totpar + potpar(ib0, 1)
        END IF
      END DO
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          t1dd(nd0, nd) = t1dd(nd0, nd)/t0
          t2dd(nd0, nd) = t2dd(nd0, nd)/t0
          t4dd(nd0, nd) = t4dd(nd0, nd)/t0
        END DO
        t1d(nd) = t1d(nd)/t0
        t2d(nd) = t2d(nd)/t0
        t4d(nd) = t4d(nd)/t0
      END DO
      DO nd0=1,nbdirs0
        t1d0(nd0) = t1d0(nd0)/t0
        t2d0(nd0) = t2d0(nd0)/t0
        t4d0(nd0) = t4d0(nd0)/t0
      END DO
      t1 = t1/t0
      t2 = t2/t0
      t4 = t4/t0
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        t3dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            t3dd(nd0, nd) = potpardd(nd0, nd, ib, 2)
          END DO
          t3d(nd) = potpard(nd, ib, 2)
        END DO
        DO nd0=1,nbdirs0
          t3d0(nd0) = potpard0(nd0, ib, 2)
        END DO
        t3 = potpar(ib, 2)
      ELSE
        t3 = switch%b2stbc_bc_ref_te
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
        t3dd = 0.D0
      END IF
      IF (totflux .GE. 0.) THEN
        x5dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x5dd(nd0, nd) = totfluxdd(nd0, nd)
          END DO
          x5d(nd) = totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x5d0(nd0) = totfluxd0(nd0)
        END DO
        x5 = totflux
      ELSE
        x5dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x5dd(nd0, nd) = -totfluxdd(nd0, nd)
          END DO
          x5d(nd) = -totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x5d0(nd0) = -totfluxd0(nd0)
        END DO
        x5 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y5dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y5dd(nd0, nd) = totpardd(nd0, nd)
          END DO
          y5d(nd) = totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          y5d0(nd0) = totpard0(nd0)
        END DO
        y5 = totpar
      ELSE
        y5dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            y5dd(nd0, nd) = -totpardd(nd0, nd)
          END DO
          y5d(nd) = -totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          y5d0(nd0) = -totpard0(nd0)
        END DO
        y5 = -totpar
      END IF
      IF (x5 .LT. y5) THEN
        IF (y5 .LT. 1.0e-10_R8) THEN
          max6 = 1.0e-10_R8
          DO nd=1,nbdirsmax
            max6d(nd) = 0.d0
          END DO
          max6dd = 0.D0
          max6d0 = 0.D0
        ELSE
          max6dd = 0.D0
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              max6dd(nd0, nd) = y5dd(nd0, nd)
            END DO
            max6d(nd) = y5d(nd)
          END DO
          DO nd0=1,nbdirs0
            max6d0(nd0) = y5d0(nd0)
          END DO
          max6 = y5
        END IF
      ELSE IF (x5 .LT. 1.0e-10_R8) THEN
        max6 = 1.0e-10_R8
        DO nd=1,nbdirsmax
          max6d(nd) = 0.d0
        END DO
        max6dd = 0.D0
        max6d0 = 0.D0
      ELSE
        max6dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            max6dd(nd0, nd) = x5dd(nd0, nd)
          END DO
          max6d(nd) = x5d(nd)
        END DO
        DO nd0=1,nbdirs0
          max6d0(nd0) = x5d0(nd0)
        END DO
        max6 = x5
      END IF
! lkw 10.09.2022}
      temp7 = (totflux-totpar)/max6
      DO nd0=1,nbdirs0
        temp2d(nd0) = (totfluxd0(nd0)-totpard0(nd0)-temp7*max6d0(nd0))/&
&         max6
      END DO
      temp2 = temp7
      DO nd=1,nbdirs
        temp7 = t3*t4d(nd) + t4*t3d(nd)
        temp6 = totfluxd(nd) - totpard(nd) - temp2*max6d(nd)
        temp4 = t4*t3/max6
        DO nd0=1,nbdirs0
          t4dd(nd0, nd) = t1dd(nd0, nd) - temp7*temp2d(nd0) - temp2*(t4d&
&           (nd)*t3d0(nd0)+t3*t4dd(nd0, nd)+t3d(nd)*t4d0(nd0)+t4*t3dd(&
&           nd0, nd)) - temp6*(t3*t4d0(nd0)+t4*t3d0(nd0)-temp4*max6d0(&
&           nd0))/max6 - temp4*(totfluxdd(nd0, nd)-totpardd(nd0, nd)-&
&           max6d(nd)*temp2d(nd0)-temp2*max6dd(nd0, nd))
        END DO
        t4d(nd) = t1d(nd) - temp2*temp7 - temp4*temp6
      END DO
      DO nd0=1,nbdirs0
        t4d0(nd0) = t1d0(nd0) - temp2*(t3*t4d0(nd0)+t4*t3d0(nd0)) - t4*&
&         t3*temp2d(nd0)
      END DO
      t4 = t1 - t4*t3*temp2
!
!     ..impose potential with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = pbig*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%sch0(nd0, nd, icv1, 0) = temp2*(pldd%po(nd0, nd, icv2)&
&             +t4dd(nd0, nd)-t2dd(nd0, nd))
            srwdd%sch0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%sch0(nd, icv1, 0) = temp2*(pld%po(nd, icv2)+t4d(nd)-t2d(&
&           nd))
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%sch0(nd0, icv1, 0) = temp2*(pld0%po(nd0, icv2)+t4d0(nd0)&
&           -t2d0(nd0))
          srwd0%sch0(nd0, icv1, 1) = 0.D0
        END DO
        srw%sch0(icv1, 0) = temp2*(pl%po(icv2)+t4-t2)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcpot(ib)
      CALL XERRAB('BCPOT out of bounds')
    END SELECT
!
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_POT_DV_DV

!  Differentiation of b2stbc_phys_pot in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: scurpar prev_cur_delta po_prev
!                po_curr coeff_16 pos *(srw.sch0) vbc csbc
!   with respect to varying inputs: mompar potpar scurpar prev_cur_delta
!                po_prev po_curr coeff_16 pos *(dv.fch) *(dv.fchdia)
!                *(dv.fchin) *(dv.fchvispar) *(dv.fchvisper) *(dv.fchvisq)
!                *(dv.fchinert) *(dv.fchviskt) *(dv.ne) *(dv.vaecrb)
!                *(rt.rza) *(srw.sch0) *(co.sig0) *(pl.na) *(pl.ua)
!                *(pl.po) *(pl.te) *(pl.ti) naua2average vbc rz
!                csbc pzaverage pz
!   Plus diff mem management of: dv.fch:in dv.fchdia:in dv.fchin:in
!                dv.fchvispar:in dv.fchvisper:in dv.fchvisq:in
!                dv.fchinert:in dv.fchviskt:in dv.ne:in dv.vaecrb:in
!                dv.facdrift:in mpg.bcfcor:in geo.vxvol:in rt.rza:in
!                srw.sch0:in co.sig0:in pl.na:in pl.ua:in pl.po:in
!                pl.te:in pl.ti:in
!
  SUBROUTINE B2STBC_PHYS_POT_DV(ib, nbdirs)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: ib, ib0, ibc, ibc0, ibw, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, vte, vbnd, s1, fche, fchi, t0, t1, t2, t3, t4, &
&   neave, poave, totpar, totflux, wrk, seec, fchy_dia, fchy_inertia
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd, vted, vbndd, fched, &
&   fchid, t0d, t1d, t2d, t3d, t4d, neaved, poaved, totpard, totfluxd, &
&   fchy_diad, fchy_inertiad
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    INTRINSIC MIN
    INTRINSIC MOD
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8) :: y1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y1d
    REAL(kind=r8) :: y2
    REAL(kind=r8) :: x2
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x2d
    REAL(kind=r8) :: x3
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x3d
    REAL(kind=r8) :: y3
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y3d
    REAL(kind=r8) :: x4
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x4d
    REAL(kind=r8) :: y4
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y4d
    REAL(kind=r8) :: x5
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x5d
    REAL(kind=r8) :: y5
    REAL(kind=r8), DIMENSION(nbdirsmax) :: y5d
    REAL(r8) :: y6
    REAL(r8), DIMENSION(nbdirsmax) :: y6d
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: max1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max1d
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: max2
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max2d
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: max3
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max3d
    REAL(kind=r8) :: max4
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max4d
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: max5
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max5d
    REAL(kind=r8) :: max6
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max6d
    REAL(kind=r8) :: abs4
    REAL(r8) :: min1
    REAL(r8), DIMENSION(nbdirsmax) :: min1d
    REAL(kind=r8) :: abs5
    REAL(r8) :: arg12
    REAL(r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(kind=r8) :: arg13
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result20d
    REAL(kind=r8) :: result11
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(kind=r8) :: temp2
    REAL(r8) :: temp3
    INTEGER :: nbdirs
    INTRINSIC MAXVAL
!
! -- BOUNDARY CONDITIONS FOR POTENTIAL EQUATION --
!
    SELECT CASE  (bcpot(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCPOT=1 -- PRESCRIBE THE VALUE OF THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  1 : specified potential '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp = pbig*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = temp*potpard(nd, ib, 1)
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        srw%sch0(icv1, 0) = temp*potpar(ib, 1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCPOT=2 -- PRESCRIBE THE GRADIENT OF THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  2 : potential gradient ', &
&                                   potpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        CALL INTVERTEX_S_DV_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%po&
&                            , pld%po, t1, t1d, nbdirs)
        CALL INTVERTEX_S_DV_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%po&
&                            , pld%po, t2, t2d, nbdirs)
        temp = pbig*geo%fcs(ifc)
        temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
        temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, &
&         2))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = temp*(temp0*geo%fcqgam(ifc, 0)*&
&           potpard(nd, ib, 1)-temp1*temp2*(t2d(nd)-t1d(nd))/geo%fcht(&
&           ifc)+pld%po(nd, icv2))
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        srw%sch0(icv1, 0) = temp*(temp0*(geo%fcqgam(ifc, 0)*potpar(ib, 1&
&         ))-temp1*(temp2*((t2-t1)/geo%fcht(ifc)))+pl%po(icv2))
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCPOT=3 -- SHEATH CONDITIONS, ELECTRON ENERGY TRANSMISSION
!
      CALL XERRAB('b2stbc_phys -- BCPOT = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCPOT = 11')
!
! -- BCPOT=4 -- PRESCRIBE THE VALUE OF THE POTENTIAL,
!                 WEAKLY A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'BCPOT =  4 : weak potential ', &
&       potpar(ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(potpar(ib, 2) .GT. 0.0_R8, &
&             'BCPOT = 4, POTPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = geo%fcs(ifc)*(potpar(ib, 1)*potpard(&
&           nd, ib, 2)+potpar(ib, 2)*potpard(nd, ib, 1))
          srwd%sch0(nd, icv1, 1) = -(geo%fcs(ifc)*potpard(nd, ib, 2))
        END DO
        srw%sch0(icv1, 0) = potpar(ib, 2)*geo%fcs(ifc)*potpar(ib, 1)
        srw%sch0(icv1, 1) = -(potpar(ib, 2)*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCPOT=5 -- PRESCRIBE THE CURRENT FLUX DENSITY PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCPOT =  5 : current flux density per area '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO nd=1,nbdirs
          srwd%sch0(nd, icv, 0) = geo%fcs(ifc)*potpard(nd, ib, 1)
          srwd%sch0(nd, icv, 1) = 0.d0
        END DO
        srw%sch0(icv, 0) = potpar(ib, 1)*geo%fcs(ifc)
        srw%sch0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCPOT=6 -- PRESCRIBE THE TOTAL CURRENT FLUX DENSITY FOR A
!                 CONSTANT POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                             'BCPOT =  6 : total current flux density '&
&                                   , potpar(ib, 1), &
&                                   ' with const potential on ', bcchar(&
&                                   ib), boundary_location(ib)
      CALL XERRAB('B2STBC -- BCPOT=6, NOT YET AVAILABLE')
!
! -- BCPOT=7 -- PRESCRIBE THE GIVEN PROFILE OF POTENTIAL
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') 'BCPOT = 7 : specified potential on ', bcchar(&
&       ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = 0.d0
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*bv_po(icv1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCPOT=8 -- PRESCRIBE THE TOTAL ELECTRON CURRENT WITH CONSTANT
!                 FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  8 : total current ', &
&                                   potpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = geo%fcs(ifc)*potpard(nd, ib, 1)/us
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        srw%sch0(icv1, 0) = potpar(ib, 1)/us*geo%fcs(ifc)
        srw%sch0(icv1, 1) = 0.0_R8
      END DO
    CASE (9) 
!
! -- BCPOT=9 -- PRESCRIBE THE DECAY LENGTH FOR
!                 THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT =  9 : potential decay length ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(potpar(ib, 1) .NE. 0.0_R8, &
&             'BCPOT = 9, POTPAR(,1) = 0')
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        temp2 = qe*potpar(ib, 1)
        temp1 = temp2*dv%ne(icv)
        temp3 = co%sig0(ifc)/temp1
        DO nd=1,nbdirs
          srwd%sch0(nd, icv, 0) = 0.d0
          srwd%sch0(nd, icv, 1) = -(geo%fcs(ifc)*(cod%sig0(nd, ifc)-&
&           temp3*(dv%ne(icv)*qe*potpard(nd, ib, 1)+temp2*dvd%ne(nd, icv&
&           )))/temp1)
        END DO
        srw%sch0(icv, 0) = 0.0_R8
        srw%sch0(icv, 1) = -(geo%fcs(ifc)*temp3)
      END DO
    CASE (10) 
!
! -- BCPOT=10 -- Feedback option for core
!                NOT YET TESTED!!!!!!!!!
!
      CALL XERRAB('b2stbc_phys -- BCPOT = 10 not adapted for WG')
!
! -- BCPOT=11 -- SHEATH CONDITION, CURRENT CONTINUITY                !srv 01.02.09 {
!
    CASE (11) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCPOT = 11 : sheath potential current continuity bc', &
&       ' with POTPAR(IB,2) =', potpar(ib, 2), ' gammae =', gammae, &
&       ' on ', bcchar(ib), boundary_location(ib)
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) CALL XERTST(bccon(is, ib) .EQ. 14, &
&                                        'When BCPOT=11, '//&
&                          'one must have BCCON=14 for all ion species!'&
&                                       )
        END DO
      END IF
!srv 15.02.26
      conv_bcpot11 = .true.
!srv 15.02.26
      mrs = 0.0_R8
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
!srv 15.02.26 {
        DO is=0,ns-1
          CALL CSBC_IS_DV(icv1, ib, is, cs, csd, nbdirs)
          CALL VBC_IS_DV(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), &
&                  csbcd(:, icv1, is), wrk, nbdirs)
!srv 15.02.26 }
        END DO
        arg12 = pl%te(icv1)/me
        temp3 = SQRT(arg12)
        DO nd=1,nbdirs
          arg12d(nd) = pld%te(nd, icv1)/me
          IF (arg12 .EQ. 0.d0) THEN
            vted(nd) = 0.d0
          ELSE
            vted(nd) = arg12d(nd)/(2.0*temp3)
          END IF
        END DO
        vte = temp3
        t0 = 0.0_R8
        wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
        IF (wrk .GE. 0.) THEN
          abs0 = wrk
        ELSE
          abs0 = -wrk
        END IF
        IF (abs0 .LT. geo%qalfmin) THEN
          CALL INTVERTEX_S_DV_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%&
&                              po, pld%po, t1, t1d, nbdirs)
          CALL INTVERTEX_S_DV_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%&
&                              po, pld%po, t2, t2d, nbdirs)
          temp2 = pbig*geo%fcs(ifc)
          temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc&
&           , 2))
          temp0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          DO nd=1,nbdirs
            srwd%sch0(nd, icv1, 0) = temp2*(pld%po(nd, icv2)-temp1*temp0&
&             *(t2d(nd)-t1d(nd))/geo%fcht(ifc))
            srwd%sch0(nd, icv1, 1) = 0.d0
          END DO
          srw%sch0(icv1, 0) = temp2*(pl%po(icv2)-temp1*(temp0*((t2-t1)/&
&           geo%fcht(ifc))))
          srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
        ELSE
          s1 = geo%fcs(ifc)
          DO nd=1,nbdirsmax
            t0d(nd) = 0.d0
          END DO
          DO is=0,ns-1
            IF (.NOT.is_neutral(is)) THEN
              temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
              DO nd=1,nbdirs
                vbndd(nd) = temp2*(geo%fcqalf(ifc, 0)*dvd%vaecrb(nd, ifc&
&                 , 0, is)+geo%fcqalf(ifc, 1)*dvd%vaecrb(nd, ifc, 1, is)&
&                 )
              END DO
              vbnd = temp2*(geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo&
&               %fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))
              IF (wrk .GE. 0.) THEN
                abs4 = wrk
              ELSE
                abs4 = -wrk
              END IF
              temp3 = SIGN(1.0_R8, wrk)
              DO nd=1,nbdirs
                x1d(nd) = abs4*csbcd(nd, icv1, is)
                y1d(nd) = temp3*vbcd(nd, icv1, is) + vbndd(nd)
              END DO
              x1 = csbc(icv1, is)*abs4
              y1 = temp3*vbc(icv1, is) + vbnd
              IF (x1 .LT. y1) THEN
                DO nd=1,nbdirs
                  max1d(nd) = y1d(nd)
                END DO
                max1 = y1
              ELSE
                DO nd=1,nbdirs
                  max1d(nd) = x1d(nd)
                END DO
                max1 = x1
              END IF
              temp2 = mompar(is, ib, 1)*pl%na(icv1, is)
              temp3 = rt%rza(icv1, is)*max1
              DO nd=1,nbdirs
                t0d(nd) = t0d(nd) + s1*(temp2*(max1*rtd%rza(nd, icv1, is&
&                 )+rt%rza(icv1, is)*max1d(nd))+temp3*(pl%na(icv1, is)*&
&                 mompard(nd, is, ib, 1)+mompar(is, ib, 1)*pld%na(nd, &
&                 icv1, is)))
              END DO
              t0 = t0 + s1*(temp3*temp2)
            END IF
          END DO
          DO nd=1,nbdirs
            fchid(nd) = qe*t0d(nd)
          END DO
          fchi = qe*t0
          IF (wrk .GE. 0.) THEN
            abs1 = wrk
          ELSE
            abs1 = -wrk
          END IF
          IF (-50.0_R8 .LT. -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)&
&             )) THEN
            temp3 = (pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)
            DO nd=1,nbdirs
              y6d(nd) = -(qe*(pld%po(nd, icv1)-potpard(nd, ib, 2)-temp3*&
&               pld%te(nd, icv1))/pl%te(icv1))
            END DO
            y6 = -(qe*temp3)
          ELSE
            y6 = -50.0_R8
            DO nd=1,nbdirsmax
              y6d(nd) = 0.d0
            END DO
          END IF
          IF (0.0_R8 .GT. y6) THEN
            DO nd=1,nbdirs
              min1d(nd) = y6d(nd)
            END DO
            min1 = y6
          ELSE
            min1 = 0.0_R8
            DO nd=1,nbdirsmax
              min1d(nd) = 0.d0
            END DO
          END IF
!lkw 31.03.2023
          arg13 = 1/(2*pi)
          result10 = SQRT(arg13)
          CALL EXPU2_DV(min1, min1d, result20, result20d, nbdirs)
          temp2 = result10*qe*s1*abs1
          DO nd=1,nbdirs
            fched(nd) = temp2*(vte*result20*dvd%ne(nd, icv1)+dv%ne(icv1)&
&             *(result20*vted(nd)+vte*result20d(nd)))
          END DO
          fche = temp2*(dv%ne(icv1)*(vte*result20))
          seec = gammae
          IF (fchi .LT. (1.0_R8-seec)*fche) THEN
            DO nd=1,nbdirs
              max2d(nd) = (1.0_R8-seec)*fched(nd)
            END DO
            max2 = (1.0_R8-seec)*fche
          ELSE
            DO nd=1,nbdirs
              max2d(nd) = fchid(nd)
            END DO
            max2 = fchi
          END IF
          temp2 = max2/pl%te(icv1)
          t0 = qe*temp2
          DO nd=1,nbdirs
            t0d(nd) = qe*(max2d(nd)-temp2*pld%te(nd, icv1))/pl%te(icv1)
!    ..compute charge source
            srwd%sch0(nd, icv1, 0) = (1.0_R8-seec)*fched(nd) - fchid(nd)&
&             + pl%po(icv1)*t0d(nd) + t0*pld%po(nd, icv1)
            srwd%sch0(nd, icv1, 1) = -t0d(nd)
          END DO
          srw%sch0(icv1, 0) = (1.0_R8-seec)*fche - fchi + t0*pl%po(icv1)
          srw%sch0(icv1, 1) = -t0
!    ..compute the maximum difference between the left and right sides of the boundary condition
!srv 15.02.26 {
          fch_sch = srw%sch0(icv1, 0) + srw%sch0(icv1, 1)*pl%po(icv1)
          fch_bnd = dv%fch(ifc, 0) + dv%fch(ifc, 1)
          IF (mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1) .GT. 0.0_R8) fch_bnd = &
&             -fch_bnd
          res_bcpot11 = fch_sch - fch_bnd
          IF (res_bcpot11 .GE. 0.) THEN
            abs2 = res_bcpot11
          ELSE
            abs2 = -res_bcpot11
          END IF
          IF (fch_bnd .GE. 0.) THEN
            abs5 = fch_bnd
          ELSE
            abs5 = -fch_bnd
          END IF
          IF (abs2 .GE. abs5*switch%bcpot11_epsr + switch%bcpot11_epsa) &
&           conv_bcpot11 = .false.
          IF (res_bcpot11 .GE. 0.) THEN
            y2 = res_bcpot11
          ELSE
            y2 = -res_bcpot11
          END IF
          IF (mrs .LT. y2) THEN
            mrs = y2
          ELSE
            mrs = mrs
          END IF
        END IF
!wdk Todo: seecmodel
        wrong_flow = .false.
      END DO
    CASE (12) 
!
! -- BCPOT=12 -- Test condition for south core region ! Solovyev 07.04.14   !srv 03.03.15 {
! code here is a part of code from 50000 for istyle_cur_contr_on_S_and_N.eq.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,a)') 'BCPOT = 12 : Adding contributions ', &
&       'from diamagnetic and inertial currents ', 'on ', bcchar(ib), &
&       boundary_location(ib)
        IF (switch%istyle_cur_contr_on_s_and_n .EQ. 0 .OR. switch%&
&           istyle_cur_contr_on_s_and_n .EQ. 1) THEN
          WRITE(*, *) ' BCPOT=12 cannot be used when ', &
&         'istyle_cur_contr_on_S_and_N = 0 or 1'
          CALL XERRAB('faulty parameter istyle_cur_contr_on_S_and_N !')
        ELSE
          DO ibc=1,mpg%bccvp(ib, 2)
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL XERTST(mpg%cvonclosedsurface(icv1), &
&                 'BCPOT=12 intended for core boundaries only!')
          END DO
        END IF
      END IF
      result11 = MAXVAL(dv%facdrift)
      IF (result11 .NE. 0.0_R8) THEN
!       ..compute the source
        IF (bcpot_12_style .EQ. -1) THEN
!wdk with <fcBb(:,2)>
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = switch%b2stbc_phm0*bzaverage*geo%fcqalf(ifc, 1)*&
&             gonedbsq(ifc, 0)*geo%fcs(ifc)
            temp1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              fchy_diad(nd) = -(temp2*temp1*dv%facdrift(ifc)*pzaveraged(&
&               nd))
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_diad(nd)
            END DO
            fchy_dia = -(temp1*(dv%facdrift(ifc)*pzaverage)*temp2)
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            fchy_inertia = 0.0_R8
            DO nd=1,nbdirsmax
              fchy_inertiad(nd) = 0.d0
            END DO
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) THEN
                temp2 = 0.5_R8*switch%b2stbc_phm1*geo%fcs(ifc)*dv%&
&                 facdrift(ifc)*gonedbsq(ifc, 0)
                temp1 = mp*bzaverage*geo%fcqalf(ifc, 1)
                temp0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
                DO nd=1,nbdirs
                  fchy_inertiad(nd) = fchy_inertiad(nd) - temp2*temp1*&
&                   temp0*am(is)*naua2averaged(nd, is)
                END DO
                fchy_inertia = fchy_inertia - temp0*(am(is)*naua2average&
&                 (is))*temp1*temp2
              END IF
            END DO
            DO nd=1,nbdirs
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_inertiad(nd)
            END DO
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 0) THEN
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
!wdk now uses fcBb(iFc,2) instead of <fcBb(:,2)>
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%facdrift(ifc)*&
&             gonedbsq(ifc, 0)
            temp1 = geo%fcbb(ifc, 2)*geo%fcs(ifc)
            DO nd=1,nbdirs
              fchy_diad(nd) = -(temp2*temp1*geo%fcqalf(ifc, 1)*switch%&
&               b2stbc_phm0*pzaveraged(nd))
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_diad(nd)
            END DO
            fchy_dia = -(temp2*(temp1*(geo%fcqalf(ifc, 1)*(switch%&
&             b2stbc_phm0*pzaverage))))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            fchy_inertia = 0.0_R8
            DO nd=1,nbdirsmax
              fchy_inertiad(nd) = 0.d0
            END DO
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) THEN
                temp2 = 0.5_R8*switch%b2stbc_phm1*geo%fcbb(ifc, 2)*&
&                 gonedbsq(ifc, 0)*geo%fcs(ifc)
                temp1 = am(is)*mp*geo%fcqalf(ifc, 1)
                temp0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
                DO nd=1,nbdirs
                  fchy_inertiad(nd) = fchy_inertiad(nd) - temp2*temp1*&
&                   temp0*dv%facdrift(ifc)*naua2averaged(nd, is)
                END DO
                fchy_inertia = fchy_inertia - temp1*(temp0*(dv%facdrift(&
&                 ifc)*naua2average(is)))*temp2
              END IF
            END DO
            DO nd=1,nbdirs
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_inertiad(nd)
            END DO
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 1) THEN
!wdk experimental - use fchdia / fchinert as computed
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
!wdk now uses fcBb(iFc,2) instead of <fcBb(:,2)>
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              fchy_diad(nd) = temp2*(dvd%fchdia(nd, ifc, 0)+dvd%fchdia(&
&               nd, ifc, 1))
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_diad(nd)
            END DO
            fchy_dia = temp2*(dv%fchdia(ifc, 0)+dv%fchdia(ifc, 1))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              fchy_inertiad(nd) = temp2*(dvd%fchinert(nd, ifc, 0)+dvd%&
&               fchinert(nd, ifc, 1))
              srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - &
&               fchy_inertiad(nd)
            END DO
            fchy_inertia = temp2*(dv%fchinert(ifc, 0)+dv%fchinert(ifc, 1&
&             ))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 2) THEN
!wdk experimental - find constant potential (with
!    perturbation taken from flux tube just inside
!    domain) such that total current through core
!    is sum of dia + inert currents
!     ..compute average potential on core boundary
          t0 = 0.0_R8
          t1 = 0.0_R8
          t2 = 0.0_R8
          totflux = 0.0_R8
          totpar = 0.0_R8
          DO nd=1,nbdirsmax
            totfluxd(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t1d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            t2d(nd) = 0.d0
          END DO
          DO nd=1,nbdirsmax
            totpard(nd) = 0.d0
          END DO
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
          DO ib0=1,nbc
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
            IF (mpg%cvonclosedsurface(icv1)) THEN
              IF (bcpot(ib0) .NE. 12) CALL XERRAB(&
&                                      'BCPOT=12: incompatible core BCs'&
&                                          )
! loop over number of cells in the boundary
              DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
                icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
                icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
                DO nd=1,nbdirs
                  t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%po(nd, icv1)
                  t2d(nd) = t2d(nd) + geo%cvvol(icv2)*pld%po(nd, icv2)
                  totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fch(nd, ifc, &
&                   0)+dvd%fch(nd, ifc, 1))
                END DO
                t1 = t1 + geo%cvvol(icv2)*pl%po(icv1)
                t2 = t2 + geo%cvvol(icv2)*pl%po(icv2)
                totflux = totflux - temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1)&
&                 )
                temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
                DO nd=1,nbdirs
                  totpard(nd) = totpard(nd) - temp2*(dvd%fchdia(nd, ifc&
&                   , 0)+dvd%fchdia(nd, ifc, 1)+dvd%fchinert(nd, ifc, 0)&
&                   +dvd%fchinert(nd, ifc, 1))
                END DO
                totpar = totpar - temp2*(dv%fchdia(ifc, 0)+dv%fchdia(ifc&
&                 , 1)+dv%fchinert(ifc, 0)+dv%fchinert(ifc, 1))
              END DO
            END IF
          END DO
          DO nd=1,nbdirs
            t1d(nd) = t1d(nd)/t0
            t2d(nd) = t2d(nd)/t0
          END DO
          t1 = t1/t0
          t2 = t2/t0
          IF (potpar(ib, 2) .GT. 0.0_R8) THEN
            DO nd=1,nbdirs
              t3d(nd) = potpard(nd, ib, 2)
            END DO
            t3 = potpar(ib, 2)
          ELSE
            DO nd=1,nbdirsmax
              t3d(nd) = 0.d0
            END DO
          END IF
          IF (potpar(ib, 2) .LE. 0.0_R8) THEN
            t3 = switch%b2stbc_bc_ref_te
            DO nd=1,nbdirsmax
              t3d(nd) = 0.d0
            END DO
          END IF
          IF (totflux .GE. 0.) THEN
            DO nd=1,nbdirs
              x2d(nd) = totfluxd(nd)
            END DO
            x2 = totflux
          ELSE
            DO nd=1,nbdirs
              x2d(nd) = -totfluxd(nd)
            END DO
            x2 = -totflux
          END IF
          IF (x2 .LT. totpar) THEN
            IF (totpar .LT. 1.0e-10_R8) THEN
              max3 = 1.0e-10_R8
              DO nd=1,nbdirsmax
                max3d(nd) = 0.d0
              END DO
            ELSE
              DO nd=1,nbdirs
                max3d(nd) = totpard(nd)
              END DO
              max3 = totpar
            END IF
          ELSE IF (x2 .LT. 1.0e-10_R8) THEN
            max3 = 1.0e-10_R8
            DO nd=1,nbdirsmax
              max3d(nd) = 0.d0
            END DO
          ELSE
            DO nd=1,nbdirs
              max3d(nd) = x2d(nd)
            END DO
            max3 = x2
          END IF
          temp2 = t3/max3
          temp3 = -((totflux-totpar)*temp2) + 1.0_R8
          DO nd=1,nbdirs
            t4d(nd) = temp3*t1d(nd) - t1*(temp2*(totfluxd(nd)-totpard(nd&
&             ))+(totflux-totpar)*(t3d(nd)-temp2*max3d(nd))/max3)
          END DO
          t4 = temp3*t1
!       ..impose potential with perturbation
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = pbig*geo%fcs(ifc)
            DO nd=1,nbdirs
              srwd%sch0(nd, icv1, 0) = temp2*(pld%po(nd, icv2)+t4d(nd)-&
&               t2d(nd))
              srwd%sch0(nd, icv1, 1) = 0.d0
            END DO
            srw%sch0(icv1, 0) = temp2*(pl%po(icv2)+t4-t2)
            srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
          END DO
        ELSE
          CALL XERRAB('wrong value bcpot_12_style')
        END IF
      END IF
    CASE (13) 
!
! -- BCPOT=13 -- Test condition for south private & north regions ! Solovyev 07.04.14
! code here is a part of code from 50000 for istyle_cur_contr_on_S_and_N.eq.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,a)') 'Adding contributions ', &
&       'from all currents ', 'on ', bcchar(ib), boundary_location(ib)
        IF (switch%istyle_cur_contr_on_s_and_n .EQ. 0 .OR. switch%&
&           istyle_cur_contr_on_s_and_n .EQ. 1) THEN
          WRITE(*, *) ' BCPOT=13 cannot be used when ', &
&         'istyle_cur_contr_on_S_and_N = 0 or 1'
          CALL XERRAB('faulty parameter istyle_cur_contr_on_S_and_N !')
        ELSE
          DO ibc=1,mpg%bccvp(ib, 2)
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL XERTST(.NOT.mpg%cvonclosedsurface(icv1), &
&                 'BCPOT=13 not intended for core boundaries!')
          END DO
        END IF
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = srwd%sch0(nd, icv1, 0) - temp2*(dvd%&
&           fchdia(nd, ifc, 0)+dvd%fchdia(nd, ifc, 1)+dvd%fchin(nd, ifc&
&           , 0)+dvd%fchin(nd, ifc, 1)+dvd%fchvispar(nd, ifc, 0)+dvd%&
&           fchvispar(nd, ifc, 1)+dvd%fchvisq(nd, ifc, 0)+dvd%fchvisq(nd&
&           , ifc, 1)+dvd%fchviskt(nd, ifc, 0)+dvd%fchviskt(nd, ifc, 1)+&
&           dvd%fchvisper(nd, ifc, 0)+dvd%fchvisper(nd, ifc, 1)+dvd%&
&           fchinert(nd, ifc, 0)+dvd%fchinert(nd, ifc, 1))
        END DO
        srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - temp2*(dv%fchdia(ifc, 0)&
&         +dv%fchdia(ifc, 1)+dv%fchin(ifc, 0)+dv%fchin(ifc, 1)+dv%&
&         fchvispar(ifc, 0)+dv%fchvispar(ifc, 1)+dv%fchvisq(ifc, 0)+dv%&
&         fchvisq(ifc, 1)+dv%fchviskt(ifc, 0)+dv%fchviskt(ifc, 1)+dv%&
&         fchvisper(ifc, 0)+dv%fchvisper(ifc, 1)+dv%fchinert(ifc, 0)+dv%&
&         fchinert(ifc, 1))
!srv 03.03.15 }
      END DO
    CASE (14) 
!
! -- BCPOT=14 -- PRESCRIBE THE TOTAL CURRENT WITHOUT IMPOSING A
!                 SPECIFIC PROFILE. FOLLOW PROFILE OF 1st RING INSIDE.
!wdk    Intended use: core boundary, total PF boundary,...
!wdk    For testing purposes, use with care!
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                'BCPOT = 14 : specified total current '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      us = 0.0_R8
      t0 = 0.0_R8
      DO nd=1,nbdirsmax
        t0d(nd) = 0.d0
      END DO
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          t0d(nd) = t0d(nd) + temp2*(dvd%fch(nd, ifc, 0)+dvd%fch(nd, ifc&
&           , 1))
        END DO
        t0 = t0 + temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1))
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = geo%fcs(ifc)*(t0d(nd)-potpard(nd, ib&
&           , 1))/us - temp2*(dvd%fch(nd, ifc, 0)+dvd%fch(nd, ifc, 1))
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        srw%sch0(icv1, 0) = geo%fcs(ifc)*((t0-potpar(ib, 1))/us) - temp2&
&         *(dv%fch(ifc, 0)+dv%fch(ifc, 1))
        srw%sch0(icv1, 1) = 0.0_R8
      END DO
    CASE (15) 
!
! -- BCPOT=15 -- Feedback boundary condition on total current with constant potential
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCPOT = 15 : zero net anomalous current on '&
&                                   , bcchar(ib), boundary_location(ib)
!     ..compute average potential on boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      totflux = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = t0 + geo%fcs(ifc)
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          t1d(nd) = t1d(nd) + geo%fcs(ifc)*pld%po(nd, icv1)
          totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fch(nd, ifc, 0)+dvd%&
&           fch(nd, ifc, 1))
        END DO
        t1 = t1 + geo%fcs(ifc)*pl%po(icv1)
        totflux = totflux - temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1))
      END DO
      DO nd=1,nbdirs
        t1d(nd) = t1d(nd)/t0
        totpard(nd) = potpard(nd, ib, 1)
      END DO
      t1 = t1/t0
      totpar = potpar(ib, 1)
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        DO nd=1,nbdirs
          t3d(nd) = potpard(nd, ib, 2)
        END DO
        t3 = potpar(ib, 2)
      ELSE
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      IF (potpar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_te
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      IF (totflux .GE. 0.) THEN
        DO nd=1,nbdirs
          x3d(nd) = totfluxd(nd)
        END DO
        x3 = totflux
      ELSE
        DO nd=1,nbdirs
          x3d(nd) = -totfluxd(nd)
        END DO
        x3 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        DO nd=1,nbdirs
          y3d(nd) = totpard(nd)
        END DO
        y3 = totpar
      ELSE
        DO nd=1,nbdirs
          y3d(nd) = -totpard(nd)
        END DO
        y3 = -totpar
      END IF
      IF (x3 .LT. y3) THEN
        IF (y3 .LT. 1.0_R8) THEN
          max4 = 1.0_R8
          DO nd=1,nbdirsmax
            max4d(nd) = 0.d0
          END DO
        ELSE
          DO nd=1,nbdirs
            max4d(nd) = y3d(nd)
          END DO
          max4 = y3
        END IF
      ELSE IF (x3 .LT. 1.0_R8) THEN
        max4 = 1.0_R8
        DO nd=1,nbdirsmax
          max4d(nd) = 0.d0
        END DO
      ELSE
        DO nd=1,nbdirs
          max4d(nd) = x3d(nd)
        END DO
        max4 = x3
      END IF
      temp2 = t3/max4
      temp3 = -((totflux-totpar)*temp2) + 1.0_R8
      DO nd=1,nbdirs
        t2d(nd) = temp3*t1d(nd) - t1*(temp2*(totfluxd(nd)-totpard(nd))+(&
&         totflux-totpar)*(t3d(nd)-temp2*max4d(nd))/max4)
      END DO
      t2 = temp3*t1
      IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&               'bcpot=15: curr_flux, desired_flux, old/new potential, '&
&                                      , totflux, totpar, t1, t2
!     ..impose potential
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = geo%fcs(ifc)*pbig*t2d(nd)
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*t2
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (16) 
!
! -- BCPOT=16 -- Feedback boundary condition with constant potential    !Solovyev 22.03.14 !srv 29.09.15
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a)') &
&       'BCPOT = 16 : electric potential feedback by current on ', &
&       bcchar(ib), boundary_location(ib)
! add smth about #ifdef ASTRA here
! Init variables for BCPOT=16                                  { Solovyev 01.05.14
! square of delta between desired and calculated current
        cur_delta = 0.0_R8
! previous value of upper value
        prev_cur_delta = 0.0_R8
! step of approximation (set after 1st iteration)
        po_step = 0.0_R8
        coeff_16 = 1.0_R8
!************************************************************* } Solovyev 01.05.14
        scurpar = 0.0_R8
        DO nd=1,nbdirsmax
          scurpard(nd) = 0.d0
        END DO
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bcpot(ibw) .EQ. bcpot(ib)) THEN
            DO nd=1,nbdirs
              scurpard(nd) = scurpard(nd) + potpard(nd, ibw, 1)
            END DO
            scurpar = scurpar + potpar(ibw, 1)
          END IF
        END DO
        WRITE(*, *) 'SCURPAR = ', scurpar
!srv 29.09.15
        pos = 0.0_R8
        vs = 0.0_R8
        DO nd=1,nbdirsmax
          posd(nd) = 0.d0
        END DO
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bcpot(ibw) .EQ. bcpot(ib)) THEN
            DO ibc=1,mpg%bccvp(ibw, 2)
              icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
              DO nd=1,nbdirs
                posd(nd) = posd(nd) + geo%cvvol(icv)*pld%po(nd, icv)
              END DO
              pos = pos + pl%po(icv)*geo%cvvol(icv)
              vs = vs + geo%cvvol(icv)
            END DO
          END IF
        END DO
        DO nd=1,nbdirs
!srv 29.09.15 }
          posd(nd) = posd(nd)/vs
          po_prevd(nd) = posd(nd)
        END DO
        pos = pos/vs
        po_prev = pos
        WRITE(*, *) 'POS at 0 = ', pos
        DO nd=1,nbdirsmax
          prev_cur_deltad(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          coeff_16d(nd) = 0.d0
        END DO
      END IF
!srv 29.09.15 }
      IF (.NOT.once_bcpot) THEN
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
          totflux = 0.0_R8
          DO nd=1,nbdirsmax
            totfluxd(nd) = 0.d0
          END DO
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcpot(ibw) .EQ. bcpot(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
                DO nd=1,nbdirs
                  totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fch(nd, ifc, &
&                   0)+dvd%fch(nd, ifc, 1))
                END DO
                totflux = totflux - temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1)&
&                 )
              END DO
            END IF
          END DO
! The implementation is based on one step of Newton method
! { Solovyev 03.05.14
          DO nd=1,nbdirs
            cur_deltad(nd) = totfluxd(nd) - scurpard(nd)
          END DO
          cur_delta = totflux - scurpar
! } Solovyev 03.05.14
          IF (ncall_b2stbc_phys .EQ. 0) THEN
            WRITE(*, *) '# Newton'
! previous value of upper value
            DO nd=1,nbdirs
              prev_cur_deltad(nd) = cur_deltad(nd)
            END DO
            prev_cur_delta = cur_delta
          ELSE
!Solovyev 23.05.14
            IF (ncall_b2stbc_phys .EQ. 1) THEN
! Solovyev 23.05.14
!srv 29.09.15
              po_curr = 0.0_R8
              vs = 0.0_R8
              DO nd=1,nbdirsmax
                po_currd(nd) = 0.d0
              END DO
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bcene(ibw) .EQ. bcene(ib)) THEN
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    DO nd=1,nbdirs
                      po_currd(nd) = po_currd(nd) + geo%cvvol(icv)*pld%&
&                       po(nd, icv)
                    END DO
                    po_curr = po_curr + pl%po(icv)*geo%cvvol(icv)
                    vs = vs + geo%cvvol(icv)
                  END DO
                END IF
              END DO
!srv 29.09.15 }
              DO nd=1,nbdirs
                po_currd(nd) = po_currd(nd)/vs
              END DO
              po_curr = po_curr/vs
            END IF
! Solovyev 23.05.14
            IF (MOD(ncall_b2stbc_phys, bcpot_16_step) .EQ. 0) THEN
              IF (cur_delta - prev_cur_delta .GE. 0.) THEN
                abs3 = cur_delta - prev_cur_delta
              ELSE
                abs3 = -(cur_delta-prev_cur_delta)
              END IF
!Solovyev 23.05.14
              IF (abs3 .GT. 1.0e-20_R8) THEN
!{ Solovyev 24.05.14
                temp2 = (po_prev-po_curr)/(cur_delta-prev_cur_delta)
                DO nd=1,nbdirs
                  coeff_16d(nd) = (po_prevd(nd)-po_currd(nd)-temp2*(&
&                   cur_deltad(nd)-prev_cur_deltad(nd)))/(cur_delta-&
&                   prev_cur_delta)
                END DO
                coeff_16 = temp2
              END IF
              DO nd=1,nbdirs
!} Solovyev 24.05.14
                po_stepd(nd) = cur_delta*coeff_16d(nd) + coeff_16*&
&                 cur_deltad(nd)
                posd(nd) = po_currd(nd) + po_stepd(nd)
                prev_cur_deltad(nd) = cur_deltad(nd)
                po_prevd(nd) = po_currd(nd)
                po_currd(nd) = posd(nd)
              END DO
              po_step = coeff_16*cur_delta
              pos = po_curr + po_step
              prev_cur_delta = cur_delta
              po_prev = po_curr
              po_curr = pos
            END IF
          END IF
! end of implementation
!Solovyev 29.04.14 - test output to b2fdebug
          WRITE(*, *) 'ncall, totflux, POS', ncall_b2stbc_phys, totflux&
&         , pos
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcpot(ibw) .EQ. bcpot(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                DO nd=1,nbdirs
!Solovyev 27.04.14
                  srwd%sch0(nd, icv, 0) = geo%fcs(ifc)*pbig*posd(nd)
!Solovyev 27.04.14
                  srwd%sch0(nd, icv, 1) = 0.d0
                END DO
                srw%sch0(icv, 0) = pbig*pos*geo%fcs(ifc)
                srw%sch0(icv, 1) = -(pbig*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bcpot = .true.
        ELSE
          CALL XERRAB('B2STBC -- BCPOT=16, NOT AVAILABLE FOR N,W,E')
        END IF
      END IF
    CASE (17) 
!
! -- BCPOT=17 -- Feedback boundary condition on total current, imposing potential,
!                with same profile as neighbouring flux tube
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT = 17 : imposed current on ', &
&                                   bcchar(ib), boundary_location(ib)
!     ..compute average potential on boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the plasma cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = t0 + geo%fcs(ifc)
        t1 = t1 + geo%fcs(ifc)*pl%po(icv1)
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          t1d(nd) = geo%fcs(ifc)*pld%po(nd, icv2)
          totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fch(nd, ifc, 0)+dvd%&
&           fch(nd, ifc, 1))
        END DO
        t1 = t2 + geo%fcs(ifc)*pl%po(icv2)
        totflux = totflux - temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1))
      END DO
      DO nd=1,nbdirs
        t1d(nd) = t1d(nd)/t0
        totpard(nd) = potpard(nd, ib, 1)
      END DO
      t1 = t1/t0
      t2 = t2/t0
      totpar = potpar(ib, 1)
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        DO nd=1,nbdirs
          t3d(nd) = potpard(nd, ib, 2)
        END DO
        t3 = potpar(ib, 2)
      ELSE
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      IF (potpar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_te
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      IF (totflux .GE. 0.) THEN
        DO nd=1,nbdirs
          x4d(nd) = totfluxd(nd)
        END DO
        x4 = totflux
      ELSE
        DO nd=1,nbdirs
          x4d(nd) = -totfluxd(nd)
        END DO
        x4 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        DO nd=1,nbdirs
          y4d(nd) = totpard(nd)
        END DO
        y4 = totpar
      ELSE
        DO nd=1,nbdirs
          y4d(nd) = -totpard(nd)
        END DO
        y4 = -totpar
      END IF
      IF (x4 .LT. y4) THEN
        IF (y4 .LT. 1.0_R8) THEN
          max5 = 1.0_R8
          DO nd=1,nbdirsmax
            max5d(nd) = 0.d0
          END DO
        ELSE
          DO nd=1,nbdirs
            max5d(nd) = y4d(nd)
          END DO
          max5 = y4
        END IF
      ELSE IF (x4 .LT. 1.0_R8) THEN
        max5 = 1.0_R8
        DO nd=1,nbdirsmax
          max5d(nd) = 0.d0
        END DO
      ELSE
        DO nd=1,nbdirs
          max5d(nd) = x4d(nd)
        END DO
        max5 = x4
      END IF
      temp2 = t3/max5
      temp3 = -((totflux-totpar)*temp2) + 1.0_R8
      DO nd=1,nbdirs
        t4d(nd) = temp3*t1d(nd) - t1*(temp2*(totfluxd(nd)-totpard(nd))+(&
&         totflux-totpar)*(t3d(nd)-temp2*max5d(nd))/max5)
      END DO
      t4 = temp3*t1
      IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&               'bcpot=17: curr_flux, desired_flux, old/new potential, '&
&                                      , totflux, totpar, t1, t4
!     ..impose potential
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = pbig*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = temp2*(pld%po(nd, icv2)+t4d(nd))
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        srw%sch0(icv1, 0) = temp2*(pl%po(icv2)-t2+t4)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (18) 
!
! -- BCPOT=18 -- Nothing implemented
!
      CALL XERRAB('B2STBC -- BCPOT=18, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=19 -- Nothing implemented
!
    CASE (19) 
      CALL XERRAB('B2STBC -- BCPOT=19, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=20 -- Nothing implemented
!
    CASE (20) 
      CALL XERRAB('B2STBC -- BCPOT=20, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=21 -- constant potential scaled by potential on the ring bc_type21_ref away
!
    CASE (21) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCPOT = 21 : fixed potential (modified by nearby ring) ', &
&       potpar(ib, 1), ' with ', potpar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(potpar(ib, 2) .GT. 0.0_R8, &
&             'faulty parameter potpar2')
      END IF
      IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'N') .OR. bcchar(ib)&
&         .EQ. 'A') THEN
        poave = 0.0_R8
        neave = 0.0_R8
        DO nd=1,nbdirsmax
          poaved(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          neaved(nd) = 0.d0
        END DO
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          DO nd=1,nbdirs
            poaved(nd) = poaved(nd) + geo%cvvol(icv)*(dv%ne(icv)*pld%po(&
&             nd, icv)+pl%po(icv)*dvd%ne(nd, icv))
            neaved(nd) = neaved(nd) + geo%cvvol(icv)*dvd%ne(nd, icv)
          END DO
          poave = poave + pl%po(icv)*dv%ne(icv)*geo%cvvol(icv)
          neave = neave + dv%ne(icv)*geo%cvvol(icv)
        END DO
        DO nd=1,nbdirs
          poaved(nd) = (poaved(nd)-poave*neaved(nd)/neave)/neave
        END DO
        poave = poave/neave
        IF (potpar(ib, 2) .GT. 0.0_R8) THEN
          DO nd=1,nbdirs
            t3d(nd) = potpard(nd, ib, 2)
          END DO
          t3 = potpar(ib, 2)
        ELSE
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
        END IF
        IF (potpar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          DO nd=1,nbdirsmax
            t3d(nd) = 0.d0
          END DO
        END IF
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*geo%fcs(ifc)
          temp1 = t3/poave
          temp3 = pl%po(icv)*temp1 - t3 + 1.0_R8
          DO nd=1,nbdirs
            srwd%sch0(nd, icv, 0) = temp2*(temp3*potpard(nd, ib, 1)+&
&             potpar(ib, 1)*(temp1*pld%po(nd, icv)+pl%po(icv)*(t3d(nd)-&
&             temp1*poaved(nd))/poave-t3d(nd)))
            srwd%sch0(nd, icv, 1) = 0.d0
          END DO
          srw%sch0(icv, 0) = temp2*(potpar(ib, 1)*temp3)
          srw%sch0(icv, 1) = -(vbig*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCPOT=21, NOT AVAILABLE FOR W,E')
      END IF
    CASE (22) 
!
! -- BCPOT=22 -- Prescribe the value of the potential, with perturbation taken
!                from first flux tube in the domain
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT = 22 : specified potential ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCPOT=22 intended for core boundaries only!')
        END DO
      END IF
!     ..compute average potential on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            DO nd=1,nbdirs
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%po(nd, icv2)
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%po(icv2)
          END DO
        END IF
      END DO
      DO nd=1,nbdirs
        t1d(nd) = t1d(nd)/t0
      END DO
      t1 = t1/t0
!     ..impose potential with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = pbig*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = temp2*(pld%po(nd, icv2)+potpard(nd, &
&           ib, 1)-t1d(nd))
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        srw%sch0(icv1, 0) = temp2*(pl%po(icv2)+potpar(ib, 1)-t1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (23) 
!
! -- BCPOT=23 -- Feedback on the total current for the South core boundary, by imposing a flux surface
!                averaged potential, with poloidal perturbation taken from flux
!                tube just inside domain. The feedback is scaled with the ion temperature.
!               POTPAR(,,1) specifies the desired integral current through flux surfaces(A).
!               POTPAR(,,2) is the strength of the feedback
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT = 23 : specified potential ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCPOT=23 intended for core boundaries only!')
        END DO
      END IF
!     ..compute average potential on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
!lkw
      t4 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t2d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t4d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        totpard(nd) = 0.d0
      END DO
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bcpot(ib0) .NE. 23) CALL XERRAB(&
&                                      'BCPOT=23: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            temp2 = mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
            DO nd=1,nbdirs
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%po(nd, icv1)
              t2d(nd) = t2d(nd) + geo%cvvol(icv2)*pld%po(nd, icv2)
! lkw 10.09.2022{
              t4d(nd) = t4d(nd) + geo%cvvol(icv2)*pld%ti(nd, icv2)/qe
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fch(nd, ifc, 0)+&
&               dvd%fch(nd, ifc, 1))
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%po(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%po(icv2)
            t4 = t4 + geo%cvvol(icv2)*pl%ti(icv2)/qe
            totflux = totflux - temp2*(dv%fch(ifc, 0)+dv%fch(ifc, 1))
          END DO
          DO nd=1,nbdirs
            totpard(nd) = totpard(nd) + potpard(nd, ib0, 1)
          END DO
          totpar = totpar + potpar(ib0, 1)
        END IF
      END DO
      DO nd=1,nbdirs
        t1d(nd) = t1d(nd)/t0
        t2d(nd) = t2d(nd)/t0
        t4d(nd) = t4d(nd)/t0
      END DO
      t1 = t1/t0
      t2 = t2/t0
      t4 = t4/t0
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        DO nd=1,nbdirs
          t3d(nd) = potpard(nd, ib, 2)
        END DO
        t3 = potpar(ib, 2)
      ELSE
        t3 = switch%b2stbc_bc_ref_te
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      IF (totflux .GE. 0.) THEN
        DO nd=1,nbdirs
          x5d(nd) = totfluxd(nd)
        END DO
        x5 = totflux
      ELSE
        DO nd=1,nbdirs
          x5d(nd) = -totfluxd(nd)
        END DO
        x5 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        DO nd=1,nbdirs
          y5d(nd) = totpard(nd)
        END DO
        y5 = totpar
      ELSE
        DO nd=1,nbdirs
          y5d(nd) = -totpard(nd)
        END DO
        y5 = -totpar
      END IF
      IF (x5 .LT. y5) THEN
        IF (y5 .LT. 1.0e-10_R8) THEN
          max6 = 1.0e-10_R8
          DO nd=1,nbdirsmax
            max6d(nd) = 0.d0
          END DO
        ELSE
          DO nd=1,nbdirs
            max6d(nd) = y5d(nd)
          END DO
          max6 = y5
        END IF
      ELSE IF (x5 .LT. 1.0e-10_R8) THEN
        max6 = 1.0e-10_R8
        DO nd=1,nbdirsmax
          max6d(nd) = 0.d0
        END DO
      ELSE
        DO nd=1,nbdirs
          max6d(nd) = x5d(nd)
        END DO
        max6 = x5
      END IF
! lkw 10.09.2022}
      temp2 = (totflux-totpar)/max6
      DO nd=1,nbdirs
        t4d(nd) = t1d(nd) - temp2*(t3*t4d(nd)+t4*t3d(nd)) - t4*t3*(&
&         totfluxd(nd)-totpard(nd)-temp2*max6d(nd))/max6
      END DO
      t4 = t1 - t4*t3*temp2
!
!     ..impose potential with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = pbig*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%sch0(nd, icv1, 0) = temp2*(pld%po(nd, icv2)+t4d(nd)-t2d(&
&           nd))
          srwd%sch0(nd, icv1, 1) = 0.d0
        END DO
        srw%sch0(icv1, 0) = temp2*(pl%po(icv2)+t4-t2)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcpot(ib)
      CALL XERRAB('BCPOT out of bounds')
    END SELECT
!
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_POT_DV

!
  SUBROUTINE B2STBC_PHYS_POT(ib)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER :: ib, ib0, ibc, ibc0, ibw, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, vte, vbnd, s1, fche, fchi, t0, t1, t2, t3, t4, &
&   neave, poave, totpar, totflux, wrk, seec, fchy_dia, fchy_inertia
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    INTRINSIC MIN
    INTRINSIC MOD
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: y1
    REAL(kind=r8) :: y2
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: y3
    REAL(kind=r8) :: x4
    REAL(kind=r8) :: y4
    REAL(kind=r8) :: x5
    REAL(kind=r8) :: y5
    REAL(r8) :: y6
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: max1
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: max2
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: max3
    REAL(kind=r8) :: max4
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: max5
    REAL(kind=r8) :: max6
    REAL(kind=r8) :: abs4
    REAL(r8) :: min1
    REAL(kind=r8) :: abs5
    REAL(r8) :: arg12
    REAL(kind=r8) :: arg13
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8) :: result11
    INTRINSIC MAXVAL
!
! -- BOUNDARY CONDITIONS FOR POTENTIAL EQUATION --
!
    SELECT CASE  (bcpot(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCPOT=1 -- PRESCRIBE THE VALUE OF THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  1 : specified potential '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*potpar(ib, 1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCPOT=2 -- PRESCRIBE THE GRADIENT OF THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  2 : potential gradient ', &
&                                   potpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1 = INTVERTEX_S_NODIFF_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, &
&         pl%po)
        t2 = INTVERTEX_S_NODIFF_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, &
&         pl%po)
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(potpar(ib, 1)*(geo%fchc(&
&         ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2-t1)*geo%&
&         fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(&
&         ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%po(icv2))
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCPOT=3 -- SHEATH CONDITIONS, ELECTRON ENERGY TRANSMISSION
!
      CALL XERRAB('b2stbc_phys -- BCPOT = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCPOT = 11')
!
! -- BCPOT=4 -- PRESCRIBE THE VALUE OF THE POTENTIAL,
!                 WEAKLY A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'BCPOT =  4 : weak potential ', &
&       potpar(ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(potpar(ib, 2) .GT. 0.0_R8, &
&             'BCPOT = 4, POTPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = potpar(ib, 2)*geo%fcs(ifc)*potpar(ib, 1)
        srw%sch0(icv1, 1) = -(potpar(ib, 2)*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCPOT=5 -- PRESCRIBE THE CURRENT FLUX DENSITY PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCPOT =  5 : current flux density per area '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%sch0(icv, 0) = potpar(ib, 1)*geo%fcs(ifc)
        srw%sch0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCPOT=6 -- PRESCRIBE THE TOTAL CURRENT FLUX DENSITY FOR A
!                 CONSTANT POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                             'BCPOT =  6 : total current flux density '&
&                                   , potpar(ib, 1), &
&                                   ' with const potential on ', bcchar(&
&                                   ib), boundary_location(ib)
      CALL XERRAB('B2STBC -- BCPOT=6, NOT YET AVAILABLE')
!
! -- BCPOT=7 -- PRESCRIBE THE GIVEN PROFILE OF POTENTIAL
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') 'BCPOT = 7 : specified potential on ', bcchar(&
&       ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*bv_po(icv1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCPOT=8 -- PRESCRIBE THE TOTAL ELECTRON CURRENT WITH CONSTANT
!                 FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  8 : total current ', &
&                                   potpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = potpar(ib, 1)/us*geo%fcs(ifc)
        srw%sch0(icv1, 1) = 0.0_R8
      END DO
    CASE (9) 
!
! -- BCPOT=9 -- PRESCRIBE THE DECAY LENGTH FOR
!                 THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT =  9 : potential decay length ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(potpar(ib, 1) .NE. 0.0_R8, &
&             'BCPOT = 9, POTPAR(,1) = 0')
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%sch0(icv, 0) = 0.0_R8
        srw%sch0(icv, 1) = -(co%sig0(ifc)/potpar(ib, 1)*geo%fcs(ifc)/qe/&
&         dv%ne(icv))
      END DO
    CASE (10) 
!
! -- BCPOT=10 -- Feedback option for core
!                NOT YET TESTED!!!!!!!!!
!
      CALL XERRAB('b2stbc_phys -- BCPOT = 10 not adapted for WG')
!
! -- BCPOT=11 -- SHEATH CONDITION, CURRENT CONTINUITY                !srv 01.02.09 {
!
    CASE (11) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCPOT = 11 : sheath potential current continuity bc', &
&       ' with POTPAR(IB,2) =', potpar(ib, 2), ' gammae =', gammae, &
&       ' on ', bcchar(ib), boundary_location(ib)
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) CALL XERTST(bccon(is, ib) .EQ. 14, &
&                                        'When BCPOT=11, '//&
&                          'one must have BCCON=14 for all ion species!'&
&                                       )
        END DO
      END IF
!srv 15.02.26
      conv_bcpot11 = .true.
!srv 15.02.26
      mrs = 0.0_R8
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
!srv 15.02.26 {
        DO is=0,ns-1
          CALL CSBC_IS(icv1, ib, is, cs)
          CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), wrk)
!srv 15.02.26 }
        END DO
        arg12 = pl%te(icv1)/me
        vte = SQRT(arg12)
        t0 = 0.0_R8
        wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
        IF (wrk .GE. 0.) THEN
          abs0 = wrk
        ELSE
          abs0 = -wrk
        END IF
        IF (abs0 .LT. geo%qalfmin) THEN
          t1 = INTVERTEX_S_NODIFF_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol&
&           , pl%po)
          t2 = INTVERTEX_S_NODIFF_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol&
&           , pl%po)
          srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(-(cor9*(t2-t1)*geo%&
&           fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(&
&           ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1))+pl%po(icv2))
          srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
        ELSE
          s1 = geo%fcs(ifc)
          DO is=0,ns-1
            IF (.NOT.is_neutral(is)) THEN
              vbnd = (dv%vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb&
&               (ifc, 1, is)*geo%fcqalf(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib&
&               , 1)+ibc-1)
              IF (wrk .GE. 0.) THEN
                abs4 = wrk
              ELSE
                abs4 = -wrk
              END IF
              x1 = csbc(icv1, is)*abs4
              y1 = vbc(icv1, is)*SIGN(1.0_R8, wrk) + vbnd
              IF (x1 .LT. y1) THEN
                max1 = y1
              ELSE
                max1 = x1
              END IF
              t0 = t0 + rt%rza(icv1, is)*mompar(is, ib, 1)*s1*max1*pl%na&
&               (icv1, is)
            END IF
          END DO
          fchi = qe*t0
          IF (wrk .GE. 0.) THEN
            abs1 = wrk
          ELSE
            abs1 = -wrk
          END IF
          IF (-50.0_R8 .LT. -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)&
&             )) THEN
            y6 = -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1))
          ELSE
            y6 = -50.0_R8
          END IF
          IF (0.0_R8 .GT. y6) THEN
            min1 = y6
          ELSE
            min1 = 0.0_R8
          END IF
!lkw 31.03.2023
          arg13 = 1/(2*pi)
          result10 = SQRT(arg13)
          result20 = EXPU2(min1)
          fche = result10*qe*dv%ne(icv1)*vte*s1*abs1*result20
          seec = gammae
          IF (fchi .LT. (1.0_R8-seec)*fche) THEN
            max2 = (1.0_R8-seec)*fche
          ELSE
            max2 = fchi
          END IF
          t0 = max2*qe/pl%te(icv1)
!    ..compute charge source
          srw%sch0(icv1, 0) = (1.0_R8-seec)*fche - fchi + t0*pl%po(icv1)
          srw%sch0(icv1, 1) = -t0
!    ..compute the maximum difference between the left and right sides of the boundary condition
!srv 15.02.26 {
          fch_sch = srw%sch0(icv1, 0) + srw%sch0(icv1, 1)*pl%po(icv1)
          fch_bnd = dv%fch(ifc, 0) + dv%fch(ifc, 1)
          IF (mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1) .GT. 0.0_R8) fch_bnd = &
&             -fch_bnd
          res_bcpot11 = fch_sch - fch_bnd
          IF (res_bcpot11 .GE. 0.) THEN
            abs2 = res_bcpot11
          ELSE
            abs2 = -res_bcpot11
          END IF
          IF (fch_bnd .GE. 0.) THEN
            abs5 = fch_bnd
          ELSE
            abs5 = -fch_bnd
          END IF
          IF (abs2 .GE. abs5*switch%bcpot11_epsr + switch%bcpot11_epsa) &
&           conv_bcpot11 = .false.
          IF (res_bcpot11 .GE. 0.) THEN
            y2 = res_bcpot11
          ELSE
            y2 = -res_bcpot11
          END IF
          IF (mrs .LT. y2) THEN
            mrs = y2
          ELSE
            mrs = mrs
          END IF
        END IF
!wdk Todo: seecmodel
        wrong_flow = .false.
      END DO
    CASE (12) 
!
! -- BCPOT=12 -- Test condition for south core region ! Solovyev 07.04.14   !srv 03.03.15 {
! code here is a part of code from 50000 for istyle_cur_contr_on_S_and_N.eq.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,a)') 'BCPOT = 12 : Adding contributions ', &
&       'from diamagnetic and inertial currents ', 'on ', bcchar(ib), &
&       boundary_location(ib)
        IF (switch%istyle_cur_contr_on_s_and_n .EQ. 0 .OR. switch%&
&           istyle_cur_contr_on_s_and_n .EQ. 1) THEN
          WRITE(*, *) ' BCPOT=12 cannot be used when ', &
&         'istyle_cur_contr_on_S_and_N = 0 or 1'
          CALL XERRAB('faulty parameter istyle_cur_contr_on_S_and_N !')
        ELSE
          DO ibc=1,mpg%bccvp(ib, 2)
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL XERTST(mpg%cvonclosedsurface(icv1), &
&                 'BCPOT=12 intended for core boundaries only!')
          END DO
        END IF
      END IF
      result11 = MAXVAL(dv%facdrift)
      IF (result11 .NE. 0.0_R8) THEN
!       ..compute the source
        IF (bcpot_12_style .EQ. -1) THEN
!wdk with <fcBb(:,2)>
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            fchy_dia = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*switch%&
&             b2stbc_phm0*pzaverage*dv%facdrift(ifc)*bzaverage*gonedbsq(&
&             ifc, 0)*geo%fcs(ifc)*geo%fcqalf(ifc, 1))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            fchy_inertia = 0.0_R8
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) fchy_inertia = fchy_inertia - mpg&
&                 %bcfcor(mpg%bccvp(ib, 1)+ibc-1)*switch%b2stbc_phm1*&
&                 0.5_R8*am(is)*mp*naua2average(is)*dv%facdrift(ifc)*&
&                 bzaverage*gonedbsq(ifc, 0)*geo%fcs(ifc)*geo%fcqalf(ifc&
&                 , 1)
            END DO
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 0) THEN
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
!wdk now uses fcBb(iFc,2) instead of <fcBb(:,2)>
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            fchy_dia = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*switch%&
&             b2stbc_phm0*pzaverage*dv%facdrift(ifc)*geo%fcbb(ifc, 2)*&
&             gonedbsq(ifc, 0)*geo%fcs(ifc)*geo%fcqalf(ifc, 1))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            fchy_inertia = 0.0_R8
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) fchy_inertia = fchy_inertia - mpg&
&                 %bcfcor(mpg%bccvp(ib, 1)+ibc-1)*switch%b2stbc_phm1*&
&                 0.5_R8*am(is)*mp*naua2average(is)*dv%facdrift(ifc)*geo&
&                 %fcbb(ifc, 2)*gonedbsq(ifc, 0)*geo%fcs(ifc)*geo%fcqalf&
&                 (ifc, 1)
            END DO
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 1) THEN
!wdk experimental - use fchdia / fchinert as computed
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
!wdk now uses fcBb(iFc,2) instead of <fcBb(:,2)>
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            fchy_dia = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fchdia(ifc&
&             , 0)+dv%fchdia(ifc, 1))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            fchy_inertia = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%&
&             fchinert(ifc, 0)+dv%fchinert(ifc, 1))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 2) THEN
!wdk experimental - find constant potential (with
!    perturbation taken from flux tube just inside
!    domain) such that total current through core
!    is sum of dia + inert currents
!     ..compute average potential on core boundary
          t0 = 0.0_R8
          t1 = 0.0_R8
          t2 = 0.0_R8
          totflux = 0.0_R8
          totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
          DO ib0=1,nbc
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
            IF (mpg%cvonclosedsurface(icv1)) THEN
              IF (bcpot(ib0) .NE. 12) CALL XERRAB(&
&                                      'BCPOT=12: incompatible core BCs'&
&                                          )
! loop over number of cells in the boundary
              DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
                icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
                icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + geo%cvvol(icv2)*pl%po(icv1)
                t2 = t2 + geo%cvvol(icv2)*pl%po(icv2)
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)&
&                 *(dv%fch(ifc, 0)+dv%fch(ifc, 1))
                totpar = totpar - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)*(&
&                 dv%fchdia(ifc, 0)+dv%fchdia(ifc, 1)+dv%fchinert(ifc, 0&
&                 )+dv%fchinert(ifc, 1))
              END DO
            END IF
          END DO
          t1 = t1/t0
          t2 = t2/t0
          IF (potpar(ib, 2) .GT. 0.0_R8) t3 = potpar(ib, 2)
          IF (potpar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
          IF (totflux .GE. 0.) THEN
            x2 = totflux
          ELSE
            x2 = -totflux
          END IF
          IF (x2 .LT. totpar) THEN
            IF (totpar .LT. 1.0e-10_R8) THEN
              max3 = 1.0e-10_R8
            ELSE
              max3 = totpar
            END IF
          ELSE IF (x2 .LT. 1.0e-10_R8) THEN
            max3 = 1.0e-10_R8
          ELSE
            max3 = x2
          END IF
          t4 = (1.0_R8-t3*(totflux-totpar)/max3)*t1
!       ..impose potential with perturbation
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(pl%po(icv2)+t4-t2)
            srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
          END DO
        ELSE
          CALL XERRAB('wrong value bcpot_12_style')
        END IF
      END IF
    CASE (13) 
!
! -- BCPOT=13 -- Test condition for south private & north regions ! Solovyev 07.04.14
! code here is a part of code from 50000 for istyle_cur_contr_on_S_and_N.eq.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,a)') 'Adding contributions ', &
&       'from all currents ', 'on ', bcchar(ib), boundary_location(ib)
        IF (switch%istyle_cur_contr_on_s_and_n .EQ. 0 .OR. switch%&
&           istyle_cur_contr_on_s_and_n .EQ. 1) THEN
          WRITE(*, *) ' BCPOT=13 cannot be used when ', &
&         'istyle_cur_contr_on_S_and_N = 0 or 1'
          CALL XERRAB('faulty parameter istyle_cur_contr_on_S_and_N !')
        ELSE
          DO ibc=1,mpg%bccvp(ib, 2)
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL XERTST(.NOT.mpg%cvonclosedsurface(icv1), &
&                 'BCPOT=13 not intended for core boundaries!')
          END DO
        END IF
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - mpg%bcfcor(mpg%bccvp(ib&
&         , 1)+ibc-1)*(dv%fchdia(ifc, 0)+dv%fchdia(ifc, 1)+dv%fchin(ifc&
&         , 0)+dv%fchin(ifc, 1)+dv%fchvispar(ifc, 0)+dv%fchvispar(ifc, 1&
&         )+dv%fchvisq(ifc, 0)+dv%fchvisq(ifc, 1)+dv%fchviskt(ifc, 0)+dv&
&         %fchviskt(ifc, 1)+dv%fchvisper(ifc, 0)+dv%fchvisper(ifc, 1)+dv&
&         %fchinert(ifc, 0)+dv%fchinert(ifc, 1))
!srv 03.03.15 }
      END DO
    CASE (14) 
!
! -- BCPOT=14 -- PRESCRIBE THE TOTAL CURRENT WITHOUT IMPOSING A
!                 SPECIFIC PROFILE. FOLLOW PROFILE OF 1st RING INSIDE.
!wdk    Intended use: core boundary, total PF boundary,...
!wdk    For testing purposes, use with care!
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                'BCPOT = 14 : specified total current '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      us = 0.0_R8
      t0 = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
        t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fch(ifc, 0)+dv%&
&         fch(ifc, 1))
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fch&
&         (ifc, 0)+dv%fch(ifc, 1))) + (t0-potpar(ib, 1))/us*geo%fcs(ifc)
        srw%sch0(icv1, 1) = 0.0_R8
      END DO
    CASE (15) 
!
! -- BCPOT=15 -- Feedback boundary condition on total current with constant potential
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCPOT = 15 : zero net anomalous current on '&
&                                   , bcchar(ib), boundary_location(ib)
!     ..compute average potential on boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      totflux = 0.0_R8
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = t0 + geo%fcs(ifc)
        t1 = t1 + geo%fcs(ifc)*pl%po(icv1)
        totflux = totflux - (dv%fch(ifc, 0)+dv%fch(ifc, 1))*mpg%bcfcor(&
&         mpg%bccvp(ib, 1)+ibc-1)
      END DO
      t1 = t1/t0
      totpar = potpar(ib, 1)
      IF (potpar(ib, 2) .GT. 0.0_R8) t3 = potpar(ib, 2)
      IF (potpar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
      IF (totflux .GE. 0.) THEN
        x3 = totflux
      ELSE
        x3 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y3 = totpar
      ELSE
        y3 = -totpar
      END IF
      IF (x3 .LT. y3) THEN
        IF (y3 .LT. 1.0_R8) THEN
          max4 = 1.0_R8
        ELSE
          max4 = y3
        END IF
      ELSE IF (x3 .LT. 1.0_R8) THEN
        max4 = 1.0_R8
      ELSE
        max4 = x3
      END IF
      t2 = (1.0_R8-t3*(totflux-totpar)/max4)*t1
      IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&               'bcpot=15: curr_flux, desired_flux, old/new potential, '&
&                                      , totflux, totpar, t1, t2
!     ..impose potential
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*t2
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (16) 
!
! -- BCPOT=16 -- Feedback boundary condition with constant potential    !Solovyev 22.03.14 !srv 29.09.15
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a)') &
&       'BCPOT = 16 : electric potential feedback by current on ', &
&       bcchar(ib), boundary_location(ib)
! add smth about #ifdef ASTRA here
! Init variables for BCPOT=16                                  { Solovyev 01.05.14
! square of delta between desired and calculated current
        cur_delta = 0.0_R8
! previous value of upper value
        prev_cur_delta = 0.0_R8
! step of approximation (set after 1st iteration)
        po_step = 0.0_R8
        coeff_16 = 1.0_R8
!************************************************************* } Solovyev 01.05.14
        scurpar = 0.0_R8
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bcpot(ibw) .EQ. bcpot(ib)) scurpar = scurpar + potpar(ibw&
&             , 1)
        END DO
        WRITE(*, *) 'SCURPAR = ', scurpar
!srv 29.09.15
        pos = 0.0_R8
        vs = 0.0_R8
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bcpot(ibw) .EQ. bcpot(ib)) THEN
            DO ibc=1,mpg%bccvp(ibw, 2)
              icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
              pos = pos + pl%po(icv)*geo%cvvol(icv)
              vs = vs + geo%cvvol(icv)
            END DO
          END IF
        END DO
!srv 29.09.15 }
        pos = pos/vs
        po_prev = pos
        WRITE(*, *) 'POS at 0 = ', pos
      END IF
!srv 29.09.15 }
      IF (.NOT.once_bcpot) THEN
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
          totflux = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcpot(ibw) .EQ. bcpot(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(&
&                 dv%fch(ifc, 0)+dv%fch(ifc, 1))
              END DO
            END IF
          END DO
! The implementation is based on one step of Newton method
! { Solovyev 03.05.14
          cur_delta = totflux - scurpar
! } Solovyev 03.05.14
          IF (ncall_b2stbc_phys .EQ. 0) THEN
            WRITE(*, *) '# Newton'
! previous value of upper value
            prev_cur_delta = cur_delta
          ELSE
!Solovyev 23.05.14
            IF (ncall_b2stbc_phys .EQ. 1) THEN
! Solovyev 23.05.14
!srv 29.09.15
              po_curr = 0.0_R8
              vs = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bcene(ibw) .EQ. bcene(ib)) THEN
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    po_curr = po_curr + pl%po(icv)*geo%cvvol(icv)
                    vs = vs + geo%cvvol(icv)
                  END DO
                END IF
              END DO
!srv 29.09.15 }
              po_curr = po_curr/vs
            END IF
! Solovyev 23.05.14
            IF (MOD(ncall_b2stbc_phys, bcpot_16_step) .EQ. 0) THEN
              IF (cur_delta - prev_cur_delta .GE. 0.) THEN
                abs3 = cur_delta - prev_cur_delta
              ELSE
                abs3 = -(cur_delta-prev_cur_delta)
              END IF
!Solovyev 23.05.14
              IF (abs3 .GT. 1.0e-20_R8) THEN
!{ Solovyev 24.05.14
                coeff_16 = (po_prev-po_curr)/(cur_delta-prev_cur_delta)
              END IF
!} Solovyev 24.05.14
              po_step = coeff_16*cur_delta
              pos = po_curr + po_step
              prev_cur_delta = cur_delta
              po_prev = po_curr
              po_curr = pos
            END IF
          END IF
! end of implementation
!Solovyev 29.04.14 - test output to b2fdebug
          WRITE(*, *) 'ncall, totflux, POS', ncall_b2stbc_phys, totflux&
&         , pos
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcpot(ibw) .EQ. bcpot(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
!Solovyev 27.04.14
                srw%sch0(icv, 0) = pbig*pos*geo%fcs(ifc)
!Solovyev 27.04.14
                srw%sch0(icv, 1) = -(pbig*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bcpot = .true.
        ELSE
          CALL XERRAB('B2STBC -- BCPOT=16, NOT AVAILABLE FOR N,W,E')
        END IF
      END IF
    CASE (17) 
!
! -- BCPOT=17 -- Feedback boundary condition on total current, imposing potential,
!                with same profile as neighbouring flux tube
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT = 17 : imposed current on ', &
&                                   bcchar(ib), boundary_location(ib)
!     ..compute average potential on boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the plasma cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = t0 + geo%fcs(ifc)
        t1 = t1 + geo%fcs(ifc)*pl%po(icv1)
        t1 = t2 + geo%fcs(ifc)*pl%po(icv2)
        totflux = totflux - (dv%fch(ifc, 0)+dv%fch(ifc, 1))*mpg%bcfcor(&
&         mpg%bccvp(ib, 1)+ibc-1)
      END DO
      t1 = t1/t0
      t2 = t2/t0
      totpar = potpar(ib, 1)
      IF (potpar(ib, 2) .GT. 0.0_R8) t3 = potpar(ib, 2)
      IF (potpar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
      IF (totflux .GE. 0.) THEN
        x4 = totflux
      ELSE
        x4 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y4 = totpar
      ELSE
        y4 = -totpar
      END IF
      IF (x4 .LT. y4) THEN
        IF (y4 .LT. 1.0_R8) THEN
          max5 = 1.0_R8
        ELSE
          max5 = y4
        END IF
      ELSE IF (x4 .LT. 1.0_R8) THEN
        max5 = 1.0_R8
      ELSE
        max5 = x4
      END IF
      t4 = (1.0_R8-t3*(totflux-totpar)/max5)*t1
      IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&               'bcpot=17: curr_flux, desired_flux, old/new potential, '&
&                                      , totflux, totpar, t1, t4
!     ..impose potential
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(pl%po(icv2)+t4-t2)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (18) 
!
! -- BCPOT=18 -- Nothing implemented
!
      CALL XERRAB('B2STBC -- BCPOT=18, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=19 -- Nothing implemented
!
    CASE (19) 
      CALL XERRAB('B2STBC -- BCPOT=19, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=20 -- Nothing implemented
!
    CASE (20) 
      CALL XERRAB('B2STBC -- BCPOT=20, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=21 -- constant potential scaled by potential on the ring bc_type21_ref away
!
    CASE (21) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCPOT = 21 : fixed potential (modified by nearby ring) ', &
&       potpar(ib, 1), ' with ', potpar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(potpar(ib, 2) .GT. 0.0_R8, &
&             'faulty parameter potpar2')
      END IF
      IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'N') .OR. bcchar(ib)&
&         .EQ. 'A') THEN
        poave = 0.0_R8
        neave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          poave = poave + pl%po(icv)*dv%ne(icv)*geo%cvvol(icv)
          neave = neave + dv%ne(icv)*geo%cvvol(icv)
        END DO
        poave = poave/neave
        IF (potpar(ib, 2) .GT. 0.0_R8) t3 = potpar(ib, 2)
        IF (potpar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sch0(icv, 0) = vbig*potpar(ib, 1)*geo%fcs(ifc)*(1.0_R8-t3+&
&           t3*pl%po(icv)/poave)
          srw%sch0(icv, 1) = -(vbig*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCPOT=21, NOT AVAILABLE FOR W,E')
      END IF
    CASE (22) 
!
! -- BCPOT=22 -- Prescribe the value of the potential, with perturbation taken
!                from first flux tube in the domain
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT = 22 : specified potential ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCPOT=22 intended for core boundaries only!')
        END DO
      END IF
!     ..compute average potential on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%po(icv2)
          END DO
        END IF
      END DO
      t1 = t1/t0
!     ..impose potential with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(pl%po(icv2)+potpar(ib, 1)&
&         -t1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (23) 
!
! -- BCPOT=23 -- Feedback on the total current for the South core boundary, by imposing a flux surface
!                averaged potential, with poloidal perturbation taken from flux
!                tube just inside domain. The feedback is scaled with the ion temperature.
!               POTPAR(,,1) specifies the desired integral current through flux surfaces(A).
!               POTPAR(,,2) is the strength of the feedback
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT = 23 : specified potential ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCPOT=23 intended for core boundaries only!')
        END DO
      END IF
!     ..compute average potential on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
!lkw
      t4 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bcpot(ib0) .NE. 23) CALL XERRAB(&
&                                      'BCPOT=23: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%po(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%po(icv2)
! lkw 10.09.2022{
            t4 = t4 + geo%cvvol(icv2)*pl%ti(icv2)/qe
            totflux = totflux - (dv%fch(ifc, 0)+dv%fch(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
          END DO
          totpar = totpar + potpar(ib0, 1)
        END IF
      END DO
      t1 = t1/t0
      t2 = t2/t0
      t4 = t4/t0
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        t3 = potpar(ib, 2)
      ELSE
        t3 = switch%b2stbc_bc_ref_te
      END IF
      IF (totflux .GE. 0.) THEN
        x5 = totflux
      ELSE
        x5 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y5 = totpar
      ELSE
        y5 = -totpar
      END IF
      IF (x5 .LT. y5) THEN
        IF (y5 .LT. 1.0e-10_R8) THEN
          max6 = 1.0e-10_R8
        ELSE
          max6 = y5
        END IF
      ELSE IF (x5 .LT. 1.0e-10_R8) THEN
        max6 = 1.0e-10_R8
      ELSE
        max6 = x5
      END IF
! lkw 10.09.2022}
      t4 = t1 - t4*t3*(totflux-totpar)/max6
!
!     ..impose potential with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(pl%po(icv2)+t4-t2)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcpot(ib)
      CALL XERRAB('BCPOT out of bounds')
    END SELECT
!
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_POT

!  Differentiation of b2stbc_phys_enk_dv in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: *(srwd.skt0) *(srw.skt0)
!   with respect to varying inputs: conpar conpard mompar enkpar
!                *(srwd.skt0) *(dv.fna) *(dv.fhe) *(dv.fhi) *(dv.fkt)
!                *(dv.ni) *(dvd.fna) *(dvd.fhe) *(dvd.fhi) *(dvd.fkt)
!                *(dvd.ni) *(srw.skt0) switch.b2tfhi_fflokt *(cod.dna0)
!                *(co.dna0) *(pld.na) *(pld.kt) *(pl.na) *(pl.kt)
!                pzd rzd rz pz
!   Plus diff mem management of: srwd.skt0:in dv.fna:in dv.fhe:in
!                dv.fhi:in dv.fkt:in dv.ni:in geo.vxvol:in dvd.fna:in
!                dvd.fhe:in dvd.fhi:in dvd.fkt:in dvd.ni:in srw.skt0:in
!                cod.dna0:in co.dna0:in pld.na:in pld.kt:in pl.na:in
!                pl.kt:in
!  Differentiation of b2stbc_phys_enk in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: *(srw.skt0)
!   with respect to varying inputs: conpar mompar enkpar *(dv.fna)
!                *(dv.fhe) *(dv.fhi) *(dv.fkt) *(dv.ni) *(srw.skt0)
!                switch.b2tfhi_fflokt *(co.dna0) *(pl.na) *(pl.kt)
!                rz pz
!   Plus diff mem management of: dv.fna:in dv.fhe:in dv.fhi:in
!                dv.fkt:in dv.ni:in mpg.bcfcor:in geo.vxvol:in
!                srw.skt0:in co.dna0:in pl.na:in pl.kt:in
!
  SUBROUTINE B2STBC_PHYS_ENK_DV_DV(ib, nbdirs, nbdirs0)
    USE B2MOD_DIFFSIZES
!  Hint: nbdirsmax0 should be the maximum number of differentiation directions
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: ib, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, t0, t1, t2, t3, t4, totpar, totflux
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: csd0, t0d0, t1d0, t2d0, t3d0&
&   , t4d0, totpard0, totfluxd0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd, t0d, t1d, t2d, t3d, t4d&
&   , totpard, totfluxd
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: csdd, t0dd, t1dd&
&   , t2dd, t4dd, totfluxdd
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: x1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: x1dd
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: max1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: max1d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max1d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: max1dd
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: arg12d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg12dd
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp1d
    REAL(kind=r8) :: temp2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp2d
    REAL(r8) :: temp3
    REAL(r8), DIMENSION(nbdirsmax0) :: temp3d
    INTEGER :: nbdirs
    INTEGER :: nd0
    REAL(r8) :: temp4
    REAL(r8) :: temp5
    REAL(kind=r8) :: temp6
    REAL(kind=r8) :: temp7
    REAL(kind=r8) :: temp8
    INTEGER :: nbdirs0
!
! -- BOUNDARY CONDITIONS FOR TURBULENT KINETIC ENERGY EQUATION --
!
    SELECT CASE  (bcenk(ib)) 
    CASE (0) 
!
!
! -- BCENK=1 -- PRESCRIBE THE VALUE OF KT
!

    CASE (1) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified kt ', enkpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 1, ENKPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp = geo%fcs(ifc)*ev
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%skt0(nd0, nd, icv1, 0) = 0.D0
            srwdd%skt0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%skt0(nd, icv1, 0) = temp*vbig*ne00*enkpard(nd, ib, 1)
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%skt0(nd0, icv1, 0) = vbig*ne00*temp*enkpard0(nd0, ib, 1)
          srwd0%skt0(nd0, icv1, 1) = 0.D0
        END DO
        srw%skt0(icv1, 0) = vbig*ne00*enkpar(ib, 1)*temp
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENK=2 -- PRESCRIBE THE GRADIENT OF THE TURB. KIN. ENERGY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. kin. en. gradient ', enkpar(&
&                                   ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
!wdk    Note: specifies the gradient in the outward normal direction
!wdk    Tmp: in "connector" direction - ok for orthogonal grids
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1dd = 0.D0
        CALL INTVERTEX_S_DV_DV(ivx1, ncv, nvx, mpg, geo%vxvol, pl%kt, &
&                        pld0%kt, pld%kt, pldd%kt, t1, t1d0, t1d, t1dd, &
&                        nbdirs, nbdirs0)
        t2dd = 0.D0
        CALL INTVERTEX_S_DV_DV(ivx2, ncv, nvx, mpg, geo%vxvol, pl%kt, &
&                        pld0%kt, pld%kt, pldd%kt, t2, t2d0, t2d, t2dd, &
&                        nbdirs, nbdirs0)
        temp = vbig*ne00*geo%fcs(ifc)
        temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
        temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, &
&         2))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%skt0(nd0, nd, icv1, 0) = temp*(pldd%kt(nd0, nd, icv2)-&
&             temp1*temp2*(t2dd(nd0, nd)-t1dd(nd0, nd))/geo%fcht(ifc))
            srwdd%skt0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%skt0(nd, icv1, 0) = temp*(temp0*geo%fcqgam(ifc, 0)*ev*&
&           enkpard(nd, ib, 1)-temp1*temp2*(t2d(nd)-t1d(nd))/geo%fcht(&
&           ifc)+pld%kt(nd, icv2))
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%skt0(nd0, icv1, 0) = temp*(temp0*ev*geo%fcqgam(ifc, 0)*&
&           enkpard0(nd0, ib, 1)-temp1*temp2*(t2d0(nd0)-t1d0(nd0))/geo%&
&           fcht(ifc)+pld0%kt(nd0, icv2))
          srwd0%skt0(nd0, icv1, 1) = 0.D0
        END DO
        srw%skt0(icv1, 0) = temp*(temp0*(geo%fcqgam(ifc, 0)*(ev*enkpar(&
&         ib, 1)))-temp1*(temp2*((t2-t1)/geo%fcht(ifc)))+pl%kt(icv2))
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENK=3 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENK=3, NOT AVAILABLE')
!
! -- BCENK=4 -- not implemented
!
    CASE (4) 
      CALL XERRAB('B2STBC -- BCENK=4, NOT AVAILABLE')
!
! -- BCENK=5 -- not implemented
!
    CASE (5) 
      CALL XERRAB('B2STBC -- BCENK=5, NOT AVAILABLE')
!
! -- BCENK=6 -- Prescribe the total flux of kt, following the
!               profile of fhi + fhe
!
    CASE (6) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=6 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'turb. kin. energy flux ', enkpar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
      END IF
!     ..compute total ion+electron heat flux, and total kt flux
      totflux = 0.0_R8
      totpar = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        totpard(nd) = 0.d0
      END DO
      totfluxd0 = 0.D0
      totpard0 = 0.D0
      totfluxdd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 6) CALL XERRAB(&
&                                      'BCENK=6: incompatible core BCs')
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%&
&                 fhe(nd0, nd, ifc, 0)+dvdd%fhe(nd0, nd, ifc, 1)+dvdd%&
&                 fhi(nd0, nd, ifc, 0)+dvdd%fhi(nd0, nd, ifc, 1))
              END DO
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhe(nd, ifc, 0)+&
&               dvd%fhe(nd, ifc, 1)+dvd%fhi(nd, ifc, 0)+dvd%fhi(nd, ifc&
&               , 1))
            END DO
            DO nd0=1,nbdirs0
              totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fhe(nd0, ifc&
&               , 0)+dvd0%fhe(nd0, ifc, 1)+dvd0%fhi(nd0, ifc, 0)+dvd0%&
&               fhi(nd0, ifc, 1))
            END DO
            totflux = totflux - temp2*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%&
&             fhi(ifc, 0)+dv%fhi(ifc, 1))
          END DO
          DO nd=1,nbdirs
            totpard(nd) = totpard(nd) + enkpard(nd, ib0, 1)
          END DO
          DO nd0=1,nbdirs0
            totpard0(nd0) = totpard0(nd0) + enkpard0(nd0, ib0, 1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
!     ..impose the flux
      WRITE(*, *) 'BCENK=6, totflux = ', totflux, ', totpar = ', totpar
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd0=1,nbdirs0
          temp1d(nd0) = (totpard0(nd0)-totpar*totfluxd0(nd0)/totflux)/&
&           totflux
          temp3d(nd0) = dvd0%fhe(nd0, ifc, 0) + dvd0%fhe(nd0, ifc, 1) + &
&           dvd0%fhi(nd0, ifc, 0) + dvd0%fhi(nd0, ifc, 1)
        END DO
        temp1 = totpar/totflux
        temp3 = dv%fhe(ifc, 0) + dv%fhe(ifc, 1) + dv%fhi(ifc, 0) + dv%&
&         fhi(ifc, 1)
        DO nd=1,nbdirs
          temp4 = dvd%fhe(nd, ifc, 0) + dvd%fhe(nd, ifc, 1) + dvd%fhi(nd&
&           , ifc, 0) + dvd%fhi(nd, ifc, 1)
          temp5 = temp3/totflux
          temp6 = totpard(nd) - temp1*totfluxd(nd)
          DO nd0=1,nbdirs0
            srwdd%skt0(nd0, nd, icv1, 0) = -(temp2*(temp4*temp1d(nd0)+&
&             temp1*(dvdd%fhe(nd0, nd, ifc, 0)+dvdd%fhe(nd0, nd, ifc, 1)&
&             +dvdd%fhi(nd0, nd, ifc, 0)+dvdd%fhi(nd0, nd, ifc, 1))-&
&             temp5*(totfluxd(nd)*temp1d(nd0)+temp1*totfluxdd(nd0, nd))+&
&             temp6*(temp3d(nd0)-temp5*totfluxd0(nd0))/totflux))
            srwdd%skt0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%skt0(nd, icv1, 0) = -(temp2*(temp1*temp4+temp6*temp5))
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%skt0(nd0, icv1, 0) = -(temp2*(temp1*temp3d(nd0)+temp3*&
&           temp1d(nd0)))
          srwd0%skt0(nd0, icv1, 1) = 0.D0
        END DO
        srw%skt0(icv1, 0) = -(temp2*(temp3*temp1))
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (7) 
!
! -- BCENK=7 -- Prescribe the total flux of kt, following the
!               profile of fna
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=7 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'turb. kin. energy flux ', enkpar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
      END IF
!     ..compute total particle flux, and total kt flux
      totflux = 0.0_R8
      totpar = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        totpard(nd) = 0.d0
      END DO
      totfluxd0 = 0.D0
      totpard0 = 0.D0
      totfluxdd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 7) CALL XERRAB(&
&                                      'BCENK=7: incompatible core BCs')
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%&
&                 fna(nd0, nd, ifc, 0, ismain)+dvdd%fna(nd0, nd, ifc, 1&
&                 , ismain))
              END DO
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, ifc, 0, &
&               ismain)+dvd%fna(nd, ifc, 1, ismain))
            END DO
            DO nd0=1,nbdirs0
              totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fna(nd0, ifc&
&               , 0, ismain)+dvd0%fna(nd0, ifc, 1, ismain))
            END DO
            totflux = totflux - temp2*(dv%fna(ifc, 0, ismain)+dv%fna(ifc&
&             , 1, ismain))
          END DO
          DO nd=1,nbdirs
            totpard(nd) = totpard(nd) + enkpard(nd, ib0, 1)
          END DO
          DO nd0=1,nbdirs0
            totpard0(nd0) = totpard0(nd0) + enkpard0(nd0, ib0, 1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
!     ..impose the flux
      WRITE(*, *) 'BCENK=7, totflux = ', totflux, ', totpar = ', totpar
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd0=1,nbdirs0
          temp1d(nd0) = (totpard0(nd0)-totpar*totfluxd0(nd0)/totflux)/&
&           totflux
          temp3d(nd0) = dvd0%fna(nd0, ifc, 0, ismain) + dvd0%fna(nd0, &
&           ifc, 1, ismain)
        END DO
        temp1 = totpar/totflux
        temp3 = dv%fna(ifc, 0, ismain) + dv%fna(ifc, 1, ismain)
        DO nd=1,nbdirs
          temp5 = dvd%fna(nd, ifc, 0, ismain) + dvd%fna(nd, ifc, 1, &
&           ismain)
          temp4 = temp3/totflux
          temp6 = totpard(nd) - temp1*totfluxd(nd)
          DO nd0=1,nbdirs0
            srwdd%skt0(nd0, nd, icv1, 0) = -(temp2*(temp5*temp1d(nd0)+&
&             temp1*(dvdd%fna(nd0, nd, ifc, 0, ismain)+dvdd%fna(nd0, nd&
&             , ifc, 1, ismain))-temp4*(totfluxd(nd)*temp1d(nd0)+temp1*&
&             totfluxdd(nd0, nd))+temp6*(temp3d(nd0)-temp4*totfluxd0(nd0&
&             ))/totflux))
            srwdd%skt0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%skt0(nd, icv1, 0) = -(temp2*(temp1*temp5+temp6*temp4))
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%skt0(nd0, icv1, 0) = -(temp2*(temp1*temp3d(nd0)+temp3*&
&           temp1d(nd0)))
          srwd0%skt0(nd0, icv1, 1) = 0.D0
        END DO
        srw%skt0(icv1, 0) = -(temp2*(temp3*temp1))
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (8) 
!
! -- BCENK=8 -- PRESCRIBE THE TOTAL FLUX OF KT WITH CONSTANT
!               FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'total turb. kin. energy flux ', &
&                                   enkpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%skt0(nd0, nd, icv1, 0) = 0.D0
            srwdd%skt0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%skt0(nd, icv1, 0) = geo%fcs(ifc)*enkpard(nd, ib, 1)/us
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%skt0(nd0, icv1, 0) = geo%fcs(ifc)*enkpard0(nd0, ib, 1)/&
&           us
          srwd0%skt0(nd0, icv1, 1) = 0.D0
        END DO
        srw%skt0(icv1, 0) = enkpar(ib, 1)/us*geo%fcs(ifc)
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (9) 
!
! -- BCENK=9 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENK=9, NOT AVAILABLE')
!
! -- BCENK=10 -- not implemented
!
    CASE (10) 
      CALL XERRAB('B2STBC -- BCENK=10, NOT AVAILABLE')
!
! -- BCENK=11 -- not implemented
!
    CASE (11) 
      CALL XERRAB('B2STBC -- BCENK=11, NOT AVAILABLE')
!
! -- BCENK=12 -- not implemented
!
    CASE (12) 
      CALL XERRAB('B2STBC -- BCENK=12, NOT AVAILABLE')
!
! -- BCENK=13 -- not implemented
!
    CASE (13) 
      CALL XERRAB('B2STBC -- BCENK=13, NOT AVAILABLE')
!
! -- BCENK=14 -- Leakage option for turbulent kinetic energy
    CASE (14) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'turb. kin. energy leakage ', &
&       enkpar(ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        csdd = 0.D0
        arg12dd = 0.D0
      ELSE
        csdd = 0.D0
        arg12dd = 0.D0
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp6 = pz(icv1)/rz(icv1)
        DO nd0=1,nbdirs0
          temp2d(nd0) = (pzd0(nd0, icv1)-temp6*rzd0(nd0, icv1))/rz(icv1)
        END DO
        temp2 = temp6
        DO nd=1,nbdirs
          temp6 = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
          DO nd0=1,nbdirs0
            arg12dd(nd0, nd) = (pzdd(nd0, nd, icv1)-rzd(nd, icv1)*temp2d&
&             (nd0)-temp2*rzdd(nd0, nd, icv1)-temp6*rzd0(nd0, icv1))/rz(&
&             icv1)
            srwdd%skt0(nd0, nd, icv1, 0) = 0.D0
          END DO
          arg12d(nd) = temp6
          srwd%skt0(nd, icv1, 0) = 0.d0
        END DO
        arg12 = temp2
        temp6 = SQRT(arg12)
        DO nd0=1,nbdirs0
          arg12d0(nd0) = temp2d(nd0)
          IF (arg12 .EQ. 0.D0) THEN
            temp2d(nd0) = 0.D0
          ELSE
            temp2d(nd0) = arg12d0(nd0)/(2.0*temp6)
          END IF
          csd0(nd0) = temp2d(nd0)
        END DO
        temp2 = temp6
        cs = temp2
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = 0.D0
            END DO
            csd(nd) = 0.d0
          ELSE
            temp6 = arg12d(nd)/(2.0*temp2)
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = (arg12dd(nd0, nd)-temp6*2.0*temp2d(nd0))/(&
&               2.0*temp2)
            END DO
            csd(nd) = temp6
          END IF
          DO nd0=1,nbdirs0
            srwdd%skt0(nd0, nd, icv1, 3) = geo%fcs(ifc)*(csd(nd)*&
&             enkpard0(nd0, ib, 1)+enkpar(ib, 1)*csdd(nd0, nd)+enkpard(&
&             nd, ib, 1)*csd0(nd0))
          END DO
          srwd%skt0(nd, icv1, 3) = geo%fcs(ifc)*(enkpar(ib, 1)*csd(nd)+&
&           cs*enkpard(nd, ib, 1))
        END DO
        DO nd0=1,nbdirs0
          srwd0%skt0(nd0, icv1, 0) = 0.D0
          srwd0%skt0(nd0, icv1, 3) = geo%fcs(ifc)*(enkpar(ib, 1)*csd0(&
&           nd0)+cs*enkpard0(nd0, ib, 1))
        END DO
        srw%skt0(icv1, 0) = 0.0_R8
        srw%skt0(icv1, 3) = geo%fcs(ifc)*cs*enkpar(ib, 1)
      END DO
    CASE (15) 
!
! -- BCENK=15 -- Sheath transmission factor
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENK=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY', ib&
&                                , ' FOR ALL IONS'
!srv 20.09.17
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 15, ENKPAR(I,,1) <= 0 not allowed!')
!srv 20.09.17
        WRITE(*, '(a,a,1p,g14.7,a,a,a)') &
&       'sheath transmission factor BC for turb. kin. energy', &
&       ' with ENKPAR(IB,1) =', enkpar(ib, 1), ' on ', bcchar(ib), &
&       boundary_location(ib)
        csdd = 0.D0
        arg12dd = 0.D0
        t0dd = 0.D0
        t1dd = 0.D0
      ELSE
        csdd = 0.D0
        arg12dd = 0.D0
        t0dd = 0.D0
        t1dd = 0.D0
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp6 = pz(icv1)/rz(icv1)
        DO nd0=1,nbdirs0
          temp2d(nd0) = (pzd0(nd0, icv1)-temp6*rzd0(nd0, icv1))/rz(icv1)
        END DO
        temp2 = temp6
        DO nd=1,nbdirs
          temp6 = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
          DO nd0=1,nbdirs0
            arg12dd(nd0, nd) = (pzdd(nd0, nd, icv1)-rzd(nd, icv1)*temp2d&
&             (nd0)-temp2*rzdd(nd0, nd, icv1)-temp6*rzd0(nd0, icv1))/rz(&
&             icv1)
          END DO
          arg12d(nd) = temp6
        END DO
        arg12 = temp2
        temp6 = SQRT(arg12)
        DO nd0=1,nbdirs0
          arg12d0(nd0) = temp2d(nd0)
          IF (arg12 .EQ. 0.D0) THEN
            temp2d(nd0) = 0.D0
          ELSE
            temp2d(nd0) = arg12d0(nd0)/(2.0*temp6)
          END IF
        END DO
        temp2 = temp6
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = 0.D0
            END DO
            csd(nd) = 0.d0
          ELSE
            temp6 = arg12d(nd)/(2.0*temp2)
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = (arg12dd(nd0, nd)-temp6*2.0*temp2d(nd0))/(&
&               2.0*temp2)
            END DO
            csd(nd) = temp6
          END IF
        END DO
        DO nd0=1,nbdirs0
          csd0(nd0) = temp2d(nd0)
        END DO
        cs = temp2
        t0 = 0.0_R8
        t1 = 0.0_R8
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            t0dd(nd0, nd) = 0.D0
          END DO
          t0d(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            t1dd(nd0, nd) = 0.D0
          END DO
          t1d(nd) = 0.d0
        END DO
        t0d0 = 0.D0
        t1d0 = 0.D0
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t0dd(nd0, nd) = t0dd(nd0, nd) + mompard(nd, is, ib, 1)*&
&                 pld0%na(nd0, icv1, is) + pld%na(nd, icv1, is)*mompard0&
&                 (nd0, is, ib, 1) + mompar(is, ib, 1)*pldd%na(nd0, nd, &
&                 icv1, is)
              END DO
              t0d(nd) = t0d(nd) + pl%na(icv1, is)*mompard(nd, is, ib, 1)&
&               + mompar(is, ib, 1)*pld%na(nd, icv1, is)
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = t0d0(nd0) + pl%na(icv1, is)*mompard0(nd0, is, &
&               ib, 1) + mompar(is, ib, 1)*pld0%na(nd0, icv1, is)
            END DO
            t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              temp5 = co%dna0(icv1, is)*pl%na(icv1, is)/conpar(is, ib, 2&
&               )
              DO nd0=1,nbdirs0
                temp3d(nd0) = (pl%na(icv1, is)*cod0%dna0(nd0, icv1, is)+&
&                 co%dna0(icv1, is)*pld0%na(nd0, icv1, is)-temp5*&
&                 conpard0(nd0, is, ib, 2))/conpar(is, ib, 2)
              END DO
              temp3 = temp5
              DO nd=1,nbdirs
                temp5 = (pl%na(icv1, is)*cod%dna0(nd, icv1, is)+co%dna0(&
&                 icv1, is)*pld%na(nd, icv1, is)-temp3*conpard(nd, is, &
&                 ib, 2))/conpar(is, ib, 2)
                DO nd0=1,nbdirs0
                  t1dd(nd0, nd) = t1dd(nd0, nd) + (cod%dna0(nd, icv1, is&
&                   )*pld0%na(nd0, icv1, is)+pl%na(icv1, is)*codd%dna0(&
&                   nd0, nd, icv1, is)+pld%na(nd, icv1, is)*cod0%dna0(&
&                   nd0, icv1, is)+co%dna0(icv1, is)*pldd%na(nd0, nd, &
&                   icv1, is)-conpard(nd, is, ib, 2)*temp3d(nd0)-temp3*&
&                   conpardd(nd0, nd, is, ib, 2)-temp5*conpard0(nd0, is&
&                   , ib, 2))/conpar(is, ib, 2)
                END DO
                t1d(nd) = t1d(nd) + temp5
              END DO
              DO nd0=1,nbdirs0
                t1d0(nd0) = t1d0(nd0) + temp3d(nd0)
              END DO
              t1 = t1 + temp3
            END IF
          END IF
        END DO
        IF (geo%fcpbs(ifc) .GE. 0.) THEN
          abs0 = geo%fcpbs(ifc)
        ELSE
          abs0 = -geo%fcpbs(ifc)
        END IF
        DO nd0=1,nbdirs0
          temp2d(nd0) = (switch%b2tfhi_fflokt+1.0_R8)*enkpard0(nd0, ib, &
&           1) + enkpar(ib, 1)*switchd0%b2tfhi_fflokt(nd0)
        END DO
        temp2 = enkpar(ib, 1)*(switch%b2tfhi_fflokt+1.0_R8)
        DO nd=1,nbdirs
          temp6 = enkpard(nd, ib, 1)*(switch%b2tfhi_fflokt+1.0_R8) + &
&           switchd%b2tfhi_fflokt(nd)*enkpar(ib, 1)
          temp7 = cs*t0d(nd) + t0*csd(nd)
          DO nd0=1,nbdirs0
            srwdd%skt0(nd0, nd, icv1, 1) = srwdd%skt0(nd0, nd, icv1, 1) &
&             - abs0*(temp6*(cs*t0d0(nd0)+t0*csd0(nd0))+t0*cs*(enkpard(&
&             nd, ib, 1)*switchd0%b2tfhi_fflokt(nd0)+switchd%&
&             b2tfhi_fflokt(nd)*enkpard0(nd0, ib, 1))+temp7*temp2d(nd0)+&
&             temp2*(t0d(nd)*csd0(nd0)+cs*t0dd(nd0, nd)+csd(nd)*t0d0(nd0&
&             )+t0*csdd(nd0, nd))) - geo%fcs(ifc)*(enkpard(nd, ib, 2)*&
&             t1d0(nd0)+t1d(nd)*enkpard0(nd0, ib, 2)+enkpar(ib, 2)*t1dd(&
&             nd0, nd))
          END DO
          srwd%skt0(nd, icv1, 1) = srwd%skt0(nd, icv1, 1) - abs0*(t0*cs*&
&           temp6+temp2*temp7) - geo%fcs(ifc)*(enkpard(nd, ib, 2)*t1+&
&           enkpar(ib, 2)*t1d(nd))
        END DO
        DO nd0=1,nbdirs0
          srwd0%skt0(nd0, icv1, 1) = srwd0%skt0(nd0, icv1, 1) - abs0*(cs&
&           *(t0*temp2d(nd0)+temp2*t0d0(nd0))+temp2*t0*csd0(nd0)) - geo%&
&           fcs(ifc)*(t1*enkpard0(nd0, ib, 2)+enkpar(ib, 2)*t1d0(nd0))
        END DO
        srw%skt0(icv1, 1) = srw%skt0(icv1, 1) - abs0*(temp2*(t0*cs)) - &
&         geo%fcs(ifc)*(enkpar(ib, 2)*t1)
!wdk    Todo: corrections for BCCON.ne.14
      END DO
    CASE (16) 
!
! -- BCENK=16 -- Prescribe the value of the turb. kin. energy, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=16 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. kin. energy + perturbation', enkpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 16, ENKPAR(,1) !> 0')
      END IF
!     ..compute average kt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      t1d0 = 0.D0
      t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%kt(&
&                 nd0, nd, icv2)
              END DO
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%kt(nd, icv2)
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%kt(nd0, icv2)
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%kt(icv2)
          END DO
        END IF
      END DO
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          t1dd(nd0, nd) = t1dd(nd0, nd)/t0
        END DO
        t1d(nd) = t1d(nd)/t0
      END DO
      DO nd0=1,nbdirs0
        t1d0(nd0) = t1d0(nd0)/t0
      END DO
      t1 = t1/t0
!     ..impose kt with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%skt0(nd0, nd, icv1, 0) = temp2*(pldd%kt(nd0, nd, icv2)&
&             -t1dd(nd0, nd))
            srwdd%skt0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%skt0(nd, icv1, 0) = temp2*(pld%kt(nd, icv2)+ev*enkpard(nd&
&           , ib, 1)-t1d(nd))
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%skt0(nd0, icv1, 0) = temp2*(pld0%kt(nd0, icv2)+ev*&
&           enkpard0(nd0, ib, 1)-t1d0(nd0))
          srwd0%skt0(nd0, icv1, 1) = 0.D0
        END DO
        srw%skt0(icv1, 0) = temp2*(pl%kt(icv2)+ev*enkpar(ib, 1)-t1)
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (17) 
!
! -- BCENK=17 -- Feedback on turb. kin. energy flux, by imposing a flux surface
!                averaged kt, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=17 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. kin. energy flux ', enkpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 17, ENKPAR(,1) !> 0')
      END IF
!     ..compute average kt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t0d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t2d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        totpard(nd) = 0.d0
      END DO
      totfluxd0 = 0.D0
      t2dd = 0.D0
      t0d0 = 0.D0
      t1d0 = 0.D0
      t2d0 = 0.D0
      totpard0 = 0.D0
      t0dd = 0.D0
      totfluxdd = 0.D0
      t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 17) CALL XERRAB(&
&                                      'BCENK=17: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t0dd(nd0, nd) = t0dd(nd0, nd) + geo%cvvol(icv2)*dvdd%ni(&
&                 nd0, nd, icv1, 0)
                t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*(dvd%ni(&
&                 nd, icv1, 0)*pld0%kt(nd0, icv1)+pl%kt(icv1)*dvdd%ni(&
&                 nd0, nd, icv1, 0)+pld%kt(nd, icv1)*dvd0%ni(nd0, icv1, &
&                 0)+dv%ni(icv1, 0)*pldd%kt(nd0, nd, icv1))
                t2dd(nd0, nd) = t2dd(nd0, nd) + geo%cvvol(icv2)*(dvd%ni(&
&                 nd, icv2, 0)*pld0%kt(nd0, icv2)+pl%kt(icv2)*dvdd%ni(&
&                 nd0, nd, icv2, 0)+pld%kt(nd, icv2)*dvd0%ni(nd0, icv2, &
&                 0)+dv%ni(icv2, 0)*pldd%kt(nd0, nd, icv2))
                totfluxdd(nd0, nd) = totfluxdd(nd0, nd) - temp2*(dvdd%&
&                 fkt(nd0, nd, ifc, 0)+dvdd%fkt(nd0, nd, ifc, 1))
              END DO
              t0d(nd) = t0d(nd) + geo%cvvol(icv2)*dvd%ni(nd, icv1, 0)
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*(pl%kt(icv1)*dvd%ni(nd&
&               , icv1, 0)+dv%ni(icv1, 0)*pld%kt(nd, icv1))
              t2d(nd) = t2d(nd) + geo%cvvol(icv2)*(pl%kt(icv2)*dvd%ni(nd&
&               , icv2, 0)+dv%ni(icv2, 0)*pld%kt(nd, icv2))
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fkt(nd, ifc, 0)+&
&               dvd%fkt(nd, ifc, 1))
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = t0d0(nd0) + geo%cvvol(icv2)*dvd0%ni(nd0, icv1&
&               , 0)
              t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*(pl%kt(icv1)*dvd0%&
&               ni(nd0, icv1, 0)+dv%ni(icv1, 0)*pld0%kt(nd0, icv1))
              t2d0(nd0) = t2d0(nd0) + geo%cvvol(icv2)*(pl%kt(icv2)*dvd0%&
&               ni(nd0, icv2, 0)+dv%ni(icv2, 0)*pld0%kt(nd0, icv2))
              totfluxd0(nd0) = totfluxd0(nd0) - temp2*(dvd0%fkt(nd0, ifc&
&               , 0)+dvd0%fkt(nd0, ifc, 1))
            END DO
            t0 = t0 + geo%cvvol(icv2)*dv%ni(icv1, 0)
            t1 = t1 + geo%cvvol(icv2)*dv%ni(icv1, 0)*pl%kt(icv1)
            t2 = t2 + geo%cvvol(icv2)*dv%ni(icv2, 0)*pl%kt(icv2)
            totflux = totflux - temp2*(dv%fkt(ifc, 0)+dv%fkt(ifc, 1))
          END DO
          DO nd=1,nbdirs
            totpard(nd) = totpard(nd) + enkpard(nd, ib0, 1)
          END DO
          DO nd0=1,nbdirs0
            totpard0(nd0) = totpard0(nd0) + enkpard0(nd0, ib0, 1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
      DO nd=1,nbdirs
        temp7 = t1/t0
        temp6 = (t1d(nd)-t0d(nd)*temp7)/t0
        DO nd0=1,nbdirs0
          t1dd(nd0, nd) = (t1dd(nd0, nd)-temp7*t0dd(nd0, nd)-t0d(nd)*(&
&           t1d0(nd0)-temp7*t0d0(nd0))/t0-temp6*t0d0(nd0))/t0
        END DO
        t1d(nd) = temp6
        temp7 = t2/t0
        temp6 = (t2d(nd)-t0d(nd)*temp7)/t0
        DO nd0=1,nbdirs0
          t2dd(nd0, nd) = (t2dd(nd0, nd)-temp7*t0dd(nd0, nd)-t0d(nd)*(&
&           t2d0(nd0)-temp7*t0d0(nd0))/t0-temp6*t0d0(nd0))/t0
        END DO
        t2d(nd) = temp6
      END DO
      DO nd0=1,nbdirs0
        t1d0(nd0) = (t1d0(nd0)-t1*t0d0(nd0)/t0)/t0
        t2d0(nd0) = (t2d0(nd0)-t2*t0d0(nd0)/t0)/t0
      END DO
      t1 = t1/t0
      t2 = t2/t0
      IF (enkpar(ib, 2) .GT. 0.0_R8) THEN
        DO nd=1,nbdirs
          t3d(nd) = enkpard(nd, ib, 2)
        END DO
        DO nd0=1,nbdirs0
          t3d0(nd0) = enkpard0(nd0, ib, 2)
        END DO
        t3 = enkpar(ib, 2)
      ELSE
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
      END IF
      IF (enkpar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_ti
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
        t3d0 = 0.D0
      END IF
      IF (totflux .GE. 0.) THEN
        x1dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x1dd(nd0, nd) = totfluxdd(nd0, nd)
          END DO
          x1d(nd) = totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x1d0(nd0) = totfluxd0(nd0)
        END DO
        x1 = totflux
      ELSE
        x1dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            x1dd(nd0, nd) = -totfluxdd(nd0, nd)
          END DO
          x1d(nd) = -totfluxd(nd)
        END DO
        DO nd0=1,nbdirs0
          x1d0(nd0) = -totfluxd0(nd0)
        END DO
        x1 = -totflux
      END IF
      IF (x1 .LT. totpar) THEN
        DO nd=1,nbdirs
          max1d(nd) = totpard(nd)
        END DO
        DO nd0=1,nbdirs0
          max1d0(nd0) = totpard0(nd0)
        END DO
        max1 = totpar
        max1dd = 0.D0
      ELSE
        max1dd = 0.D0
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            max1dd(nd0, nd) = x1dd(nd0, nd)
          END DO
          max1d(nd) = x1d(nd)
        END DO
        DO nd0=1,nbdirs0
          max1d0(nd0) = x1d0(nd0)
        END DO
        max1 = x1
      END IF
      temp2 = t3/max1
      DO nd0=1,nbdirs0
        temp2d(nd0) = (t3d0(nd0)-t3*max1d0(nd0)/max1)/max1
        temp3d(nd0) = -(temp2*(totfluxd0(nd0)-totpard0(nd0))+(totflux-&
&         totpar)*temp2d(nd0))
      END DO
      temp3 = -((totflux-totpar)*temp2) + 1.0_R8
      t4dd = 0.D0
      DO nd=1,nbdirs
        temp7 = t3d(nd) - temp2*max1d(nd)
        temp6 = (totflux-totpar)/max1
        temp8 = temp2*(totfluxd(nd)-totpard(nd)) + temp6*temp7
        DO nd0=1,nbdirs0
          t4dd(nd0, nd) = t1d(nd)*temp3d(nd0) + temp3*t1dd(nd0, nd) - &
&           temp8*t1d0(nd0) - t1*((totfluxd(nd)-totpard(nd))*temp2d(nd0)&
&           +temp2*totfluxdd(nd0, nd)+temp7*(totfluxd0(nd0)-totpard0(nd0&
&           )-temp6*max1d0(nd0))/max1-temp6*(max1d(nd)*temp2d(nd0)+temp2&
&           *max1dd(nd0, nd)))
        END DO
        t4d(nd) = temp3*t1d(nd) - t1*temp8
      END DO
      DO nd0=1,nbdirs0
        t4d0(nd0) = t1*temp3d(nd0) + temp3*t1d0(nd0)
      END DO
      t4 = temp3*t1
      IF (bcenk_17_style .EQ. 0) THEN
!       ..impose kt with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*ne00*geo%fcs(ifc)
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%skt0(nd0, nd, icv1, 0) = temp2*(pldd%kt(nd0, nd, &
&               icv2)+t4dd(nd0, nd)-t2dd(nd0, nd))
              srwdd%skt0(nd0, nd, icv1, 1) = 0.D0
            END DO
            srwd%skt0(nd, icv1, 0) = temp2*(pld%kt(nd, icv2)+t4d(nd)-t2d&
&             (nd))
            srwd%skt0(nd, icv1, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%skt0(nd0, icv1, 0) = temp2*(pld0%kt(nd0, icv2)+t4d0(&
&             nd0)-t2d0(nd0))
            srwd0%skt0(nd0, icv1, 1) = 0.D0
          END DO
          srw%skt0(icv1, 0) = temp2*(pl%kt(icv2)+t4-t2)
          srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
!       ..impose kt w/o perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            DO nd0=nd,nbdirs0
              srwdd%skt0(nd0, nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t4dd&
&               (nd0, nd)
              srwdd%skt0(nd0, nd, icv1, 1) = 0.D0
            END DO
            srwd%skt0(nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t4d(nd)
            srwd%skt0(nd, icv1, 1) = 0.d0
          END DO
          DO nd0=1,nbdirs0
            srwd0%skt0(nd0, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t4d0(nd0)
            srwd0%skt0(nd0, icv1, 1) = 0.D0
          END DO
          srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t4
          srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      END IF
    CASE DEFAULT
!
      WRITE(*, *) bcenk(ib)
      CALL XERRAB('BCENK out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENK_DV_DV

!  Differentiation of b2stbc_phys_enk in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: *(srw.skt0)
!   with respect to varying inputs: conpar mompar enkpar *(dv.fna)
!                *(dv.fhe) *(dv.fhi) *(dv.fkt) *(dv.ni) *(srw.skt0)
!                switch.b2tfhi_fflokt *(co.dna0) *(pl.na) *(pl.kt)
!                rz pz
!   Plus diff mem management of: dv.fna:in dv.fhe:in dv.fhi:in
!                dv.fkt:in dv.ni:in mpg.bcfcor:in geo.vxvol:in
!                srw.skt0:in co.dna0:in pl.na:in pl.kt:in
!
  SUBROUTINE B2STBC_PHYS_ENK_DV(ib, nbdirs)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: ib, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, t0, t1, t2, t3, t4, totpar, totflux
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd, t0d, t1d, t2d, t3d, t4d&
&   , totpard, totfluxd
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(kind=r8) :: x1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: x1d
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: max1
    REAL(kind=r8), DIMENSION(nbdirsmax) :: max1d
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(kind=r8) :: temp2
    REAL(r8) :: temp3
    INTEGER :: nbdirs
!
! -- BOUNDARY CONDITIONS FOR TURBULENT KINETIC ENERGY EQUATION --
!
    SELECT CASE  (bcenk(ib)) 
    CASE (0) 
!
!
! -- BCENK=1 -- PRESCRIBE THE VALUE OF KT
!

    CASE (1) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified kt ', enkpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 1, ENKPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp = geo%fcs(ifc)*ev
        DO nd=1,nbdirs
          srwd%skt0(nd, icv1, 0) = temp*vbig*ne00*enkpard(nd, ib, 1)
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        srw%skt0(icv1, 0) = vbig*ne00*enkpar(ib, 1)*temp
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENK=2 -- PRESCRIBE THE GRADIENT OF THE TURB. KIN. ENERGY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. kin. en. gradient ', enkpar(&
&                                   ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
!wdk    Note: specifies the gradient in the outward normal direction
!wdk    Tmp: in "connector" direction - ok for orthogonal grids
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        CALL INTVERTEX_S_DV_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%kt&
&                            , pld%kt, t1, t1d, nbdirs)
        CALL INTVERTEX_S_DV_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%kt&
&                            , pld%kt, t2, t2d, nbdirs)
        temp = vbig*ne00*geo%fcs(ifc)
        temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
        temp1 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, &
&         2))
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          srwd%skt0(nd, icv1, 0) = temp*(temp0*geo%fcqgam(ifc, 0)*ev*&
&           enkpard(nd, ib, 1)-temp1*temp2*(t2d(nd)-t1d(nd))/geo%fcht(&
&           ifc)+pld%kt(nd, icv2))
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        srw%skt0(icv1, 0) = temp*(temp0*(geo%fcqgam(ifc, 0)*(ev*enkpar(&
&         ib, 1)))-temp1*(temp2*((t2-t1)/geo%fcht(ifc)))+pl%kt(icv2))
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENK=3 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENK=3, NOT AVAILABLE')
!
! -- BCENK=4 -- not implemented
!
    CASE (4) 
      CALL XERRAB('B2STBC -- BCENK=4, NOT AVAILABLE')
!
! -- BCENK=5 -- not implemented
!
    CASE (5) 
      CALL XERRAB('B2STBC -- BCENK=5, NOT AVAILABLE')
!
! -- BCENK=6 -- Prescribe the total flux of kt, following the
!               profile of fhi + fhe
!
    CASE (6) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=6 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'turb. kin. energy flux ', enkpar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
      END IF
!     ..compute total ion+electron heat flux, and total kt flux
      totflux = 0.0_R8
      totpar = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        totpard(nd) = 0.d0
      END DO
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 6) CALL XERRAB(&
&                                      'BCENK=6: incompatible core BCs')
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fhe(nd, ifc, 0)+&
&               dvd%fhe(nd, ifc, 1)+dvd%fhi(nd, ifc, 0)+dvd%fhi(nd, ifc&
&               , 1))
            END DO
            totflux = totflux - temp2*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%&
&             fhi(ifc, 0)+dv%fhi(ifc, 1))
          END DO
          DO nd=1,nbdirs
            totpard(nd) = totpard(nd) + enkpard(nd, ib0, 1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
!     ..impose the flux
      WRITE(*, *) 'BCENK=6, totflux = ', totflux, ', totpar = ', totpar
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        temp1 = totpar/totflux
        temp3 = dv%fhe(ifc, 0) + dv%fhe(ifc, 1) + dv%fhi(ifc, 0) + dv%&
&         fhi(ifc, 1)
        DO nd=1,nbdirs
          srwd%skt0(nd, icv1, 0) = -(temp2*(temp1*(dvd%fhe(nd, ifc, 0)+&
&           dvd%fhe(nd, ifc, 1)+dvd%fhi(nd, ifc, 0)+dvd%fhi(nd, ifc, 1))&
&           +temp3*(totpard(nd)-temp1*totfluxd(nd))/totflux))
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        srw%skt0(icv1, 0) = -(temp2*(temp3*temp1))
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (7) 
!
! -- BCENK=7 -- Prescribe the total flux of kt, following the
!               profile of fna
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=7 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'turb. kin. energy flux ', enkpar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
      END IF
!     ..compute total particle flux, and total kt flux
      totflux = 0.0_R8
      totpar = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        totpard(nd) = 0.d0
      END DO
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 7) CALL XERRAB(&
&                                      'BCENK=7: incompatible core BCs')
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fna(nd, ifc, 0, &
&               ismain)+dvd%fna(nd, ifc, 1, ismain))
            END DO
            totflux = totflux - temp2*(dv%fna(ifc, 0, ismain)+dv%fna(ifc&
&             , 1, ismain))
          END DO
          DO nd=1,nbdirs
            totpard(nd) = totpard(nd) + enkpard(nd, ib0, 1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
!     ..impose the flux
      WRITE(*, *) 'BCENK=7, totflux = ', totflux, ', totpar = ', totpar
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        temp1 = totpar/totflux
        temp3 = dv%fna(ifc, 0, ismain) + dv%fna(ifc, 1, ismain)
        DO nd=1,nbdirs
          srwd%skt0(nd, icv1, 0) = -(temp2*(temp1*(dvd%fna(nd, ifc, 0, &
&           ismain)+dvd%fna(nd, ifc, 1, ismain))+temp3*(totpard(nd)-&
&           temp1*totfluxd(nd))/totflux))
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        srw%skt0(icv1, 0) = -(temp2*(temp3*temp1))
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (8) 
!
! -- BCENK=8 -- PRESCRIBE THE TOTAL FLUX OF KT WITH CONSTANT
!               FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'total turb. kin. energy flux ', &
&                                   enkpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          srwd%skt0(nd, icv1, 0) = geo%fcs(ifc)*enkpard(nd, ib, 1)/us
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        srw%skt0(icv1, 0) = enkpar(ib, 1)/us*geo%fcs(ifc)
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (9) 
!
! -- BCENK=9 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENK=9, NOT AVAILABLE')
!
! -- BCENK=10 -- not implemented
!
    CASE (10) 
      CALL XERRAB('B2STBC -- BCENK=10, NOT AVAILABLE')
!
! -- BCENK=11 -- not implemented
!
    CASE (11) 
      CALL XERRAB('B2STBC -- BCENK=11, NOT AVAILABLE')
!
! -- BCENK=12 -- not implemented
!
    CASE (12) 
      CALL XERRAB('B2STBC -- BCENK=12, NOT AVAILABLE')
!
! -- BCENK=13 -- not implemented
!
    CASE (13) 
      CALL XERRAB('B2STBC -- BCENK=13, NOT AVAILABLE')
!
! -- BCENK=14 -- Leakage option for turbulent kinetic energy
    CASE (14) 
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. kin. energy leakage ', enkpar&
&                                   (ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = pz(icv1)/rz(icv1)
        DO nd=1,nbdirs
          arg12d(nd) = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
          srwd%skt0(nd, icv1, 0) = 0.d0
        END DO
        arg12 = temp2
        temp2 = SQRT(arg12)
        cs = temp2
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            csd(nd) = 0.d0
          ELSE
            csd(nd) = arg12d(nd)/(2.0*temp2)
          END IF
          srwd%skt0(nd, icv1, 3) = geo%fcs(ifc)*(enkpar(ib, 1)*csd(nd)+&
&           cs*enkpard(nd, ib, 1))
        END DO
        srw%skt0(icv1, 0) = 0.0_R8
        srw%skt0(icv1, 3) = geo%fcs(ifc)*cs*enkpar(ib, 1)
      END DO
    CASE (15) 
!
! -- BCENK=15 -- Sheath transmission factor
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENK=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY', ib&
&                                , ' FOR ALL IONS'
!srv 20.09.17
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 15, ENKPAR(I,,1) <= 0 not allowed!')
!srv 20.09.17
        WRITE(*, '(a,a,1p,g14.7,a,a,a)') &
&       'sheath transmission factor BC for turb. kin. energy', &
&       ' with ENKPAR(IB,1) =', enkpar(ib, 1), ' on ', bcchar(ib), &
&       boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = pz(icv1)/rz(icv1)
        DO nd=1,nbdirs
          arg12d(nd) = (pzd(nd, icv1)-temp2*rzd(nd, icv1))/rz(icv1)
        END DO
        arg12 = temp2
        temp2 = SQRT(arg12)
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            csd(nd) = 0.d0
          ELSE
            csd(nd) = arg12d(nd)/(2.0*temp2)
          END IF
        END DO
        cs = temp2
        t0 = 0.0_R8
        t1 = 0.0_R8
        DO nd=1,nbdirsmax
          t0d(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          t1d(nd) = 0.d0
        END DO
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            DO nd=1,nbdirs
              t0d(nd) = t0d(nd) + pl%na(icv1, is)*mompard(nd, is, ib, 1)&
&               + mompar(is, ib, 1)*pld%na(nd, icv1, is)
            END DO
            t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              temp3 = co%dna0(icv1, is)*pl%na(icv1, is)/conpar(is, ib, 2&
&               )
              DO nd=1,nbdirs
                t1d(nd) = t1d(nd) + (pl%na(icv1, is)*cod%dna0(nd, icv1, &
&                 is)+co%dna0(icv1, is)*pld%na(nd, icv1, is)-temp3*&
&                 conpard(nd, is, ib, 2))/conpar(is, ib, 2)
              END DO
              t1 = t1 + temp3
            END IF
          END IF
        END DO
        IF (geo%fcpbs(ifc) .GE. 0.) THEN
          abs0 = geo%fcpbs(ifc)
        ELSE
          abs0 = -geo%fcpbs(ifc)
        END IF
        temp2 = enkpar(ib, 1)*(switch%b2tfhi_fflokt+1.0_R8)
        DO nd=1,nbdirs
          srwd%skt0(nd, icv1, 1) = srwd%skt0(nd, icv1, 1) - abs0*(t0*cs*&
&           ((switch%b2tfhi_fflokt+1.0_R8)*enkpard(nd, ib, 1)+enkpar(ib&
&           , 1)*switchd%b2tfhi_fflokt(nd))+temp2*(cs*t0d(nd)+t0*csd(nd)&
&           )) - geo%fcs(ifc)*(t1*enkpard(nd, ib, 2)+enkpar(ib, 2)*t1d(&
&           nd))
        END DO
        srw%skt0(icv1, 1) = srw%skt0(icv1, 1) - abs0*(temp2*(t0*cs)) - &
&         geo%fcs(ifc)*(enkpar(ib, 2)*t1)
!wdk    Todo: corrections for BCCON.ne.14
      END DO
    CASE (16) 
!
! -- BCENK=16 -- Prescribe the value of the turb. kin. energy, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=16 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. kin. energy + perturbation', enkpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 16, ENKPAR(,1) !> 0')
      END IF
!     ..compute average kt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            DO nd=1,nbdirs
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%kt(nd, icv2)
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%kt(icv2)
          END DO
        END IF
      END DO
      DO nd=1,nbdirs
        t1d(nd) = t1d(nd)/t0
      END DO
      t1 = t1/t0
!     ..impose kt with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp2 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%skt0(nd, icv1, 0) = temp2*(pld%kt(nd, icv2)+ev*enkpard(nd&
&           , ib, 1)-t1d(nd))
          srwd%skt0(nd, icv1, 1) = 0.d0
        END DO
        srw%skt0(icv1, 0) = temp2*(pl%kt(icv2)+ev*enkpar(ib, 1)-t1)
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (17) 
!
! -- BCENK=17 -- Feedback on turb. kin. energy flux, by imposing a flux surface
!                averaged kt, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=17 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. kin. energy flux ', enkpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 17, ENKPAR(,1) !> 0')
      END IF
!     ..compute average kt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
      DO nd=1,nbdirsmax
        totfluxd(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t0d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        t2d(nd) = 0.d0
      END DO
      DO nd=1,nbdirsmax
        totpard(nd) = 0.d0
      END DO
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 17) CALL XERRAB(&
&                                      'BCENK=17: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            temp2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
            DO nd=1,nbdirs
              t0d(nd) = t0d(nd) + geo%cvvol(icv2)*dvd%ni(nd, icv1, 0)
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*(pl%kt(icv1)*dvd%ni(nd&
&               , icv1, 0)+dv%ni(icv1, 0)*pld%kt(nd, icv1))
              t2d(nd) = t2d(nd) + geo%cvvol(icv2)*(pl%kt(icv2)*dvd%ni(nd&
&               , icv2, 0)+dv%ni(icv2, 0)*pld%kt(nd, icv2))
              totfluxd(nd) = totfluxd(nd) - temp2*(dvd%fkt(nd, ifc, 0)+&
&               dvd%fkt(nd, ifc, 1))
            END DO
            t0 = t0 + geo%cvvol(icv2)*dv%ni(icv1, 0)
            t1 = t1 + geo%cvvol(icv2)*dv%ni(icv1, 0)*pl%kt(icv1)
            t2 = t2 + geo%cvvol(icv2)*dv%ni(icv2, 0)*pl%kt(icv2)
            totflux = totflux - temp2*(dv%fkt(ifc, 0)+dv%fkt(ifc, 1))
          END DO
          DO nd=1,nbdirs
            totpard(nd) = totpard(nd) + enkpard(nd, ib0, 1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
      DO nd=1,nbdirs
        t1d(nd) = (t1d(nd)-t1*t0d(nd)/t0)/t0
        t2d(nd) = (t2d(nd)-t2*t0d(nd)/t0)/t0
      END DO
      t1 = t1/t0
      t2 = t2/t0
      IF (enkpar(ib, 2) .GT. 0.0_R8) THEN
        DO nd=1,nbdirs
          t3d(nd) = enkpard(nd, ib, 2)
        END DO
        t3 = enkpar(ib, 2)
      ELSE
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      IF (enkpar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_ti
        DO nd=1,nbdirsmax
          t3d(nd) = 0.d0
        END DO
      END IF
      IF (totflux .GE. 0.) THEN
        DO nd=1,nbdirs
          x1d(nd) = totfluxd(nd)
        END DO
        x1 = totflux
      ELSE
        DO nd=1,nbdirs
          x1d(nd) = -totfluxd(nd)
        END DO
        x1 = -totflux
      END IF
      IF (x1 .LT. totpar) THEN
        DO nd=1,nbdirs
          max1d(nd) = totpard(nd)
        END DO
        max1 = totpar
      ELSE
        DO nd=1,nbdirs
          max1d(nd) = x1d(nd)
        END DO
        max1 = x1
      END IF
      temp2 = t3/max1
      temp3 = -((totflux-totpar)*temp2) + 1.0_R8
      DO nd=1,nbdirs
        t4d(nd) = temp3*t1d(nd) - t1*(temp2*(totfluxd(nd)-totpard(nd))+(&
&         totflux-totpar)*(t3d(nd)-temp2*max1d(nd))/max1)
      END DO
      t4 = temp3*t1
      IF (bcenk_17_style .EQ. 0) THEN
!       ..impose kt with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp2 = vbig*ne00*geo%fcs(ifc)
          DO nd=1,nbdirs
            srwd%skt0(nd, icv1, 0) = temp2*(pld%kt(nd, icv2)+t4d(nd)-t2d&
&             (nd))
            srwd%skt0(nd, icv1, 1) = 0.d0
          END DO
          srw%skt0(icv1, 0) = temp2*(pl%kt(icv2)+t4-t2)
          srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
!       ..impose kt w/o perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO nd=1,nbdirs
            srwd%skt0(nd, icv1, 0) = vbig*ne00*geo%fcs(ifc)*t4d(nd)
            srwd%skt0(nd, icv1, 1) = 0.d0
          END DO
          srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t4
          srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      END IF
    CASE DEFAULT
!
      WRITE(*, *) bcenk(ib)
      CALL XERRAB('BCENK out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENK_DV

!
  SUBROUTINE B2STBC_PHYS_ENK(ib)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER :: ib, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, t0, t1, t2, t3, t4, totpar, totflux
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: max1
    REAL(kind=r8) :: arg12
!
! -- BOUNDARY CONDITIONS FOR TURBULENT KINETIC ENERGY EQUATION --
!
    SELECT CASE  (bcenk(ib)) 
    CASE (0) 
!
!
! -- BCENK=1 -- PRESCRIBE THE VALUE OF KT
!

    CASE (1) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified kt ', enkpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 1, ENKPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*enkpar(ib, 1)*ev
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENK=2 -- PRESCRIBE THE GRADIENT OF THE TURB. KIN. ENERGY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. kin. en. gradient ', enkpar(&
&                                   ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
!wdk    Note: specifies the gradient in the outward normal direction
!wdk    Tmp: in "connector" direction - ok for orthogonal grids
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1 = INTVERTEX_S_NODIFF_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, &
&         pl%kt)
        t2 = INTVERTEX_S_NODIFF_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, &
&         pl%kt)
        srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(ev*enkpar(ib, 1)*(&
&         geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2&
&         -t1)*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/&
&         geo%fcht(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%kt(icv2))
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENK=3 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENK=3, NOT AVAILABLE')
!
! -- BCENK=4 -- not implemented
!
    CASE (4) 
      CALL XERRAB('B2STBC -- BCENK=4, NOT AVAILABLE')
!
! -- BCENK=5 -- not implemented
!
    CASE (5) 
      CALL XERRAB('B2STBC -- BCENK=5, NOT AVAILABLE')
!
! -- BCENK=6 -- Prescribe the total flux of kt, following the
!               profile of fhi + fhe
!
    CASE (6) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=6 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'turb. kin. energy flux ', enkpar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
      END IF
!     ..compute total ion+electron heat flux, and total kt flux
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 6) CALL XERRAB(&
&                                      'BCENK=6: incompatible core BCs')
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%fhi(&
&             ifc, 0)+dv%fhi(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
!     ..impose the flux
      WRITE(*, *) 'BCENK=6, totflux = ', totflux, ', totpar = ', totpar
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        srw%skt0(icv1, 0) = -(totpar/totflux*(dv%fhe(ifc, 0)+dv%fhe(ifc&
&         , 1)+dv%fhi(ifc, 0)+dv%fhi(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib, 1&
&         )+ibc-1))
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (7) 
!
! -- BCENK=7 -- Prescribe the total flux of kt, following the
!               profile of fna
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=7 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'turb. kin. energy flux ', enkpar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
      END IF
!     ..compute total particle flux, and total kt flux
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 7) CALL XERRAB(&
&                                      'BCENK=7: incompatible core BCs')
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            totflux = totflux - (dv%fna(ifc, 0, ismain)+dv%fna(ifc, 1, &
&             ismain))*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
!     ..impose the flux
      WRITE(*, *) 'BCENK=7, totflux = ', totflux, ', totpar = ', totpar
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        srw%skt0(icv1, 0) = -(totpar/totflux*(dv%fna(ifc, 0, ismain)+dv%&
&         fna(ifc, 1, ismain))*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1))
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (8) 
!
! -- BCENK=8 -- PRESCRIBE THE TOTAL FLUX OF KT WITH CONSTANT
!               FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'total turb. kin. energy flux ', &
&                                   enkpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%skt0(icv1, 0) = enkpar(ib, 1)/us*geo%fcs(ifc)
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (9) 
!
! -- BCENK=9 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENK=9, NOT AVAILABLE')
!
! -- BCENK=10 -- not implemented
!
    CASE (10) 
      CALL XERRAB('B2STBC -- BCENK=10, NOT AVAILABLE')
!
! -- BCENK=11 -- not implemented
!
    CASE (11) 
      CALL XERRAB('B2STBC -- BCENK=11, NOT AVAILABLE')
!
! -- BCENK=12 -- not implemented
!
    CASE (12) 
      CALL XERRAB('B2STBC -- BCENK=12, NOT AVAILABLE')
!
! -- BCENK=13 -- not implemented
!
    CASE (13) 
      CALL XERRAB('B2STBC -- BCENK=13, NOT AVAILABLE')
!
! -- BCENK=14 -- Leakage option for turbulent kinetic energy
    CASE (14) 
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. kin. energy leakage ', enkpar&
&                                   (ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        srw%skt0(icv1, 0) = 0.0_R8
        srw%skt0(icv1, 3) = geo%fcs(ifc)*cs*enkpar(ib, 1)
      END DO
    CASE (15) 
!
! -- BCENK=15 -- Sheath transmission factor
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENK=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY', ib&
&                                , ' FOR ALL IONS'
!srv 20.09.17
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 15, ENKPAR(I,,1) <= 0 not allowed!')
!srv 20.09.17
        WRITE(*, '(a,a,1p,g14.7,a,a,a)') &
&       'sheath transmission factor BC for turb. kin. energy', &
&       ' with ENKPAR(IB,1) =', enkpar(ib, 1), ' on ', bcchar(ib), &
&       boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        t0 = 0.0_R8
        t1 = 0.0_R8
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t1 = t1 + co%dna0(icv1, &
&               is)/conpar(is, ib, 2)*pl%na(icv1, is)
          END IF
        END DO
        IF (geo%fcpbs(ifc) .GE. 0.) THEN
          abs0 = geo%fcpbs(ifc)
        ELSE
          abs0 = -geo%fcpbs(ifc)
        END IF
        srw%skt0(icv1, 1) = srw%skt0(icv1, 1) - enkpar(ib, 1)*t0*cs*abs0&
&         *(1.0_R8+switch%b2tfhi_fflokt) - enkpar(ib, 2)*t1*geo%fcs(ifc)
!wdk    Todo: corrections for BCCON.ne.14
      END DO
    CASE (16) 
!
! -- BCENK=16 -- Prescribe the value of the turb. kin. energy, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=16 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. kin. energy + perturbation', enkpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 16, ENKPAR(,1) !> 0')
      END IF
!     ..compute average kt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%kt(icv2)
          END DO
        END IF
      END DO
      t1 = t1/t0
!     ..impose kt with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%kt(icv2)+enkpar(&
&         ib, 1)*ev-t1)
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (17) 
!
! -- BCENK=17 -- Feedback on turb. kin. energy flux, by imposing a flux surface
!                averaged kt, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=17 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. kin. energy flux ', enkpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 17, ENKPAR(,1) !> 0')
      END IF
!     ..compute average kt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 17) CALL XERRAB(&
&                                      'BCENK=17: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)*dv%ni(icv1, 0)
            t1 = t1 + geo%cvvol(icv2)*dv%ni(icv1, 0)*pl%kt(icv1)
            t2 = t2 + geo%cvvol(icv2)*dv%ni(icv2, 0)*pl%kt(icv2)
            totflux = totflux - (dv%fkt(ifc, 0)+dv%fkt(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
      t1 = t1/t0
      t2 = t2/t0
      IF (enkpar(ib, 2) .GT. 0.0_R8) t3 = enkpar(ib, 2)
      IF (enkpar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
      IF (totflux .GE. 0.) THEN
        x1 = totflux
      ELSE
        x1 = -totflux
      END IF
      IF (x1 .LT. totpar) THEN
        max1 = totpar
      ELSE
        max1 = x1
      END IF
      t4 = (1.0_R8-t3*(totflux-totpar)/max1)*t1
      IF (bcenk_17_style .EQ. 0) THEN
!       ..impose kt with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%kt(icv2)+t4-t2)
          srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
!       ..impose kt w/o perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t4
          srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      END IF
    CASE DEFAULT
!
      WRITE(*, *) bcenk(ib)
      CALL XERRAB('BCENK out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENK

!  Differentiation of b2stbc_phys_enz_dv in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: *(srwd.szt0) *(srw.szt0)
!   with respect to varying inputs: conpar conpard mompar *(srwd.szt0)
!                *(srw.szt0) switch.b2tfhi_fflozt *(cod.dna0) *(co.dna0)
!                *(pld.na) *(pld.zt) *(pl.na) *(pl.zt) pzd rzd
!                rz pz
!   Plus diff mem management of: srwd.szt0:in geo.vxvol:in srw.szt0:in
!                cod.dna0:in co.dna0:in pld.na:in pld.zt:in pl.na:in
!                pl.zt:in
!  Differentiation of b2stbc_phys_enz in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: *(srw.szt0)
!   with respect to varying inputs: conpar mompar *(srw.szt0) switch.b2tfhi_fflozt
!                *(co.dna0) *(pl.na) *(pl.zt) rz pz
!   Plus diff mem management of: mpg.bcfcor:in geo.vxvol:in srw.szt0:in
!                co.dna0:in pl.na:in pl.zt:in
!
  SUBROUTINE B2STBC_PHYS_ENZ_DV_DV(ib, nbdirs, nbdirs0)
    USE B2MOD_DIFFSIZES
!  Hint: nbdirsmax0 should be the maximum number of differentiation directions
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: ib, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, t0, t1, t2
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: csd0, t0d0, t1d0, t2d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd, t0d, t1d, t2d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: csdd, t0dd, t1dd&
&   , t2dd
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: arg12d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg12dd
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: temp1d
    REAL(r8) :: temp2
    REAL(r8), DIMENSION(nbdirsmax0) :: temp2d
    INTEGER :: nbdirs
    INTEGER :: nd0
    REAL(kind=r8) :: temp3
    REAL(r8) :: temp4
    INTEGER :: nbdirs0
!
! -- BOUNDARY CONDITIONS FOR TURBULENT ENSTROPHY EQUATION --
!
    SELECT CASE  (bcenz(ib)) 
    CASE (0) 
!
!
! -- BCENZ=1 -- PRESCRIBE THE VALUE OF ZT
!

    CASE (1) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified zt ', enzpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enzpar(ib, 1) .GE. 0.0_R8, &
&             'BCENZ = 1, ENZPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%szt0(nd0, nd, icv1, 0) = 0.D0
            srwdd%szt0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%szt0(nd, icv1, 0) = 0.d0
          srwd%szt0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%szt0(nd0, icv1, 0) = 0.D0
          srwd0%szt0(nd0, icv1, 1) = 0.D0
        END DO
        srw%szt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*enzpar(ib, 1)*ev
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENZ=2 -- PRESCRIBE THE GRADIENT OF THE TURB. ENSTROPHY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. enstr. gradient ', enzpar(ib&
&                                   , 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1dd = 0.D0
        CALL INTVERTEX_S_DV_DV(ivx1, ncv, nvx, mpg, geo%vxvol, pl%zt, &
&                        pld0%zt, pld%zt, pldd%zt, t1, t1d0, t1d, t1dd, &
&                        nbdirs, nbdirs0)
        t2dd = 0.D0
        CALL INTVERTEX_S_DV_DV(ivx2, ncv, nvx, mpg, geo%vxvol, pl%zt, &
&                        pld0%zt, pld%zt, pldd%zt, t2, t2d0, t2d, t2dd, &
&                        nbdirs, nbdirs0)
        temp = vbig*ne00*geo%fcs(ifc)
        temp0 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, &
&         2))
        temp1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%szt0(nd0, nd, icv1, 0) = temp*(pldd%zt(nd0, nd, icv2)-&
&             temp0*temp1*(t2dd(nd0, nd)-t1dd(nd0, nd))/geo%fcht(ifc))
            srwdd%szt0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%szt0(nd, icv1, 0) = temp*(pld%zt(nd, icv2)-temp0*temp1*(&
&           t2d(nd)-t1d(nd))/geo%fcht(ifc))
          srwd%szt0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%szt0(nd0, icv1, 0) = temp*(pld0%zt(nd0, icv2)-temp0*&
&           temp1*(t2d0(nd0)-t1d0(nd0))/geo%fcht(ifc))
          srwd0%szt0(nd0, icv1, 1) = 0.D0
        END DO
        srw%szt0(icv1, 0) = temp*(ev*enzpar(ib, 1)*geo%fcqgam(ifc, 0)*(&
&         geo%fchc(ifc, 1)+geo%fchc(ifc, 2))+pl%zt(icv2)-temp0*(temp1*((&
&         t2-t1)/geo%fcht(ifc))))
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENZ=3 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENZ=3, NOT AVAILABLE')
!
! -- BCENZ=4 -- not implemented
!
    CASE (4) 
      CALL XERRAB('B2STBC -- BCENZ=4, NOT AVAILABLE')
!
! -- BCENZ=5 -- not implemented
!
    CASE (5) 
      CALL XERRAB('B2STBC -- BCENZ=5, NOT AVAILABLE')
!
! -- BCENZ=6 -- Prescribe the total flux of kt, following the
!               profile of fhi + fhe
!
    CASE (6) 
      CALL XERRAB('B2STBC -- BCENZ=6, NOT AVAILABLE')
!
! -- BCENZ=7 -- Prescribe the total flux of kt, following the
!               profile of fna
!
    CASE (7) 
      CALL XERRAB('B2STBC -- BCENZ=7, NOT AVAILABLE')
!
! -- BCENZ=8 -- PRESCRIBE THE TOTAL FLUX OF KT WITH CONSTANT
!               FLUX DENSITY
!
    CASE (8) 
      CALL XERRAB('B2STBC -- BCENZ=8, NOT AVAILABLE')
!
! -- BCENZ=9 -- not implemented
!
    CASE (9) 
      CALL XERRAB('B2STBC -- BCENZ=9, NOT AVAILABLE')
!
! -- BCENZ=10 -- not implemented
!
    CASE (10) 
      CALL XERRAB('B2STBC -- BCENZ=10, NOT AVAILABLE')
!
! -- BCENZ=11 -- not implemented
!
    CASE (11) 
      CALL XERRAB('B2STBC -- BCENZ=11, NOT AVAILABLE')
!
! -- BCENZ=12 -- not implemented
!
    CASE (12) 
      CALL XERRAB('B2STBC -- BCENZ=12, NOT AVAILABLE')
!
! -- BCENZ=13 -- not implemented
!
    CASE (13) 
      CALL XERRAB('B2STBC -- BCENZ=13, NOT AVAILABLE')
!
! -- BCENZ=14 -- Leakage option for turbulent enstrophy
!
    CASE (14) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'turb. enstrophy leakage ', &
&       enzpar(ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        csdd = 0.D0
        arg12dd = 0.D0
      ELSE
        csdd = 0.D0
        arg12dd = 0.D0
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp3 = pz(icv1)/rz(icv1)
        DO nd0=1,nbdirs0
          temp1d(nd0) = (pzd0(nd0, icv1)-temp3*rzd0(nd0, icv1))/rz(icv1)
        END DO
        temp1 = temp3
        DO nd=1,nbdirs
          temp3 = (pzd(nd, icv1)-temp1*rzd(nd, icv1))/rz(icv1)
          DO nd0=1,nbdirs0
            arg12dd(nd0, nd) = (pzdd(nd0, nd, icv1)-rzd(nd, icv1)*temp1d&
&             (nd0)-temp1*rzdd(nd0, nd, icv1)-temp3*rzd0(nd0, icv1))/rz(&
&             icv1)
            srwdd%szt0(nd0, nd, icv1, 0) = 0.D0
          END DO
          arg12d(nd) = temp3
          srwd%szt0(nd, icv1, 0) = 0.d0
        END DO
        arg12 = temp1
        temp3 = SQRT(arg12)
        DO nd0=1,nbdirs0
          arg12d0(nd0) = temp1d(nd0)
          IF (arg12 .EQ. 0.D0) THEN
            temp1d(nd0) = 0.D0
          ELSE
            temp1d(nd0) = arg12d0(nd0)/(2.0*temp3)
          END IF
        END DO
        temp1 = temp3
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = 0.D0
            END DO
            csd(nd) = 0.d0
          ELSE
            temp3 = arg12d(nd)/(2.0*temp1)
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = (arg12dd(nd0, nd)-temp3*2.0*temp1d(nd0))/(&
&               2.0*temp1)
            END DO
            csd(nd) = temp3
          END IF
          DO nd0=1,nbdirs0
            srwdd%szt0(nd0, nd, icv1, 3) = geo%fcs(ifc)*enzpar(ib, 1)*&
&             csdd(nd0, nd)
          END DO
          srwd%szt0(nd, icv1, 3) = enzpar(ib, 1)*geo%fcs(ifc)*csd(nd)
        END DO
        DO nd0=1,nbdirs0
          csd0(nd0) = temp1d(nd0)
          srwd0%szt0(nd0, icv1, 0) = 0.D0
          srwd0%szt0(nd0, icv1, 3) = enzpar(ib, 1)*geo%fcs(ifc)*csd0(nd0&
&           )
        END DO
        cs = temp1
        srw%szt0(icv1, 0) = 0.0_R8
        srw%szt0(icv1, 3) = geo%fcs(ifc)*cs*enzpar(ib, 1)
      END DO
    CASE (15) 
!
! -- BCENZ=15 -- Sheath transmission factor
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENZ=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY', ib&
&                                , ' FOR ALL IONS'
!srv 20.09.17
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENZ = 15, ENZPAR(I,,1) <= 0 not allowed!')
!srv 20.09.17
        WRITE(*, '(a,a,1p,g14.7,a,a,a)') &
&       'BCENZ=15: sheath transmission factor BC for ', &
&       'turb. enstrophy with ENZPAR(IB,1) =', enzpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        csdd = 0.D0
        arg12dd = 0.D0
        t0dd = 0.D0
        t1dd = 0.D0
      ELSE
        csdd = 0.D0
        arg12dd = 0.D0
        t0dd = 0.D0
        t1dd = 0.D0
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp3 = pz(icv1)/rz(icv1)
        DO nd0=1,nbdirs0
          temp1d(nd0) = (pzd0(nd0, icv1)-temp3*rzd0(nd0, icv1))/rz(icv1)
        END DO
        temp1 = temp3
        DO nd=1,nbdirs
          temp3 = (pzd(nd, icv1)-temp1*rzd(nd, icv1))/rz(icv1)
          DO nd0=1,nbdirs0
            arg12dd(nd0, nd) = (pzdd(nd0, nd, icv1)-rzd(nd, icv1)*temp1d&
&             (nd0)-temp1*rzdd(nd0, nd, icv1)-temp3*rzd0(nd0, icv1))/rz(&
&             icv1)
          END DO
          arg12d(nd) = temp3
        END DO
        arg12 = temp1
        temp3 = SQRT(arg12)
        DO nd0=1,nbdirs0
          arg12d0(nd0) = temp1d(nd0)
          IF (arg12 .EQ. 0.D0) THEN
            temp1d(nd0) = 0.D0
          ELSE
            temp1d(nd0) = arg12d0(nd0)/(2.0*temp3)
          END IF
        END DO
        temp1 = temp3
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = 0.D0
            END DO
            csd(nd) = 0.d0
          ELSE
            temp3 = arg12d(nd)/(2.0*temp1)
            DO nd0=1,nbdirs0
              csdd(nd0, nd) = (arg12dd(nd0, nd)-temp3*2.0*temp1d(nd0))/(&
&               2.0*temp1)
            END DO
            csd(nd) = temp3
          END IF
        END DO
        DO nd0=1,nbdirs0
          csd0(nd0) = temp1d(nd0)
        END DO
        cs = temp1
        t0 = 0.0_R8
        t1 = 0.0_R8
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            t0dd(nd0, nd) = 0.D0
          END DO
          t0d(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          DO nd0=1,nbdirs0
            t1dd(nd0, nd) = 0.D0
          END DO
          t1d(nd) = 0.d0
        END DO
        t0d0 = 0.D0
        t1d0 = 0.D0
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t0dd(nd0, nd) = t0dd(nd0, nd) + mompard(nd, is, ib, 1)*&
&                 pld0%na(nd0, icv1, is) + pld%na(nd, icv1, is)*mompard0&
&                 (nd0, is, ib, 1) + mompar(is, ib, 1)*pldd%na(nd0, nd, &
&                 icv1, is)
              END DO
              t0d(nd) = t0d(nd) + pl%na(icv1, is)*mompard(nd, is, ib, 1)&
&               + mompar(is, ib, 1)*pld%na(nd, icv1, is)
            END DO
            DO nd0=1,nbdirs0
              t0d0(nd0) = t0d0(nd0) + pl%na(icv1, is)*mompard0(nd0, is, &
&               ib, 1) + mompar(is, ib, 1)*pld0%na(nd0, icv1, is)
            END DO
            t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              temp4 = co%dna0(icv1, is)*pl%na(icv1, is)/conpar(is, ib, 2&
&               )
              DO nd0=1,nbdirs0
                temp2d(nd0) = (pl%na(icv1, is)*cod0%dna0(nd0, icv1, is)+&
&                 co%dna0(icv1, is)*pld0%na(nd0, icv1, is)-temp4*&
&                 conpard0(nd0, is, ib, 2))/conpar(is, ib, 2)
              END DO
              temp2 = temp4
              DO nd=1,nbdirs
                temp4 = (pl%na(icv1, is)*cod%dna0(nd, icv1, is)+co%dna0(&
&                 icv1, is)*pld%na(nd, icv1, is)-temp2*conpard(nd, is, &
&                 ib, 2))/conpar(is, ib, 2)
                DO nd0=1,nbdirs0
                  t1dd(nd0, nd) = t1dd(nd0, nd) + (cod%dna0(nd, icv1, is&
&                   )*pld0%na(nd0, icv1, is)+pl%na(icv1, is)*codd%dna0(&
&                   nd0, nd, icv1, is)+pld%na(nd, icv1, is)*cod0%dna0(&
&                   nd0, icv1, is)+co%dna0(icv1, is)*pldd%na(nd0, nd, &
&                   icv1, is)-conpard(nd, is, ib, 2)*temp2d(nd0)-temp2*&
&                   conpardd(nd0, nd, is, ib, 2)-temp4*conpard0(nd0, is&
&                   , ib, 2))/conpar(is, ib, 2)
                END DO
                t1d(nd) = t1d(nd) + temp4
              END DO
              DO nd0=1,nbdirs0
                t1d0(nd0) = t1d0(nd0) + temp2d(nd0)
              END DO
              t1 = t1 + temp2
            END IF
          END IF
        END DO
        IF (geo%fcpbs(ifc) .GE. 0.) THEN
          abs0 = geo%fcpbs(ifc)
        ELSE
          abs0 = -geo%fcpbs(ifc)
        END IF
        temp1 = enzpar(ib, 1)*abs0
        DO nd=1,nbdirs
          temp3 = cs*t0d(nd) + t0*csd(nd)
          DO nd0=1,nbdirs0
            srwdd%szt0(nd0, nd, icv1, 1) = srwdd%szt0(nd0, nd, icv1, 1) &
&             - temp1*(temp3*switchd0%b2tfhi_fflozt(nd0)+(switch%&
&             b2tfhi_fflozt+1.0_R8)*(t0d(nd)*csd0(nd0)+cs*t0dd(nd0, nd)+&
&             csd(nd)*t0d0(nd0)+t0*csdd(nd0, nd))+switchd%b2tfhi_fflozt(&
&             nd)*(cs*t0d0(nd0)+t0*csd0(nd0))) - enzpar(ib, 2)*geo%fcs(&
&             ifc)*t1dd(nd0, nd)
          END DO
          srwd%szt0(nd, icv1, 1) = srwd%szt0(nd, icv1, 1) - temp1*((&
&           switch%b2tfhi_fflozt+1.0_R8)*temp3+switchd%b2tfhi_fflozt(nd)&
&           *(t0*cs)) - geo%fcs(ifc)*t1d(nd)*enzpar(ib, 2)
        END DO
        DO nd0=1,nbdirs0
          srwd0%szt0(nd0, icv1, 1) = srwd0%szt0(nd0, icv1, 1) - temp1*((&
&           switch%b2tfhi_fflozt+1.0_R8)*(cs*t0d0(nd0)+t0*csd0(nd0))+t0*&
&           cs*switchd0%b2tfhi_fflozt(nd0)) - geo%fcs(ifc)*enzpar(ib, 2)&
&           *t1d0(nd0)
        END DO
        srw%szt0(icv1, 1) = srw%szt0(icv1, 1) - temp1*(t0*cs*(switch%&
&         b2tfhi_fflozt+1.0_R8)) - enzpar(ib, 2)*t1*geo%fcs(ifc)
!wdk    Todo: corrections for BCCON.ne.14
      END DO
    CASE (16) 
!
! -- BCENZ=16 -- Prescribe the value of the turb. enstropy, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENZ=16 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. enstrophy + perturbation', enzpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enzpar(ib, 1) .GT. 0.0_R8, &
&             'BCENZ = 16, ENZPAR(,1) !> 0')
      END IF
!     ..compute average zt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
      t1d0 = 0.D0
      t1dd = 0.D0
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            DO nd=1,nbdirs
              DO nd0=nd,nbdirs0
                t1dd(nd0, nd) = t1dd(nd0, nd) + geo%cvvol(icv2)*pldd%zt(&
&                 nd0, nd, icv2)
              END DO
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%zt(nd, icv2)
            END DO
            DO nd0=1,nbdirs0
              t1d0(nd0) = t1d0(nd0) + geo%cvvol(icv2)*pld0%zt(nd0, icv2)
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%zt(icv2)
          END DO
        END IF
      END DO
      DO nd=1,nbdirs
        DO nd0=nd,nbdirs0
          t1dd(nd0, nd) = t1dd(nd0, nd)/t0
        END DO
        t1d(nd) = t1d(nd)/t0
      END DO
      DO nd0=1,nbdirs0
        t1d0(nd0) = t1d0(nd0)/t0
      END DO
      t1 = t1/t0
!     ..impose zt with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp1 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          DO nd0=nd,nbdirs0
            srwdd%szt0(nd0, nd, icv1, 0) = temp1*(pldd%zt(nd0, nd, icv2)&
&             -t1dd(nd0, nd))
            srwdd%szt0(nd0, nd, icv1, 1) = 0.D0
          END DO
          srwd%szt0(nd, icv1, 0) = temp1*(pld%zt(nd, icv2)-t1d(nd))
          srwd%szt0(nd, icv1, 1) = 0.d0
        END DO
        DO nd0=1,nbdirs0
          srwd0%szt0(nd0, icv1, 0) = temp1*(pld0%zt(nd0, icv2)-t1d0(nd0)&
&           )
          srwd0%szt0(nd0, icv1, 1) = 0.D0
        END DO
        srw%szt0(icv1, 0) = temp1*(enzpar(ib, 1)*ev+pl%zt(icv2)-t1)
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcenz(ib)
      CALL XERRAB('BCENZ out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENZ_DV_DV

!  Differentiation of b2stbc_phys_enz in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: *(srw.szt0)
!   with respect to varying inputs: conpar mompar *(srw.szt0) switch.b2tfhi_fflozt
!                *(co.dna0) *(pl.na) *(pl.zt) rz pz
!   Plus diff mem management of: mpg.bcfcor:in geo.vxvol:in srw.szt0:in
!                co.dna0:in pl.na:in pl.zt:in
!
  SUBROUTINE B2STBC_PHYS_ENZ_DV(ib, nbdirs)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    INTEGER :: ib, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, t0, t1, t2
    REAL(kind=r8), DIMENSION(nbdirsmax) :: csd, t0d, t1d, t2d
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(r8) :: temp2
    INTEGER :: nbdirs
!
! -- BOUNDARY CONDITIONS FOR TURBULENT ENSTROPHY EQUATION --
!
    SELECT CASE  (bcenz(ib)) 
    CASE (0) 
!
!
! -- BCENZ=1 -- PRESCRIBE THE VALUE OF ZT
!

    CASE (1) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified zt ', enzpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enzpar(ib, 1) .GE. 0.0_R8, &
&             'BCENZ = 1, ENZPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        DO nd=1,nbdirs
          srwd%szt0(nd, icv1, 0) = 0.d0
          srwd%szt0(nd, icv1, 1) = 0.d0
        END DO
        srw%szt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*enzpar(ib, 1)*ev
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENZ=2 -- PRESCRIBE THE GRADIENT OF THE TURB. ENSTROPHY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. enstr. gradient ', enzpar(ib&
&                                   , 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        CALL INTVERTEX_S_DV_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%zt&
&                            , pld%zt, t1, t1d, nbdirs)
        CALL INTVERTEX_S_DV_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%zt&
&                            , pld%zt, t2, t2d, nbdirs)
        temp = vbig*ne00*geo%fcs(ifc)
        temp0 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, &
&         2))
        temp1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
        DO nd=1,nbdirs
          srwd%szt0(nd, icv1, 0) = temp*(pld%zt(nd, icv2)-temp0*temp1*(&
&           t2d(nd)-t1d(nd))/geo%fcht(ifc))
          srwd%szt0(nd, icv1, 1) = 0.d0
        END DO
        srw%szt0(icv1, 0) = temp*(ev*enzpar(ib, 1)*geo%fcqgam(ifc, 0)*(&
&         geo%fchc(ifc, 1)+geo%fchc(ifc, 2))+pl%zt(icv2)-temp0*(temp1*((&
&         t2-t1)/geo%fcht(ifc))))
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENZ=3 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENZ=3, NOT AVAILABLE')
!
! -- BCENZ=4 -- not implemented
!
    CASE (4) 
      CALL XERRAB('B2STBC -- BCENZ=4, NOT AVAILABLE')
!
! -- BCENZ=5 -- not implemented
!
    CASE (5) 
      CALL XERRAB('B2STBC -- BCENZ=5, NOT AVAILABLE')
!
! -- BCENZ=6 -- Prescribe the total flux of kt, following the
!               profile of fhi + fhe
!
    CASE (6) 
      CALL XERRAB('B2STBC -- BCENZ=6, NOT AVAILABLE')
!
! -- BCENZ=7 -- Prescribe the total flux of kt, following the
!               profile of fna
!
    CASE (7) 
      CALL XERRAB('B2STBC -- BCENZ=7, NOT AVAILABLE')
!
! -- BCENZ=8 -- PRESCRIBE THE TOTAL FLUX OF KT WITH CONSTANT
!               FLUX DENSITY
!
    CASE (8) 
      CALL XERRAB('B2STBC -- BCENZ=8, NOT AVAILABLE')
!
! -- BCENZ=9 -- not implemented
!
    CASE (9) 
      CALL XERRAB('B2STBC -- BCENZ=9, NOT AVAILABLE')
!
! -- BCENZ=10 -- not implemented
!
    CASE (10) 
      CALL XERRAB('B2STBC -- BCENZ=10, NOT AVAILABLE')
!
! -- BCENZ=11 -- not implemented
!
    CASE (11) 
      CALL XERRAB('B2STBC -- BCENZ=11, NOT AVAILABLE')
!
! -- BCENZ=12 -- not implemented
!
    CASE (12) 
      CALL XERRAB('B2STBC -- BCENZ=12, NOT AVAILABLE')
!
! -- BCENZ=13 -- not implemented
!
    CASE (13) 
      CALL XERRAB('B2STBC -- BCENZ=13, NOT AVAILABLE')
!
! -- BCENZ=14 -- Leakage option for turbulent enstrophy
!
    CASE (14) 
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. enstrophy leakage ', enzpar(&
&                                   ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp1 = pz(icv1)/rz(icv1)
        DO nd=1,nbdirs
          arg12d(nd) = (pzd(nd, icv1)-temp1*rzd(nd, icv1))/rz(icv1)
          srwd%szt0(nd, icv1, 0) = 0.d0
        END DO
        arg12 = temp1
        temp1 = SQRT(arg12)
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            csd(nd) = 0.d0
          ELSE
            csd(nd) = arg12d(nd)/(2.0*temp1)
          END IF
          srwd%szt0(nd, icv1, 3) = enzpar(ib, 1)*geo%fcs(ifc)*csd(nd)
        END DO
        cs = temp1
        srw%szt0(icv1, 0) = 0.0_R8
        srw%szt0(icv1, 3) = geo%fcs(ifc)*cs*enzpar(ib, 1)
      END DO
    CASE (15) 
!
! -- BCENZ=15 -- Sheath transmission factor
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENZ=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY', ib&
&                                , ' FOR ALL IONS'
!srv 20.09.17
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENZ = 15, ENZPAR(I,,1) <= 0 not allowed!')
!srv 20.09.17
        WRITE(*, '(a,a,1p,g14.7,a,a,a)') &
&       'BCENZ=15: sheath transmission factor BC for ', &
&       'turb. enstrophy with ENZPAR(IB,1) =', enzpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp1 = pz(icv1)/rz(icv1)
        DO nd=1,nbdirs
          arg12d(nd) = (pzd(nd, icv1)-temp1*rzd(nd, icv1))/rz(icv1)
        END DO
        arg12 = temp1
        temp1 = SQRT(arg12)
        DO nd=1,nbdirs
          IF (arg12 .EQ. 0.d0) THEN
            csd(nd) = 0.d0
          ELSE
            csd(nd) = arg12d(nd)/(2.0*temp1)
          END IF
        END DO
        cs = temp1
        t0 = 0.0_R8
        t1 = 0.0_R8
        DO nd=1,nbdirsmax
          t0d(nd) = 0.d0
        END DO
        DO nd=1,nbdirsmax
          t1d(nd) = 0.d0
        END DO
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            DO nd=1,nbdirs
              t0d(nd) = t0d(nd) + pl%na(icv1, is)*mompard(nd, is, ib, 1)&
&               + mompar(is, ib, 1)*pld%na(nd, icv1, is)
            END DO
            t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              temp2 = co%dna0(icv1, is)*pl%na(icv1, is)/conpar(is, ib, 2&
&               )
              DO nd=1,nbdirs
                t1d(nd) = t1d(nd) + (pl%na(icv1, is)*cod%dna0(nd, icv1, &
&                 is)+co%dna0(icv1, is)*pld%na(nd, icv1, is)-temp2*&
&                 conpard(nd, is, ib, 2))/conpar(is, ib, 2)
              END DO
              t1 = t1 + temp2
            END IF
          END IF
        END DO
        IF (geo%fcpbs(ifc) .GE. 0.) THEN
          abs0 = geo%fcpbs(ifc)
        ELSE
          abs0 = -geo%fcpbs(ifc)
        END IF
        temp1 = enzpar(ib, 1)*abs0
        DO nd=1,nbdirs
          srwd%szt0(nd, icv1, 1) = srwd%szt0(nd, icv1, 1) - temp1*((&
&           switch%b2tfhi_fflozt+1.0_R8)*(cs*t0d(nd)+t0*csd(nd))+t0*cs*&
&           switchd%b2tfhi_fflozt(nd)) - geo%fcs(ifc)*enzpar(ib, 2)*t1d(&
&           nd)
        END DO
        srw%szt0(icv1, 1) = srw%szt0(icv1, 1) - temp1*(t0*cs*(switch%&
&         b2tfhi_fflozt+1.0_R8)) - enzpar(ib, 2)*t1*geo%fcs(ifc)
!wdk    Todo: corrections for BCCON.ne.14
      END DO
    CASE (16) 
!
! -- BCENZ=16 -- Prescribe the value of the turb. enstropy, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENZ=16 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. enstrophy + perturbation', enzpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enzpar(ib, 1) .GT. 0.0_R8, &
&             'BCENZ = 16, ENZPAR(,1) !> 0')
      END IF
!     ..compute average zt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      DO nd=1,nbdirsmax
        t1d(nd) = 0.d0
      END DO
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            DO nd=1,nbdirs
              t1d(nd) = t1d(nd) + geo%cvvol(icv2)*pld%zt(nd, icv2)
            END DO
            t1 = t1 + geo%cvvol(icv2)*pl%zt(icv2)
          END DO
        END IF
      END DO
      DO nd=1,nbdirs
        t1d(nd) = t1d(nd)/t0
      END DO
      t1 = t1/t0
!     ..impose zt with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp1 = vbig*ne00*geo%fcs(ifc)
        DO nd=1,nbdirs
          srwd%szt0(nd, icv1, 0) = temp1*(pld%zt(nd, icv2)-t1d(nd))
          srwd%szt0(nd, icv1, 1) = 0.d0
        END DO
        srw%szt0(icv1, 0) = temp1*(enzpar(ib, 1)*ev+pl%zt(icv2)-t1)
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcenz(ib)
      CALL XERRAB('BCENZ out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENZ_DV

!
  SUBROUTINE B2STBC_PHYS_ENZ(ib)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER :: ib, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, t0, t1, t2
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: arg12
!
! -- BOUNDARY CONDITIONS FOR TURBULENT ENSTROPHY EQUATION --
!
    SELECT CASE  (bcenz(ib)) 
    CASE (0) 
!
!
! -- BCENZ=1 -- PRESCRIBE THE VALUE OF ZT
!

    CASE (1) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified zt ', enzpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enzpar(ib, 1) .GE. 0.0_R8, &
&             'BCENZ = 1, ENZPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%szt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*enzpar(ib, 1)*ev
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENZ=2 -- PRESCRIBE THE GRADIENT OF THE TURB. ENSTROPHY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. enstr. gradient ', enzpar(ib&
&                                   , 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1 = INTVERTEX_S_NODIFF_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, &
&         pl%zt)
        t2 = INTVERTEX_S_NODIFF_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, &
&         pl%zt)
        srw%szt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(ev*enzpar(ib, 1)*(&
&         geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2&
&         -t1)*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/&
&         geo%fcht(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%zt(icv2))
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENZ=3 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENZ=3, NOT AVAILABLE')
!
! -- BCENZ=4 -- not implemented
!
    CASE (4) 
      CALL XERRAB('B2STBC -- BCENZ=4, NOT AVAILABLE')
!
! -- BCENZ=5 -- not implemented
!
    CASE (5) 
      CALL XERRAB('B2STBC -- BCENZ=5, NOT AVAILABLE')
!
! -- BCENZ=6 -- Prescribe the total flux of kt, following the
!               profile of fhi + fhe
!
    CASE (6) 
      CALL XERRAB('B2STBC -- BCENZ=6, NOT AVAILABLE')
!
! -- BCENZ=7 -- Prescribe the total flux of kt, following the
!               profile of fna
!
    CASE (7) 
      CALL XERRAB('B2STBC -- BCENZ=7, NOT AVAILABLE')
!
! -- BCENZ=8 -- PRESCRIBE THE TOTAL FLUX OF KT WITH CONSTANT
!               FLUX DENSITY
!
    CASE (8) 
      CALL XERRAB('B2STBC -- BCENZ=8, NOT AVAILABLE')
!
! -- BCENZ=9 -- not implemented
!
    CASE (9) 
      CALL XERRAB('B2STBC -- BCENZ=9, NOT AVAILABLE')
!
! -- BCENZ=10 -- not implemented
!
    CASE (10) 
      CALL XERRAB('B2STBC -- BCENZ=10, NOT AVAILABLE')
!
! -- BCENZ=11 -- not implemented
!
    CASE (11) 
      CALL XERRAB('B2STBC -- BCENZ=11, NOT AVAILABLE')
!
! -- BCENZ=12 -- not implemented
!
    CASE (12) 
      CALL XERRAB('B2STBC -- BCENZ=12, NOT AVAILABLE')
!
! -- BCENZ=13 -- not implemented
!
    CASE (13) 
      CALL XERRAB('B2STBC -- BCENZ=13, NOT AVAILABLE')
!
! -- BCENZ=14 -- Leakage option for turbulent enstrophy
!
    CASE (14) 
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. enstrophy leakage ', enzpar(&
&                                   ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        srw%szt0(icv1, 0) = 0.0_R8
        srw%szt0(icv1, 3) = geo%fcs(ifc)*cs*enzpar(ib, 1)
      END DO
    CASE (15) 
!
! -- BCENZ=15 -- Sheath transmission factor
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENZ=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY', ib&
&                                , ' FOR ALL IONS'
!srv 20.09.17
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENZ = 15, ENZPAR(I,,1) <= 0 not allowed!')
!srv 20.09.17
        WRITE(*, '(a,a,1p,g14.7,a,a,a)') &
&       'BCENZ=15: sheath transmission factor BC for ', &
&       'turb. enstrophy with ENZPAR(IB,1) =', enzpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        arg12 = pz(icv1)/rz(icv1)
        cs = SQRT(arg12)
        t0 = 0.0_R8
        t1 = 0.0_R8
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t1 = t1 + co%dna0(icv1, &
&               is)/conpar(is, ib, 2)*pl%na(icv1, is)
          END IF
        END DO
        IF (geo%fcpbs(ifc) .GE. 0.) THEN
          abs0 = geo%fcpbs(ifc)
        ELSE
          abs0 = -geo%fcpbs(ifc)
        END IF
        srw%szt0(icv1, 1) = srw%szt0(icv1, 1) - enzpar(ib, 1)*t0*cs*abs0&
&         *(1.0_R8+switch%b2tfhi_fflozt) - enzpar(ib, 2)*t1*geo%fcs(ifc)
!wdk    Todo: corrections for BCCON.ne.14
      END DO
    CASE (16) 
!
! -- BCENZ=16 -- Prescribe the value of the turb. enstropy, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENZ=16 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. enstrophy + perturbation', enzpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enzpar(ib, 1) .GT. 0.0_R8, &
&             'BCENZ = 16, ENZPAR(,1) !> 0')
      END IF
!     ..compute average zt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%zt(icv2)
          END DO
        END IF
      END DO
      t1 = t1/t0
!     ..impose zt with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%szt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%zt(icv2)+enzpar(&
&         ib, 1)*ev-t1)
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcenz(ib)
      CALL XERRAB('BCENZ out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENZ

!  Differentiation of sheath_g_dv in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: sheath_g sheath_gd
!   with respect to varying inputs: t0 t0d sheath_gd
!  Differentiation of sheath_g in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: sheath_g
!   with respect to varying inputs: t0
!
  SUBROUTINE SHEATH_G_DV_DV(t0, t0d0, t0d, t0dd, sheath_g, sheath_gd0, &
&   sheath_gd, sheath_gdd, nbdirs, nbdirs0)
    USE B2MOD_TYPES
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    USE B2MOD_DIFFSIZES
!  Hint: nbdirsmax0 should be the maximum number of differentiation directions
    IMPLICIT NONE
    REAL(kind=r8) :: sheath_g, t0
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: sheath_gd0, t0d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: sheath_gd, t0d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: sheath_gdd, t0dd
    INTRINSIC SQRT, ERF, EXP
    EXTERNAL ERF_DV
    EXTERNAL ERF_DV_DV
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: result20d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result20d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: result20dd
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: arg12d0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    REAL(kind=r8), DIMENSION(nbdirsmax0, nbdirsmax) :: arg12dd
    INTEGER :: nd
    REAL(kind=r8) :: temp
    REAL(kind=r8), DIMENSION(nbdirsmax0) :: tempd
    INTEGER :: nbdirs
    INTEGER :: nd0
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: temp1
    REAL(kind=r8) :: temp2
    INTEGER :: nbdirs0
!
    result10 = SQRT(pi)
    result20dd = 0.D0
    CALL ERF_DV_DV(t0, t0d0, t0d, t0dd, result20, result20d0, result20d&
&            , result20dd, nbdirs, nbdirs0)
    arg12 = t0**2
    DO nd0=1,nbdirs0
      arg12d0(nd0) = 2*t0*t0d0(nd0)
      tempd(nd0) = EXP(arg12)*arg12d0(nd0)
    END DO
    temp = EXP(arg12)
    arg12dd = 0.D0
    DO nd=1,nbdirs
      arg12d(nd) = 2*t0*t0d(nd)
      temp0 = (result20+1)*t0d(nd) + t0*result20d(nd)
      temp1 = EXP(arg12)
      temp2 = t0*(result20+1)*arg12d(nd)
      DO nd0=1,nbdirs0
        arg12dd(nd0, nd) = 2*(t0d(nd)*t0d0(nd0)+t0*t0dd(nd0, nd))
        sheath_gdd(nd0, nd) = result10*(temp0*tempd(nd0)+temp*(t0d(nd)*&
&         result20d0(nd0)+(result20+1)*t0dd(nd0, nd)+result20d(nd)*t0d0(&
&         nd0)+t0*result20dd(nd0, nd))+temp1*(arg12d(nd)*((result20+1)*&
&         t0d0(nd0)+t0*result20d0(nd0))+t0*(result20+1)*arg12dd(nd0, nd)&
&         )+temp2*EXP(arg12)*arg12d0(nd0))
      END DO
      sheath_gd(nd) = result10*(temp*temp0+temp2*temp1)
    END DO
    DO nd0=1,nbdirs0
      sheath_gd0(nd0) = result10*(t0*temp*result20d0(nd0)+(result20+1)*(&
&       temp*t0d0(nd0)+t0*tempd(nd0)))
    END DO
    sheath_g = result10*(t0*(result20+1)*temp) + 1.0_R8
!
    RETURN
  END SUBROUTINE SHEATH_G_DV_DV

!  Differentiation of sheath_g in forward (tangent) mode (with options multiDirectional context noISIZE r8):
!   variations   of useful results: sheath_g
!   with respect to varying inputs: t0
!
  SUBROUTINE SHEATH_G_DV(t0, t0d, sheath_g, sheath_gd, nbdirs)
    USE B2MOD_TYPES
!  Hint: nbdirsmax should be the maximum number of differentiation directions
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    REAL(kind=r8) :: sheath_g, t0
    REAL(kind=r8), DIMENSION(nbdirsmax) :: sheath_gd, t0d
    INTRINSIC SQRT, ERF, EXP
    EXTERNAL ERF_DV
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8), DIMENSION(nbdirsmax) :: result20d
    REAL(kind=r8) :: arg12
    REAL(kind=r8), DIMENSION(nbdirsmax) :: arg12d
    INTEGER :: nd
    REAL(kind=r8) :: temp
    INTEGER :: nbdirs
!
    result10 = SQRT(pi)
    CALL ERF_DV(t0, t0d, result20, result20d, nbdirs)
    arg12 = t0**2
    temp = EXP(arg12)
    DO nd=1,nbdirs
      arg12d(nd) = 2*t0*t0d(nd)
      sheath_gd(nd) = result10*(temp*((result20+1)*t0d(nd)+t0*result20d(&
&       nd))+t0*(result20+1)*EXP(arg12)*arg12d(nd))
    END DO
    sheath_g = result10*(t0*(result20+1)*temp) + 1.0_R8
!
    RETURN
  END SUBROUTINE SHEATH_G_DV

!
  FUNCTION SHEATH_G(t0)
    USE B2MOD_TYPES
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    REAL(kind=r8) :: sheath_g, t0
    INTRINSIC SQRT, ERF, EXP
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8) :: arg12
!
    result10 = SQRT(pi)
    result20 = ERF(t0)
    arg12 = t0**2
    sheath_g = 1.0_R8 + result10*t0*(1+result20)*EXP(arg12)
!
    RETURN
  END FUNCTION SHEATH_G

!
  FUNCTION PIT(icv)
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
    INTEGER, INTENT(IN) :: icv
    REAL(kind=r8) :: pit
    INTRINSIC ABS
    REAL(kind=r8) :: abs0
    IF (geo%cvbb(icv, 0) .GE. 0.) THEN
      abs0 = geo%cvbb(icv, 0)
    ELSE
      abs0 = -geo%cvbb(icv, 0)
    END IF
!
    pit = abs0/geo%cvbb(icv, 3)
!
    RETURN
  END FUNCTION PIT

!
!-----------------------------------------------------------------------
!.specification
  FUNCTION BCINT(fun, nx, ny, il, ib)
    USE B2MOD_TYPES
    USE B2MOD_GEO_DIFFV_DIFFV
    USE B2MOD_INDIRECT_DIFFV_DIFFV
    USE B2MOD_BOUNDARY_NAMELIST_DIFFV_DIFFV
    USE B2MOD_DIFFSIZES
    IMPLICIT NONE
!   ..output result (undefined upon entry)
    REAL(kind=r8) :: bcint
!   ..input arguments (unchanged on exit)
    INTEGER :: nx, ny, il, ib
    REAL(kind=r8) :: fun(-1:nx, -1:ny)
!
!-----------------------------------------------------------------------
!.documentation
!
!  1. purpose
!
!     BCINT provides interpolated face-centred values for cell-centred
!     quantities (array fun), for use in boundary conditions.
!     The interpolation is done according to distance away from the
!     cell face. The boundary index is ib, and the cell index along
!     the boundary is il.
!
!
!-----------------------------------------------------------------------
!.declarations
!
!   ..procedures
    EXTERNAL XERTST, XERRAB
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8) :: result3
    REAL(kind=r8) :: result4
!
!-----------------------------------------------------------------------
!.computation
!
! ..preliminaries
!  ..test input parameters
    CALL XERTST(0 .LE. nx .AND. 0 .LE. ny, 'faulty parameter nx, ny')
    CALL XERTST(0 .LT. ib .AND. nbc .GE. ib, 'faulty parameter ib')
    CALL XERTST(1 .LE. il .AND. bc_list_size(ib) .GE. il, &
&         'faulty parameter il')
!
! ..main computation
    IF (bcchar(ib) .EQ. 'S') THEN
      result10 = HY1(topix(bc_list_x(il, ib), bc_list_y(il, ib)), topiy(&
&       bc_list_x(il, ib), bc_list_y(il, ib)))
      result20 = HY1(bc_list_x(il, ib), bc_list_y(il, ib))
      result3 = HY1(bc_list_x(il, ib), bc_list_y(il, ib))
      result4 = HY1(topix(bc_list_x(il, ib), bc_list_y(il, ib)), topiy(&
&       bc_list_x(il, ib), bc_list_y(il, ib)))
      bcint = (fun(bc_list_x(il, ib), bc_list_y(il, ib))*result10+fun(&
&       topix(bc_list_x(il, ib), bc_list_y(il, ib)), topiy(bc_list_x(il&
&       , ib), bc_list_y(il, ib)))*result20)/(result3+result4)
    ELSE IF (bcchar(ib) .EQ. 'N') THEN
      result10 = HY1(bottomix(bc_list_x(il, ib), bc_list_y(il, ib)), &
&       bottomiy(bc_list_x(il, ib), bc_list_y(il, ib)))
      result20 = HY1(bc_list_x(il, ib), bc_list_y(il, ib))
      result3 = HY1(bc_list_x(il, ib), bc_list_y(il, ib))
      result4 = HY1(bottomix(bc_list_x(il, ib), bc_list_y(il, ib)), &
&       bottomiy(bc_list_x(il, ib), bc_list_y(il, ib)))
      bcint = (fun(bc_list_x(il, ib), bc_list_y(il, ib))*result10+fun(&
&       bottomix(bc_list_x(il, ib), bc_list_y(il, ib)), bottomiy(&
&       bc_list_x(il, ib), bc_list_y(il, ib)))*result20)/(result3+&
&       result4)
    ELSE IF (bcchar(ib) .EQ. 'E') THEN
      bcint = (fun(bc_list_x(il, ib), bc_list_y(il, ib))*hx(leftix(&
&       bc_list_x(il, ib), bc_list_y(il, ib)), leftiy(bc_list_x(il, ib)&
&       , bc_list_y(il, ib)))+fun(leftix(bc_list_x(il, ib), bc_list_y(il&
&       , ib)), leftiy(bc_list_x(il, ib), bc_list_y(il, ib)))*hx(&
&       bc_list_x(il, ib), bc_list_y(il, ib)))/(hx(bc_list_x(il, ib), &
&       bc_list_y(il, ib))+hx(leftix(bc_list_x(il, ib), bc_list_y(il, ib&
&       )), leftiy(bc_list_x(il, ib), bc_list_y(il, ib))))
    ELSE IF (bcchar(ib) .EQ. 'W') THEN
      bcint = (fun(bc_list_x(il, ib), bc_list_y(il, ib))*hx(rightix(&
&       bc_list_x(il, ib), bc_list_y(il, ib)), rightiy(bc_list_x(il, ib)&
&       , bc_list_y(il, ib)))+fun(rightix(bc_list_x(il, ib), bc_list_y(&
&       il, ib)), rightiy(bc_list_x(il, ib), bc_list_y(il, ib)))*hx(&
&       bc_list_x(il, ib), bc_list_y(il, ib)))/(hx(bc_list_x(il, ib), &
&       bc_list_y(il, ib))+hx(rightix(bc_list_x(il, ib), bc_list_y(il, &
&       ib)), rightiy(bc_list_x(il, ib), bc_list_y(il, ib))))
    ELSE
      CALL XERRAB('bcint : Unknown orientation!')
    END IF
!
! ..return
    RETURN
!
!-----------------------------------------------------------------------
!.end bcint
!
  END FUNCTION BCINT

END SUBROUTINE B2STBC_PHYS_DV_DV

